        public static void playerRiding(TickEvent.PlayerTickEvent event)
        {
            if (event.phase == TickEvent.Phase.START && !event.player.level().isClientSide() && event.player.tickCount % 5 == 0)
            {
                Player player = event.player;
                if (player.getVehicle() != null)
                {
                    Entity mount = player.getVehicle();
                    // If insulated minecart
                    if (mount instanceof Minecart minecart && minecart.getDisplayBlockState().getBlock() == ModBlocks.MINECART_INSULATION)
                    {   Temperature.replaceOrAddModifier(player, new MountTempModifier(1, 1).tickRate(5).expires(5), Trait.RATE, Matcher.SAME_CLASS);
                    }
                    // If insulated entity (defined in config)
                    else
                    {
                        MountData entityInsul = ConfigSettings.INSULATED_MOUNTS.get().get(mount.getType())
                                                      .stream().filter(mnt -> mnt.test(mount)).findFirst().orElse(null);
                        if (entityInsul != null)
                        {
                            double coldInsulation = entityInsul.coldInsulation(mount, player);
                            double heatInsulation = entityInsul.heatInsulation(mount, player);
                            Temperature.replaceOrAddModifier(player, new MountTempModifier(coldInsulation, heatInsulation).tickRate(5).expires(5), Trait.RATE, Matcher.SAME_CLASS);
                        }
                    }
                }
            }
        }

@SubscribeEvent
	public void tick(TickEvent.WorldTickEvent event) {
		newEntries.forEach(e -> entityToEntry.put(e.getTarget(), e));
		newEntries.clear();

		entityToEntry.keySet().removeIf(entity -> {
			TrackingEntry entry = entityToEntry.get(entity);
			Entity caster = entry.getCaster();
			int ticks = entry.getTicks();
			double potency = entry.getPotency();
			double duration = entry.getDuration();

			if (ticks > 0) {
				entry.setTicks(ticks - 1);
				return false;
			}

			entity.setFire((int) duration);

			int invTime = entity.hurtResistantTime;
			entity.hurtResistantTime = 0;
			if (caster instanceof EntityPlayer)
				entity.attackEntityFrom(new EntityDamageSource("lightningbolt", caster), (float) potency);
			else entity.attackEntityFrom(DamageSource.LIGHTNING_BOLT, (float) potency);
			entity.hurtResistantTime = invTime;
			return true;
		});
	}

@SubscribeEvent
    public static void onServerTick(TickEvent.LevelTickEvent tick) {
        if (!tick.level.isClientSide && tick.level instanceof ServerLevel serverWorld) {
            BEACHED_CACHALOT_WHALE_SPAWNER_MAP.computeIfAbsent(serverWorld,
                k -> new BeachedCachalotWhaleSpawner(serverWorld));
            BeachedCachalotWhaleSpawner spawner = BEACHED_CACHALOT_WHALE_SPAWNER_MAP.get(serverWorld);
            spawner.tick();

            if (!teleportPlayers.isEmpty()) {
                for (final var triple : teleportPlayers) {
                    ServerPlayer player = triple.a;
                    ServerLevel endpointWorld = triple.b;
                    BlockPos endpoint = triple.c;
                    final int heightFromMap = endpointWorld.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, endpoint.getX(), endpoint.getZ());
                    endpoint = new BlockPos(endpoint.getX(), Math.max(heightFromMap, endpoint.getY()), endpoint.getZ());
                    player.teleportTo(endpointWorld, endpoint.getX() + 0.5D, endpoint.getY() + 0.5D, endpoint.getZ() + 0.5D, player.getYRot(), player.getXRot());
                    ChunkPos chunkpos = new ChunkPos(endpoint);
                    endpointWorld.getChunkSource().addRegionTicket(TicketType.POST_TELEPORT, chunkpos, 1, player.getId());
                    player.connection.send(new ClientboundSetExperiencePacket(player.experienceProgress, player.totalExperience, player.experienceLevel));

                }
                teleportPlayers.clear();
            }
        }
        AMWorldData data = AMWorldData.get(tick.level);
        if (data != null) {
            data.tickPupfish();
        }
    }

