                                wight.lookTime = 0;
                                ModNetwork.INSTANCE.send(PacketDistributor.SERVER.noArg(), new CTargetPlayerPacket(wight));
                            }
                        }
                    } else {
                        if (wight.lookTime > 0){
                            wight.lookTime -= 1;
                        }
