@SubscribeEvent
            public void onTick(TickEvent.LevelTickEvent event)
            {
                if (event.level.isClientSide == level.isClientSide && event.phase == TickEvent.Phase.START)
                {
                    // Temperature of waterskin weakens over time
                    double waterTemp = CSMath.blend(itemTemp, itemTemp / 5, tick, 20, 100);
                    double effectAmount = waterTemp * (ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() / 50d);
                    double wetnessTemp = 0.05 * CSMath.sign(waterTemp+0.01);

                    // Move the box down at the speed of gravity
                    aabb = aabb.move(0, -acceleration, 0);

                    // If there's ground, stop
                    BlockPos pos = BlockPos.containing(aabb.minX, aabb.minY, aabb.minZ);
                    if (WorldHelper.isSpreadBlocked(level, chunk.getBlockState(pos), pos, Direction.DOWN, Direction.DOWN))
                    {   MinecraftForge.EVENT_BUS.unregister(this);
                        return;
                    }

                    // Apply the waterskin modifier to all entities in the box
                    WorldHelper.getEntitiesOfClass(Player.class, level, aabb, e -> true).forEach(player ->
                    {
                        if (!affectedPlayers.contains(player))
                        {   // Apply the effect and store the player
                            Temperature.addModifier(player, new WaterskinTempModifier(effectAmount).expires(0), Temperature.Trait.CORE, Placement.LAST);
                            Temperature.replaceOrAddModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                            affectedPlayers.add(player);
                        }
                    });

                    // Increase the speed of the box
                    acceleration += 0.0052;
                    tick++;

                    // Expire after 5 seconds
                    if (tick > 100)
                    {   MinecraftForge.EVENT_BUS.unregister(this);
                    }
                }
            }

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void tick(TickEvent.ClientTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		World world = Minecraft.getMinecraft().world;
		if (world == null) return;

		List<EntityUnicorn> unicorns = world.getEntities(EntityUnicorn.class, input -> true);

		for (EntityUnicorn unicorn : unicorns) {
			if (unicorn == null) continue;
			if (unicorn.isDead) {
				positions.remove(unicorn);
				break;
			}

			positions.putIfAbsent(unicorn, new ArrayList<>());

			List<Point> poses = positions.get(unicorn);

			if ((poses.size() >= 1000 || world.getTotalWorldTime() % 20 == 0) && !poses.isEmpty()) {
				poses.remove(0);
			}

			double mot = 0.05;
			if (poses.size() < 1000) {
				if (unicorn.motionX >= mot || unicorn.motionX <= -mot
						|| unicorn.motionY >= mot || unicorn.motionY <= -mot
						|| unicorn.motionZ >= mot || unicorn.motionZ <= -mot) {

					Vec3d backCenter = unicorn.getPositionVector();
					Vec3d look = new Vec3d(unicorn.motionX, unicorn.motionY, unicorn.motionZ).normalize();
					backCenter = backCenter.add(look.scale(-1));

					Vec3d cross = look.crossProduct(new Vec3d(0, 1, 0)).normalize().scale(0.35f);
					poses.add(new Point(backCenter, cross, world.getTotalWorldTime()));
				} else if (!poses.isEmpty()) {
					poses.remove(0);
				}
			}
		}
	}

@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void clientTick(TickEvent.ClientTickEvent event) {
		if (Minecraft.getMinecraft().world == null) return;
		if (Minecraft.getMinecraft().player == null) return;
		if (event.side == Side.SERVER) return;
		if (event.phase != TickEvent.Phase.END) return;

		EntityPlayer player = Minecraft.getMinecraft().player;
		World world = Minecraft.getMinecraft().world;

		ItemStack stack = player.getHeldItemMainhand();

		if (stack.getItem() != ModItems.FAIRY_BELL) return;

		for (EntityFairy entityFairy : world.getEntities(EntityFairy.class, input -> {
			if (input == null) return false;
			FairyData dataFairy = input.getDataFairy();
			if (dataFairy == null) return false;
			return dataFairy.isDepressed;
		})) {
			Vec3d look = entityFairy.getLookTarget();
