default void updateScheduledTasks() {
        if (!getImmediateTasks().isEmpty()) {
            var copyTasks = new ArrayList<>(getImmediateTasks());
            getImmediateTasks().clear();
            for (Runnable task : copyTasks) {
                task.run();
            }
        }

        var taskQueue = getScheduledTasks();
        if (taskQueue.isEmpty()) {
            return;
        }
        var currentTime = getSchedulerTime();
        var currentTasks = taskQueue.get(currentTime);
        if (currentTasks != null) {
            for (Runnable task : currentTasks) {
                task.run();
            }
            taskQueue.remove(currentTime);
        }
    }

public static void onClientTick(@SuppressWarnings("unused") ClientTickEvent.Post event) {
        if (tasks.isEmpty()) {
            return;
        }

        Level level = Minecraft.getInstance().level;
        if (level == null || level.dimension() != lastDimension) {
            lastDimension = level != null ? level.dimension() : null;
            tasks.clear(); //Clear remaining tasks from the previous level

            if (level == null) {
                return;
            }
        }

        Iterator<ClientTask> it = tasks.iterator();
        while (it.hasNext()) {
            ClientTask task = it.next();
            if (level.getGameTime() >= task.time) {
                task.task.run();
                it.remove();
            }
        }
    }

public static void jobStatus(UUID id,
            AEKey what,
            long requestedAmount,
            long remainingAmount,
            CraftingJobStatusPacket.Status status) {

        AELog.debug("Crafting job " + id + " for " + requestedAmount
                + "x" + what.getDisplayName().getString() + ". State=" + status);

        var existing = jobs.get(id);
        switch (status) {
            case STARTED -> {
                if (existing == null) {
                    jobs.put(id, new PendingJob(id, what, requestedAmount, remainingAmount));
                }
            }
            case CANCELLED -> jobs.remove(id);
            case FINISHED -> {
                jobs.remove(id);
                // Only toast if no terminal is open (i.e. REI/JEI or no screen at all)
                // and a wireless terminal is in the player inv
                var minecraft = Minecraft.getInstance();
                if (AEConfig.instance().isNotifyForFinishedCraftingJobs()
                        && !(minecraft.gui.screen() instanceof MEStorageScreen<?>)
                        && minecraft.player != null && hasNotificationEnablingItem(minecraft.player)) {
                    minecraft.gui.toastManager().addToast(new FinishedJobToast(what, requestedAmount));
                }
            }
        }
    }

@Override
    public void tick(boolean serverSide) {
        if (serverSide) return;

        var context = LightManager.dynamicLightsContext;
        if (context == null) {
            // We do not want to update the entity on the server.
            if (!LightManager.shouldUpdateDynamicLight()) {
                luminance = 0;
            } else if (LightManager.shouldUpdateDynamicLight()) {
                if (this.isExpired()) {
                    this.ars_nouveau$setDynamicLightEnabled(false);
                } else {
                    this.ars_nouveau$dynamicLightTick();
                    LightManager.updateTracking(this);
                }
            }
        } else {
            this.ars_nouveau$dynamicLightTick();
        }

        ticksLeft--;
        if (ticksLeft <= 0 && context == null) {
            this.ars_nouveau$setDynamicLightEnabled(false);
        }
    }

public static void cancelCast(ServerPlayer serverPlayer, boolean triggerCooldown) {
        if (serverPlayer != null) {
            var playerMagicData = MagicData.getPlayerMagicData(serverPlayer);
            if (playerMagicData.isCasting()) {
                var spellData = playerMagicData.getCastingSpell();

                if (triggerCooldown) {
                    MagicHelper.MAGIC_MANAGER.addCooldown(serverPlayer, spellData.getSpell(), playerMagicData.getCastSource());
                }
                if (playerMagicData.getCastSource() == CastSource.SCROLL && spellData.getSpell().getCastType() == CastType.CONTINUOUS) {
                    Scroll.attemptRemoveScrollAfterCast(serverPlayer);
                }
                playerMagicData.getCastingSpell().getSpell().onServerCastComplete(serverPlayer.level, spellData.getLevel(), serverPlayer, playerMagicData, true);
            }
        }
    }

