public static void handle(DeleteObjectMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
			if (PermissionsHelper.canPlayerEdit(context)) {
				List<Long> idSublist = QuestBookEditEvent.takeLimitedElements(message.ids);
				// LinkedHashSet deduplicates input ids while preserving order, which may be significant
				List<CreateOrDeleteRecord> records = expandChildren(sqf, CreateOrDeleteRecord.fromIds(sqf, new LinkedHashSet<>(idSublist)));
				if (!records.isEmpty()) {
					DeleteQuestObjects deleteEvent = new DeleteQuestObjects(records);
					cleanUpQuestDependencies(sqf, records).ifPresentOrElse(
							modifyEvent -> sqf.getHistoryStack().addAndApply(sqf,
									CompositeEditEvent.of(modifyEvent, deleteEvent)
							),
							() -> sqf.getHistoryStack().addAndApply(sqf, deleteEvent));

				}
			}
		}));
	}

public static void handle(PacketStorageBagScreen message, IPayloadContext context) {
    context.enqueueWork(() -> {
      ServerPlayer player = (ServerPlayer) context.player();
      if (player != null) {
        ItemStack serverStack = ItemStack.EMPTY;
        if (0 <= message.slot && message.slot < player.getInventory().getContainerSize()) {
          serverStack = player.getInventory().getItem(message.slot);
        }
        String key = message.nbtKey.getAsString();
        if (!serverStack.isEmpty()
            && serverStack.getItem() == ItemRegistry.STORAGE_BAG.get()
            && (key.equals(RefillMode.NBT) || key.equals(DepositMode.NBT) || key.equals(PickupMode.NBT))) {
          //its validated this item and nbt key so now save value in the tag
          CompoundTag tag = ItemStorageBag.getCustomData(serverStack); tag.put(key, message.nbtValue); ItemStorageBag.setCustomData(serverStack, tag);
        }
      }
    });
  }

