public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(this.getIdentifier(), this.getIndex())).ifPresent(slot -> {
                var stack = slot.stack();

                if (!(stack.getItem() instanceof RingOfTheSevenDeadlySinsItem relic))
                    return;

                if (player.hurt(player.level().damageSources().magic(), 1F)) {
                    relic.addHurtTimer(stack, 40);

                    relic.getRelicData(player, stack).getStatisticData().getMetricData("unequip_attempts").addValue(1);
                }
            });
        });
    }

@Override
    public void pressButton(@NotNull ITaskInstance taskInfo) {
        TaskAction action = buttonAction(taskInfo);
        switch (action) {
            case TaskAction.COMPLETE -> {
                taskInfo.complete();
                this.completableTasks.remove(taskInfo.getId());
                this.taskInstances.remove(taskInfo);
                ISoundHandler.getSoundHandler().createMasterSoundReference(FactionSounds.TASK_COMPLETE.get(), 1, 1).startPlaying();
            }
            case TaskAction.ACCEPT -> taskInfo.startTask(factionPlayer.asEntity().level().getGameTime() + taskInfo.getTaskDuration());
            default -> taskInfo.abortTask();
        }
        FactionsMod.proxy.sendToServer(new ServerboundTaskActionPacket(taskInfo.getId(), taskInfo.getTaskBoard(), action));
        if (this.listener != null) {
            this.listener.run();
        }
    }

public static void handle(CreatePortalItemEmitterPacket message, IPayloadContext ctx) {
		if (ctx.flow().isClientbound()) {
			@SuppressWarnings("Convert2Lambda")
			Runnable work = new Runnable() {
				@Override
				public void run() {
					ClientLevel level = Minecraft.getInstance().level;
					if (level == null)
						return;

					Entity entity = level.getEntity(message.entityID());
					if (entity instanceof ItemEntity item)
						Minecraft.getInstance().particleEngine.add(new PortalItemEmitter(level, item, message.lifetime()));
