@Override
	protected void tick(ServerLevel level, E owner, long gameTime) {
		if (owner.isBlocking()) {
			blockTime++;

			LivingEntity target = owner.getLastHurtByMob();

			if (blockTime >= 5) {
				if (!owner.getBrain().hasMemoryValue(MemoryModuleType.LOOK_TARGET))
					BehaviorUtils.lookAtEntity(owner, target);

				if (owner.isWithinMeleeAttackRange(target)) {
					owner.swing(InteractionHand.MAIN_HAND);
					owner.doHurtTarget(target);
					doStop(level, owner, gameTime);
				}
				else if (owner.onGround()) {
					Vec3 lungeVector = new Vec3(target.getX() - owner.getX(), 0, target.getZ() - owner.getZ());

					if (lungeVector.lengthSqr() > 1.0E-7D)
						lungeVector = lungeVector.normalize().scale(0.4d);

					owner.setDeltaMovement(lungeVector.x(), 0.1f, lungeVector.z());
				}
			}

			return;
		}

		if (lastHitTime != owner.getLastHurtByMobTimestamp()) {
			lastHitTime = owner.getLastHurtByMobTimestamp();
			stunCount++;
		}

		if (stunCount > 2) {
			if (!(owner.getItemInHand(InteractionHand.OFF_HAND).getItem() instanceof ShieldItem))
				owner.setItemInHand(InteractionHand.OFF_HAND, new ItemStack(Items.SHIELD));

			owner.startUsingItem(InteractionHand.OFF_HAND);
		}
	}

public static void handle(MessageMungusBiomeChange message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            context.get().enqueueWork(() -> {
                Player player = context.get().getSender();
                if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                    player = AlexsMobs.PROXY.getClientSidePlayer();
                }

                if (player != null) {
                    if (player.level() != null) {
                        Entity entity = player.level().getEntity(message.mungusID);
                        Registry<Biome> registry = player.level().registryAccess().registryOrThrow(Registries.BIOME);
                        Biome biome = registry.get(new ResourceLocation(message.biomeOption));
                        ResourceKey<Biome> resourceKey = registry.getResourceKey(biome).orElse(null);
                        Holder<Biome> holder = registry.getHolder(resourceKey).orElse(null);
                        if (AMConfig.mungusBiomeTransformationType == 2) {
                            if (entity instanceof EntityMungus && entity.distanceToSqr(message.posX, entity.getY(), message.posZ) < 1000 && biome != null) {
                                LevelChunk chunk = player.level().getChunkAt(new BlockPos(message.posX, 0, message.posZ));
                                int i = QuartPos.fromBlock(chunk.getMinBuildHeight());
                                int k = i + QuartPos.fromBlock(chunk.getHeight()) - 1;
                                int l = Mth.clamp(QuartPos.fromBlock((int)entity.getY()), i, k);
                                int j = chunk.getSectionIndex(QuartPos.toBlock(l));
                                LevelChunkSection section = chunk.getSection(j);
                                if(section != null){
                                    PalettedContainer<Holder<Biome>> container = section.getBiomes().recreate();
                                    for (int biomeX = 0; biomeX < 4; ++biomeX) {
                                        for (int biomeY = 0; biomeY < 4; ++biomeY) {
                                            for (int biomeZ = 0; biomeZ < 4; ++biomeZ) {
                                                container.getAndSetUnchecked(biomeX, biomeY, biomeZ, holder);
                                            }
                                        }
                                    }
                                    section.biomes = container;
                                }
                                AlexsMobs.PROXY.updateBiomeVisuals(message.posX, message.posZ);
                            }
                        }
                    }
                }
            });

        }

public static void handle(CopyQuestMessage message, NetworkManager.PacketContext context) {
        context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
            if (PermissionsHelper.canPlayerEdit(context) && sqf.get(message.id) instanceof Quest toCopy && sqf.get(message.chapterId) instanceof Chapter chapter) {
                var allocator = new BaseQuestFile.UniqueIdAllocator(sqf);

                // deep copy of the quest
                Quest newQuest = QuestObjectBase.copy(toCopy, () -> new Quest(allocator.newId(), chapter));
                if (newQuest == null) {
                    return;
                }
                if (!message.copyDeps) {
                    newQuest.clearDependencies();
                }
                newQuest.setPosition(message.qx, message.qy);
                newQuest.setRawSubtitle(toCopy.getRawSubtitle());
                newQuest.setRawDescription(toCopy.getRawDescription());

                // deep copy of all tasks and rewards
                List<CreateOrDeleteRecord> newTasks = new ArrayList<>();
                toCopy.getTasks().forEach(task -> {
                    Task newTask = QuestObjectBase.copy(task, () -> TaskType.createTask(allocator.newId(), newQuest, task.getType().getTypeForNBT()));
                    if (newTask != null) {
                        newTasks.add(CreateOrDeleteRecord.ofQuestObject(newTask));
                    }
                });
                List<CreateOrDeleteRecord> newRewards = new ArrayList<>();
                for (Reward reward : toCopy.getRewards()) {
                    Reward newReward = QuestObjectBase.copy(reward, () -> RewardType.createReward(allocator.newId(), newQuest, reward.getType().getTypeForNBT()));
                    if (newReward != null) {
                        newRewards.add(CreateOrDeleteRecord.ofQuestObject(newReward));
                    }
                }

                List<CreateOrDeleteRecord> recs = new ArrayList<>();
                recs.add(CreateOrDeleteRecord.ofQuestObject(newQuest));
                recs.addAll(newTasks);
                recs.addAll(newRewards);

                sqf.getHistoryStack().addAndApply(sqf, new CreateQuestObjects(recs, null));
            }
        }));
    }

public int updateChunkLoading(MekGameTestHelper helper, boolean load, int level) {
            if (absolutePos == null) {
                absolutePos = helper.absolutePos(relativePos);
                absPos = absolutePos.pack();
            }
            if (helper.isChunkLoaded(relativePos) != load) {
                //If the chunk isn't watched and is loaded we want to try and unload it
                ChunkMap chunkMap = helper.getChunkMap();
                DistanceManager distanceManager = chunkMap.getDistanceManager();
                ChunkHolder holder = distanceManager.getChunk(absPos);
                //Watch the chunk and mark whether it is currently loaded or not
                if ((holder == null) == load) {
                    //If it is loaded then we need to try and unload it
                    isLoaded = !load;
                    if (DEBUG_CHUNK_LOADING) {
                        Mekanism.logger.info("Trying to {} chunk at: {}", load ? "load" : "unload", absolutePos);
                    }
                    if (load) {
                        //Load the chunk to the level it was unloaded at
                        holder = distanceManager.updateChunkScheduling(absPos, level, holder, MekGameTestHelper.UNLOAD_LEVEL);
                        if (holder == null) {//Should never happen unless start value was unloaded
                            helper.fail("Error loading chunk", relativePos);
                        } else {
                            //And ensure we schedule it to be updated by the distance manager
                            distanceManager.chunksToUpdateFutures.add(holder);
                        }
                    } else {
                        //If it is currently loaded, queue it for unload
                        level = holder.getTicketLevel();
                        distanceManager.updateChunkScheduling(absPos, MekGameTestHelper.UNLOAD_LEVEL, holder, level);
                        //And then unload it
                        chunkMap.processUnloads(ConstantPredicates.ALWAYS_TRUE);
                    }
                } else if (DEBUG_CHUNK_LOADING) {
                    //Note: Even with debug logging enabled odds are this case isn't even possible due to the earlier check to skip if unloaded
                    Mekanism.logger.info("Trying to {} already {} chunk at: {}", load ? "load" : "unload", load ? "loaded" : "unloaded", absolutePos);
                }
            } else if (DEBUG_CHUNK_LOADING) {
                Mekanism.logger.info("Chunk at: {} is already {}", absolutePos, load ? "unloaded" : "loaded");
            }
            return level;
        }

@Override
        public IMessage onMessage(final MessageCasterOrb message, final MessageContext ctx) {
            EntityPlayer player = ctx.getServerHandler().player;
            WorldServer world = ctx.getServerHandler().player.getServerWorld();
            world.addScheduledTask(() -> {
                ItemStack heldStack = player.getHeldItemMainhand();
                if (ItemModUtil.hasHeat(heldStack)) {
                    int level = ItemModUtil.getModifierLevel(heldStack, EmbersAPI.CASTER_ORB);
                    UUID uuid = player.getUniqueID();
                    if (level > 0 && EmberInventoryUtil.getEmberTotal(player) > EmbersAPI.CASTER_ORB.cost && !ModifierCasterOrb.hasCooldown(uuid)) {
                        float handmod = player.getPrimaryHand() == EnumHandSide.RIGHT ? 1.0f : -1.0f;
                        float offX = handmod * 0.5f * (float) Math.sin(Math.toRadians(-player.rotationYaw - 90));
                        float offZ = handmod * 0.5f * (float) Math.cos(Math.toRadians(-player.rotationYaw - 90));
                        EmberInventoryUtil.removeEmber(player, EmbersAPI.CASTER_ORB.cost);
                        double lookDist = Math.sqrt(message.lookX * message.lookX + message.lookY * message.lookY + message.lookZ * message.lookZ);
                        if (lookDist == 0)
                            return;
                        double xVel = (message.lookX / lookDist) * 0.5;
                        double yVel = (message.lookY / lookDist) * 0.5;
                        double zVel = (message.lookZ / lookDist) * 0.5;
                        double xOrigin = player.posX + offX;
                        double yOrigin = player.posY + player.getEyeHeight();
                        double zOrigin = player.posZ + offZ;

                        double resonance = EmbersAPI.getEmberEfficiency(heldStack);
                        double value = 8.0 * (Math.atan(0.6 * (level)) / (1.25));
                        value *= resonance;
                        EffectDamage effect = new EffectDamage((float) value, DamageEmber.EMBER_DAMAGE_SOURCE_FACTORY, 1, 1.0);
                        ProjectileFireball fireball = new ProjectileFireball(player, new Vec3d(xOrigin, yOrigin, zOrigin), new Vec3d(xVel, yVel, zVel), value, 160, effect);
                        EmberProjectileEvent event = new EmberProjectileEvent(player, heldStack, 0.0, fireball);
                        MinecraftForge.EVENT_BUS.post(event);
                        if (!event.isCanceled()) {
                            for (IProjectilePreset projectile : event.getProjectiles()) {
                                projectile.shoot(world);
                            }
                        }
                        world.playSound(null, xOrigin, yOrigin, zOrigin, SoundManager.FIREBALL, SoundCategory.PLAYERS, 1.0f, 1.0f);
                        ModifierCasterOrb.setCooldown(uuid, 20);
                    }
                }
            });
            return null;
        }

