        }
        return this.handle(new CraftAsyncTask(this.asyncScheduler.runners, plugin, runnable, this.nextId(), period), delay); // Paper
    }

@Override
  public void handleGeneric(MinecraftPacket packet) {
    if (packet instanceof PluginMessagePacket pluginMessage) {
      pluginMessage.retain();
    }
    boolean huge = packet instanceof DeferredByteBufHolder def && def.content().readableBytes() > LARGE_PACKET_THRESHOLD;
    playerConnection.delayedWrite(packet);
    if (huge || ++packetsFlushed >= MAXIMUM_PACKETS_TO_FLUSH) {
      playerConnection.flush();
      packetsFlushed = 0;
    }
  }

private void releaseQueue(ChannelHandlerContext ctx, boolean active) {
    // Handle all the queued packets
    Object msg;
    while ((msg = this.queue.poll()) != null) {
      if (active) {
        ctx.fireChannelRead(msg);
      } else {
        ReferenceCountUtil.release(msg);
      }
    }
    this.queueSize = 0;
  }

@Override
    protected void onTaskCompletion(final SpongeScheduledTask task) {
        if (task.state() == SpongeScheduledTask.ScheduledTaskState.RUNNING) {
            this.lock.lock();
            try {
                this.stateChanged.set(true);
                this.condition.signalAll();
            } finally {
                this.lock.unlock();
            }
        }
    }

@Override
    public SpongeScheduledTask submit(Task task, String name) {
        Objects.requireNonNull(task, "task");
        if (Objects.requireNonNull(name, "name").isEmpty()) {
            throw new IllegalArgumentException("Task name cannot empty!");
        }

        final SpongeScheduledTask scheduledTask = new SpongeScheduledTask(this, (SpongeTask) task,
                name + "-" + this.tag + "-#" + this.sequenceNumber++);
        this.addTask(scheduledTask);
        return scheduledTask;
    }

