            // run all deferred registrations
            for (Consumer<ParticleProviderRegistrar> consumer : deferred) {
                consumer.accept(registrar);
            }
            // yeet deferred list - register immediately from now on
            deferred = null;
        }
    }

private void freeChunkReuseQueue(Thread ownerThread) {
            if (ownerThread != null && chunkCache instanceof ThreadLocalSizeClassedChunkCache) {
                ThreadLocalSizeClassedChunkCache tlCache = (ThreadLocalSizeClassedChunkCache) chunkCache;
                int mask = tlCache.chunks.length - 1;
                for (int i = 0; i < tlCache.count; i++) {
                    SizeClassedChunk chunk = tlCache.chunks[(tlCache.head + i) & mask];
                    assert ownerThread == chunk.ownerThread;
                    chunk.ownerThread = null;
                }
            }
            chunkCache.free();
        }

public void offer(int handle) {
        if (handle == NO_VALUE) {
            throw new IllegalArgumentException("The NO_VALUE (" + NO_VALUE + ") cannot be added to the queue.");
        }
        size++;
        if (size == array.length) {
            // Grow queue capacity.
            array = Arrays.copyOf(array, 1 + (array.length - 1) * 2);
        }
        array[size] = handle;
        lift(size);
    }

