public static boolean finalizePendingCraftLinker(ServerLevel level, ItemStack linker) {
		EnderLinkPendingCraftData pendingCraft = linker.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null || !pendingCraft.resolvesToLinkerTarget() || pendingCraft.claimId() == null) {
			return false;
		}
		LinkedStorageGroupManager manager = LinkedStorageGroupsSavedData.get(level).manager();
		Optional<ActivePendingCraftClaim> claim = manager.getActivePendingCraftClaim(pendingCraft.claimId())
				.filter(activeClaim -> activeClaim.plan() == pendingCraft.plan());
		if (claim.isEmpty()) {
			return false;
		}
		linker.remove(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		linker.set(ModCoreDataComponents.ENDER_LINKER_TARGET, createTarget(manager, claim.get().groupId()));
		manager.consumeActivePendingCraftClaim(claim.get().claimId());
		return true;
	}

private static boolean finalizePendingCraftEndpoint(ServerLevel level, ItemStack endpoint) {
		EnderLinkPendingCraftData pendingCraft = endpoint.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null || pendingCraft.claimId() == null) {
			return false;
		}
		LinkedStorageGroupManager manager = LinkedStorageGroupsSavedData.get(level).manager();
		Optional<ActivePendingCraftClaim> claim = manager.getActivePendingCraftClaim(pendingCraft.claimId())
				.filter(activeClaim -> activeClaim.plan() == pendingCraft.plan());
		Optional<ILinkedStorageItemEndpointAdapter> adapter = LinkedStorageEndpointAdapters.find(endpoint);
		if (claim.isEmpty() || adapter.isEmpty()
				|| manager.getHostDescriptor(claim.get().groupId()).filter(descriptor -> adapter.get().acceptsHostFactory(descriptor.factoryId())).isEmpty()) {
			return false;
		}
		endpoint.remove(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		adapter.get().bindEndpoint(level, endpoint, new LinkedStorageEndpointData(claim.get().groupId(), claim.get().endpointId()));
		manager.consumeActivePendingCraftClaim(claim.get().claimId());
		return true;
	}

public static void issueCraftClaim(Player player, ItemStack result) {
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null) {
			return;
		}
		EnderLinkPendingCraftPlan plan = pendingCraft.plan();

		UUID playerId = player.getUUID();
		InFlightClaim inFlightClaim = pendingCraft.claimId() == null ? null : IN_FLIGHT_CLAIMS.get(pendingCraft.claimId());
		if (inFlightClaim != null && inFlightClaim.playerId().equals(playerId) && inFlightClaim.plan() == plan) {
			return;
		}
		UUID latestClaimId = LATEST_IN_FLIGHT_CLAIMS.getOrDefault(playerId, Map.of()).get(plan);
		InFlightClaim latestClaim = latestClaimId == null ? null : IN_FLIGHT_CLAIMS.get(latestClaimId);
		if (latestClaim != null && latestClaim.playerId().equals(playerId) && latestClaim.plan() == plan) {
			result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), latestClaimId));
			return;
		}
		UUID claimId = UUID.randomUUID();
		result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), claimId));
		IN_FLIGHT_CLAIMS.put(claimId, new InFlightClaim(claimId, playerId, plan));
		LATEST_IN_FLIGHT_CLAIMS.computeIfAbsent(playerId, ignored -> new HashMap<>()).put(plan, claimId);
	}

public static boolean completeCraft(ServerLevel level, Player player, Container inventory, ItemStack result) {
		Optional<Inputs> liveInputs = getInputs(inventory.getContainerSize(), inventory::getItem);
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		EnderLinkPendingCraftPlan plan = pendingCraft == null ? liveInputs.map(Inputs::plan).orElse(null) : pendingCraft.plan();
		if (plan == null) {
			return false;
		}
		InFlightClaim claim = findInFlightClaim(player, pendingCraft, plan);
		if (claim == null) {
			return false;
		}
		if (liveInputs.isEmpty() || liveInputs.get().plan() != plan) {
			return false;
		}
		Inputs inputs = liveInputs.get();
		LinkedStorageEndpointData endpointData;
		if (plan == EnderLinkPendingCraftPlan.CREATE_PRIMARY) {
			if (!LinkedStorageService.link(level, player.getUUID(), inputs.linker().copyWithCount(1), inputs.endpoint())) {
				return false;
			}
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else if (plan == EnderLinkPendingCraftPlan.BIND_EXISTING_ENDPOINT) {
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else {
			if (LinkedStorageStackLifecycle.classifyLinker(inputs.linker()) == EnderLinkerStackState.PENDING_CRAFT
					&& !finalizePendingCraftLinker(level, inputs.linker())) {
				return false;
			}
			ItemStack endpoint = inputs.endpoint().copyWithCount(1);
			if (!LinkedStorageService.link(level, inputs.linker().copyWithCount(1), endpoint)) {
				return false;
			}
			endpointData = endpoint.get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		}
		LinkedStorageGroupsSavedData.get(level).manager()
				.activatePendingCraftClaim(new ActivePendingCraftClaim(claim.claimId(), endpointData.groupId(), endpointData.endpointId(), inputs.plan()));
		IN_FLIGHT_CLAIMS.remove(claim.claimId());
		Map<EnderLinkPendingCraftPlan, UUID> latestClaims = LATEST_IN_FLIGHT_CLAIMS.get(player.getUUID());
		if (latestClaims != null) {
			latestClaims.remove(plan, claim.claimId());
			if (latestClaims.isEmpty()) {
				LATEST_IN_FLIGHT_CLAIMS.remove(player.getUUID());
			}
		}
		return true;
	}

@SubscribeEvent
	public void onPlayerTick(LivingTickEvent event) {
		if (!event.getEntity().isAlive())
			return;

		if (!event.getEntity().level().isClientSide) {
			if (event.getEntity() instanceof EnderMan || event.getEntity() instanceof Shulker) {
				int cooldown = event.getEntity().getPersistentData().getInt("ELTeleportBlock");

				if (cooldown > 0) {
					if (--cooldown > 0) {
						event.getEntity().getPersistentData().putInt("ELTeleportBlock", cooldown);
					} else {
						event.getEntity().getPersistentData().remove("ELTeleportBlock");
					}
				}
			}
		}

		if (event.getEntity() instanceof Player player) {
			if (!player.level().isClientSide) {
				SCHEDULED_DATA_SYNC.removeIf(p -> {
					TransientPlayerData.get(p).syncToPlayer();
					return true;
				});

				var counter = IPlaytimeCounter.get(player);

				if (SuperpositionHandler.isTheCursedOne(player)) {
					counter.incrementTimeWithCurses();
				} else {
					counter.incrementTimeWithoutCurses();
				}

				if (SuperpositionHandler.hasCurio(player, EnigmaticItems.DESOLATION_RING) && SuperpositionHandler.isTheWorthyOne(player)) {
					DESOLATION_BOXES.put(player, SuperpositionHandler.getBoundingBoxAroundEntity(player, 128));
				} else {
					DESOLATION_BOXES.remove(player);
				}

				if (SuperpositionHandler.hasItem(player, EnigmaticItems.SOUL_COMPASS)) {
					Integer lastUpdate = LAST_SOUL_COMPASS_UPDATE.get(player);

					if (lastUpdate == null || player.tickCount - lastUpdate > 10) {
						var optional = SuperpositionHandler.updateSoulCompass((ServerPlayer) player);


						optional.ifPresent(tuple -> {
							BlockPos pos = tuple.getB();

							if (player.distanceToSqr(pos.getX(), pos.getY(), pos.getZ()) < 256) {
								player.level().getChunkAt(pos);
								UUID id = tuple.getA();
								int radius = 3;

								AABB box = new AABB(pos.getX() - radius, pos.getY() - radius, pos.getZ() - radius,
										pos.getX() + radius, pos.getY() + radius, pos.getZ() + radius);

								List<PermanentItemEntity> list = player.level().getEntitiesOfClass(PermanentItemEntity.class, box, entity -> entity.getUUID().equals(id));

								if (list.size() <= 0) {
									SoulArchive.getInstance().removeItem(id);
								}
							}
						});
					}
				}

				if (player.tickCount % 100 == 0) {
					this.syncPlayTime(player);
				}
			} else {
				if (scheduledCubeRevive > 0 && !(Minecraft.getInstance().screen instanceof ReceivingLevelScreen)) {
					scheduledCubeRevive--;

					if (scheduledCubeRevive == 0) {
						PROXY.displayReviveAnimation(player.getId(), 1);
						scheduledCubeRevive = -1;
					}
				}
			}

			/*
			 * Temporary handler for fixing player state corruption.
			 * I still do not know why it happens.
			 */

			if (Float.isNaN(player.getHealth())) {
				player.setHealth(0F);
			}

			if (Float.isNaN(player.getAbsorptionAmount())) {
				player.setAbsorptionAmount(0F);
			}

			BlueSkiesHelper.maybeFixCapability(player);

			if (EnigmaticItems.FORBIDDEN_FRUIT.haveConsumedFruit(player)) {
				FoodData foodStats = player.getFoodData();
				foodStats.setFoodLevel(20);
				foodStats.saturationLevel = 0F;

				if (player.hasEffect(MobEffects.HUNGER)) {
					player.removeEffect(MobEffects.HUNGER);
				}
			}

			if (!CursedRing.disableInsomnia.getValue())
				if (player.isSleeping() && SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
					if (player.getSleepTimer() == 5) {
						if (player instanceof ServerPlayer) {
							player.sendSystemMessage(Component.translatable("message.enigmaticlegacy.cursed_sleep")
									.withStyle(ChatFormatting.RED));
						}
					} else if (player.getSleepTimer() > 90) {
						player.sleepCounter = 90;
					}
				}

			if (player.isOnFire() && SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
				player.setRemainingFireTicks(player.getRemainingFireTicks()+2);
			}

			/*
			 * Handler for faster effect ticking, if player is bearing Blazing Core.
			 */

			if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BLAZING_CORE))
				if (!player.getActiveEffects().isEmpty()) {
					Collection<MobEffectInstance> effects = new ArrayList<>();
					effects.addAll(player.getActiveEffects());

					for (MobEffectInstance effect : effects) {
						if (effect.getEffect().equals(EnigmaticEffects.MOLTEN_HEART)) {
							if (player.tickCount % 2 == 0 && effect.duration > 0) {
								effect.duration += 1;
							}
						} else {
							effect.tick(player, () -> {});
						}
					}

				}

			/*
			 * Handler for removing debuffs from players protected by Etherium Armor Shield.
			 * Removed as of Release 2.5.0.
			 */

			/*
			if (EnigmaticLegacy.etheriumChestplate.hasShield(player))
				if (!player.getActivePotionEffects().isEmpty()) {
					List<MobEffectInstance> effects = new ArrayList<MobEffectInstance>(player.getActivePotionEffects());

					for (MobEffectInstance effect : effects) {
						if (!effect.getPotion().isBeneficial()) {
							player.removePotionEffect(effect.getPotion());
						}
					}
				}
			 */

			if (player instanceof ServerPlayer  serverPlayer) {

				/*
				 * Handler for players' spellstone cooldowns.
				 */

				if (SuperpositionHandler.hasSpellstoneCooldown(player)) {
					SuperpositionHandler.tickSpellstoneCooldown(player, 1);
				}

				TransientPlayerData data = TransientPlayerData.get(player);
				data.setFireImmunityTimer(data.getFireImmunityTimer() - (player.isOnFire() ? 100 : 200));

				if (data.needsSync) {
					data.syncToPlayer();
					data.needsSync = false;
				}

				EnigmaticItems.ENIGMATIC_ITEM.handleEnigmaticFlight(player);

				/*
				 * Detect Unwitnessed Amulet and turn in into random color;
				 */

				for (NonNullList<ItemStack> list : player.getInventory().compartments) {
					for (int i = 0; i < list.size(); ++i) {
						ItemStack stack = list.get(i);

						// Null check 'cause I don't trust you
						if (stack != null) {
							if (stack.is(EnigmaticItems.UNWITNESSED_AMULET)) {
								stack = new ItemStack(EnigmaticItems.ENIGMATIC_AMULET);
								EnigmaticItems.ENIGMATIC_AMULET.setInscription(stack, player.getGameProfile().getName());

								if (EnigmaticAmulet.seededColorGen.getValue()) {
									EnigmaticItems.ENIGMATIC_AMULET.setSeededColor(stack);
								} else {
									EnigmaticItems.ENIGMATIC_AMULET.setRandomColor(stack);
								}

								list.set(i, stack);
							} else if (CursedRing.autoEquip.getValue() && !player.isCreative() && !player.isSpectator()
									&& stack.is(EnigmaticItems.CURSED_RING)) {
								if (!SuperpositionHandler.hasCurio(player, EnigmaticItems.CURSED_RING)) {
									if (SuperpositionHandler.tryForceEquip(player, stack)) {
										list.set(i, ItemStack.EMPTY);
									}
								}
							}
						}
					}
				}

				/*
				 * Handle Growing Hunger application.
				 */

				List<ItemStack> handItems = ImmutableList.of(player.getMainHandItem()/*, player.getOffhandItem()*/);

				if (handItems.stream().anyMatch(s -> s.is(EnigmaticItems.ELDRITCH_PAN))) {
					int currentTicks = EldritchPan.HOLDING_DURATIONS.getOrDefault(player, 0);

					if (SuperpositionHandler.cannotHunger(player)) {
						int bloodlustAmplifier = currentTicks / GrowingBloodlustEffect.ticksPerLevel.getValue();

						bloodlustAmplifier = Math.min(bloodlustAmplifier, 9);

						player.addEffect(new MobEffectInstance(EnigmaticEffects.GROWING_BLOODLUST,
								MobEffectInstance.INFINITE_DURATION, bloodlustAmplifier, true, true));
					} else {
						int hungerAmplifier = currentTicks / GrowingHungerEffect.ticksPerLevel.getValue();

						hungerAmplifier = Math.min(hungerAmplifier, 9);

						player.addEffect(new MobEffectInstance(EnigmaticEffects.GROWING_HUNGER,
								MobEffectInstance.INFINITE_DURATION, hungerAmplifier, true, true));
					}

					EldritchPan.HOLDING_DURATIONS.put(player, currentTicks + 1);
				} else {
					EldritchPan.HOLDING_DURATIONS.put(player, 0);
					player.removeEffect(EnigmaticEffects.GROWING_HUNGER);
					player.removeEffect(EnigmaticEffects.GROWING_BLOODLUST);
				}
			}

		}

	}

private static void breakInner(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos,
            float refHardness, ToolAction refTool) {
        Vec3i axis1 = RotationHelper.shiftAxis(direction.getNormal());
        Vec3i axis2 = RotationHelper.shiftAxis(axis1);
        breakBlock(world, player, item, itemStack, pos.offset(axis1), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.subtract(axis1), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.offset(axis2), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.subtract(axis2), refHardness, refTool);
    }

private static void breakOuter(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos,
            float refHardness, ToolAction refTool) {
        Vec3i axis1 = RotationHelper.shiftAxis(direction.getNormal());
        Vec3i axis2 = RotationHelper.shiftAxis(axis1);
        breakBlock(world, player, item, itemStack, pos.offset(axis1).offset(axis2), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.subtract(axis1).subtract(axis2), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.offset(axis1).subtract(axis2), refHardness, refTool);
        breakBlock(world, player, item, itemStack, pos.subtract(axis1).offset(axis2), refHardness, refTool);
    }

private static boolean breakBlock(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, BlockPos pos,
            float refHardness, ToolAction refTool) {
        BlockState offsetState = world.getBlockState(pos);

        float blockHardness = offsetState.getDestroySpeed(world, pos);
        if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                && blockHardness != -1
                && blockHardness <= refHardness
                && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
            if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                return true;
            }
        }

        return false;
    }

private static boolean breakBlock(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, BlockPos pos,
            float refHardness, ToolAction refTool) {
        BlockState offsetState = world.getBlockState(pos);

        float blockHardness = offsetState.getDestroySpeed(world, pos);
        if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                && blockHardness != -1
                && blockHardness <= refHardness
                && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
            if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                return true;
            }
        }

        return false;
    }

private boolean breakBlock(Level world, BlockPos pos, ServerPlayer shooter) {
        ServerLevel serverWorld = (ServerLevel) world;
        GameType gameType = shooter.gameMode.getGameModeForPlayer();
        BlockState blockState = world.getBlockState(pos);

        BlockEntity tileEntity = world.getBlockEntity(pos);

        if (blockState.getDestroySpeed(world, pos) != -1
                && isAlive()
                && !shooter.blockActionRestricted(world, pos, gameType)
                && blockState.is(FracturedBedrockTile.extractorBreakable)
                && blockState.getBlock().onDestroyedByPlayer(blockState, world, pos, shooter, true, world.getFluidState(pos))
                && ForgeHooks.onBlockBreakEvent(world, gameType, shooter, pos) != -1) {

            blockState.getBlock().playerDestroy(world, shooter, pos, blockState, tileEntity, ItemStack.EMPTY);
            blockState.getBlock().destroy(world, pos, blockState);
            world.levelEvent(null, 2001, pos, Block.getId(blockState));
            damage++;
            heat += 10;

            // custom exp drop check since player is not holding an item that can harvest the block
            int exp = blockState.getExpDrop(world, world.getRandom(), pos, 0, 0);
            if (exp > 0) {
                blockState.getBlock().popExperience(serverWorld, pos, exp);
            }


            if (damage > ChthonicExtractorBlock.maxDamage) {
                destroyExtractor();
            }

            return true;
        }

        return false;
    }

private static void spawnLightningBolt(ServerLevel serverLevel, BlockPos pos, ServerPlayer causingPlayer) {
        LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(serverLevel);
        lightning.moveTo(Vec3.atBottomCenterOf(pos));
        lightning.setCause(causingPlayer);
        serverLevel.addFreshEntity(lightning);
    }

