private void explode() {
        this.level().broadcastEntityEvent(this, EXPLOSION_PARTICLES_ID);

        playSound(MMSounds.ENTITY_NAGA_ACID_HIT.get(), 1, 1);

        List<Entity> entitiesHit = getEntitiesNearby(2);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity == getCaster()) continue;
                if (entity instanceof EntityNaga) continue;
                if (entity.hurt(damageSources().indirectMagic(this, getCaster()), 3 * ConfigHandler.COMMON.MOBS.NAGA.combatConfig.attackMultiplier.get().floatValue()) && entity instanceof LivingEntity livingEntity) {
                    livingEntity.addEffect(new MobEffectInstance(MobEffects.POISON, 80, 0, false, true));
                }
            }
        }

        discard() ;
    }

@Override
	public boolean hurt(DamageSource source, float amount) {
		boolean b = super.hurt(source, amount);
        if(!level().isClientSide() && isAlive()) {
            byte variant = getVariant();
            boolean isRed = variant == 4, isYellow = variant == 5, isBlue = variant == 6;
            for(EntityAyeraco e : getNearbyAyeracos(level(), position())) {
                if(isRed && e != this && e.getHealth() < e.getMaxHealth()) e.setHealth(e.getMaxHealth());
                if(isYellow) e.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 255, 2, true, false, false));
                if(isBlue) e.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 255, 2, true, false, false));
                if(e.isPurple()) {
                    playSound(SoundRegistry.AYERACO_TELEPORT.get(), 2.0F, 0.4F / (random.nextFloat() * 0.4F + 0.8F));
                    teleportRelative(random.nextInt(5) - 2, 3 + random.nextInt(15), random.nextInt(5) - 2);
                }
            }
        }
		return b;
	}

private static void causeTruesweepDamage(DamageSource damageSource, float baseDamage, ItemStack itemStack, LivingEntity attacker, LivingEntity target) {
        float targetModifier = EnchantmentHelper.getDamageBonus(itemStack, target.getMobType());
        float critMultiplier = CastOptional.cast(attacker, Player.class)
                .map(player -> ForgeHooks.getCriticalHit(player, target, false, 1.5f))
                .map(CriticalHitEvent::getDamageModifier)
                .orElse(1f);

        target.hurt(damageSource, (baseDamage + targetModifier) * critMultiplier);

        if (targetModifier > 0) {
            CastOptional.cast(attacker, Player.class).ifPresent(player -> player.magicCrit(target));
        }

        if (critMultiplier > 1) {
            attacker.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 1.3f);
            ((Player) attacker).crit(target);
        }
    }

