@Override
  public InteractionResult afterBlockUse(IToolStackView tool, ModifierEntry modifier, UseOnContext context, InteractionSource source) {
    if (!tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
      Player player = context.getPlayer();
      if (!context.getLevel().isClientSide) {
        Level world = context.getLevel();
        Direction face = context.getClickedFace();
        BlockPos pos = context.getClickedPos().relative(face);
        if (TinkerCommons.glowBlock.get().addGlow(world, pos, face.getOpposite())) {
          // damage the tool, showing animation if relevant
          if (damage > 0 && ToolDamageUtil.damage(tool, damage, player, context.getItemInHand(), modifier.getId()) && player != null) {
            player.broadcastBreakEvent(source.getSlot(context.getHand()));
          }
          world.playSound(null, pos, world.getBlockState(pos).getSoundType(world, pos, player).getPlaceSound(), SoundSource.BLOCKS, 1.0f, 1.0f);
        }
      }
      return InteractionResult.sidedSuccess(context.getLevel().isClientSide);
    }
    return InteractionResult.PASS;
  }

public static void attemptCookEntity(BlockState blockState, Level level, BlockPos pos, Entity entity, CookExecution execution) {
        if (level.isClientSide) {
            return;
        }
        if (!CampfireBlock.isLitCampfire(level.getBlockState(pos.below()))) {
            return;
        }
        if (!(level.getBlockState(pos).getBlock() instanceof AbstractCauldronBlock cauldron)) {
            return;
        }
        if (entity instanceof LivingEntity livingEntity &&
                livingEntity.getBoundingBox().intersects(cauldron.defaultBlockState().getInteractionShape(level, pos).bounds().move(pos)) &&
                livingEntity.hurt(DamageSources.get(level, ISSDamageTypes.CAULDRON), 2) &&
                !livingEntity.getType().is(ModTags.CANT_PRODUCE_BLOOD)) {
            MagicManager.spawnParticles(level, ParticleHelper.BLOOD, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 20, .05, .05, .05, .1, false);
            if (Utils.random.nextDouble() <= .5 && !isCauldronFull(blockState)) {
                execution.execute();
            }
        }
    }

public void sendRay(Player pPlayer) {
        if (pPlayer != null && !pPlayer.isSpectator()) {
            Entity target = null;
            if (this.entityResult(pPlayer) != null) {
                target = this.entityResult(pPlayer).getEntity();
            }
            if (target instanceof LivingEntity livingEntity) {
                if (!livingEntity.isAlive()) {
                    return;
                } else {
                    this.drawParticleBeam(pPlayer, livingEntity);
                }
                if (livingEntity.hurt(ModDamageSource.soulLeech(pPlayer, pPlayer), 1.0F)) {
                    int souls = SEHelper.getSoulGiven(livingEntity) < 5 ? SEHelper.getSoulGiven(livingEntity) : (int)SEHelper.getSoulGiven(livingEntity)/5;
                    SEHelper.increaseSouls(pPlayer, souls);
                    pPlayer.playSound(ModSounds.SOUL_EAT.get(), 1.0F, 1.0F);
                    ModNetwork.sendTo(pPlayer, new SPlayPlayerSoundPacket(ModSounds.SOUL_EAT.get(), 1.0F, 1.0F));
                }
            }
        }
    }

private void EarthQuake(double area) {
        this.playSound(ModSounds.EXPLOSION.get(), 1.5f, 1F + this.getRandom().nextFloat() * 0.1F);
        if (!this.level().isClientSide) {
            DamageSource damagesource = this.damageSources().mobAttack(this);
            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(area))) {
                if (!isAlliedTo(entity) && !(entity instanceof Netherite_Monstrosity_Entity) && entity != this) {
                    boolean flag = entity.hurt(damagesource, (float) ((float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) + Math.min(this.getAttributeValue(Attributes.ATTACK_DAMAGE), entity.getMaxHealth() * (float)CMCommonConfig.NetheriteMonstrosity.SmashHpdamage)));
                    if (entity.isDamageSourceBlocked(damagesource) && entity instanceof Player player) {
                        EntityUtil.disableShield(player, 120);
                    }

                    if (flag) {
                        launch(entity, 2D, 0.6D);
                        if (getIsBerserk()) {
                            entity.setSecondsOnFire(6);
                        }
                    }
                }
            }
        }
    }

@Override	
	public boolean causeFallDamage(float distance, float damageMultiplier, DamageSource p_149501_) {
		if (distance > 1.0F) {
			this.playSound(SoundEvents.COW_STEP, 0.15F, 1.0F);
		}

		int i = this.calculateFallDamage(distance, damageMultiplier);
		if (i <= 0) {
			return false;
		} else {
			this.hurt(this.damageSources().fall(), (float)i);
			if (this.isVehicle()) {
				for(Entity entity : this.getIndirectPassengers()) {
					entity.hurt(this.damageSources().fall(), (float)i);
				}
			}

			this.playBlockFallSound();
			return true;
		}
	}

@Override
	public boolean attackEntityFrom(DamageSource source, float amount) {
		if(!this.isActive() && this.isEntityAlive()) {
			if(this.hitTicks <= 0) {
				if(!this.world.isRemote && (this.rand.nextInt(12) == 0 || amount > 3.0F)) {
					this.setActive(true);
					return super.attackEntityFrom(source, amount);
				}
				for(int i = 0; i < 10; i++) {
					if(this.world.isRemote) {
						ParticleArgs<?> args = ParticleArgs.get().withMotion((this.rand.nextFloat() - 0.5F) / 2.0F, (this.rand.nextFloat() - 0.5F) / 2.0F, (this.rand.nextFloat() - 0.5F) / 2.0F).withColor(1F, 0.65F, 0.25F, 1);
						BLParticles.WEEDWOOD_LEAF.spawn(this.world, this.posX, this.posY + 0.8D, this.posZ, args);
					}
					this.playSound(SoundRegistry.PYRAD_HURT, 0.1F, 0.3F + this.rand.nextFloat() * 0.3F);
				}
				this.hitTicks = 20;
			}
			return false;
		} else {
			return super.attackEntityFrom(source, amount);
		}
	}

@Override
	public ActionResult onUse(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit) {
		boolean client = world.isClient;
		if (!state.get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (stack.getItem() instanceof FlintAndSteelItem && !state.get(Properties.LIT)) {
				if (!client) {
					world.setBlockState(pos, state.with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
				}
				return ActionResult.success(client);
			} else if (stack.isEmpty() && state.get(Properties.LIT)) {
				if (!client) {
					world.setBlockState(pos, state.with(Properties.LIT, false));
					world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				}
				return ActionResult.success(client);
			}
		}
		return super.onUse(state, world, pos, player, hand, hit);
	}

public static void clientTick(ClientLevel level) {
        long time = level.getGameTime();
        if (time == lastTick) return;
        lastTick = time;

        // 2. process all providers as before
        var iterator = providers.iterator();
        while (iterator.hasNext()) {
            var p = iterator.next();
            RenderBuffer buffer = getOrCreateBuffer(Cast.cast(p));

            if (!p.shouldRender(Cast.cast(buffer))) {
                map.remove(p);
                iterator.remove();
                continue;
            }

            if (time % p.getUpdateFrequency() == 0) {
                buffer.tick(p);
            }
        }
    }

public void applyEffectTick(LivingEntity living, int amplify) {
        if (living.tickCount % 20 == 0) {
            float amp = (amplify + 1.0F) / 10.0F;
            float damage = living.getMaxHealth() * amp;
            if (living.getHealth() <= damage || living instanceof Player) {
                living.hurt(ModDamageSource.getDamageSource(living.level, ModDamageSource.RAGE), damage);
            } else if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(living)) {
                living.setHealth(living.getHealth() - damage);
            }
        }
        if (living.level instanceof ServerLevel serverLevel) {
            if (living.canChangeDimensions()
                    && !living.getType().is(Tags.EntityTypes.BOSSES)
                    && !living.isDeadOrDying()) {
                int i1 = living.isInvisible() ? 15 : 4;
                int j = 1;
                if (living.getRandom().nextInt(i1 * j) == 0) {
                    serverLevel.sendParticles(ModParticleTypes.HYSTERIA.get(), living.getRandomX(0.5D), living.getRandomY(), living.getRandomZ(0.5D), 1, 0.0D, 0.5D, 0.0D, 0);
                }
            }
        }
    }

