@Override
	public void setDead() {
		if(!this.isDead && this.dropContentsWhenDead) {
			if(this.getAttackTarget() != null) {
				if(this.world.isRemote) {
					for(int i = 0; i < 200; i++) {
						Random rnd = this.world.rand;
						float rx = rnd.nextFloat() * 1.0F - 0.5F;
						float ry = rnd.nextFloat() * 1.0F - 0.5F;
						float rz = rnd.nextFloat() * 1.0F - 0.5F;
						Vec3d vec = new Vec3d(rx, ry, rz);
						vec = vec.normalize();
						BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.1F, this.posY + ry, this.posZ + rz + 0.1F, ParticleArgs.get().withMotion(vec.x * 0.4F, vec.y * 0.4F, vec.z * 0.4F));
					}
				} else {
					for(int i = 0; i < 8; i++) {
						this.playSound(SoundRegistry.TAR_BEAST_STEP, 1F, (this.rand.nextFloat() * 0.4F + 0.8F) * 0.8F);
					}
					List<EntityCreature> affectedEntities = (List<EntityCreature>)this.world.getEntitiesWithinAABB(EntityCreature.class, this.getEntityBoundingBox().grow(5.25F, 5.25F, 5.25F));
					for(EntityCreature e : affectedEntities) {
						if(e == this || e.getDistance(this) > 5.25F || !e.canEntityBeSeen(this) || e instanceof EntityTarminion) continue;
						double dst = e.getDistance(this);
						e.attackEntityFrom(DamageSource.causeMobDamage(this), (float)this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue() * 4);
						e.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, (int)(20 + (1.0F - dst / 5.25F) * 150), 1));
					}
				}
			}

			if(!this.world.isRemote) {
				this.dropLoot(false, 0, DamageSource.GENERIC);
			}

			this.playSound(SoundRegistry.TAR_BEAST_STEP, 2.5F, 0.5F);

			if(this.world.isRemote) {
				for(int i = 0; i < 100; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 1.0F - 0.5F;
					float ry = rnd.nextFloat() * 1.0F - 0.5F;
					float rz = rnd.nextFloat() * 1.0F - 0.5F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.1F, this.posY + ry, this.posZ + rz + 0.1F, ParticleArgs.get().withMotion(vec.x * 0.2F, vec.y * 0.2F, vec.z * 0.2F));
				}
			}
		}

		super.setDead();
	}

public void fire() {
		Vec3d ray = (new Vec3d(target.getX()-getPos().getX(),target.getY()-getPos().getY(),target.getZ()-getPos().getZ())).normalize();
		double impactDist = Double.POSITIVE_INFINITY;
		double damage = UpgradeUtil.getOtherParameter(this,"damage",DAMAGE,upgrades);
		if (!getWorld().isRemote){
			double posX = getPos().getX()+0.5;
			double posY = getPos().getY()+0.5;
			double posZ = getPos().getZ()+0.5;
			double startX = posX;
			double startY = posY;
			double startZ = posZ;
			boolean doContinue = true;
			int maxDist = UpgradeUtil.getOtherParameter(this,"distance",MAX_DISTANCE,upgrades);
			for (int i = 0; i < maxDist * 10 && doContinue; i++){
				posX += ray.x*0.1;
				posY += ray.y*0.1;
				posZ += ray.z*0.1;
				IBlockState state = getWorld().getBlockState(new BlockPos(posX,posY,posZ));
				TileEntity tile = getWorld().getTileEntity(new BlockPos(posX,posY,posZ));
				if(sparkTarget(tile))
					doContinue = false;
				else if (tile instanceof IEmberPacketReceiver){
					if (tile.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)){
						tile.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null).addAmount(capability.getEmber(), true);
						tile.markDirty();
					}
					doContinue = false;
				}
				else if (state.isFullCube() && state.isOpaqueCube()){
					doContinue = false;
				}
				//TODO: OPTIMIZE THIS, THIS CALL IS GARBAGE
				List<EntityLivingBase> rawEntities = getWorld().getEntitiesWithinAABB(EntityLivingBase.class, new AxisAlignedBB(posX-0.85,posY-0.85,posZ-0.85,posX+0.85,posY+0.85,posZ+0.85));
				for (EntityLivingBase rawEntity : rawEntities) {
					rawEntity.attackEntityFrom(RegistryManager.damage_ember, (float)damage);
				}
				if(!doContinue) {
					world.playSound(null, posX, posY, posZ, SoundManager.BEAM_CANNON_HIT, SoundCategory.BLOCKS, 1.0f, 1.0f);
					impactDist = i;
				}
			}
			PacketHandler.INSTANCE.sendToAll(new MessageBeamCannonFX(startX,startY,startZ,ray.x,ray.y,ray.z,impactDist));
			UpgradeUtil.throwEvent(this, new EmberEvent(this, EmberEvent.EnumType.CONSUME, this.capability.getEmber()), upgrades);
			this.capability.setEmber(0);
			markDirty();

			world.playSound(null,pos.getX()+0.5,pos.getY()+0.5,pos.getZ()+0.5, SoundManager.BEAM_CANNON_FIRE, SoundCategory.BLOCKS, 1.0f, 1.0f);
		}
	}

public void serverTick() {
        if (targetPlayer == null || isValidTarget(targetPlayer)) {
            debug("Aborting charge player as no target was set or target is dead");
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed();
        } else if (timeSinceCharge > 0 && timeSinceCharge >= 20 * 5) {
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
            debug("Aborting charge, Timed out");
        } else {
            double distance = targetPlayer.distanceTo(guardian);
            if (distance - closestApproach > 16 && timeSinceCharge > 10) {
                guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
                debug("Aborting charge, Player got away");
            } else {
                closestApproach = Math.min(distance, closestApproach);
                targetLocation = targetPlayer.position();
                if (!charging) {
                    double tRelX = targetLocation.x - guardian.getX();
                    double tRelZ = targetLocation.z - guardian.getZ();
                    double relTargetAngle = Mth.clamp(Mth.wrapDegrees(180.0D - Mth.atan2(tRelX, tRelZ) * (double) (180F / (float) Math.PI) - (double) guardian.getYRot()), -50.0D, 50.0D);
                    charging = Math.abs(relTargetAngle) < 1;
                    if (charging) {
                        debug("CHARGE!");
                    }
                }
                else {
                    timeSinceCharge++;
                }

                if (distance <= 5) {
                    guardian.getPhaseManager().setPhase(PhaseType.START);
                    debug("Charge Successful");
                    targetPlayer.hurt(DEDamage.guardian(guardian.level(), guardian), GuardianFightManager.CHARGE_DAMAGE);
                    guardian.playSound(SoundEvents.GENERIC_EAT, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
                    guardian.playSound(SoundEvents.GENERIC_EAT, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
                    DraconicNetwork.sendImpactEffect(guardian.level(), targetPlayer.blockPosition(), 0);
                }
            }
        }

        if (tick > 10*20) {
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
            debug("Aborting charge, Master timed out");
        }
        else if (charging && timeSinceCharge < 20 && timeSinceCharge % 5 == 0) {
            guardian.playSound(SoundEvents.ENDER_DRAGON_GROWL, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
        }

        tick++;
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        double potency = spellStat.getPotency();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster) / 2.0D;
        }
        if (this.victim != null){
            try {
                Vec3 vec3 = this.victim.getDeltaMovement();
                Vec3 force = (caster.getLookAngle()
                        .normalize()
                        .scale(Math.max(caster.distanceTo(this.victim), 4))
                        .add(caster.position())
                        .subtract(this.victim.position()))
                        .scale(potency);
                if (force.y > 0) {
                    this.victim.resetFallDistance();
                }
                Vec3 newMotion = force.subtract(vec3).scale(0.25).add(vec3);
                Vec3 delta = newMotion.subtract(vec3);
                Vec3 clampedMotion = new Vec3(signedMin(delta.x, force.x * 4), signedMin(delta.y, force.y * 4), signedMin(delta.z, force.z * 4));
                MobUtil.push(this.victim, clampedMotion, 0.25D);
                Vec3 old = new Vec3(this.victim.xOld, this.victim.yOld, this.victim.zOld);
                Vec3 travel = this.victim.position().subtract(old);
                if (this.victim.horizontalCollision && this.victim instanceof LivingEntity livingTarget) {
                    double d11 = livingTarget.getDeltaMovement().horizontalDistance();
                    float f1 = (float) (d11 * 10.0D - 3.0D);
                    int airborne = (int) travel.horizontalDistanceSqr() / 2;
                    if (f1 >= 1.0F) {
                        if (livingTarget.hurt(livingTarget.damageSources().flyIntoWall(), 4.0F + (airborne + 1) * 0.5F)) {
                            livingTarget.playSound(livingTarget.getFallSounds().big(), 2.0F, 1.0F);
                        }
                    }
                }
                if (CuriosFinder.hasCurio(caster, ModItems.RING_OF_FORCE.get())){
                    this.victim.setAirSupply(Math.max(-20, this.victim.getAirSupply() - 10));
                    if (this.victim.getAirSupply() <= -20){
                        this.victim.setAirSupply(0);
                        this.victim.hurt(ModDamageSource.choke(caster, caster), 2.0F);
                    }
                }
                ServerParticleUtil.addParticlesAroundMiddleSelf(worldIn, ParticleTypes.PORTAL, this.victim);
            } catch (NullPointerException exception) {
                caster.stopUsingItem();
            }
        } else {
            this.findVictim(worldIn, caster, spellStat);
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {
			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;
			if (targetEntity instanceof EntityPlayer) {

				double targetMana = ManaManager.getMana(targetEntity);

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					targetMana /= 2;
					targetMana = MathHelper.clamp(targetMana, targetMana, spellRing.getManaDrain(spell) * 2);
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else if (targetEntity instanceof EntityWitch) {

				double targetMana = spellRing.getManaDrain(spell) * 2;

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else {
				if (caster instanceof EntityLivingBase) ((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);

				if (caster != null)
					targetEntity.attackEntityFrom(new EntityDamageSource("magic", caster).setDamageBypassesArmor().setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);

			}
			targetEntity.hurtResistantTime = invTime;
		}

		Vec3d target = spell.getTargetWithFallback(world);
		if (target != null)
			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, CommonProxy.SoundCategory_WizardryGeneral, 0.5f, 1f);
		return true;
	}

@Override
    public boolean hurt(DamageSource pSource, float pAmount) {
        if (level.isClientSide) {
            return false;
        }
        /*
        can parry:
        - serverside
        - in combat
        - we aren't in melee attack anim or spell cast
        - the damage source is caused by an entity (ie not fall damage)
        - the damage is caused within our rough field of vision (117 degrees)
        - the damage is not /kill
         */
        boolean isDodgeableAttack = this.isAggressive() &&
                parryCooldown <= 0 &&
                !isImmobile() &&
                pSource.getEntity() != null &&
                !pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY);
        boolean canParry = isDodgeableAttack &&
                !attackGoal.isActing() &&
                pSource.getSourcePosition() != null && pSource.getSourcePosition().subtract(this.position()).normalize().dot(this.getForward()) >= 0.35;
        if (canParry && this.random.nextFloat() < 0.5) {
            serverTriggerAnimation("offhand_parry");
            procSpectralDagger();
            this.parryCooldown = 100;
            this.playSound(SoundRegistry.FIRE_DAGGER_PARRY.get());
            return false;
        }
        if (isStanceBroken()) {
            pAmount *= 0.40f;
        }
        if (isSoulMode()) {
            pAmount *= 0.50f;
        }
        if (isHalfHealthAttacking()) {
            pAmount *= 0.80f;
        }
        // damage limiter
        var limit = getMaxHealth() * 0.025f;
        if (pAmount > limit) {
            pAmount = limit + (pAmount - limit) * .3f; // damage about limit has .3x multiplier applied
        }
        if (pSource.is(DamageTypes.IN_WALL) && this.destroyBlockDelay <= 0) {
            Utils.doMobBreakSuffocatingBlocks(this);
            destroyBlockDelay = 40;
        }
        return super.hurt(pSource, pAmount);
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            if(canBlockFaceSource(source)) {
                if (!this.level().isClientSide) {
                    if (CanParryState()) {
                        if (this.getParryCount() >= MAX_PARRY_COUNT) {
                            this.setParryCount(CAN_PARRY);
                            this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                            this.level().broadcastEntityEvent(this, (byte) 11);
                            return false;
                        } else {
                            if (this.random.nextFloat() * 100.0F < (this.getParryCount() + 1) * 5 && Scylla_Entity.this.parry_cooldown <= 0) {
                                this.setParryCount(CAN_PARRY);
                                this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                                this.level().broadcastEntityEvent(this, (byte) 11);
                                return false;
                            }
                        }
                    }
                    if (this.getAttackState() == 19 && this.attackTicks < 11 && this.attackTicks > 1) {
                        this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                        this.level().broadcastEntityEvent(this, (byte) 11);
                        return false;
                    }
                }
            }
            if (this.getAttackState() == 21 || this.getAttackState() == 22) {
                return false;
            }

            if (this.isSleep()) {
                return false;
            }
        }
        if (this.destroyBlocksTick <= 0) {
            this.destroyBlocksTick = 20;
        }
        boolean flag = super.hurt(source, damage);
        if(flag) {
            if(canBlockFaceSource(source)) {
                if (this.getParryCount() < MAX_PARRY_COUNT) {
                    this.setParryCount(this.getParryCount() + (source.is(DamageTypeTags.IS_PROJECTILE) ? 2 : 1));
                }
            }
        }

        return flag;
    }

@Override
	public void tick() {
		super.tick();

		if (this.getTarget() != null && !this.getTarget().isAlive() && this.ticksSinceLastSonarFire >= 55 && this.getRandom().nextFloat() < 0.05F) {
			this.setTarget(null);
		}

		if (!this.isNoAi()) {
			if (this.isEndimationPlaying(UAPlayableEndimations.THRASHER_SONAR_FIRE)) {
				this.ticksSinceLastSonarFire = 0;
			} else {
				this.ticksSinceLastSonarFire++;
			}
			if (this.isInWaterRainOrBubble()) {
				this.setWaterTime(2400);
			} else {
				this.setWaterTime(this.getWaterTime() - 1);
				if (this.getWaterTime() <= 0) {
					this.hurt(this.damageSources().dryOut(), 1.0F);
				}

				if (!this.isInWater() && !this.isStunned() && this.onGround()) {
					this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
					this.setYRot(this.random.nextFloat() * 360.0F);
					this.setXRot(this.random.nextFloat() * -50.0F);
					this.setOnGround(false);
					this.hasImpulse = true;
					this.playSound(this.getFlopSound(), this.getSoundVolume(), this.getVoicePitch());
				}
			}
			if (this.level().isClientSide()) {
				if (!this.getPassengers().isEmpty() && this.isEndimationPlaying(UAPlayableEndimations.THRASHER_THRASH) && this.getAnimationTick() % 2 == 0 && this.getAnimationTick() > 5) {
					Entity passenger = this.getFirstPassenger();
					for (int i = 0; i < 3; ++i) {
						if (passenger.isEyeInFluid(FluidTags.WATER)) {
							this.level().addParticle(ParticleTypes.BUBBLE, passenger.getX() + (this.getRandom().nextDouble() - 0.5D) * (double) passenger.getBbWidth(), passenger.getY(), passenger.getZ() + (this.getRandom().nextDouble() - 0.5D) * (double) passenger.getBbWidth(), (this.getRandom().nextDouble() - 0.5D) * 2.0D, -this.getRandom().nextDouble(), (this.getRandom().nextDouble() - 0.5D) * 2.0D);
						}
					}
				}
			}
			if (!this.level().isClientSide && this.isStunned()) {
				if (!this.getPassengers().isEmpty()) {
					this.ejectPassengers();
				}
				this.setStunned(this.getStunTime() - 1);
			}
		}
	}

public void hitEntities() {
        List<Entity> entitiesHit = getEntityLivingBaseNearby(RANGE, RANGE, RANGE, RANGE);
        float damage = DAMAGE_PER_HIT;
        if (getCaster() instanceof EntityFrostmaw) damage *= ConfigHandler.COMMON.MOBS.FROSTMAW.combatConfig.attackMultiplier.get();
        if (getCaster() instanceof Player) damage *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.ICE_CRYSTAL.attackMultiplier.get();
        for (Entity entityHit : entitiesHit) {
            if (entityHit instanceof ItemEntity) continue;
            if (entityHit == getCaster()) continue;
            if (entityHit instanceof ItemEntity) continue;

            if (entityHit.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES) || entityHit instanceof EnderDragon) continue;

            float entityHitYaw = (float) ((Math.atan2(entityHit.getZ() - getZ(), entityHit.getX() - getX()) * (180 / Math.PI) - 90) % 360);
            float entityAttackingYaw = getYRot() % 360;
            if (entityHitYaw < 0) {
                entityHitYaw += 360;
            }
            if (entityAttackingYaw < 0) {
                entityAttackingYaw += 360;
            }
            float entityRelativeYaw = entityHitYaw - entityAttackingYaw;

            float xzDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()));
            double hitY = entityHit.getY() + entityHit.getBbHeight() / 2.0;
            float entityHitPitch = (float) ((Math.atan2((hitY - getY()), xzDistance) * (180 / Math.PI)) % 360);
            float entityAttackingPitch = -getXRot() % 360;
            if (entityHitPitch < 0) {
                entityHitPitch += 360;
            }
            if (entityAttackingPitch < 0) {
                entityAttackingPitch += 360;
            }
            float entityRelativePitch = entityHitPitch - entityAttackingPitch;

            float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()) + (hitY - getY()) * (hitY - getY()));

            boolean inRange = entityHitDistance <= RANGE;
            boolean yawCheck = (entityRelativeYaw <= ARC / 2f && entityRelativeYaw >= -ARC / 2f) || (entityRelativeYaw >= 360 - ARC / 2f || entityRelativeYaw <= -360 + ARC / 2f);
            boolean pitchCheck = (entityRelativePitch <= ARC / 2f && entityRelativePitch >= -ARC / 2f) || (entityRelativePitch >= 360 - ARC / 2f || entityRelativePitch <= -360 + ARC / 2f);
            boolean frostmawCloseCheck = getCaster() instanceof EntityFrostmaw && entityHitDistance <= 2;
            if (inRange && yawCheck && pitchCheck || frostmawCloseCheck) {
                // Do raycast check to prevent damaging through walls
                if (!raytraceCheckEntity(entityHit)) continue;

                if (entityHit.hurt(damageSources().freeze(), damage) && entityHit instanceof LivingEntity) {
                    entityHit.setDeltaMovement(entityHit.getDeltaMovement().multiply(0.25, 1, 0.25));
                    DataHandler.getData(entityHit, DataHandler.FROZEN_DATA).addFreezeProgress((LivingEntity) entityHit, 0.23f);
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (tickCount == 1) {
            if (level().isClientSide) {
                MMCommon.PROXY.playIceBreathSound(this);
            }
        }
        if (tickCount > 1 && getCaster() == null) this.discard() ;
        if (getCaster() != null && !getCaster().isAlive()) this.discard() ;
        if (tickCount == 1) playSound(MMSounds.ENTITY_FROSTMAW_ICEBREATH_START.get(), 1, 0.6f);
        if (getCaster() instanceof Player player) {
            absMoveTo(player.getX(), player.getEyeY() - 0.5f, player.getZ(), player.getYRot(), player.getXRot());
            AbilityData abilityData = DataHandler.getData(player, DataHandler.ABILITY_DATA);
            if (!abilityData.getAbilityFromType(AbilityHandler.ICE_BREATH_ABILITY).isUsing()) {
                this.discard();
            }
        }

        float yaw = (float) Math.toRadians(-getYRot());
        float pitch = (float) Math.toRadians(-getXRot());
        float spread = 0.25f;
        float speed = 0.56f;
        float xComp = (float) (Math.sin(yaw) * Math.cos(pitch));
        float yComp = (float) (Math.sin(pitch));
        float zComp = (float) (Math.cos(yaw) * Math.cos(pitch));
        if (level().isClientSide) {
            Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
            boolean overrideLimiter = camera.getPosition().distanceToSqr(getX(), getY(), getZ()) < 64 * 64;
            if (tickCount % 8 == 0) {
                level().addAlwaysVisibleParticle(new ParticleRing.Data(yaw, -pitch, 40, 1f, 1f, 1f, 1f, (int) (110 * spread), false, ParticleRing.EnumRingBehavior.GROW), overrideLimiter, getX(), getY(), getZ(), 0.5f * xComp, 0.5f * yComp, 0.5f * zComp);
            }

            for (int i = 0; i < 6; i++) {
                double xSpeed = speed * 1f * xComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(xComp)));
                double ySpeed = speed * 1f * yComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(yComp)));
                double zSpeed = speed * 1f * zComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(zComp)));
                level().addParticle(new ParticleSnowFlake.Data(37f, true), getX(), getY(), getZ(), xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 5; i++) {
                double xSpeed = speed * xComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                float value = random.nextFloat() * 0.15f;
                level().addAlwaysVisibleParticle(new ParticleCloud.Data(0.75f + value, 0.75f + value,1f, 10f + random.nextFloat() * 20f, 40, ParticleCloud.EnumCloudBehavior.GROW, 1f), overrideLimiter, getX(), getY(), getZ(), xSpeed, ySpeed, zSpeed);
            }
        }
        if (tickCount > 10) hitEntities();
        if (tickCount > 10) freezeBlocks();

        if (tickCount > 65 && !(getCaster() instanceof Player)) discard() ;
    }

@Override
    public void tick() {
        if (startActive() && tickCount == 1) activate();
        super.tick();
        if (level().isLoaded(blockPosition()) && !level().isClientSide() && (getCaster() == null || getCaster().isRemoved())) {
            explode();
        }
        findRidingEntities();
        if (travelling){
            for (Entity entity : ridingEntities) {
                entity.move(MoverType.SHULKER_BOX, getDeltaMovement().add(0, 0.1, 0));
            }
        }

        // Hit entities
        List<Entity> entitiesHit = getEntitiesNearby(1.7);
        if (travelling && !entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity.isRemoved()) continue;
                if (entity instanceof LivingEntity livingEntity && livingEntity.isDeadOrDying()) continue;
                if (level().isClientSide) continue;
                if (entity == getCaster()) continue;
                if (entity.noPhysics) continue;
                if (!entity.canBeHitByProjectile()) continue;
                if (entity instanceof ItemEntity) continue;
                if (!travellingBlockedBy(entity)) continue;
                if (ridingEntities != null && ridingEntities.contains(entity)) continue;
                if (hitEntities.contains(entity)) continue;
                boolean didHurt;
                if (getCaster() != null) {
                    didHurt = entity.hurt(damageSources().mobProjectile(this, getCaster()), damage);
                }
                else {
                    didHurt = entity.hurt(damageSources().generic(), damage);
                }
                if (didHurt) hitEntities.add(entity);
                if (isAlive() && getTier() != GeomancyTier.HUGE) this.explode();
            }
        }

        // Hit other boulders
        handleHitOtherBoulders();

        // Hit blocks
        if (travelling) {
            if (
                    !level().getEntities(this, getBoundingBox().inflate(0.1), (e) -> (ridingEntities == null || !ridingEntities.contains(e)) && e.canBeCollidedWith() && this.travellingBlockedBy(e)).isEmpty() ||
                            Iterables.size(level().getBlockCollisions(this, getBoundingBox().inflate(0.1))) > 0
            ) {
                this.explode();
            }
        }

        if (level().isClientSide() && getEntityData().get(SHOOT_DIRECTION).length() > 0 && !didShootParticles) {
            Vec3 ringOffset = new Vec3(getEntityData().get(SHOOT_DIRECTION)).scale(-1).normalize();
            ParticleRotation.OrientVector rotation = new ParticleRotation.OrientVector(ringOffset);
            AdvancedParticleBase.spawnAlwaysVisibleParticle(level(), ParticleHandler.RING2, 64, (float) getX() + (float) ringOffset.x, (float) getY() + 0.5f + (float) ringOffset.y, (float) getZ() + (float) ringOffset.z, 0, 0, 0, rotation, 3.5F, 0.83f, 1, 0.39f, 1, 1, (int) (5 + 2 * getBbWidth()), true, true, new ParticleComponent[]{
                    new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.ALPHA, ParticleComponent.KeyTrack.startAndEnd(0.7f, 0f), false),
                    new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.SCALE, ParticleComponent.KeyTrack.startAndEnd(0f, (1.0f + 0.5f * getBbWidth()) * 8f * getShootRingParticleScale()), false)
            });
            didShootParticles = true;
        }
    }

@Override
        protected void beginSection(AbilitySection section) {
            super.beginSection(section);
            if (section.sectionType == AbilitySection.AbilitySectionType.ACTIVE) {
                getUser().playSound(MMSounds.EFFECT_GEOMANCY_HIT_MEDIUM.get(0).get(), 1, 1.2f);
                if (!getLevel().isClientSide()) {
                    shootFissureAtTarget(getUser().getTarget(), prevTargetPos, 0.1f);

                    List<Entity> entitiesHit = getLevel().getEntities(getUser(), getUser().getBoundingBox().inflate(0.4), e -> e != getUser());
                    double damage = 10;
                    AttributeInstance attrib = getUser().getAttribute(Attributes.ATTACK_DAMAGE);
                    if (attrib != null) {
                        damage = attrib.getValue();
                    }
                    damage = damage * ConfigHandler.COMMON.MOBS.BLUFF.combatConfig.attackMultiplier.get();
                    for (Entity entity : entitiesHit) {
                        if (entity instanceof EntityBluff) continue;
                        entity.hurt(getUser().damageSources().mobAttack(getUser()), (float) damage);
                    }
                }

                playAnimation(ATTACK_END_ANIMATION);
                if (getLevel().isClientSide()) {
                    BlockState blockBeneath = getUser().level().getBlockState(getUser().getOnPos());
                    for (byte i = 0; i < 30; i++) {
                        getLevel().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, blockBeneath), getUser().getX(), getUser().getBlockY() + 0.1f, getUser().getZ(), getUser().random.nextFloat() * 3f - 1.5f, 2.2d, getUser().random.nextFloat() * 3f - 1.5f);
                    }
                }
            }
        }

@Override
    public boolean hurt(DamageSource source, float amount) {
        Entity entitySource = source.getEntity();
        if (entitySource != null) {
            if ((!active || getTarget() == null) && entitySource instanceof LivingEntity && !(entitySource instanceof Player && ((Player) entitySource).isCreative()) && !(entitySource instanceof EntityWroughtnaut)) setTarget((LivingEntity) entitySource);
            if (vulnerable) {
                int arc = 220;
                float entityHitAngle = (float) ((Math.atan2(entitySource.getZ() - getZ(), entitySource.getX() - getX()) * (180 / Math.PI) - 90) % 360);
                float entityAttackingAngle = yBodyRot % 360;
                if (entityHitAngle < 0) {
                    entityHitAngle += 360;
                }
                if (entityAttackingAngle < 0) {
                    entityAttackingAngle += 360;
                }
                float entityRelativeAngle = entityHitAngle - entityAttackingAngle;
                if ((entityRelativeAngle <= arc / 2f && entityRelativeAngle >= -arc / 2f) || (entityRelativeAngle >= 360 - arc / 2f || entityRelativeAngle <= -arc + 90f / 2f)) {
                    playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
                    return false;
                } else {
                    setAnimation(NO_ANIMATION);
                    return super.hurt(source, amount);
                }
            } else {
                playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
            }
        }
        else if (source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return super.hurt(source, amount);
        }
        return false;
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (getActiveAbilityType() == DEACTIVATE_ABILITY) {
            return false;
        }
        Entity entity = source.getEntity();
        if (source == damageSources().hotFloor()) return false;
        boolean angleFlag = true;
        if (entity != null) {
            int arc = 220;
            Vec3 entityPos = entity.position();
            float entityHitAngle = (float) ((Math.atan2(entityPos.z() - getZ(), entityPos.x() - getX()) * (180 / Math.PI) - 90) % 360);
            float entityAttackingAngle = yBodyRot % 360;
            if (entityHitAngle < 0) {
                entityHitAngle += 360;
            }
            if (entityAttackingAngle < 0) {
                entityAttackingAngle += 360;
            }
            float entityRelativeAngle = entityHitAngle - entityAttackingAngle;
            angleFlag = (entityRelativeAngle <= arc / 2.0 && entityRelativeAngle >= -arc / 2.0) || (entityRelativeAngle >= 360 - arc / 2.0 || entityRelativeAngle <= -arc + 90 / 2.0);
        }
        if (angleFlag && getMaskType().canBlock && entity instanceof LivingEntity && (getActiveAbility() == null || getActiveAbilityType() == HURT_ABILITY || getActiveAbilityType() == BLOCK_ABILITY) && !source.is(DamageTypeTags.BYPASSES_ARMOR)) {
            blockingEntity = (LivingEntity) entity;
            playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
            if (blockingEntity == getTarget() && random.nextFloat() < Mth.clamp(blockCount / 5.0, 0.0, 1.0) && distanceTo(blockingEntity) < 4) {
                AbilityHandler.INSTANCE.sendAbilityMessage(this, BLOCK_COUNTER_ABILITY);
                blockCount = 0;
            }
            else {
                AbilityHandler.INSTANCE.sendAbilityMessage(this, BLOCK_ABILITY);
                blockCount++;
            }
            return false;
        }
        return super.hurt(source, damage);
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (source.is(DamageTypeTags.IS_FALL)) return false;
        if (source.is(DamageTypes.LAVA) && getAnimation() == NO_ANIMATION) {
            AnimationHandler.INSTANCE.sendAnimationMessage(this, DODGE_ANIMATION);
        }

        if (source.is(DamageTypeTags.IS_FIRE)) damage *= 1.25;

        if (source.getDirectEntity() instanceof AbstractArrow) {
            playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
            Entity entity = source.getEntity();
            if (entity != null && entity instanceof LivingEntity && (!(entity instanceof Player) || !((Player)entity).isCreative()) && getTarget() == null && !(entity instanceof EntityFrostmaw)) setTarget((LivingEntity) entity);
            if (!getActive()) {
                if (getAnimation() != DIE_ANIMATION) {
                    if (level().getDifficulty() != Difficulty.PEACEFUL) {
                        if (getHasCrystal()) AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_ANIMATION);
                        else AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                    }
                }
                if (level().getDifficulty() != Difficulty.PEACEFUL) setActive(true);
            }
            return false;
        }

        boolean attack = super.hurt(source, damage);

        if (attack) {
            shouldDodgeMeasure += damage;
            Entity entity = source.getEntity();
            if (entity != null && entity instanceof LivingEntity && (!(entity instanceof Player) || !((Player)entity).isCreative()) && getTarget() == null && !(entity instanceof EntityFrostmaw)) setTarget((LivingEntity) entity);
            if (!getActive()) {
                if (getAnimation() != DIE_ANIMATION && level().getDifficulty() != Difficulty.PEACEFUL) {
                    if (getHasCrystal()) AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_ANIMATION);
                    else AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                }
                if (level().getDifficulty() != Difficulty.PEACEFUL) setActive(true);
            }
        }

        return attack;
    }

@Override
    public void tick() {
        super.tick();

        if (damageDelay >= 0) --damageDelay;

        if (!emerged) {
            emerged = true;
            damageDelay = 2;
            playSound(MMSounds.ENTITY_BLUFF_SPIKE_EMERGE.get(), 1, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            if (level().isClientSide()) {
                for (int i = 0; i < 30; i++) {
                    Vec3 offset = new Vec3(0.6 + random.nextFloat() * 0.2, 0.1, 0).yRot(random.nextFloat() * (float) Math.PI * 2f);
                    Vec3 vel = offset.normalize().scale(random.nextGaussian() * 0.12).yRot(random.nextFloat() * 0.2f - 0.1f).add(0, random.nextDouble() * 0.45 + 0.2, 0).add(getForward().scale(0.1));
                    AdvancedTerrainParticle.spawnTerrainParticle(level(), ParticleHandler.TERRAIN, getX() + offset.x, getY(), getZ() + offset.z, vel.x, vel.y, vel.z, 0, 0.4f + random.nextGaussian() * 0.3, 0.94f, 25 + random.nextFloat() * 10, getBlock(), new ParticleComponent[]{
                            new ParticleComponent.Gravity(1)
                    });
                }
            }
        }

        if (damageDelay == 0 && !level().isClientSide()) {
            damageDelay = -1;
            List<Entity> entitiesHit = level().getEntities(this, getBoundingBox().inflate(0.4), e -> e.canBeHitByProjectile() && e != getCaster() && !(e instanceof ItemEntity));
            double damage = 10;
            if (getCaster() != null) {
                if (getCaster() instanceof EntityBluff) {
                    AttributeInstance attrib = getCaster().getAttribute(Attributes.ATTACK_DAMAGE);
                    if (attrib != null) {
                        damage = attrib.getValue();
                    }
                    damage = damage * ConfigHandler.COMMON.MOBS.BLUFF.combatConfig.attackMultiplier.get();
                }
            }
            for (Entity entity : entitiesHit) {
                if (getCaster() instanceof EntityBluff && entity instanceof EntityBluff) continue;
                if (entity instanceof ItemEntity) continue;
                entity.hurt(damageSources().mobProjectile(this, getCaster()), (float) damage);
                float applyKnockbackResistance = 0;
                if (entity instanceof LivingEntity) {
                    applyKnockbackResistance = (float) ((LivingEntity) entity).getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue();
                }
                double y = 0;
                if (entity.onGround()) {
                    y += 0.15 * (1 - applyKnockbackResistance);
                }
                entity.setDeltaMovement(entity.getDeltaMovement().add(0, y, 0));
                if (entity instanceof ServerPlayer) {
                    ((ServerPlayer) entity).connection.send(new ClientboundSetEntityMotionPacket(entity));
                }
            }
        }
    }

public LivingEntity getCaster() {
        if (this.cachedCaster != null && !this.cachedCaster.isRemoved()) {
            return this.cachedCaster;
        } else if (this.getCasterID().isPresent() && this.level() instanceof ServerLevel) {
            Entity entity = ((ServerLevel)this.level()).getEntity(this.getCasterID().get());
            if (entity instanceof LivingEntity) {
                cachedCaster = (LivingEntity) entity;
                PacketDistributor.sendToPlayersTrackingEntityAndSelf(this, MessageLinkEntities.fromEntity(this, cachedCaster));
            }
            return this.cachedCaster;
        } else {
            return null;
        }
    }

