public void tick() {
        super.tick();
        var cloudData = this.getCloudData();
        if (cloudData == null) {
            // this.discard();
            return;
        }
        var world = this.getWorld();
        if (world.isClient) {
            // Client side tick
            float trackedRadius = getDataTracker().get(RADIUS_TRACKER);
            if (spawnRenderRadius < 0F) {
                spawnRenderRadius = prevRenderRadius = renderRadius = trackedRadius;
            } else {
                prevRenderRadius = renderRadius;
                renderRadius = trackedRadius;
            }
            setupAnimationStates();
            var clientData = cloudData.client_data;
            var spawnParticles = clientData.particle_spawn_interval <= 1 || (this.age % clientData.particle_spawn_interval) == 0;
            if (spawnParticles) {
                for (var particleBatch : clientData.interval_particles) {
                    ParticleHelper.play(world, this, particleBatch);
                }
            }
            for (var particleBatch : clientData.particles) {
                ParticleHelper.play(world, this, particleBatch);
            }

            var presence_sound = cloudData.presence_sound;
            if (!presenceSoundFired && presence_sound != null) {
                var soundEvent = Registries.SOUND_EVENT.get(Identifier.of(presence_sound.id()));
                if (soundEvent != null) {
                    ((SoundPlayerWorld) world).playSoundFromEntity(this, soundEvent, SoundCategory.PLAYERS,
                            presence_sound.volume(),
                            presence_sound.randomizedPitch());
                    presenceSoundFired = true;
                } else {
                    System.out.println("SpellCloud: Failed to find presence sound " + presence_sound.id());
                }
            }

        } else {
            // Server side tick
            if (this.age >= this.timeToLive) {
                this.discard();
                return;
            }
            // Advance the lifecycle phase. Impacts are only performed while ACTIVE — the
            // spawning and despawning phases are warm-up / wind-down, matching SummonedEntity.
            byte phase;
            if (this.age < spawnDuration) {
                phase = PHASE_SPAWNING;
            } else if (this.age >= timeToLive - despawnDuration) {
                phase = PHASE_DESPAWNING;
            } else {
                phase = PHASE_ACTIVE;
            }
            setPhase(phase);
            // Lifetime growth: recompute the radius from the current age and republish it only when it
            // actually changes (i.e. on a growth-step boundary), so rendering/collision follow and sync
            // traffic stays minimal. `radiusForAge` is a no-op unless `growth` is configured.
            float grownRadius = radiusForAge(this.age);
            if (grownRadius != getDataTracker().get(RADIUS_TRACKER)) {
                getDataTracker().set(RADIUS_TRACKER, grownRadius);
                calculateDimensions();
            }
            if (phase == PHASE_ACTIVE && (this.age % cloudData.impact_tick_interval) == 0) {
                // Impact tick due
                var area_impact = cloudData.volume;
                var owner = (LivingEntity) this.getOwner();
                var spellEntry = getSpellEntry();
                if (area_impact != null && owner != null && spellEntry != null) {
                    var spell = spellEntry.value();
                    var context = this.context;
                    if (context == null) {
                        context = new SpellExecution.ImpactContext();
                    }
                    var performed = SpellImpacts.lookupAndPerformAreaImpact(area_impact, spellEntry, owner,null,
                            this, spell.impacts, context.position(this.getPos()), true, grownRadius);
                    if (performed) {
                        onImpactPerformed(owner, world, cloudData, context);
                        if (this.impactCap > 0 && this.impactsPerformed >= this.impactCap) {
                            // A spent cloud winds down through DESPAWNING rather than vanishing on
                            // the spot, so its model gets a phase to animate in. A subclass that
                            // already called `beginDespawn` from `onImpactPerformed` (e.g. to use a
                            // longer, bespoke clip) makes this a no-op.
                            beginDespawn(this.despawnDuration);
                        }
                    } else {
                        onImpactFailed(owner, world, cloudData, context);
                    }
                }
            }
        }
    }

@Override
    public void tick() {
        LivingEntity target = summonedEntity.getTarget();
        // If the target vanished mid-swing, abort the swing so shouldContinue() returns false
        // next tick and MOVE/LOOK get released — otherwise FollowSummonerGoal can never start.
        if (target == null || !target.isAlive()) {
            swingTick = -1;
            return;
        }
        // Lock onto the target — every tick the melee goal is active, the entity faces
        // its target without the 30°/tick smoothing lag of `lookAt`.
        summonedEntity.lockRotationTo(target);

        boolean inRange = isTargetInRange(target);

        // Begin a new swing only when not currently swinging, in range, and fully recovered.
        // Recovery uses vanilla LivingEntity.lastAttackTime: onAttacking(target) below sets it
        // to the current age, mirroring how PlayerEntity.getAttackCooldownProgress works.
        if (swingTick < 0 && inRange && attackCooldownProgress() >= 1F) {
            swingTick = 0;
            summonedEntity.onAttacking(target); // saves vanilla lastAttackTime = age
            summonedEntity.onAttackAnimated(config.duration, summonedEntity.pickVariant(config.animation_variants));
            summonedEntity.playConfiguredSound(config.swing_sound);
//            SummonedEntity.LOGGER.info("[WindupMelee] attack-start entity={} target={} duration={} windup={}->tick{} radius={} interval={}",
//                    summonedEntity.getId(), target.getId(),
//                    config.duration, config.windup, windupTick(), config.radius, swingInterval());
        }

        // Navigation: hold inside the (smaller) desired range — held back from full
        // attack reach so the entity doesn't bump into the target. Pursue otherwise,
        // slowed to movement_modifier × movement_speed during a swing.
        boolean atHoldRange = summonedEntity.squaredDistanceTo(target) <= squaredHoldRange(target);
        double moveSpeed = (swingTick >= 0)
                ? config.movement_speed * config.movement_modifier
                : config.movement_speed;
        navUpdateCountdown--;
        if (atHoldRange) {
            summonedEntity.getNavigation().stop();
        } else if (moveSpeed > 0) {
            if (navUpdateCountdown <= 0) {
                summonedEntity.getNavigation().startMovingTo(target, moveSpeed);
                navUpdateCountdown = 5;
            }
        } else {
            summonedEntity.getNavigation().stop();
        }

        // Drive swing progression.
        if (swingTick >= 0) {
            if (swingTick == windupTick()) {
                // Re-check reach with in-progress tolerance: if the target drifted only
                // slightly out during the windup the swing still connects; only a clear
                // dodge whiffs it.
                boolean hit = isTargetInRange(target, IN_PROGRESS_RANGE_TOLERANCE);
//                SummonedEntity.LOGGER.info("[WindupMelee] attack-impact entity={} target={} tick={} hit={}",
//                        summonedEntity.getId(), target.getId(), swingTick, hit);
                if (hit) {
                    performAttackImpact(target);
                }
            }
            swingTick++;
            if (swingTick >= config.duration) {
                swingTick = -1;
                // No explicit ATTACK_ANIMATION stop needed: the client auto-stops the
                // animation when `age - startAge >= duration`. Every new swing carries a
                // fresh monotonic startAge in the packed tracker, so back-to-back swings
                // always re-sync even if variant and duration repeat.
                summonedEntity.onActionCompleted(SummonBehaviour.Action.Type.MELEE_ATTACK, null);
            }
        }
    }

public static void performAttackAgainstTargets(ServerPlayerEntity player, AttackContext context, int[] targetIds) {
        var world = player.getWorld();
        var focusMode = focusMode();
        var attributeInstance = player.getAttributes().getCustomInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE);
        EntityAttributeModifier appliedDamageModifier = null;
        EntityAttributeModifier appliedDualWieldModifier = null;
        EntityAttributeModifier appliedChargeModifier = null;
        // Arrived from the client, so it is never trusted as-is.
        var curvedRatio = MathHelper.clamp(context.charge(), 0F, 1F);
        try {
            var lastAttackTime = ((LivingEntityAccessor)player).spellEngine_getLastAttackedTicks();
            var targets = new ArrayList<Entity>();
            var resolvedContext = resolveAttackData(player, world, context.spellId, context.attackId);
            var spellEntry = resolvedContext.spell();
            ((SpellCaster.Player)player).setActiveMeleeSkill(spellEntry);
            var attack = resolvedContext.attack();
            Sound impactSound = null;
            int impactSoundLimit = 0;
            var resolvedCharge = resolveCharge(spellEntry, curvedRatio);
            var charge = resolvedCharge.outputMultiplier();
            var modifiers = SpellModifiers.of(player, spellEntry, resolvedCharge.modifier());
            var damageMultiplierBase = 0F;
            for (var modifier : modifiers) {
                damageMultiplierBase += modifier.melee_damage_multiplier;
            }
            // Read before any temporary modifier lands, so it cannot inflate its own ratio. Kept as a
            // separate modifier rather than summed into the one below: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so this way percentage bonuses scale the dual
            // wielded swing instead of the main hand one.
            var dualWieldBonus = dualWieldDamageBonus(player, spellEntry != null ? spellEntry.value() : null);
            if (dualWieldBonus != 0 && attributeInstance != null) {
                appliedDualWieldModifier = new EntityAttributeModifier(DUAL_WIELD_MODIFIER_ID, dualWieldBonus, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedDualWieldModifier);
            }
            // Melee skills land their damage through vanilla `player.attack(...)`, which the
            // `ImpactContext` never reaches, so a partial CHARGE release scales the swing here.
            // Kept separate for the same reason as the dual wield bonus: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so the charge scales the whole swing rather
            // than being diluted by the flat bonuses below.
            if (charge != 1F && attributeInstance != null) {
                appliedChargeModifier = new EntityAttributeModifier(CHARGE_MODIFIER_ID, charge - 1F, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedChargeModifier);
            }
            if (attack != null && attributeInstance != null) {
                var damageModifierAmount = attack.damage_bonus + damageMultiplierBase;
                if (damageModifierAmount != 0) {
                    appliedDamageModifier = new EntityAttributeModifier(DAMAGE_MODIFIER_ID, damageModifierAmount, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                    attributeInstance.addTemporaryModifier(appliedDamageModifier);
                }
                impactSound = attack.impact_sound;
                impactSoundLimit = attack.impact_sound_cap > 0 ? attack.impact_sound_cap : 999;
            }
            var attackRange = spellEntry != null ? SpellParameters.getRangeCurved(player, spellEntry, curvedRatio) : (float)player.getEntityInteractionRange();

            for (int targetId : targetIds) {
                var target = world.getEntityById(targetId);
                if (target != null && target.isAttackable()) {
                    if (!EntityRelations.actionAllowed(
                            focusMode, SpellTarget.Intent.HARMFUL,
                            player, target)) {
                        continue;
                    }

                    var distanceGuard = (attackRange + largesSideLength(target.getBoundingBox())) * 1.2F; // Adding some tolerance
                    if (player.squaredDistanceTo(target) > (distanceGuard * distanceGuard) ) {
                        continue;
                    }

                    var timeUntilRegen = target.timeUntilRegen;
                    target.timeUntilRegen = 0;
                    ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(100);
                    player.attack(target);
                    if (impactSound != null && impactSoundLimit > 0) {
                        SoundHelper.playSound(target.getWorld(), target, impactSound);
                        impactSoundLimit -= 1;
                    }
                    targets.add(target);
                    target.timeUntilRegen = timeUntilRegen;
                }
            }

            if (!targets.isEmpty()) {
                var impactContext = new SpellExecution.ImpactContext()
                        .position(player.getPos())
                        .charge(curvedRatio)
                        .chargeModifier(resolvedCharge.modifier());
                SpellImpacts.meleeImpact(player, targets, spellEntry, impactContext);
            }
            ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(lastAttackTime);
        } catch (Exception e) {
            System.err.println("Failed to perform melee attack: " + e.getMessage());
        }
        if (appliedDamageModifier != null) {
            attributeInstance.removeModifier(appliedDamageModifier);
        }
        if (appliedDualWieldModifier != null) {
            attributeInstance.removeModifier(appliedDualWieldModifier);
        }
        if (appliedChargeModifier != null) {
            attributeInstance.removeModifier(appliedChargeModifier);
        }
        ((SpellCaster.Player)player).setActiveMeleeSkill(null);
    }

public void onCreatedFromSpell(Identifier spellId, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context, float time_to_live_seconds, Spell.Modifier.Cloud cloudModifier) {
        this.spellId = spellId;
        this.context = context;
        this.cloudModifier = cloudModifier;

        var spellEntry = getSpellEntry();
        if (spellEntry != null) {
            var spell = spellEntry.value();
            var index = 0;
            var dataList = spell.deliver.clouds;
            if (!dataList.isEmpty()) {
                index = dataList.indexOf(cloudData);
            }
            this.dataIndex = index;
        }
        this.getDataTracker().set(SPELL_ID_TRACKER, this.spellId.toString());
        this.getDataTracker().set(DATA_INDEX_TRACKER, this.dataIndex);
        this.getDataTracker().set(RADIUS_TRACKER, radiusForAge(this.age));

        // Carve the lifetime into spawning / active / despawning, like a summoned entity.
        // `time_to_live_seconds` is the ACTIVE duration; spawn/despawn bracket it.
        this.spawnDuration   = cloudData.spawn_ticks;
        this.despawnDuration = cloudData.despawn_ticks;
        int activeTicks      = (int) (time_to_live_seconds * 20);
        this.timeToLive      = this.spawnDuration + activeTicks + this.despawnDuration;
        this.impactCap = cloudData.impact_cap;
    }

protected void beginDespawn(int ticks) {
        if (getWorld().isClient || isDespawning()) {
            return;
        }
        if (ticks <= 0) {
            this.discard();
            return;
        }
        this.despawnDuration = ticks;
        this.timeToLive = this.age + ticks;
        // Publish now; waiting for the next tick would leak one frame of the ACTIVE pose.
        setPhase(PHASE_DESPAWNING);
    }

private void setPhase(byte phase) {
        if (getDataTracker().get(PHASE_TRACKER) != phase) {
            getDataTracker().set(PHASE_TRACKER, phase);
            // Fire the wind-down FX exactly on the ACTIVE -> DESPAWNING transition. This is the sole
            // server-side choke point for phase changes (both the age-based expiry in `tick()` and
            // `beginDespawn()` route through here), and the tracker guard makes it run once. Mirrors the
            // spawn FX in CloudPlacer.placeCloud. `despawn_ticks == 0` clouds discard before reaching
            // DESPAWNING, so they get no wind-down FX by design.
            if (phase == PHASE_DESPAWNING) {
                playDespawnFX();
            }
        }
        int endOfPhaseAge = switch (phase) {
            case PHASE_SPAWNING   -> spawnDuration;
            case PHASE_ACTIVE     -> timeToLive - despawnDuration;
            case PHASE_DESPAWNING -> timeToLive;
            default               -> 0;
        };
        getDataTracker().set(END_OF_PHASE_AGE, endOfPhaseAge);
    }

public void tick() {
        if(chargeCooldown > 0){
            chargeCooldown--;
        }
        if(chargeTimeout > 100){
            chargeTimeout = 0;
            candicorn.setCharging(false);
        }
        LivingEntity target = candicorn.getTarget();
        if (target != null && target.isAlive()) {
            double distance = candicorn.distanceTo(target);
            double chargeFromDistance = 15;
            double attackDistance = candicorn.getBbWidth() + target.getBbWidth() + 0.5F;
            candicorn.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            if (candicorn.getAnimation() == CandicornEntity.ANIMATION_STAB) {
                candicorn.getNavigation().stop();
                if(candicorn.getAnimationTick() > 8 && candicorn.getAnimationTick() <= 12){
                    if(target.hurt(target.damageSources().mobAttack(candicorn), (float) candicorn.getAttribute(Attributes.ATTACK_DAMAGE).getValue())){
                        target.knockback(0.6F, candicorn.getX() - target.getX(), candicorn.getZ() - target.getZ());
                    }
                }
            } else {
                if(candicorn.isCharging()){
                    chargeTimeout++;
                    candicorn.getNavigation().stop();
                    Vec3 sub = startChargeTargetVec.subtract(startChargeFromVec);
                    Vec3 delta = sub.normalize().scale(0.85);
                    candicorn.setDeltaMovement(candicorn.getDeltaMovement().scale(0.9).add(delta));
                    candicorn.setChargeYaw(Mth.wrapDegrees((float)(Mth.atan2(sub.z, sub.x) * (double)(180F / (float)Math.PI)) - 90.0F));
                    if((distance < attackDistance || candicorn.distanceToSqr(startChargeTargetVec) < attackDistance * attackDistance) && candicorn.getChargeProgress(1.0F) == 1.0F && candicorn.hasLineOfSight(target)){
                        chargeCooldown = 100;
                        candicorn.setCharging(false);
                    }
                    candicorn.setRunning(true);
                }else if(distance > attackDistance && distance < chargeFromDistance && chargeCooldown <= 0 && !candicorn.isCharging() && candicorn.hasLineOfSight(target)){
                    candicorn.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                    candicorn.setCharging(true);
                    startChargeTargetVec = target.position();
                    startChargeFromVec = candicorn.position();
                }else if (distance < attackDistance && candicorn.getAnimation() == IAnimatedEntity.NO_ANIMATION && candicorn.hasLineOfSight(target) && !candicorn.isCharging()) {
                    candicorn.setAnimation(CandicornEntity.ANIMATION_STAB);
                }else if (distance > attackDistance) {
                    this.candicorn.getNavigation().moveTo(target, 1.0D);
                    candicorn.setRunning(true);
                } else {
                    candicorn.setRunning(false);
                }
            }
        }
    }

public void tick() {
        if(jumpCooldown > 0){
            jumpCooldown--;
        }
        if (stalk) {
            if (secondPartOfLeap) {
                this.leopard.setTackling(!leopard.onGround());
                leopard.lookAt(target, 180F, 10F);
                leopard.yBodyRot = leopard.getYRot();
                if (this.leopard.distanceTo(target) < 3F && this.leopard.hasLineOfSight(target)) {
                    target.hurt(this.leopard.damageSources().mobAttack(leopard), (float) (leopard.getAttribute(Attributes.ATTACK_DAMAGE).getValue() * 2.5F));
                    this.stalk = false;
                    this.secondPartOfLeap = false;
                }else if (leopard.onGround() && jumpCooldown == 0) {
                    this.leopard.setSlSneaking(false);
                    jumpCooldown = 10 + leopard.getRandom().nextInt(10);
                    Vec3 vector3d = this.leopard.getDeltaMovement();
                    Vec3 vector3d1 = new Vec3(this.target.getX() - this.leopard.getX(), 0.0D, this.target.getZ() - this.leopard.getZ());
                    if (vector3d1.lengthSqr() > 1.0E-7D) {
                        vector3d1 = vector3d1.normalize().scale(0.9D).add(vector3d.scale(0.8D));
                    }
                    this.leopard.setDeltaMovement(vector3d1.x, vector3d1.y + 0.6F, vector3d1.z);
                }
            } else {
                if (leapPos == null || target.distanceToSqr(leapPos) > 250) {
                    Vec3 vector3d1 = calculateFarPoint(50);
                    if (vector3d1 != null) {
                        leapPos = vector3d1;
                    }else{
                        leapPos = LandRandomPos.getPosTowards(leopard, 10, 10, target.position());
                    }
                } else {
                    this.leopard.setSlSneaking(true);
                    this.leopard.getNavigation().moveTo(leapPos.x, leapPos.y, leapPos.z, 1D);
