public void tick() {
        LivingEntity target = raptor.getTarget();
        raptor.setRunning(true);
        if (target != null) {
            double dist = raptor.distanceTo(target);
            if (raptor.isLeaping()) {
                checkAndDealDamage(target);
                if (raptor.onGround() || raptor.isInWaterOrBubble()) {
                    raptor.setLeaping(false);
                }
            } else if (raptor.getAnimation() == VallumraptorEntity.ANIMATION_STARTLEAP) {
                raptor.getNavigation().stop();
                raptor.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                if (raptor.getAnimationTick() > 15 && raptor.onGround()) {
                    raptor.setLeaping(true);
                    raptor.playSound(ACSoundRegistry.VALLUMRAPTOR_ATTACK.get());
                    Vec3 vector3d = raptor.getDeltaMovement();
                    Vec3 vector3d1 = new Vec3(target.getX() - raptor.getX(), 0.0D, target.getZ() - raptor.getZ());
                    if (vector3d1.lengthSqr() > 1.0E-7D) {
                        vector3d1 = vector3d1.normalize().scale(0.9D).add(vector3d.scale(0.5D));
                    }
                    raptor.setDeltaMovement(vector3d1.x, 0.6F, vector3d1.z);
                }
            } else {
                raptor.getNavigation().moveTo(target, 1.0D);
                if (dist < raptor.getBbWidth() + target.getBbWidth() + 1) {
                    tryAnimation(raptor.getRandom().nextBoolean() ? VallumraptorEntity.ANIMATION_MELEE_BITE : raptor.getRandom().nextBoolean() ? VallumraptorEntity.ANIMATION_MELEE_SLASH_2 : VallumraptorEntity.ANIMATION_MELEE_SLASH_1);
                    if (raptor.getAnimation() == VallumraptorEntity.ANIMATION_MELEE_BITE && raptor.getAnimationTick() > 5 && raptor.getAnimationTick() <= 8) {
                        checkAndDealDamage(target);
                    }
                    if ((raptor.getAnimation() == VallumraptorEntity.ANIMATION_MELEE_SLASH_1 || raptor.getAnimation() == VallumraptorEntity.ANIMATION_MELEE_SLASH_2) && raptor.getAnimationTick() > 7 && raptor.getAnimationTick() <= 10) {
                        checkAndDealDamage(target);
                    }
                } else {
                    int jumpChance = raptor.isTame() ? 5 : 10;
                    if (dist > 3.0F && dist < 7.0F && raptor.getRandom().nextInt(jumpChance) == 0) {
                        tryAnimation(VallumraptorEntity.ANIMATION_STARTLEAP);
                    }
                }
            }
        }
    }

@Override
    public void startAttackBehavior(LivingEntity target) {
        double distance = this.distanceTo(target);
        float f = this.getBbWidth() + target.getBbWidth();
        boolean meleeOnly = this.getItemInHand(InteractionHand.MAIN_HAND).is(ACItemRegistry.ORTHOLANCE.get());
        if ((distance > 15 || !melee) && !meleeOnly) {
            melee = false;
            if (!pickUpTrident() && this.getItemInHand(InteractionHand.MAIN_HAND).is(Items.TRIDENT)) {
                if (this.hasLineOfSight(target) && distance < 35) {
                    this.getNavigation().stop();
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(ANIMATION_THROW);
                    } else if (this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() > 8) {
                        melee = true;
                        throwTrident(target);
                        this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                } else {
                    this.getNavigation().moveTo(target, 1.2);
                }
            }
        }
        if (melee || meleeOnly) {
            if (distance < f + 1.0F) {
                if (this.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    setAnimation(this.getRandom().nextBoolean() ? ANIMATION_SCRATCH : ANIMATION_BITE);
                    this.playSound(ACSoundRegistry.DEEP_ONE_KNIGHT_ATTACK.get());
                }
            } else {
                this.getNavigation().moveTo(target, 1.2);
            }
        }
        if (this.getAnimation() == ANIMATION_SCRATCH) {
            if (this.getAnimationTick() > 5 && this.getAnimationTick() < 9 || this.getAnimationTick() > 12 && this.getAnimationTick() < 16) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE) {
            if (this.getAnimationTick() > 3 && this.getAnimationTick() <= 7) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
    }

@Override
	public void tick() {
		LivingEntity target = this.taskOwner.getTarget();

		if (target == null) {
			stop();

			return;
		}

		double attackDistance = this.taskOwner.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());

		this.taskOwner.getLookControl().setLookAt(target, 30, 30);
		this.delayTicks--;

		if ((this.retainTarget || this.taskOwner.getSensing().canSee(target)) &&
				this.delayTicks <= 0 &&
				(this.targetX == 0 && this.targetY == 0 && this.targetZ == 0 || target.distanceToSqr(this.targetX, this.targetY, this.targetZ) >= 1 ||
						this.taskOwner.getRandom().nextFloat() < 0.05f)) {
			this.targetX = target.getX();
			this.targetY = target.getBoundingBox().minY;
			this.targetZ = target.getZ();
			this.delayTicks = 4 + this.taskOwner.getRandom().nextInt(7);

			if (attackDistance > 1024) {
				this.delayTicks += 10;
			}
			else if (attackDistance < 256) {
				this.delayTicks += 5;
			}

			if (!this.taskOwner.getNavigation().moveTo(target, this.speedModifier)) {
				this.delayTicks += 15;
			}
			else {
				this.taskOwner.getMoveControl().setWantedPosition(this.targetX, this.targetY, this.targetZ, this.speedModifier);
			}

		}

		if (this.attackCooldown > 0)
			this.attackCooldown--;

		this.checkAndAttack(target, attackDistance);
	}

