                    if (i >= 20 || crossbow && crossbowCooldown == 0) {
                        this.entity.stopUsingItem();
                        this.entity.performRangedAttack(livingentity, BowItem.getPowerForTime(i));
                        this.attackTime = this.attackCooldown;
                        crossbowCooldown = 20;
                    }
                }
            } else if (--this.attackTime <= 0 && this.seeTime >= -60) {
                this.entity.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.entity, Items.BOW));
            }

        }
    }

public void tick() {
		LivingEntity target = shooter.getTarget();

		if (target != null) {
			double distanceToTarget = shooter.distanceToSqr(target.getX(), target.getY(), target.getZ());
			boolean canSeeTarget = shooter.getSensing().canSee(target);


			if (canSeeTarget != seeTime > 0)
				seeTime = 0;

			if (canSeeTarget) {
				++seeTime;
			}
			else {
				--seeTime;
			}

			if (!(distanceToTarget > maxAttackDistance) && seeTime >= 20) {
				shooter.getNavigation().stop();
				++strafingTime;
			}
			else {
				shooter.getNavigation().moveTo(target, moveSpeedAmp);
				strafingTime = -1;
			}

			if (strafingTime >= 20) {
				if (shooter.getRandom().nextFloat() < 0.3D)
					strafingClockwise = !strafingClockwise;

				if (shooter.getRandom().nextFloat() < 0.3D)
					strafingBackwards = !strafingBackwards;

				strafingTime = 0;
			}

			if (strafingTime > -1) {
				if (distanceToTarget > maxAttackDistance * 0.75F) {
					strafingBackwards = false;
				}
				else if (distanceToTarget < maxAttackDistance * 0.25F) {
					strafingBackwards = true;
				}

				shooter.getMoveControl().strafe(strafingBackwards ? -0.5F : 0.5F, strafingClockwise ? 0.5F : -0.5F);
				shooter.lookAt(target, 30.0F, 30.0F);
			}
			else {
				shooter.getLookControl().setLookAt(target, 30.0F, 30.0F);
			}

			if (shooter.isUsingItem()) {
				if (!canSeeTarget && seeTime < -60) {
					shooter.stopUsingItem();
				}
				else if (canSeeTarget) {
					int maxItemUseTime = shooter.getTicksUsingItem();

					if (maxItemUseTime >= 20) {
						shooter.stopUsingItem();
						shooter.performRangedAttack(target, BowItem.getPowerForTime(maxItemUseTime));
						attackTime = attackCooldown;
					}
				}
			}
			else if (--attackTime <= 0 && seeTime >= -60) {
				shooter.startUsingItem(ProjectileHelper.getWeaponHoldingHand(shooter, Items.BOW));
			}
		}
	}

@Override
	public void end(LivingEntityPatch<?> entitypatch, AssetAccessor<? extends DynamicAnimation> nextAnimation, boolean isEnd) {
		super.end(entitypatch, nextAnimation, isEnd);

        AnimationPlayer player = entitypatch.getAnimator().getPlayerFor(this.getAccessor());

        if (player == null) {
            return;
        }

        float elapsedTime = player.getElapsedTime();
        EntityState state = this.getState(entitypatch, elapsedTime);

        if (!isEnd && state.attacking() && !entitypatch.isLogicalClient()) {
            EpicFightEventHooks.Animation.ATTACK_PHASE_END.postWithListener(new AttackPhaseEndEvent(entitypatch, this.getAccessor(), this.getPhaseByTime(elapsedTime), this.getPhaseOrderByTime(elapsedTime), true), entitypatch.getEventListener());
        }

		if (entitypatch instanceof HumanoidMobPatch<?> mobpatch && entitypatch.isLogicalClient()) {
			Mob entity = mobpatch.getOriginal();

			if (entity.getTarget() != null && !entity.getTarget().isAlive()) {
				entity.setTarget(null);
			}
		}
	}

protected void attackTick(LivingEntityPatch<?> entitypatch, AssetAccessor<? extends DynamicAnimation> animation) {
		AnimationPlayer player = entitypatch.getAnimator().getPlayerFor(this.getAccessor());

        if (player == null) {
            return;
        }

		float prevElapsedTime = player.getPrevElapsedTime();
		float elapsedTime = player.getElapsedTime();
		EntityState prevState = animation.get().getState(entitypatch, prevElapsedTime);
		EntityState state = animation.get().getState(entitypatch, elapsedTime);
		Phase phase = this.getPhaseByTime(animation.get().isLinkAnimation() ? 0.0F : elapsedTime);

		if (prevState.attacking() || state.attacking() || (prevState.getLevel() <= 2 && state.getLevel() > 2)) {
			if (!prevState.attacking() || (phase != this.getPhaseByTime(prevElapsedTime) && (state.attacking() || (prevState.getLevel() <= 2 && state.getLevel() > 2)))) {
				entitypatch.onStrike(this, phase.effectiveHand(entitypatch));
				entitypatch.playSound(this.getSwingSound(entitypatch, phase), 0.0F, 0.0F);
				entitypatch.removeHurtEntities();
			}

			this.hurtCollidingEntities(entitypatch, prevElapsedTime, elapsedTime, prevState, state, phase);

			if ((!state.attacking() || elapsedTime >= this.getTotalTime()) && entitypatch instanceof ServerPlayerPatch playerpatch) {
                EpicFightEventHooks.Animation.ATTACK_PHASE_END.postWithListener(new AttackPhaseEndEvent(entitypatch, this.getAccessor(), phase, this.getPhaseOrderByTime(elapsedTime), false), entitypatch.getEventListener());
			}
		}
	}

