public void aiStep() {
        super.aiStep();
        if (this.isSitting() && this.getNavigation().isDone()) {
            this.getNavigation().stop();
        }
        boolean swim = this.isInWater();
        this.prevSwimProgress = SwimProgress;
        this.prevSitProgress = sitProgress;
        if(SwimProgress < 5F && swim){
            SwimProgress++;
        }
        if(SwimProgress > 0 && !swim){
            SwimProgress--;
        }
        if (this.isSitting() && sitProgress < 5) {
            this.sitProgress ++;
        }
        if (!this.isSitting() && sitProgress > 0) {
            this.sitProgress --;
        }

        if (this.isInWater() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!this.isInWater() && !this.isLandNavigator) {
            switchNavigator(true);
        }

        if (blast_cooldown > 0) {
            blast_cooldown--;
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
        if (this.getAnimation() == BABY_LEVIATHAN_BITE) {
            if (this.getAnimationTick() == 7) {
                this.playSound(ModSounds.LEVIATHAN_BITE.get(), 0.5f, 2.0f);
            }
            if (this.getAnimationTick() == 9) {
                biteattack(1.5f, 0.5, 0.5, 0.5);
            }
        }
    }

@Override
    public void aiStep() {
        super.aiStep();
        setFlying(true);
        boolean flying = this.isFlying() && !this.onGround;
        setTicksAlive(getTicksAlive() + 1);
        if (flying) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.08D, 0));
            if (this.moveControl.getWantedY() > this.getY()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.08D, 0));
            }
        }
        if (this.onGround) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2D, 0));
        }
        if (this.getTarget() != null) {
            this.moveControl.setWantedPosition(this.getTarget().getX(), this.getTarget().getBoundingBox().minY, this.getTarget().getZ(), 1.0F);
            if (this.getAttackBounds().intersects(this.getTarget().getBoundingBox())) {
                this.setAnimation(random.nextBoolean() ? ANIMATION_BITE : ANIMATION_STING);
            }
        }
        if (this.getTicksAlive() > 1800) {
            this.kill();
        }
        if (this.getAnimation() == ANIMATION_BITE && this.getTarget() != null && this.getAnimationTick() == 6) {
            this.playBiteSound();
            double dist = this.distanceToSqr(this.getTarget());
            if (dist < attackDistance()) {
                this.getTarget().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.getAnimation() == ANIMATION_STING && this.getTarget() != null && this.getAnimationTick() == 6) {
            this.playStingSound();
            double dist = this.distanceToSqr(this.getTarget());
            if (dist < attackDistance()) {
                this.getTarget().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue() * 2));
                // After calling hurt the target can become null due to forge hooks
                if (this.getTarget() != null)
                    this.getTarget().addEffect(new MobEffectInstance(MobEffects.POISON, 70, 1));
            }
        }
    }

@Override
    public void updateTask() {
        int tick = this.entity.getAnimationTick();

        if (this.animation == EntityAnimation.PREPARE_LEAP && tick < this.prevTick) {
            this.animation = EntityAnimation.LEAP;

            this.entity.playSound(this.entity.getSoundForAnimation(EntityAnimation.ATTACKING.get()), this.entity.getSoundVolume(), this.entity.getSoundPitch());

            double targetSpeedX = this.target.posX - (!this.ticked ? this.target.prevPosX : this.targetPrevPosX);
            double targetSpeedZ = this.target.posZ - (!this.ticked ? this.target.prevPosZ : this.targetPrevPosZ);

            double length = this.entity.width * 6.0F;

            double destX = this.target.posX + targetSpeedX * length;
            double destZ = this.target.posZ + targetSpeedZ * length;

            double delta = Math.sqrt((destX - this.entity.posX) * (destX - this.entity.posX) + (destZ - this.entity.posZ) * (destZ - this.entity.posZ));
            double angle = Math.atan2(destZ - this.entity.posZ, destX - this.entity.posX);

            this.entity.motionX = delta / length * Math.cos(angle);
            this.entity.motionZ = (delta / length * Math.sin(angle));
            this.entity.motionY = Math.min(0.3, Math.max(0, (this.target.posY - this.entity.posY) * 0.1)) + 0.6;
        } else if (this.animation == EntityAnimation.LEAP && this.entity.motionY < 0) {
            this.animation = EntityAnimation.LEAP_LAND;
        } else if (this.animation == EntityAnimation.LEAP_LAND && (this.entity.onGround || this.entity.isSwimming())) {
            this.animation = EntityAnimation.IDLE;

            if (this.entity.getEntityBoundingBox() != null && this.target.getEntityBoundingBox() != null && this.entity.getEntityBoundingBox().intersects(this.target.getEntityBoundingBox().expand(2.0, 2.0, 2.0))) {
                this.entity.attackEntityAsMob(this.target);
            }
        }

        this.targetPrevPosX = this.target.posX;
        this.targetPrevPosZ = this.target.posZ;
        this.ticked = true;

        if (this.entity.getAnimation() != this.animation.get()) {
            this.entity.setAnimation(this.animation.get());
            this.entity.setAnimationTick(this.prevTick + 1);
        }

        this.prevTick = tick;
    }

public void tick() {
        if (peppermintCooldown > 0) {
            peppermintCooldown--;
        }
        if (hexCooldown > 0) {
            hexCooldown--;
        }
        if (potionCooldown > 0) {
            potionCooldown--;
        }
        if (checkReachCooldown > 0) {
            checkReachCooldown--;
        }
        LivingEntity target = licowitch.getTarget();
        if(duration > 200 && checkReachCooldown == 0 && target != null){
            checkReachCooldown = 100 + licowitch.getRandom().nextInt(40);
            if(licowitch.canTeleport() && !licowitch.canReach(target.blockPosition())){
                licowitch.setTeleportingToPos(Vec3.atBottomCenterOf(target.blockPosition()));
                return;
            }
        }
        if (target != null && target.isAlive() && licowitch.getTeleportingToPos() == null) {
            double distance = licowitch.distanceTo(target);
            double distanceXZ = Mth.sqrt((float) licowitch.distanceToSqr(target.getX(), licowitch.getY(), target.getZ()));
            double attackDistance = licowitch.getBbWidth() + target.getBbWidth() + 5;
            licowitch.lookAt(target, 30.0F, 30.0F);
            if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT || enqueuedAttackType == 0 && distance < attackDistance - 1 || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && distanceXZ < 6.0F) {
                licowitch.getMoveControl().strafe(-4, 0.0F);
                licowitch.getNavigation().stop();
            } else if (distance > attackDistance || !this.licowitch.hasLineOfSight(target)) {
                this.licowitch.getNavigation().moveTo(target, 1.0D);
            }
            if (this.licowitch.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                if (enqueuedAttackType == 0) {
                    if (this.licowitch.hasLineOfSight(target)) {
                        if (peppermintCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 1;
                            peppermintCooldown = 80;
                        } else if (hexCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 2;
                            hexCooldown = 200;
                        } else if (potionCooldown <= 0 && distance < 10.0D && !target.hasEffect(MobEffects.HUNGER)) {
                            enqueuedAttackType = 3;
                            licowitch.updateHeldItems = false;
                            licowitch.setItemInHand(InteractionHand.MAIN_HAND, LicowitchEntity.hungerPotion.copy());
                            potionCooldown = 100;
                        }
                    }
                } else {
                    if (enqueuedAttackType == 1 && distance < 10.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_0);
                    }
                    if ((enqueuedAttackType == 2 || enqueuedAttackType == 4) && distance < 7.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_1);
                    }
                    if (enqueuedAttackType == 3 && distance < 10.0D) {
                        this.licowitch.setAnimation(licowitch.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                    }
                }
            }
            if (enqueuedAttackType == 1 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0 && licowitch.getAnimationTick() == 18) {
                peppermintAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 2 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && licowitch.getAnimationTick() == 36) {
                hexAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 3 && (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && licowitch.getAnimationTick() == 6) {
                potionAttack(target);
                licowitch.updateHeldItems = true;
                enqueuedAttackType = 0;
            }
        }
        duration++;
    }

