public void run(Listener listener) {
        if (this.listener != null) {
            throw new IllegalStateException("already running!");
        }

        this.listener = listener;

        // Off thread chunk scanning to skip already generated chunks
        CompletableFuture.runAsync(this::tryEnqueueTasks, Util.backgroundExecutor());
    }

private void registerPhaseContextProvider(final PhaseContext<?> context) {
        Objects.requireNonNull(context.state.getFrameModifier(), "Consumer");
        // Reset our cached objects
        this.pendingProviders.compareAndSet(false, true); //I Reset the cache
        this.cached_cause = null; // Reset the cache
        this.cached_ctx = null; // Reset the cache
        // Since we cannot rely on the PhaseStack being tied to this stack of providers,
        // we have to make the tuple to tie the phase context to provide the consumer.
        this.phaseContextProviders.push(context);
    }

@Override
    protected void addTask(final SpongeScheduledTask task) {
        this.lock.lock();
        try {
            super.addTask(task);
            this.condition.signalAll();
        } finally {
            this.lock.unlock();
        }
    }

@Redirect(method = {
        "exceptionCaught",
        "channelRead0(Lio/netty/channel/ChannelHandlerContext;Lnet/minecraft/network/protocol/Packet;)V",
        "flushQueue",
        "handleDisconnection" },
        at = @At(value = "INVOKE", target = "Lio/netty/channel/Channel;isOpen()Z"))
    private boolean impl$onIsOpen(final Channel instance) {
        //Use isConnected instead of isOpen because it might return true while isConnected is false
        return this.shadow$isConnected();
    }

@WrapMethod(method = "doRunTask(Lnet/minecraft/server/TickTask;)V")
    private void tracker$wrapAndPerformContextSwitch(final TickTask task, final Operation<Void> original) {
        try (final PhaseContext<@NonNull ?> context = PluginPhase.State.DELAYED_TASK.createPhaseContext(PhaseTracker.SERVER)
            .source(task)
            .setDelayedContextPopulator(((TickTaskBridge) task).bridge$getFrameModifier().orElse(null))
        ) {
            context.buildAndSwitch();
            original.call(task);
        }
    }

void handleClientAck(Acknowledge msg, CustomPayloadEvent.Context ctx) {
        ctx.setPacketHandled(true);
        var consumer = this.pendingAcknowledgments.remove(msg.token());
        if (consumer != null) {
            LOGGER.debug(MARKER, "Received acknowledgement {} from client", msg.token());
            consumer.accept(msg, ctx);
        } else {
            LOGGER.error(MARKER, "Received unknown acknowledgement {} from client", msg.token());
            ctx.getConnection().disconnect(Component.literal("Illegal Acknowledge packet received, unknown token: " + Integer.toHexString(msg.token())));
        }
    }

private <T> CompletableFuture<T> asyncFailableFuture(Callable<T> call, Executor exec) {
        final CompletableFuture<T> ret = new CompletableFuture<>();
        exec.execute(() -> {
            try {
                ret.complete(call.call());
            } catch (Throwable e) {
                ret.completeExceptionally(e);
            }
        });
        return ret;
    }

@Inject(method = "handleDisconnection", at = @At("RETURN"))
    private void impl$onDisconnected(final CallbackInfo ci) {
        if (!this.disconnectionHandled) {
            //Vanilla has race condition here where this might be called
            //while the channel is still open
            return;
        }
        this.impl$disconnected = true;
        this.impl$engineConnection.disconnected();
        this.impl$closePendingActions();
    }

@Inject(method = "wrapRunnable(Ljava/lang/Runnable;)Lnet/minecraft/server/TickTask;", at = @At("RETURN"))
    private void tracker$associatePhaseContextWithWrappedTask(final Runnable runnable, final CallbackInfoReturnable<TickTask> cir) {
        final TickTask returnValue = cir.getReturnValue();
        if (!PhaseTracker.SERVER.onSidedThread()) {
            final PhaseContext<@NonNull ?> phaseContext = PhaseTracker.getInstance().getPhaseContext();
            if (phaseContext.isEmpty()) {
