protected void hurtCollidingEntities(LivingEntityPatch<?> entitypatch, float prevElapsedTime, float elapsedTime, EntityState prevState, EntityState state, Phase phase) {
		LivingEntity entity = entitypatch.getOriginal();
		float prevPoseTime = prevState.attacking() ? prevElapsedTime : phase.preDelay;
		float poseTime = state.attacking() ? elapsedTime : phase.contact;
		List<Entity> list = this.getPhaseByTime(elapsedTime).getCollidingEntities(entitypatch, this, prevPoseTime, poseTime, this.getPlaySpeed(entitypatch, this));

		if (!list.isEmpty()) {
			HitEntityList hitEntities = new HitEntityList(entitypatch, list, phase.getProperty(AttackPhaseProperty.HIT_PRIORITY).orElse(HitEntityList.Priority.DISTANCE));
			int maxStrikes = this.getMaxStrikes(entitypatch, phase);

			while (entitypatch.getCurrentlyActuallyHitEntities().size() < maxStrikes && hitEntities.next()) {
				Entity target = hitEntities.getEntity();
				LivingEntity trueEntity = this.getTrueEntity(target);

				if (trueEntity != null && trueEntity.isAlive() && !entitypatch.getCurrentlyAttackTriedEntities().contains(trueEntity) && !entitypatch.isTargetInvulnerable(target)) {
					if (target instanceof LivingEntity || target instanceof PartEntity) {
						AABB aabb = target.getBoundingBox();

						if (MathUtils.canBeSeen(target, entity, target.position().distanceTo(entity.getEyePosition()) + aabb.getCenter().distanceTo(new Vec3(aabb.maxX, aabb.maxY, aabb.maxZ)))) {
							EpicFightDamageSource damagesource = this.getEpicFightDamageSource(entitypatch, target, phase);
							int prevInvulTime = target.invulnerableTime;
							target.invulnerableTime = 0;

							AttackResult attackResult = entitypatch.attack(damagesource, target, phase.effectiveHand(entitypatch));
							target.invulnerableTime = prevInvulTime;

							if (attackResult.resultType.dealtDamage()) {
                                SoundEvent hitSound = this.getHitSound(entitypatch, phase);

                                if (hitSound != null) {
								    target.level().playSound(null, target.getX(), target.getY(), target.getZ(), hitSound, target.getSoundSource(), 1.0F, 1.0F);
                                }

								this.spawnHitParticle((ServerLevel)target.level(), entitypatch, target, phase);
							}

							entitypatch.getCurrentlyAttackTriedEntities().add(trueEntity);

							if (attackResult.resultType.shouldCount()) {
								entitypatch.getCurrentlyActuallyHitEntities().add(trueEntity);
							}
						}
					}
				}
			}
		}
	}

@Override
    protected void onImpact(RayTraceResult result) {
        if (!this.world.isRemote) {
            AxisAlignedBB hitBB = this.getEntityBoundingBox().grow(4.0D, 2.0D, 4.0D);
            List<EntityLivingBase> hitEntities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, hitBB);
            if (!hitEntities.isEmpty()) {
                Iterator<EntityLivingBase> hitEntitiesIT = hitEntities.iterator();
                while (hitEntitiesIT.hasNext()) {
                    EntityLivingBase affectedEntity = hitEntitiesIT.next();
                    double entityDst = this.getDistanceSq(affectedEntity);
                    if (entityDst < 16.0D) {
                        double modifier = 1.0D - Math.sqrt(entityDst) / 4.0D;
                        if (affectedEntity == result.entityHit) {
                            modifier = 1.0D;
                        }
                        PotionEffect effect = ItemRegistry.ELIXIR.createPotionEffect(getElixirStack(), modifier);
                        SplashPotionEvent event = new SplashPotionEvent(this, affectedEntity, effect, effect.getPotion().isInstant());
                        MinecraftForge.EVENT_BUS.post(event);
                        if(!event.isCanceled()) {
                        	affectedEntity.addPotionEffect(effect);
                        }
                    }
                }
            }
            this.world.playEvent(2002, new BlockPos(this), ItemRegistry.ELIXIR.getColorMultiplier(getElixirStack(), 0));
            this.entityDropItem(new ItemStack(ItemRegistry.ELIXIR.getDentrothystType(getElixirStack()) == EnumDentrothyst.GREEN ? ItemRegistry.DENTROTHYST_SHARD_GREEN : ItemRegistry.DENTROTHYST_SHARD_ORANGE,
            		this.world.rand.nextInt(2) + 2), this.height / 2);
            if(this.world.rand.nextInt(2) == 0) this.entityDropItem(EnumItemMisc.RUBBER_BALL.create(1), this.height / 2);
            this.setDead();
        }
    }

@Override
    protected void onHitEntity(EntityHitResult hitResult) {
        Entity hit = hitResult.getEntity();
        if (properties().damageMultiplier() <= 0f) {
            if (!level().isClientSide() && hit instanceof LivingEntity target) {
                ItemStack arrow = getPickupItem();
                if (arrow.getItem() instanceof IVampirismQuarrel<?> quarrel) {
                    quarrel.onHitEntity(arrow, target, this, getOwner());
                }
            }
            return;
        }

        if (this.ignoreHurtTimer && !level().isClientSide() && hit instanceof LivingEntity living && living.getData(ModAttachments.QUARREL_HURT_BYPASS).registerHit(living.level().getGameTime())) {
            living.invulnerableTime = 0;
        }

        float knockbackFactor = properties().knockbackMultiplier();
        Vec3 preHitVelocity = knockbackFactor != 1f && hit instanceof LivingEntity ? hit.getDeltaMovement() : null;

        double ballistaScale = ballistaDamageScale();
        if (ballistaScale > 1) {
            double launchDamage = launchBaseDamage(properties());
            super.setBaseDamage(launchDamage * ballistaScale);
            super.onHitEntity(hitResult);
            super.setBaseDamage(launchDamage);
        } else {
            super.onHitEntity(hitResult);
        }

        if (preHitVelocity != null && hit.isAlive()) {
            Vec3 imparted = hit.getDeltaMovement().subtract(preHitVelocity);
            hit.setDeltaMovement(preHitVelocity.add(imparted.scale(knockbackFactor)));
            hit.hurtMarked = true; // resync the corrected velocity to clients
        }
    }

public boolean hurt(DamageSource p_31579_, float p_31580_) {
        if (!this.level.isClientSide && !this.isRemoved()) {
            if (p_31579_.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                this.kill();
                return false;
            } else if (!this.isInvulnerableTo(p_31579_) && !this.isInvisible() && !this.isMarker()) {
                if (p_31579_.is(DamageTypeTags.IS_EXPLOSION)) {
                    this.brokenByAnything(p_31579_);
                    this.kill();
                    return false;
                } else {
                    boolean flag = p_31579_.getDirectEntity() instanceof AbstractArrow;
                    boolean flag1 = flag && ((AbstractArrow)p_31579_.getDirectEntity()).getPierceLevel() > 0;
                    boolean flag2 = "player".equals(p_31579_.getMsgId());
                    if (!flag2 && !flag) {
                        return false;
                    } else if (p_31579_.getEntity() instanceof Player && !((Player)p_31579_.getEntity()).getAbilities().mayBuild) {
                        return false;
                    } else if (p_31579_.isCreativePlayer()) {
                        this.playBrokenSound();
                        this.showBreakingParticles();
                        this.kill();
                        return flag1;
                    } else {
                        long i = this.level.getGameTime();
                        if (i - this.lastHit > 5L && !flag) {
                            this.level.broadcastEntityEvent(this, (byte)32);
                            this.gameEvent(GameEvent.ENTITY_DAMAGE, p_31579_.getEntity());
                            this.lastHit = i;
                        } else {
                            this.brokenByPlayer(p_31579_);
                            this.showBreakingParticles();
                            this.kill();
                        }

                        return true;
                    }
                }
            } else {
                return false;
            }
        } else {
            return false;
        }
    }

