                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + livingEntity.getRandom().nextInt(2))));
                this.playSound(ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (livingEntity.level instanceof ServerLevel serverLevel){
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.PACKED_ICE.defaultBlockState()), livingEntity);
                }
                this.discard();
            }

        }
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){

				float damage = Spells.iceball.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FROST).setProjectile(),
						damage);

				if(entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.FROST, entityHit)){
					((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.iceball.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.iceball.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}

			}else{

				BlockPos pos = rayTrace.getBlockPos();

				if(rayTrace.sideHit == EnumFacing.UP && !world.isRemote && world.isSideSolid(pos, EnumFacing.UP)
						&& BlockUtils.canBlockBeReplaced(world, pos.up()) && BlockUtils.canPlaceBlock(thrower, world, pos)){
					world.setBlockState(pos.up(), Blocks.SNOW_LAYER.getDefaultState());
				}
			}

			this.playSound(WizardrySounds.ENTITY_ICEBALL_HIT, 2, 0.8f + rand.nextFloat() * 0.3f);

			this.setDead();
		}
	}

@Override
    public boolean hurt(DamageSource source, float amount) {
        if (getSynchedData(ARMOUR) > 0 && !level().isClientSide && !DamageUtil.isEnvironmentalDamage(source)) {
            float armourDamage = amount;

            if (source.is(DamageTypeTags.IS_PROJECTILE) && !DamageUtil.isMagicDamage(source) && !source.is(AoADamageTypes.HEAVY_GUN))
                armourDamage *= 0.1f;

            if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) {
                if (DamageUtil.isMeleeDamage(source) && source.getDirectEntity() instanceof LivingEntity attacker) {
                    ItemStack weapon = attacker.getMainHandItem();

                    if (weapon.canPerformAction(ItemAbilities.PICKAXE_DIG)) {
                        armourDamage *= 1 + (weapon.getDestroySpeed(Blocks.STONE.defaultBlockState()) * 0.075f) + (float)attacker.getAttributeValue(Attributes.MINING_EFFICIENCY) * 0.04f;
                    }
                    else {
                        armourDamage *= 0.25f;
                    }
                }
                else if (source.is(DamageTypeTags.IS_EXPLOSION)) {
                    armourDamage *= 1.1f;
                }

                if (IntegrationManager.isTESActive())
                    TESIntegration.sendParticle(this, armourDamage, 0xFFAAAAAA);

                ParticleBuilder.forRandomPosInEntity(ParticleTypes.CRIT, this)
                        .spawnNTimes(50)
                        .sendToAllPlayersTrackingEntity(this);

                updateArmour(getSynchedData(ARMOUR) - armourDamage);
            }
        }

        return super.hurt(source, amount);
    }

