@Override
	protected boolean effectOnDamage(DamageSource src, MutableFloat amount, Player player, ItemStack stack) {
		if (!src.is(DamageTypeTags.WITCH_RESISTANT_TO)) {
			amount.setValue(amount.getValue() / 2);

			if (src.getEntity() != null) {
				src.getEntity().hurt(player.damageSources().indirectMagic(player, player), amount.getValue());
			}

			if (amount.getValue() > player.getHealth()) {
				amount.setValue(player.getHealth() - 1);
			}

			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.holyCloak, SoundSource.PLAYERS, 1F, 1F);
			for (int i = 0; i < 30; i++) {
				double x = player.getX() + Math.random() * player.getBbWidth() * 2 - player.getBbWidth();
				double y = player.getY() + Math.random() * player.getBbHeight();
				double z = player.getZ() + Math.random() * player.getBbWidth() * 2 - player.getBbWidth();
				boolean green = Math.random() > 0.5;
				float g = green ? 1F : 0.3F;
				float b = green ? 0.3F : 1F;
				SparkleParticleData data = SparkleParticleData.sparkle(0.8F + (float) Math.random() * 0.4F, 0.3F, g, b, 3);
				player.level().addParticle(data, x, y, z, 0, 0, 0);
			}
			return true;
		}

		return false;
	}

@Inject(method = "damage", at = @At("HEAD"), cancellable = true)
	private void damage(DamageSource source, float amount, CallbackInfoReturnable<Boolean> callbackInfo) {
		if (!getWorld().isClient) {
			Entity directSource = source.getSource();
			if (hasStatusEffect(BWStatusEffects.DEFLECTION) && directSource != null && directSource.getType().isIn(EntityTypeTags.ARROWS)) {
				int amplifier = getStatusEffect(BWStatusEffects.DEFLECTION).getAmplifier() + 1;
				Vec3d velocity = directSource.getVelocity();
				directSource.setVelocity(velocity.getX() * 2 * amplifier, velocity.getY() * 2 * amplifier, velocity.getZ() * 2 * amplifier);
				callbackInfo.setReturnValue(false);
			} else if (amount > 0 && hurtTime == 0) {
				if (!hasStatusEffect(StatusEffects.STRENGTH) && !hasStatusEffect(StatusEffects.REGENERATION) && !hasStatusEffect(StatusEffects.RESISTANCE) && directSource instanceof LivingEntity livingSource && livingSource.hasStatusEffect(BWStatusEffects.LEECHING)) {
					livingSource.heal(amount * (livingSource.getStatusEffect(BWStatusEffects.LEECHING).getAmplifier() + 1) / 8);
				}
				if (directSource != null && hasStatusEffect(BWStatusEffects.THORNS) && source.isOf(DamageTypes.THORNS)) {
					directSource.damage(getWorld().getDamageSources().thorns(directSource), 2 * (getStatusEffect(BWStatusEffects.THORNS).getAmplifier() + 1));
				}
				if (hasStatusEffect(BWStatusEffects.VOLATILITY) && !source.isIn(DamageTypeTags.IS_EXPLOSION)) {
					for (LivingEntity entity : getWorld().getEntitiesByClass(LivingEntity.class, getBoundingBox().expand(3), foundEntity -> foundEntity.isAlive() && !foundEntity.getUuid().equals(getUuid()))) {
						entity.damage(getWorld().getDamageSources().explosion(((LivingEntity) (Object) this), ((LivingEntity) (Object) this)), 4 * (getStatusEffect(BWStatusEffects.VOLATILITY).getAmplifier() + 1));
					}
					getWorld().playSound(null, getBlockPos(), SoundEvents.ENTITY_GENERIC_EXPLODE, SoundCategory.NEUTRAL, 1, 1);
					PlayerLookup.tracking(this).forEach(trackingPlayer -> SpawnExplosionParticlesPacket.send(trackingPlayer, this));
					if (((Object) this) instanceof ServerPlayerEntity player) {
						SpawnExplosionParticlesPacket.send(player, this);
					}
					removeStatusEffect(BWStatusEffects.VOLATILITY);
				}
			}
		}
	}

public void chain(LivingEntity pTarget, LivingEntity pAttacker) {
            double range = 6;
            Level level = pAttacker.level;
            float oDamage = (float) pAttacker.getAttributeValue(Attributes.ATTACK_DAMAGE);

            List<Entity> harmed = new ArrayList<>();
            Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && !harmed.contains(livingEntity) && MobUtil.canAttack(CrusherServant.this, livingEntity);
            LivingEntity prevTarget = pTarget;

            float damage = level.isThundering() ? oDamage : oDamage / 2.0F;

            for (int i = 0; i < 4; i++) {
                AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
                List<Entity> entities = level.getEntities(prevTarget, aabb, selector);
                if (!entities.isEmpty()) {
                    LivingEntity target = (LivingEntity) entities.get(level.getRandom().nextInt(entities.size()));
                    if (target.hurt(ModDamageSource.directShock(pAttacker), damage)) {
                        if (prevTarget != target) {
                            Vec3 vec3 = prevTarget.getEyePosition();
                            Vec3 vec31 = target.getEyePosition();
                            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, 8));
                        }
                    }

                    harmed.add(target);
                    prevTarget = target;
                    damage--;
                }
            }
        }

