@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        Vec3 vec3 = caster.getEyePosition();
        LivingEntity target = this.lockedTarget != null && this.lockedTarget.isAlive() ? this.lockedTarget : this.getTarget(caster);
        this.lockedTarget = null;
        if (target != null){
            ColorUtil colorUtil = new ColorUtil(0xd91516);
            Vec3 vec31 = new Vec3(target.getX(), target.getY() + target.getBbHeight() / 2, target.getZ());
            DamageSource damageSource = ModDamageSource.deathCurse(caster);
            float damage = target.getHealth();
            float casterDamage = damage * SpellConfig.KillingFeedback.get().floatValue();
            if (caster.getHealth() - MobUtil.hurtCalculation(caster, damageSource, casterDamage) <= 0.0F && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(caster)){
                damage = caster.getHealth() - 1;
                casterDamage = caster.getHealth() - 1;
            }
            if (caster.hurt(damageSource, casterDamage) || !EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(caster)) {
                if (target.hurt(damageSource, damage)) {
                    for (int i = 0; i < 8; ++i) {
                        Vec3 vector3d = new Vec3(target.getX(), target.getEyeY(), target.getZ());
                        Vec3 vector3d1 = vector3d.offsetRandom(target.getRandom(), 8.0F);
                        worldIn.sendParticles(new GatherTrailParticleOption(colorUtil, vector3d1), vector3d.x, vector3d.y, vector3d.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                        ServerParticleUtil.windParticle(worldIn, colorUtil, 1.0F, 0.0F, target.getId(), target.position());
                    }
                    ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                    this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get(), 3.0F, 0.75F);
                    this.playSound(worldIn, caster, SoundEvents.LIGHTNING_BOLT_IMPACT, 3.0F, 0.75F);
                }
            }
        }
    }

@Override
	protected void tick(ServerLevel level, Yak yak, long gameTime) {
		Brain<?> brain = yak.getBrain();
		LivingEntity attackTarget = brain.getMemory(MemoryModuleType.ATTACK_TARGET).orElse(null);

		List<LivingEntity> list = level.getNearbyEntities(LivingEntity.class, TargetingConditions.forCombat().selector(entity -> Objects.equals(entity, attackTarget)), yak, yak.getBoundingBox());

		if (list.isEmpty()) {
			Optional<WalkTarget> destination = brain.getMemory(MemoryModuleType.WALK_TARGET);
			Optional<Vec3> ramTarget = brain.getMemory(MemoryModuleType.RAM_TARGET);
			if (destination.isEmpty() || ramTarget.isEmpty() || destination.get().getTarget().currentPosition().closerThan(ramTarget.get(), 0.25D)) {
				this.finishRam(level, yak);
			}
			return;
		}

		LivingEntity target = list.get(0);
		target.hurt(level.damageSources().mobAttack(yak), (float) yak.getAttributeValue(Attributes.ATTACK_DAMAGE));

		int speedFactor = yak.hasEffect(MobEffects.MOVEMENT_SPEED) ? yak.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier() + 1 : 0;
		int slownessFactor = yak.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) ? yak.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier() + 1 : 0;
		float effectSpeed = 0.25F * (speedFactor - slownessFactor);

		float speedForce = Mth.clamp(yak.getSpeed() * RAM_SPEED_FORCE_FACTOR, 0.2F, 3.0F) + effectSpeed;
		float knockbackForce = target.isDamageSourceBlocked(level.damageSources().mobAttack(yak)) ? 0.5F : 1.0F;

		target.knockback((knockbackForce * speedForce) * this.getKnockbackForce.applyAsDouble(yak), this.ramDirection.x(), this.ramDirection.z());
		this.finishRam(level, yak);
		level.playSound(null, yak, this.getImpactSound.apply(yak), SoundSource.NEUTRAL, 1.0F, 1.0F);
	}

