@Override
	public ItemStack finishUsing(ItemStack stack, World world, LivingEntity user) {
		if (user instanceof PlayerEntity player) {
			if (!world.isClient && BewitchmentAPI.drainMagic(player, 2, false)) {
				PotionEntity potion = new PotionEntity(world, user);
				List<StatusEffectInstance> effects = PotionUtil.getCustomPotionEffects(stack);
				ItemStack potionStack = PotionUtil.setCustomPotionEffects(new ItemStack(Items.SPLASH_POTION), effects);
				potionStack.getOrCreateNbt().putInt("CustomPotionColor", PotionUtil.getColor(effects));
				if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
					potionStack.getOrCreateNbt().putUuid("PolymorphUUID", stack.getOrCreateNbt().getUuid("PolymorphUUID"));
					potionStack.getOrCreateNbt().putString("PolymorphName", stack.getOrCreateNbt().getString("PolymorphName"));
				}
				potion.setItem(potionStack);
				potion.setVelocity(user, user.getPitch(), user.getYaw(), -20, 0.5f, 1);
				world.spawnEntity(potion);
				world.playSound(null, user.getBlockPos(), SoundEvents.ENTITY_SPLASH_POTION_THROW, SoundCategory.PLAYERS, 1, 1);
				if (!player.isCreative()) {
					stack.getOrCreateNbt().putInt("PotionUses", stack.getOrCreateNbt().getInt("PotionUses") - 1);
					if (stack.getOrCreateNbt().getInt("PotionUses") <= 0) {
						if (stack.getOrCreateNbt().contains("PolymorphUUID")) {
							potionStack.getOrCreateNbt().remove("PolymorphUUID");
							potionStack.getOrCreateNbt().remove("PolymorphName");
						}
						stack.getOrCreateNbt().put("CustomPotionEffects", new NbtList());
					}

					stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(user.getActiveHand()));
				}
			}
		}
		return stack;
	}

public static void warlockUse(Level level, Player player, ItemStack itemStack){
        if (level instanceof ServerLevel serverLevel) {
            Wartling wartling = new Wartling(ModEntityType.WARTLING.get(), level);
            wartling.setTrueOwner(player);
            wartling.setLimitedLife(MathHelper.secondsToTicks(9));
            wartling.moveTo(player.blockPosition(), player.getYRot(), player.getXRot());
            player.getActiveEffects().stream().filter(mobEffect -> mobEffect.getEffect().getCategory() == MobEffectCategory.HARMFUL && !mobEffect.getEffect().getCurativeItems().isEmpty()).findFirst().ifPresent(effect -> {
                wartling.setStoredEffect(effect);
                player.removeEffect(effect.getEffect());
            });
            wartling.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(player.blockPosition()), MobSpawnType.MOB_SUMMONED, null, null);
            if (!CuriosFinder.hasCurio(player, itemStack1 -> itemStack1.getItem() instanceof WarlockGarmentItem)) {
                if (player.level.addFreshEntity(wartling)) {
                    player.hurt(player.damageSources().generic(), 2.0F);
                }
            } else {
                player.level.addFreshEntity(wartling);
            }
        }
        if (!player.isSilent()) {
            level.playSound((Player) null, player.getX(), player.getY(), player.getZ(), SoundEvents.SCULK_BLOCK_SPREAD, player.getSoundSource(), 1.0F, 0.8F + level.random.nextFloat() * 0.4F);
        }
        if (!player.getAbilities().instabuild) {
            if (CuriosFinder.hasWarlockRobe(player)) {
                if (level.random.nextFloat() > 0.1F){
                    itemStack.shrink(1);
                }
            } else {
                itemStack.shrink(1);
            }
        }
    }

public void attackMobs(LivingEntity pTarget, Player pPlayer, ItemStack pStack){
        float f = (float)pPlayer.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float f1 = EnchantmentHelper.getDamageBonus(pStack, pTarget.getMobType());
        int j = EnchantmentHelper.getFireAspect(pPlayer);
        double area = 1.75D;
        area += pStack.getEnchantmentLevel(ModEnchantments.RADIUS.get());
        for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area, 0.25D, area))) {
            if (livingentity != pPlayer && livingentity != pTarget && !MobUtil.areAllies(pPlayer, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && livingentity != pPlayer.getVehicle()) {
                livingentity.knockback(0.4F, (double) Mth.sin(pPlayer.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(pPlayer.getYRot() * ((float) Math.PI / 180F))));
                if (livingentity.hurt(pPlayer.damageSources().playerAttack(pPlayer), f + f1)) {
                    if (j > 0) {
                        livingentity.setSecondsOnFire(j * 4);
                    }
                    EnchantmentHelper.doPostHurtEffects(livingentity, pPlayer);
                    EnchantmentHelper.doPostDamageEffects(pPlayer, livingentity);
                }
            }
        }
        for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area * 2.0D, 1.0D, area * 2.0D))) {
            if (livingentity != pPlayer && livingentity != pTarget && !MobUtil.areAllies(pPlayer, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && livingentity != pPlayer.getVehicle()) {
                Vec3 vec3 = livingentity.position().subtract(pTarget.position());
                vec3 = vec3.normalize();
                livingentity.level.playSound((Player) null, livingentity.getX(), livingentity.getY(), livingentity.getZ(), ModSounds.GRAVITY.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
                MobUtil.pull(livingentity, vec3.x, vec3.y, vec3.z);
                if (livingentity.level instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(new TeleportInShockwaveParticleOption(), livingentity.getX(), livingentity.getY() + 0.25F, livingentity.getZ(), 0, 0, 0, 0, 0.5F);
                }
            }
        }

        pPlayer.level.playSound((Player) null, pPlayer.getX(), pPlayer.getY(), pPlayer.getZ(), ModSounds.BONEHEAD_HAMMER_IMPACT.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
    }

private void ChargeGrab(double inflateXZ,double inflateY,  double range, float damage, int shieldbreakticks, boolean maledictio) {
        double yaw = Math.toRadians(this.getYRot() + 90);
        double xExpand = range * Math.cos(yaw);
        double zExpand = range * Math.sin(yaw);
        AABB attackRange = this.getBoundingBox().inflate(inflateXZ,inflateY,inflateXZ).expandTowards(xExpand, 0, zExpand);
        if (!this.level().isClientSide) {
            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, attackRange)) {
                if (!isAlliedTo(entity) && entity != this) {
                    if (this.getPassengers().isEmpty()) {
                        DamageSource damagesource = maledictio ? CMDamageTypes.causeMaledictioDamage(this) : this.damageSources().mobAttack(this);
                        boolean flag = entity.hurt(damagesource, damage);
                        if (entity.isDamageSourceBlocked(damagesource) && entity instanceof Player player && shieldbreakticks > 0) {
                            EntityUtil.disableShield(player, shieldbreakticks);
                        }
                        if (flag) {
                            if (!entity.getType().is(ModTag.IGNIS_CANT_POKE) && entity.isAlive()) {
                                if (entity.isShiftKeyDown()) {
                                    entity.setShiftKeyDown(false);
                                }

                                    entity.startRiding(this, true);
                                    Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> entity), new MessageEntityCamera(entity.getId(), false));

                            }

                        }
                    }

                }
            }
        }
    }

public void boof(float internalStrength, float offensiveStrength, boolean slam) {
		float verticalStrength = 1.0F;

		if (this.isControlledByLocalInstance() && !(this.getControllingPassenger() instanceof Player && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_INFLATE) && this.getBoostPower() > 0)) {
			this.push(-Mth.sin((float) (this.getYRot() * Math.PI / 180.0F)) * ((4 * internalStrength) * (this.random.nextFloat() + 0.1F)) * 0.1F, 1.3F * verticalStrength, Mth.cos((float) (this.getYRot() * Math.PI / 180.0F)) * ((4 * internalStrength) * (this.random.nextFloat() + 0.1F)) * 0.1F);
		}

		if (slam && this.level().isClientSide) {
			for (int i = 0; i < 12; i++) {
				double offsetX = MathUtil.makeNegativeRandomly(this.random.nextFloat() * 0.25F, this.random);
				double offsetZ = MathUtil.makeNegativeRandomly(this.random.nextFloat() * 0.25F, this.random);

				double x = this.getX() + 0.5D + offsetX;
				double y = this.getY() + 0.5D + (this.random.nextFloat() * 0.05F);
				double z = this.getZ() + 0.5D + offsetZ;

				this.level().addParticle(EEParticleTypes.POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((this.random.nextFloat() * 0.3F), this.random) + 0.025F, (this.random.nextFloat() * 0.15F) + 0.1F, MathUtil.makeNegativeRandomly((this.random.nextFloat() * 0.3F), this.random) + 0.025F);
			}
		}

		var rider = this.getControllingPassenger();
		for (Entity entity : this.level().getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(3.5F * Math.max(offensiveStrength / 2.0F, 1.0F)), entity -> entity != this && entity != rider && (entity instanceof ItemEntity || entity instanceof LivingEntity) && !(entity instanceof Player && ((Player) entity).isCreative() && ((Player) entity).getAbilities().flying))) {
			float resistance = this.isResistantToBoof(entity) ? 0.15F : 1.0F;
			float amount = (0.2F * offensiveStrength) * resistance;
			if (offensiveStrength > 2.0F && resistance > 0.15F) {
				entity.hurt(this.level().damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
				entity.hurtMarked = false;
			}
			Vec3 result = entity.position().subtract(this.position());
			entity.push(result.x * amount, (this.random.nextFloat() * 0.75D + 0.25D) * (offensiveStrength * 0.75F), result.z * amount);
		}
	}

public static void slam(BroodEetle broodEetle, RandomSource random, float power) {
		ServerLevel world = (ServerLevel) broodEetle.level();
		double posX = broodEetle.getX();
		double posY = broodEetle.getY();
		double posZ = broodEetle.getZ();
		for (BlockState state : sampleGround(world, broodEetle.blockPosition().below(), random)) {
			world.sendParticles(new BlockParticleOption(EEParticleTypes.FAST_BLOCK.get(), state), posX, posY, posZ, 8, 0.0D, 0.0D, 0.0D, 0.225F);
		}
		float attackDamage = (float) broodEetle.getAttributeValue(Attributes.ATTACK_DAMAGE) * power;
		double knockback = broodEetle.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
		for (LivingEntity livingEntity : world.getEntitiesOfClass(LivingEntity.class, broodEetle.getBoundingBox().inflate(4.5D), entity1 -> entity1 != broodEetle)) {
			float damage;
			if ((int) attackDamage > 0.0F) {
				damage = attackDamage / 2.0F + random.nextInt((int) attackDamage);
			} else {
				damage = attackDamage;
			}

			if (livingEntity instanceof AbstractEetle) {
				damage = 0.0F;
			}

			if (livingEntity.hurt(world.damageSources().mobAttack(broodEetle), damage)) {
				broodEetle.doEnchantDamageEffects(broodEetle, livingEntity);
				double knockbackForce = knockback - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
				float inAirFactor = livingEntity.onGround() ? 1.0F : 0.75F;
				Vec3 horizontalVelocity = new Vec3(livingEntity.getX() - posX, 0.0D, livingEntity.getZ() - posZ).normalize().scale((knockbackForce * (random.nextFloat() * 0.75F + 0.5F)) * inAirFactor * power);
				livingEntity.push(horizontalVelocity.x, knockbackForce * 0.5F * random.nextFloat() * 0.5F * inAirFactor, horizontalVelocity.z);
				livingEntity.hurtMarked = true;
			}
		}
	}

private void onUpdateInAir() {
        this.lifeTime -= 1;

        if (this.lifeTime <= 0) {
            this.discard();
        }
        BlockPos pos =  BlockPos.containing(this.getX(), this.getY() - 1, this.getZ());
        BlockState iblockstate = this.level().getBlockState(pos);
        Entity entity1 = this.getOwner();
        LivingEntity livingonwer = entity1 instanceof LivingEntity ? (LivingEntity)entity1 : null;
        for (LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.5,0.5,0.5))) {
            if (this.getOwner() != null) {
                if (this.tickCount % 5 == 0) {
                    if (livingentity != this.getOwner() && livingentity.onGround() && !this.getOwner().isAlliedTo(livingentity) && livingentity.isAlive()) {
                        if(livingentity.hurt(damageSources().mobProjectile(this, livingonwer), this.getDamage())) {
                            this.strongKnockback(livingentity, 0.5);
                        }


                    }
                }
            }
        }

        if (this.level().isClientSide) {
            for (int i = 0; i < 3; i++) {
                this.level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, iblockstate), this.getX() + this.random.nextFloat() - 0.5D, this.getY() + this.random.nextFloat() - 0.5D, this.getZ() + this.random.nextFloat()
                        - 0.5D, 4.0D * ((double) this.random.nextFloat() - 0.5D), (double) this.random.nextFloat() * 5 + 0.5D,
                        ((double) this.random.nextFloat() - 0.5D) * 4.0D);
            }
            this.level().addParticle(ModParticle.DUST_BLAST.get(), this.getX(), this.getY() + 0.1d, this.getZ(), 0,0,0);
        }
    }

private void onSting(HitResult result) {
		HitResult.Type resultType = result.getType();
		if (resultType == HitResult.Type.ENTITY) {
			EntityHitResult entityResult = (EntityHitResult) result;
			Entity entity = entityResult.getEntity();
			if (entity.hurt(this.level().damageSources().mobProjectile(this, this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue())) {
				this.setInflated(true);
				this.removeFireDirection();
				this.stuckInBlock = false;

				if (!this.getActiveEffects().isEmpty() && entity instanceof LivingEntity) {
					for (MobEffectInstance effects : this.getActiveEffects()) {
						((LivingEntity) entity).addEffect(effects);
					}
					this.removeAllEffects();
				}
			}
		} else {
			BlockHitResult blockraytraceresult = (BlockHitResult) result;
			this.stuckInBlockState = this.level().getBlockState(blockraytraceresult.getBlockPos());
			this.stuckInBlock = true;

			Vec3 end = result.getLocation();
			this.setPos(end.x(), end.y(), end.z());
			this.setDeltaMovement(Vec3.ZERO);

			if (!this.level().isClientSide) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_LAND);
			}

			this.level().playSound(null, this, EESoundEvents.PUFFBUG_LAND.get(), SoundSource.HOSTILE, 0.5F, this.getVoicePitch());
		}
	}

public void lifeSpanDamage(){
        if (this.getTrueOwner() != null
                && this.getTrueOwner().isAlive()
                && !this.getTrueOwner().isDeadOrDying()
                && (this.getStoredEffect() == null || this.getStoredEffect().getEffect().isBeneficial())){
            this.getNavigation().moveTo(this.getTrueOwner(), 1.25F);
            this.setTarget(null);
            ++this.searchTime;
            if (this.getBoundingBox().intersects(this.getTrueOwner().getBoundingBox())){
                this.getTrueOwner().heal(this.getHealth());
                for (MobEffectInstance mobEffectInstance : this.getActiveEffects()){
                    if (mobEffectInstance.getEffect().isBeneficial()){
                        this.getTrueOwner().addEffect(mobEffectInstance);
                    }
                }
                if (this.getStoredEffect() != null && this.getStoredEffect().getEffect().isBeneficial()){
                    this.getTrueOwner().addEffect(this.getStoredEffect());
                }
                this.playSound(SoundEvents.SCULK_BLOCK_SPREAD, 1.0F, 1.0F);
                if (!this.level.isClientSide) {
                    this.level.broadcastEntityEvent(this, (byte) 15);
                }
                this.discard();
            } else if (this.searchTime >= MathHelper.secondsToTicks(5)){
                this.hurt(this.damageSources().starve(), this.getMaxHealth());
            }
        } else {
            this.limitedLifeTicks = 20;
            this.hurt(this.damageSources().starve(), this.getMaxHealth());
        }
    }

@Override public void tick() {
        super.tick();
        //Spawn fish around it randomly
        if(!level().isClientSide() && random.nextInt(500) == 0) {
            double x = getX() + (random.nextDouble() - .5) * 8, y = getY(), z = getZ() + (random.nextDouble() - .5) * 8;
            BlockPos pos = new BlockPos((int) x, (int) y, (int) z);
            BlockState state = level().getBlockState(pos);
            if(state.getFluidState().is(FluidTags.WATER)) {
                List<EntityType<?>> fishEntities = Arrays.asList(EntityType.PUFFERFISH, EntityRegistry.SHARK.get(), EntityRegistry.AEQUOREA.get(), EntityType.GLOW_SQUID);
                EntityType<?> randomFishEntity = fishEntities.get(level().getRandom().nextInt(fishEntities.size()));
                if(level().noCollision(randomFishEntity.getSpawnAABB(x, y, z).deflate(.0625))) randomFishEntity.spawn((ServerLevel) level(), pos, MobSpawnType.REINFORCEMENT);
            } else if(state.isAir() && level().noCollision(EntityRegistry.ALICANTO.get().getSpawnAABB(x, y, z))) EntityRegistry.ALICANTO.get().spawn((ServerLevel) level(), pos, MobSpawnType.REINFORCEMENT);
        }
        //Randomly add negative effects to nearby players
        for(Player player : level().getEntitiesOfClass(Player.class, getBoundingBox().inflate(16D))) if(!player.isSpectator() && !player.isCreative() && player.isAlive() && random.nextInt(500) == 0)
            player.addEffect(getRandomNegativeEffect());
        //Break boats if the whale is nearby
        for(Boat boat : level().getEntitiesOfClass(Boat.class, getBoundingBox().inflate(4D))) boat.hurt(damageSources().generic(), 100F);
        //Break ice
        if(isAlive()) {
            AABB box = getBoundingBox().inflate(1.5);
            BlockPos.betweenClosedStream(
                    new BlockPos((int) box.minX, (int) box.minY, (int) box.minZ),
                    new BlockPos((int) box.maxX, (int) box.maxY, (int) box.maxZ)
            ).forEach((blockPos) -> {
                BlockState state = level().getBlockState(blockPos);
                if(state.is(BlockTags.ICE)) {
                    if(blockPos.getY() == level().getSeaLevel()) level().setBlockAndUpdate(blockPos, Blocks.WATER.defaultBlockState()); // Replace ice with water
                    else level().destroyBlock(blockPos, false); // Break ice block
                    playSound(SoundEvents.GLASS_BREAK, 1, 1);
                }
            });
        }
    }

@Override
    public void render(T blockEntity, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var blockState = blockEntity.getBlockState();
        var pos = blockEntity.getBlockPos();

        var type = blockState.getValue(SoulwovenBannerBlock.BANNER_TYPE);
        var direction = type.direction.getAxis().isVertical() ? type.equals(SoulwovenBannerBlock.BannerType.HANGING_Z) ? Direction.NORTH : Direction.WEST : type.direction;
        float sway = ((float) Math.floorMod((pos.getX() * 7L + pos.getY() * 9L + pos.getZ() * 13L) + blockEntity.getLevel().getGameTime(), 100L) + partialTicks) / 100.0F;
        float swayRotation = (0.01F * Mth.cos((float) (Math.PI * 2) * sway)) * (float) Math.PI;

        poseStack.pushPose();
        poseStack.translate(0.5f, 0.5f, 0.5f);
        poseStack.mulPose(Axis.YN.rotationDegrees(direction.toYRot()));
        poseStack.translate(-0.5f, -0.5f, -0.5f);
        if (type.direction.getAxis().isHorizontal()) {
            poseStack.translate(0, -0.25f, 0.0625f);
            swayRotation -= 0.0125f;
        } else {
            poseStack.translate(0, 0, 0.5f);
            swayRotation = swayRotation - 0.0157f;
        }
        poseStack.translate(0, 1f, 0);
        poseStack.mulPose(Axis.XP.rotation(swayRotation));
        float xStart = 0;
        float xEnd = 1;
        float yStart = -2;
        float yEnd = 0;

        var vertices = new Vector3f[]{new Vector3f(xEnd, yStart, 0), new Vector3f(xStart, yStart, 0), new Vector3f(xStart, yEnd, 0), new Vector3f(xEnd, yEnd, 0)};
        var builder = VFXBuilders.createWorld().setLightLevel(pos);

        renderBanner(blockEntity, poseStack, builder, vertices);
        poseStack.popPose();
    }

@Override
    public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
        var self = livingEntity.getEffect(MobEffectRegistry.IMMOLATE);
        if (DELAYED_INSTANCES.containsKey(self) && !(DELAYED_INSTANCES.get(self) - duration > 4)) {
            return true;
        }
        float explosionRadius = 6;
        var level = livingEntity.level;
        if (level.isClientSide) {
            return true;
        }
        @Nullable Entity attacker = EFFECT_CREDIT.remove(livingEntity);
        double baseDamage = damageFor(attacker);

        var source = new DamageSource(level.damageSources().damageTypes.getHolderOrThrow(ISSDamageTypes.FIRE_MAGIC), attacker);
        var explosionRadiusSqr = explosionRadius * explosionRadius;
        var entities = level.getEntities(null, livingEntity.getBoundingBox().inflate(explosionRadius));
        Vec3 losPoint = Utils.raycastForBlock(level, livingEntity.position(), livingEntity.position().add(0, 1, 0), ClipContext.Fluid.NONE).getLocation();
        for (Entity entity : entities) {
            double distanceSqr = entity.distanceToSqr(livingEntity.position());
            if (distanceSqr < explosionRadiusSqr && entity.canBeHitByProjectile() && !DamageSources.isFriendlyFireBetween(attacker, entity) && Utils.hasLineOfSight(level, losPoint, entity.getBoundingBox().getCenter(), true)) {
                double p = (1 - distanceSqr / explosionRadiusSqr);
                float damage = (float) (baseDamage * p);
                entity.invulnerableTime = 0; // ensure explosion can hit after the damage that procs it
                if (entity.hurt(source, damage) && entity instanceof LivingEntity livingVictim) {
                    var inst = addImmolateStack(livingVictim, attacker);
                    DELAYED_INSTANCES.put(inst, inst.getDuration());
                }
            }
        }
