@Override
  public void tick(BlockState state, ServerWorld world, BlockPos pos, Random rand) {
    if (!hasAtLeastOneArrow(state)) return;

    // search for all arrow entities which are colliding with the target

    VoxelShape voxelShape = state.getCollisionShape(world, pos);
    AxisAlignedBB targetAABB = voxelShape.getBoundingBox();
    AxisAlignedBB targetAABBinWorld = targetAABB.offset(pos);
    List<AbstractArrowEntity> embeddedArrows = world.getEntitiesWithinAABB(AbstractArrowEntity.class, targetAABBinWorld);

    if (embeddedArrows.isEmpty()) {
      BlockState newBlockState = state.with(ARROW_DISTANCE_FROM_CENTRE, NO_ARROW);
      final int FLAGS = SetBlockStateFlag.get(SetBlockStateFlag.BLOCK_UPDATE, SetBlockStateFlag.SEND_TO_CLIENTS);
      world.setBlockState(pos, newBlockState, FLAGS);
      informNeighborsOfPowerChange(newBlockState, world, pos);
    } else {
      world.getPendingBlockTicks().scheduleTick(pos, this, this.tickRate(world));
    }
  }

@ApiStatus.NonExtendable
    default BlockState updateShapeLockable(
            BlockState state,
            LevelReader level,
            ScheduledTickAccess tickAccess,
            BlockPos pos,
            Direction side,
            BlockPos adjPos,
            BlockState adjState,
            RandomSource random,
            UpdateShapeHandler updateShape
    ) {
        if (!state.getValue(FramedProperties.STATE_LOCKED)) {
            return updateShape.handle(state, level, tickAccess, pos, side, adjPos, adjState, random);
        }
        if (getBlockType().supportsWaterLogging() && state.getValue(BlockStateProperties.WATERLOGGED)) {
            tickAccess.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }
        return state;
    }

@SuppressWarnings("unchecked") // Again, we know it must be ok
	private void update(){

		if(this.selectedMinion != null && this.selectedMinion.get() == null) this.selectedMinion = null;

		prevMotionY = player.motionY;

		// This new system removes a lot of repetitive event handler code and inflexible data which had duplicate
		// functions, just for different enchantments.
		if(player.ticksExisted % IMBUEMENT_UPDATE_INTERVAL == 0) updateImbuedItems();
		updateContinuousSpellCasting();

		// Clean up expired recent spells every 60 ticks (1 second)
		if(player.ticksExisted % 60 == 0) {
			long currentTime = player.world.getTotalWorldTime();
			this.recentSpells.removeIf(entry -> (currentTime - entry.getValue()) >= Wizardry.settings.recentSpellExpiryTime);
		}

		this.spellData.forEach((k, v) -> this.spellData.put(k, k.update(player, v)));
		this.spellData.keySet().removeIf(k -> k.canPurge(player, this.spellData.get(k)));
	}

private void updateImbuedItems(){

		// FIXME: Iterating through the entire inventory each tick is an AWFUL way of doing this, and is super-slow!
		//        Change the imbuement durations map to be ItemStack -> Integer and just decrement them, adding entries
		//		  whenever an item with an imbuement enters the inventory and removing them when the time expires.

		Set<Imbuement> activeImbuements = new HashSet<Imbuement>();

		// For each item in the player's inventory
		for(ItemStack stack : player.inventory.mainInventory){
			updateImbuedItem(stack, activeImbuements);
		}
		for(ItemStack stack : player.inventory.armorInventory){
			updateImbuedItem(stack, activeImbuements);
		}
		for(ItemStack stack : player.inventory.offHandInventory){
			updateImbuedItem(stack, activeImbuements);
		}

		// Removes all imbuements from the map that are no longer active
		this.imbuementDurations.keySet().retainAll(activeImbuements);
	}

