public void updateContinuousSpellCasting(){

		if(this.castCommandSpell != null && this.castCommandSpell.isContinuous){

			if(castCommandTick > castCommandDuration){
				this.stopCastingContinuousSpell();
				return;
			}

			if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Tick(Source.COMMAND, castCommandSpell, player, castCommandModifiers, castCommandTick))){
				this.stopCastingContinuousSpell();
				return;
			}

			if(this.castCommandSpell.cast(player.world, player, EnumHand.MAIN_HAND, castCommandTick, this.castCommandModifiers)
					&& this.castCommandTick == 0){
				// On the first tick casting a continuous spell via commands, SpellCastEvent.Post is fired.
				MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.COMMAND, castCommandSpell, player, castCommandModifiers));
			}

			castCommandTick++;

		}else{
			// Why is this here? Surely castCommandTick will always be 0 if castCommandSpell is null?
			this.castCommandTick = 0;
		}
	}

@Override
    public final TickRateModulation tickingRequest(IGridNode node, int ticksSinceLastCall) {
        // Sometimes between being woken up and actually doing work, the config/redstone mode may have changed
        // put us back to sleep if that was the case
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        }

        if (!canDoBusWork()) {
            return TickRateModulation.IDLE;
        }

        // Reset a potential redstone pulse trigger
        this.pendingPulse = false;

        var hasDoneWork = this.doBusWork(node.getGrid());

        // We may be back to sleep (i.e. in pulse mode)
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        } else {
            return hasDoneWork ? TickRateModulation.FASTER : TickRateModulation.SLOWER;
        }
    }

@Nonnull
	@Override
	public ItemStack insertItem(int slot, @Nonnull ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level.get(), state.tank.getFluid(), stack);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stack))
			return stack;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		int inputAmount = 1;
		if(recipe==null)
			process = new BottlingProcess(stack.copy(), stack.copy(), state);
		else
		{
			ItemStack displayStack = recipe.value().getDisplayStack(stack);
			process = new BottlingProcess(recipe, Utils.createNonNullItemStackListFromItemStack(displayStack), state);
			inputAmount = displayStack.getCount();
		}

		if(processor.addProcessToQueue(process, level.get(), simulate))
			stack.shrink(inputAmount);
		return stack;
	}

@Override
	protected ItemStack insert(ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<R> recipe = getRecipeOnInsert.apply(level.get(), stack);
		if(recipe==null)
			return stack;
		ItemStack displayStack;
		if(!doProcessStacking)
		{
			// if process stacking is not allowed, we need to work with exact input quantities
			displayStack = recipe.value().getDisplayStack(stack);
			displayStack = stack.copyWithCount(displayStack.getCount());
		}
		else
			displayStack = stack.copy();
		if(processor.addProcessToQueue(new MultiblockProcessInWorld<>(
				recipe,
				TRANSFORMATION_POINT,
				Utils.createNonNullItemStackListFromItemStack(displayStack)
		), level.get(), simulate, doProcessStacking))
			stack.shrink(displayStack.getCount());
		return stack;
	}

private void updatePumpQueue(@Nullable FluidType fluidType) {
        if (getLevel() == null) return;

        if (pumpQueue != null && !pumpQueue.queue().isEmpty()) {
            return;
        }

        BlockPos headPos = getBlockPos().below(pumpHeadY);

        BlockPos downPos = headPos.below(1);
        var downBlock = getLevel().getBlockState(downPos);

        if (!(downBlock.getBlock() instanceof LiquidBlock)) {
            pumpQueue = null;
            return;
        }

        if (fluidType != null && downBlock.getFluidState().getFluidType() != fluidType) {
            pumpQueue = null;
            return;
        }

        pumpQueue = buildPumpQueue(getLevel(), headPos, downBlock.getFluidState().getFluidType(), queueSize(), true);
    }

public void update() {
        if (autoOutput.getFluidOutputDirection() != null) {
            cache.exportToNearby(autoOutput.getFluidOutputDirection());
        }

        // do not do anything without enough energy supplied
        if (energyContainer.getEnergyStored() < GTValues.V[getTier()] * 2) {
            return;
        }
        // Try to put 5 times as many in the queue as there are pumps in the cycle
        // In practice only EV tier has more than 1 pump per cycle
        // The queue can contain at most the y-levels at the pump head or just the y-level below, so for many oil veins
        // It will not be the ideal size
        boolean advanced = false;
        if (getOffsetTimer() % (getPumpingCycleLength() * 2L) == 0) {
            advanced = canAdvancePumpHead();
        }
        if (!advanced && getOffsetTimer() % getPumpingCycleLength() == 0) {
            pumpCycle();
        }
        if (getOffsetTimer() % (20 * 60) == 0) {
            forbiddenBlocks.clear();
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (drone != null && !drone.isAlive()) {
            setDrone(null);
        }
        if (drone != null) {
            if (ringSendCooldown > 0) ringSendCooldown--;
            if (!ringSendQueue.isEmpty() && ringSendCooldown <= 0) {
                ringSendCooldown = ringSendQueue.size() > 10 ? 1 : 5;
                Integer color = ringSendQueue.poll();
                NetworkHandler.sendToAllTracking(PacketSpawnRing.create(getBlockPos(), drone, color), this);
            }
            if (!getBlockState().getValue(DroneInterfaceBlock.CONNECTED)) {
                nonNullLevel().setBlockAndUpdate(worldPosition, getBlockState().setValue(DroneInterfaceBlock.CONNECTED, true));
            }
        } else {
            if (getBlockState().getValue(DroneInterfaceBlock.CONNECTED)) {
                NetworkHandler.sendToAllTracking(PacketShowArea.forPos(getBlockPos()), DroneInterfaceBlockEntity.this);
                nonNullLevel().setBlockAndUpdate(worldPosition, getBlockState().setValue(DroneInterfaceBlock.CONNECTED, false));
            }
        }
    }

private void enqueueProcesses(State state, Level level)
	{
		// TODO deduplicate with fermenter
		if(state.energy.getEnergyStored() <= 0||state.processor.getQueueSize() >= state.processor.getMaxQueueSize())
			return;
		final int[] usedInvSlots = new int[NUM_INPUT_SLOTS];
		for(MultiblockProcess<?, ?> process : state.processor.getQueue())
			if(process instanceof MultiblockProcessInMachine)
				for(int i : ((MultiblockProcessInMachine<?>)process).getInputSlots())
					usedInvSlots[i]++;

		Integer[] preferredSlots = new Integer[]{0, 1, 2, 3, 4, 5, 6, 7};
		Arrays.sort(preferredSlots, 0, NUM_INPUT_SLOTS, Comparator.comparingInt(arg0 -> usedInvSlots[arg0]));
		for(int slot : preferredSlots)
		{
			ItemStack stack = state.inventory.getStackInSlot(slot);
			if(stack.getCount() <= usedInvSlots[slot])
				continue;
			stack = stack.copy();
			stack.shrink(usedInvSlots[slot]);
			RecipeHolder<SqueezerRecipe> recipe = SqueezerRecipe.findRecipe(level, stack);
			if(recipe!=null)
				state.processor.addProcessToQueue(new MultiblockProcessInMachine<>(recipe, slot), level, false);
		}
	}

private void mineAndInsertItems(NonNullList<ItemStack> blockDrops, ServerLevel world) {
        // If the block's drops can fit in the inventory, move the previously mined position to the block
        // replace the ore block with cobblestone instead of breaking it to prevent mob spawning
        // remove the ore block's position from the mining queue
        var handler = getCachedItemHandler();
        if (GTTransferUtils.addItemsToItemHandler(handler, true, blockDrops)) {
            GTTransferUtils.addItemsToItemHandler(handler, false, blockDrops);
            var pos = blocksToMine.getFirst();
            world.setBlock(pos, findMiningReplacementBlock(world, pos), 3);
            mineX = pos.getX();
            mineZ = pos.getZ();
            mineY = pos.getY();
            syncDataHolder.markClientSyncFieldDirty("mineX");
            syncDataHolder.markClientSyncFieldDirty("mineY");
            syncDataHolder.markClientSyncFieldDirty("mineZ");
            blocksToMine.removeFirst();
            onMineOperation();

            // if the inventory was previously considered full, mark it as not since an item was able to fit
            isInventoryFull = false;
        } else {
            // the ore block was not able to fit, so the inventory is considered full
            isInventoryFull = true;
        }
    }

private static void removeExpiredMobCharms() {
		int secondsToExpire = 4;
		boolean changed = false;
		lock.lock();
		for (Iterator<Map.Entry<Integer, CharmToDraw>> iterator = charmsToDraw.entrySet().iterator(); iterator.hasNext();) {
			Map.Entry<Integer, CharmToDraw> entry = iterator.next();
			CharmToDraw charmToDraw = entry.getValue();
			float percentToMaxDamage = 1 - (float) charmToDraw.getCharm().getDamageValue() / charmToDraw.getCharm().getMaxDamage();

			int expirationDuration = secondsToExpire * 1000;
			if (percentToMaxDamage < 0.1f) {
				expirationDuration = (int) (expirationDuration + (expirationDuration * 2 * (1 - percentToMaxDamage * 10)));
			}

			if (charmToDraw.time + expirationDuration < System.currentTimeMillis()) {
				iterator.remove();
				changed = true;
			}
		}
		lock.unlock();

		if (changed) {
			updateCharmsPane();
		}
	}

@SubscribeEvent
        public static void onEatFood(LivingEntityUseItemEvent.Finish event)
        {
            ItemStack item = event.getItem();
            if (event.getEntity() instanceof Player player
            && (item.getUseAnimation() == UseAnim.DRINK || item.getUseAnimation() == UseAnim.EAT)
            && !event.getEntity().level().isClientSide)
            {
                // If food item defined in config
                for (FoodData foodData : ConfigSettings.FOOD_TEMPERATURES.get().get(item.getItem()))
                {
                    if (foodData != null && foodData.test(item))
                    {
                        double temperature = foodData.temperature(item, player);
                        int duration = foodData.duration(item, player);
                        Trait modTrait = duration > 0 ? Trait.BASE : Trait.CORE;
                        // Custom class for soul sprouts
                        FoodTempModifier foodModifier = item.getItem() == ModItems.SOUL_SPROUT
                                                        ? new SoulSproutTempModifier(temperature)
                                                        : new FoodTempModifier(temperature);
                        // Store the item ID & duration of the TempModifier
                        foodModifier.getNBT().putString("item", ForgeRegistries.ITEMS.getKey(item.getItem()).toString());
                        foodModifier.getNBT().putInt("duration", duration);
                        // Set duration & tick rate
                        foodModifier.expires(duration).tickRate(duration);
                        // Add the TempModifier
                        Placement placement = Placement.LAST.limitDuplicates(Matcher.EQUALS, foodData.stackLimit(item, player))
                                              .orElse(Placement.of(Mode.REPLACE, Order.FIRST, foodModifier::equals));
                        Temperature.addModifier(player, foodModifier, modTrait, placement);
                        foodData.modifiers().forEach((trait, modifiers) ->
                        {   modifiers.forEach(modifier -> Temperature.addModifier(player, modifier.get(), trait, placement));
                        });
                    }
                }
            }
        }

@Override
  public void onProjectileCollision(World world, BlockState state, BlockRayTraceResult hit, ProjectileEntity projectile) {
    if (world.isRemote) return;  // on client - do nothing
    if (!(projectile instanceof AbstractArrowEntity)) return;  // only for arrows
    if (hit.getType() != RayTraceResult.Type.BLOCK) return;  // just being defensive; this should always be true

    BlockPos blockPos = hit.getPos();
    Direction hitFace = hit.getFace();
    Direction directionOfBack = state.get(DIRECTION_THAT_BACK_IS_POINTING);
    Direction directionOfFront = directionOfBack.getOpposite();
    if (hitFace != directionOfFront) return;          // only count hits on the front face

    // when a new arrow hits, remove all others which are already embedded:
    // search for all arrow entities which are colliding with the target, and remove them.

    VoxelShape voxelShape = state.getCollisionShape(world, hit.getPos());
    AxisAlignedBB targetAABB = voxelShape.getBoundingBox();
    AxisAlignedBB targetAABBinWorld = targetAABB.offset(blockPos);
    List<AbstractArrowEntity> embeddedArrows = world.getEntitiesWithinAABB(AbstractArrowEntity.class, targetAABBinWorld);

    for (AbstractArrowEntity embeddedEntity : embeddedArrows) {
      if (embeddedEntity.getEntityId() != projectile.getEntityId()) {
        embeddedEntity.remove();
      }
    }

    // update our blockstate to reflect which ring the arrow is stuck into.
    int arrowDistanceFromCentre = findArrowDistanceFromCentre(directionOfFront, targetAABBinWorld, hit.getHitVec());
    BlockState newBlockState = state.with(ARROW_DISTANCE_FROM_CENTRE, arrowDistanceFromCentre);
    final int FLAGS = SetBlockStateFlag.get(SetBlockStateFlag.BLOCK_UPDATE, SetBlockStateFlag.SEND_TO_CLIENTS);
    world.setBlockState(blockPos, newBlockState, FLAGS);
    informNeighborsOfPowerChange(newBlockState, world, blockPos);

    // start periodically checking whether the arrow has disappeared or been removed
    world.getPendingBlockTicks().scheduleTick(blockPos, this, this.tickRate(world));
  }

private void onWorldTick(LevelTickEvent.Post event) {
		if (event.getLevel().isClientSide()) {
			return;
		}

		ResourceLocation dimensionKey = event.getLevel().dimension().location();
		boolean runSlownessLogic = Boolean.TRUE.equals(Config.SERVER.nerfsConfig.tooManyBackpacksSlowness.get());
		boolean runDedupeLogic = Boolean.FALSE.equals(Config.SERVER.tickDedupeLogicDisabled.get());
		if ((!runSlownessLogic && !runDedupeLogic) || nextBackpackCheckTime.getOrDefault(dimensionKey, 0L) > event.getLevel().getGameTime()) {
			return;
		}
		nextBackpackCheckTime.put(dimensionKey, event.getLevel().getGameTime() + BACKPACK_CHECK_COOLDOWN);

		Map<UUID, IBackpackWrapper> backpackIds = new HashMap<>();

		event.getLevel().players().forEach(player -> {
			Set<ItemStack> allBackpacks = new HashSet<>();
			PlayerInventoryProvider.get().runOnBackpacks(player, (backpack, handlerName, identifier, slot) -> {
				if (runSlownessLogic) {
					allBackpacks.add(backpack);
				}
				if (runDedupeLogic && LinkedStorageStackLifecycle.classifyEndpoint(backpack) != LinkedStorageEndpointStackState.ENDPOINT) {
					addBackpackIdIfUniqueOrDedupe(backpackIds, BackpackWrapper.fromStack(backpack));
				}
				return false;
			});
			if (runSlownessLogic) {
				int maxNumberOfBackpacks = Config.SERVER.nerfsConfig.maxNumberOfBackpacks.get();
				if (allBackpacks.size() > maxNumberOfBackpacks) {
					int numberOfSlownessLevels = Math.min(10, (int) Math
							.ceil((allBackpacks.size() - maxNumberOfBackpacks) * Config.SERVER.nerfsConfig.slownessLevelsPerAdditionalBackpack.get()));
					Holder<MobEffect> effect = Config.SERVER.nerfsConfig.getEffect();
					player.addEffect(new MobEffectInstance(effect, BACKPACK_CHECK_COOLDOWN * 2, numberOfSlownessLevels - 1, false, false));
				}
			}
		});
	}

private static boolean insertItemToProcess(
			ItemStack stack, boolean simulate, State state, Level rawLevel
	)
	{
		if(state.sawmillProcessQueue.size() >= MAX_PROCESSES)
			return false;
		float dist = 1;
		float minProcessDist = 0.1f;
		SawmillProcess p = null;
		if(state.sawmillProcessQueue.size() > 0)
		{
			p = state.sawmillProcessQueue.get(state.sawmillProcessQueue.size()-1);
			if(p!=null)
			{
				dist = p.getRelativeProcessStep(rawLevel);
				// either it's a different item or we have 3 together already
				if(!ItemStack.isSameItem(stack, p.getInput())||state.combinedLogs > 2)
				{
					if(!simulate)
						state.combinedLogs = 0;
					minProcessDist = 0.5f;
				}
			}
		}
		else if(state.combinedLogs > 0)
			state.combinedLogs = 0;

		if(p!=null&&dist < minProcessDist)
			return false;
		if(!simulate)
		{
			p = new SawmillProcess(stack.copyWithCount(1));
			state.sawmillProcessQueue.add(p);
			state.combinedLogs++;
		}
		stack.shrink(1);
		return true;
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		final boolean rsAllowed = state.rsState.isEnabled(context);
		int i = 0;
		Iterator<SawmillProcess> processIterator = state.sawmillProcessQueue.iterator();
		Set<ItemStack> secondaries = new HashSet<>();
		while(rsAllowed&&processIterator.hasNext()&&i++ < MAX_PROCESSES)
		{
			SawmillProcess process = processIterator.next();
			if(process.processStep(rawLevel, state.energy, state.sawblade, secondaries))
				context.markMasterDirty();
			if(process.isProcessFinished())
			{
				state.output.insertOrDrop(process.getCurrentStack(rawLevel, !state.sawblade.isEmpty()).copy(), level);
				processIterator.remove();
				ItemUtils.damageStackableItem(state.sawblade, level.getRawLevel(), IEServerConfig.MACHINES.sawmill_bladeDamage.get());
				context.markDirtyAndSync();
			}
		}
		for(ItemStack output : secondaries)
			state.secondaryOutput.insertOrDrop(output.copy(), level);
		ActiveState renderActive;
		boolean noJobs = state.sawmillProcessQueue.isEmpty();
		boolean hasBlade = !state.sawblade.isEmpty();
		if(state.energy.getEnergyStored() <= 0||!rsAllowed||(noJobs&&!hasBlade))
			renderActive = ActiveState.NOT_RUNNING;
		else if(noJobs)
			renderActive = ActiveState.IDLE_WITH_BLADE;
		else if(hasBlade)
			renderActive = ActiveState.SAWING;
		else
			renderActive = ActiveState.RUNNING_NO_BLADE;
		if(state.active!=renderActive)
		{
			state.active = renderActive;
			context.markDirtyAndSync();
		}
	}

@Override
    protected void checkAndPerformAttack(LivingEntity enemy, boolean inRange) {
        long currentTime = mob.level.getGameTime();
        if (attackType == GRAB) {
            for (Entity passenger : mob.getPassengers()) {
                if (passenger instanceof LivingEntity && passenger != mob.getRidingPlayer()) {
                    if (mob.tickCount % 20 == 0) {
                        boolean hurt = passenger.hurt(DamageSource.mobAttack(mob), (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        if (!hurt || (currentTime >= grabStartTick + GRAB_DURATION && mob.getRandom().nextInt(5) == 0)) {
                            attackEndTick = currentTime + 20;
                            mob.stopGrabAttack(passenger);
                        }
                    }
                }
            }
        } else if (attackType == ATTACK) {
            if (inRange && attackDamageTick > 0 && currentTime >= attackDamageTick) {
                mob.attackTarget(enemy);
                mob.destroyBoat(enemy);
                attackDamageTick = -1;
                attackType = -1;
            }
        } else if (currentTime > attackEndTick + 20 && inRange) {
            //Is target smaller than 1 block (if prehistoric is adult)
            boolean tooBig = !Util.isEntitySmallerThan(enemy, mob.grabTargetSize());
            if (tooBig || mob.getRandom().nextInt(5) > 0 || mob.getVehicle() == enemy) {
                attackType = ATTACK;
                ServerAnimationInfo animationInfo = mob.startAttack();
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength);
                attackDamageTick = Math.min((long) (currentTime + animationInfo.actionDelay), attackEndTick);
            } else {
                attackType = GRAB;
                mob.destroyBoat(enemy);
                mob.startGrabAttack(enemy);
                //TODO: Grab attack needs to be delayed and probably only start when looking at player?
                attackEndTick = 1;
                grabStartTick = currentTime;
            }
        }
    }

public int countRecentCasts(Spell spell){
		long currentTime = player.world.getTotalWorldTime();
		return (int)this.recentSpells.stream()
				.filter(entry -> entry.getKey() == spell && (currentTime - entry.getValue()) < Wizardry.settings.recentSpellExpiryTime)
				.count(); // We know this can't be more than 5
	}

@SubscribeEvent
        public static void tickTemperature(LivingEvent.LivingTickEvent event)
        {
            LivingEntity entity = event.getEntity();
            boolean isServer = !entity.level().isClientSide;
            if (!TEMPERATURE_ENABLED_ENTITIES.contains(entity.getType())) return;

            getTemperatureCap(entity).ifPresent(cap ->
            {
                // Tick modifiers serverside
                if (isServer)
                {   cap.tick(entity);
                }

                // Tick modifiers & removed expired
                AtomicBoolean sync = new AtomicBoolean(false);
                for (Trait trait : VALID_MODIFIER_TRAITS)
                {
                    List<TempModifier> modifiers = cap.getModifiers(trait);
                    for (int i = 0; i < modifiers.size(); i++)
                    {
                        TempModifier modifier = modifiers.get(i);
                        // Tick modifier
                        if (modifier.getTicksExisted() % modifier.getTickRate() == 0)
                        {   modifier.tick(entity);
                        }
                        if (isServer)
                        {
                            // Sync if the modifier is dirty
                            if (modifier.isDirty())
                            {   sync.set(true);
                                modifier.markClean();
                            }
                            // Remove expired modifiers
                            int expireTime = modifier.getExpireTime();
                            modifier.setTicksExisted(modifier.getTicksExisted() + 1);
                            if (modifier.getTicksExisted() > expireTime && expireTime != -1)
                            {
                                modifier.onRemoved(entity, trait);
                                Temperature.updateSiblingsRemove(modifiers, entity, trait, modifier);
                                modifiers.remove(i);
                                sync.set(true);
                                i--;
                            }
                        }
                    }
                }
                if (isServer && sync.get())
                {   Temperature.updateModifiers(entity, cap);
                }

                // Spawn particles for uninhabitable entities
                if (isServer && hasClimateData(entity))
                {
                    if (entity.tickCount % 5 == 0 && entity.getRandom().nextDouble() < 0.1)
                    {
                        double worldTemp = cap.getTrait(Trait.WORLD);
                        double entityX = entity.getX();
                        double entityY = entity.getY() + entity.getBbHeight();
                        double entityZ = entity.getZ();

                        if (worldTemp < cap.getTrait(Trait.FREEZING_POINT))
                        {
                            WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_COLD.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                           entity.getRandom().nextInt(2, 4), 0);
                        }
                        else if (worldTemp > cap.getTrait(Trait.BURNING_POINT))
                        {
                            WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_HOT.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                           entity.getRandom().nextInt(2, 4), 0);
                        }
                    }
                }
            });
        }

private void pumpCycle() {
        Level level;
        if ((level = getLevel()) == null) {
            return;
        }
        // Will only update if the queue is empty
        updatePumpQueue(null);
        int pumps = pumpsPerCycle();

        // We try to pump `pumps` amount of source blocks, using multiple paths if necessary
        boolean pumped = false;
        int iterations = 0;
        // We keep looking at paths as long as we still have pumps to go
        // We put the iterations at max 10 just to be sure
        while (pumps > 0 && pumpQueue != null && !pumpQueue.queue().isEmpty() && iterations < 10) {
            iterations++;

            Deque<BlockPos> pumpPath = pumpQueue.queue().peek();
            Deque<SourceState> states = new ArrayDeque<>();

            // We iterate through the positions to check if it is still a valid path, saving the states
            for (BlockPos pos : pumpPath) {
                // Stop once an unloaded block is found
                if (!level.isLoaded(pos)) {
                    break;
                }
                BlockState state = level.getBlockState(pos);
                if (state.getBlock() instanceof LiquidBlock liquidBlock &&
                        (liquidBlock.getFluidState(state)).getFluidType() == pumpQueue.fluidType()) {
                    states.add(new SourceState(state, pos));
                } else {
                    break;
                }
            }

            // We remove from the end until we find a matching state, everything after must be no longer valid
            while (pumps > 0 && !pumpPath.isEmpty()) {
                BlockPos pos = pumpPath.removeLast();
                SourceState sourceState = states.peekLast();
                if (sourceState != null && pos.equals(sourceState.pos())) {
                    states.removeLast();
                    FluidState fluidState = sourceState.state().getFluidState();
                    if (sourceState.state().getBlock() instanceof LiquidBlock liquidBlock && fluidState.isSource()) {
                        var fluidHandler = new BucketPickupHandlerWrapper(liquidBlock, getLevel(), pos);
                        FluidStack drainStack = fluidHandler.drain(Integer.MAX_VALUE, FluidAction.SIMULATE);
                        if (!drainStack.isEmpty() &&
                                cache.fillInternal(drainStack, FluidAction.SIMULATE) == drainStack.getAmount()) {
                            cache.fillInternal(drainStack, FluidAction.EXECUTE);
                            fluidHandler.drain(drainStack, FluidAction.EXECUTE);
                            getLevel().setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
                            pumped = true;
                            pumps--;
                        } else if (!drainStack.isEmpty()) {
                            // In this case we just couldn't fill the internal tank, it's most likely full
                            // So we add back to the pump path and return
                            pumpPath.add(pos);
                            return;
                        } else {
                            // drain stack is empty even though it's a fluid source, probably something went wrong
                            // ignore block for a while
                            forbiddenBlocks.add(pos);
                            return;
                        }
                    }
                }
            }

            if (pumpPath.isEmpty()) {
                pumpQueue.queue().remove();
            }

            // If we have pumps left over and there is still more to be pumped at the current level
            // (But it wasn't in the queue because maybe it's the final source block below the pump head)
            // We still want to be able to pump
            if (pumps > 0 && pumpQueue.queue().isEmpty()) {
                updatePumpQueue(pumpQueue.fluidType());
            }
        }

        // Use energy if any pumps happened at all
        if (pumped) {
            energyContainer.changeEnergy(-GTValues.V[getTier()] * 2);
        }
    }

private PumpQueue buildPumpQueue(Level level, BlockPos headPos, FluidType fluidType, int queueSourceAmount,
                                     boolean upSources) {
        Set<BlockPos> checked = new ObjectOpenHashSet<>();

        BlockPos headPosBelow = headPos.below();

        checked.add(headPos);
        checked.add(headPosBelow);

        int maxPumpRange = getMaxPumpRadius(getTier());

        List<BlockPos> pathStack = new ArrayList<>();

        Deque<BlockPos> nonSources = new ArrayDeque<>();
        Deque<BlockPos> pathToLastSource = new ArrayDeque<>();
        Deque<BlockPos> sourceStack = new ArrayDeque<>();

        pathStack.add(headPosBelow);
        nonSources.add(headPosBelow);

        int iterations = 0;
        int previousSources = 0;
        Queue<Deque<BlockPos>> paths = new ArrayDeque<>();
        List<BlockPos> sources = new ArrayList<>();
        // We do at most 1000 iterations to try and find source blocks
        while (!pathStack.isEmpty() && iterations < 1000) {
            // Peeks at the tail
            BlockPos searchHead = pathStack.get(pathStack.size() - 1);

            SearchResult next = searchNext(level, headPosBelow, searchHead, fluidType, maxPumpRange, upSources,
                    checked);

            iterations++;

            if (next == null) {
                boolean continueSearch = sources.size() < queueSourceAmount;

                int addedSources = sources.size() - previousSources;
                previousSources = sources.size();
                if (addedSources > 0) {
                    var toAdd = new ArrayDeque<>(pathToLastSource);
                    // This is always the headPosBelow, which we do not want to include
                    toAdd.removeFirst();
                    paths.add(toAdd);
                }

                if (!continueSearch) {
                    return new PumpQueue(paths, fluidType);
                }

                // Now we need to rewind our stack
                BlockPos last = pathStack.remove(pathStack.size() - 1);
                BlockPos lastSource = sourceStack.peekLast();
                if (last.equals(lastSource)) {
                    BlockPos prevSource = sourceStack.removeLast();
                    // Rebuild nonSources until previous source
                    for (int i = pathStack.size() - 1; i >= 0; i--) {
                        BlockPos p = pathStack.get(i);
                        if (!p.equals(prevSource)) {
                            nonSources.addFirst(p);
                        } else {
                            break;
                        }
                    }
                    // If the last is a source, then nonSources will be empty regardless
                } else if (!nonSources.isEmpty()) {
                    nonSources.removeLast();
                }
            } else {
                // Add the next
                pathStack.add(next.pos());
                // If we are in search up mode, we only count it as a source if it's up
                if (next.isSource() && (!upSources || next.pos().getY() > headPosBelow.getY())) {
                    sources.add(next.pos());
                    // Found a source, so add all the non-source blocks we passed since the last one
                    pathToLastSource.addAll(nonSources);
                    // Also add the source itself
                    pathToLastSource.add(next.pos());
                    // Reset non-sources because we just added them and found a source
                    nonSources.clear();
                    sources.add(next.pos());
                } else {
                    // Not a source, but we want to track it
                    nonSources.add(next.pos());
                }

            }
        }
        if (upSources) {
            // If we found none, we try again without the restriction
            if (paths.isEmpty()) {
                return buildPumpQueue(level, headPos, fluidType, queueSourceAmount, false);
            }

            return new PumpQueue(paths, fluidType);
        }

        // Only after everything except the block directly below the pipe is pumped, do we want to pump it
        // Otherwise we might advance the pump head prematurely
        if (paths.isEmpty() && level.getBlockState(headPosBelow).getFluidState().isSource()) {
            return new PumpQueue(new ArrayDeque<>(List.of(new ArrayDeque<>(List.of(headPosBelow)))), fluidType);
        }

        return new PumpQueue(paths, fluidType);
    }

@Override
    protected void tryAbsorbWater(Level level, BlockPos pos) {
        Queue<Tuple<BlockPos, Integer>> queue = Lists.newLinkedList();
        queue.add(new Tuple<>(pos, 0));
        int checkedBlocksCount = 0;

        while (!queue.isEmpty()) {
            Tuple<BlockPos, Integer> tuple = queue.poll();
            BlockPos blockpos = tuple.getA();
            int currentRange = tuple.getB();

            for (Direction direction : Direction.values()) {
                BlockPos blockToCheckPos = blockpos.relative(direction);
                BlockState blockToCheckState = level.getBlockState(blockToCheckPos);
                Block blockToCheck = blockToCheckState.getBlock();

                if (blockToCheck instanceof BucketPickup bucketPickup && !bucketPickup.pickupBlock(null, level, blockToCheckPos, blockToCheckState).isEmpty()) {
                    ++checkedBlocksCount;

                    if (currentRange < MAX_RANGE) {
                        queue.add(new Tuple<>(blockToCheckPos, currentRange + 1));
                    }

                } else if (blockToCheckState.getBlock() instanceof LiquidBlock) {
                    if (blockToCheckState.is(Blocks.KELP) || blockToCheckState.is(Blocks.KELP_PLANT) || blockToCheckState.is(Blocks.SEAGRASS) || blockToCheckState.is(Blocks.TALL_SEAGRASS)) {
                        BlockEntity blockEntity = blockToCheckState.hasBlockEntity() ? level.getBlockEntity(blockToCheckPos) : null;
                        dropResources(blockToCheckState, level, blockToCheckPos, blockEntity);
                    }
                    this.removeBlock(blockToCheckPos, level);
                    ++checkedBlocksCount;

                    if (currentRange < MAX_RANGE) {
                        queue.add(new Tuple<>(blockToCheckPos, currentRange + 1));
                    }
                }
            }

            if (checkedBlocksCount > MAX_REPLACES) {
                break;
            }
        }
    }

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		boolean isRSEnabled = state.rsState.isEnabled(context);
		boolean active = state.processor.tickServer(state, context.getLevel(), isRSEnabled);
		if(active!=state.active)
		{
			state.active = active;
			context.requestMasterBESync();
		}
		if(!context.getLevel().shouldTickModulo(16))
			return;
		if(!isRSEnabled||state.inventory.getStackInSlot(BLUEPRINT_SLOT).isEmpty())
			return;

		List<RecipeHolder<BlueprintCraftingRecipe>> recipes = getAvailableRecipes(context.getLevel().getRawLevel(), state);
		if(state.selectedRecipe >= 0&&state.selectedRecipe < recipes.size())
		{
			RecipeHolder<BlueprintCraftingRecipe> holder = recipes.get(state.selectedRecipe);
			BlueprintCraftingRecipe recipe = holder.value();
			if(!recipe.output.get().isEmpty())
			{
				NonNullList<ItemStack> query = NonNullList.withSize(NUM_INPUT_SLOTS, ItemStack.EMPTY);
				for(int i = 0; i < query.size(); i++)
					query.set(i, state.inventory.getStackInSlot(i+FIRST_INPUT_SLOT));
				int crafted = recipe.getMaxCrafted(query);
				if(crafted > 0&&state.processor.addProcessToQueue(
						new MultiblockProcessInWorld<>(holder, 0.78f, NonNullList.create()),
						context.getLevel().getRawLevel(),
						true
				))
				{
					state.processor.addProcessToQueue(
							new MultiblockProcessInWorld<>(holder, 0.78f, recipe.consumeInputs(query, 1)),
							context.getLevel().getRawLevel(),
							false
					);
					for(int i = 0; i < query.size(); i++)
						state.inventory.setStackInSlot(i+FIRST_INPUT_SLOT, query.get(i));
				}
			}
		}
	}

private void submitNewArrivals(InventorySummary before, InventorySummary after) {
		if (before == null || after.isEmpty())
			return;

		Set<RequestPromiseQueue> promiseQueues = new HashSet<>();

		for (Direction d : Iterate.directions) {
			if (!level.isLoaded(worldPosition.relative(d)))
				continue;

			BlockState adjacentState = level.getBlockState(worldPosition.relative(d));
			if (AllBlocks.FACTORY_GAUGE.has(adjacentState)) {
				if (FactoryPanelBlock.connectedDirection(adjacentState) != d)
					continue;
				if (!(level.getBlockEntity(worldPosition.relative(d)) instanceof FactoryPanelBlockEntity fpbe))
					continue;
				if (!fpbe.restocker)
					continue;
				for (FactoryPanelBehaviour behaviour : fpbe.panels.values()) {
					if (!behaviour.isActive())
						continue;
					promiseQueues.add(behaviour.restockerPromises);
				}
			}

			if (AllBlocks.STOCK_LINK.has(adjacentState)) {
				if (PackagerLinkBlock.getConnectedDirection(adjacentState) != d)
					continue;
				if (!(level.getBlockEntity(worldPosition.relative(d)) instanceof PackagerLinkBlockEntity plbe))
					continue;
				UUID freqId = plbe.behaviour.freqId;
				if (!Create.LOGISTICS.hasQueuedPromises(freqId))
					continue;
				promiseQueues.add(Create.LOGISTICS.getQueuedPromises(freqId));
			}
		}

		if (promiseQueues.isEmpty())
			return;

		for (BigItemStack entry : after.getStacks())
			before.add(entry.stack, -entry.count);
		for (RequestPromiseQueue queue : promiseQueues)
			for (BigItemStack entry : before.getStacks())
				if (entry.count < 0)
					queue.itemEnteredSystem(entry.stack, -entry.count);
	}

@Override
	public void onEntityCollision(IMultiblockContext<State> ctx, BlockPos posInMultiblock, Entity collided)
	{
		final Level level = collided.level();
		if(!new BlockPos(0, 1, 1).equals(posInMultiblock)||level.isClientSide)
			return;
		else if(!(collided instanceof ItemEntity)||!collided.isAlive())
			return;
		final State state = ctx.getState();
		final BlockPos absoluteCollisionPos = ctx.getLevel().toAbsolute(posInMultiblock);
		List<Pair<ItemEntity, ItemStack>> itemsOnConveyor = level.getEntitiesOfClass(
				ItemEntity.class, AABB.unitCubeFromLowerCorner(Vec3.atLowerCornerOf(absoluteCollisionPos))
		).stream().map(itemEntity1 -> Pair.of(itemEntity1, itemEntity1.getItem())).toList();
		if(itemsOnConveyor.isEmpty())
			return;

		ItemStack[] stacks = itemsOnConveyor.stream().map(Pair::getSecond).toArray(ItemStack[]::new);
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level, state.tank.getFluid(), stacks);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stacks[0]))
			return;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		NonNullList<ItemStack> displayStacks;
		if(recipe==null)
		{
			ItemStack inputItem = stacks[0].copyWithCount(1);
			displayStacks = Utils.createNonNullItemStackListFromItemStack(inputItem);
			process = new BottlingProcess(inputItem, inputItem.copy(), state);
		}
		else
		{
			displayStacks = recipe.value().getDisplayStacks(stacks);
			process = new BottlingProcess(recipe, displayStacks, state);
		}

		if(state.processor.addProcessToQueue(process, level, false))
			for(ItemStack stack : displayStacks)
				itemsOnConveyor.stream()
						.filter(t -> ItemStack.isSameItemSameComponents(t.getSecond(), stack))
						.findFirst()
						.ifPresent(t -> {
							ItemStack remaining = t.getSecond().copy();
							remaining.shrink(stack.getCount());
							t.getFirst().setItem(remaining);
							if(remaining.isEmpty())
								t.getFirst().discard();
						});
	}

@Override
    public void onUpdate() {
        BlockPos startPos = this.getPosition();
        if(!world.isRemote) {
            BlockPos rail = getPosition();
            boolean isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            if(!isRails) {
                rail = rail.down();
                isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            }
            if(!isRails && world.getBlockState(rail.down()).getBlock() instanceof TourRailBlock && Arrays.asList(TourRailBlock.EnumRailDirection.ASCENDING_EAST, TourRailBlock.EnumRailDirection.ASCENDING_NORTH, TourRailBlock.EnumRailDirection.ASCENDING_SOUTH, TourRailBlock.EnumRailDirection.ASCENDING_WEST).contains(TourRailBlock.getRailDirection(world, rail.down()))) {
                rail = rail.down(1);
                isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            }

            if(onRails != isRails) {
                if(isRails) {
                    minecart.isInReverse = lastDirBackwards;
                }
                onRails = isRails;
                RebornMod.NETWORK_WRAPPER.sendToDimension(new FordExplorerSnowChangeStateMessage(this), world.provider.getDimension());
            }
            this.railTracks = isRails ? rail : INACTIVE;
            if(!this.railTracks.equals(prevRailTracks)) {
                RebornMod.NETWORK_WRAPPER.sendToDimension(new FordExplorerSnowUpdatePositionStateMessage(this, rail), world.provider.getDimension());
            }
            this.prevRailTracks = railTracks;
        }
        if(onRails) {
            this.setSize(0.75F, 0.25F);
//			this.stepHeight = 0F;
        } else {
            this.setSize(3.0F, 2.5F);
//			this.stepHeight = 1.5F;
        }
        this.setPosition(this.posX, this.posY, this.posZ); //Make sure that the car is in the right position. Can cause issues when changing size of car
        super.onUpdate();
        if(onRails) {
            minecart.onUpdate();
            Vector4d vec = wheeldata.carVector;
            this.backValue.setTarget(this.calculateWheelHeight(vec.y, false));
            this.frontValue.setTarget(this.calculateWheelHeight(vec.w, false));
            this.leftValue.setTarget(posY);
            this.rightValue.setTarget(posY);
        }
        prevOnRails = onRails;
        if(!startPos.equals(this.getPosition())) {
            prevPos = this.getPosition();
        }
    }

private int placeNonBlockItem(FluidEffectContext.Block context, FluidAction action, Block block, BlockPlaceContext placeContext) {

    // following code is based on block item, with notably differences of not calling block item methods (as if we had one we'd use it above)
    // we do notably call this logic in simulation as we need to stop the block item logic early, differences are noted in comments with their vanilla impacts

    // simulate note: we don't ask the block item for its state for placement as that method is protected, this notably affects signs/banners (unlikely need)
    BlockState state = block.getStateForPlacement(placeContext);
    if (state == null) {
      return 0;
    }

    Level world = context.getLevel();
    BlockPos clicked = placeContext.getClickedPos();
    Player player = context.getPlayer();
    // simulate note: we don't call BlockItem#canPlace as its protected, though never overridden in vanilla
    if (!state.canSurvive(world, clicked) || !world.isUnobstructed(state, clicked, player == null ? CollisionContext.empty() : CollisionContext.of(player))) {
      return 0;
    }
    // at this point the only check we are missing on simulate is actually placing the block failing
    if (action.execute()) {
      // actually place the block
      if (!world.setBlock(clicked, state, Block.UPDATE_ALL_IMMEDIATE)) {
        return 0;
      }
      // if its the expected block, run some criteria stuffs
      BlockState placed = world.getBlockState(clicked);
      ItemStack stack = placeContext.getItemInHand();
      if (placed.is(block)) {
        // difference from BlockItem: do not update block state or block entity from tag as we have no tag
        // it might however be worth passing in a set of properties to set here as part of JSON
        // setPlacedBy only matters when placing from held item
        block.setPlacedBy(world, clicked, placed, player, stack);
        if (player instanceof ServerPlayer serverPlayer) {
          CriteriaTriggers.PLACED_BLOCK.trigger(serverPlayer, clicked, stack);
        }
      }

      // resulting events
      LivingEntity placer = context.getEntity(); // possible that living is nonnull when player is null
      world.gameEvent(GameEvent.BLOCK_PLACE, clicked, GameEvent.Context.of(placer, placed));
      SoundType sound = placed.getSoundType(world, clicked, placer);
      world.playSound(null, clicked, Objects.requireNonNullElse(this.sound, sound.getPlaceSound()), SoundSource.BLOCKS, (sound.getVolume() + 1.0F) / 2.0F, sound.getPitch() * 0.8F);

      // stack might be empty if we failed to find an item form; only matters in null block form anyways
      if ((player == null || !player.getAbilities().instabuild) && !stack.isEmpty()) {
        stack.shrink(1);
      }
    }
    return 1;
  }

@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack heldStack = player.getItemInHand(hand);

		if (getCharge(heldStack) <= 0 && InventoryUtil.findItemForConsumption(player, AoAItems.CRYSTALLITE, player.getAbilities().instabuild ? 0 : 1, true)) {
			setCharge(heldStack, level.getGameTime() + 2400);
			heldStack.update(DataComponents.ATTRIBUTE_MODIFIERS, ItemAttributeModifiers.EMPTY, modifiers -> modifiers.withModifierAdded(Attributes.ATTACK_DAMAGE, new AttributeModifier(BASE_ATTACK_DAMAGE_ID, 3 + getTier().getAttackDamageBonus(), AttributeModifier.Operation.ADD_VALUE), EquipmentSlotGroup.MAINHAND));

			if (level instanceof ServerLevel serverLevel) {
				double xOffset = -Mth.sin(player.getYRot() * (float)Math.PI / 140f);
				double zOffset = Mth.cos(player.getYRot() * (float)Math.PI / 140f);

				serverLevel.sendParticles(ParticleTypes.END_ROD, player.getX() + xOffset, player.getY() + player.getBbHeight() * 0.5d, player.getZ() + zOffset, 5, xOffset, 0, zOffset, 0);
			}

			return InteractionResultHolder.success(heldStack);
		}

		return super.use(level, player, hand);
	}

protected List<HitResult> raycastForEntitiesAlongPath(Vec3 destination, Vec3 position) {
        AABB range = this.getBoundingBox().expandTowards(destination.subtract(position)).inflate(0.1);
        List<HitResult> hits = new ArrayList<>();
        List<Entity> hitEntities = new ArrayList<>(); // prevents large hitbox entities from registering multiple hits in one tick
        List<? extends Entity> entities = level.getEntities(this, range, this::canHitEntity);
        for (Entity target : entities) {
            if (hitEntities.contains(target)) {
                continue;
            }
            HitResult hit = Utils.checkEntityIntersecting(target, position, destination, getHitDetectionInflation());
            if (hit.getType() != HitResult.Type.MISS) {
                hits.add(hit);
                hitEntities.add(target);
            }
        }

        if (!hits.isEmpty()) {
            hits.sort(Comparator.comparingDouble(o -> o.getLocation().distanceToSqr(position)));
        }
        return hits;
    }

public void tick(Level level) {
        if (!(level instanceof ServerLevel serverLevel)) {
            return;
        }
        if (!serverLevel.dimension().equals(PocketDimensionManager.POCKET_DIMENSION)) {
            return;
        }
        if (serverLevel.getGameTime() % 100 == 0) {
            serverLevel.players().forEach(player -> {
                if (!player.isCreative() && !player.isSpectator()) {
                    int pocketX = (int) (player.getX() / PocketDimensionManager.POCKET_SPACING) * PocketDimensionManager.POCKET_SPACING;
                    int pocketZ = (int) (player.getZ() / PocketDimensionManager.POCKET_SPACING) * PocketDimensionManager.POCKET_SPACING;
                    if (player.getX() < pocketX || player.getX() > pocketX + 16
                            || player.getZ() < pocketZ || player.getZ() > pocketZ + 16) {
                        // snap player back into bounds
                        var blockPos = structurePosForPlayer(player);
                        var portalPos = findPortalForStructure(serverLevel, blockPos);
                        player.resetFallDistance();
                        player.stopRiding();
                        player.moveTo(portalPos.getBottomCenter());
                    }
                }
            });
        }
    }

