@SubscribeEvent
    public static void livingTick(EntityTickEvent.Pre event) {
        GuidingBoltManager manager = event.getEntity().level instanceof ServerLevel ? GuidingBoltManager.INSTANCE : GuidingBoltManager.CLIENT_INSTANCE;
//        if (MinecraftInstanceHelper.getPlayer() == event.getEntity() && event.getEntity().tickCount % 20 == 0) {
//            IronsSpellbooks.LOGGER.debug("\nGuiding Bolt Dump");
//            for (Map.Entry entry : GuidingBoltManager.INSTANCE.trackedEntities.entrySet()) {
//                IronsSpellbooks.LOGGER.debug("{}: {}", entry.getKey(), entry.getValue());
//            }
//        }
        if (manager.trackedEntities.isEmpty()) {
            return;
        }
        if (event.getEntity() instanceof LivingEntity livingEntity) {
            if (livingEntity.tickCount % manager.tickDelay == 0) {
                var projectiles = manager.trackedEntities.get(event.getEntity().getUUID());
                if (projectiles != null) {
                    if (livingEntity.isRemoved() || livingEntity.isDeadOrDying()) {
                        manager.stopTracking(livingEntity);
                        return;
                    }
                    List<Projectile> projectilesToRemove = new ArrayList<>();
                    for (Projectile projectile : projectiles) {
                        Vec3 motion = projectile.getDeltaMovement();
                        float speed = (float) motion.length();
                        Vec3 home = livingEntity.getBoundingBox().getCenter().subtract(projectile.position()).normalize().scale(speed * .55f * manager.tickDelay / 3f);
                        if (projectile.isRemoved() || home.dot(motion) < -0.75) {
                            //We have passed the entity
                            projectilesToRemove.add(projectile);
                            continue;
                        }
                        Vec3 newMotion = motion.add(home).normalize().scale(speed);
                        projectile.setDeltaMovement(newMotion);
                    }
                    projectiles.removeAll(projectilesToRemove);
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();

        if (caster != null && !caster.isAlive()) this.discard();

        if (caster !=null){
            this.setYRot(caster.yHeadRot);
           // this.setXRot(caster.getXRot());
        }
        float yaw = (float) Math.toRadians(-getYRot());
        float pitch = (float) Math.toRadians(-getXRot());
        float spread = 0.25f;
        float speed = 0.56f;
        float xComp = (float) (Math.sin(yaw) * Math.cos(pitch));
        float yComp = (float) (Math.sin(pitch));
        float zComp = (float) (Math.cos(yaw) * Math.cos(pitch));
        double theta = (getYRot()) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = Math.cos(theta);
        double vecZ = Math.sin(theta);
        double vec = 0.9;
        if (level().isClientSide) {
            for (int i = 0; i < 80; i++) {
                double xSpeed = speed * xComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                level().addParticle(ParticleTypes.SMOKE, getX() + vec * vecX, getY(), getZ() + vec * vecZ, xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 2; i++) {
                double xSpeed = speed * xComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                level().addParticle(ParticleTypes.FLAME, getX() + vec * vecX, getY(), getZ() + vec * vecZ, xSpeed, ySpeed, zSpeed);
            }
        }
        if (tickCount > 2 && caster != null) {
            hitEntities();
        }
        if (tickCount > 25) discard() ;
    }

public void hitEntities() {
        List<LivingEntity> entitiesHit = getEntityLivingBaseNearby(RANGE, RANGE, RANGE, RANGE);;
        for (LivingEntity entityHit : entitiesHit) {
            float entityHitYaw = (float) ((Math.atan2(entityHit.getZ() - getZ(), entityHit.getX() - getX()) * (180 / Math.PI) - 90) % 360);
            float entityAttackingYaw = getYRot() % 360;
            if (entityHitYaw < 0) {
                entityHitYaw += 360;
            }
            if (entityAttackingYaw < 0) {
                entityAttackingYaw += 360;
            }
            float entityRelativeYaw = entityHitYaw - entityAttackingYaw;

            float xzDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()));
            double hitY = entityHit.getY() + entityHit.getBbHeight() / 2.0;
            float entityHitPitch = (float) ((Math.atan2((hitY - getY()), xzDistance) * (180 / Math.PI)) % 360);
            float entityAttackingPitch = -getXRot() % 360;
            if (entityHitPitch < 0) {
                entityHitPitch += 360;
            }
            if (entityAttackingPitch < 0) {
                entityAttackingPitch += 360;
            }
            float entityRelativePitch = entityHitPitch - entityAttackingPitch;

            float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()) + (hitY - getY()) * (hitY - getY()));
            int distance = this.tickCount / 2 ;
            boolean inRange = entityHitDistance <= distance + 1.0F;
            boolean yawCheck = (entityRelativeYaw <= ARC / 2f && entityRelativeYaw >= -ARC / 2f) || (entityRelativeYaw >= 360 - ARC / 2f || entityRelativeYaw <= -360 + ARC / 2f);
            boolean pitchCheck = (entityRelativePitch <= ARC / 2f && entityRelativePitch >= -ARC / 2f) || (entityRelativePitch >= 360 - ARC / 2f || entityRelativePitch <= -360 + ARC / 2f);
            boolean CloseCheck = caster instanceof Ignited_Revenant_Entity && entityHitDistance <= 2;
            if (inRange && yawCheck && pitchCheck || CloseCheck) {
                if (this.tickCount % 3 == 0) {
                    if (!isAlliedTo(entityHit) && entityHit != caster) {
                        boolean flag = entityHit.hurt(this.damageSources().indirectMagic(this, caster), this.getDamage());
                        if (flag) {
                            //entityHit.setDeltaMovement(entityHit.getDeltaMovement().multiply(0.25, 1, 0.25));
                            MobEffectInstance effectinstance = new MobEffectInstance(MobEffects.BLINDNESS, 60, 0, false, false, true);
                            entityHit.addEffect(effectinstance);
                        }
                    }
                }
            }
        }
    }

@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        int signalModifier = Mth.clamp((int) spellStats.getAmpMultiplier() + 10, 1, 15);
        int timeBonus = (int) spellStats.getDurationMultiplier();
        int delay = Math.max(GENERIC_INT.get() + timeBonus * BONUS_TIME.get(), 2);
        List<BlockPos> posList = SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats);
        Player fakePlayer = ANFakePlayer.getOrFakePlayer((ServerLevel) world, shooter);
        for (BlockPos pos1 : posList) {
            if (spellStats.isSensitive()) {
                if (!world.isInWorldBounds(pos1))
                    return;
                pos1 = pos1.immutable();
                RedstoneSavedData.from((ServerLevel) world).SIGNAL_MAP.put(pos1, new RedstoneSavedData.Entry(pos1, signalModifier, delay));
                world.neighborChanged(pos1, world.getBlockState(pos1).getBlock(), pos1);
                world.updateNeighborsAt(pos1, world.getBlockState(pos1).getBlock());
            } else {

                pos1 = pos1.relative(rayTraceResult.getDirection());

                if (!world.isInWorldBounds(pos1))
                    return;
                boolean notReplaceable = !world.getBlockState(pos1).canBeReplaced();
                if (notReplaceable)
                    continue;
                var event = NeoForge.EVENT_BUS.post(new BlockEvent.EntityPlaceEvent(BlockSnapshot.create(world.dimension(), world, pos1), world.getBlockState(pos1), fakePlayer));
                if (event.isCanceled()) {
                    continue;
                }
                BlockState state1 = BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState().setValue(TemporaryBlock.POWER, signalModifier);
                world.setBlockAndUpdate(pos1, state1);
                if (world.getBlockEntity(pos1) instanceof TemporaryTile tile) {
                    tile.gameTime = world.getGameTime();
                    tile.tickDuration = delay;
                    tile.mimicState = Blocks.REDSTONE_BLOCK.defaultBlockState();
                    tile.updateBlock();
                }
                world.sendBlockUpdated(pos1, world.getBlockState(pos1), world.getBlockState(pos1), 2);
            }
        }

    }

public static void initializeHandlers() {
        configSerialized = Packets.ConfigSync.write(BetterCombat.config);
        ServerPlayConnectionEvents.JOIN.register( (handler, sender, server) -> {
            sender.sendPacket(Packets.WeaponRegistrySync.ID, WeaponRegistry.getEncodedRegistry());
            sender.sendPacket(Packets.ConfigSync.ID, configSerialized);
        });

        ServerPlayNetworking.registerGlobalReceiver(Packets.AttackAnimation.ID, (server, player, handler, buf, responseSender) -> {
            ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                    .orNull();
            if (world == null || world.isClient) {
                return;
            }
            final var packet = Packets.AttackAnimation.read(buf);
            final var forwardBuffer = new Packets.AttackAnimation(player.getId(), packet.animatedHand(), packet.animationName(), packet.length(), packet.upswing()).write();
            try {
                //send info back for Replaymod Compat
                if (ServerPlayNetworking.canSend(player, Packets.AttackAnimation.ID)) {
                    ServerPlayNetworking.send(player, Packets.AttackAnimation.ID, forwardBuffer);
                }
            } catch (Exception e){
                e.printStackTrace();
            }
            PlayerLookup.tracking(player).forEach(serverPlayer -> {
                try {
                    if (ServerPlayNetworking.canSend(serverPlayer, Packets.AttackAnimation.ID)) {
                        ServerPlayNetworking.send(serverPlayer, Packets.AttackAnimation.ID, forwardBuffer);
                    }
                } catch (Exception e){
                    e.printStackTrace();
                }
            });
        });

        ServerPlayNetworking.registerGlobalReceiver(Packets.C2S_AttackRequest.ID, (server, player, handler, buf, responseSender) -> {
            ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
                    .orNull();
            if (world == null || world.isClient) {
                return;
            }
            final var request = Packets.C2S_AttackRequest.read(buf);
            final var hand = PlayerAttackHelper.getCurrentAttack(player, request.comboCount());
            if (hand == null) {
                LOGGER.error("Server handling Packets.C2S_AttackRequest - No current attack hand!");
                LOGGER.error("Combo count: " + request.comboCount() + " is dual wielding: " + PlayerAttackHelper.isDualWielding(player));
                LOGGER.error("Main-hand stack: " + player.getMainHandStack());
                LOGGER.error("Off-hand stack: " + player.getOffHandStack());
                LOGGER.error("Selected slot server: " + player.getInventory().selectedSlot + " | client: " + request.selectedSlot());
                return;
            }
            final var attack = hand.attack();
            final var attributes = hand.attributes();
            final boolean useVanillaPacket = Packets.C2S_AttackRequest.UseVanillaPacket;
            world.getServer().executeSync(() -> {
                ((PlayerAttackProperties)player).setComboCount(request.comboCount());
                Multimap<EntityAttribute, EntityAttributeModifier> comboAttributes = null;
                Multimap<EntityAttribute, EntityAttributeModifier> dualWieldingAttributes = null;
                Multimap<EntityAttribute, EntityAttributeModifier> sweepingModifiers = HashMultimap.create();
                double range = 18.0;
                if (attributes != null && attack != null) {
                    range = attributes.attackRange();

                    comboAttributes = HashMultimap.create();
                    double comboMultiplier = attack.damageMultiplier() - 1;
                    comboAttributes.put(
                            EntityAttributes.GENERIC_ATTACK_DAMAGE,
                            new EntityAttributeModifier(COMBO_DAMAGE_MODIFIER_ID, "COMBO_DAMAGE_MULTIPLIER", comboMultiplier, EntityAttributeModifier.Operation.MULTIPLY_BASE));
                    player.getAttributes().addTemporaryModifiers(comboAttributes);

                    var dualWieldingMultiplier = PlayerAttackHelper.getDualWieldingAttackDamageMultiplier(player, hand) - 1;
                    if (dualWieldingMultiplier != 0) {
                        dualWieldingAttributes = HashMultimap.create();
                        dualWieldingAttributes.put(
                                EntityAttributes.GENERIC_ATTACK_DAMAGE,
                                new EntityAttributeModifier(DUAL_WIELDING_MODIFIER_ID, "DUAL_WIELDING_DAMAGE_MULTIPLIER", dualWieldingMultiplier, EntityAttributeModifier.Operation.MULTIPLY_TOTAL));
                        player.getAttributes().addTemporaryModifiers(dualWieldingAttributes);
                    }

                    if (hand.isOffHand()) {
                        PlayerAttackHelper.setAttributesForOffHandAttack(player, true);
                    }

                    SoundHelper.playSound(world, player, attack.swingSound());

                    if (BetterCombat.config.allow_reworked_sweeping && request.entityIds().length > 1) {
                        double multiplier = 1.0
                                - (BetterCombat.config.reworked_sweeping_maximum_damage_penalty / BetterCombat.config.reworked_sweeping_extra_target_count)
                                * Math.min(BetterCombat.config.reworked_sweeping_extra_target_count, request.entityIds().length - 1);
                        int sweepingLevel = EnchantmentHelper.getLevel(Enchantments.SWEEPING, hand.itemStack());
                        double sweepingSteps = BetterCombat.config.reworked_sweeping_enchant_restores / ((double)Enchantments.SWEEPING.getMaxLevel());
                        multiplier += sweepingLevel * sweepingSteps;
                        multiplier = Math.min(multiplier, 1);
                        sweepingModifiers.put(
                                EntityAttributes.GENERIC_ATTACK_DAMAGE,
                                new EntityAttributeModifier(SWEEPING_MODIFIER_ID, "SWEEPING_DAMAGE_MODIFIER", multiplier - 1, EntityAttributeModifier.Operation.MULTIPLY_TOTAL));
                        // System.out.println("Applied sweeping multiplier " + multiplier + " , sweepingSteps " + sweepingSteps + " , enchant bonus: " + (sweepingLevel * sweepingSteps));
                        player.getAttributes().addTemporaryModifiers(sweepingModifiers);

                        boolean playEffects = !BetterCombat.config.reworked_sweeping_sound_and_particles_only_for_swords
                                || (hand.itemStack().getItem() instanceof SwordItem);
                        if (BetterCombat.config.reworked_sweeping_plays_sound && playEffects) {
                            world.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ENTITY_PLAYER_ATTACK_SWEEP, player.getSoundCategory(), 1.0f, 1.0f);
                        }
                        if (BetterCombat.config.reworked_sweeping_emits_particles && playEffects) {
                            player.spawnSweepAttackParticles();
                        }
                    }
                }

                var attackCooldown = PlayerAttackHelper.getAttackCooldownTicksCapped(player);
                var knockbackMultiplier = BetterCombat.config.knockback_reduced_for_fast_attacks
                        ? MathHelper.clamp(attackCooldown / 12.5F, 0.1F, 1F)
                        : 1F;
                var lastAttackedTicks = ((LivingEntityAccessor)player).getLastAttackedTicks();
                if (!useVanillaPacket) {
                    player.setSneaking(request.isSneaking());
                }


                for (int entityId: request.entityIds()) {
                    // getEntityById(entityId);
                    boolean isBossPart = false;
                    Entity entity = world.getEntityById(entityId);
                    if (entity == null) {
                        isBossPart = true;
                        entity = world.getDragonPart(entityId); // Get LivingEntity or DragonPart
                    }

                    if (entity == null
                            || (entity.equals(player.getVehicle()) && !TargetHelper.isAttackableMount(entity))
                            || (entity instanceof ArmorStandEntity && ((ArmorStandEntity)entity).isMarker())) {
                        continue;
                    }
                    if (entity instanceof LivingEntity livingEntity) {
                        if (BetterCombat.config.allow_fast_attacks) {
                            livingEntity.timeUntilRegen = 0;
                        }
                        if (knockbackMultiplier != 1F) {
                            ((ConfigurableKnockback)livingEntity).setKnockbackMultiplier_BetterCombat(knockbackMultiplier);
                        }
                    }
                    ((LivingEntityAccessor) player).setLastAttackedTicks(lastAttackedTicks);
                    // System.out.println("Server - Attacking hand: " + (hand.isOffHand() ? "offhand" : "mainhand") + " CD: " + player.getAttackCooldownProgress(0));
                    if (!isBossPart && useVanillaPacket) {
                        // System.out.println("HIT - A entity: " + entity.getEntityName() + " id: " + entity.getId() + " class: " + entity.getClass());
                        PlayerInteractEntityC2SPacket vanillaAttackPacket = PlayerInteractEntityC2SPacket.attack(entity, request.isSneaking());
                        handler.onPlayerInteractEntity(vanillaAttackPacket);
                    } else {
                        // System.out.println("HIT - B entity: " + entity.getEntityName() + " id: " + entity.getId() + " class: " + entity.getClass());
                        if (true || player.squaredDistanceTo(entity) < range * BetterCombat.config.target_search_range_multiplier) {
                            if (entity instanceof ItemEntity || entity instanceof ExperienceOrbEntity || entity instanceof PersistentProjectileEntity || entity == player) {
                                handler.disconnect(Text.translatable("multiplayer.disconnect.invalid_entity_attacked"));
                                LOGGER.warn("Player {} tried to attack an invalid entity", (Object)player.getName().getString());
                                return;
                            }
                            player.attack(entity);
                        }
                    }
                    if (entity instanceof LivingEntity livingEntity) {
                        if (knockbackMultiplier != 1F) {
                            ((ConfigurableKnockback)livingEntity).setKnockbackMultiplier_BetterCombat(1F);
                        }
                    }
                }

                if (!useVanillaPacket) {
                    player.updateLastActionTime();
                }

                if (comboAttributes != null) {
                    player.getAttributes().removeModifiers(comboAttributes);
                    if (hand.isOffHand()) {
                        PlayerAttackHelper.setAttributesForOffHandAttack(player, false);
                    }
                }
                if (dualWieldingAttributes != null) {
                    player.getAttributes().removeModifiers(dualWieldingAttributes);
                }
                if (!sweepingModifiers.isEmpty()) {
                    player.getAttributes().removeModifiers(sweepingModifiers);
                }
                ((PlayerAttackProperties)player).setComboCount(-1);
            });
        });
    }

private void startUpswing(WeaponAttributes attributes) {
        // Guard conditions

        if (player.isRiding()) {
            // isRiding is `isHandsBusy()` according to official mappings
            // Support for revival mod
            return;
        }

        var hand = getCurrentHand();
        if (hand == null) { return; }
        float upswingRate = (float) hand.upswingRate();
        if (upswingTicks > 0
                || attackCooldown > 0
                || player.isUsingItem()
                || player.getAttackCooldownProgress(0) < (1.0 - upswingRate)) {
//            double attackCooldownTicks = PlayerAttackHelper.getAttackCooldownTicksCapped(player) / PlayerAttackHelper.getDualWieldingAttackSpeedMultiplier(player);
//            var currentCD = Math.round(attackCooldownTicks * player.getAttackCooldownProgress(0));
//            System.out.println("Waiting for cooldown: " + currentCD + "/" + attackCooldownTicks);
            return;
        }

        // Starting upswing
        player.stopUsingItem();

        lastAttacked = 0;
        upswingStack = player.getMainHandStack();
        float attackCooldownTicksFloat = PlayerAttackHelper.getAttackCooldownTicksCapped(player); // `getAttackCooldownProgressPerTick` should be called `getAttackCooldownLengthTicks`
        int attackCooldownTicks = Math.round(attackCooldownTicksFloat);
        this.comboReset = Math.round(attackCooldownTicksFloat * BetterCombat.config.combo_reset_rate);
        this.upswingTicks = Math.max(Math.round(attackCooldownTicksFloat * upswingRate), 1); // At least 1 upswing ticks
        this.lastSwingDuration = attackCooldownTicksFloat;
        this.itemUseCooldown = attackCooldownTicks; // Vanilla MinecraftClient property for compatibility
        setMiningCooldown(attackCooldownTicks);
//        System.out.println("Starting upswingTicks: " + upswingTicks);
        String animationName = hand.attack().animation();
        boolean isOffHand = hand.isOffHand();
        var animatedHand = AnimatedHand.from(isOffHand, attributes.isTwoHanded());
        ((PlayerAttackAnimatable) player).playAttackAnimation(animationName, animatedHand, attackCooldownTicksFloat, upswingRate);
        ClientPlayNetworking.send(
                Packets.AttackAnimation.ID,
                new Packets.AttackAnimation(player.getId(), animatedHand, animationName, attackCooldownTicksFloat, upswingRate).write());
        BetterCombatClientEvents.ATTACK_START.invoke(handler -> {
            handler.onPlayerAttackStart(player, hand);
        });
    }

@Override
	public void triggerEvent(World world, GameEventListener listener, WirelessRedstoneSignalEventQueue.EventEntry redstoneEvent) {
		if (!isSender(this.getWorld(), this.pos) && redstoneEvent.gameEvent.getDyeColor() == getChannel(this.getWorld(), this.pos)) {
			int receivedSignal = redstoneEvent.gameEvent.getPower();
			this.currentSignal = receivedSignal;
			// trigger a block update in all cases, even when powered does not change. That way connected blocks
			// can react on the strength change of the block, since we store the power in the block entity, not the block state
			if (receivedSignal == 0) {
				world.setBlockState(pos, world.getBlockState(pos).with(RedstoneTransceiverBlock.POWERED, false), Block.NOTIFY_LISTENERS);
			} else {
				world.setBlockState(pos, world.getBlockState(pos).with(RedstoneTransceiverBlock.POWERED, true), Block.NOTIFY_LISTENERS);
			}
			world.updateNeighbors(pos, SpectrumBlocks.REDSTONE_TRANSCEIVER);
		}
	}

@Override
	public void triggerEvent(World world, GameEventListener listener, BlockPosEventQueue.EventEntry entry) {
		if (listener instanceof BlockPosEventQueue && this.getWorld() != null) {
			BlockPos eventPos = entry.eventSourceBlockPos;
			BlockState eventState = world.getBlockState(eventPos);
			if (eventState.isIn(SpectrumBlockTags.CRYSTAL_APOTHECARY_HARVESTABLE)) {
				// harvest
				LootContextParameterSet.Builder builder = new LootContextParameterSet.Builder((ServerWorld) world)
					.add(LootContextParameters.ORIGIN, Vec3d.ofCenter(eventPos))
					.add(LootContextParameters.TOOL, HARVEST_ITEMSTACK)
					.addOptional(LootContextParameters.THIS_ENTITY, getOwnerIfOnline())
					.addOptional(LootContextParameters.BLOCK_ENTITY, eventState.hasBlockEntity() ? this.getWorld().getBlockEntity(eventPos) : null);

				List<ItemStack> drops = eventState.getDroppedStacks(builder);
				boolean anyDropsUsed = drops.size() == 0;
				for (ItemStack drop : drops) {
					if (hasOwner()) {
						PlayerEntity owner = getOwnerIfOnline();
						if (owner instanceof ServerPlayerEntity serverPlayerEntity) {
							SpectrumAdvancementCriteria.CRYSTAL_APOTHECARY_COLLECTING.trigger(serverPlayerEntity, drop);
						}
					}
					ItemStack remainingStack = InventoryHelper.smartAddToInventory(drop, this, null);
					if (remainingStack.isEmpty() || drop.getCount() != remainingStack.getCount()) {
						anyDropsUsed = true;
					}
					// remaining items are voided to not cause lag
				}

				if (anyDropsUsed) {
					world.syncWorldEvent(WorldEvents.BLOCK_BROKEN, eventPos, Block.getRawIdFromState(eventState)); // block break particles & sound
					if (eventState.getBlock() instanceof Waterloggable && eventState.get(Properties.WATERLOGGED)) {
						world.setBlockState(eventPos, Blocks.WATER.getDefaultState());
					} else {
						world.setBlockState(eventPos, Blocks.AIR.getDefaultState());
					}
				} else {
					this.listenerPaused = true;
				}
			}
		}
	}

private static void compensateGemstoneClusterDropsForUnloadedTicks(World world, BlockPos blockPos, CrystalApothecaryBlockEntity blockEntity, long ticksToCompensate) {
		Map<Block, Integer> matches = new HashMap<>();

		// search for blocks in working range and sum them up
		Collection<Block> compensationBlocks = CrystalApothecarySimulationsDataLoader.COMPENSATIONS.keySet();
		for (BlockPos pos : BlockPos.iterateOutwards(blockPos, RANGE, RANGE, RANGE)) {
			if (!blockPos.isWithinDistance(pos, RANGE)) {
				continue;
			}

			BlockState state = world.getBlockState(pos);
			Block block = state.getBlock();
			if (compensationBlocks.contains(block)) {
				int validBlocks = countValidGemstoneClusterBlocksAroundBlockPos(world, pos, CrystalApothecarySimulationsDataLoader.COMPENSATIONS.get(block).validNeighbors());
				if (matches.containsKey(block)) {
					matches.put(block, matches.get(block) + validBlocks);
				} else {
					matches.put(block, validBlocks);
				}
			}
		}

		List<ItemStack> needsAwarding = new ArrayList<>();
		int totalNeedsAwarding = 0;

		// for each of those blocks generate some loot
		double gameRuleTickModifier = world.getGameRules().get(GameRules.RANDOM_TICK_SPEED).get() / 3.0;
		for (Map.Entry<Block, Integer> match : matches.entrySet()) {
			CrystalApothecarySimulationsDataLoader.SimulatedBlockGrowthEntry drop = CrystalApothecarySimulationsDataLoader.COMPENSATIONS.get(match.getKey());

			int compensatedItemCount = (int) (drop.compensatedStack().getCount() * match.getValue() * gameRuleTickModifier * ticksToCompensate) / drop.ticksForCompensationLootPerValidNeighbor();
			compensatedItemCount *= 0.8 + world.random.nextFloat() * 0.4;
			if (compensatedItemCount > 0) {
				ItemStack compensatedStack = drop.compensatedStack().copy();
				compensatedStack.setCount(compensatedItemCount);
				needsAwarding.add(compensatedStack);
				totalNeedsAwarding += compensatedItemCount;
			}
		}

		if (needsAwarding.size() <= 1) {
			for (ItemStack awardStack : needsAwarding) {
				InventoryHelper.smartAddToInventory(awardStack, blockEntity, null);
			}
			return;
		}

		for (int slot = 0; slot < blockEntity.size(); slot++) {
			if (totalNeedsAwarding <= 0) {
				break;
			}
			ItemStack currentStack = blockEntity.getStack(slot);
			if (currentStack.isEmpty()) {
				int selector = world.random.nextInt(totalNeedsAwarding);
				int acc = 0;
				for (ItemStack awardStack : needsAwarding) {
					acc += awardStack.getCount();
					if (selector < acc) {
						int maxCount = Math.min(blockEntity.getMaxCountPerStack(), awardStack.getMaxCount());
						int toAward = Math.min(maxCount, awardStack.getCount());
						ItemStack newStack = awardStack.copy();
						newStack.setCount(toAward);
						awardStack.decrement(toAward);
						blockEntity.setStack(slot, newStack);
						totalNeedsAwarding -= toAward;
						break;
					}
				}
			} else {
				int maxCount = Math.min(blockEntity.getMaxCountPerStack(), currentStack.getMaxCount());
				if (currentStack.getCount() > maxCount) {
					continue;
				}
				int wantsAdded = maxCount - currentStack.getCount();
				for (ItemStack awardStack : needsAwarding) {
					if (wantsAdded <= 0) {
						break;
					}
					if (ItemStack.canCombine(currentStack, awardStack)) {
						int canAdd = Math.min(wantsAdded, awardStack.getCount());
						awardStack.decrement(canAdd);
						currentStack.increment(canAdd);
						totalNeedsAwarding -= canAdd;
						wantsAdded -= canAdd;
					}
				}
			}
		}
	}

@Override
	public void triggerEvent(World world, GameEventListener listener, Object entry) {
		if (SpectrumChestBlock.isChestBlocked(world, pos)) {
			return;
		}

		if (entry instanceof ExperienceOrbEventQueue.EventEntry experienceEntry) {
			ExperienceOrbEntity experienceOrbEntity = experienceEntry.experienceOrbEntity;
			if (experienceOrbEntity != null && experienceOrbEntity.isAlive() && hasExperienceStorageItem()) {
				ExperienceStorageItem.addStoredExperience(this.inventory.get(EXPERIENCE_STORAGE_PROVIDER_ITEM_SLOT), experienceOrbEntity.getExperienceAmount()); // overflow experience is void, to not lag the world on large farms

				sendPlayExperienceOrbEntityAbsorbedParticle((ServerWorld) world, experienceOrbEntity);
				world.playSound(null, experienceOrbEntity.getBlockPos(), SoundEvents.ENTITY_EXPERIENCE_ORB_PICKUP, SoundCategory.BLOCKS, 0.9F + world.random.nextFloat() * 0.2F, 0.9F + world.random.nextFloat() * 0.2F);
				experienceOrbEntity.remove(Entity.RemovalReason.DISCARDED);
			}
		} else if (entry instanceof ItemEntityEventQueue.EventEntry itemEntry) {
			ItemEntity itemEntity = itemEntry.itemEntity;
			if (itemEntity != null && itemEntity.isAlive() && !itemEntity.cannotPickup() && this.acceptsItem(itemEntity.getStack().getItem())) {
				int previousAmount = itemEntity.getStack().getCount();
				ItemStack remainingStack = InventoryHelper.smartAddToInventory(itemEntity.getStack(), this, Direction.UP);

				if (remainingStack.isEmpty()) {
					sendPlayItemEntityAbsorbedParticle((ServerWorld) world, itemEntity);
					world.playSound(null, itemEntity.getBlockPos(), SoundEvents.ENTITY_ITEM_PICKUP, SoundCategory.BLOCKS, 0.9F + world.random.nextFloat() * 0.2F, 0.9F + world.random.nextFloat() * 0.2F);
					itemEntity.setStack(ItemStack.EMPTY);
					itemEntity.discard();
				} else {
					if (remainingStack.getCount() != previousAmount) {
						sendPlayItemEntityAbsorbedParticle((ServerWorld) world, itemEntity);
						world.playSound(null, itemEntity.getBlockPos(), SoundEvents.ENTITY_ITEM_PICKUP, SoundCategory.BLOCKS, 0.9F + world.random.nextFloat() * 0.2F, 0.9F + world.random.nextFloat() * 0.2F);
						itemEntity.setStack(remainingStack);
					}
				}
			}
		}
	}

@Override
    public void triggerEvent(World world, GameEventListener listener, HummingstoneEventQueue.EventEntry entry) {
        GameEvent.Message message = entry.message;

        if (message.getEvent() == SpectrumGameEvents.HUMMINGSTONE_HUMMING) {
