@Override
	public void applyUpdateEffect(LivingEntity entity, int amplifier) {
		long lastKillTick = LastKillComponent.getLastKillTick(entity);
		long worldTime = entity.getWorld().getTime();
		long lastKillTickDifference = worldTime - lastKillTick;
		boolean scoredKillInTime = lastKillTick >= 0 && lastKillTickDifference < REQUIRE_KILL_EVERY_X_TICKS;

		if (!scoredKillInTime && lastKillTickDifference % REQUIRE_KILL_EVERY_X_TICKS == 0) {
			updateAttributes(entity, amplifier, -1);
		}

		var potency = (SleepStatusEffect.getSleepScaling(entity) * (amplifier + 1) / 3) / 20;
		if (potency > 0 && entity.getHealth() > potency) {
			entity.damage(SpectrumDamageTypes.sleep(entity.getWorld(), null), potency);
		}
	}

@Override
	protected void onEntityHit(EntityHitResult entityHitResult) {
		super.onEntityHit(entityHitResult);

		Entity entity = entityHitResult.getEntity();

		if (EntityColorProcessorRegistry.colorEntity(entity, getInkColor().getDyeColor())) {
			entity.getWorld().playSoundFromEntity(null, entity, SoundEvents.ITEM_DYE_USE, SoundCategory.PLAYERS, 1.0F, 1.0F);
		}

		float velocity = (float) this.getVelocity().length();
		int damage = MathHelper.ceil(MathHelper.clamp((double) velocity * DAMAGE_PER_POTENCY * SPELL_POTENCY, 0.0D, 2.147483647E9D));

		Entity entity2 = this.getOwner();
		DamageSource damageSource;
		if (entity2 == null) {
			damageSource = SpectrumDamageTypes.inkProjectile(this, this);
		} else {
			damageSource = SpectrumDamageTypes.inkProjectile(this, entity2);
			if (entity2 instanceof LivingEntity) {
				((LivingEntity) entity2).onAttacking(entity);
			}
		}

		if (entity.damage(damageSource, (float) damage)) {
			if (entity instanceof LivingEntity livingEntity) {

				if (!this.getWorld().isClient() && entity2 instanceof LivingEntity) {
					EnchantmentHelper.onUserDamaged(livingEntity, entity2);
					EnchantmentHelper.onTargetDamaged((LivingEntity) entity2, livingEntity);
				}

				this.onHit(livingEntity);

				if (livingEntity != entity2 && livingEntity instanceof PlayerEntity && entity2 instanceof ServerPlayerEntity && !this.isSilent()) {
					((ServerPlayerEntity) entity2).networkHandler.sendPacket(new GameStateChangeS2CPacket(GameStateChangeS2CPacket.PROJECTILE_HIT_PLAYER, 0.0F));
				}

				if (!this.getWorld().isClient() && entity2 instanceof ServerPlayerEntity serverPlayerEntity) {
					if (!entity.isAlive()) {
						SpectrumAdvancementCriteria.KILLED_BY_INK_PROJECTILE.trigger(serverPlayerEntity, List.of(entity));
					}
				}
			}

			this.playSound(this.getHitSound(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
			this.discard();
		} else {
			this.setVelocity(this.getVelocity().multiply(-0.1D));
			this.setYaw(this.getYaw() + 180.0F);
			this.prevYaw += 180.0F;
			if (!this.getWorld().isClient() && this.getVelocity().lengthSquared() < 1.0E-7D) {
				this.discard();
			}
		}
	}

@Override
	public void tick() {
		super.tick();

		age++;
		if (this.getWorld().isClient() && age > DECELERATION_PHASE_LENGTH - 1 && getVelocity().length() > 0.075) {
			if (getVelocity().length() > 0.2 || this.getWorld().getTime() % 2 == 0)
				this.getWorld().addParticle(SpectrumParticleTypes.LIGHT_TRAIL, true, prevX, prevY, prevZ, 0, 0, 0);
		}

		if (age > getMaxAge()) {
			playSound(SpectrumSoundEvents.SOFT_HUM, random.nextFloat() + 0.25F, 1F + random.nextFloat());
			this.remove(RemovalReason.DISCARDED);
		}

		var velocity = getVelocity();
		updatePosition(getX() + velocity.getX(), getY() + velocity.getY(), getZ() + velocity.getZ());

		if (age < DECELERATION_PHASE_LENGTH) {
			var deceleration = Math.max((float) age / DECELERATION_PHASE_LENGTH, 0.5);
			setVelocity(
					MathHelper.lerp(deceleration, initialVelocity.x, 0),
					MathHelper.lerp(deceleration, initialVelocity.y, 0),
					MathHelper.lerp(deceleration, initialVelocity.z, 0)
			);
			velocityDirty = true;
			scheduleVelocityUpdate();
			return;
		}

		var hitResult = ProjectileUtil.getCollision(this, this::canHit);
		onCollision(hitResult);

		if (this.targetEntity.isEmpty() || !isValidTarget(targetEntity.get())) {
			World world = this.getWorld();
			if (world.isClient)
				return;

			if (random.nextFloat() > 0.25)
				return;

			findSuitableTargets((ServerWorld) this.getWorld());
		}

		if (this.targetEntity.isPresent() && isValidTarget(targetEntity.get())) {
			var entity = targetEntity.get();

			var transformVector = entity
					.getPos()
					.add(0, entity.getHeight() / 2, 0)
					.subtract(getPos())
					.normalize();

			var accelerationVector = transformVector.multiply(DEFAULT_ACCELERATION);
			addVelocity(accelerationVector.x, accelerationVector.y, accelerationVector.z);
		}
	}

@Override
	protected boolean tryPickup(PlayerEntity player) {
		if (player != getOwner()) {
			player.damage(getDamageSources().thorns(this), 20);
			playSound(SoundEvents.ENCHANT_THORNS_HIT, 1, 0.9F + random.nextFloat() * 0.2F);
			return false;
		}

		var rootStack = DraconicTwinswordItem.findThrownStack(player, uuid);
		if (!rootStack.isEmpty()) {
			if (this.getWorld().isClient())
				return true;

			SpectrumItems.DRACONIC_TWINSWORD.markReserved(rootStack, false);
			player.sendPickup(this, 1);
			player.playSound(SoundEvents.ENTITY_ITEM_PICKUP, 1, 1);
			discard();
			return true;
		} else {
			discard();
		}
		return false;
	}

