public void tick(@NotNull BlockState pState, ServerLevel pLevel, @NotNull BlockPos pPos, @NotNull RandomSource pRandom) {
        pLevel.scheduleTick(pPos, this, getFireTickDelay(pLevel.random));
        if (pLevel.getGameRules().getBoolean(GameRules.RULE_DOFIRETICK)) {
            BlockState blockstate = pLevel.getBlockState(pPos.below());
            boolean fireSourceBelow = blockstate.isFireSource(pLevel, pPos, Direction.UP);
            int age = pState.getValue(AGE);
            if (!fireSourceBelow && pLevel.isRaining() && this.isNearRain(pLevel, pPos) && pRandom.nextFloat() < 0.2F + (float) age * 0.064F) {
                pLevel.removeBlock(pPos, false);
            } else {
                int j = Math.min(MAX_AGE, age + pRandom.nextInt(3) / 2);
                if (age != j) {
                    pState = pState.setValue(AGE, j);
                    pLevel.setBlock(pPos, pState, 4);
                }

                if (!fireSourceBelow) {
                    if (!this.isValidFireLocation(pLevel, pPos)) {
                        BlockPos blockpos = pPos.below();
                        if (!pLevel.getBlockState(blockpos).isFaceSturdy(pLevel, blockpos, Direction.UP) || age > 3) {
                            pLevel.removeBlock(pPos, false);
                        }

                        return;
                    }

                    if (age == MAX_AGE && pRandom.nextInt(2) == 0 && !this.canCatchFire(pLevel, pPos.below(), Direction.UP)) {
                        pLevel.removeBlock(pPos, false);
                        return;
                    }
                }
            }
        }
    }

@Override
	public void onUpdate() {
		// super.onUpdate();
		if (!getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime() % 5 == 0) {
			if (!getHasExploded())
				checkArea();
			if (getHasExploded())
				checkAreaOfEffect();
		}

		if (!getEntityWorld().isRemote) {
			if (!getSwelling() && getSwellCount() > MIN_SWELL)
				setSwellCount(getSwellCount() - 1);

			if (getSwelling() && getSwellCount() < MAX_SWELL)
				setSwellCount(getSwellCount() + 1);

			if(getHasExploded()) {
				if (getSwellCount() < MAX_SWELL)
					setSwellCount(MAX_SWELL);
				if (getAOESizeXZ() > 0.5F)
					setAOESizeXZ(getAOESizeXZ() - 0.01F);
				if (getAOESizeXZ() <= 0.5F)
					setDead();
			}
		}

		if (getHasExploded())
			setBoundingBoxSize();

		if (getEntityWorld().isRemote)
			if(getHasExploded())
				spawnCloudParticle();
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (level.isClientSide() || nextCheckTime > level.getGameTime()) {
			return;
		}

		if (remainingApplyTime > 0) {
			remainingApplyTime--;
			if (remainingApplyTime <= 0) {
				if (defBeingApplied.hasItemUseEffects()) {
					triggerItemUseEffects(level);
				}
				applying = false;
				ItemStack remainingStack = defBeingApplied.finishUsing.apply(stackBeingAplied, applyingToEntity);
				stackBeingAplied = ItemStack.EMPTY;
				applyingToEntity = null;
				defBeingApplied = null;
				storageWrapper.getInventoryForUpgradeProcessing().insertItem(remainingStack, false);
				nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
			} else if (shouldTriggerItemUseEffects()) {
				triggerItemUseEffects(level);
			}
			return;
		}

		if (entity instanceof LivingEntity livingEntity) {
			applyTo(livingEntity);
		} else {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, new AABB(pos).inflate(CHECK_RADIUS), this::entityMatches);
			for (LivingEntity livingEntity : entities) {
				applyTo(livingEntity);
				if (applying) {
					break;
				}
			}
		}
		if (!applying) {
			nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
		}
	}

@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        Player player = commonArmorHandler.getPlayer();

        if (player.level().isClientSide || player.isSpectator() || !enabled
                || (player.level().getGameTime() & 0x3) != 0
                || !commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST))
            return;

        int magnetRadius = PneumaticValues.MAGNET_BASE_RANGE
                + Math.min(commonArmorHandler.getUpgradeCount(EquipmentSlot.CHEST, ModUpgrades.MAGNET.get()), PneumaticValues.MAGNET_MAX_UPGRADES);
        int magnetRadiusSq = magnetRadius * magnetRadius;

        AABB box = new AABB(player.blockPosition()).inflate(magnetRadius);
        List<Entity> itemList = player.getCommandSenderWorld().getEntitiesOfClass(Entity.class, box,
                e -> (e instanceof ExperienceOrb || e instanceof ItemEntity) && e.isAlive());

        Vec3 playerVec = player.position();
        for (Entity item : itemList) {
            if (item instanceof ItemEntity && ((ItemEntity) item).hasPickUpDelay()) continue;

            if (item.position().distanceToSqr(playerVec) <= magnetRadiusSq
                    && !ItemRegistry.getInstance().shouldSuppressMagnet(item)
                    && !item.getPersistentData().getBoolean(Names.PREVENT_REMOTE_MOVEMENT)) {
                if (!commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST)) break;
                item.setPos(player.getX(), player.getY(), player.getZ());
                if (item instanceof ItemEntity) ((ItemEntity) item).setPickUpDelay(0);
                commonArmorHandler.addAir(EquipmentSlot.CHEST, -ConfigHelper.common().armor.magnetAirUsage.get());
            }
        }
    }

public void tick(Level level, BlockPos pos, BlockState state) {
        if (redstonePower > 0 && level.getGameTime() % tickrate() == 0 && level.hasNeighborSignal(pos) && isFunctional()) {
            BlockPos targetPos = pos.below(2);
            BlockState targetState = level.getBlockState(targetPos);

            HammerHeadBlockEntity head = TileEntityOptional.from(level, pos.below(), HammerHeadBlockEntity.class).orElse(null);

            if (head == null || head.isJammed()) {
                return;
            }

            CastOptional.cast(targetState.getBlock(), IInteractiveBlock.class)
                    .map(block -> block.getPotentialInteractions(level, targetPos, targetState, Direction.UP, Collections.singletonList(TetraToolActions.hammer)))
                    .stream()
                    .flatMap(Arrays::stream)
                    .filter(interaction -> TetraToolActions.hammer.equals(interaction.requiredTool))
                    .filter(interaction -> getHammerLevel() >= interaction.requiredLevel)
                    .findFirst()
                    .ifPresent(interaction -> {
                        interaction.applyOutcome(level, targetPos, targetState, null, null, Direction.UP);

                        // the workbench triggers the hammer on the server side, so no need to consume fuel and play sounds
                        if (!(targetState.getBlock() instanceof AbstractWorkbenchBlock)) {
                            if (!level.isClientSide) {
                                consumeFuel();
                            } else {
                                head.activate();
                                level.playSound(null, pos, SoundEvents.ANVIL_LAND, SoundSource.BLOCKS, 0.2f, (float) (0.5 + Math.random() * 0.2));
                            }
                        } else {
                            head.activate();
                        }
                    });
        }
    }

public void tick() {
        if (this.level != null) {
            if (this.level.getBlockState(this.getBlockPos()).getBlock() instanceof WindBlowerBlock){
                Direction facing = this.level.getBlockState(this.getBlockPos()).getValue(WindBlowerBlock.FACING);
                double power = this.level.getBlockState(this.getBlockPos()).getValue(WindBlowerBlock.POWER);
                boolean active = power > 0;
                if (this.level.getBlockEntity(this.worldPosition) instanceof WindBlowerBlockEntity fan) {
                    if (this.level.getGameTime() % 2 == 0 && this.level.getBlockState(this.worldPosition).getBlock() instanceof WindBlowerBlock){
                        if (active) {
                            fan.blowEntities();
                        }
                    }
                    if (!this.level.isClientSide) {
                        this.level.sendBlockUpdated(this.getBlockPos(), this.level.getBlockState(this.getBlockPos()), this.level.getBlockState(this.getBlockPos()), 8);
                    }
                    //Particle codes based of Create mod's Air Flow Particle: https://github.com/Creators-of-Create/Create/blob/mc1.18/dev/src/main/java/com/simibubi/create/content/kinetics/fan/AirFlowParticle.java
                    if (this.level.isClientSide){
                        if (active && this.level.random.nextFloat() <= 0.25F) {
                            Vec3 pos = getCenterOf(this.getBlockPos()).add(Vec3.atLowerCornerOf(facing.getNormal()).scale(0.5D));
                            Vec3 direction = Vec3.atLowerCornerOf(facing.getNormal());
                            Vec3 motion = direction.scale(1 / 8.0F);
                            double distance = new Vec3(this.getBlockPos().getX(), this.getBlockPos().getY(), this.getBlockPos().getZ()).subtract(getCenterOf(this.getBlockPos())).multiply(direction).length() - 0.5F;
                            motion = motion.scale(power - (distance - 1.0F)).scale(0.5F);
                            this.level.addParticle(ModParticleTypes.FAN_CLOUD.get(), pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
                            pos = pos.offsetRandom(this.level.getRandom(), 1.01F);
                            int width = this.level.getRandom().nextIntBetweenInclusive(1, 4);
                            float height = this.level.getRandom().nextFloat() * 0.5F;
                            this.level.addParticle(new WindBlowParticleOption(ColorUtil.WHITE, width, height), pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
                        }
                    }
                }
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(WindBlowerBlock.POWERED, active), 3);
            }
        }
    }

@Override
    protected void tick(E entity) {
        var treePos = BrainUtil.getMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get());
        if (NearestTreeSensor.isLog(entity.level(), treePos)) {
            BrainUtil.setMemory(entity, MemoryModuleType.LOOK_TARGET, new BlockPosTracker(treePos));
            this.breakingTime++;
            entity.swing(InteractionHand.MAIN_HAND, true);
            int i = (int) ((float) this.breakingTime / 160.0F * 10.0F);
            if (this.breakingTime % 20 == 0) {
                entity.playSound(SoundEvents.WOOD_HIT, 1, 1);
                entity.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1, 0.5F);
            }
            if (i != this.previousBreakProgress) {
                entity.level().destroyBlockProgress(entity.getId(), treePos, i);
                this.previousBreakProgress = i;
            }
            if (this.breakingTime == 160) {
                entity.playSound(SoundEvents.WOOD_BREAK, 1, 1);
                List<BlockPos> stump = new ArrayList<>(List.of());
                this.addAllStump(treePos, entity.level(), stump);
                this.fellTree(entity, treePos);
                var felled = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get());
                if (felled != null) {
                    felled.addAll(stump);
                } else {
                    felled = stump;
                }
                BrainUtil.setMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get(), felled);
                this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
                //we stop here (even though the above condition would save us) because sensor might reset last felled tree meanwhile
            }

        } else {
            //if the tree is gone, just stop and reset.
            this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
        }
    }

@Override
        public void tick() {
            // Every configured interval, see if we need to adjust muffling
            Level level = Minecraft.getInstance().level;
            if (level == null) {
                stop();
                return;
            }
            if (!MekanismUtils.isTickingNormally(level)) {
                //Mute it similar to how the minecart sound handling is
                volume = 0;
            } else if (level.getGameTime() % checkInterval == 0) {
                if (!isClientPlayerInRange(this)) {
                    //If the player is not in range of hearing this sound anymore; go ahead and shutdown
                    stop();
                    return;
                }
                // Run the event bus with the original sound. Note that we must make sure to set the GLOBAL/STATIC
                // flag that ensures we don't wrap already muffled sounds. This is...NOT ideal and makes some
                // significant (hopefully well-informed) assumptions about locking/ordering of all these calls.
                IN_MUFFLED_CHECK = true;
                //Make sure we set our volume back to what it actually would be for purposes of letting other mods know
                // what volume to use
                volume = originalVolume;
                SoundInstance s = soundEngine == null ? null : ClientHooks.playSound(soundEngine, this);
                IN_MUFFLED_CHECK = false;

                if (s == this) {
                    // No filtering done, use the original sound's volume
                    volume = originalVolume * getTileVolumeFactor();
                } else if (s == null) {
                    // Full on mute; go ahead and shutdown
                    stop();
                } else {
                    // Altered sound returned; adjust volume
                    volume = s.getVolume() * getTileVolumeFactor();
                }
            }
        }

@Override
    public void tick() {
        super.tick();
        if (this.cropPos.isPresent()) {
            BlockPos blockpos = this.cropPos.get();
            if (blockpos.closerToCenterThan(this.servant.position(), 2.0D)){
                if (this.servant.level.getGameTime() >= this.nextWorkCycleTime) {
                    ItemStack itemstack = ItemStack.EMPTY;
                    SimpleContainer simplecontainer = this.servant.getInventory();
                    int i = simplecontainer.getContainerSize();

                    for (int j = 0; j < i; ++j) {
                        ItemStack itemstack1 = simplecontainer.getItem(j);
                        if (itemstack1.is(Items.BONE_MEAL)) {
                            itemstack = itemstack1;
                            break;
                        }
                    }

                    if (!itemstack.isEmpty() && BoneMealItem.growCrop(itemstack, this.servant.level, blockpos)) {
                        this.servant.level.levelEvent(1505, blockpos, 0);
                        itemstack.shrink(1);
                        if (this.servant.getMainHandItem().is(Items.BONE_MEAL)) {
                            this.servant.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                        } else if (this.servant.getOffhandItem().is(Items.BONE_MEAL)){
                            this.servant.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                        }
                        this.cropPos = this.pickNextTarget(this.servant.level, this.servant);
                        this.setCurrentCropAsTarget(this.servant);
                        this.nextWorkCycleTime = this.servant.level.getGameTime() + 40L;
                    }

                    ++this.timeWorkedSoFar;
                }
            } else {
                this.servant.getLookControl().setLookAt(blockpos.getCenter());
                this.servant.getNavigation().moveTo(blockpos.getCenter().x(), blockpos.getCenter().y(), blockpos.getCenter().z(), 1.0F);
            }
        }
    }

