                int numBookwyrms = getConsumedItems().stream().filter(i -> i.getItem() instanceof WritableBookItem).mapToInt(ItemStack::getCount).sum();
                if (progress < numBookwyrms) {
                    ItemStack charm = new ItemStack(ItemsRegistry.BOOKWYRM_CHARM);
                    ItemEntity itemEntity = new ItemEntity(serverLevel, getPos().getX() + 0.5, getPos().getY() + 1, getPos().getZ() + 0.5, charm);
                    float range = 0.1f;
                    itemEntity.setDeltaMovement(ParticleUtil.inRange(-range, range), ParticleUtil.inRange(0.4, 0.6), ParticleUtil.inRange(-range, range));
                    serverLevel.playSound(null, getPos(), SoundEvents.BOOK_PAGE_TURN, SoundSource.BLOCKS, 1.0F, 1.0F);
                    serverLevel.addFreshEntity(itemEntity);
                } else {
                    setFinished();
                }
            } else {
                if (getProgress() > 5) {
                    findTargets(serverLevel);
                    if (entity != null) {
                        ParticleUtil.spawnPoof(serverLevel, foundPos);
                        LivingEntity walker = entity.create(serverLevel);
                        walker.setPos(foundPos.getX() + 0.5, foundPos.getY(), foundPos.getZ() + 0.5);
                        serverLevel.addFreshEntity(walker);
                        setFinished();
                    }
                }
            }
            incrementProgress();
        }
    }

@SubscribeEvent
        public static void initRegistries(FMLConstructModEvent event)
        {
            event.enqueueWork(() ->
            {
                if (REGISTRIES_INITIALIZED) return;

                ColdSweat.LOGGER.info("Gathering Cold Sweat registries");
                // Gather modded registries
                AddRegistriesEvent addRegistriesEvent = new AddRegistriesEvent();

                // Check if the event bus is closed
                boolean busWasClosed = !MinecraftForge.EVENT_BUS.post(new ProbeEventBusEvent());
                // Start the event bus temporarily
                MinecraftForge.EVENT_BUS.start();
                // Post AddRegistriesEvent to the event bus
                MinecraftForge.EVENT_BUS.post(addRegistriesEvent);
                // Re-close the event bus if it was closed before
                if (busWasClosed)
                {
                    ColdSweat.LOGGER.info("The event bus was started early to gather Cold Sweat registries; it will now be stopped again until the correct loading phase.");
                    try
                    {   Field shutdown = EventBus.class.getDeclaredField("shutdown");
                        shutdown.setAccessible(true);
                        shutdown.set(MinecraftForge.EVENT_BUS, true);
                    }
                    catch (Exception e)
                    {   ColdSweat.LOGGER.error("Failed to re-shutdown the event bus after gathering Cold Sweat registries", e);
                    }
                }

                // Add registries via dummy NewRegistry event
                DataPackRegistryEvent.NewRegistry dummyEvent = new DataPackRegistryEvent.NewRegistry();
                for (RegistryHolder holder : ModRegistries.getRegistries().values())
                {   dummyEvent.dataPackRegistry(holder.key(), holder.codec(), holder.codec());
                }
                try
                {   Method process = DataPackRegistryEvent.NewRegistry.class.getDeclaredMethod("process");
                    process.setAccessible(true);
                    process.invoke(dummyEvent);
                }
                catch (Exception ignored) {}

                REGISTRIES_INITIALIZED = true;
            });
        }

@Override
    public @Nullable StarbyState tick() {
        if (dest == null) {
            behavior.findItemBackoff = 30 + starbuncle.level.random.nextInt(30);
            starbuncle.addGoalDebug(this, new DebugEvent("NotReachable", "No pathable items nearby"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }

        if (behavior.isPickupDisabled())
            return new DecideStarbyActionState(starbuncle, behavior);
        ItemStack itemstack = starbyWithSpace.getHeldStack();
        if (!itemstack.isEmpty()) {
            starbuncle.addGoalDebug(this, new DebugEvent("ItemPickup", "Received item, ending."));
            starbuncle.getNavigation().stop();
            Starbuncle nextAvailableStarby = starbuncle.getStarbuncleWithSpace();
            List<ItemEntity> nearbyItems = FindItemState.nearbyItems(starbuncle, behavior);
            if (nextAvailableStarby != null && !nearbyItems.isEmpty()) {
                return new FindItemState(starbuncle, behavior, nearbyItems);
            }
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (ticksRunning > 20 * 15) {
            starbuncle.addGoalDebug(this, new DebugEvent("TooLong", "Stopped finding item, time finding expired"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (itemStuck || this.starbyWithSpace == null) {
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (dest == null || dest.getItem().isEmpty() || dest.isRemoved()) {
            itemStuck = true;
            starbuncle.addGoalDebug(this, new DebugEvent("ItemRemoved", "Item removed during goal"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        starbuncle.minecraftPathNav.stop();
        Path path = starbuncle.minecraftPathNav.createPath(BlockPos.containing(dest.position()), 1, 9);
        if (path == null || !path.canReach()) {
            stuckTicks++;
            if (stuckTicks > 20 * 5) { // Give up after 5 seconds of being unpathable, in case we fall or jump into the air
                itemStuck = true;
                starbuncle.addGoalDebug(this, new DebugEvent("ItemStuck", "Item stuck for 5 seconds. Ending goal"));
            }
            return super.tick();
        }

        starbuncle.getNavigation().moveTo(dest, 1.4d);
        starbuncle.addGoalDebug(this, new DebugEvent("PathTo", "Pathing to " + dest));
        return super.tick();
    }

