@Override
    public void tick() {
        if (attackTime > 0) {
            attackTime--;
        } else {
            LivingEntity target = entity.getTarget();
            if (target != null) {
                double d0 = this.entity.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
                boolean canSee = this.entity.getSensing().hasLineOfSight(target);
                boolean couldSee = this.seeTime > 0;

                if (canSee != couldSee) {
                    this.seeTime = 0;
                }

                if (canSee) {
                    ++this.seeTime;
                    this.entity.lookAt(target, 19.0F, 10.0F);


                    this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition(1.0F));
                } else {
                    --this.seeTime;
                }

                if (d0 <= (double) this.maxAttackDistance && this.seeTime >= 20) {
                    attack(target);
                    this.attackTime = attackCooldown;
                    entity.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 20));


                } else {
                    this.entity.getNavigation().moveTo(target, 1.0);

                }
            }
        }
    }

@Override
	public void tick() {
		double targetDistance = this.taskOwner.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
		boolean canSeeTarget = this.taskOwner.getSensing().hasLineOfSight(this.target);

		if (canSeeTarget) {
			++this.seeTime;
		}
		else {
			this.seeTime = 0;
		}

		if (!(targetDistance > (double)this.attackRadius * this.attackRadius) && this.seeTime >= 5) {
			this.taskOwner.getNavigation().stop();
		}
		else {
			this.taskOwner.getNavigation().moveTo(this.target, this.speedModifier);
		}

		this.taskOwner.getLookControl().setLookAt(this.target, 30f, 30f);

		if (--this.attackTime <= 0 && this.attackTime >= -preAttackTime) {
			if (!canSeeTarget)
				return;

			if (this.attackTime == 0)
				this.taskOwner.swing(InteractionHand.MAIN_HAND);

			if (this.attackTime == -preAttackTime) {
				float distMod = (float)Math.sqrt(targetDistance) / this.attackRadius;
				float distFactor = Mth.clamp(distMod, 0.1f, 1);

				this.taskOwner.performRangedAttack(this.target, distFactor);
				this.attackTime = Mth.floor(distMod * (float)(this.attackCooldownMax - this.attackCooldownMin) + (float)this.attackCooldownMin);
			}
		}
		else if (this.attackTime < 0) {
			this.attackTime = Mth.floor(Mth.lerp(Math.sqrt(targetDistance) / (double)this.attackRadius, this.attackCooldownMin, this.attackCooldownMax));
		}
	}

public void onUpdate(){

		if(this.ticksExisted % 40 == 1){
			this.playSound(WizardrySounds.ENTITY_FIRE_RING_AMBIENT, 4.0f, 0.7f);
		}

		super.onUpdate();

		if(this.ticksExisted % 5 == 0 && !this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY, this.posZ, this.height, this.world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					double velX = target.motionX;
					double velY = target.motionY;
					double velZ = target.motionZ;

					if(!MagicDamage.isEntityImmune(DamageType.FIRE, target)){

						target.setFire(Spells.ring_of_fire.getProperty(Spell.BURN_DURATION).intValue());

						float damage = Spells.ring_of_fire.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

						if(this.getCaster() != null){
							target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
									DamageType.FIRE), damage);
						}else{
							target.attackEntityFrom(DamageSource.MAGIC, damage);
						}
					}

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;
				}
			}
		}
	}

@Override
	public void onUpdate(){

		super.onUpdate();

		if(!this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY, this.posZ, this.height, this.world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					double velX = target.motionX;
					double velY = target.motionY;
					double velZ = target.motionZ;

					target.attackEntityFrom(this.getCaster() != null
							? MagicDamage.causeIndirectMagicDamage(this, this.getCaster(), DamageType.FIRE)
							: DamageSource.MAGIC, Spells.fire_sigil.getProperty(Spell.DAMAGE).floatValue()
							* damageMultiplier);

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;

					if(!MagicDamage.isEntityImmune(DamageType.FIRE, target))
						target.setFire(Spells.fire_sigil.getProperty(Spell.BURN_DURATION).intValue());

					this.playSound(WizardrySounds.ENTITY_FIRE_SIGIL_TRIGGER, 1, 1);

					// The trap is destroyed once triggered.
					this.setDead();
				}
			}
		}else if(this.rand.nextInt(15) == 0){
			double radius = (0.5 + rand.nextDouble() * 0.3) * width/2;
			float angle = rand.nextFloat() * (float)Math.PI * 2;
			world.spawnParticle(EnumParticleTypes.FLAME, this.posX + radius * MathHelper.cos(angle), this.posY + 0.1,
					this.posZ + radius * MathHelper.sin(angle), 0, 0, 0);
		}
	}

private static int update(EntityPlayer player, Integer chargeTime){

		if(chargeTime == null) chargeTime = 0;

		if(chargeTime > 0){

			SpellModifiers modifiers = WizardData.get(player).getVariable(CHARGE_MODIFIERS);
			if(modifiers == null) modifiers = new SpellModifiers();

			Vec3d look = player.getLookVec();

			float speed = Spells.charge.getProperty(Charge.CHARGE_SPEED).floatValue() * modifiers.get(WizardryItems.range_upgrade);

			player.motionX = look.x * speed;
			player.motionZ = look.z * speed;

			if(player.world.isRemote){
				for(int i = 0; i < 5; i++){
					ParticleBuilder.create(Type.SPARK, player).spawn(player.world);
				}
			}

			List<EntityLivingBase> collided = player.world.getEntitiesWithinAABB(EntityLivingBase.class, player.getEntityBoundingBox().grow(EXTRA_HIT_MARGIN));

			collided.remove(player);

			float damage = Spells.charge.getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY);
			float knockback = Spells.charge.getProperty(KNOCKBACK_STRENGTH).floatValue();

			collided.forEach(e -> e.attackEntityFrom(MagicDamage.causeDirectMagicDamage(player, MagicDamage.DamageType.SHOCK), damage));
			collided.forEach(e -> e.addVelocity(player.motionX * knockback, player.motionY * knockback + 0.3f, player.motionZ * knockback));

			if(player.world.isRemote) player.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE,
					player.posX + player.motionX, player.posY + player.height/2, player.posZ + player.motionZ, 0, 0, 0);

			if(collided.isEmpty()) chargeTime--;
			else{
				EntityUtils.playSoundAtPlayer(player, SoundEvents.ENTITY_GENERIC_HURT, 1, 1);
				chargeTime = 0;
			}
		}

		return chargeTime;
	}

@Override
        public void tick(LivingEntity entity) {
            if(isCharge()) {
                if (!entity.level().isClientSide()) {
                    int temp = getTimer();
                    setTimer(temp - 1);
                    //Deal with rocket punch is valid
                    if (temp > 0) {
                        //Slightly enlarge player's hitbox
                        AABB collideBox = entity.getBoundingBox().inflate(0.75f, 0.75f, 0.75f);

                        //Collision Detection
                        List<LivingEntity> checks = entity.level().getEntitiesOfClass(LivingEntity.class, collideBox);
                        checks.remove(entity);

                        //If any mob is detected
                        if (!checks.isEmpty()) {
                            // spawn an watchEntity to simulate rocket punch effect
                            Wall_Watcher_Entity watchEntity = new Wall_Watcher_Entity(entity.level(), entity.blockPosition(), temp, effectiveChargeTime,
                                    knockbackSpeedIndex, damagePerEffectiveCharge, dx, dz,
                                    entity);

                            List<LivingEntity> impact = entity.level().getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(3.5f, 0.75f, 3.5f));
                            impact.remove(entity);

                            for (LivingEntity target : impact) {
                                // Deal damage
                                if (!target.isAlliedTo(entity)) {
                                    boolean flag = target.hurt(entity.damageSources().mobProjectile(entity, entity), damagePerEffectiveCharge * effectiveChargeTime);
                                    watchEntity.watch(target);
                                    if (flag) {
                                        target.playSound(SoundEvents.ANVIL_LAND, 1.5f, 0.8F);
                                    }

                                }
                            }
                            entity.level().addFreshEntity(watchEntity);

                            // Player stop moving and clear pocket punch status
                            entity.setDeltaMovement(0, 0, 0);
                            entity.hurtMarked = true;
                            setCharge(false);
                        }
                    }
                    if (entity.horizontalCollision || temp == 0) {
                        setCharge(false);
                    }
                }
            }
        }

@Override
    public void tick() {
        super.tick();
        if (!level().isClientSide()) {
            int temp = entityData.get(TIMER);
            if (watchedEntities != null && source != null) {
                if (!watchedEntities.isEmpty()) {
                    List<YUnchangedLivingEntity> entitiesRemoveFromWatchList = new ArrayList<>();
                    for (YUnchangedLivingEntity entity : watchedEntities) {
                        if (entity.livingEntity.horizontalCollision) {
                            if (!entity.livingEntity.isAlliedTo(source)) {
                                entity.livingEntity.invulnerableTime = 0;
                                float realDamageApplied = damagePerEffectiveCharge * effectiveChargeTime + 1;
                                boolean flag = entity.livingEntity.hurt(this.damageSources().mobProjectile(this, source), realDamageApplied);
                                if (flag) {
                                    entity.livingEntity.playSound(ModSounds.EXPLOSION.get(), 0.3F, 1);
                                    entity.livingEntity.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), 50));
                                }
                            }

                            entitiesRemoveFromWatchList.add(entity);
                        } else {
                            entity.setMotion(dx * knockbackSpeedIndex, dz * knockbackSpeedIndex);
                        }
                    }
                    for (YUnchangedLivingEntity remove : entitiesRemoveFromWatchList) {
                        removeFromWatchList(remove);
                    }
                    if (temp - 1 == 0) {
                        watchedEntities.clear();
                        remove(RemovalReason.DISCARDED);
                    } else entityData.set(TIMER, temp - 1);
                } else {
                    if (temp - 1 == 0) remove(RemovalReason.DISCARDED);
                    else entityData.set(TIMER, temp - 1);
                }
            } else {
                remove(RemovalReason.DISCARDED);
            }
        }
    }

public void entityInside(BlockState pState, Level pLevel, BlockPos pPos, Entity pEntity) {
        if (pState.getValue(LIT)) {
            if (!pEntity.fireImmune()
                    && pEntity instanceof LivingEntity livingEntity
                    && livingEntity.getMobType() != MobType.UNDEAD
                    && !LichdomHelper.isInLichMode(livingEntity)
                    && !EnchantmentHelper.hasFrostWalker((LivingEntity) pEntity)
                    && pEntity.getY() >= pPos.getY() + 0.5F) {
                pEntity.hurt(pEntity.damageSources().inFire(), 1.0F);
            }
            BlockEntity tileentity = pLevel.getBlockEntity(pPos);
            if (tileentity instanceof NecroBrazierBlockEntity blockEntity) {
                if (pEntity instanceof ItemEntity itemEntity) {
                    if (!pLevel.isClientSide) {
                        if (itemEntity.isAlive() && !itemEntity.getItem().isEmpty() && !itemEntity.getTags().contains(ConstantPaths.resultItem())) {
                            if (blockEntity.currentTime <= 0) {
                                if (blockEntity.addItem(null, itemEntity.getItem())) {
                                    pLevel.playSound(null, pPos, SoundEvents.ITEM_PICKUP, SoundSource.BLOCKS, 1.0F, 1.0F);
                                    syncItem(itemEntity);
                                }
                            }
                        }
                    }
                }
            }
        }

        super.entityInside(pState, pLevel, pPos, pEntity);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        int particles = 5;
        int efficiency = 0;
        boolean damage = false;
        if (!this.level.isClientSide && !this.isEmerging()) {
            if (ModDamageSource.physicalAttacks(pSource)) {
                if (pSource.getDirectEntity() instanceof LivingEntity living) {
                    if (living.getMainHandItem().isCorrectToolForDrops(this.getState())){
                        damage = true;
                        efficiency += EnchantmentHelper.getBlockEfficiency(living);
                    }
                }
            }
            if (damage){
                pAmount *= 2.0F + (efficiency / 2.0F);
                particles = 20;
            }
            if (pSource.is(DamageTypeTags.IS_FIRE)){
                pAmount *= 2.0F;
            }
            if (!pSource.is(DamageTypes.STARVE)) {
                if (this.level instanceof ServerLevel serverLevel) {
                    for (int i = 0; i < particles; ++i) {
                        ServerParticleUtil.addParticlesAroundSelf(serverLevel, this.getParticles(), this);
                    }
                }
            }
        }
        return super.hurt(pSource, pAmount);
    }

public void damageEntities(Set<LivingEntity> entities){
        for (LivingEntity entity : entities) {
            DamageSource damageSource = ModDamageSource.directDrench(this);
            if (this.getTrueOwner() != null) {
                damageSource = ModDamageSource.indirectDrench(this, this.getTrueOwner());
            }
            boolean flag = entity.hurt(damageSource, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            if (flag) {
                this.level.playSound(null, entity.getX(), entity.getY(), entity.getZ(), ModSounds.WHIP_HIT.get(), this.getSoundSource(), 1.0F, this.getVoicePitch());
                if (this.isStaff) {
                    GulfTentacle gulfTentacle = new GulfTentacle(ModEntityType.GULF_TENTACLE.get(), this.level);
                    gulfTentacle.setPos(this.position());
                    if (this.getTrueOwner() != null) {
                        gulfTentacle.setRot(this.getTrueOwner().getYRot(), this.getTrueOwner().getXRot());
                        gulfTentacle.setTrueOwner(this.getTrueOwner());
                    } else {
                        gulfTentacle.setRot(this.getYRot(), this.getXRot());
                    }
                    gulfTentacle.setRange(this.getRange());
                    gulfTentacle.setOffset(this.offset);
                    if (this.hasEffect(GoetyEffects.BUFF.get())) {
                        gulfTentacle.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), EffectsUtil.getAmplifier(this, GoetyEffects.BUFF.get()), false, false));
                    }
                    gulfTentacle.setStaff(false);
                    this.level.addFreshEntity(gulfTentacle);
                    gulfTentacle.playSound(ModSounds.WHIP_SWING.get());
                }
            }
        }
    }

