@Override
    public ActionResult onItemRightClick(ItemStack itemStackIn, World worldIn, EntityPlayer playerIn, EnumHand hand) {
        if (hand == EnumHand.MAIN_HAND) {
            double range = 64;
            double timer = MuseItemUtils.getDoubleOrZero(itemStackIn, TIMER);
            double energyConsumption = ModuleManager.computeModularProperty(itemStackIn, ENERGY);
            if (ElectricItemUtils.getPlayerEnergy(playerIn) > energyConsumption && timer == 0) {
                ElectricItemUtils.drainPlayerEnergy(playerIn, energyConsumption);
                MuseItemUtils.setDoubleOrRemove(itemStackIn, TIMER, 10);
                MuseHeatUtils.heatPlayer(playerIn, ModuleManager.computeModularProperty(itemStackIn, HEAT));
                RayTraceResult hitMOP = MusePlayerUtils.doCustomRayTrace(playerIn.worldObj, playerIn, true, range);
                // TODO: actual railgun sound
                worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ARROW_SHOOT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
                double damage = ModuleManager.computeModularProperty(itemStackIn, IMPULSE) / 100.0;
                double knockback = damage / 20.0;
                Vec3d lookVec = playerIn.getLookVec();
                if (hitMOP != null) {
                    switch (hitMOP.typeOfHit) {
                        case ENTITY:
                            drawParticleStreamTo(playerIn, worldIn, hitMOP.hitVec.xCoord, hitMOP.hitVec.yCoord, hitMOP.hitVec.zCoord);
                            DamageSource damageSource = DamageSource.causePlayerDamage(playerIn);
                            if (hitMOP.entityHit.attackEntityFrom(damageSource, (int) damage)) {
                                hitMOP.entityHit.addVelocity(lookVec.xCoord * knockback, Math.abs(lookVec.yCoord + 0.2f) * knockback, lookVec.zCoord
                                        * knockback);
                            }
                            break;
                        case BLOCK:
                            drawParticleStreamTo(playerIn, worldIn, hitMOP.hitVec.xCoord, hitMOP.hitVec.yCoord, hitMOP.hitVec.zCoord);
                            break;
                        default:
                            break;
                    }
                    playerIn.addVelocity(-lookVec.xCoord * knockback, Math.abs(-lookVec.yCoord + 0.2f) * knockback, -lookVec.zCoord * knockback);

                    worldIn.playSound(playerIn, playerIn.getPosition(), SoundEvents.ENTITY_ARROW_SHOOT, SoundCategory.PLAYERS, 0.5F, 0.4F / ((float) Math.random() * 0.4F + 0.8F));
                }
                playerIn.setActiveHand(hand);
                return new ActionResult(EnumActionResult.SUCCESS, itemStackIn);
            }
        }
        return new ActionResult(EnumActionResult.PASS, itemStackIn);
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
        float damage = SpellConfig.SonicBoomDamage.get().floatValue() * WandUtil.damageMultiply();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)){
            damage += WandUtil.getPotencyLevel(caster);
            range += WandUtil.getRangeLevel(caster);
        }
        damage += spellStat.getPotency();
        LivingEntity livingEntity = this.getTarget(caster, range);
        if (livingEntity != null){
            Vec3 vec3 = caster.position().add(0.0D, (double) 1.6F, 0.0D);
            Vec3 vec31 = livingEntity.getEyePosition().subtract(vec3);
            Vec3 vec32 = vec31.normalize();

            for (int i = 1; i < Mth.floor(vec31.length()) + 7; ++i) {
                Vec3 vec33 = vec3.add(vec32.scale((double) i));
                worldIn.sendParticles(ParticleTypes.SONIC_BOOM, vec33.x, vec33.y, vec33.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            }

            this.playSound(worldIn, caster, SoundEvents.WARDEN_SONIC_BOOM, 3.0F, 1.0F);
            livingEntity.hurt(caster.damageSources().sonicBoom(caster), damage);
            double d1 = 0.5D * (1.0D - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
            double d0 = 2.5D * (1.0D - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
            livingEntity.push(vec32.x() * d0, vec32.y() * d1, vec32.z() * d0);
        } else {
            Vec3 srcVec = new Vec3(caster.getX(), caster.getEyeY(), caster.getZ());
            Vec3 lookVec = caster.getViewVector(1.0F);
            Vec3 destVec = srcVec.add(lookVec.x * range, lookVec.y * range, lookVec.z * range);
            for(int i = 1; i < Math.floor(destVec.length()) + 7; ++i) {
                Vec3 vector3d2 = srcVec.add(lookVec.scale(i));
                worldIn.sendParticles(ParticleTypes.SONIC_BOOM, vector3d2.x, vector3d2.y, vector3d2.z, 1, 0.0D, 0.0D, 0.0D, 0.0D);
            }
            if (MobUtil.getSingleTarget(worldIn, caster, range, 3.0D) instanceof LivingEntity target1){
                target1.hurt(caster.damageSources().sonicBoom(caster), damage);
                double d0 = target1.getX() - caster.getX();
                double d1 = target1.getZ() - caster.getZ();
                double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                MobUtil.push(target1, d0 / d2 * 4.0D, 0.2D, d1 / d2 * 4.0D);
            }
        }
        this.playSound(worldIn, caster, SoundEvents.WARDEN_SONIC_BOOM, 3.0F, 1.0F);
    }

@Override
    public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.tickCount % 2 == 0) {
                if (this.level instanceof ServerLevel serverLevel) {
                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ModParticleTypes.FLY.get(), this);
                }
            }
            if (this.getTarget() != null) {
                this.navigation.moveTo(this.getTarget(), 7.0D);
            } else {
                Vec3 vec3 = LandRandomPos.getPos(this, 10, 7);
                if (vec3 == null){
                    vec3 = DefaultRandomPos.getPos(this, 10, 7);
                }
                if (vec3 != null){
                    this.navigation.moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                }
            }
            if (this.level.collidesWithSuffocatingBlock(this, this.getBoundingBox().move(0.0D, -1.0D, 0.0D))) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.02D, 0.0D));
            } else {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.008D, 0.0D));
            }
            if (!this.moveControl.hasWanted()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(0.95F, 1.0F, 0.95F));
            }
            float inflate = 2.0F - this.getBbWidth() * 0.5F;
            for (LivingEntity living : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(inflate))) {
                if (living != this && !MobUtil.areAllies(this, living) && SummonTargetGoal.predicate(this).test(living)) {
                    if (living.hurt(ModDamageSource.swarm(this, this.getTrueOwner()), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                        this.playSound(ModSounds.INSECT_SWARM_BITE.get(), 1.0F, this.getVoicePitch());
                        int speed = (int) ((this.getHealth() / this.getMaxHealth()) * 5);
                        living.invulnerableTime = Math.min(20, (20 - speed));
                        this.hurt(this.damageSources().starve(), 2.0F);
                        if (this.getTrueOwner() != null && CuriosFinder.hasWildRobe(this.getTrueOwner())){
                            living.addEffect(new MobEffectInstance(GoetyEffects.ACID_VENOM.get(), MathHelper.secondsToTicks(5)));
                        }
                    }
                }
            }
        }
    }

public ItemStack finishUsingItem(ItemStack pStack, Level pLevel, LivingEntity pEntityLiving) {
        super.finishUsingItem(pStack, pLevel, pEntityLiving);
        if (pEntityLiving instanceof Player player) {
            if (MainConfig.LichEnable.get()) {
                if (pLevel instanceof ServerLevel serverWorld) {
                    ILichdom lichdom = LichdomHelper.getCapability(player);
                    ISoulEnergy soulEnergy = SEHelper.getCapability(player);
                    boolean isLich = lichdom.getLichdom();
                    if (isLich) {
                        player.heal(20.0F);
                    } else {
                        if (serverWorld.getMoonBrightness() > 0.9F && serverWorld.isNight()) {
                            if (soulEnergy.getSEActive() && soulEnergy.getArcaBlock() != null) {
                                if (pEntityLiving instanceof ServerPlayer serverPlayer) {
                                    CriteriaTriggers.CONSUME_ITEM.trigger(serverPlayer, pStack);
                                    serverPlayer.awardStat(Stats.ITEM_USED.get(this));
                                }
                                lichdom.setLichdom(true);
                                lichdom.setLichMode(true);
                                LichdomHelper.sendLichUpdatePacket(player);
                                player.displayClientMessage(Component.translatable("info.goety.lichdom.success"), true);
                                player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 20, 1));
                                player.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 20, 1));
                                player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 0.5F);
                                player.playSound(SoundEvents.ZOMBIE_VILLAGER_CURE, 1.0F, 0.5F);
                                player.hurt(player.damageSources().wither(), 50.0F);
                            } else {
                                player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                                player.hurt(player.damageSources().wither(), 50.0F);
                            }
                        } else {
                            player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                            player.hurt(player.damageSources().wither(), 50.0F);
                        }
                    }
                    if (!player.getAbilities().instabuild) {
                        pStack.shrink(1);
                    }
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.lichdom.disable").withStyle(ChatFormatting.DARK_RED), false);
            }
        }
        return pStack.isEmpty() ? new ItemStack(Items.GLASS_BOTTLE) : pStack;
    }

@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker)
	{
		if (attacker instanceof FakePlayer)
			return false;

		if (target == null || attacker == null || attacker.getCommandSenderWorld().isClientSide || (attacker instanceof Player && !(attacker instanceof ServerPlayer)))
			return false;

		if (!target.canChangeDimensions())
			return false;

		if (target instanceof Player)
			return false;

		if (target.isBaby() && !(target instanceof Enemy))
			return false;

		if (!target.isAlive() || target.getHealth() < 0.5F)
			return false;

//		EntityEntry entityEntry = EntityRegistry.getEntry(target.getClass());
//		if (entityEntry == null)
//			return false;
		ResourceLocation id = ForgeRegistries.ENTITY_TYPES.getKey(target.getType());
		int lifeEssenceRatio = BloodMagicAPI.INSTANCE.getValueManager().getSacrificial().getOrDefault(id, ConfigManager.COMMON.entitySacrificeDefault.get());
//		int lifeEssenceRatio = 25;

		if (lifeEssenceRatio <= 0)
			return false;

		int lifeEssence = (int) (lifeEssenceRatio * target.getHealth());
//		if (target instanceof AnimalEntity)
//		{
//			lifeEssence = (int) (lifeEssence * (1 + PurificationHelper.getCurrentPurity((AnimalEntity) target)));
//		}

		if (target.isBaby())
		{
			lifeEssence *= 0.5F;
		}

		if (PlayerSacrificeHelper.findAndFillAltar(attacker.getCommandSenderWorld(), target, lifeEssence, true))
		{
			target.getCommandSenderWorld().playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (target.getCommandSenderWorld().random.nextFloat() - target.getCommandSenderWorld().random.nextFloat()) * 0.8F);
			target.setHealth(0.00001f);
			target.invulnerableTime = 0;
			target.hurt(target.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
//			target.onDeath(DamageSourceBloodMagic.INSTANCE);
		}

		return false;
	}

@Inject(method = "tryUseTotem", at = @At("RETURN"), cancellable = true)
	private void tryUseTotem(DamageSource source, CallbackInfoReturnable<Boolean> callbackInfo) {
		if (!getWorld().isClient) {
			if (!callbackInfo.getReturnValueZ()) {
				boolean isPlayer = (Object) this instanceof PlayerEntity;
				PoppetData poppetData = BewitchmentAPI.getPoppet(getWorld(), BWObjects.DEATH_PROTECTION_POPPET, this);
				if (!poppetData.stack().isEmpty() && !(isPlayer && ReviveEvents.CANCEL_REVIVE.invoker().shouldCancel((PlayerEntity) (Object) this, source, poppetData.stack()))) {
					if (isPlayer) {
						ReviveEvents.ON_REVIVE.invoker().onRevive((PlayerEntity) (Object) this, source, poppetData.stack());
					}
					boolean sync = false;
					if (poppetData.stack().damage((Object) this instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.WOLF && random.nextBoolean() ? 0 : 1, random, null) && poppetData.stack().getDamage() >= poppetData.stack().getMaxDamage()) {
						poppetData.stack().decrement(1);
						sync = true;
					}
					poppetData.update(getWorld(), sync);
					setHealth(1);
					clearStatusEffects();
					addStatusEffect(new StatusEffectInstance(StatusEffects.REGENERATION, 900, 1));
					addStatusEffect(new StatusEffectInstance(StatusEffects.ABSORPTION, 100, 1));
					addStatusEffect(new StatusEffectInstance(StatusEffects.FIRE_RESISTANCE, 800, 0));
					callbackInfo.setReturnValue(true);
				}
			}
			if (callbackInfo.getReturnValueZ() && (Object) this instanceof ServerPlayerEntity player && (!BWConfig.enableCurses || BWComponents.CURSES_COMPONENT.get(player).hasCurse(BWCurses.SUSCEPTIBILITY))) {
				BWComponents.TRANSFORMATION_COMPONENT.maybeGet(player).ifPresent(transformationComponent -> {
					if (transformationComponent.getTransformation() == BWTransformations.HUMAN) {
						if (source.getSource() instanceof VampireEntity || (source.getSource() instanceof PlayerEntity playerSource && BewitchmentAPI.isVampire(playerSource, true) && BewitchmentAPI.isPledged(playerSource, BWPledges.LILITH))) {
							transformationComponent.getTransformation().onRemoved(player);
							transformationComponent.setTransformation(BWTransformations.VAMPIRE);
							transformationComponent.getTransformation().onAdded(player);
							PlayerLookup.tracking(this).forEach(trackingPlayer -> SpawnSmokeParticlesPacket.send(trackingPlayer, this));
							SpawnSmokeParticlesPacket.send(player, this);
							getWorld().playSound(null, getBlockPos(), BWSoundEvents.ENTITY_GENERIC_CURSE, getSoundCategory(), getSoundVolume(), getSoundPitch());
						} else if (source.getSource() instanceof WerewolfEntity || (source.getSource() instanceof PlayerEntity playerSource && BewitchmentAPI.isWerewolf(playerSource, false) && BewitchmentAPI.isPledged(playerSource, BWPledges.HERNE))) {
							transformationComponent.getTransformation().onRemoved(player);
							transformationComponent.setTransformation(BWTransformations.WEREWOLF);
							transformationComponent.getTransformation().onAdded(player);
							int variant = -1;
							if (source.getSource() instanceof WerewolfEntity) {
								variant = source.getSource().getDataTracker().get(BWHostileEntity.VARIANT);
							} else if (source.getSource() instanceof PlayerEntity playerSource) {
								variant = BWComponents.ADDITIONAL_WEREWOLF_DATA_COMPONENT.get(playerSource).getVariant();
							}
							if (variant > -1) {
								BWComponents.ADDITIONAL_WEREWOLF_DATA_COMPONENT.get(player).setVariant(variant);
							}
							PlayerLookup.tracking(this).forEach(trackingPlayer -> SpawnSmokeParticlesPacket.send(trackingPlayer, this));
							SpawnSmokeParticlesPacket.send(player, this);
							getWorld().playSound(null, getBlockPos(), BWSoundEvents.ENTITY_GENERIC_CURSE, getSoundCategory(), getSoundVolume(), getSoundPitch());
						}
					}
				});
			}
		}
	}

public void onUpdate(){

		super.onUpdate();

		// Synchronises the rider field
		if((this.rider == null || this.rider.get() == null)
				&& EntityUtils.getRider(this) instanceof EntityLivingBase
				&& !EntityUtils.getRider(this).isDead){
			this.rider = new WeakReference<>((EntityLivingBase)EntityUtils.getRider(this));
		}

		// Prevents dismounting
		if(EntityUtils.getRider(this) == null && this.rider != null && this.rider.get() != null
				&& !this.rider.get().isDead){
			this.rider.get().startRiding(this);
		}

		// Stops the bubble bursting instantly.
		if(this.ticksExisted < 1 && !isDarkOrb) ((EntityLivingBase)EntityUtils.getRider(this)).hurtTime = 0;

		this.move(MoverType.SELF, 0, 0.03, 0);

		if(isDarkOrb){

			if(EntityUtils.getRider(this) != null
					&& EntityUtils.getRider(this).ticksExisted % Spells.entrapment.getProperty(Entrapment.DAMAGE_INTERVAL).intValue() == 0){
				if(this.getCaster() != null){
					EntityUtils.getRider(this).attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.MAGIC),
							1 * damageMultiplier);
				}else{
					EntityUtils.getRider(this).attackEntityFrom(DamageSource.MAGIC, 1 * damageMultiplier);
				}
			}

			for(int i = 0; i < 5; i++){
				this.world.spawnParticle(EnumParticleTypes.PORTAL,
						this.posX + (this.rand.nextDouble() - 0.5D) * (double)this.width,
						this.posY + this.rand.nextDouble() * (double)this.height + 0.5d,
						this.posZ + (this.rand.nextDouble() - 0.5D) * (double)this.width,
						(this.rand.nextDouble() - 0.5D) * 2.0D, -this.rand.nextDouble(),
						(this.rand.nextDouble() - 0.5D) * 2.0D);
			}
			if(lifetime - this.ticksExisted == 75){
				this.playSound(WizardrySounds.ENTITY_ENTRAPMENT_VANISH, 1.5f, 1.0f);
			}else if(this.ticksExisted % 100 == 1 && this.ticksExisted < 150){
				this.playSound(WizardrySounds.ENTITY_ENTRAPMENT_AMBIENT, 1.5f, 1.0f);
			}
		}

		// Bubble bursts if the entity is hurt (see event handler) or killed, or if the bubble has existed for more than
		// 10 seconds.
		if(EntityUtils.getRider(this) == null && this.ticksExisted > 1){
			if(!this.isDarkOrb) this.playSound(WizardrySounds.ENTITY_BUBBLE_POP, 1.5f, 1.0f);
			this.setDead();
		}
	}

@Override
	public void onUpdate(){

		if(this.ticksExisted % 25 == 1){
			this.playSound(WizardrySounds.ENTITY_HEAL_AURA_AMBIENT, 0.1f, 1.0f);
		}

		super.onUpdate();

		if(!this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(width/2, posX, posY, posZ, this.height, world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					if(target.isEntityUndead()) {

						double velX = target.motionX;
						double velY = target.motionY;
						double velZ = target.motionZ;

						if (this.ticksExisted % 10 == 1) {
							if (this.getCaster() != null) {
								target.attackEntityFrom(
										MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.RADIANT),
										Spells.healing_aura.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier);
							} else {
								target.attackEntityFrom(DamageSource.MAGIC, Spells.healing_aura.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier);
							}

							// Removes knockback
							target.motionX = velX;
							target.motionY = velY;
							target.motionZ = velZ;
						}
					}

				}else if(target.getHealth() < target.getMaxHealth() && target.ticksExisted % 5 == 0){
					target.heal(Spells.healing_aura.getProperty(Spell.HEALTH).floatValue() * damageMultiplier);
				}
			}
		}else{
			for(int i=1; i<3; i++){
				float brightness = 0.5f + (rand.nextFloat() * 0.5f);
				double radius = rand.nextDouble() * (width/2);
				float angle = rand.nextFloat() * (float)Math.PI * 2;
				ParticleBuilder.create(Type.SPARKLE)
				.pos(this.posX + radius * MathHelper.cos(angle), this.posY, this.posZ + radius * MathHelper.sin(angle))
				.vel(0, 0.05, 0)
				.time(48 + this.rand.nextInt(12))
				.clr(1.0f, 1.0f, brightness)
				.spawn(world);
			}
		}
	}

@Override
	public ActionResult useOnBlock(ItemUsageContext context) {
		World world = context.getWorld();
		BlockPos pos = context.getBlockPos();
		BlockState state = world.getBlockState(pos);
		PlayerEntity player = context.getPlayer();
		boolean client = world.isClient;
		AthameStrippingRecipe entry = world.getRecipeManager().listAllOfType(BWRecipeTypes.ATHAME_STRIPPING_RECIPE_TYPE).stream().filter(recipe -> recipe.log == state.getBlock()).findFirst().orElse(null);
		if (entry != null) {
			world.playSound(player, pos, BWSoundEvents.ITEM_ATHAME_STRIP, SoundCategory.BLOCKS, 1, 1);
			if (!client) {
				world.setBlockState(pos, entry.strippedLog.getDefaultState().with(PillarBlock.AXIS, state.get(PillarBlock.AXIS)), 11);
				if (player != null) {
					context.getStack().damage(1, player, stackUser -> stackUser.sendToolBreakStatus(context.getHand()));
					if (world.random.nextFloat() < 2 / 3f) {
						ItemStack bark = entry.getOutput(world.getRegistryManager()).copy();
						if (!player.getInventory().insertStack(bark)) {
							player.dropStack(bark);
						}
					}
				}
			}
			return ActionResult.success(client);
		}
		BlockEntity blockEntity = world.getBlockEntity(state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.down() : pos);
		if (blockEntity instanceof SigilHolder sigilHolder) {
			if (player != null && player.getUuid().equals(sigilHolder.getOwner())) {
				if (!client && !sigilHolder.getEntities().isEmpty()) {
					boolean whitelist = sigilHolder.getModeOnWhitelist();
					world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
					player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
					sigilHolder.setModeOnWhitelist(!whitelist);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		} else if (blockEntity instanceof TaglockHolder taglockHolder) {
			if (player != null && player.getUuid().equals(taglockHolder.getOwner()) && taglockHolder.getFirstEmptySlot() != 0) {
				if (!client) {
					ItemScatterer.spawn(world, pos, taglockHolder.getTaglockInventory());
					taglockHolder.syncTaglockHolder(blockEntity);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		} else if (blockEntity instanceof Lockable lockable) {
			if (player != null && player.getUuid().equals(lockable.getOwner()) && !lockable.getEntities().isEmpty()) {
				if (!client) {
					boolean whitelist = lockable.getModeOnWhitelist();
					world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
					player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
					lockable.setModeOnWhitelist(!whitelist);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		}
		return super.useOnBlock(context);
	}

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        float damage = SpellConfig.ShockingDamage.get().floatValue() * WandUtil.damageMultiply();
        if (caster instanceof SpriteMob spriteMob) {
            if (spriteMob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                damage = (float) spriteMob.getAttributeValue(Attributes.ATTACK_DAMAGE);
            }
        }
        int range = spellStat.getRange();
        int burning = spellStat.getBurning();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
            burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !this.rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
            worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.ZAP.get(), this.getSoundSource(), 1.0F, 1.0F);
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 5));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (burning > 0){
                        if (worldIn.random.nextFloat() < 0.05F){
                            livingEntity.setSecondsOnFire(5 * burning);
                        }
                    }
                    if (this.rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage, true);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.ZAP.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
                this.playSound(worldIn, caster, ModSounds.ZAP.get());
            }
        }
    }

@Override
    protected void tick() {
        if (getWorld().isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 5);
        } else {
            if (getWorld().getGameTime() % 200 == 0) {
                List<Animal> animals = getWorld().getEntitiesOfClass(Animal.class, new AABB(getPos()).inflate(5));
                if (animals.size() >= 20) {
                    return;
                }
                boolean didWorkOnce = false;
                for (Animal a : animals) {
                    if (a.getType().is(EntityTags.BREED_BLACKLIST))
                        continue;
                    if (a.getAge() == 0 && a.canFallInLove()) {
                        didWorkOnce = true;
                        a.setInLove(null);
                    }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            }
        }
    }

