@Override
    public void tick() {
        if (key == null)
            return;

        if (level instanceof ServerLevel serverLevel) {
            if (level.getGameTime() % 200 == 0) {
                playersNearby = false;
                for (ServerPlayer serverPlayer : serverLevel.players()) {
                    if (BlockPosHelpers.distanceBetween(worldPosition, serverPlayer.blockPosition()) < 64) {
                        playersNearby = true;
                        break;
                    }
                }
            }
            if (!playersNearby) {
                return;
            }
            if (level.getGameTime() % ServerConfig.PLANARIUM_UPDATE_RATE.get() == 0) {
                DimManager.Entry entry1 = dimManager.getOrCreateTemplate(serverLevel, worldPosition, key);
                if (entry1 != null) {
                    // Notifies nearby players if the dimension has changed
                    if (entry1.lastUpdated > lastUpdated) {
                        lastUpdated = entry1.lastUpdated;
                        StructureTemplate template = dimManager.getTemplate(key);
                        if (template != null) {
                            Networking.sendToNearbyClient(level, worldPosition, new PacketUpdateDimTile(worldPosition, template));
                        }
                    }
                }
            }
        }
    }

@Override
    protected void tick() {
        WildenChimera.spawnPhaseParticles(getPos().above(), getWorld(), 1);
        if (getWorld().getGameTime() % 20 == 0)
            incrementProgress();
        if (getWorld().getGameTime() % 60 == 0 && (getWorld() instanceof ServerLevel serverLevel)) {
            FakePlayer fakePlayer = ANFakePlayer.getPlayer(serverLevel, this.playerUUID);
            if (!isBossSpawn()) {
                int wild = rand.nextInt(3);
                BlockPos summonPos = getPos().above().east(rand.nextInt(3) - rand.nextInt(6)).north(rand.nextInt(3) - rand.nextInt(6));
                Mob mobEntity = switch (wild) {
                    case 0 -> new WildenStalker(serverLevel);
                    case 1 -> new WildenGuardian(serverLevel);
                    default -> new WildenHunter(serverLevel);
                };
                summon(mobEntity, summonPos);
                if (getProgress() >= 15) {
                    setFinished();
                }
            } else {
                if (getProgress() >= 8) {
                    WildenChimera chimera = new WildenChimera(serverLevel);
                    summon(chimera, getPos().above());
                    for (BlockPos b : BlockPos.betweenClosed(getPos().east(5).north(5).above(), getPos().west(5).south(5).above(5))) {
                        if (!net.neoforged.neoforge.event.EventHooks.canEntityGrief(serverLevel, chimera)) {
                            continue;
                        }
