private int processQueue(Queue<ILevelRunnable> queue, Level level) {
        if (queue == null) {
            return 0;
        }

        // start the clock
        stopWatch.start();

        while (!queue.isEmpty()) {
            try {
                // call the first queue element.
                queue.poll().call(level);
                this.processQueueElementsProcessed++;

                if (stopWatch.elapsed(TimeUnit.MILLISECONDS) > TIME_LIMIT_PROCESS_QUEUE_MILLISECONDS) {
                    break;
                }
            } catch (Exception e) {
                LOG.warn("Uncaught exception when running delay action", e);
            }
        }

        // stop watch for the next call
        stopWatch.stop();

        return queue.size();
    }

public boolean tickServer(CTX ctx, IMultiblockLevel level, boolean canWork)
	{
		ctx.getEnergy().updateAverage();
		if(!canWork)
			return false;

		int i = 0;
		Iterator<MultiblockProcess<R, CTX>> processIterator = processQueue.iterator();
		boolean tickedAny = false;
		while(processIterator.hasNext()&&i++ < maxProcessPerTick)
		{
			MultiblockProcess<R, CTX> process = processIterator.next();
			if(process.canProcess(ctx, level.getRawLevel()))
			{
				process.doProcessTick(ctx, level);
				tickedAny = true;
			}
			if(process.clearProcess)
			{
				processIterator.remove();
				onQueueChange.run();
			}
		}
		if(tickedAny)
			markDirty.run();
		return tickedAny;
	}

@Override
	protected MutableComponent provideLine(DisplayLinkContext context, DisplayTargetStats stats) {
		if (!(context.getSourceBlockEntity() instanceof CuckooClockBlockEntity ccbe))
			return TimeOfDayDisplaySource.EMPTY_TIME;
		if (ccbe.getSpeed() == 0)
			return TimeOfDayDisplaySource.EMPTY_TIME;

		if (!context.sourceConfig()
			.contains("StartTime"))
			onSignalReset(context);

		long started = context.sourceConfig()
			.getLong("StartTime");
		long current = context.blockEntity()
			.getLevel()
			.getGameTime();

		int diff = (int) (current - started);
		int hours = (diff / 60 / 60 / 20);
		int minutes = (diff / 60 / 20) % 60;
		int seconds = (diff / 20) % 60;

		MutableComponent component = Component.literal((hours == 0 ? "" : (hours < 10 ? " " : "") + hours + ":")
			+ (minutes < 10 ? hours == 0 ? " " : "0" : "") + minutes + ":" + (seconds < 10 ? "0" : "") + seconds);

		return component;
	}

private void updateQueue(Map<@Nullable IRenderSetup, Queue<GTParticle>> renderQueue) {
        Iterator<Queue<GTParticle>> it = renderQueue.values().iterator();
        while (it.hasNext()) {
            Queue<GTParticle> particlesForSetup = it.next();

            Iterator<GTParticle> particles = particlesForSetup.iterator();
            while (particles.hasNext()) {
                GTParticle particle = particles.next();

                if (particle.isAlive()) {
                    try {
                        particle.onUpdate();
                    } catch (RuntimeException exception) {
                        GTCEu.LOGGER.error("Particle update error: {}", particle, exception);
                        particle.setExpired();
                    }
                    if (particle.isAlive()) continue;
                }

                particles.remove();
            }

            if (particlesForSetup.isEmpty()) {
                it.remove();
            }
        }
    }

public void updateFreshness(SpoilContext spoilContext, boolean createTag) {
        if (!stack.is(originalItem)) return;
        if (!createTag && !initialized || frozen) return;
        if (!spoilContext.isEmpty()) setSpoilContext(spoilContext);
        Level level = SpoilContext.getDefaultLevel();
        if (level != null && createTag && !initialized) {
            setCreationTick(level.getGameTime());
        }
        if (level != null && this.shouldSpoil()) {
            long spoilTicks = this.getSpoilTicks();
            long timeDifference = level.getGameTime() - creationTick - spoilTicks;
            if (timeDifference >= 0) {
                ItemStack newStack = this.spoilResult(getSpoilContext(), GTCEu.isClientThread());
                ((ISpoilableItemStackExtension) (Object) stack).gtceu$setStack(newStack);
                onItemChanged();
                ISpoilableItem newSpoilable = GTCapabilityHelper.getSpoilable(stack);
                if (newSpoilable != null) {
                    newSpoilable.setCreationTick(level.getGameTime() - timeDifference);
                    try {
                        newSpoilable.updateFreshness(spoilContext, false);
                    } catch (StackOverflowError ignored) {
                        // if items spoil in a giant chain or a loop
                    }
                }
            }
        }
    }

@Inject(method = "cookTick(Lnet/minecraft/world/level/Level;Lnet/minecraft/core/BlockPos;Lnet/minecraft/world/level/block/state/BlockState;Lnet/minecraft/world/level/block/entity/CampfireBlockEntity;)V",
            at = @At(value = "HEAD"))
    private static void onItemCook(Level level, BlockPos pos, BlockState state, CampfireBlockEntity blockEntity, CallbackInfo ci)
    {
        double maxStrength = ConfigSettings.WATERSKIN_CONSUME_STRENGTH.get() * 0.6;
        double tempRate = ConfigSettings.TEMP_RATE.get();

        for (int i = 0; i < blockEntity.getItems().size(); i++)
        {
            ItemStack stack = blockEntity.getItems().get(i);
            if (stack.is(ModItems.FILLED_WATERSKIN) && (level.getGameTime() & 4) == 0)
            {
                CompoundTag tag = stack.getOrCreateTag();
                double temperature = tag.getDouble(FilledWaterskinItem.NBT_TEMPERATURE);

                // If the block ID contains "soul", it's a soul campfire
                if (state.is(BlockTags.CAMPFIRES) && CSMath.betweenExclusive(tag.getDouble(FilledWaterskinItem.NBT_TEMPERATURE), -maxStrength, maxStrength))
                {
                    double delta = tempRate * 0.1;
                    if (state.is(ModBlockTags.SOUL_FIRE) && ConfigSettings.COLD_SOUL_FIRE.get())
                    {   delta *= -1;
                    }
                    tag.putDouble(FilledWaterskinItem.NBT_TEMPERATURE, temperature + delta);
                }
            }
        }
    }

