private void handleAmmoRepair(ItemStack stack, Level world, Minigun minigun) {
        if (minigun.getPlayer().containerMenu instanceof MinigunMagazineMenu) {
            return;  // avoid potential item duping or other shenanigans
        }
        int itemLife = minigun.getUpgrades(ModUpgrades.ITEM_LIFE.get());
        if (itemLife > 0) {
            MagazineHandler handler = getMagazine(stack);
            boolean repaired = false;
            float pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
            if (world.getGameTime() % (200 - itemLife * 35L) == 0) {
                for (int i = 0; i < handler.getSlots() && pressure > 0.25f; i++) {
                    ItemStack ammo = handler.getStackInSlot(i);
                    if (ammo.getItem() instanceof AbstractGunAmmoItem && ammo.getDamageValue() > 0) {
                        ammo.setDamageValue(ammo.getDamageValue() - 1);
                        if (!minigun.getPlayer().isCreative()) {
                            minigun.getAirCapability().ifPresent(h -> h.addAir(-(100 * itemLife)));
                        }
                        pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
                        repaired = true;
                    }
                }
            }
            if (repaired) {
                handler.save();
            }
        }
    }

@SubscribeEvent
	public static void onFlyableFall(PlayerFlyableFallEvent event) {
		EntityLivingBase entity = event.getEntityLiving();
		if (entity == null) return;

		if (!shouldBounce(entity)) return;

		INSTANCE.blocks.removeIf(bouncyBlock -> entity.world.getTotalWorldTime() - bouncyBlock.tickSpawned > bouncyBlock.expiry);

		boolean isClient = entity.getEntityWorld().isRemote;
		if (event.getDistance() > 0.5) {
			entity.fallDistance = 0;

			if (isClient) {
				entity.motionY *= -0.9;
				entity.isAirBorne = true;
				entity.onGround = false;
				double f = 0.95;
				entity.motionX /= f;
				entity.motionZ /= f;
				PacketHandler.NETWORK.sendToServer(new PacketBounce());
			}
			entity.playSound(SoundEvents.ENTITY_SLIME_SQUISH, 1f, 1f);
			BounceHandler.addBounceHandler(entity, entity.motionY);

		}
	}

protected void customServerAiStep() {
		super.customServerAiStep();

		if (isUnderWater()) {
			AABB boundingBox = getBoundingBox();
			double width = boundingBox.maxX - boundingBox.minX;
			double depth = boundingBox.maxZ - boundingBox.minZ;
			double height = boundingBox.maxY - boundingBox.minY;
			int particleCount = (int)Math.ceil(3 + (10 * width * depth * height));
			TMEParticlePacket packet = new TMEParticlePacket(particleCount);

			for (int i = 0; i < particleCount; i++) {
				packet.particle(ParticleBuilder.forRandomPosInEntity(EntityTrackingParticleOptions.ambient(AoAParticleTypes.FREEZING_SNOWFLAKE), this)
						.lifespan(Mth.ceil(3 / (this.random.nextFloat() * 0.8f + 0.2f)))
						.scaleMod(0.3f)
						.velocity(RandomUtil.scaledGaussianValue(0.05d), 0, RandomUtil.scaledGaussianValue(0.05d)));
			}

			packet.sendToAllPlayersNearby((ServerLevel)level(), position(), 10);
			remove(RemovalReason.KILLED);
		}

		Entity target = getTarget();

		if (target != null && target.isFullyFrozen())
			lastAttackTime = tickCount;
	}

public static void checkLookingAtEnderOverseer(Player player) {
		Level level = player.level();
		long gameTime = level.getGameTime();
		if (Math.abs(gameTime - lastTickedGameTime) > 5) {
			// don't even bother if there are no loaded Ender Overseer blocks
			return;
		}
		if (!player.canBeSeenByAnyone()) {
			// exclude spectators and dead players
			return;
		}

		ItemStack helm = player.getItemBySlot(EquipmentSlot.HEAD);
		if (!helm.isEmpty() && helm.is(Blocks.CARVED_PUMPKIN.asItem())) {
			return;
		}

		Vec3 from = player.getEyePosition(1);
		Vec3 dir = player.getViewVector(1);
		Vec3 to = from.add(dir.scale(RANGE));
		BlockHitResult hit = level.clip(
				new ClipContext(from, to, ClipContext.Block.VISUAL, ClipContext.Fluid.NONE, player));
		if (hit.getType() == HitResult.Type.BLOCK
				&& level.getBlockEntity(hit.getBlockPos()) instanceof EnderOverseerBlockEntity enderOverseer) {
			enderOverseer.lookedAtGameTime = gameTime;
		}
	}

