public void addMouseOverText(TooltipList list, boolean includeWeight, boolean includeEmpty) {
		if (ClientQuestFile.INSTANCE.canEdit() || !hideTooltip) {
			float totalWeight = getTotalWeight(includeEmpty);

			if (includeWeight && includeEmpty && emptyWeight > 0) {
				addItem(list, Component.translatable("ftbquests.reward_table.nothing"), emptyWeight, totalWeight);
			}

			List<WeightedReward> sortedRewards = weightedRewards.stream().sorted().toList();

			BaseScreen gui = ClientUtils.getCurrentGuiAs(BaseScreen.class);
			int maxLines = gui == null ? 12 : (gui.height - 20) / (gui.getTheme().getFontHeight() + 2);
			int nRewards = sortedRewards.size();
			int start = nRewards > maxLines ?
					(int) ((FTBQuestsClient.getClientLevel().getGameTime() / 10) % nRewards) :
					0;

			int nLines = Math.min(maxLines, nRewards);
			for (int idx = 0; idx < nLines; idx++) {
				WeightedReward wr = sortedRewards.get((start + idx) % nRewards);
				if (includeWeight) {
					addItem(list, wr.getReward().getTitle(), wr.getWeight(), totalWeight);
				} else {
					list.add(Component.literal("- ").withStyle(ChatFormatting.GRAY).append(wr.getReward().getTitle()));
				}
			}
		}
	}

@Override
  public void render(TileExperienceFountain tankHere, float v, PoseStack matrix,
      MultiBufferSource renderer, int light, int overlayLight) {
    float angle = 0F;
    if (tankHere.getLevel() != null && tankHere.getLevel().hasNeighborSignal(tankHere.getBlockPos())) {
      angle = ((tankHere.getLevel().getGameTime() % 60L) + v) * 6F;
    }
    SpinModelRenderer.render(SpinModelRenderer.FOUNTAIN_SPIN, angle, matrix, renderer, light, overlayLight);
    IFluidHandler handler = CapabilityUtil.fluid(tankHere.getLevel(), tankHere.getBlockPos());
    if (handler == null || handler.getFluidInTank(0) == null) {
      return;
    }
    FluidStack fluid = handler.getFluidInTank(0);
    if (fluid.isEmpty()) {
      return;
    }
    VertexConsumer buffer = renderer.getBuffer(FluidTankRenderType.RESIZABLE);
    if (buffer.getClass().getName().equals("com.mojang.blaze3d.vertex.VertexMultiConsumer$Double")) {
      buffer = Minecraft.getInstance().renderBuffers().bufferSource().getBuffer(FluidTankRenderType.RESIZABLE);
    }
    matrix.scale(1F, FluidHelpers.getScale(tankHere.tank) / 4F, 1F);
    float f = 0.5F;
    matrix.scale(f, 1F, f);
    matrix.translate(f, 0, f);
    RenderBlockUtils.renderObject(FluidHelpers.getFluidModel(fluid, FluidHelpers.STAGES - 1),
        matrix, buffer, RenderBlockUtils.getColorARGB(fluid),
        RenderBlockUtils.calculateGlowLight(light, fluid));
  }

public static void clientTick(Level level, BlockPos pos, BlockState state, SarcophagusBlockEntity blockEntity) {
        boolean occupied = state.getValue(SarcophagusBlock.OCCUPIED);

        if (blockEntity.closingStartTick > 0) {
            --blockEntity.closingStartTick;
        }

        if (occupied != blockEntity.wasOccupied) {
            if (occupied) {
                blockEntity.closingState.start((int) level.getGameTime());
                blockEntity.playSound(ModSounds.STONE_DRAG.get(), level.getRandom().nextFloat() * 0.25F + 0.75F);
                blockEntity.closingStartTick = 20;
                blockEntity.openingState.stop();
                blockEntity.closedState.stop();
            } else {
                blockEntity.closedState.stop();
                blockEntity.openingState.start((int) level.getGameTime());
                blockEntity.playSound(ModSounds.STONE_DRAG.get(), level.getRandom().nextFloat() * 0.25F + 0.75F);
                blockEntity.closingState.stop();
            }
            blockEntity.wasOccupied = occupied;
        }

        if (occupied && blockEntity.closingStartTick <= 0) {
            blockEntity.closingState.stop();
            blockEntity.closedState.start((int) level.getGameTime());
        }
    }

