private void commonSetup(FMLCommonSetupEvent event) {
        event.enqueueWork(() -> {
            //Dispenser behavior
            DispenserBlock.registerBehavior(AdditionsBlocks.OBSIDIAN_TNT, new OptionalDispenseItemBehavior() {
                @Override
                protected ItemStack execute(BlockSource source, ItemStack dispensed) {
                    //Based heavily on vanilla's tnt dispense behavior
                    ServerLevel level = source.level();
                    if (!level.getGameRules().get(GameRules.TNT_EXPLODES)) {
                        setSuccess(false);
                        return dispensed;
                    }
                    BlockPos target = source.pos().relative(source.state().getValue(DispenserBlock.FACING));
                    if (SulfurCubeBlockDispenseItemBehavior.dispenseBlock(level, target, dispensed)) {
                        return dispensed;
                    }
                    if (BlockObsidianTNT.createAndAddEntity(source.level(), target, null)) {
                        level.gameEvent(null, GameEvent.ENTITY_PLACE, target);
                        dispensed.shrink(1);
                        setSuccess(true);
                    }
                    return dispensed;
                }
            });
            EnumColorCollection.zipApply(EnumColorCollection.VALUES, AdditionsItems.BALLOONS, (color, balloon) -> DispenserBlock.registerBehavior(balloon, new ItemBalloon.DispenserBehavior(color)));
        });
        Mekanism.logger.info("Loaded 'Mekanism: Additions' module.");
    }

public static <LEVEL extends BlockGetter, NODE extends @Nullable Object> int explore(LEVEL level, Long2ObjectMap<ChunkAccess> chunkMap, BlockPos start, NODE node,
          FormationChecker<LEVEL, NODE> checker, int maxCount) {
        if (!checker.check(level, chunkMap, start, node, start)) {
            return 0;
        }

        BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos();
        Queue<BlockPos> openSet = new LinkedList<>();
        Set<BlockPos> traversed = new ObjectOpenHashSet<>();
        openSet.add(start);
        traversed.add(start);
        while (!openSet.isEmpty()) {
            BlockPos ptr = openSet.poll();
            int traversedSize = traversed.size();
            if (traversedSize >= maxCount) {
                return traversedSize;
            }
            for (Direction side : EnumUtils.DIRECTIONS) {
                mutable.setWithOffset(ptr, side);
                if (!traversed.contains(mutable) && checker.check(level, chunkMap, start, node, mutable)) {
                    BlockPos offset = mutable.immutable();
                    openSet.add(offset);
                    traversed.add(offset);
                }
            }
        }
        return traversed.size();
    }

@Override
    public boolean canUse() {
        if (this.mob.isPassenger() || mob.isVehicle() && mob.getControllingPassenger() != null) {
            return false;
        }
        if(!mob.getItemInHand(InteractionHand.MAIN_HAND).isEmpty()){
            return false;
        }
        if (!this.mustUpdate) {
            long worldTime = this.mob.level().getGameTime() % 10;
            if (this.mob.getNoActionTime() >= 100 && worldTime != 0) {
                return false;
            }
            if (this.mob.getRandom().nextInt(this.executionChance) != 0 && worldTime != 0) {
                return false;
            }
        }
        List<ItemEntity> list = this.mob.level().getEntitiesOfClass(ItemEntity.class, this.getTargetableArea(this.getFollowDistance()), this.targetEntitySelector);
        if (list.isEmpty()) {
            return false;
        } else {
            Collections.sort(list, this.theNearestAttackableTargetSorter);
            this.targetEntity = list.get(0);
            this.endergrade.stopWandering = true;
            this.endergrade.hasItemTarget = true;
            this.mustUpdate = false;
            return true;
        }
    }

public EnumBestiaryPages[] randomizePages(ItemStack bestiary, ItemStack manuscript) {
        if (!level.isClientSide) {
            if (bestiary.getItem() == IafItemRegistry.BESTIARY.get()) {
                List<EnumBestiaryPages> possibleList = getPossiblePages();
                localRand.setSeed(this.level.getGameTime());
                Collections.shuffle(possibleList, localRand);
                if (!possibleList.isEmpty()) {
                    selectedPages[0] = possibleList.get(0);
                } else {
                    selectedPages[0] = null;
                }
                if (possibleList.size() > 1) {
                    selectedPages[1] = possibleList.get(1);
                } else {
                    selectedPages[1] = null;
                }
                if (possibleList.size() > 2) {
                    selectedPages[2] = possibleList.get(2);
                } else {
                    selectedPages[2] = null;
                }
            }
            int page1 = selectedPages[0] == null ? -1 : selectedPages[0].ordinal();
            int page2 = selectedPages[1] == null ? -1 : selectedPages[1].ordinal();
            int page3 = selectedPages[2] == null ? -1 : selectedPages[2].ordinal();
            IceAndFire.sendMSGToAll(new MessageUpdateLectern(worldPosition.asLong(), page1, page2, page3, false, 0));
        }
        return selectedPages;
    }

private void playerTick(Player player) {
		ServerQuestFile file = ServerQuestFile.INSTANCE;

		if (player instanceof ServerPlayer serverPlayer && file != null && !PlayerHooks.isFake(player)) {
			if (autoSubmitTasks == null) {
				autoSubmitTasks = file.collect(Task.class, t -> t.autoSubmitOnPlayerTick() > 0);
			}

			// Don't be deceived, it's somehow possible to be null here
			if (autoSubmitTasks == null || autoSubmitTasks.isEmpty()) {
				return;
			}

			file.getTeamData(player).ifPresent(data -> {
				long now = player.level().getGameTime();

				file.withPlayerContext(serverPlayer, () -> {
					for (Task task : autoSubmitTasks) {
						long interval = task.autoSubmitOnPlayerTick();
						if (interval > 0L && now % interval == 0L) {
							if (!data.isCompleted(task) && data.canStartTasks(task.getQuest())) {
								task.submitTask(data, serverPlayer);
							}
						}
					}
				});
			});
		}
	}

