@Override
  public void render(TileDisenchant tile, float partialTick, PoseStack pose,
      MultiBufferSource buffer, int packedLight, int packedOverlay) {
    if (tile.inputSlots.getStackInSlot(1).isEmpty()) {
      return;
    }
    pose.pushPose();
    //block is 12/16 tall, sit the book just above the top surface
    pose.translate(0.5F, 0.95F, 0.5F);
    float time = (tile.getLevel() == null ? 0F : tile.getLevel().getGameTime()) + partialTick;
    //gentle bobbing, same as vanilla
    pose.translate(0.0F, 0.1F + Mth.sin(time * 0.1F) * 0.01F, 0.0F);
    //upside-down: flip the book over on the X axis
    pose.mulPose(Axis.XP.rotationDegrees(180.0F));
    //slow continuous spin so the book is visibly alive
    float spin = time * 0.04F;
    pose.mulPose(Axis.YP.rotation(-spin));
    pose.mulPose(Axis.ZP.rotationDegrees(80.0F));
    //book is mostly open with a slight flutter
    float flip = time * 0.02F;
    float pageL = Mth.frac(flip + 0.25F) * 1.6F - 0.3F;
    float pageR = Mth.frac(flip + 0.75F) * 1.6F - 0.3F;
    pageL = Mth.clamp(pageL, 0.0F, 1.0F);
    pageR = Mth.clamp(pageR, 0.0F, 1.0F);
    this.bookModel.setupAnim(time, pageL, pageR, 0.2F);
    VertexConsumer vc = BOOK_LOCATION.buffer(buffer, RenderType::entitySolid);
    this.bookModel.renderToBuffer(pose, vc, packedLight, packedOverlay);
    pose.popPose();
  }

public static void onLivingUpdate(EntityTickEvent.Post event) {
		Entity entity = event.getEntity();
		if (entity.level().isClientSide() || entity instanceof Player || !(entity instanceof LivingEntity livingEntity)) {
			return;
		}
		if (livingEntity instanceof Monster monster && hasPendingBackpackAddition(monster)) {
			setPendingBackpackAddition(monster, false);
			if (monster.getItemBySlot(EquipmentSlot.CHEST).isEmpty()) {
				addBackpack(monster, entity.level(), entity.level().getRandom());
			}
		}
		if (!hasSpawnedJukeboxUpgrade(livingEntity)) {
			return;
		}
		ItemStack backpack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
		if (!(backpack.getItem() instanceof BackpackItem)) {
			clearSpawnedBackpackData(livingEntity);
			return;
		}

		IBackpackWrapper backpackWrapper = BackpackWrapper.fromStack(backpack);
		backpackWrapper.getUpgradeHandler().getTypeWrappers(JukeboxUpgradeItem.TYPE).forEach(wrapper -> {
			if (wrapper.isPlaying()) {
				wrapper.tick(livingEntity, entity.level(), entity.blockPosition());
			} else {
				wrapper.play(livingEntity);
			}
		});
	}

public boolean hurt(DamageSource pSource, float pAmount) {
        if (this.getHealth() <= 10.0F){
            if (pSource.is(DamageTypes.CACTUS) || pSource.is(DamageTypes.SWEET_BERRY_BUSH) || pSource.is(DamageTypeTags.WITCH_RESISTANT_TO)){
                return false;
            }
        }

        if (pSource.getEntity() instanceof LivingEntity livingentity && livingentity != this){
            this.toHealTime = MathHelper.secondsToTicks(15);
            if (MobsConfig.CroneThornDefense.get()) {
                if (!pSource.is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !pSource.is(DamageTypes.THORNS)) {
                    float thorn = 2.0F;
                    if (this.level.getDifficulty() == Difficulty.HARD) {
                        thorn *= 2.0F;
                    }
                    livingentity.hurt(this.damageSources().thorns(this), thorn);
                }
            }
            if (pAmount >= 6 && this.overwhelmed <= 0) {
                this.hitTimes += 1;
                this.lastHitTime = 25;
            }
            if (pAmount >= 15 || this.hitTimes > 3){
                this.overwhelmed = MathHelper.secondsToTicks(15);
            }
        }

        return super.hurt(pSource, pAmount);
    }

public static <T extends IFactionPlayer<T> & ISkillPlayer<T>> void handleToggleActionPacket(ServerboundToggleActionPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            Player player = context.player();
            IActionHandler.<T>get(player).ifPresent(handler -> {
                IAction.ActivationContext activationContext = msg.target() != null ? msg.target().map(entityId -> {
                    Entity e = player.level().getEntity(entityId);
                    if (e == null) {
                        LOGGER.warn("Could not find entity {} the player was looking at when toggling action", entityId);
                    }
                    return new ActionHandler.ActivationContext(e);
                }, ActionHandler.ActivationContext::new) : new ActionHandler.ActivationContext();

                Holder<? extends IAction<?>> action = msg.action();
                if (action != null) {
                    @SuppressWarnings("unchecked")
                    IActionResult r = handler.toggleAction((Holder<IAction<T>>) (Object) action, activationContext);
                    if (!r.successful()) {
                        if (r.sendToStatusBar()) {
                            player.sendOverlayMessage(r.message());
                        } else {
                            player.sendSystemMessage(r.message());
                        }
                    } else {
                        handler.sync();
                    }
                }
            });
        });
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (currentDepth > 0) {
            // check for broken drill pipes
            int curCheckingPipe = (int)(nonNullLevel().getGameTime() % currentDepth);
            if (curCheckingPipe > 0 && !isPipe(nonNullLevel(), getBlockPos().relative(Direction.DOWN, curCheckingPipe))) {
                currentDepth = curCheckingPipe - 1;
            }
        }

        if (rsController.shouldRun() && getPressure() >= getMinWorkingPressure()) {
            workTimer += this.getSpeedMultiplierFromUpgrades();
            while (workTimer > 20f) {
                workTimer -= 20f;
                status = Status.IDLE;
                if (pumpMode == PumpMode.RETRACT) {
                    retractPipes();
                } else {
                    if (!suckLiquid() && !tryDigDown()) {
                        break;
                    }
                }
            }
        } else {
            status = Status.IDLE;
        }
    }

@Override
    protected boolean doBlockInteraction(BlockPos pos, double squareDistToBlock) {
        ServerPlayerGameMode manager = drone.getFakePlayer().gameMode;
        ServerPlayerGameModeAccess access = (ServerPlayerGameModeAccess) manager;
        if (!access.isDestroyingBlock() || !access.hasDelayedDestroy()) { //is not destroying and is not acknowledged.
            BlockState blockState = worldCache.getBlockState(pos);
            if (!ignoreBlock(blockState) && isBlockValidForFilter(worldCache, pos, drone, progWidget)) {
                if (blockState.getDestroySpeed(drone.getDroneLevel(), pos) < 0) {
                    addToBlacklist(pos);
                    drone.getDebugger().addEntry("pneumaticcraft.gui.progWidget.dig.debug.cantDigBlock", pos);
                    drone.setDugBlock(null);
                    return false;
                }
                Direction face = progWidget instanceof ProgWidgetDig dig ? dig.getDigSide() : Direction.UP;
                PlayerInteractEvent.LeftClickBlock event = CommonHooks.onLeftClickBlock(drone.getFakePlayer(), pos, face, ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK);
                if (!event.isCanceled()) {
                    int limit = drone.getDroneLevel().getMaxBuildHeight();
                    manager.handleBlockBreakAction(pos, ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK, face, limit, 0);
                    manager.handleBlockBreakAction(pos, ServerboundPlayerActionPacket.Action.STOP_DESTROY_BLOCK, face, limit, 1);
                    drone.setDugBlock(pos, face);
                    return true;
                }
            }
            drone.setDugBlock(null);
            return false;
        } else {
            return true;
        }
    }

