    public static void playerOnTick(PlayerTickEvent.Pre e) {
        Player player = e.getEntity();
        if (!(player instanceof ServerPlayer serverPlayer) || player.getCommandSenderWorld().getGameTime() % ServerConfig.REGEN_INTERVAL.get() != 0)
            return;

        ManaCap mana = CapabilityRegistry.getMana(player);
        if (mana == null)
            return;
        boolean sync = false;
        // Force sync mana to client because client caps vanish on world change
        boolean forceSync = player.level().getGameTime() % 60 == 0;
        if (mana.getCurrentMana() != mana.getMaxMana() || forceSync) {
            double regenPerSecond = ManaUtil.getManaRegen(player) / Math.max(1, ((int) MEAN_TPS / ServerConfig.REGEN_INTERVAL.get()));
            mana.addMana(regenPerSecond);
            sync = true;
        }
        ManaUtil.Mana maxmana = ManaUtil.calcMaxMana(player);
        int max = maxmana.getRealMax();
        if (mana.getMaxMana() != max || forceSync) {
            mana.setMaxMana(max);
            mana.setReserve(maxmana.Reserve());
            sync = true;
        }

        if (sync) {
            mana.syncToClient(serverPlayer);
        }
    }

@SubscribeEvent
    public static void onSummonerLogin(EntityJoinLevelEvent event) {
        if (INSTANCE.offlineSummonersToSavedEntities.isEmpty()) {
            return;
        }
        var entity = event.getEntity();
        if (entity.level instanceof ServerLevel serverLevel) {
            IronsDataStorage.INSTANCE.setDirty();
            var savedSummons = INSTANCE.offlineSummonersToSavedEntities.remove(entity.getUUID());
            if (savedSummons != null) {
                // Note: summons always get added to summoner's level, even if that conflicts with where they were saved
                // However, it is logically impossible for a summon to not be in the summoner's level, so that should be fine
                var server = serverLevel.getServer();
                Set<UUID> summonsSet = new HashSet<>();
                UUID ownerUUID = entity.getUUID();
                for (CompoundTag summon : savedSummons) {
                    var summonedEntity = EntityType.create(summon, serverLevel).orElse(null);
                    if (summonedEntity != null) {
                        serverLevel.addFreshEntityWithPassengers(summonedEntity);
                        var summonUUID = summonedEntity.getUUID();
                        summonsSet.add(summonUUID);
                        INSTANCE.summonToOwner.put(summonUUID, ownerUUID);
                        INSTANCE.summonExpirations.add(new ExpirationInstance(summonUUID, server.getTickCount(), server.getTickCount() + summon.getInt("summon_duration_remaining")));
                    }
                    INSTANCE.ownerToSummons.put(ownerUUID, summonsSet);
                }
            }
        }
    }

private void Icicle_Crash() {

        if (this.level().getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
            BlockPos ceil = this.blockPosition().offset(0, 5, 0);
            while ((!level().getBlockState(ceil).isSolid() || level().getBlockState(ceil).getBlock() == ModBlocks.POINTED_ICICLE.get()) && ceil.getY() < level().getMaxBuildHeight()) {
                ceil = ceil.above();
            }
            final int i = 8;
            final int j = 8;
            final int k = 8;

            for (BlockPos blockpos1 : BlockPos.betweenClosed(ceil.offset(-i, -j, -k), ceil.offset(i, j, k))) {
                if (level().getBlockState(blockpos1).getBlock() instanceof Fallable) {
                    if (isHangingIcicle(blockpos1)) {
                        while (isHangingIcicle(blockpos1.above()) && blockpos1.getY() < level().getMaxBuildHeight()) {
                            blockpos1 = blockpos1.above();
                        }
                        if (isHangingIcicle(blockpos1)) {
                            Vec3 vec3 = Vec3.atBottomCenterOf(blockpos1);
                            FallingBlockEntity.fall(level(), BlockPos.containing(vec3.x, vec3.y, vec3.z), level().getBlockState(blockpos1));
                        }
                    } else {
                        this.level().scheduleTick(blockpos1, level().getBlockState(blockpos1).getBlock(), 2);
                    }
                }
            }
        }

    }

@Override
	public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
		if (SuperpositionHandler.hasSpellstoneCooldown(player))
			return;

		LivingEntity target = SuperpositionHandler.getObservedEntity(player, world, 3.0F, (int) phaseRange.getValue());

		if (target != null) {
			Vector3 targetPos = Vector3.fromEntityCenter(target);
			Vector3 chaserPos = Vector3.fromEntityCenter(player);

			Vector3 dir = targetPos.subtract(chaserPos);
			dir = dir.normalize();
			dir = dir.multiply(1.5D);

			dir = targetPos.add(dir);

			world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 72, 1.0F, false));

			player.teleportTo(dir.x, target.getY() + 0.25D, dir.z);
			EnigmaticLegacy.packetInstance.send(PacketDistributor.PLAYER.with(() -> player), new PacketPlayerSetlook(target.getX(), target.getY() - 1.0D + (target.getBbHeight() / 2), target.getZ()));

			world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 24, false));

			SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));
			TransientPlayerData.get(player).setEyeOfNebulaPower(true);
		}
	}

@Override
	public void readFromNBT(NBTTagCompound compound) {

		this.activated = compound.getBoolean("activated");
		this.conquered = compound.getBoolean("conquered");
		this.regenerationTime = compound.getLong("regenerationTime");
		this.lastRegenerationTime = compound.getLong("lastRegenerationTime");
		if (compound.hasKey("shrineElement"))
			this.shrineElement = Element.values()[compound.getInteger("shrineElement")];
		this.linkedContainerPos = NBTUtil.getPosFromTag(compound.getCompoundTag("linkedContainerPos"));

		NBTTagList wizardTagList = compound.getTagList("wizards", Constants.NBT.TAG_COMPOUND);
		int i = 0;
		for (NBTBase tag : wizardTagList) {
			if (tag instanceof NBTTagCompound) linkedWizards[i++] = NBTUtil.getUUIDFromTag((NBTTagCompound) tag);
			else Wizardry.logger.warn("Unexpected tag type in NBT tag list of compound tags!");
		}

		this.lootedPlayers.clear();
		if (compound.hasKey("lootedPlayers")) {
			NBTTagList playerTagList = compound.getTagList("lootedPlayers", Constants.NBT.TAG_COMPOUND);
			for (NBTBase tag : playerTagList) {
				if (tag instanceof NBTTagCompound) lootedPlayers.add(NBTUtil.getUUIDFromTag((NBTTagCompound) tag));
			}
		}

		super.readFromNBT(compound);
		// Must be after super
		initContainmentField(this.pos);
	}

