@Override
	public void onUpdate(){

		double extensionSpeed = 0;

		if(!world.isRemote){
			if(lifetime - this.ticksExisted < 15){
				extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
			}else if(lifetime - this.ticksExisted < 25){
				extensionSpeed = 0;
			}else if(lifetime - this.ticksExisted < 28){
				extensionSpeed = 0.25;
			}

			if(facing != null){ // Will probably be null on the client side, but should never be on the server side
				this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
						this.facing.getZOffset() * extensionSpeed);
			}
		}

		if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

		if(!this.world.isRemote){
			for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
				if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
					DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
					// Potion effect only gets added if the damage succeeded
					// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
					if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
						((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
								Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
								Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}
			}
		}

		super.onUpdate();
	}

@Override
	public boolean attackEntityFrom(DamageSource source, float damage) {
		if(source != DamageSource.IN_WALL) {
			if(source instanceof EntityDamageSource) {
				Entity direct = ((EntityDamageSource) source).getImmediateSource();
				if(direct instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) direct;

					ItemStack held = player.getHeldItem(EnumHand.MAIN_HAND);

					if(!held.isEmpty() && held.getItem() == ItemRegistry.DENTROTHYST_VIAL && held.getItemDamage() != 1) {
						if(this.world.isRemote) {
							for(int i = 0; i < 10; i++) {
								this.world.spawnParticle(EnumParticleTypes.CRIT, this.posX + this.motionX, this.posY + this.motionY + this.height * 0.5f, this.posZ + this.motionZ, -this.motionX + (this.rand.nextFloat() - 0.5f), -this.motionY + 0.2D + (this.rand.nextFloat() - 0.5f), -this.motionZ + (this.rand.nextFloat() - 0.5f));
							}
						}

						if(super.attackEntityFrom(source, damage * 3.0f)) {
							if(!this.world.isRemote) {
								if(!this.isEntityAlive()) {
									held.shrink(1);
									ItemHandlerHelper.giveItemToPlayer(player, ItemRegistry.DENTROTHYST_FLUID_VIAL.withFluid(held.getItemDamage() == 2 ? 1 : 0, FluidRegistry.SHALLOWBREATH));
								}

								this.world.playSound(null, player.posX, player.posY, player.posZ, FluidRegistry.SHALLOWBREATH.getFillSound(new FluidStack(FluidRegistry.SHALLOWBREATH, 1000)), SoundCategory.BLOCKS, 1.0F, 1.0F);
							}

							return true;
						}

						return false;
					}
				}
			}

			return super.attackEntityFrom(source, damage);
		}
		return false;
	}

@Override
        public void tick() {
            checkForMobsTime--;
            LivingEntity target = GammaroachEntity.this.getTarget();
            if (target != null && target.isAlive()) {
                if (checkForMobsTime < 0) {
                    checkForMobsTime = 120 + GammaroachEntity.this.random.nextInt(100);
                    Predicate<Entity> monsterAway = (animal) -> animal instanceof Enemy && !(animal instanceof GammaroachEntity) && animal.distanceTo(target) > 5 && !animal.isPassenger();
                    List<Mob> list = GammaroachEntity.this.level().getEntitiesOfClass(Mob.class, GammaroachEntity.this.getBoundingBox().inflate(30, 12, 30), EntitySelector.NO_SPECTATORS.and(monsterAway));
                    list.sort(Comparator.comparingDouble(GammaroachEntity.this::distanceToSqr));
                    if (!list.isEmpty()) {
                        pickupMonster = list.get(0);
                    }
                }
                if (pickupMonster == null || pickupMonster.isPassengerOfSameVehicle(GammaroachEntity.this)) {
                    GammaroachEntity.this.getNavigation().moveTo(target, 1.0D);
                    GammaroachEntity.this.lookAt(target, 180, 30);
                    if (GammaroachEntity.this.distanceTo(target) < 1.5F + target.getBbWidth()) {
                        if (GammaroachEntity.this.getAnimation() == NO_ANIMATION) {
                            GammaroachEntity.this.setAnimation(GammaroachEntity.ANIMATION_RAM);
                        } else if (GammaroachEntity.this.getAnimation() == GammaroachEntity.ANIMATION_RAM && GammaroachEntity.this.getAnimationTick() > 8 && GammaroachEntity.this.getAnimationTick() < 15) {
                            GammaroachEntity.this.playSound(ACSoundRegistry.GAMMAROACH_ATTACK.get());
                            target.hurt(damageSources().mobAttack(GammaroachEntity.this), (float) GammaroachEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        }
                        if (pickupMonster != null) {
                            pickupMonster.stopRiding();
                            pickupMonster = null;
                        }
                    }
                } else if (pickupMonster.isAlive() && (!pickupMonster.isPassenger())) {
                    GammaroachEntity.this.getNavigation().moveTo(pickupMonster, 1.0D);
                    GammaroachEntity.this.lookAt(pickupMonster, 180, 30);
                    if (GammaroachEntity.this.distanceTo(pickupMonster) < 1.5F + pickupMonster.getBbWidth()) {
                        pickupMonster.startRiding(GammaroachEntity.this, true);
                        pickupMonster.hurt(damageSources().cactus(), 1);
                    }
                } else {
                    pickupMonster = null;
                }
            }
        }

public void onUse(World world, BlockPos pos, PlayerEntity player, Hand hand) {
		if (!getCachedState().get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (getCachedState().get(Properties.LIT)) {
				world.setBlockState(pos, getCachedState().with(Properties.LIT, false));
				world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				reset(hasIncense);
				syncBrazier();
			} else {
				if (stack.getItem() instanceof FlintAndSteelItem) {
					world.setBlockState(pos, getCachedState().with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
					IncenseRecipe foundIncenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
					if (foundIncenseRecipe != null) {
						incenseRecipe = foundIncenseRecipe;
						timer = -6000;
						hasIncense = true;
						syncBrazier();
					} else if (BWConfig.enableCurses) {
						CurseRecipe foundCurseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
						if (foundCurseRecipe != null && getTarget() != null) {
							curseRecipe = foundCurseRecipe;
							timer = -100;
							syncBrazier();
						}
					}
				} else if (!stack.isEmpty()) {
					int firstEmpty = getFirstEmptySlot();
					if (firstEmpty != -1) {
						setStack(firstEmpty, stack.split(1));
						syncBrazier();
					}
				} else {
					reset(hasIncense);
					syncBrazier();
				}
			}
		}
		markDirty();
	}

@Override
    protected void onHitEntity(EntityHitResult rayTraceResult) {
        Entity entity = rayTraceResult.getEntity();

        float damage = 7.5f;

        Entity entity1 = this.getOwner();
        DamageSource damagesource;
        if (entity1 == null) {
            damagesource = level.damageSources().indirectMagic(this, null);
        } else {
            damagesource = level.damageSources().magic();
            if (entity1 instanceof LivingEntity) {
                ((LivingEntity) entity1).setLastHurtMob(entity);
            }
        }

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.igniteForSeconds(5);
        }

        if (entity.hurt(damagesource, damage)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                this.doPostHurtEffects(livingentity);
            }

            this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            this.remove(RemovalReason.DISCARDED);

        } else {
            entity.setRemainingFireTicks(k);
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            this.setYRot(this.getYRot() + 180f);
            this.yRotO += 180.0F;
            if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                this.remove(RemovalReason.DISCARDED);
            }
        }
    }

public void tick() {
        if (this.level != null) {
            ++this.tickCount;
            if (this.level instanceof ServerLevel serverLevel) {
                int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
                if (this.target == null) {
                    for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                            boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                            if (this.getTrueOwner() != null) {
                                flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                            } else {
                                flag &= !this.isAllyWith(livingEntity);
                            }
                            if (flag) {
                                this.target = livingEntity;
                            }
                        }
                    }
                } else {
                    if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                        this.attackTick = 0;
                        this.target = null;
                    } else {
                        ++this.attackTick;
                        if (this.attackTick % 20 == 0) {
                            Vec3 vector3d1 = this.getBlockPos().getCenter();
                            DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                            this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                            if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                                ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                                serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                                Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                                serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                for (int i = 0; i < 8; ++i) {
                                    Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                                }
                                this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                if (this.getTrueOwner() instanceof Player player) {
                                    if (SEHelper.getSoulGiven(this.target) > 0) {
                                        int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                        SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.yBodyRot = this.getYRot();
        if (this.onGround() && groundProgress < 5F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0F) {
            groundProgress--;
        }
        if (!level().isClientSide) {
            Entity winch = getWinch();
            if (winch == null) {
                LivingEntity created = createWinch();
                level().addFreshEntity(created);
                this.setWinchUUID(created.getUUID());
                this.entityData.set(WINCH_ID, created.getId());
            } else {
                if (winch instanceof BoundroidWinchEntity winchEntity) {
                    winchEntity.linkWithHead(this);
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                Vec3 distanceVec = target.position().subtract(this.position());
                if (distanceVec.horizontalDistance() < 1.2 && stopSlammingFor == 0) {
                    this.setSlamming(true);
                }
            }
            if (this.isSlamming()) {
                this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, -1, this.getDeltaMovement().z));
                if (this.onGround()) {
                    this.setSlamming(false);
                    this.playSound(ACSoundRegistry.BOUNDROID_SLAM.get());
                    this.stayOnGroundFor = 10;
                    this.stopSlammingFor = 30 + random.nextInt(20);
                    this.level().broadcastEntityEvent(this, (byte) 45);
                    AABB bashBox = new AABB(-1.5F, -2F, -1.5F, 1.5F, 1F, 1.5F);
                    bashBox = bashBox.move(this.position());
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                        if (!isAlliedTo(entity) && !(entity instanceof BoundroidEntity) && !(entity instanceof BoundroidWinchEntity)) {
                            entity.hurt(damageSources().mobAttack(this), 5);
                        }
                    }
                }
            }
        }else if(isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 12);
        }
        if (stopSlammingFor > 0) {
            stopSlammingFor--;
        }
        if (stayOnGroundFor > 0) {
            stayOnGroundFor--;
        }
    }

public void tick(){
            LivingEntity target = EntityMurmurHead.this.getTarget();
            Entity body = EntityMurmurHead.this.getBody();
            if(target != null){
                double dist = Math.sqrt(EntityMurmurHead.this.distanceToSqr(target.getEyePosition()));
                double bodyDist = body != null ? body.distanceTo(target) : 0.0;
                if(bodyDist > 16 && time > 30){
                    if(body instanceof EntityMurmur){
                        EntityMurmur murmur = (EntityMurmur) body;
                        murmur.setTarget(target);
                        murmur.getNavigation().moveTo(target, 1.35D);
                    }
                }
                if(bodyDist > 64){
                    EntityMurmurHead.this.setPulledIn(true);
                }else if(biteCooldown == 0){
                    EntityMurmurHead.this.setPulledIn(false);
                    Vec3 moveTo = target.getEyePosition();
                    if(time > 30){
                        if(!EntityMurmurHead.this.isAngry()){
                            EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ANGER.get(), 1.5F * EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                            EntityMurmurHead.this.gameEvent(GameEvent.ENTITY_ROAR);
                        }
                        EntityMurmurHead.this.setAngry(true);
                        EntityMurmurHead.this.getNavigation().moveTo(moveTo.x, moveTo.y, moveTo.z, 1.3D);
                    }else{
                        if(time == 0){
                            emergeFrom = EntityMurmurHead.this.getNeckTop(1.0F).add(0, 0.5F, 0);
                            Vec3 face = moveTo.subtract(emergeFrom);
                        }
                        boolean clockwise = false;
                        float circleDistance = 2.5F;
                        float circlingTime = 30 * time;
                        float angle = (Maths.STARTING_ANGLE * (clockwise ? -circlingTime : circlingTime));
                        double extraX = circleDistance * Mth.sin(Mth.PI + angle);
                        double extraZ = circleDistance * Mth.cos(angle);
                        double y = Math.max(emergeFrom.y + 2, target.getEyeY());
                        Vec3 vec3 = new Vec3(emergeFrom.x + extraX, y, emergeFrom.z + extraZ);
                        EntityMurmurHead.this.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 0.7D);
                    }
                    EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, moveTo);
                    if(dist < 1.5F && EntityMurmurHead.this.hasLineOfSight(target)){
                        EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ATTACK.get(), EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                        biteCooldown = 5 + EntityMurmurHead.this.getRandom().nextInt(15);
                        target.hurt(EntityMurmurHead.this.damageSources().mobAttack(EntityMurmurHead.this), 5.0F);
                    }
                }else{
                    EntityMurmurHead.this.setPulledIn(true);
                    EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                    EntityMurmurHead.this.setAngry(false);
                }
                time++;
            }
            if(biteCooldown > 0){
                biteCooldown--;
            }
        }

public void tick() {
        super.tick();
        this.setYHeadRot(this.getYRot());
        prevMergeProgress = mergeProgress;
        prevAttackProgress = attackProgress;
        if (prevHeadCount != this.getHeadCount()) {
            refreshDimensions();
            if (this.mergeProgress < 5.0F) {
                this.mergeProgress++;
            } else {
                this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(Mth.clamp(getHeadCount() * 10, 10, 100));
                this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(Mth.clamp(getHeadCount() * 2, 2, 10));
                double d = this.getAttribute(Attributes.MAX_HEALTH).getValue();
                if(this.getHealth() < d && getHeadCount() > 0){
                    this.heal((float) Math.ceil(d - this.getHealth()));
                }
                prevHeadCount = this.getHeadCount();
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            LivingEntity target = this.getTarget();
            if (attackProgress >= 3F && target != null && this.distanceTo(target) < getSlimeSize(1.0F)) {
                target.hurt(damageSources().mobAttack(this), 4F + getHeadCount() * 2);
            }
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if (level().isClientSide && isAlive()) {
            float slimeSize = getSlimeSize(1);
            for (int i = 0; i < Math.ceil(slimeSize); i++) {
                double particleX = this.getX() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleY = this.getY() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleZ = this.getZ() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                level().addParticle(ACParticleRegistry.FERROUSLIME.get(), particleX, particleY, particleZ, this.getId(), 0, 0);
            }
            AlexsCaves.PROXY.playWorldSound(this, (byte) 13);
        } else {
            LivingEntity living = this.getTarget();
            if (living != null && living.isAlive()) {
                if (this.getDeltaMovement().length() < 0.1) {
                    noMoveTime++;
                } else {
                    noMoveTime = 0;
                }
                if (noMoveTime > 40 && mergeCooldown <= 0) {
                    split(1200);
                }
            }
        }
        if (mergeCooldown > 0) {
            mergeCooldown--;
        }
    }

@Override
	public void tick() {
		double lastTickPosX = this.xOld;
		double lastTickPosY = this.yOld;
		double lastTickPosZ = this.zOld;

		super.tick();

		if (!level().isClientSide && (!findTarget() || time > 40)) {
			discard();
			return;
		}

		boolean evil = isEvil();
		Vec3 thisVec = VecHelper.fromEntityCenter(this);
		Vec3 oldPos = new Vec3(lastTickPosX, lastTickPosY, lastTickPosZ);
		Vec3 diff = thisVec.subtract(oldPos);
		Vec3 step = diff.normalize().scale(0.05);
		int steps = (int) (diff.length() / step.length());
		Vec3 particlePos = oldPos;

		SparkleParticleData data = evil ? SparkleParticleData.corrupt(0.8F, 1F, 0.0F, 1F, 2)
				: SparkleParticleData.sparkle(0.8F, 1F, 0.4F, 1F, 2);
		for (int i = 0; i < steps; i++) {
			level().addParticle(data, particlePos.x, particlePos.y, particlePos.z, 0, 0, 0);

			if (level().random.nextInt(steps) <= 1) {
				level().addParticle(data, particlePos.x + (Math.random() - 0.5) * 0.4, particlePos.y + (Math.random() - 0.5) * 0.4, particlePos.z + (Math.random() - 0.5) * 0.4, 0, 0, 0);
			}

			particlePos = particlePos.add(step);
		}

		LivingEntity target = getTargetEntity();
		if (target != null) {
			if (lockY == Integer.MIN_VALUE) {
				lockX = target.getX();
				lockY = target.getY();
				lockZ = target.getZ();
			}

			Vec3 targetVec = evil ? new Vec3(lockX, lockY, lockZ) : VecHelper.fromEntityCenter(target);
			Vec3 diffVec = targetVec.subtract(thisVec);
			Vec3 motionVec = diffVec.normalize().scale(evil ? 0.5 : 0.6);
			setDeltaMovement(motionVec);
			if (time < 10) {
				setDeltaMovement(getDeltaMovement().x(), Math.abs(getDeltaMovement().y()), getDeltaMovement().z());
			}

			List<LivingEntity> targetList = level().getEntitiesOfClass(LivingEntity.class, new AABB(getX() - 0.5, getY() - 0.5, getZ() - 0.5, getX() + 0.5, getY() + 0.5, getZ() + 0.5));
			if (targetList.contains(target)) {
				target.hurt(this.getDamageSource(), evil ? 12 : 7);
				discard();
			}

			if (evil && diffVec.length() < 1) {
				discard();
			}
		}

		time++;
	}

@Override
    public void releaseUsing(@NotNull ItemStack stack, Level worldIn, LivingEntity entity, int timeLeft) {
        double dist = 32;
        Vec3 Vector3d = entity.getEyePosition(1.0F);
        Vec3 Vector3d1 = entity.getViewVector(1.0F);
        Vec3 Vector3d2 = Vector3d.add(Vector3d1.x * dist, Vector3d1.y * dist, Vector3d1.z * dist);
        double d1 = dist;
        Entity pointedEntity = null;
        List<Entity> list = worldIn.getEntities(entity, entity.getBoundingBox().expandTowards(Vector3d1.x * dist, Vector3d1.y * dist, Vector3d1.z * dist).inflate(1.0D, 1.0D, 1.0D), new Predicate<Entity>() {
            @Override
            public boolean apply(@Nullable Entity entity) {
                boolean blindness = entity instanceof LivingEntity && ((LivingEntity) entity).hasEffect(MobEffects.BLINDNESS) || (entity instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) entity).canBeTurnedToStone());
                return entity != null && entity.isPickable() && !blindness && (entity instanceof Player || (entity instanceof LivingEntity && DragonUtils.isAlive((LivingEntity) entity)));
            }
        });
        double d2 = d1;
        for (int j = 0; j < list.size(); ++j) {
            Entity entity1 = list.get(j);
            AABB axisalignedbb = entity1.getBoundingBox().inflate(entity1.getPickRadius());
            Optional<Vec3> optional = axisalignedbb.clip(Vector3d, Vector3d2);

            if (axisalignedbb.contains(Vector3d)) {
                if (d2 >= 0.0D) {
                    //pointedEntity = entity1;
                    d2 = 0.0D;
                }
            } else if (optional.isPresent()) {
                double d3 = Vector3d.distanceTo(optional.get());

                if (d3 < d2 || d2 == 0.0D) {
                    if (entity1.getRootVehicle() == entity.getRootVehicle() && !entity.canRiderInteract()) {
                        if (d2 == 0.0D) {
                            pointedEntity = entity1;
                        }
                    } else {
                        pointedEntity = entity1;
                        d2 = d3;
                    }
                }
            }
        }
        if (pointedEntity != null) {
            if (pointedEntity instanceof LivingEntity) {
                pointedEntity.playSound(IafSoundRegistry.TURN_STONE, 1, 1);
                EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity((LivingEntity) pointedEntity);
                if (pointedEntity instanceof Player) {
                    pointedEntity.hurt(IafDamageRegistry.causeGorgonDamage(pointedEntity), Integer.MAX_VALUE);
                } else {
                    if (!worldIn.isClientSide)
                        pointedEntity.remove(Entity.RemovalReason.KILLED);
                }
                statue.absMoveTo(pointedEntity.getX(), pointedEntity.getY(), pointedEntity.getZ(), pointedEntity.getYRot(), pointedEntity.getXRot());
                statue.yBodyRot = pointedEntity.getYRot();
                if (!worldIn.isClientSide) {
                    worldIn.addFreshEntity(statue);
                }
                if (entity instanceof Player && !((Player) entity).isCreative()) {
                    stack.shrink(1);
                }
            }
        }
        stack.getTag().putBoolean("Active", false);
    }

public void onUse(World world, BlockPos pos, LivingEntity user, Hand hand, LivingEntity sacrifice) {
		ItemStack stack = user.getStackInHand(hand);
		if (ritualFunction != null && pos.equals(effectivePos) && stack.getItem() instanceof WaystoneItem && stack.hasNbt() && stack.getOrCreateNbt().contains("LocationPos") && world.getRegistryKey().getValue().toString().equals(stack.getOrCreateNbt().getString("LocationWorld"))) {
			effectivePos = BlockPos.fromLong(stack.getOrCreateNbt().getLong("LocationPos"));
			stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(hand));
			syncGlyph();
		} else {
			if (ritualFunction == null) {
				SimpleInventory test = new SimpleInventory(size());
				List<ItemEntity> items = world.getEntitiesByType(EntityType.ITEM, new Box(pos).expand(2, 0, 2), entity -> true);
				for (ItemEntity entity : items) {
					test.addStack(entity.getStack().copy().split(1));
				}
				RitualRecipe recipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.RITUAL_RECIPE_TYPE).stream().filter(ritualRecipe -> ritualRecipe.matches(test, world)).findFirst().orElse(null);
				if (recipe != null && recipe.input.size() == items.size() && hasValidChalk(recipe)) {
					if (recipe.ritualFunction.isValid((ServerWorld) world, pos, test) || (recipe.ritualFunction.sacrifice != null && sacrifice != null && recipe.ritualFunction.sacrifice.test(sacrifice))) {
						boolean cat = user instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.CAT;
						if (altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(altarPos)).drain((int) (recipe.cost * (cat ? 0.75f : 1)), false)) {
							world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FIRE, SoundCategory.BLOCKS, 1, 1);
							if (user instanceof PlayerEntity player) {
								player.sendMessage(Text.translatable("ritual." + recipe.getId().toString().replace(":", ".").replace("/", ".")), true);
							}
							for (int i = 0; i < items.size(); i++) {
								ItemEntity item = items.get(i);
								PlayerLookup.tracking(item).forEach(foundPlayer -> SpawnSmokeParticlesPacket.send(foundPlayer, item));
								setStack(i, item.getStack().split(1));
							}
							effectivePos = pos;
							ritualFunction = recipe.ritualFunction;
							timer = -100;
							endTime = recipe.runningTime;
							catFamiliar = cat;
							syncGlyph();
							return;
						}
						world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
						if (user instanceof PlayerEntity player) {
							player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
						}
						return;
					}
					world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
					if (user instanceof PlayerEntity player) {
						player.sendMessage(Text.translatable(recipe.ritualFunction.getInvalidMessage()), true);
					}
					return;
				}
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				if (user instanceof PlayerEntity player) {
					player.sendMessage(Text.translatable("ritual.none"), true);
				}
			} else if (sacrifice == null) {
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				ItemScatterer.spawn(world, pos, this);
				effectivePos = null;
				ritualFunction = null;
				timer = 0;
				endTime = 0;
				catFamiliar = false;
				syncGlyph();
			}
		}
	}

@SuppressWarnings("deprecation")
	@Override
	public void tick() {
		Purpoid purpoid = this.purpoid;
		if (purpoid.isNoEndimationPlaying()) {
			Purpoid.TeleportController teleportController = purpoid.getTeleportController();
			if (!teleportController.isTeleporting()) {
				boolean sky = this.teleportPattern.next();
				BlockPos teleportPos = null;
				BlockPos pos = purpoid.blockPosition();
				RandomSource random = purpoid.getRandom();
				Level world = purpoid.level();
				Entity ridingEntity = purpoid.getVehicle();
				if (sky) {
					EntityDimensions size = purpoid.getDimensions(purpoid.getPose());
					for (int i = 0; i < 16; i++) {
						BlockPos randomPos = pos.offset(random.nextInt(32) - random.nextInt(32), random.nextInt(32) + 8, random.nextInt(32) - random.nextInt(32));
						AABB collisionBox = size.makeBoundingBox(randomPos.getX() + 0.5F, randomPos.getY(), randomPos.getZ() + 0.5F);
						if (world.hasChunkAt(randomPos) && world.noCollision(collisionBox) && !world.containsAnyLiquid(collisionBox)) {
							teleportPos = randomPos;
							break;
						}
					}
				} else {
					EntityDimensions size = ridingEntity.getDimensions(ridingEntity.getPose());
					int x = pos.getX();
					int z = pos.getZ();
					for (int i = 0; i < 32; i++) {
						int randomX = x + (random.nextInt(32) - random.nextInt(32));
						int randomZ = z + (random.nextInt(32) - random.nextInt(32));
						BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(randomX, (int) ridingEntity.getY(), randomZ);
						if (world.hasChunkAt(mutable)) {
							boolean successful = true;
							while (true) {
								int y = mutable.getY();
								if (y > 0 && !world.getBlockState(mutable).blocksMotion()) {
									mutable.setY(y - 1);
								} else if (y <= 0) {
									successful = false;
									break;
								} else {
									break;
								}
							}
							if (successful) {
								mutable.move(Direction.UP);
								AABB collisionBox = size.makeBoundingBox(mutable.getX() + 0.5F, mutable.getY(), mutable.getZ() + 0.5F);
								if (world.noCollision(collisionBox) && !world.containsAnyLiquid(collisionBox)) {
									teleportPos = mutable;
									break;
								}
							}
						}
					}
				}
				if (teleportPos != null) {
					teleportController.beginTeleportation(purpoid, teleportPos, true);
					ridingEntity.hurt(purpoid.level().damageSources().mobAttack(purpoid), (float) purpoid.getAttributeValue(Attributes.ATTACK_DAMAGE));
					if (ridingEntity instanceof ServerPlayer) {
						EndergeticExpansion.CHANNEL.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) ridingEntity), new S2CEnablePurpoidFlash());
					}
				}
			}
		}
	}

@Override
    public void tick() {
        super.tick();
        prevStab = this.getStab();
        Entity entity = getTargetEntity();
        if (level().isClientSide) {
            level().addParticle(DustParticleOptions.REDSTONE, (double) this.getRandomX(0.75F), (double) this.getRandomY(), (double) this.getRandomZ(0.75F), 0.0D, 0.0D, 0.0D);
        }
        if (!playedSummonNoise) {
            this.playSound(ACSoundRegistry.DESOLATE_DAGGER_SUMMON.get());
            playedSummonNoise = true;
        }
        if (entity != null) {
            this.noPhysics = true;
            float invStab = 1F - getStab();
            Vec3 orbitAround = entity.position().add(0, entity.getBbHeight() * 0.25F, 0);
            orbitRandom.setSeed(this.getId());
            if (orbitOffset == 0) {
                orbitOffset = orbitRandom.nextInt(360);
            }
            Vec3 orbitAdd = new Vec3(0, (orbitRandom.nextFloat() + entity.getBbHeight()) * invStab, (orbitRandom.nextFloat() + entity.getBbWidth()) * invStab).yRot((float) Math.toRadians((orbitOffset)));
            this.setDeltaMovement(orbitAround.add(orbitAdd).subtract(this.position()));
            if (!level().isClientSide) {
                if (orbitFor > 0 && entity.isAlive()) {
                    orbitFor--;
                } else {
                    this.setStab(Math.min(this.getStab() + 0.2F, 1F));
                }
                if (this.getStab() >= 1F) {
                    Entity player = getPlayer();
                    Entity damageFrom = player == null ? this : player;
                    float damage = 2 + this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.IMPENDING_STAB.get()) * 2F;
                    if (entity.hurt(ACDamageTypes.causeDesolateDaggerDamage(this.level().registryAccess(), damageFrom), damage)) {
                        this.playSound(ACSoundRegistry.DESOLATE_DAGGER_HIT.get());
                        int healBy = this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.SATED_BLADE.get());
                        if(healBy > 0 && damageFrom instanceof Player healPlayer && healPlayer.getFoodData().getSaturationLevel() < 5F){
                            healPlayer.getFoodData().setSaturation(healPlayer.getFoodData().getSaturationLevel() + healBy * 0.1F);
                        }
                    }
                    this.discard();
                }
            }
            double d1 = entity.getZ() - this.getZ();
            double d3 = entity.getEyeY() - this.getEyeY();
            double d2 = entity.getX() - this.getX();
            float f = Mth.sqrt((float) (d2 * d2 + d1 * d1));
            this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
            this.setXRot(-(float) (Mth.atan2(d3, f) * (double) (180F / (float) Math.PI)));
        } else if (tickCount > 3) {
            this.noPhysics = false;
            this.discard();
        }
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));

        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
        }
    }

@SubscribeEvent
        public static void onPlayerFall(LivingFallEvent event) {
            if (event.getDistance() > 3.0F && event.getEntity() instanceof Player player) {
                float origDistance = event.getDistance();

                CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(player);

                JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
                if (event.getEntity().level().getDifficulty() == Difficulty.HARD && jbState.isActive()) {
                    // thrusting into the ground hurts at hard difficulty!
                    event.setDamageMultiplier(0.2F);
                    return;
                }
                if (handler.upgradeUsable(CommonUpgradeHandlers.jumpBoostHandler, true)) {
                    // straight fall distance reduction if jump upgrade operational in legs
                    event.setDistance(Math.max(0, event.getDistance() - 1.5f * handler.getUpgradeCount(EquipmentSlot.LEGS, ModUpgrades.JUMPING.get())));
                    if (event.getDistance() < 2) {
                        event.setCanceled(true);
                        return;
                    }
                }
                if (!handler.upgradeUsable(CommonUpgradeHandlers.fallProtectionHandler, true)) {
                    return;
                }

                if (!player.level().isClientSide) {
                    float airNeeded = event.getDistance() * PneumaticValues.PNEUMATIC_ARMOR_FALL_USAGE;
                    float extraAirNeeded = 0f;

                    int airAvailable = handler.getAir(EquipmentSlot.FEET);
                    List<Entity> stomped = new ArrayList<>();
                    if (handler.upgradeUsable(CommonUpgradeHandlers.stompHandler, true)) {
                        for (Entity e: player.level().getEntities(player, new AABB(player.blockPosition()).inflate(7.0), e -> e instanceof Mob && e.isAlive())) {
                            if (airAvailable > airNeeded + extraAirNeeded) {
                                stomped.add(e);
                                extraAirNeeded += airNeeded;
                            } else {
                                break;
                            }
                        }
                    }
                    if (airAvailable < 1) {
                        return;
                    } else if (airAvailable >= airNeeded + extraAirNeeded) {
                        event.setCanceled(true);
                    } else {
                        event.setDamageMultiplier(1.0F - (airAvailable / airNeeded));
                    }
                    for (int i = 0; i < event.getDistance() / 2; i++) {
                        float sx = player.getRandom().nextFloat() * 0.6F - 0.3F;
                        float sz = player.getRandom().nextFloat() * 0.6F - 0.3F;
                        NetworkHandler.sendToAllTracking(PacketSpawnParticle.oneParticle(AirParticleData.DENSE,
                                player.position().toVector3f(),
                                new Vector3f(sx, 0.1f, sz)
                        ), player.level(), player.blockPosition());
                    }
                    for (Entity e : stomped) {
                        NetworkHandler.sendToAllTracking(PacketSpawnParticle.oneParticle(ParticleTypes.EXPLOSION,
                                e.position().toVector3f(),
                                PneumaticCraftUtils.VEC3F_ZERO
                        ), player.level(), player.blockPosition());
                        e.hurt(player.damageSources().explosion(player, null), Mth.clamp(origDistance / 3f, 1f, 20f));
                    }
                    if (!stomped.isEmpty()) {
                        player.level().playSound(null, player.blockPosition(), SoundEvents.GENERIC_EXPLODE.value(), SoundSource.PLAYERS, 1f, 0.5f);
                    }
                    player.level().playSound(null, player.blockPosition(), ModSounds.SHORT_HISS.get(), SoundSource.PLAYERS, 0.3f, 0.8f);
                    handler.addAir(EquipmentSlot.FEET, (int) -(airNeeded + extraAirNeeded));
                }
            }
        }

@Override
	public void curioTick(SlotContext context, ItemStack stack) {
		if (context.entity() instanceof Player player) {
			/*
			FoodData stats = player.getFoodStats();
			stats.setFoodLevel(20);

			//((AccessorFoodStats) stats).setFoodSaturationLevel(0);


			try {
				ObfuscatedFields.foodSaturationField.setFloat(stats, 0F);
			} catch (Exception ex) {
				ex.printStackTrace();
			}

			 */

			if (player.getAirSupply() < 300) {
				player.setAirSupply(300);
			}

			if (player.isOnFire()) {
				player.clearFire();
			}

			for (MobEffectInstance effect : new ArrayList<>(player.getActiveEffects())) {
				if (effect.getEffect() == MobEffects.NIGHT_VISION) {
					if (effect.getDuration() >= EnigmaticItems.MINING_CHARM.nightVisionDuration-10 && effect.getDuration() <= EnigmaticItems.MINING_CHARM.nightVisionDuration) {
						continue;
					}
				} else if (ForgeRegistries.MOB_EFFECTS.getKey(effect.getEffect()).equals(new ResourceLocation("mana-and-artifice", "chrono-exhaustion"))) {
					continue;
				}

				player.removeEffect(effect.getEffect());
			}

			if (player.tickCount % 10 == 0) {
				List<LivingEntity> entities = player.level().getEntitiesOfClass(LivingEntity.class, new AABB(player.getX() - shadowRange.getValue(), player.getY() - shadowRange.getValue(), player.getZ() - shadowRange.getValue(), player.getX() + shadowRange.getValue(), player.getY() + shadowRange.getValue(), player.getZ() + shadowRange.getValue()));
				boolean hasAnimalGuide = SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK);

				if (entities.contains(player)) {
					entities.remove(player);
				}

				for (LivingEntity victim : entities) {
					if (victim.level().getMaxLocalRawBrightness(victim.blockPosition(), 0) < 3 || (victim instanceof Phantom && !victim.isOnFire())) {
						if (hasAnimalGuide && EnigmaticItems.ANIMAL_GUIDEBOOK.isProtectedAnimal(victim)) {
							continue;
						}

						if (victim instanceof Player) {
							Player playerVictim = (Player) victim;
							if (SuperpositionHandler.hasCurio(playerVictim, EnigmaticItems.VOID_PEARL)) {
								playerVictim.addEffect(new MobEffectInstance(MobEffects.WITHER, 80, 1, false, true));
								continue;
							}
						}

						if (!(victim instanceof Player) || player.canHarmPlayer((Player) victim)) {
							boolean attack = victim.hurt(victim.damageSources().source(EnigmaticDamageTypes.DARKNESS, player), (float) baseDarknessDamage.getValue());

							if (attack) {
								player.level().playSound(null, victim.blockPosition(), SoundEvents.PHANTOM_BITE, SoundSource.PLAYERS, 1.0F, (float) (0.3F + (Math.random() * 0.4D)));

								victim.addEffect(new MobEffectInstance(MobEffects.WITHER, 80, 1, false, true));
								victim.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 100, 2, false, true));
								victim.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 100, 0, false, true));
								victim.addEffect(new MobEffectInstance(MobEffects.HUNGER, 160, 2, false, true));
								victim.addEffect(new MobEffectInstance(MobEffects.DIG_SLOWDOWN, 100, 3, false, true));
							}
						}
					}
				}
			}
		}

	}

@Override
    public void tick() {
        float progress = this.getProgress();
        this.prevProgress = progress;
        if(tickCount < 1){
            onJoinWorld();
        }else if(tickCount == 1){
            if(!this.level().isClientSide){
                this.playSound(AMSoundRegistry.TENDON_WHIP.get(),1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if(progress < MAX_EXTEND_TIME && !this.isRetracting()){
            this.setProgress(progress + 1);
        }
        if(progress > 0F && this.isRetracting()){
            this.setProgress(progress - 1);
        }
        if(progress == 0F && this.isRetracting()){
            Entity from = this.getFromEntity();
            if(from instanceof EntityTendonSegment){
                EntityTendonSegment tendonSegment = (EntityTendonSegment) from;
                tendonSegment.setRetracting(true);
                updateLastTendon(tendonSegment);
            }else{
                updateLastTendon(null);
            }

            this.remove(RemovalReason.DISCARDED);
        }
        if (creator instanceof LivingEntity) {
            if (current != null) {
                Vec3 target = new Vec3(current.getX(), current.getY(0.4F), current.getZ());
                Vec3 lerp = target.subtract(this.position());
                this.setDeltaMovement(lerp.scale(0.5F));
                if(!this.level().isClientSide){
                    if(!hasTouched && progress >= MAX_EXTEND_TIME){
                        hasTouched = true;
                        Entity entity = getCreatorEntity();
                        if(entity instanceof LivingEntity){
                            if(current != creator && current.hurt(damageSources().mobProjectile(this, (LivingEntity)entity), (float) getDamageFor((LivingEntity)creator, (LivingEntity)entity))){
                                this.doEnchantDamageEffects((LivingEntity) creator, entity);
                            }
                        }
                    }
                }
            }
        }
        Vec3 vector3d = this.getDeltaMovement();
        if(!this.level().isClientSide){
            if(!hasChained){
                if(this.getTargetsHit() > 3){
                    this.setRetracting(true);
                }else if(creator instanceof LivingEntity && this.getProgress() >= MAX_EXTEND_TIME) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(8.0D))) {
                        if (!entity.equals(creator) && !previouslyTouched.contains(entity) && isValidTarget((LivingEntity) creator, entity) && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createChain(closestValid);
                        hasChained = true;
                    }else{
                        this.setRetracting(true);
                    }
                }
            }
        }
        final double d0 = this.getX() + vector3d.x;
        final double d1 = this.getY() + vector3d.y;
        final double d2 = this.getZ() + vector3d.z;
        this.setDeltaMovement(vector3d.scale(0.99F));
        this.setPos(d0, d1, d2);
    }

@Override
	public void tick() {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player player) || !thrower.isAlive()) {
			if (!level().isClientSide) {
				discard();
			}
			return;
		}
		if (!level().isClientSide) {
			ItemStack stack = PlayerHelper.getFirstHeldItem(player, BotaniaItems.kingKey);
			boolean newCharging = !stack.isEmpty() && KeyOfTheKingsLawItem.isCharging(stack);
			if (isCharging() != newCharging) {
				setCharging(newCharging);
			}
		}

		Vec3 mot = getDeltaMovement();

		int liveTime = getLiveTicks();
		int delay = getDelay();
		boolean charging = isCharging() && liveTime == 0;

		if (charging) {
			setDeltaMovement(Vec3.ZERO);

			int chargeTime = getChargeTicks();
			setChargeTicks(chargeTime + 1);

			if (level().random.nextInt(20) == 0) {
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonSpawn, SoundSource.PLAYERS, 0.1F, 1F + level().random.nextFloat() * 3F);
			}
		} else {
			if (liveTime < delay) {
				setDeltaMovement(Vec3.ZERO);
			} else if (liveTime == delay) {
				Vec3 playerLook;
				BlockHitResult rtr = ToolCommons.raytraceFromEntity(player, 64, true);
				if (rtr.getType() != HitResult.Type.BLOCK) {
					playerLook = player.getLookAngle().scale(64).add(player.position());
				} else {
					playerLook = Vec3.atCenterOf(rtr.getBlockPos());
				}

				Vec3 thisVec = VecHelper.fromEntityCenter(this);

				mot = playerLook.subtract(thisVec.x, thisVec.y, thisVec.z).normalize().scale(2);
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonAttack, SoundSource.PLAYERS, 2F, 0.1F + level().random.nextFloat() * 3F);
			}

			if (!level().isClientSide) {
				setLiveTicks(liveTime + 1);
				AABB axis = new AABB(getX(), getY(), getZ(), xOld, yOld, zOld).inflate(2);
				List<LivingEntity> entities = level().getEntitiesOfClass(LivingEntity.class, axis);
				for (LivingEntity living : entities) {
					if (living == thrower) {
						continue;
					}

					if (living.hurtTime == 0) {
						living.hurt(level().damageSources().playerAttack(player), 20);
						onHit(new EntityHitResult(living));
						return;
					}
				}
			}
		}

		super.tick();

		// Apply after super tick so drag is not applied by super
		setDeltaMovement(mot);

		if (level().isClientSide && liveTime > delay) {
			WispParticleData data = WispParticleData.wisp(0.3F, 1F, 1F, 0F, 1);
			level().addParticle(data, getX(), getY(), getZ(), 0, -0F, 0);
		}

		if (!level().isClientSide && liveTime > 200 + delay) {
			discard();
		}
	}

@Override
    public void tick() {
        super.tick();

        var level = getCommandSenderWorld();

        var particleCenter = this.position().add(this.getDeltaMovement().scale(-1F));

        for (int i = 0; i < 5; i++)
            level.addParticle(ParticleUtils.constructSimpleSpark(new Color(50 + random.nextInt(100), 0, 150 + random.nextInt(100)), 0.1F + random.nextFloat() * 0.15F, 5 + random.nextInt(10), 0.85F),
                    particleCenter.x() + MathUtils.randomFloat(random) * 0.25F, particleCenter.y(), particleCenter.z() + MathUtils.randomFloat(random) * 0.25F, 0F, 0F, 0F);

        var currentTarget = getTarget();

        if (currentTarget != null && (this.position().distanceTo(currentTarget.position()) >= 16F || currentTarget.isDeadOrDying()))
            currentTarget = null;

        if (!level.isClientSide()) {
            LivingEntity potentialTarget = null;

            var candidateEntities = locateNearestTargets();

            candidateEntities.removeIf(entity -> blacklistedTargets.contains(entity.getStringUUID()));

            var targetEntities = candidateEntities.stream()
                    .filter(entity -> {
                        var uuid = entity.getStringUUID();

                        return !bouncedTargets.contains(uuid) && !blacklistedTargets.contains(uuid);
                    })
                    .toList();

            if (!targetEntities.isEmpty())
                potentialTarget = targetEntities.getFirst();
            else if (!candidateEntities.isEmpty()) {
                bouncedTargets.clear();

                potentialTarget = candidateEntities.getFirst();
            }

            if (potentialTarget != null && (currentTarget == null || !currentTarget.getStringUUID().equals(potentialTarget.getStringUUID()))) {
                NetworkHandler.sendToClientsTrackingEntity(new S2CSyncEntityTargetPacket(this.getId(), potentialTarget.getId()), this);

                setTarget(potentialTarget);

                currentTarget = potentialTarget;
            }
        }

        if (currentTarget == null || currentTarget.isDeadOrDying() || this.tickCount >= 250 || getBounces() >= getMaxBounces()) {
            if (!level.isClientSide())
                this.discard();

            return;
        }

        if (this.getEyePosition().distanceTo(currentTarget.getEyePosition()) <= 1.5F) {
            currentTarget.invulnerableTime = 0;

            if (currentTarget.hurt(level.damageSources().thrown(this, getOwner()), getDamage())) {
                bouncedTargets.add(currentTarget.getStringUUID());
                lastTarget = currentTarget;

                setTarget(null);
                addBounces(1);

                if (random.nextDouble() <= getChance()) {
                    var entity = new ShadowGlaiveEntity(RelicsEntities.SHADOW_GLAIVE.get(), level);

                    entity.setMaxBounces(getMaxBounces());
                    entity.setBounces(getBounces());
                    entity.setPos(getEyePosition());
                    entity.setDamage(getDamage());
                    entity.setOwner(getOwner());

                    level.addFreshEntity(entity);
                }
            } else {
                blacklistedTargets.add(currentTarget.getStringUUID());

                setTarget(null);
            }
        } else {
            this.setDeltaMovement(currentTarget.getEyePosition().subtract(this.getEyePosition()).normalize());
        }
    }

public void attackTargetEntityWithCurrentItem(Entity targetEntity, Player player, float damageMult, float knockbackMult) {
        if (!CommonHooks.onPlayerAttackTarget(player, targetEntity) || !targetEntity.isAttackable()) {
            return;
        }

        ItemStack oldStack = player.getMainHandItem();
        ItemStack newStack = getAxeStack();
        resetModifiers(player, oldStack, newStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, newStack);

        // Check this after swapping main hand in cases the main hand item impacts the result
        if (targetEntity.skipAttackInteraction(player)) {
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        if (targetEntity.getType().is(EntityTypeTags.REDIRECTABLE_PROJECTILE) && targetEntity instanceof Projectile projectile && projectile.deflect(ProjectileDeflection.AIM_DEFLECT, this, this, true)) {
            this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, this.getSoundSource());
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        DamageSource damageSource = damageSources().playerAttack(player);

        float attackDamage = (float) player.getAttributeValue(Attributes.ATTACK_DAMAGE) * damageMult;
        float enchantedDamage = player.getEnchantedDamage(targetEntity, attackDamage, damageSource);

        if (attackDamage > 0 || enchantedDamage > 0) {
            boolean wasSprinting = false;

            if (player.isSprinting()) {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, player.getSoundSource(), 1.0F, 1.0F);
                wasSprinting = true;
            }

            attackDamage += newStack.getItem().getAttackDamageBonus(targetEntity, attackDamage, damageSource);
            float damage = attackDamage + enchantedDamage;
            float targetHealth = targetEntity instanceof LivingEntity livingTarget ? livingTarget.getHealth() : 0;

            Vec3 targetMovement = targetEntity.getDeltaMovement();
            boolean wasHurt = targetEntity.hurt(damageSource, damage);

            if (wasHurt) {
                float knockback = player.getKnockback(targetEntity, damageSource) + (wasSprinting ? 1 : 0);

                if (knockback > 0) {
                    if (targetEntity instanceof LivingEntity livingTarget) {
                        livingTarget.knockback(knockback * 0.5F * knockbackMult, Mth.sin(player.getYRot() * ((float) Math.PI / 180F)), -Mth.cos(player.getYRot() * ((float) Math.PI / 180F)));
                    } else {
                        targetEntity.push(-Mth.sin(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult, 0.1D, Mth.cos(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult);
                    }

                    player.setDeltaMovement(player.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
                    player.setSprinting(false);
                }

                if (targetEntity instanceof ServerPlayer && targetEntity.hurtMarked) {
                    ((ServerPlayer) targetEntity).connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
                    targetEntity.hurtMarked = false;
                    targetEntity.setDeltaMovement(targetMovement);
                }

                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_STRONG, player.getSoundSource(), 1.0F, 1.0F);

                if (enchantedDamage > 0) {
                    player.magicCrit(targetEntity);
                }

                player.setLastHurtMob(targetEntity);
                Entity entity = targetEntity;

                if (targetEntity instanceof PartEntity<?> part) {
                    entity = part.getParent();
                }

                ItemStack copy = newStack.copy();
                boolean hurtEnemy = false;

                if (level() instanceof ServerLevel serverLevel) {
                    if (entity instanceof LivingEntity livingEntity) {
                        hurtEnemy = newStack.hurtEnemy(livingEntity, player);
                    }

                    EnchantmentHelper.doPostAttackEffects(serverLevel, targetEntity, damageSource);
                }

                if (!level().isClientSide() && !copy.isEmpty() && entity instanceof LivingEntity livingEntity) {
                    if (hurtEnemy) {
                        newStack.postHurtEnemy(livingEntity, player);
                    }

                    if (newStack.isEmpty()) {
                        EventHooks.onPlayerDestroyItem(player, copy, InteractionHand.MAIN_HAND);
                        player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                }

                if (targetEntity instanceof LivingEntity livingTarget) {
                    float healthDifference = targetHealth - livingTarget.getHealth();
                    player.awardStat(Stats.DAMAGE_DEALT, Math.round(healthDifference * 10));

                    if (level() instanceof ServerLevel serverLevel && healthDifference > 2) {
                        int particleCount = (int) ((double) healthDifference * 0.5);
                        serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0.0, 0.1, 0.2);
                    }
                }

                player.causeFoodExhaustion(0.1F);
            } else {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, player.getSoundSource(), 1.0F, 1.0F);
            }
        }

        resetModifiers(player, newStack, oldStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
    }

@Override
    public void tick() {
        super.tick();
        if (getCaster() != null) {
            if (!getCaster().isAlive()) discard();
            absMoveTo(getCaster().getX(), getCaster().getY() + getCaster().getEyeHeight(), getCaster().getZ(), getCaster().getYRot(), getCaster().getXRot());
        }
        if (!level().isClientSide && tickCount == 7) playSound(MMSounds.ENTITY_WROUGHT_WHOOSH.get(), 0.7F, 1.1f);
        if (!level().isClientSide && getCaster() != null) {
            if (!getVertical() && tickCount == SWING_DURATION_HOR /2 - 1) dealDamage(7.0f * ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f, 4f, 160, 1.2f);
            else if (getVertical() && tickCount == SWING_DURATION_VER /2 - 1) {
                dealDamage(ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue(), 4.5f, 40, 0.8f);
                quakeAngle = getYRot();
                quakeBB = getBoundingBox().move(0, -getCaster().getEyeHeight(), 0);
                playSound(MMSounds.ENTITY_WROUGHT_AXE_LAND.get(), 0.3F, 0.5F);
                playSound(SoundEvents.GENERIC_EXPLODE.value(), 2, 0.9F + random.nextFloat() * 0.1F);
            }
            else if (getVertical() && tickCount == SWING_DURATION_VER /2 + 1) {
                EntityCameraShake.cameraShake(level(), position(), 10, 0.05f, 0, 10);
            }
        }

        if (getVertical() && getCaster() != null) {
            if (tickCount >= SWING_DURATION_VER /2) {
                int maxDistance = 16;
                double perpFacing = quakeAngle * (Math.PI / 180);
                double facingAngle = perpFacing + Math.PI / 2;
                int hitY = Mth.floor(quakeBB.minY - 0.5);
                int distance = tickCount - 15;
                double spread = Math.PI * 0.35F;
                int arcLen = Mth.ceil(distance * spread);
                double minY = quakeBB.minY;
                double maxY = quakeBB.maxY;
                for (int i = 0; i < arcLen; i++) {
                    double theta = (i / (arcLen - 1.0) - 0.5) * spread + facingAngle;
                    double vx = Math.cos(theta);
                    double vz = Math.sin(theta);
                    double px = getX() + vx * distance;
                    double pz = getZ() + vz * distance;
                    float factor = 1 - distance / (float) maxDistance;
                    AABB selection = new AABB(px - 1.5, minY, pz - 1.5, px + 1.5, maxY, pz + 1.5);
                    List<Entity> hit = level().getEntitiesOfClass(Entity.class, selection);
                    for (Entity entity : hit) {
                        if (entity.onGround()) {
                            if (entity == this || entity instanceof FallingBlockEntity || entity == getCaster()) {
                                continue;
                            }
                            float applyKnockbackResistance = 0;
                            boolean hitEntity = false;
                            if (!raytraceCheckEntity(entity)) continue;

                            if (getCaster() instanceof Player)
                                hitEntity = entity.hurt(damageSources().playerAttack((Player) getCaster()), (factor * 5 + 1) * (ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f));
                            else
                                hitEntity = entity.hurt(damageSources().mobAttack(getCaster()), (factor * 5 + 1) * (ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f));
                            if (entity instanceof LivingEntity) {
                                applyKnockbackResistance = (float) ((LivingEntity) entity).getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue();
                            }
                            if (hitEntity) {
                                double magnitude = -4;
                                double x = vx * (1 - factor) * magnitude * (1 - applyKnockbackResistance);
                                double y = 0;
                                if (entity.onGround()) {
                                    y += 0.15 * (1 - applyKnockbackResistance);
                                }
                                double z = vz * (1 - factor) * magnitude * (1 - applyKnockbackResistance);
                                entity.setDeltaMovement(entity.getDeltaMovement().add(x, y, z));
                                if (entity instanceof ServerPlayer) {
                                    ((ServerPlayer) entity).connection.send(new ClientboundSetEntityMotionPacket(entity));
                                }
                            }
                        }
                    }
                    if (level().random.nextBoolean()) {
                        int hitX = Mth.floor(px);
                        int hitZ = Mth.floor(pz);
                        BlockPos pos = new BlockPos(hitX, hitY, hitZ);
                        BlockPos abovePos = new BlockPos(pos).above();
                        BlockState block = level().getBlockState(pos);
                        BlockState blockAbove = level().getBlockState(abovePos);
                        if (!block.isAir() && block.isRedstoneConductor(level(), pos) && !block.hasBlockEntity() && !blockAbove.blocksMotion()) {
                            EntityFallingBlock fallingBlock = new EntityFallingBlock(EntityHandler.FALLING_BLOCK.get(), level(), block, 0.3f);
                            fallingBlock.setPos(hitX + 0.5, hitY + 1, hitZ + 0.5);
                            level().addFreshEntity(fallingBlock);
                        }
                    }
                }
            }
        }
        if (tickCount > SWING_DURATION_HOR) discard();
    }

public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            if (this.getWarmupDelayTicks() <= 0) {
                if (!this.sentSpikeEvent) {
                    this.sentSpikeEvent = true;
                    if (this.explodeEffect) {
                        SoundEvent soundEvent = SoundEvent.createVariableRangeEvent(new ResourceLocation(this.getSoundEvent()));
                        this.playSound(soundEvent, 1.0F, 1.0F);
                        ColorUtil colorUtil = new ColorUtil(this.getColor());
                        ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_CULT_SPELL.get(), this.getX(), this.getY() + 1.0F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius());
                        ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.ROLLING_SPIRAL.get(), this.getX(), this.getY() + 1.0F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius());
                        serverLevel.sendParticles(new SphereExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius(), 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                        serverLevel.sendParticles(new CircleExplodeParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius(), 1), this.getX(), this.getY(), this.getZ(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                    }
                }
            } else {
                --this.warmupDelayTicks;
                if (this.level.getRandom().nextBoolean()) {
                    ColorUtil colorUtil = new ColorUtil(this.getWarmupColor());
                    ServerParticleUtil.circularParticles(serverLevel, ModParticleTypes.BIG_CULT_SPELL.get(), this.getX(), this.getY() - 0.5F, this.getZ(), colorUtil.red(), colorUtil.green(), colorUtil.blue(), this.radius() / 2.0F);
                }
            }

            if (this.sentSpikeEvent){
                ++this.lifeTick;
                if (this.getParticle() == null || this.getParticle() == ModParticleTypes.NONE.get()) {
                    if (this.tickCount % 5 == 0) {
                        serverLevel.sendParticles(new FoggyCloudParticleOption(new ColorUtil(this.getColor()), this.radius() / 2.0F, 1), this.getX(), this.getY() + 0.25D, this.getZ(), 1, 0, 0, 0, 0);
                    }
                }
                List<LivingEntity> targets = new ArrayList<>();
                for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())){
                    if (this.owner != null) {
                        if (livingEntity != this.owner && !MobUtil.areAllies(this.owner, livingEntity)) {
                            targets.add(livingEntity);
                        }
                    } else {
                        targets.add(livingEntity);
                    }
                }
                if (!targets.isEmpty()){
                    for (LivingEntity livingEntity : targets) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                            float damage = this.getDamage();
                            if (this.getPercentDamage() > 0.0F) {
                                damage = livingEntity.getMaxHealth() * this.getPercentDamage();
                            }
                            boolean flag;
                            if (this.owner != null) {
                                flag = livingEntity.hurt(ModDamageSource.acid(this, this.owner), damage);
                            } else {
                                flag = livingEntity.hurt(this.damageSources().magic(), damage);
                            }
                            if (flag) {
                                if (this.getInvTime() > -1) {
                                    livingEntity.invulnerableTime = this.getInvTime();
                                }
                                if (!this.getEffects().isEmpty()) {
                                    for (MobEffectInstance mobeffectinstance1 : this.getEffects()) {
                                        if (mobeffectinstance1.getEffect().isInstantenous()) {
                                            mobeffectinstance1.getEffect().applyInstantenousEffect(this, this.getOwner(), livingEntity, mobeffectinstance1.getAmplifier(), 0.5D);
                                        } else {
                                            livingEntity.addEffect(new MobEffectInstance(mobeffectinstance1), this);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                if (this.lifeTick >= this.getDuration()) {
                    this.discard();
                }
            }
        }
    }

@Override
	public void onUpdate(){

		super.onUpdate();

		if(this.ticksExisted > 600 && this.getCaster() == null && !this.world.isRemote){
			this.setDead();
		}

		List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY,
				this.posZ, this.height, this.world);

		for(EntityLivingBase target : targets){

			if(this.isValidTarget(target)){

				double velX = target.motionX;
				double velY = target.motionY;
				double velZ = target.motionZ;

				// Only works if target is actually damaged to account for hurtResistantTime
				if(target.attackEntityFrom(getCaster() != null ? MagicDamage.causeIndirectMagicDamage(this, getCaster(),
						DamageType.SHOCK) : DamageSource.MAGIC, Spells.lightning_sigil.getProperty(Spell.DIRECT_DAMAGE)
						.floatValue() * damageMultiplier)){

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;

					this.playSound(WizardrySounds.ENTITY_LIGHTNING_SIGIL_TRIGGER, 1.0f, 1.0f);

					// Secondary chaining effect
					double seekerRange = Spells.lightning_sigil.getProperty(SECONDARY_RANGE).doubleValue();

					List<EntityLivingBase> secondaryTargets = EntityUtils.getLivingWithinRadius(seekerRange,
							target.posX, target.posY + target.height / 2, target.posZ, world);

					for(int j = 0; j < Math.min(secondaryTargets.size(),
							Spells.lightning_sigil.getProperty(SECONDARY_MAX_TARGETS).floatValue()); j++){

						EntityLivingBase secondaryTarget = secondaryTargets.get(j);

						if(secondaryTarget != target && this.isValidTarget(secondaryTarget)){

							if(world.isRemote){

								ParticleBuilder.create(Type.LIGHTNING).entity(target)
								.pos(0, target.height/2, 0).target(secondaryTarget).spawn(world);

								ParticleBuilder.spawnShockParticles(world, secondaryTarget.posX,
										secondaryTarget.posY + secondaryTarget.height / 2,
										secondaryTarget.posZ);
							}

							secondaryTarget.playSound(WizardrySounds.ENTITY_LIGHTNING_SIGIL_TRIGGER, 1.0F,
									world.rand.nextFloat() * 0.4F + 1.5F);

							secondaryTarget.attackEntityFrom(
									MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.SHOCK),
									Spells.lightning_sigil.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);
						}

					}
					// The trap is destroyed once triggered.
					this.setDead();
				}
			}
		}

		if(this.world.isRemote && this.rand.nextInt(15) == 0){
			double radius = (0.5 + rand.nextDouble() * 0.3) * width/2;
			float angle = rand.nextFloat() * (float)Math.PI * 2;
			ParticleBuilder.create(Type.SPARK)
			.pos(this.posX + radius * MathHelper.cos(angle), this.posY + 0.1, this.posZ + radius * MathHelper.sin(angle))
			.spawn(world);
		}
	}

public void tick() {
        super.tick();
        if (!this.level.isClientSide) {
            if (this.warmUp <= 0) {
                if (this.level instanceof ServerLevel serverWorld) {
                    if (this.tickCount % 5 == 0) {
                        serverWorld.sendParticles(ModParticleTypes.FIERY_PILLAR.get(), this.getX(), this.getY() + 0.5D, this.getZ(), 0, 0, 0.5D, 0, 1.0D);
                    }
                }
                this.setActivated(true);
                if (!this.playEvent) {
                    this.playSound(ModSounds.FIRE_BREATH_START.get(), 0.05F, 1.0F);
                    this.playEvent = true;
                }
                if (this.tickCount % 20 == 0) {
                    this.playSound(ModSounds.FIRE_TORNADO_AMBIENT.get(), 1.0F, 1.0F);
                }
                List<LivingEntity> targets = new ArrayList<>();
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(0, 8, 0))) {
                    LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
                    if (livingEntity != null) {
                        if (this.getOwner() != null) {
                            if (livingEntity != this.getOwner() && !MobUtil.areAllies(this.getOwner(), livingEntity)) {
                                targets.add(livingEntity);
                            }
                        } else {
                            targets.add(livingEntity);
                        }
                    }
                }
                if (!targets.isEmpty()) {
                    for (LivingEntity livingEntity : targets) {
                        int distance = Math.max((int) (livingEntity.getY() - this.getY()), 1);
                        if (BlockFinder.emptySpaceBetween(this.level, this.blockPosition().above(), Math.min(8, distance), true)) {
                            float damage = SpellConfig.FlameStrikeDamage.get().floatValue() * WandUtil.damageMultiply();
                            if (this.getOwner() != null) {
                                if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                                    damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F;
                                }
                            }
                            damage += this.getExtraDamage();
                            DamageSource damageSource = ModDamageSource.fireBreath(this, this.getOwner());
                            if (CuriosFinder.hasNetherRobe(this.getOwner())){
                                damageSource = ModDamageSource.magicFireBreath(this, this.getOwner());
                            }
                            if (MobUtil.getOwner(livingEntity) != null){
                                if (CuriosFinder.hasNetherRobe(MobUtil.getOwner(livingEntity))){
                                    damageSource = ModDamageSource.magicFireBreath(this, this.getOwner());
                                }
                            }
                            if (this.getOwner() instanceof AbstractWitherNecromancer || CuriosFinder.hasUnholySet(this.getOwner())){
                                damageSource = ModDamageSource.hellfire(this, this.getOwner());
                            }
                            livingEntity.hurt(damageSource, damage);
                            livingEntity.setSecondsOnFire(5);
                        }
                    }
                }
            } else {
                if (!this.isNoGravity()) {
                    MobUtil.moveDownToGround(this);
                }
                if (this.level instanceof ServerLevel serverWorld) {
                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    double d2 = this.getY() + 0.5F;
                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    serverWorld.sendParticles(ModParticleTypes.BIG_FIRE_GROUND.get(), d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                }
                if (this.getOwner() != null && this.getOwner().isDeadOrDying()) {
                    this.discard();
                }
                --this.warmUp;
            }
            if (this.tickCount >= this.getDuration()) {
                this.discard();
            }
        }
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        LivingEntity livingEntity = this.getTarget();
        if (!this.level.isClientSide) {
            if (livingEntity != null && pSource.getEntity() instanceof LivingEntity) {
                this.increaseHitTime();
            }
        }

        int smiteLevel = 0;
        if (pSource.getDirectEntity() instanceof LivingEntity living){
            int smite = EnchantmentHelper.getEnchantmentLevel(Enchantments.SMITE, living);
            if (smite > 0){
                int smite2 = Mth.clamp(smite, 1, 5);
                int duration = MathHelper.secondsToTicks(smite2);
                this.antiRegenTotal = duration;
                this.antiRegen = duration;
                smiteLevel = smite;
                if (this.level instanceof ServerLevel){
                    ModNetwork.sendToALL(new SApostleSmitePacket(this.getId(), duration));
                    if (this.getCoolDown() < this.coolDownLimit()){
                        this.coolDown += 10;
                    }
                }
            }
        }

        if (pSource.is(DamageTypes.FELL_OUT_OF_WORLD) && pSource.getEntity() == null){
            this.discard();
        }

        if (pSource.is(DamageTypes.LIGHTNING_BOLT) || pSource.is(DamageTypes.FALL) || pSource.is(DamageTypes.IN_WALL)){
            return false;
        }

        if (pSource.getDirectEntity() instanceof AbstractArrow && ((AbstractArrow) pSource.getDirectEntity()).getOwner() == this){
            return false;
        }

        if (this.isSettingUpSecond()){
            return false;
        }

        if (pSource.getDirectEntity() instanceof NetherMeteor || pSource.getEntity() instanceof NetherMeteor){
            return false;
        }

        if (this.moddedInvul > 0 || this.obsidianInvul > 0){
            return false;
        }

        float trueAmount = this.isInNether() ? pAmount * (1.0F - (MobsConfig.ApostleNetherDamageReduction.get() / 100.0F)) : pAmount;

        if (!this.isNoAi()) {
            if (this.getHealth() > trueAmount) {
                if (this.getHitTimes() >= this.hitTimeTeleport()) {
                    this.teleport();
                } else if (pSource.getEntity() == null) {
                    if (this.level.getRandom().nextBoolean()) {
                        this.teleport();
                    }
                }
            }
        }

        if (!this.level.getNearbyPlayers(TargetingConditions.forCombat().selector(MobUtil.NO_CREATIVE_OR_SPECTATOR), this, this.getBoundingBox().inflate(32)).isEmpty()){
            if (!(pSource.getEntity() instanceof Player)){
                trueAmount = trueAmount / 2;
            }
        }

        if (smiteLevel > 0) {
            if (MobsConfig.ApostleSmiteDamageReduction.get() > 0) {
                float reduce = 1.0F - (MobsConfig.ApostleSmiteDamageReduction.get() / 100.0F);
                trueAmount *= reduce;
            }
        }

        if (this.isDeadOrDying()) {
            this.deathBlow = pSource;
        }

        return super.hurt(pSource, trueAmount);
    }

@SubscribeEvent
    public static void HurtEvent(LivingHurtEvent event){
        LivingEntity victim = event.getEntity();
        Entity directEntity = event.getSource().getDirectEntity();
        if (event.getAmount() > 0.0F) {
            if (directEntity instanceof LivingEntity livingAttacker) {
                ItemStack itemStack = livingAttacker.getMainHandItem();
                if (ModDamageSource.physicalAttacks(event.getSource())) {
                    ItemHelper.setItemEffect(itemStack, victim);
                    if (itemStack.getItem() instanceof TieredItem weapon) {
                        if (weapon == ModItems.FANGED_DAGGER.get()){
                            MobEffect effect = MobEffects.POISON;
                            if (CuriosFinder.hasWildRobe(livingAttacker)){
                                effect = GoetyEffects.ACID_VENOM.get();
                            }
                            if (livingAttacker.hasEffect(GoetyEffects.VENOMOUS_HANDS.get())){
                                EffectsUtil.increaseDuration(victim, effect, 600);
                            } else {
                                victim.addEffect(new MobEffectInstance(effect, 200));
                            }
                        }
                        if (weapon == ModItems.FROZEN_BLADE.get()) {
                            if (victim.getType().is(EntityTypeTags.FREEZE_HURTS_EXTRA_TYPES)) {
                                event.setAmount(event.getAmount() * 2);
                            }
                        }
                        if (weapon == ModItems.HUNGRY_DAGGER.get()){
                            int soulEat = EnchantmentHelper.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get(), livingAttacker) + 1;
                            livingAttacker.heal(event.getAmount() * (0.05F * soulEat));
                        }
                        if (weapon instanceof DarkScytheItem) {
                            victim.playSound(ModSounds.SCYTHE_HIT_MEATY.get());
                        }
                        if (weapon instanceof DeathScytheItem) {
                            if (ItemConfig.DeathScytheSappedDuration.get() > 0) {
                                int seconds = MathHelper.secondsToTicks(ItemConfig.DeathScytheSappedDuration.get());
                                if (!victim.hasEffect(GoetyEffects.SAPPED.get())) {
                                    victim.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), seconds));
                                    victim.playSound(SoundEvents.SHIELD_BREAK, 2.0F, 1.0F);
                                } else {
                                    if (ItemConfig.DeathScytheSappedChance.get() > 0 && victim.level.random.nextFloat() <= (ItemConfig.DeathScytheSappedChance.get() / 100.0F)) {
                                        EffectsUtil.amplifyEffect(victim, GoetyEffects.SAPPED.get(), seconds);
                                        victim.playSound(SoundEvents.SHIELD_BREAK, 2.0F, 1.0F);
                                    } else {
                                        EffectsUtil.resetDuration(victim, GoetyEffects.SAPPED.get(), seconds);
                                    }
                                }
                            }
                        }
                    }
                    if (itemStack.is(ModTags.Items.SOUL_TAKING)) {
                        if (livingAttacker instanceof Player player) {
                            boolean giveSoul = false;
                            if (victim instanceof OwnableEntity owned){
                                if (owned.getOwner() != player){
                                    giveSoul = true;
                                }
                            } else {
                                giveSoul = true;
                            }
                            if (giveSoul) {
                                int enchantment = itemStack.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get());
                                int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                if (SEHelper.getSoulGiven(victim) > 0) {
                                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * soulEater);
                                }
                            }
                        }
                    }
                }
            }
        }
        if (victim instanceof Player player) {
            if (CuriosFinder.hasCurio(victim, ModItems.SPITEFUL_BELT.get())) {
                int a = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.THORNS, CuriosFinder.findCurio(victim, ModItems.SPITEFUL_BELT.get()));
                if (SEHelper.getSoulsAmount(player, ItemConfig.SpitefulBeltUseAmount.get() * (a + 1))) {
                    if (!event.getSource().is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !event.getSource().is(DamageTypes.THORNS) && event.getSource().getEntity() instanceof LivingEntity livingentity && livingentity != victim) {
                        livingentity.hurt(livingentity.damageSources().thorns(victim), 2.0F + a);
                        SEHelper.decreaseSouls(player, ItemConfig.SpitefulBeltUseAmount.get() * (a + 1));
                    }
                }
            }
        }
    }

@WrapWithCondition(method = "method_31420", at = @At(
		value = "INVOKE",
		target = "Lnet/minecraft/server/level/ServerLevel;guardEntityTick(Ljava/util/function/Consumer;Lnet/minecraft/world/entity/Entity;)V"
	))
	private boolean slowTime(ServerLevel instance, Consumer<?> consumer, Entity entity) {
		if(ArcanusHelper.shouldTimeDilate(entity, this) && getGameTime() % 2 == 0) {
			entity.setOldPosAndRot();
			entity.tickCount++;
			return false;
		}

		return true;
	}

private void knockbackExhilaration(Player attacker, Vec3 origin, LivingEntity target, long timeLimit, double multiplier) {
        ServerScheduler.schedule(20, () -> {
            if (target.onGround()) {
                double distance = Math.min(20, origin.distanceTo(target.position()));
                int amplifier = (int) (distance * multiplier) - 1;
                if (amplifier >= 0) {
                    attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, 200, amplifier, false, true));
                }
            } else if (target.level().getGameTime() < timeLimit) {
                knockbackExhilaration(attacker, origin, target, timeLimit, multiplier);
            }
        });
    }

