public static void onSpellResolve(SpellResolveEvent.Pre pre) {
        HitResult hitResult = pre.rayTraceResult;
        if (pre.context.getUnwrappedCaster() instanceof Breeze) {
            return;
        }
        if (hitResult instanceof EntityHitResult entityHitResult
                && !(pre.shooter instanceof FakePlayer fakePlayer)
                && entityHitResult.getEntity() instanceof Breeze breeze
                && pre.resolver.spell.getCastMethod() instanceof MethodProjectile) {
            pre.setCanceled(true);
            EntityOrbitProjectile orbitProjectile = new EntityOrbitProjectile(breeze.level, new SpellResolver(SpellContext.fromEntity(pre.spell, breeze, ItemStack.EMPTY)), entityHitResult.getEntity());
            breeze.level.addFreshEntity(orbitProjectile);
            EventQueue.getServerInstance().addEvent(new BreezeEvent(breeze, orbitProjectile, pre.shooter));
        }
    }

@Override
	public void effect(@Nullable LivingEntity caster, @Nullable Entity sourceEntity, Level level, HitResult target, List<SpellEffect> effects, ItemStack stack, double potency) {
		if(target.getType() == HitResult.Type.BLOCK) {
			BlockHitResult blockHit = (BlockHitResult) target;
			BlockPos pos = blockHit.getBlockPos().relative(blockHit.getDirection());

			if(level.getBlockState(pos).canBeReplaced() && (!(caster instanceof Player player) || level.mayInteract(player, pos))) {
				level.setBlock(pos, ArcanusBlocks.MAGIC_BLOCK.get().defaultBlockState(), Block.UPDATE_CLIENTS);
				level.scheduleTick(pos, level.getBlockState(pos).getBlock(), (int) (ArcanusConfig.UtilityEffects.BuildEffectProperties.baseLifeSpan * potency));

				if(caster != null) {
					level.getBlockEntity(pos, ArcanusBlockEntities.MAGIC_BLOCK.get()).ifPresent(blockEntity -> ArcanusHelper.copyMagicColor(blockEntity, caster));
				}
			}
		}
	}

@Nullable
	private static InFlightClaim findInFlightClaim(Player player, @Nullable EnderLinkPendingCraftData pendingCraft, EnderLinkPendingCraftPlan plan) {
		UUID playerId = player.getUUID();
		UUID claimId = pendingCraft == null ? null : pendingCraft.claimId();
		if (claimId == null) {
			claimId = LATEST_IN_FLIGHT_CLAIMS.getOrDefault(playerId, Map.of()).get(plan);
		}
		InFlightClaim claim = claimId == null ? null : IN_FLIGHT_CLAIMS.get(claimId);
		if (claim == null || !claim.playerId().equals(playerId) || claim.plan() != plan) {
			return null;
		}
		if (pendingCraft != null && pendingCraft.claimId() != null && !pendingCraft.claimId().equals(claim.claimId())) {
			return null;
		}
		return claim;
	}

private void checkMistFormTrigger() {
        long gameTime = this.level().getGameTime();
        if (gameTime < this.mistCooldownUntil) return;
        this.recentDamage.removeIf(p -> gameTime - p.getFirst() > 100);
        float total = 0;
        for (Pair<Long, Float> p : this.recentDamage) {
            total += p.getSecond();
        }
        if (total > this.getMaxHealth() * 0.2f) {
            this.setState(DraculaState.MIST);
            this.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
            this.mistStartTime = gameTime;
            this.mistCooldownUntil = gameTime + MIST_COOLDOWN;
            this.recentDamage.clear();
        }
    }

public void fulfilRequest() {
		if (!hasPendingRequest()) {
			return;
		}

		CorporeaSpark spark = CorporeaHelper.instance().getSparkForBlock(level, requestPos);
		if (spark != null) {
			BlockEntity te = spark.getSparkNode().getWorld().getBlockEntity(spark.getSparkNode().getPos());
			if (te instanceof CorporeaRequestor requestor) {
				requestor.doCorporeaRequest(request, requestCount, spark, null);

				forget();
				setChanged();
			}
		}
	}

private void updateTimes(Level level) {
		if (paused) {
			unpause(level);
			return;
		}

		if (isBurning(level)) {
			remainingBurnTime = getBurnTimeFinish() - level.getGameTime();
		} else {
			remainingBurnTime = 0;
		}
		if (isCooking()) {
			remainingCookTime = getCookTimeFinish() - level.getGameTime();
		} else {
			remainingCookTime = 0;
		}
	}

public void setRemoved() {
