@Override
    public void aiStep() {
        if (this.level().getGameTime() % 1024 == 0)
            this.heal(1F);

        // Every 10 ticks, attempt to refresh the owner buff
        if (!this.level().isClientSide() && this.level().getGameTime() % 10 == 0 && this.isTame()) {
            LivingEntity owner = this.getOwner();
            if (owner != null && this.distanceTo(owner) < MAX_BOOST_DISTANCE) {
                // close enough to boost
                for (MobEffectInstance effect : this.getFamiliarEffects())
                    owner.addEffect(effect);
            }
        }

        super.aiStep();
    }

@Override
    public boolean canUse() {
        long worldTime = this.seagull.level().getGameTime() % 10;
        if (this.seagull.getNoActionTime() >= 100 && worldTime != 0 || seagull.isSitting() || !AMConfig.seagullStealing) {
            return false;
        }
        if (this.seagull.getRandom().nextInt(12) != 0 && worldTime != 0 || seagull.stealCooldown > 0) {
            return false;
        }
        if(this.seagull.getMainHandItem().isEmpty()){
            Player valid = getClosestValidPlayer();
            if(valid != null){
                target = valid;
                return true;
            }
        }
        return false;
    }

public boolean boost(ItemStack stack, LivingEntity entity, int time) {

        if (!entity.getItemBySlot(EquipmentSlot.CHEST).canElytraFly(entity)) {
            return false;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isCreative = isPlayer && ((Player) entity).abilities.instabuild;
        if (!useEnergy(stack, getEnergyPerUse(true) * time / energyUseInterval, isCreative)) {
            return false;
        }
        if (!entity.isFallFlying() && isPlayer) {
            ((Player) entity).startFallFlying();
        }
        propel(entity, propelSpeed);
        stack.getOrCreateTag().putLong(NBTTags.TAG_TIME, entity.level.getGameTime());

        return true;
    }

@Override
	public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos,
		boolean isMoving) {
		if (level.isClientSide)
			return;

		Direction blockFacing = state.getValue(FACING);
		if (fromPos.equals(pos.relative(blockFacing.getOpposite()))) {
			if (!canSurvive(state, level, pos)) {
				level.destroyBlock(pos, true);
				return;
			}
		}

		if (!level.getBlockTicks()
			.willTickThisTick(pos, this))
			level.scheduleTick(pos, this, 1);
	}

@Override
    public void tick(boolean serverSide) {
        ticks++;
        if (ticks < 5)
            return;
        if (!serverSide || level.getGameTime() % 3 != 0)
            return;

        boolean destroyPortal = false;
        boolean placingFrame = !framePos.isEmpty();
        if (placingFrame) {
            BlockPos pos = framePos.get(0);
            framePos.remove(pos);
            BlockState bs = level.getBlockState(pos);
            if (bs.is(BlockTagProvider.DECORATIVE_AN) || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                tick(true);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                return;
            }
            if (bs.canBeReplaced() || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                level.setBlock(pos, BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState(), 3);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                level.playSound(null, pos, BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                ParticleUtil.spawnTouchPacket(level, pos, ParticleColor.makeRandomColor(255, 255, 255, level.random));
                placedBlocks.add(pos);
                return;
            } else {
                destroyPortal = true;
                ServerLevel serverLevel = (ServerLevel) level;
                serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
            }
        }
        boolean placingPortal = !portalPos.isEmpty() && framePos.isEmpty() && !destroyPortal;
        if (placingPortal) {
            for (BlockPos pos : portalPos) {
                if (level.getBlockState(pos).canBeReplaced()) {
                    level.setBlock(pos, BlockRegistry.PORTAL_BLOCK.defaultBlockState().setValue(PortalBlock.AXIS, direction.getAxis()), 2);
                    level.playSound(null, pos, BlockRegistry.PORTAL_BLOCK.get().defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    placedBlocks.add(pos);
                } else {
                    destroyPortal = true;
                    ServerLevel serverLevel = (ServerLevel) level;
                    serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
                    break;
                }
            }
            portalPos.clear();
        }
        if (destroyPortal) {
            for (BlockPos pos : placedBlocks) {
                level.destroyBlock(pos, false);
            }
            level.playSound(null, targetPos, SoundRegistry.GAIA_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            portalPos.clear();
            framePos.clear();
            return;
        }
        if (portalPos.isEmpty()) {
            level.playSound(null, targetPos.above(2), SoundRegistry.TEMPESTRY_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            for (BlockPos pos : placedBlocks) {
                if (level.getBlockEntity(pos) instanceof PortalTile portalTile) {
                    portalTile.setFromScroll(warpScrollData);
                }
            }
        }
    }

@Override
    public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity livingEntity) {
        if (livingEntity instanceof ServerPlayer player && player.getRespawnDimension() == player.level().dimension()) {
            DimensionTransition transition = player.findRespawnPositionAndUseSpawnBlock(true, DimensionTransition.DO_NOTHING); // ??
            transition = EventHooks.firePlayerRespawnPositionEvent(player, transition, false).getDimensionTransition();

            if (transition.newLevel() == level) {
                Vec3 pos = transition.pos();

                ParticleBuilder.forRandomPosInEntity(ParticleTypes.CHERRY_LEAVES, player)
                        .spawnNTimes(150)
                        .colourTint(0xE57200)
                        .addBulkProperty(builder -> builder
                                .scaleMod(RandomUtil.valueBetween(0.5f, 1f))
                                .lifespan(RandomUtil.numberBetween(40, 80))
                                .velocity(RandomUtil.gaussianOffset(Vec3.ZERO, 0.1f, 0, 0.1f)))
                        .sendToAllPlayersTrackingBlock(player.serverLevel(), player.blockPosition());

                player.teleportTo(transition.newLevel(), pos.x, pos.y, pos.z, Set.of(), transition.yRot(), transition.xRot());

                ParticleBuilder.forRandomPosOnToroid(ParticleTypes.TRIAL_SPAWNER_DETECTED_PLAYER, livingEntity.position().add(0, livingEntity.getBbHeight() * 0.5f, 0), livingEntity.getBbWidth() * 0.45f, livingEntity.getBbWidth())
                        .addTransition(OrbitPositionParticleTransition.create(livingEntity, RandomUtil.numberBetween(5, 10)))
                        .spawnNTimes(100)
                        .addBulkProperty(builder -> builder.lifespan(RandomUtil.numberBetween(20, 60)))
                        .sendToAllPlayersTrackingEntity(livingEntity);
            }
        }

        return stack;
    }

public boolean onUsedByWand(Player player, ItemStack stack, Level world, BlockPos pos) {
		if (world.isClientSide) {
			return false;
		}

		if (player == null || player.isShiftKeyDown()) {
			world.destroyBlock(pos, true);
		} else {
			GlobalPos clicked = GlobalPos.of(world.dimension(), pos.immutable());
			if (WandOfTheForestItem.getBindMode(stack)) {
				activeBindingAttempts.put(player.getUUID(), clicked);
				world.playSound(null, pos, BotaniaSounds.ding, SoundSource.BLOCKS, 0.5F, 1F);
			} else {
				var data = WorldData.get(world);
				if (XplatAbstractions.INSTANCE.isDevEnvironment()) {
					BotaniaAPI.LOGGER.info("PistonRelay pairs");
					for (var e : data.mapping.entrySet()) {
						BotaniaAPI.LOGGER.info("{} -> {}", e.getKey(), e.getValue());
					}
				}
				BlockPos dest = data.mapping.get(pos);
				if (dest != null) {
					XplatAbstractions.INSTANCE.sendToNear(world, pos, new BotaniaEffectPacket(EffectType.PARTICLE_BEAM,
							pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
							dest.getX(), dest.getY(), dest.getZ()));
				}
			}
		}

		return true;
	}

public static boolean requestShare() {
			Minecraft mc = Minecraft.getInstance();
			if(mc.level == null || !Screen.hasShiftDown())
				return false;

			if(!(mc.screen instanceof AbstractContainerScreen<?> gui))
				return false;

			for(GuiEventListener c : gui.children())
				if(c instanceof EditBox tf)
					if(tf.isFocused())
						return false;

			Slot slot = gui.getSlotUnderMouse();
			if(slot == null)
				return false;

			ItemStack stack = slot.getItem();
			if(stack.isEmpty())
				return false;

			if(mc.level.getGameTime() - lastClientShare > cooldown) {
				lastClientShare = mc.level.getGameTime();
			} else
				return false;

			//TODO: smuggle into a correctly signed chat message, so stuff like discord integration picks up on it

			PacketDistributor.sendToServer(new ShareItemC2SMessage(stack));
			return true;
		}

public static void onLevelTick(Level level) {
		if(!level.isClientSide()) {
			for(Entity entity : toUpdate.keySet()) {
				if(!entity.hurtMarked) { // Allow velocity change packets to take priority.
					MotionUpdate update = toUpdate.get(entity);
					if(update != null) { // Edge case where the entity expired in the ms between calls
						Vec3 total = update.predicted.add(update.unpredicted);
						//We want a player's motion to be handled client-side to ensure movement consistency
						//Otherwise it feels jerky.
						if(entity instanceof ServerPlayer player) {
							reduceAboveGroundTicks(player, entity);
							if(!update.predicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.predicted.x, update.predicted.y, update.predicted.z, true));
							}
							if(!update.unpredicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.unpredicted.x, update.unpredicted.y, update.unpredicted.z, false));
							}
							reduceAboveGroundTicks(player, entity);
						} else {
							entity.push(total.x, total.y, total.z);
						}
						if(entity.level() instanceof ServerLevel) {
							PsiNetwork.sendToPlayersTracking(entity, new MessageAdditiveMotion(entity.getId(), total.x, total.y, total.z, false));
						}

					}
				}
			}

			toUpdate.clear();
		}
	}

public void activateDeferred() {
		if (cannotLaunch())
			return;
		Direction facing = getFacing();
		List<Entity> entities =
			level.getEntitiesOfClass(Entity.class, new AABB(worldPosition).inflate(-1 / 16f, 0, -1 / 16f));

		// Launch Items
		boolean doLogic = !level.isClientSide || isVirtual();
		if (doLogic)
			launchItems();

		// Launch Entities
		for (Entity entity : entities) {
			boolean isPlayerEntity = entity instanceof Player;
			if (!entity.isAlive())
				continue;
			if (entity instanceof ItemEntity)
				continue;
			if (entity instanceof PackageEntity)
				continue;
			if (entity.getPistonPushReaction() == PushReaction.IGNORE)
				continue;

			entity.setOnGround(false);

			if (isPlayerEntity != level.isClientSide)
				continue;

			entity.setPos(worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5);
			launcher.applyMotion(entity, facing);

			if (!isPlayerEntity)
				continue;

			Player playerEntity = (Player) entity;

			if (launcher.getHorizontalDistance() * launcher.getHorizontalDistance()
				+ launcher.getVerticalDistance() * launcher.getVerticalDistance() >= 25 * 25)
				CatnipServices.NETWORK.sendToServer(new EjectorAwardPacket(worldPosition));

			if (!(playerEntity.getItemBySlot(EquipmentSlot.CHEST)
				.getItem() instanceof ElytraItem))
				continue;

			playerEntity.setXRot(-35);
			playerEntity.setYRot(facing.toYRot());
			playerEntity.setDeltaMovement(playerEntity.getDeltaMovement()
				.scale(.75f));
			deployElytra(playerEntity);
			CatnipServices.NETWORK.sendToServer(new EjectorElytraPacket(worldPosition));
		}

		if (doLogic) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			state = State.LAUNCHING;
			if (!level.isClientSide) {
				level.playSound(null, worldPosition, SoundEvents.WOODEN_TRAPDOOR_CLOSE, SoundSource.BLOCKS, .35f, 1f);
				level.playSound(null, worldPosition, SoundEvents.CHEST_OPEN, SoundSource.BLOCKS, .1f, 1.4f);
			}
		}
	}

@Override
	public void inventoryTick(ItemStack stack, Level world, Entity entity, int itemSlot, boolean isSelected) {
		if (entity instanceof Player && !world.isClientSide) {
			Player player = (Player) entity;
			List<Monster> genericMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, abilityRange.getValue()));

			if (SuperpositionHandler.isTheCursedOne(player) && Inventory.isHotbarSlot(itemSlot) && !player.getCooldowns().isOnCooldown(this)) {
				Monster oneWatched = null;

				for (Monster monster : genericMobs) {
					if (SuperpositionHandler.doesObserveEntity(player, monster) && !this.isExcluded(monster)) {
						oneWatched = monster;
						break;
					}
				}

				//System.out.println("The One: " + oneWatched);

				if (oneWatched != null && oneWatched.isAlive()) {
					final Monster theOne = oneWatched;
					Vector3 vec = Vector3.fromEntityCenter(theOne);
					List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(theOne, enrageRange.getValue()), (living) -> { return living.isAlive() && theOne.hasLineOfSight(living); });
					Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (monster) -> monster != theOne, vec.x, vec.y, vec.z);

					//System.out.println("Closest monster: " + closestMonster);

					if (closestMonster != null) {
						this.setAttackTarget(theOne, closestMonster);
						theOne.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 300, 0, false, true));
						theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 300, 1, false, false));
						theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 300, 1, false, false));
						//theOne.addPotionEffect(new MobEffectInstance(MobEffects., 400, 1, false, true));

						for (Monster otherMonster : surroundingMobs) {
							this.setAttackTarget(otherMonster, theOne);
						}

						player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ELDER_GUARDIAN_CURSE, SoundSource.HOSTILE, 1.0F, 1.0F);

						if (player instanceof ServerPlayer) {
							ServerPlayer serverPlayer = (ServerPlayer) player;
							EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(theOne.getX(), theOne.getY(), theOne.getZ(), 64, theOne.level().dimension())), new PacketGenericParticleEffect(theOne.getX(), theOne.getEyeY(), theOne.getZ(), 0, false, Effect.GUARDIAN_CURSE));
						}

						player.getCooldowns().addCooldown(this, abilityCooldown.getValue());
					}
				}

			}

			for (Monster monster : genericMobs) {
				if (monster instanceof Guardian && monster.getClass() != ElderGuardian.class) {
					final Guardian guardian = (Guardian) monster;

					if (guardian.getTarget() == null) {
						List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(guardian, 12), (living) -> { return living.isAlive() && guardian.hasLineOfSight(living); });
						Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (checked) -> { return !(checked instanceof Guardian); }, guardian.getX(), guardian.getY(), guardian.getZ());

						if (closestMonster != null) {
							this.setAttackTarget(guardian, closestMonster);
						}
					}
				}
			}

		}
	}

private void startNext() {
        index++;
        tries = 0;
        if (instructions.size() == index) {
            if (shouldLoop) {
                syncWithClients();
                index = 0;
            } else {
                stop();
                return;
            }
        }
        endTick = 0;
        delayTick = 0;
        Instruction current = instructions.get(index);
        if (current instanceof Instruction.MoveTo moveTo) {
            mob.getNavigation().moveTo(moveTo.target.getX(), moveTo.target.getY(), moveTo.target.getZ(), 1);
        } else if (current instanceof Instruction.FlyTo flyTo) {
            if (mob instanceof PrehistoricFlying flying) {
                flying.moveTo(Vec3.atCenterOf(flyTo.target), false, true);
            }
        } else if (current instanceof Instruction.FlyLand flyLand) {
            if (mob instanceof PrehistoricFlying flying) {
                flying.moveTo(Vec3.atCenterOf(flyLand.target), true, true);
            }
        } else if (current instanceof Instruction.TeleportTo teleportTo) {
            mob.getNavigation().stop();
            mob.moveTo(teleportTo.target, teleportTo.rotation, mob.getXRot());
            mob.setYHeadRot(teleportTo.rotation);
            endTick = mob.level.getGameTime() + 5;
        } else if (current instanceof Instruction.AttachTo attachTo) {
            attached = false;
            mob.getNavigation().moveTo(attachTo.target.getX(), attachTo.target.getY(), attachTo.target.getZ(), 1);
            if (mob instanceof Meganeura meganeura) {
                Direction face = attachTo.direction;
                float rad = mob.getBbWidth() / 2;
                Vec3 pos = new Vec3(attachTo.location.x + rad * face.getStepX(), attachTo.location.y, attachTo.location.z + rad * face.getStepZ());
                meganeura.getAttachSystem().setAttachTarget(attachTo.target, face, pos);
            }
        } else if (current instanceof Instruction.LeapLand leapLand) {
            mob.getNavigation().moveTo(leapLand.location.x, leapLand.location.y, leapLand.location.z, 1);
        } else if (current instanceof Instruction.LeapAttack leapAttack) {
            Entity target = mob.level.getEntity(leapAttack.targetId);
            if (target instanceof LivingEntity && mob instanceof PrehistoricLeaping leaping) {
                mob.getNavigation().moveTo(target, 1);
                mob.lookAt(target, 120, 10);
                mob.setTarget(leaping);

               // leaping.getLeapSystem().setLeapTarget(target);
            }
        } else if (current instanceof Instruction.Idle idle) {
            endTick = mob.level.getGameTime() + idle.duration;
        } else if (current instanceof Instruction.PlayAnim playAnim) {
            if (playAnim.timeBased) {
                animCount = mob.level.getGameTime() + playAnim.count * 20L;
                activeAnim = mob.getAnimationLogic().forceAnimation(playAnim.controller, mob.getAllAnimations().get(playAnim.name), AnimationCategory.IDLE, 1, 5,true);
            } else {
                animCount = playAnim.count;
                activeAnim = mob.getAnimationLogic().forceAnimation(playAnim.controller, mob.getAllAnimations().get(playAnim.name), AnimationCategory.IDLE, 1,5,false);
            }
        } else if (current instanceof Instruction.Sleep sleep) {
            endTick = mob.level.getGameTime() + sleep.duration;
            mob.sleepSystem.setDisabled(false);
            mob.sleepSystem.setSleeping(true);
            mob.sleepSystem.setSleepForced(true);
        }
    }

@Override
		public void tick() {
			super.tick();

			if (getPassengers().isEmpty() && !level().isClientSide) {
				discard();
				return;
			}

			boolean isItem = getPassengers().stream().allMatch(ItemEntity.class::isInstance);
			if (!isItem && tickCount % 30 == 0) {
				playSound(BotaniaSounds.lightRelay, 0.25F, (float) Math.random() * 0.3F + 0.7F);
			}
			if (!isItem && tickCount % 10 == 0) {
				gameEvent(GameEvent.ELYTRA_GLIDE);
			}

			BlockPos pos = blockPosition();
			BlockPos exitPos = getExitPos();

			if (!level().isClientSide && pos.equals(exitPos)) {
				boolean done = true;
				BlockEntity tile = level().getBlockEntity(pos);
				if (tile instanceof LuminizerBlockEntity relay) {
					BlockState state = level().getBlockState(pos);
					if (state.is(BotaniaBlocks.lightRelayDetector)) {
						level().setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, true));
						level().scheduleTick(pos, state.getBlock(), 2);
					}

					BlockPos bind = relay.getNextDestination();
					if (bind != null && relay.isValidBinding()) {
						setExit(bind);
						done = false;
					}
				}

				if (done) {
					for (Entity e : getPassengers()) {
						e.stopRiding();
					}
					discard();
					return;
				}
			}
			Vec3 thisVec = position();
			Vec3 motVec = thisVec.reverse().add(exitPos.getX() + 0.5, exitPos.getY() + 0.5, exitPos.getZ() + 0.5).normalize().scale(0.5);

			int color;

			int count = 4;
			for (int i = 0; i < count; i++) {
				color = Mth.hsvToRgb(tickCount / 36F + 1F / count * i, 1F, 1F);
				double rad = Math.PI * 2.0 / count * i + tickCount / Math.PI;
				double cos = Math.cos(rad);
				double sin = Math.sin(rad);
				double s = 0.4;

				int r = (color >> 16) & 0xFF;
				int g = (color >> 8) & 0xFF;
				int b = color & 0xFF;
				SparkleParticleData data = SparkleParticleData.sparkle(1.2F, r / 255F, g / 255F, b / 255F, 10);
				level().addParticle(data, getX() + cos * s, getY() - 0.5, getZ() + sin * s, 0, 0, 0);
			}

			setPos(getX() + motVec.x, getY() + motVec.y, getZ() + motVec.z);
		}

@Override
    public void tickServer() {
        super.tickServer();

        isCoreLoaded = inv.isCorePresent();

        if (isOpen() && isCoreLoaded && inv.getStats().getUnusedPercentage() > 0 && getPressure() <= getMinWorkingPressure()) {
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                scanForEntities();
            }
            Vec3 trapVec = Vec3.atCenterOf(worldPosition);
            double min = nonNullLevel().getFluidState(worldPosition).getType() == Fluids.WATER ? 2.5 : 1.75;
            for (Mob e : targetEntities) {
                if (!e.isAlive() || e.getTags().contains(DEFENDER_TAG)) continue;
                // kludge: mobs in water seem a bit flaky about getting close enough so increase the absorb dist a bit
                if (e.distanceToSqr(trapVec) <= min) {
                    absorbEntity(e);
                    addAir((int) (PneumaticValues.USAGE_VACUUM_TRAP * e.getHealth()));
                } else {
                    e.getNavigation().moveTo(trapVec.x(), trapVec.y(), trapVec.z(), 1.2);
                }
            }
        }
        if (!isCoreLoaded)
            problem = Problems.NO_CORE;
        else if (inv.getStats().getUnusedPercentage() == 0)
            problem = Problems.CORE_FULL;
        else if (!isOpen())
            problem = Problems.TRAP_CLOSED;
        else
            problem = Problems.OK;
    }

@Override
    public void tick() {
        if (level.isClientSide || connectedPos == null || level.getGameTime() % 20 != 0) {
            return;
        }
        BlockEntity tile = level.getBlockEntity(connectedPos);
        if (tile == null) {
            return;
        }
        IItemHandler handler = level.getCapability(Capabilities.ItemHandler.BLOCK, connectedPos, null);
        if (handler == null) {
            return;
        }
        int found = 0;
        for (int i = 0; i < handler.getSlots(); i++) {
            ItemStack ghostStack = handler.getStackInSlot(i);
            ItemStack extractedStack = handler.extractItem(i, ghostStack.getCount(), true);
            // This falls back to the getStack count if we attempted to extract beyond the max count.
            // This is a workaround for inventories that support > max stack count, as you can only extract the max stack count at a time.
            // and getStackInSlot will return counts for items that wouldn't necessarily be extractable.
            if (ghostStack.getCount() > extractedStack.getCount() && extractedStack.getMaxStackSize() == extractedStack.getCount()) {
                found += getCountForStack(ghostStack);
            } else {
                found += getCountForStack(extractedStack);
            }
            if (found > neededCount) {
                setReachedCount(true);
                return;
            }
        }
        setReachedCount(false);
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide)
            return;
        if (level.getGameTime() % 40 == 0 && this.canAcceptSource()) {
            for (ItemEntity i : level.getEntitiesOfClass(ItemEntity.class, new AABB(worldPosition).inflate(1.0))) {
                if (i.getItem().getItem().getFoodProperties(i.getItem(), null) != null) {
                    int source = getSourceValue(i.getItem());
                    this.addSource(source);
                    ItemStack containerItem = i.getItem().getCraftingRemainingItem();
                    i.getItem().shrink(1);
                    if (!containerItem.isEmpty()) {
                        level.addFreshEntity(new ItemEntity(level, i.getX(), i.getY(), i.getZ(), containerItem));
                    }
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.blockPosition(), new ParticleColor(255, 255, 255)));
                }
            }
            for (ArcanePedestalTile i : getSurroundingPedestals()) {
                int sourceValue = getSourceValue(i.getItem(0));
                if (sourceValue > 0) {
                    this.addSource(sourceValue);
                    ItemStack containerItem = i.getItem(0).getCraftingRemainingItem();
                    i.removeItem(0, 1);
                    i.setItem(0, containerItem);
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.getBlockPos().above(), new ParticleColor(255, 255, 255)));
                }
            }
        }
    }

public void tick()
	{
		AABB aabb = incenseArea.getAABB(getBlockPos());
		List<Player> playerList = getLevel().getEntitiesOfClass(Player.class, aabb);
		if (playerList.isEmpty())
		{
			return;
		}

		if (getLevel().getGameTime() % 100 == 0)
		{
			recheckConstruction();
		}

		boolean hasPerformed = false;

		for (Player player : playerList)
		{
			if (PlayerSacrificeHelper.incrementIncense(player, 0, incenseAddition, incenseAddition / 100))
			{
				hasPerformed = true;
			}
		}

		if (hasPerformed)
		{
			if (getLevel().random.nextInt(4) == 0 && getLevel() instanceof ServerLevel)
			{
				ServerLevel server = (ServerLevel) getLevel();
				server.sendParticles(ParticleTypes.FLAME, worldPosition.getX() + 0.5, worldPosition.getY() + 1.2, worldPosition.getZ() + 0.5, 1, 0.02, 0.03, 0.02, 0);
			}
		}
	}

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide)
            return;
        if (level.getGameTime() % 20 == 0 && this.canAcceptSource()) {
            for (ItemEntity i : level.getEntitiesOfClass(ItemEntity.class, new AABB(worldPosition).inflate(1.0))) {
                int source = getSourceValue(i.getItem());
                if (source > 0 && (canConsumeEntireItem(i.getItem()) || this.getSource() <= 0)) {
                    this.addSource(source);
                    ItemStack containerItem = i.getItem().getCraftingRemainingItem();
                    i.getItem().shrink(1);
                    if (!containerItem.isEmpty()) {
                        level.addFreshEntity(new ItemEntity(level, i.getX(), i.getY(), i.getZ(), containerItem));
                    }
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.blockPosition(), new ParticleColor(255, 0, 0)));
                    return;
                }
            }
            for (ArcanePedestalTile i : getSurroundingPedestals()) {
                int sourceValue = getSourceValue(i.getItem(0));
                if (sourceValue > 0 && (canConsumeEntireItem(i.getItem(0)) || this.getSource() <= 0)) {
                    this.addSource(sourceValue);
                    ItemStack containerItem = i.getItem(0).getCraftingRemainingItem();
                    i.removeItem(0, 1);
                    i.setItem(0, containerItem);
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.getBlockPos().above(), new ParticleColor(255, 0, 0)));
                }
            }
        }
    }

@Override
    public StarbyState onDestinationReached() {
        this.starbuncle.getNavigation().stop();

        IItemHandler iItemHandler = behavior.getItemCapFromTile(targetPos, behavior.TO_DIRECTION_MAP.get(targetPos.hashCode()));
        if (iItemHandler == null) {
            starbuncle.addGoalDebug(this, new DebugEvent("NoItemHandler", "No item handler at " + targetPos.toString()));
            return nextState;
        }

        boolean didDeposit = depositStack(iItemHandler);
        if (!didDeposit) {
            starbuncle.setBackOff(5 + starbuncle.level.random.nextInt(20));
            starbuncle.addGoalDebug(this, new DebugEvent("no_room", targetPos.toString()));
            return nextState;
        }

        OpenChestEvent event = new OpenChestEvent((ServerLevel) starbuncle.level, targetPos, 20);
        event.open();
        EventQueue.getServerInstance().addEvent(event);

        ItemStack left = starbuncle.getHeldStack();
        starbuncle.addGoalDebug(this, new DebugEvent("stored_item", "successful at " + targetPos.toString() + "set stack to " + left.getCount() + "x " + left.getHoverName().getString()));
        boolean fetchPassengerStack = left.isEmpty();
        while (fetchPassengerStack) {
            fetchPassengerStack = false;
            starbuncle.getNextItemFromPassengers();
            if (!starbuncle.getHeldStack().isEmpty()) {
                fetchPassengerStack = depositStack(iItemHandler) && starbuncle.getHeldStack().isEmpty();
            }
        }
        return nextState;
    }

@Override
    public void tick() {
        if (isDecorative && level.isClientSide) {
            makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
            return;
        }


        if (level.isClientSide && ritual != null) {
            makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
        }
        if (isOff)
            return;
        if (ritual != null) {

            if (ritual.getContext().isDone) {
                ritual.onEnd();
                ritual = null;
                getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
                getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
                updateBlock();
                return;
            }
            if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
                level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                    tryBurnStack(i.getItem());
                });
            }
            if (ritual.consumesSource() && ritual.needsSourceNow()) {
                if (this.sourceBackoff-- <= 0) {
                    int cost = ritual.getSourceCost();
                    if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                        ritual.setNeedsSource(false);
                        this.sourceBackoff = 0;
                        updateBlock();
                    } else {
                        this.sourceBackoff = 20;
                        return;
                    }
                } else {
                    return;
                }
            }
            if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
                ritual.tryTick(relayTile);
                relayTile.ticksToLightOff = 2;
                relayTile.isDecorative = false;
            } else {
                ritual.tryTick(this);
            }
        }
    }

@Override
    protected void tick() {
        Level world = getWorld();
        if (world.isClientSide) {
            BlockPos pos = getPos();

            for (int i = 0; i < 10; i++) {
                Vec3 particlePos = new Vec3(pos.getX(), pos.getY(), pos.getZ()).add(0.5, 0, 0.5);
                particlePos = particlePos.add(ParticleUtil.pointInSphere().multiply(5, 5, 5));
                world.addParticle(ParticleLineData.createData(getCenterColor()),
                        particlePos.x(), particlePos.y(), particlePos.z(),
                        pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
            }
        }

        if (!world.isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            List<LivingEntity> entityList = world.getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5.0),
                    (m) -> (m.getClassification(false).equals(MobCategory.MONSTER) || m.getType().is(EntityTags.DISINTEGRATION_WHITELIST)) && !(m instanceof Player));
            for (LivingEntity m : entityList) {
                if (m.getType().is(EntityTags.DISINTEGRATION_BLACKLIST)) {
                    continue;
                }
                m.remove(Entity.RemovalReason.DISCARDED);
                if (m.isRemoved()) {

                    ParticleUtil.spawnPoof((ServerLevel) world, m.blockPosition());
                    if (m.shouldDropExperience()) {
                        int exp = m.getExperienceReward((ServerLevel) world, null) * 2;
                        if (exp > 0) {
                            int numGreater = exp / 12;
                            exp -= numGreater * 12;
                            int numLesser = exp / 3;
                            if ((exp - numLesser * 3) > 0)
                                numLesser++;
                            var pos = m.blockPosition().getBottomCenter();
                            if (numGreater > 0) {
                                world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.GREATER_EXPERIENCE_GEM, numGreater)));
                            }
                            if (numLesser > 0) {
                                world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.EXPERIENCE_GEM, numLesser)));
                            }
                            didWorkOnce = true;
                        }

                    }
                }
            }
            if (didWorkOnce)
                setNeedsSource(true);
        }
    }

