@Nonnull
    @Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack stack = context.getItemInHand();
        BlockPos pos = context.getClickedPos();
        Level level = context.getLevel();
        Player player = context.getPlayer();

        if (this.getEntity(stack, level) != null) {
            if (level.getBlockState(pos).getBlock() == ModBlocks.CURSED_CAGE_BLOCK.get()){
                BlockEntity blockEntity = level.getBlockEntity(pos);
                if (blockEntity instanceof CursedCageBlockEntity cursedCageBlock){
                    if (!cursedCageBlock.getItem().isEmpty()){
                        return InteractionResult.PASS;
                    } else {
                        if (!level.isClientSide) {
                            level.setBlockAndUpdate(pos, Blocks.SPAWNER.defaultBlockState());
                            BlockEntity blockentity = level.getBlockEntity(pos);
                            if (blockentity instanceof SpawnerBlockEntity) {
                                ((SpawnerBlockEntity) blockentity).getSpawner().setEntityId(this.getEntity(stack, level).getType(), level, level.random, pos);
                            }
                        }
                        this.clearEntity(stack);
                        if (player != null) {
                            player.playSound(ModSounds.FLAME_CAPTURE_RELEASE.get());
                        }
                        stack.shrink(1);

                        return InteractionResult.sidedSuccess(level.isClientSide());
                    }
                }
            }
        } else {
            if (ItemConfig.FireSpawnCage.get()) {
                if (level.getBlockState(pos).getBlock() == Blocks.SPAWNER) {
                    if (!level.isClientSide()) {
                        BlockEntity blockentity = level.getBlockEntity(pos);
                        if (blockentity instanceof SpawnerBlockEntity spawnerBlockEntity) {
                            Entity entity = spawnerBlockEntity.getSpawner().getOrCreateDisplayEntity(level, level.getRandom(), blockentity.getBlockPos());
                            if (entity != null) {
                                this.setEntity(entity, stack);
                                level.destroyBlock(pos, false);
                            }
                        }
                    }
                    if (player != null) {
                        player.playSound(ModSounds.FLAME_CAPTURE_CATCH.get());
                    }
                    return InteractionResult.sidedSuccess(level.isClientSide());
                }
            }
        }

        return super.useOn(context);
    }

public static void travellersWingsSidestepCooldownSound(Player player) {
		ItemStack leggingsStack = player.getItemBySlot(EquipmentSlot.LEGS);
		Long cooldown = leggingsStack.get(TFDataComponents.SIDESTEP_COOLDOWN);
		if (cooldown == null)
			return;
		TravellersWingsAttachment attachment = player.getData(TFDataAttachments.TRAVELLERS_WINGS);
		long dt = player.level().getGameTime() - attachment.lastSidestepTime;
		if (TravellersModifiersManager.isModifierActive(player, leggingsStack, TravellersModifiersManager.SIDESTEP_MODIFIER) && dt > cooldown && attachment.shouldPlaySideStepCooldownSound) {
			player.level().playLocalSound(player.blockPosition(), TFSounds.SIDE_STEP_CHARGED.get(), player.getSoundSource(), 1F, player.getVoicePitch(), false);
			attachment.shouldPlaySideStepCooldownSound = false;
		}
	}

private void updateQueue(ItemStack stack, Level level, BlockPos pos, int shearsRange) {
		for (int y = pos.getY() - shearsRange; y <= pos.getY() + shearsRange; y++) {
			for (int x = pos.getX() - shearsRange; x <= pos.getX() + shearsRange; x++) {
				for (int z = pos.getZ() - shearsRange; z <= pos.getZ() + shearsRange; z++) {
					BlockPos currentBlockPos = new BlockPos(x, y, z);
					BlockState blockState = level.getBlockState(currentBlockPos);
					if (isShearableBlock(stack, level, blockState)) {
						blockQueue.add(currentBlockPos);
					}
				}
			}
		}
	}

private void fillQueueToPlant(Level level, HarvestRodCache cache, BlockPos pos, int range, ItemStack plantable) {
		boolean checkerboard = false;
		boolean bothOddOrEven = false;

		if (plantable.getItem() == Items.PUMPKIN_SEEDS || plantable.getItem() == Items.MELON_SEEDS) {
			checkerboard = true;
			boolean xEven = pos.getX() % 2 == 0;
			boolean zEven = pos.getZ() % 2 == 0;
			bothOddOrEven = xEven == zEven;
		}

		boolean finalCheckerboard = checkerboard;
		boolean finalBothOddOrEven = bothOddOrEven;
		fillQueue(cache, pos, range,
				currentPos -> (!finalCheckerboard || (finalBothOddOrEven == ((currentPos.getX() % 2 == 0) == (currentPos.getZ() % 2 == 0))))
						&& level.isEmptyBlock(currentPos.above()) && canPlacePlantableAt(level, currentPos.above(), plantable));
	}

