protected void teleport() {
        if (!this.level.isClientSide() && !this.isNoAi() && this.isAlive() && this.toTeleportPos == null && !this.isSettingUpSecond() && !this.isCasting()) {
            if (MobsConfig.ApostleDelayedTeleport.get()) {
                if (this.pendingTeleportSearch != null) {
                    if (this.pendingTeleportSearch.isDone()) {
                        final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                        Vec3 result = this.pendingTeleportSearch.getNow(null);
                        this.pendingTeleportSearch = null;
                        Vec3 vec3 = findTeleportGroundY(this.level, result.x, result.y + 3, result.z, startY);
                        if (vec3 != null) {
                            this.toTeleportPos = vec3;
                            this.playSound(ModSounds.APOSTLE_PRE_TELEPORT.get(), 2.0F, 1.0F);
                            this.resetHitTime();
                        }
                    }
                } else {
                    final double startX = this.getX();
                    final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    final double startZ = this.getZ();
                    final RandomSource randomSource = this.apostleRandom;

                    this.prevX = startX;
                    this.prevY = this.getY();
                    this.prevZ = startZ;

                    this.pendingTeleportSearch = CompletableFuture.supplyAsync(() -> {
                        double d0 = 32.0D;
                        double d1 = startX + (randomSource.nextDouble() - 0.5D) * d0;
                        double d2 = startY + 3.0D;
                        double d3 = startZ + (randomSource.nextDouble() - 0.5D) * d0;
                        return new Vec3(d1, d2, d3);
                    });
                }
            } else {
                for (int i = 0; i < 128; ++i) {
                    double d3 = this.getX() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    double d4 = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    double d5 = this.getZ() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    BlockPos blockPos = BlockPos.containing(d3, d4, d5);
                    boolean flag = this.getTarget() == null || i >= 64 || BlockFinder.canSeeBlock(this.getTarget(), blockPos);
                    if (flag && this.randomTeleport(d3, d4, d5, false)) {
                        this.teleportHits();
                        this.resetHitTime();
                        break;
                    }
                }
            }
        }
    }

public void teleportTowards(Entity entity) {
        if (!this.level.isClientSide() && !this.isNoAi() && this.isAlive() && this.toTeleportPos == null && !this.isSettingUpSecond()) {
            if (MobsConfig.ApostleDelayedTeleport.get()) {
                if (this.pendingTeleportSearch != null) {
                    if (this.pendingTeleportSearch.isDone()) {
                        Vec3 result = this.pendingTeleportSearch.getNow(null);
                        this.pendingTeleportSearch = null;
                        if (result != null) {
                            Vec3 vec3 = findTeleportGroundY(this.level, result.x, result.y + 3, result.z, entity.getY());
                            if (vec3 != null) {
                                this.toTeleportPos = vec3;
                                this.playSound(ModSounds.APOSTLE_PRE_TELEPORT.get(), 2.0F, 1.0F);
                            }
                        }
                    }
                } else {
                    final double targetX = entity.getX();
                    final double targetY = entity.getEyeY();
                    final double targetZ = entity.getZ();
                    final double selfX = this.getX();
                    final double selfY = this.getY();
                    final double selfZ = this.getZ();
                    final RandomSource randomSource = this.apostleRandom;

                    this.prevX = selfX;
                    this.prevY = selfY;
                    this.prevZ = selfZ;

                    this.pendingTeleportSearch = CompletableFuture.supplyAsync(() -> {
                        Vec3 vec3 = new Vec3(selfX - targetX, selfY * 0.5D - targetY, selfZ - targetZ).normalize();
                        double d0 = 16.0D;
                        double d1 = selfX + (randomSource.nextDouble() - 0.5D) * 8.0D - vec3.x * d0;
                        double d2 = selfY + (randomSource.nextInt(16) - 8) - vec3.y * d0;
                        double d3 = selfZ + (randomSource.nextDouble() - 0.5D) * 8.0D - vec3.z * d0;
                        return new Vec3(d1, d2, d3);
                    });
                }
            } else {
                for (int i = 0; i < 128; ++i) {
                    Vec3 vector3d = new Vec3(this.getX() - entity.getX(), this.getY(0.5D) - entity.getEyeY(), this.getZ() - entity.getZ()).normalize();
                    double d0 = 16.0D;
                    double d1 = this.getX() + (this.level.getRandom().nextDouble() - 0.5D) * 8.0D - vector3d.x * d0;
                    double d2 = this.getY() + (this.level.getRandom().nextInt(16) - 8) - vector3d.y * d0;
                    double d3 = this.getZ() + (this.level.getRandom().nextDouble() - 0.5D) * 8.0D - vector3d.z * d0;
                    if (BlockFinder.canSeeBlock(entity, BlockPos.containing(d1, d2, d3))
                            && this.randomTeleport(d1, d2, d3, false)) {
                        this.teleportHits();
                        break;
                    }
                }
            }
        }
    }

private void teleportRandomly() {
		//choose a location to teleport to
		double oldX = getX(), oldY = getY(), oldZ = getZ();
		double newX, newY = source.getY(), newZ;
		int tries = 0;

		do {
			newX = source.getX() + (random.nextDouble() - .5) * ARENA_RANGE;
			newZ = source.getZ() + (random.nextDouble() - .5) * ARENA_RANGE;
			tries++;
			//ensure it's inside the arena ring, and not just its bounding square
		} while (tries < 50 && MathHelper.pointDistanceSpace(newX, newY, newZ, source.getX(), source.getY(), source.getZ()) > 12);

		if (tries == 50) {
			//failsafe: teleport to the beacon
			newX = source.getX() + .5;
			newY = source.getY() + 1.6;
			newZ = source.getZ() + .5;
		}

		//for low-floor arenas, ensure landing on the ground
		BlockPos tentativeFloorPos = BlockPos.containing(newX, newY - 1, newZ);
		if (level().getBlockState(tentativeFloorPos).getCollisionShape(level(), tentativeFloorPos).isEmpty()) {
			newY--;
		}

		//teleport there
		teleportTo(newX, newY, newZ);

		//play sound
		level().playSound(null, oldX, oldY, oldZ, BotaniaSounds.gaiaTeleport, this.getSoundSource(), 1F, 1F);
		this.playSound(BotaniaSounds.gaiaTeleport, 1F, 1F);

		var random = getRandom();

		//spawn particles along the path
		int particleCount = 128;
		for (int i = 0; i < particleCount; ++i) {
			double progress = i / (double) (particleCount - 1);
			float vx = (random.nextFloat() - 0.5F) * 0.2F;
			float vy = (random.nextFloat() - 0.5F) * 0.2F;
			float vz = (random.nextFloat() - 0.5F) * 0.2F;
			double px = oldX + (newX - oldX) * progress + (random.nextDouble() - 0.5D) * getBbWidth() * 2.0D;
			double py = oldY + (newY - oldY) * progress + random.nextDouble() * getBbHeight();
			double pz = oldZ + (newZ - oldZ) * progress + (random.nextDouble() - 0.5D) * getBbWidth() * 2.0D;
			level().addParticle(ParticleTypes.PORTAL, px, py, pz, vx, vy, vz);
		}

		Vec3 oldPosVec = new Vec3(oldX, oldY + getBbHeight() / 2, oldZ);
		Vec3 newPosVec = new Vec3(newX, newY + getBbHeight() / 2, newZ);

		if (oldPosVec.distanceToSqr(newPosVec) > 1) {
			//damage players in the path of the teleport
			for (Player player : getPlayersAround()) {
				boolean hit = player.getBoundingBox().inflate(0.25).clip(oldPosVec, newPosVec)
						.isPresent();
				if (hit) {
					player.hurt(damageSources().mobAttack(this), 6);
				}
			}

			//break blocks in the path of the teleport
			int breakSteps = (int) oldPosVec.distanceTo(newPosVec);
			if (breakSteps >= 2) {
				for (int i = 0; i < breakSteps; i++) {
					float progress = i / (float) (breakSteps - 1);
					int breakX = Mth.floor(oldX + (newX - oldX) * progress);
					int breakY = Mth.floor(oldY + (newY - oldY) * progress);
					int breakZ = Mth.floor(oldZ + (newZ - oldZ) * progress);

					smashBlocksAround(breakX, breakY, breakZ, 1);
				}
			}
		}
	}

public static void handleSyncScheduledTasks(int tick) {
		if (scheduledSynchTasks.containsKey(tick)) {
			Iterator<Runnable> tasks = scheduledSynchTasks.get(tick).iterator();

			while (tasks.hasNext()) {
				tasks.next().run();
				tasks.remove();
			}
		}
	}

@Override
	public void tick() {
		this.baseTick();

		if (this.life == 2) {
			if (level().isClientSide()) {
				if (!isSilent()) {
					level().playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 10, 0.8F + this.random.nextFloat() * 0.2F, false);
					level().playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 1, 0.5F + this.random.nextFloat() * 0.2F, false);
				}
			}
			else {
				Difficulty difficulty = level().getDifficulty();

				if ((difficulty == Difficulty.NORMAL || difficulty == Difficulty.HARD) && this.doFire)
					spawnFire(4);

				powerLightningRod();
				clearCopperOnLightningStrike(level(), this.getStrikePosition());
				gameEvent(GameEvent.LIGHTNING_STRIKE);
			}
		}

		--this.life;

		if (this.life < 0) {
			if (this.flashes == 0) {
				if (level() instanceof ServerLevel) {
					List<Entity> entities = EntityRetrievalUtil.getEntities(level(), new AABB(getX() - 15, getY() - 15, getZ() - 15, getX() + 15, getY() + 21, getZ() + 15), entity -> entity != this && entity.isAlive() && !this.hitEntities.contains(entity));

					for (ServerPlayer player : ((ServerLevel)level()).getPlayers(player -> player.distanceTo(this) < 256)) {
						CriteriaTriggers.LIGHTNING_STRIKE.trigger(player, this, entities);
					}
				}

				discard();
			}
			else if (this.life < -this.random.nextInt(10)) {
				--this.flashes;
				this.life = 1;
				this.seed = this.random.nextLong();

				if (this.doFire)
					spawnFire(0);
			}
		}

		if (this.life >= 0) {
			if (!(level() instanceof ServerLevel serverLevel)) {
				level().setSkyFlashTime(2);
			}
			else if (!this.visualOnly) {
				List<Entity> entities = EntityRetrievalUtil.getEntities(serverLevel, new AABB(getX() - 3, getY() - 3, getZ() - 3, getX() + 3, getY() + 9, getZ() + 3), entity -> entity != this && entity.isAlive());

				for (Entity entity : entities) {
					if (!EventHooks.onEntityStruckByLightning(entity, this)) {
						entity.thunderHit(serverLevel, this);

						if (this.onEntityStrike != null)
							this.onEntityStrike.accept(entity);
					}
				}

				this.hitEntities.addAll(entities);

				if (this.cause != null)
					CriteriaTriggers.CHANNELED_LIGHTNING.trigger(this.cause, entities);
			}
		}
	}

public void castSpells() {
        float aoe = getAoe();
        int flatAoe = Math.round(aoe);
        BlockPos start = blockPosition().offset(flatAoe * getDirection().getStepX(), 0, flatAoe * getDirection().getStepZ());
        BlockPos end = blockPosition().offset(-flatAoe * getDirection().getStepX(), flatAoe, -flatAoe * getDirection().getStepZ());
        if (isSensitive()) {
            if (age % (Math.max(1, 20 - 2 * getAccelerates())) != 0 && age != 1)
                return;
            for (BlockPos p : BlockPos.betweenClosed(start, end)) {
                p = p.immutable();
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new
                            BlockHitResult(new Vec3(p.getX(), p.getY(), p.getZ()), Direction.UP, p, false));
                }
                resolveEmitter.setPositionOffset(p.subtract(blockPosition()).getCenter());
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
            }
            if (!level.isClientSide) {
                resolveSound.playSound(level, getX(), getY(), getZ());
            }
        } else {
            int i = 0;
            // Expand the axis if start and end are equal

            AABB aabb = AABB.encapsulatingFullBlocks(start, end);
            if (aabb.maxX == aabb.minX) {
                aabb = aabb.inflate(growthFactor, 0, 0);
            }
            if (aabb.maxY == aabb.minY) {
                aabb = aabb.inflate(0, growthFactor, 0);
            }
            if (aabb.maxZ == aabb.minZ) {
                aabb = aabb.inflate(0, 0, growthFactor);
            }
            for (Entity entity : level.getEntities(null, aabb)) {
                if (entity.equals(this) || entity.getType().is(EntityTags.LINGERING_BLACKLIST)) {
                    continue;
                }
                Optional<EntityHit> hit = hitEntities.stream().filter(e -> e.entity.refersTo(entity)).findFirst();
                boolean skipEntity = hit.isPresent();
                if (hit.isPresent() && level.getGameTime() - hit.get().gameTime > 20) {
                    hitEntities.remove(hit.get());
                    skipEntity = false;
                }
                if (skipEntity)
                    continue;
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new EntityHitResult(entity));
                }
                resolveEmitter.setPositionOffset(entity.position.subtract(position).add(0, entity.getBbHeight() / 2.0, 0));
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
                i++;
                if (hit.isEmpty()) {
                    hitEntities.add(new EntityHit(entity));
                }
                if (i > 5)
                    break;
                if (!level.isClientSide) {
                    resolveSound.playSound(level, getX(), getY(), getZ());
                }
            }
            totalProcs += i;
            if (totalProcs >= maxProcs)
                this.remove(RemovalReason.DISCARDED);
        }
    }

@Override
    public void tick() {
        super.tick();
        this.setYRot(this.getYHeadRot());
        this.yBodyRot = this.getYRot();
        this.noPhysics = true;
        this.setNoGravity(true);

        ++this.life;
        if (!this.level.isClientSide) {
            if (!this.sentSpawnEvent) {
                this.level.broadcastEntityEvent(this, (byte)4);
                this.sentSpawnEvent = true;
            }
            if (this.life < 30) {
                Vec3 vector3d;
                if (this.getTarget() != null) {
                    vector3d = this.getTarget().getEyePosition(1.0F);
                    MobUtil.instaLook(this, this.getTarget());
                } else {
                    vector3d = this.getViewVector(1.0F);
                    MobUtil.instaLook(this, vector3d);
                }
                double dx = this.getX() - vector3d.x();
                double dy = this.getY() - vector3d.y();
                double dz = this.getZ() - vector3d.z();
                double d0 = Math.sqrt(dx * dx + dy * dy + dz * dz);
                double velocity = 2.0D;
                double xPower = -(dx / d0 * velocity * 0.2D);
                double yPower = -(dy / d0 * velocity * 0.2D);
                double zPower = -(dz / d0 * velocity * 0.2D);
                this.chargePos = new Vec3(xPower, yPower, zPower);
                this.keepYRot = this.getYRot();
                this.keepXRot = this.getXRot();
            } else {
                this.setYRot(this.keepYRot);
                this.setXRot(this.keepXRot);
                if (!this.sentAttackEvent) {
                    this.level.broadcastEntityEvent(this, (byte)5);
                    this.sentAttackEvent = true;
                }
                if (this.chargePos != null) {
                    this.setDeltaMovement(this.chargePos);
                }
                if (this.life <= 40) {
                    for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                        if (!this.hitEntities.contains(livingEntity) && !MobUtil.areAllies(this.getOwner() != null ? this.getOwner() : this, livingEntity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                            DamageSource damageSource = this.damageSources().mobAttack(this);
                            if (this.getOwner() != null){
                                damageSource = ModDamageSource.summonAttack(this, this.getOwner());
                            }
                            if (livingEntity.hurt(damageSource, AttributesConfig.BlackBeastDamage.get().floatValue())) {
                                this.hitEntities.add(livingEntity);
                            }
                        }
                    }
                } else {
                    this.setDeltaMovement(this.getDeltaMovement().scale(0.25D));
                }
            }
            if (this.life >= 70) {
                this.discard();
            }
        } else {
            if (this.life > 10 && this.life < 50 && this.alpha < 1.0F){
                this.alpha = Mth.clamp(this.alpha + 0.1F, 0.0F, 1.0F);
            }
            if (this.life >= 50){
                this.alpha = Mth.clamp(this.alpha - 0.05F, 0.0F, 1.0F);
            }
        }
    }

