@Override
    public void tick(ModuleContext moduleContext) {
        IOPStorage storage = moduleContext.getOpStorage();
        if (!(moduleContext instanceof StackModuleContext context && EffectiveSide.get().isServer() && storage != null)) {
            return;
        }

        if (tick++ % 10 == 0) clearCaches();
        markDirty();


        ShieldData shieldData = getShieldData(context.getEntity());
        data.shieldCapacity = shieldData.shieldCapacity();
        double chargeRate = shieldData.shieldRecharge();
        boolean enabled = shieldEnabled.getValue() && getShieldPoints() > 0;

        if (data.shieldPoints > data.shieldCapacity) {
            data.shieldPoints = data.shieldCapacity;
        }

        //# Rendering #
        //Hit Indicator (Controls the effect where the shield flashes brighter when hit)
        if (shieldHitIndicator > 0) {
            shieldHitIndicator -= 0.1F;
        }

        data.shieldVisible = enabled && (alwaysVisible.getValue() || System.currentTimeMillis() - lastHitTime < 5000);
        if (data.shieldVisible && shieldAnim < 1) {
            shieldAnim = Math.min(shieldAnim + 0.05F, 1F);
        } else if (!data.shieldVisible && shieldAnim > 0) {
            shieldAnim = Math.max(shieldAnim - 0.05F, 0F);
        }

        if (data.envDmgCoolDown > 0) data.envDmgCoolDown--;

        //# Logic #
        if (!context.isEquipped()) {
            return;
        }

        if (conflict) {
            data.shieldCapacity = 0;
            data.shieldPoints = 0;
            return;
        }

        //Passive Draw
        if (enabled && storage.getOPStored() > 0) {
            double passiveDraw = data.shieldPoints * data.shieldPoints * EquipCfg.shieldPassiveModifier;
            if (passiveDraw > 0) {
                passivePowerCache += passiveDraw;
                if (passivePowerCache >= 1) {
                    storage.modifyEnergyStored(-(int) passivePowerCache);
                    passivePowerCache = passivePowerCache % 1;
                }
            }
        } else if (enabled && data.shieldPoints > 0) {
            //Shield drains if you run out of power. It takes 60 seconds to drain from full to zero.
            data.shieldPoints = Math.max(0, data.shieldPoints - (data.shieldCapacity / (60D * 20D)));
        }
        if (data.shieldBoost > 0) {
            data.boostTime--;
            if (data.boostTime == 0) {
                data.shieldBoost = 0;
            }
        }

        //Recharge Logic
        if (!enabled) chargeRate *= 1.25;
        if (data.shieldCoolDown > 0) {
            data.shieldCoolDown = Math.max(0, data.shieldCoolDown - (enabled ? 100 : 125));
        } else if (data.shieldPoints < data.shieldCapacity && data.shieldCapacity > 0 && chargeRate > 0 && storage.getOPStored() > 0) {
            double energyPerPoint = Math.max(chargeRate * EquipCfg.energyShieldChg, EquipCfg.energyShieldChg);
            long extracted = storage.modifyEnergyStored(-(int) Math.max(1, Math.min(chargeRate, data.shieldCapacity - data.shieldPoints) * energyPerPoint));
            data.shieldPoints += extracted / energyPerPoint;
        }
    }

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
			this.setDead();
			return;
		}

		if(!this.isDead) {
			if(this.getRidingEntity() == null) {
				this.ticksInAir++;

				if(this.ticksInAir > 200) {
					this.setDead();
				}

				Vec3d currentPos = new Vec3d(this.posX, this.posY, this.posZ);
				Vec3d nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
				RayTraceResult hitObject = this.world.rayTraceBlocks(currentPos, nextPos);
				currentPos = new Vec3d(this.posX, this.posY, this.posZ);
				nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);

				if (hitObject != null) {
					nextPos = new Vec3d(hitObject.hitVec.x, hitObject.hitVec.y, hitObject.hitVec.z);
				}

				Entity hitEntity = null;
				List<Entity> hitEntities = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox().grow(this.motionX, this.motionY, this.motionZ).grow(0.1D, 0.1D, 0.1D));
				double minDist = 0.0D;

				for (int i = 0; i < hitEntities.size(); ++i) {
					Entity entity = (Entity)hitEntities.get(i);
					if (entity.canBeCollidedWith() && entity != this.getThrower() && entity != this) {
						float f = 0.1F;
						AxisAlignedBB axisalignedbb = entity.getEntityBoundingBox().grow((double)f, (double)f, (double)f);
						RayTraceResult movingobjectposition1 = axisalignedbb.calculateIntercept(currentPos, nextPos);
						if (movingobjectposition1 != null) {
							double d1 = currentPos.distanceTo(movingobjectposition1.hitVec);
							if (d1 < minDist || minDist == 0.0D) {
								hitEntity = entity;
								minDist = d1;
							}
						}
					}
				}

				if (hitEntity != null) {
					hitObject = new RayTraceResult(hitEntity);
				}

				if (hitObject != null && hitObject.entityHit != this.getThrower()) {
					this.onImpact(hitObject);
				}
				this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
			} else {
				if(this.getRidingEntity() instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) this.getRidingEntity();
					ItemStack heldItem = player.getHeldItem(EnumHand.MAIN_HAND);
					if(!this.isDeflectable() || heldItem == null || heldItem.getItem() instanceof ItemSword == false) {
						if(!this.world.isRemote) {
							this.setDead();
						}
					} else {
						player.setInWeb();
						player.motionY -= 1.5D;
						if(player.isSwingInProgress) {
							if(this.canDismount) {
								Vec3d look = this.getRidingEntity().getLookVec();
								look.normalize();
								this.shoot(look.x, look.y, look.z, 0.5F, 0.0F);
								this.dismountRidingEntity();
								this.setThrower(player);
							}
						} else {
							this.canDismount = true;
						}
					}
				}
			}
		}

		super.onUpdate();
	}

@SubscribeEvent
	public void onProjectileImpact(ProjectileImpactEvent event) {
		if (event.getRayTraceResult() instanceof EntityHitResult) {
			EntityHitResult result = (EntityHitResult) event.getRayTraceResult();

			if (result.getEntity() instanceof Player) {
				Player player = (Player) result.getEntity();
				Entity arrow = event.getEntity();

				if (!player.level().isClientSide) {
					if (arrow instanceof Projectile) {
						Projectile projectile = (Projectile) arrow;

						if (projectile.getOwner() == player) {
							for (String tag : arrow.getTags()) {
								if (tag.startsWith("AB_DEFLECTED")) {
									try {
										int time = Integer.parseInt(tag.split(":")[1]);
										if (arrow.tickCount - time < 10)
											// If we cancel the event here it gets stuck in the infinite loop
											return;
									} catch (Exception ex) {
										ex.printStackTrace();
									}
								}
							}
						}
					}

					boolean trigger = false;
					double chance = 0.0D;

					if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ANGEL_BLESSING)) {
						trigger = true;
						chance += AngelBlessing.deflectChance.getValue().asModifier(false);
					}

					if (SuperpositionHandler.hasCurio(player, EnigmaticItems.THE_CUBE)) {
						trigger = true;
						chance += 0.35;
					}

					if (EnigmaticItems.ENIGMATIC_AMULET.hasColor(player, AmuletColor.VIOLET)) {
						trigger = true;
						chance += 0.15;
					}

					if (trigger && Math.random() <= chance) {
						event.setCanceled(true);

						arrow.setDeltaMovement(arrow.getDeltaMovement().scale(-1.0D));
						arrow.yRotO = arrow.getYRot() + 180.0F;
						arrow.setYRot(arrow.getYRot() + 180.0F);;

						if (arrow instanceof AbstractArrow absar) {
							if (!(absar instanceof ThrownTrident)) {
								absar.setOwner(player);
							}

							((AccessorAbstractArrowEntity)absar).clearHitEntities();
							absar.pickup = Pickup.CREATIVE_ONLY;
							absar.setPierceLevel((byte) 0);
						} else if (arrow instanceof AbstractHurtingProjectile) {
							((AbstractHurtingProjectile) arrow).setOwner(player);

							((AbstractHurtingProjectile) arrow).xPower = -((AbstractHurtingProjectile) arrow).xPower;
							((AbstractHurtingProjectile) arrow).yPower = -((AbstractHurtingProjectile) arrow).yPower;
							((AbstractHurtingProjectile) arrow).zPower = -((AbstractHurtingProjectile) arrow).zPower;
						}

						arrow.getTags().removeIf(tag -> tag.startsWith("AB_DEFLECTED"));
						arrow.addTag("AB_DEFLECTED:" + arrow.tickCount);

						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 64.0D, player.level().dimension())), new PacketForceArrowRotations(arrow.getId(), arrow.getYRot(), arrow.getXRot(), arrow.getDeltaMovement().x, arrow.getDeltaMovement().y, arrow.getDeltaMovement().z, arrow.getX(), arrow.getY(), arrow.getZ()));
						player.level().playSound(null, player.blockPosition(), EnigmaticSounds.DEFLECT, SoundSource.PLAYERS, 1.0F, 0.95F + (float) (Math.random() * 0.1D));
					}
				} /*else {
					if (event.getEntity().getTags().contains("enigmaticlegacy.redirected")) {
						event.setCanceled(true);
						event.getEntity().removeTag("enigmaticlegacy.redirected");
					}
				}*/
			}
		}
	}

public void tick() {
        super.tick();
        this.noPhysics = true;
        if (this.getItem().isEmpty()){
            this.discard();
        }
        Vec3 vec3 = this.getDeltaMovement();
        double d0 = this.getX() + vec3.x;
        double d1 = this.getY() + vec3.y;
        double d2 = this.getZ() + vec3.z;
        double d3 = vec3.horizontalDistance();
        this.setXRot(lerpRotation(this.xRotO, (float)(Mth.atan2(vec3.y, d3) * (double)(180F / (float)Math.PI))));
        this.setYRot(lerpRotation(this.yRotO, (float)(Mth.atan2(vec3.x, vec3.z) * (double)(180F / (float)Math.PI))));
        if (this.getOwner() != null){
            double d4 = this.getOwner().getX() - this.getX();
            double d5 = this.getOwner().getZ() - this.getZ();
            this.setYRot(-((float) Mth.atan2(d4, d5)) * (180F / (float) Math.PI));
        }
        if (!this.level.isClientSide) {
            ++this.life;
            if (this.life < 80){
                this.setDeltaMovement(0.0D, 0.05D, 0.0D);
            } else if (this.life > 100) {
                if (this.getOwner() != null && this.getOwner().level.dimension() == this.level.dimension()) {
                    if (this.getOwner().distanceTo(this) >= 64){
                        this.teleportTowards(this.getOwner());
                    } else {
                        Vec3 vector3d = this.getOwner().getEyePosition();
                        Vec3 vector3d1 = this.position();
                        Vec3 vector3d2 = vector3d.subtract(vector3d1);
                        if (vector3d2.lengthSqr() > 1) {
                            vector3d2.normalize();
                        }
                        double speed = 0.1D;
                        Vec3 motion = new Vec3(vector3d2.x * speed, vector3d2.y * speed, vector3d2.z * speed);
                        this.setDeltaMovement(motion);
                        if (this.getOwner().getBoundingBox().inflate(1.0F).intersects(this.getBoundingBox())){
                            if (this.getOwner() instanceof Player player){
                                if (this.getSecondsCool() > 0){
                                    SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                                }
                                if (!player.getInventory().add(this.getItem())) {
                                    player.drop(this.getItem(), false, true);
                                } else {
                                    if (!this.level.isClientSide){
                                        ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                                    }
                                }
                            } else {
                                this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                            }
                            this.discard();
                        }
                    }
                } else {
                    if (this.getOwner() instanceof Player player){
                        if (this.getSecondsCool() > 0){
                            SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                        }
                        if (!player.getInventory().add(this.getItem())) {
                            player.drop(this.getItem(), false, true);
                        } else {
                            if (!this.level.isClientSide){
                                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                            }
                        }
                    } else {
                        this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                    }
                    this.discard();
                }
            }
        }

        if (this.isInWater()) {
            for(int i = 0; i < 4; ++i) {
                this.level.addParticle(ParticleTypes.BUBBLE, d0 - vec3.x * 0.25D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D, vec3.x, vec3.y, vec3.z);
            }
        } else {
            this.level.addParticle(this.getParticle(), d0 - vec3.x * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, vec3.x, vec3.y, vec3.z);
        }

        if (!this.level.isClientSide) {
            this.setPos(d0, d1, d2);
        } else {
            this.setPosRaw(d0, d1, d2);
        }

    }

private static void summon(Spell.Impact.Action.Summon def, List<Spell.Modifier> spellModifiers,
                               RegistryEntry<Spell> spellEntry, LivingEntity caster, ImpactContext context) {
        var world = caster.getWorld();
        if (!(world instanceof ServerWorld serverWorld)) return;

        // Fold in summon-targeting spell modifiers without mutating the shared Summon / SummonBehaviour
        // instances stored on the registered spell: counts and lifespan adds are accumulated into
        // locals, attribute scaling and behaviour are recomputed onto fresh copies only when needed.
        int spawnCount = def.spawn_count;
        int groupCount = def.group_count;
        int spawnTicksAdd = 0, activeSecondsAdd = 0, despawnTicksAdd = 0;
        var extraActions = new ArrayList<SummonBehaviour.Action.Entry>();
        var attributeScaling = def.attribute_scaling;
        for (var modifier : spellModifiers) {
            spawnCount += modifier.summon_spawn_count_add;
            groupCount += modifier.summon_group_count_add;
            var behaviourMod = modifier.summon_behaviour;
            if (behaviourMod != null) {
                extraActions.addAll(behaviourMod.actions_add);
                spawnTicksAdd += behaviourMod.lifespan.spawn_ticks_add;
                activeSecondsAdd += behaviourMod.lifespan.active_seconds_add;
                despawnTicksAdd += behaviourMod.lifespan.despawn_ticks_add;
            }
            if (modifier.summon_attribute_scaling != null) {
                attributeScaling = AttributeScaling.merged(attributeScaling, modifier.summon_attribute_scaling);
            }
        }
        spawnCount = Math.max(0, spawnCount);
        groupCount = Math.max(0, groupCount);
        var behaviour = (extraActions.isEmpty() && spawnTicksAdd == 0 && activeSecondsAdd == 0 && despawnTicksAdd == 0)
                ? def.behaviour
                : def.behaviour.withModifiers(extraActions, spawnTicksAdd, activeSecondsAdd, despawnTicksAdd);

        var type = Registries.ENTITY_TYPE.get(Identifier.of(def.entity_type_id));
        for (int g = 0; g < groupCount; g++) {
            // Next group slot, wrapping around the list (null when no group offset is configured).
            var groupPlacement = def.group_placements.isEmpty() ? null : def.group_placements.get(g % def.group_placements.size());
            int groupDelay = groupPlacement != null ? groupPlacement.delay_ticks : 0;
            Vec3d groupAnchor = null; // caster position + group offset; captured from the first entity

            for (int i = 0; i < spawnCount; i++) {
                var created = (Entity) type.create(world);
                if (!(created instanceof SpellSummoned summoned)) return;

                // Next per-entity slot, wrapping around the list (null when no slots are configured).
                var placement = def.placements.isEmpty() ? null : def.placements.get(i % def.placements.size());

                summoned.onSummonedBySpell(new SpellSummoned.Args(caster, spellEntry, behaviour, attributeScaling, context));

                // Compose placements: the group offset's resulting position seeds the per-entity
                // placement (both rotate the look-offset by the caster's yaw, so the formation keeps
                // a consistent caster-relative orientation across groups).
                var origin = caster.getPos();
                if (groupPlacement != null) {
                    EntityPlacements.applyEntityPlacement(created, caster, origin, groupPlacement);
                    origin = created.getPos();
                }
                if (i == 0) groupAnchor = origin; // the group's anchor (pre per-entity offset)
                EntityPlacements.applyEntityPlacement(created, caster, origin, placement);

                // applyEntityPlacement only sets entity yaw; sync head/body yaw so the initial pose matches.
                boolean appliedYaw = (groupPlacement != null && groupPlacement.apply_yaw)
                        || (placement != null && placement.apply_yaw);
                if (appliedYaw && created instanceof LivingEntity living) {
                    living.setHeadYaw(living.getYaw());
                    living.setBodyYaw(living.getYaw());
                }
                // Anti-clip: when a contributing placement opts into `line_of_sight`, pull a placed
                // position that is out of the caster's line of sight back to the nearest visible point.
                boolean checkLineOfSight = (placement != null && placement.line_of_sight)
                        || (groupPlacement != null && groupPlacement.line_of_sight);
                if (checkLineOfSight) {
                    var visible = nearestVisiblePosition(caster, created.getPos(), serverWorld);
                    created.setPosition(visible.x, visible.y, visible.z);
                }

                // Defer the world spawn by the combined group + per-entity delay (0 = spawn this tick).
                int entityDelay = placement != null ? placement.delay_ticks : 0;
                ((WorldScheduler) serverWorld).schedule(groupDelay + entityDelay, () -> serverWorld.spawnEntity(created));
            }

            // Group spawn FX + sound: one-shot at the group anchor, deferred by the group delay.
            if (groupAnchor != null && (def.group_spawn_fx != null || def.group_spawn_sound != null)) {
                var anchor = groupAnchor;
                var fx = def.group_spawn_fx;
                var sound = def.group_spawn_sound;
                ((WorldScheduler) serverWorld).schedule(groupDelay, () -> {
                    if (fx != null) emitSummonGroupFx(serverWorld, caster, anchor, fx);
                    if (sound != null) playSummonSound(serverWorld, anchor, sound);
                });
            }
        }
    }

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || this.getOwner() == null || this.getOwner().isDead)) {
			this.setDead();
			return;
		}

		if(!this.world.isRemote) {
			if((this.getOwner() == null || !this.getOwner().isEntityAlive() || this.getOwner() instanceof EntityWight == false || !((EntityWight)this.getOwner()).isVolatile()) /*|| this.target instanceof EntityFortressBoss*/)
				this.setDead();
		}

		if(!this.isDead) {
			this.ticksInAir++;
			if(this.world.isRemote) {
				this.trail.push(this.getPositionVector());
				while(this.trail.size() > 4) {
					this.trail.removeLast();
				}
			}
			if(this.target == null || this.target.isDead) {
				List<Entity> targetList = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(16.0D, 16.0D, 16.0D));
				List<Entity> eligibleTargets = new ArrayList<Entity>();
				if(this.world.rand.nextInt(4) > 0) {
					for(Entity e : targetList) {
						if(e instanceof EntityPlayer) {
							eligibleTargets.add((EntityPlayer)e);
						}
					}
				}
				if(eligibleTargets.isEmpty()) {
					for(Entity e : targetList) {
						if(e instanceof EntityWight == false) {
							eligibleTargets.add(e);
						}
					}
				}
				if(!eligibleTargets.isEmpty()) {
					this.target = eligibleTargets.get(this.world.rand.nextInt(eligibleTargets.size()));
				}
			} 
			if(this.target != null && this.ticksInAir >= 10) {
				double dx = this.target.getEntityBoundingBox().minX + (this.target.getEntityBoundingBox().maxX - this.target.getEntityBoundingBox().minX) / 2.0D - this.posX;
				double dy = this.target.getEntityBoundingBox().minY + (this.target.getEntityBoundingBox().maxY - this.target.getEntityBoundingBox().minY) / 2.0D - this.posY;
				double dz = this.target.getEntityBoundingBox().minZ + (this.target.getEntityBoundingBox().maxZ - this.target.getEntityBoundingBox().minZ) / 2.0D - this.posZ;
				double dist = MathHelper.sqrt(dx * dx + dy * dy + dz * dz);
				double speed = 0.075D;
				double maxSpeed = 0.8D;
				this.motionX += dx / dist * speed;
				this.motionY += dy / dist * speed;
				this.motionZ += dz / dist * speed;
				Vec3d motion = new Vec3d(this.motionX, this.motionY, this.motionZ);
				if(motion.length() > maxSpeed) {
					motion = motion.normalize();
					this.motionX = motion.x * maxSpeed;
					this.motionY = motion.y * maxSpeed;
					this.motionZ = motion.z * maxSpeed;
				}
			}
			Vec3d currentPos = new Vec3d(this.posX, this.posY, this.posZ);
			Vec3d nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
			RayTraceResult hitObject = this.world.rayTraceBlocks(currentPos, nextPos);
			currentPos = new Vec3d(this.posX, this.posY, this.posZ);
			nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
			if (hitObject != null) {
				nextPos = new Vec3d(hitObject.hitVec.x, hitObject.hitVec.y, hitObject.hitVec.z);
			}
			Entity hitEntity = null;
			List<Entity> hitEntities = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox().grow(this.motionX, this.motionY, this.motionZ).grow(2.0D, 2.0D, 2.0D));
			double minDist = 0.0D;
			for (int i = 0; i < hitEntities.size(); ++i) {
				Entity entity1 = (Entity)hitEntities.get(i);
				if (entity1.canBeCollidedWith() && (this.ticksInAir >= 10)) {
					float f = 0.3F;
					AxisAlignedBB axisalignedbb = entity1.getEntityBoundingBox().grow((double)f, (double)f, (double)f);
					RayTraceResult movingobjectposition1 = axisalignedbb.calculateIntercept(currentPos, nextPos);
					if (movingobjectposition1 != null) {
						double d1 = currentPos.distanceTo(movingobjectposition1.hitVec);
						if (d1 < minDist || minDist == 0.0D) {
							hitEntity = entity1;
							minDist = d1;
						}
					}
				}
			}
			if (hitEntity != null) {
				hitObject = new RayTraceResult(hitEntity);
			}
			if (hitObject != null) {
				this.onImpact(hitObject);
			}
			this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		}

		super.onUpdate();
	}

@Override
    public void serverTick() {
        long currentTick = mob.level.getGameTime();
        if (mob.getVehicle() != null) {
            if (mob.getVehicle().getUUID().equals(loadedTarget)) {
                setLeapTarget((LivingEntity) mob.getVehicle());
                loadedTarget = null;
            } else if (target == null && isAttackRiding()) {
                mob.stopRiding();
                stopAttackRiding();
            }
        }
        if (!isLeaping() && target != null && target.isAlive()) {
            mob.lookAt(target, 100, 10);
            if (mob.distanceToSqr(target) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (!isLeaping() && blockTarget != null) {
            if (mob.distanceToSqr(blockTarget) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (isLeaping()) {
            if (target == null && blockTarget == null) {
                stopLeap();
            }
            if (target != null && ((target.isVehicle() && mob.getVehicle() != target) || target.isDeadOrDying())) {
                if (jumpDelayTick != -1) {
                    blockTarget = target.position();
                }
                setAttackRiding(false);
                setLeapTarget(null);
            }
            if (currentTick == jumpDelayTick) {
                double y;
                Vec3 offset;
                if (target != null) {
                    y = Math.min(target.getY() + target.getBbHeight() - mob.getY(), 5);
                    offset = Util.directionVecTo(mob, target).normalize();
                    offset = offset.add(target.getDeltaMovement().x, 0, target.getDeltaMovement().z);
                } else if (blockTarget != null) {
                    y = Math.min(blockTarget.y - mob.getY(), 5);
                    offset = blockTarget.subtract(mob.position()).normalize();
                } else {
                    //Shouldn't really happen
                    y = 0;
                    offset = Vec3.ZERO;
                }
                mob.setDeltaMovement(offset.x, -0.027 * Math.pow(y, 2) + 0.262 * y + 0.183, offset.z);
                setLeapStarted(false);
                setLeapFlying(true);
                landingDelayTick = jumpDelayTick + 5;
                jumpDelayTick = -1;
            }
            if (mob.isOnGround() && landingDelayTick != -1 && landingDelayTick <= currentTick) {
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLandAnimation();
                    landingEndTick = (long) (currentTick + animation.animation.animationLength);
                } else {
                    landingEndTick = currentTick + 2;
                }
                landingDelayTick = -1;
                setLeapFlying(false);
                setLanding(true);
            }
            if (landingEndTick != -1 && landingEndTick <= currentTick) {
                setLanding(false);
                setLeaping(false);
                landingEndTick = -1;
                setBlockLeapTarget(null);
                setLeapTarget(null);
            }
            if (isAttackRiding() && target != null) {
                if (mob.tickCount % 20 == 0) {
                    target.hurt(DamageSource.mobAttack(mob), (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    //target can be set to null during hurt
                }
                if (target != null && target.isDeadOrDying()) {
                    stopAttackRiding();
                }
            }
            if(!isLeapFlying() && !hasLeapStarted() && !isLanding() && !isAttackRiding()) {
                //failsafe
                setLeaping(false);
            }
            //Collision is handled in entity class
        }
    }

@Override
    protected void onHitEntity(EntityHitResult raytrace) {
        Entity target = raytrace.getEntity();
        Entity shooter = getOwner();
        Player playerShooter = CastOptional.cast(shooter, Player.class).orElse(null);

        DamageSource damagesource = level().damageSources().trident(this, (shooter == null ? this : shooter));
        SoundEvent soundevent = SoundEvents.TRIDENT_HIT;

        int pierceLevel = getEffectLevel(ItemEffect.piercing);
        int ricochetLevel = getEffectLevel(ItemEffect.ricochet);

        if (pierceLevel > 0 || ricochetLevel > 0) {
            if (hitEntities == null) {
                hitEntities = new IntOpenHashSet(5);
            }

            if (hitEntities.contains(target.getId())) {
                return;
            }

            if (hitEntities.size() < pierceLevel || hitEntities.size() < ricochetLevel) {
                hitEntities.add(target.getId());
            } else {
                dealtDamage = true;
            }
        } else {
            dealtDamage = true;
        }

        ItemStack heldTemp = null;
        if (playerShooter != null) {
            heldTemp = playerShooter.getMainHandItem();
            playerShooter.setItemInHand(InteractionHand.MAIN_HAND, thrownStack);
        }

        if (target instanceof LivingEntity && thrownStack.getItem() instanceof ItemModularHandheld) {
            LivingEntity targetLivingEntity = (LivingEntity) target;
            ItemModularHandheld item = (ItemModularHandheld) thrownStack.getItem();

            double abilityDamage = item.getAbilityBaseDamage(shooter instanceof LivingEntity living ? living : null, thrownStack);

            double critModifier = CritEffect.rollMultiplier(targetLivingEntity.getRandom(), item, thrownStack);
            double damage = abilityDamage * item.getEffectEfficiency(thrownStack, ItemEffect.throwable);

            damage += EnchantmentHelper.getDamageBonus(thrownStack, targetLivingEntity.getMobType());
            damage *= critModifier;

            if (target.hurt(damagesource, (float) damage)) {
                if (shooter instanceof LivingEntity livingShooter) {
                    EnchantmentHelper.doPostHurtEffects(targetLivingEntity, shooter);
                    EffectHelper.applyEnchantmentHitEffects(getPickupItem(), targetLivingEntity, livingShooter);
                    ItemEffectHandler.applyHitEffects(thrownStack, targetLivingEntity, livingShooter);

                    item.tickProgression(livingShooter, thrownStack, 1);
                }

                doPostHurtEffects(targetLivingEntity);

                if (critModifier != 1d && !level().isClientSide) {
                    Vec3 hitVec = raytrace.getLocation();
                    ((ServerLevel) level()).sendParticles(ParticleTypes.ENCHANTED_HIT,
                            hitVec.x(), hitVec.y(), hitVec.z(), 15, 0.2D, 0.2D, 0.2D, 0.0D);
                }
            }
        }

        float f1 = 1.0F;
        if (!level().isClientSide && level().isThundering() && EnchantmentHelper.hasChanneling(thrownStack)) {
            BlockPos blockpos = target.blockPosition();
            if (level().canSeeSky(blockpos)) {
                LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(this.level());
                lightning.moveTo(Vec3.atBottomCenterOf(blockpos));
                lightning.setCause(shooter instanceof ServerPlayer ? (ServerPlayer) shooter : null);
                this.level().addFreshEntity(lightning);
                soundevent = SoundEvents.TRIDENT_THUNDER;
                f1 = 5.0F;
            }
        }

        if (playerShooter != null) {
            playerShooter.setItemInHand(InteractionHand.MAIN_HAND, heldTemp);
        }

        playSound(soundevent, f1, 1.0F);

        if (dealtDamage) {
            setDeltaMovement(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D));
        } else if (ricochetLevel > 0 && !level().isClientSide) {
            Vec3 hitPos = raytrace.getLocation();
            setPosRaw(hitPos.x(), hitPos.y(), hitPos.z());
            setDeltaMovement(level().getEntities(shooter, new AABB(target.blockPosition()).inflate(8d), entity ->
                            !hitEntities.contains(entity.getId())
                                    && entity instanceof LivingEntity
                                    && !entity.isInvulnerableTo(damagesource)
                                    && (shooter == null || !entity.isAlliedTo(shooter)))
                    .stream()
                    .map(entity -> entity.position().add(0, entity.getBbHeight() * 0.8, 0))
                    .map(pos -> pos.subtract(position()))
                    .min(Comparator.comparing(Vec3::lengthSqr))
                    .map(Vec3::normalize)
                    .map(direction -> direction.multiply(1, 0.5, 1))
                    .map(direction -> direction.scale(Math.max(getDeltaMovement().length() * 0.5, 0.3)))
                    .orElse(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D)));
        }
    }

@Override
    public void tick() {
        LivingEntity target = watcher.getTarget();
        if (navigationCheckCooldown-- < 0) {
            calculateReach();
        }
        if (target != null && target.isAlive()) {
            double dist = watcher.distanceTo(target);
            watcher.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());

            if (retreatFor-- > 0) {
                if (retreatTo == null) {
                    retreatFor = 0;
                } else {
                    Vec3 retreatVec = retreatTo.subtract(watcher.position());
                    if (retreatVec.length() > 1) {
                        retreatVec = retreatVec.normalize();
                        watcher.setDeltaMovement(watcher.getDeltaMovement().add(retreatVec.scale(0.2F)));
                        watcher.setShadeMode(true);
                    } else {
                        retreatTo = null;
                    }
                }
            } else {
                if (!canReachViaGround && !watcher.isShadeMode() && watcher.onGround()) {
                    watcher.setShadeMode(true);
                }
                watcher.setShadeMode(!canReachViaGround);
                if (dist < 6 && watcher.hasLineOfSight(target) && watcher.onGround()) {
                    watcher.setShadeMode(false);
                }
                if (dist > target.getBbWidth() + watcher.getBbWidth() + 0.5F) {
                    watcher.getNavigation().moveTo(target, (watcher.isRunning() ? 1.3F : 1F) + Math.min(Math.log(possessions + 1), 1F) * 0.6F);
                } else {
                    if (watcher.hasLineOfSight(target)) {
                        if (watcher.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                            watcher.setAnimation(watcher.getRandom().nextBoolean() ? WatcherEntity.ANIMATION_ATTACK_0 : WatcherEntity.ANIMATION_ATTACK_1);
                            watcher.playSound(ACSoundRegistry.WATCHER_ATTACK.get());
                        } else if (watcher.getAnimationTick() == 8) {
                            target.hurt(target.damageSources().mobAttack(watcher), (float) watcher.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                            target.knockback(0.5D, watcher.getX() - target.getX(), watcher.getZ() - target.getZ());
                            retreatFor = 30 + watcher.getRandom().nextInt(30);
                            for (int i = 0; i < 15; i++) {
                                Vec3 vec3 = DefaultRandomPos.getPosAway(watcher, 30, 15, target.position());
                                if (vec3 != null) {
                                    retreatTo = vec3;
                                    break;
                                }
                            }
                        }
                    }
                    watcher.getNavigation().stop();
                }
            }
            if (possessions > 2 || dist < 20) {
                watcher.setRunning(true);
            }

            if (watcher.attemptPossession(target)) {
                if (watcher.getPossessedEntity() == null) {
                    possessions++;
                }
                watcher.setPossessedEntityUUID(target.getUUID());
            }
        }
    }

public void tick() {
        super.tick();
        boolean flag = this.isWaiting();
        float f = this.getRadius();
        if (this.level().isClientSide) {
            if (flag && this.random.nextBoolean()) {
                return;
            }
            ParticleOptions particleoptions = this.isSoul() ? ParticleTypes.SOUL_FIRE_FLAME : ParticleTypes.FLAME ;
            float f1 = flag ? 0.2F : f;
            double spread = Math.PI * 2 ;
            int arcLen = Mth.ceil(this.getRadius() * spread);

            if(!flag) {
                if (this.tickCount % 2 == 0) {
                    for (int j = 0; j < arcLen; ++j) {
                        float f2 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        double d0 = this.getX() + (double) (Mth.cos(f2) * f1) * 0.9;
                        double d2 = this.getY();
                        double d4 = this.getZ() + (double) (Mth.sin(f2) * f1) * 0.9;
                        this.level().addParticle(particleoptions, d0, d2, d4, random.nextGaussian() * 0.07D, 0.125D * this.getRadius() + 0.4D, random.nextGaussian() * 0.07D);
                    }
                }
                if (this.random.nextInt(24) == 0) {
                    this.level().playLocalSound(this.getX() + 0.5D, this.getY() + 0.5D, this.getZ() + 0.5D, SoundEvents.BLAZE_BURN, this.getSoundSource(), 1.0F + this.random.nextFloat(), this.random.nextFloat() * 0.7F + 0.3F, false);
                }
            }
        } else {
            if (this.tickCount >= this.waitTime + this.duration + this.warmupDelayTicks) {
                if(this.getRadius() > 0 ){
                    this.setRadius(getRadius() - 0.1F);
                }else{
                    if(!this.isSoul()) {
                        int explosionradius = this.owner instanceof Player ? 1 : 2;

                        IgnisExplosion explosion = new IgnisExplosion(level(), this.owner,null,null, this.getX(), this.getY(), this.getZ(), explosionradius, false, Explosion.BlockInteraction.KEEP);
                        explosion.explode();
                        explosion.finalizeExplosion(0,0);
                    }
                    this.level().broadcastEntityEvent(this, (byte)4);
                    this.discard();
                }
            }


            if (this.tickCount >= this.warmupDelayTicks) {
                this.setSee(true);
            }


            boolean flag1 = this.tickCount < this.waitTime + this.warmupDelayTicks;
            if (flag != flag1) {
                this.setWaiting(flag1);
            }

            if (flag1) {
                return;
            }

        }

        if(!flag) {
            if (this.tickCount % 5 == 0) {
                for (LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                    this.damage(livingentity);
                }
            }
        }
    }

@Override
    protected void handleAttackLogic(double distanceSquared) {
        var meleeRange = meleeRange();
        if (meleeAnimTimer < 0 && (!wantsToMelee || distanceSquared > meleeRange * meleeRange || spellCastingMob.isCasting())) {
            super.handleAttackLogic(distanceSquared);
            return;
        }
        //Handling Animation hit frames
        mob.getLookControl().setLookAt(target);
        deadKing.isMeleeing = meleeAnimTimer > 0;
        if (meleeAnimTimer > 0) {
            //We are currently attacking and are in a melee animation
            forceFaceTarget();
            meleeAnimTimer--;
            if (currentAttack.data.isHitFrame(meleeAnimTimer - 4)) {
                if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                    mob.playSound(SoundRegistry.DEAD_KING_SLAM.get());
                } else {
                    playSwingSound();
                }
            } else if (currentAttack.data.isHitFrame(meleeAnimTimer)) {
                Vec3 lunge = target.position().subtract(mob.position()).normalize().scale(.35f);
                mob.push(lunge.x, lunge.y, lunge.z);
                if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                    Vec3 slamPos = mob.position().add(mob.getForward().multiply(1, 0, 1).normalize().scale(2.5f));
                    Vec3 bbHalf = new Vec3(meleeRange, meleeRange, meleeRange).scale(.3);
                    float damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * 1.5f;
                    mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(slamPos.subtract(bbHalf), slamPos.add(bbHalf))).forEach((entity) -> {
                        if (entity.isPickable() && !DamageSources.isFriendlyFireBetween(mob, entity)) {
                            entity.hurt(mob.level().damageSources().mobAttack(mob), damage);
                            var impulse = (slamPos.subtract(entity.position()).add(0, 0.75, 0)).normalize().scale(Mth.lerp(entity.distanceToSqr(mob.position()) / (meleeRange * meleeRange), 2, .5));
                            entity.setDeltaMovement(entity.getDeltaMovement().add(impulse));
                            entity.hurtMarked = true;
                            if (entity instanceof Player player && player.isBlocking()) {
                                player.disableShield();
                            }
                        }
                    });
                } else {
                    if (distanceSquared <= meleeRange * meleeRange && Utils.hasLineOfSight(mob.level, mob, target, true)) {
                        boolean flag = this.mob.doHurtTarget(target);
                        target.invulnerableTime = 0;
                        if (flag) {
                            if (currentAttack.data.isSingleHit() && ((mob.getRandom().nextFloat() < .75f) || target.isBlocking())) {
                                //Attack again! combos!
                                queueCombo = randomizeNextAttack(0);
                            }
                        }
                    }
                }

            }
        } else if (queueCombo != null && target != null && !target.isDeadOrDying()) {
            nextAttack = queueCombo;
            queueCombo = null;
            doMeleeAction();
        } else if (meleeAnimTimer == 0) {
            //Reset animations/attack
            nextAttack = randomizeNextAttack((float) distanceSquared);
            resetMeleeAttackInterval(distanceSquared);
            meleeAnimTimer = -1;
        } else {
            //Handling attack delay
            if (distanceSquared < meleeRange * meleeRange * 1.2 * 1.2) {
                if (hasLineOfSight && --this.meleeAttackDelay == 0) {
                    doMeleeAction();
                } else if (this.meleeAttackDelay < 0) {
                    resetMeleeAttackInterval(distanceSquared);
                }
            }
        }
    }

@Override
	public void tick() {
		Purpoid purpoid = this.purpoid;
		if (!purpoid.isBoosting()) {
			purpoid.setBoostingTicks(5);
		}
		this.delayCounter = Math.max(this.delayCounter - 1, 0);
		LivingEntity target = purpoid.getTarget();
		double distanceToTargetSq = purpoid.distanceToSqr(target);
		RandomSource random = purpoid.getRandom();
		if (this.delayCounter <= 0 && random.nextFloat() < 0.05F) {
			this.delayCounter = 15 + random.nextInt(11);
			PathNavigation pathNavigator = purpoid.getNavigation();
			if (distanceToTargetSq >= 9.0F) {
				Path path = pathNavigator.createPath(purpoid.getSize() == PurpoidSize.NORMAL ? findAirPosAboveTarget(purpoid.level(), target) : target.blockPosition().above(random.nextInt(3)), 0);
				if (path == null || !pathNavigator.moveTo(path, 2.25F)) {
					this.delayCounter += 20;
				}
			} else {
				purpoid.getMoveControl().setWantedPosition(target.getX(), target.getY(), target.getZ(), 2.25F);
			}
		}

		boolean small = purpoid.getSize() == PurpoidSize.PURP;
		float width = purpoid.getBbWidth() * (small ? 3.25F : 2.0F);
		double reachRange = width * width + target.getBbWidth();
		if (distanceToTargetSq <= reachRange) {
			if (small) {
				if (purpoid.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEFRAG) && purpoid.getAnimationTick() == 5) {
					target.hurt(purpoid.level().damageSources().mobAttack(purpoid), (float) purpoid.getAttributeValue(Attributes.ATTACK_DAMAGE));
					double targetX = target.getX();
					double targetY = target.getY();
					double targetZ = target.getZ();
					for (int i = 0; i < 16; i++) {
						double randomX = targetX + (random.nextDouble() - 0.5D) * 32.0D;
						double randomY = targetY + (random.nextInt(33) - 16);
						double randomZ = targetZ + (random.nextDouble() - 0.5D) * 32.0D;
						if (target.randomTeleport(randomX, randomY, randomZ, false)) {
							if (target instanceof ServerPlayer) {
								EndergeticExpansion.CHANNEL.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) target), new S2CEnablePurpoidFlash());
							}
							break;
						}
					}
				} else if (purpoid.isNoEndimationPlaying()) {
					NetworkUtil.setPlayingAnimation(purpoid, EEPlayableEndimations.PURPOID_TELEFRAG);
				}
			} else {
				purpoid.startRiding(target);
			}
			this.teleportToTargetTimer = 0;
		} else if (small && distanceToTargetSq >= 2.0D && distanceToTargetSq <= 1024.0D && random.nextFloat() < 0.1F && ++this.teleportToTargetTimer >= 10) {
			double targetX = target.getX();
			double targetY = target.getY();
			double targetZ = target.getZ();
			Level level = purpoid.level();
			EntityDimensions dimensions = purpoid.getDimensions(purpoid.getPose());
			double predictedXDisplacement = Mth.clamp(target.getDeltaMovement().x() * 57.0F, -7.0D, 7.0D);
			double predictedZDisplacement = Mth.clamp(target.getDeltaMovement().z() * 57.0F, -7.0D, 7.0D);
			for (int i = 0; i < 16; i++) {
				double randomX = targetX + predictedXDisplacement;
				double randomY = targetY + random.triangle(0.0D, 2.0D);
				double randomZ = targetZ + predictedZDisplacement;
				if (level.noCollision(dimensions.makeBoundingBox(randomX, randomY, randomZ))) {
					purpoid.getTeleportController().beginTeleportation(purpoid, new Vec3(randomX, randomY, randomZ), false);
					purpoid.getNavigation().stop();
					break;
				}
			}
			this.teleportToTargetTimer = 0;
		}
	}

@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        if (commonArmorHandler.isOnCooldown(EquipmentSlot.FEET)) {
            // putting the boots on cooldown is a way for other mods to temporarily suppress jet boots
            return;
        }

        int jetbootsCount = commonArmorHandler.getUpgradeCount(EquipmentSlot.FEET, ModUpgrades.JET_BOOTS.get());
        if (jetbootsCount == 0) return;

        int jetbootsAirUsage = 0;

        Player player = commonArmorHandler.getPlayer();
        JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
        JetBootsLocalState jbLocal = commonArmorHandler.getExtensionData(this);

        if (commonArmorHandler.hasMinPressure(EquipmentSlot.FEET)) {
            boolean vibration = !player.level().isClientSide() && player.tickCount % 10 == 0;
            if (jbState.isActive()) {
                if (jbState.isBuilderMode() && jetbootsCount >= BUILDER_MODE_LEVEL) {
                    // builder mode - rise vertically (or hover if sneaking and firing)
                    setYMotion(player, player.isShiftKeyDown() ? 0 : 0.15 + 0.15 * (jetbootsCount - 3));
                    jetbootsAirUsage = (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * jetbootsCount / 2.5F);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY_BUILDER);
                    }
                } else {
                    // jetboots firing - move in direction of looking
                    Vec3 lookVec = player.getLookAngle().scale(0.3 * jetbootsCount);
                    jbLocal.updateAccel(lookVec);
                    lookVec = jbLocal.getEffectiveMotion(lookVec, player.isFallFlying());
                    player.setDeltaMovement(lookVec.x, player.onGround() ? 0 : lookVec.y, lookVec.z);
                    jetbootsAirUsage = jbLocal.calcAirUsage(jetbootsCount);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY);
                    }
                }
                if (player.isInWater()) jetbootsAirUsage *= 4;
                jbLocal.tickActive();
            } else if (jbState.isEnabled() && !isOnGround(player) && !player.isFallFlying()) {
                // jetboots not firing, but enabled - slowly descend (or hover if enough upgrades)
                // and bring player to complete halt if flight stabilizers and not actively moving forward/sideways
                boolean reallyHovering = jbLocal.canHover() && (!jbLocal.isSmartHover() || jbLocal.isHovering());
                boolean stopped = jbLocal.isFlightStabilizers()
                        && jetbootsCount >= STABILIZERS_LEVEL
                        && PneumaticCraftUtils.epsilonEquals(player.zza, 0f)
                        && PneumaticCraftUtils.epsilonEquals(player.xxa, 0f);
                double xMotion = stopped ? 0 : player.getDeltaMovement().x;
                double yMotion = reallyHovering ? (player.isShiftKeyDown() ? -0.45 : -0.1 + 0.02 * jetbootsCount) : player.getDeltaMovement().y;
                double zMotion = stopped ? 0 : player.getDeltaMovement().z;
                player.setDeltaMovement(new Vec3(xMotion, yMotion, zMotion));
                if (vibration && player.getKnownMovement().lengthSqr() > 0.03) {
                    player.gameEvent(jbState.isBuilderMode() ? ModGameEvents.JET_BOOTS_FLY_BUILDER : ModGameEvents.JET_BOOTS_FLY);
                }
                if (reallyHovering) player.fallDistance = 0;
                jetbootsAirUsage = reallyHovering ? (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * (player.isShiftKeyDown() ? 0.25F : 0.5F)) : 0;
                jbLocal.resetAccel();
            } else if (isOnGround(player)) {
                jbLocal.setHovering(false);
            } else {
                jbLocal.resetAccel();
            }
        } else {
            // insufficient pressure!
            if (jbState.isEnabled() && !player.onGround() && !player.isFallFlying() && jbLocal.isHovering()) {
                // still active and in the air: using minimal air here keeps the boots running
                // and thus avoids triggering multiple looping sounds (see "jet boots starting up" code below)
                jetbootsAirUsage = 1;
            }
            setJetBootsActive(commonArmorHandler,false);
        }

        if (jetbootsAirUsage != 0 && !player.level().isClientSide) {
            if (jbLocal.getPrevJetBootsAirUsage() == 0) {
                // jet boots starting up
                NetworkHandler.sendToAllTracking(new PacketPlayMovingSound(MovingSounds.Sound.JET_BOOTS, MovingSoundFocus.of(player)), player.level(), player.blockPosition());
                ModCriterionTriggers.FLIGHT.get().trigger((ServerPlayer) player);
            }
            if (player.horizontalCollision) {
                double vel = player.getDeltaMovement().length();
                if (player.level().getDifficulty() == Difficulty.HARD) {
                    vel *= 2;
                } else if (player.level().getDifficulty() == Difficulty.NORMAL) {
                    vel *= 1.5;
                }
                if (vel > 2) {
                    player.playSound(vel > 2.5 ? SoundEvents.GENERIC_BIG_FALL : SoundEvents.GENERIC_SMALL_FALL, 1.0F, 1.0F);
                    player.hurt(player.damageSources().flyIntoWall(), (float) vel);
                    ModCriterionTriggers.FLY_INTO_WALL.get().trigger((ServerPlayer) player);
                }
            }
            commonArmorHandler.addAir(EquipmentSlot.FEET, -jetbootsAirUsage);

            if (player.position().y > player.level().getMaxBuildHeight() + ConfigHelper.common().armor.jetBootsHeightLimit.get()) {
                player.getCooldowns().addCooldown(ModItems.PNEUMATIC_BOOTS.get(), 20);
            }
        }
        jbLocal.setPrevJetBootsAirUsage(jetbootsAirUsage);

    }

@Override
    protected void onHitEntity(EntityHitResult p_213868_1_) {
        Entity entity = p_213868_1_.getEntity();
        float velLength = (float) this.getDeltaMovement().length();
        double baseDamage = this.getBaseDamage();
        Entity owner = this.getOwner();
        DamageSource damagesource = getDamageSource(entity);
        if (this.getWeaponItem() != null && this.level() instanceof ServerLevel serverlevel) {
            baseDamage = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), entity, damagesource, (float)baseDamage);
        }
        int damage = Mth.ceil(Mth.clamp((double)velLength * baseDamage, 0.0D, 2.147483647E9D));

        int penetration = entityData.get(PENETRATION);
        if (this.getPierceLevel() > 0 || penetration > 0) {
            if (this.piercingIgnoreEntityIds == null) {
                this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
            }

            if (this.piercedAndKilledEntities == null) {
                this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1 && this.piercingIgnoreEntityIds.size() >= penetration + 1) {
                this.discard();
                return;
            }

            this.piercingIgnoreEntityIds.add(entity.getId());
        }

        if (this.isCritArrow()) {
            long j = (long) this.random.nextInt(damage / 2 + 2);
            damage = (int) Math.min(j + (long) damage, 2147483647L);
        }

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.setRemainingFireTicks(5);
        }

        //Break shields with penetration
        if (penetration > 1 && entity instanceof Player) {
            Player player = (Player) entity;
            if (player.isUsingItem() && player.getUseItem().getItem() instanceof ShieldItem) {
                player.getCooldowns().addCooldown(player.getUseItem().getItem(), 100);
                level().broadcastEntityEvent(player, (byte) 30);
                player.stopUsingItem();
            }
        }

        if (entity.hurt(damagesource, (float) damage)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                if (!level().isClientSide && this.getPierceLevel() <= 0 && penetration <= 0) {
                    livingentity.setArrowCount(livingentity.getArrowCount() + 1);
                }

                this.doKnockback(livingentity, damagesource);
                if (this.level() instanceof ServerLevel serverlevel1) {
                    EnchantmentHelper.doPostAttackEffectsWithItemSource(serverlevel1, livingentity, damagesource, this.getWeaponItem());
                }

                this.doPostHurtEffects(livingentity);
                if (livingentity != owner && livingentity instanceof Player && owner instanceof ServerPlayer && !this.isSilent()) {
                    ((ServerPlayer) owner).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }

                if (!level().isClientSide && owner instanceof ServerPlayer serverPlayer) {
                    if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, this.piercedAndKilledEntities);
                    } else if (!entity.isAlive() && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, Arrays.asList(entity));
                    }
                }
            }

            this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (this.getPierceLevel() <= 0 && penetration <= 0) {
                this.discard();
            }
        } else {
            entity.setRemainingFireTicks(k);
            this.setDeltaMovement(this.getDeltaMovement().scale(0));
            this.setYRot(getYRot() + 180.0F);
            this.yRotO += 180.0F;
            if (!level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }

                this.discard();
            }
        }
    }

private void executeAttacks() {
		if (this.currentState == State.MORTAR_SHOOTING && this.ticksProgress % 10 == 0) {
			HydraMortar mortar = new HydraMortar(TFEntities.HYDRA_MORTAR.get(), this.headEntity.level(), this.headEntity);

			// launch blasting mortars if the player is hiding
			if (this.targetEntity != null && !this.headEntity.canEntityBeSeen(this.targetEntity)) {
				mortar.setToBlasting();
			}

			this.headEntity.playSound(TFSounds.HYDRA_SHOOT.get(), 10.0F, (this.headEntity.level().getRandom().nextFloat() - this.headEntity.level().getRandom().nextFloat()) * 0.2F + 1.0F);
			this.headEntity.level().addFreshEntity(mortar);

		}
		if (this.headEntity.getState() == State.BITING) {
			// damage nearby things
			List<Entity> nearbyList = this.headEntity.level().getEntities(this.headEntity, this.headEntity.getBoundingBox().inflate(0.0, 1.0, 0.0));

			for (Entity nearby : nearbyList) {
				if (nearby instanceof LivingEntity living && nearby != this.hydra) {
					//is a player holding a shield? Let's do some extra stuff!
					if (nearby instanceof Player player && player.isBlocking()) {
						if (!player.getCooldowns().isOnCooldown(player.getUseItem())) {
							//cause severe damage and play a shatter sound
							this.headEntity.level().playSound(null, player.blockPosition(), player.getUseItem().is(Items.SHIELD) ? TFSounds.WOOD_SHIELD_SHATTERS.get() : TFSounds.METAL_SHIELD_SHATTERS.get(), SoundSource.PLAYERS, 1.0F, player.getVoicePitch());
							player.getUseItem().hurtAndBreak(112, player, player.getUsedItemHand());
						}
						//add cooldown and knockback
						player.getCooldowns().addCooldown(player.getUseItem(), 200);
						player.stopUsingItem();
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.15F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					}

					// bite it!
					nearby.hurt(TFDamageTypes.getEntityDamageSource(living.level(), TFDamageTypes.HYDRA_BITE, this.hydra, TFEntities.HYDRA.get()), BITE_DAMAGE);

					//knockback!
					if (living instanceof Player player) {
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.1F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					} else {
						living.knockback(-this.headEntity.getDirection().getStepX(), 0.1F, -this.headEntity.getDirection().getStepZ());
					}
				}
			}
		}

		if (this.headEntity.getState() == State.FLAMING) {
			Entity target = getHeadLookTarget();

			if (target != null && target != this.headEntity.getParent() && (!(target instanceof HydraPart) || ((HydraPart) target).getParent() != this.headEntity.getParent()) && this.hydra.level() instanceof ServerLevel serverLevel) {
				if (!target.fireImmune() && target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(target.level(), TFDamageTypes.HYDRA_FIRE, this.hydra, TFEntities.HYDRA.get()), FLAME_DAMAGE)) {
					target.igniteForSeconds(FLAME_BURN_FACTOR);
				}
			}
		}
	}

private void echoReap(ServerPlayer player, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, int chargedTicks, AABB aoe,
            double damageMultiplier, int revengeLevel, boolean overextend, int overextendLevel, double momentumEfficiency, int comboPoints) {
        EchoHelper.echo(player, 60, () -> {
            AtomicInteger kills = new AtomicInteger();
            AtomicInteger revengeKills = new AtomicInteger();
            AtomicInteger hits = new AtomicInteger();
            hitEntities(player, item, itemStack, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel, momentumEfficiency,
                    kills, revengeKills, hits);

            applyBuff(player, kills.get(), hits.get(), hand, item, itemStack, chargedTicks, comboPoints, revengeKills.get());
            player.sweepAttack();
        });
    }

public boolean initiateNukeVirus(int pos) {
        Validate.isTrue(pos >= 0 && pos < GRID_SIZE, "nuke position " + pos + " out of range!");
        Node node = getNodeAt(pos);
        if (node != null && pendingNukePos < 0 && isNukeVirusReady()
                && node.type != NetworkComponentType.DIAGNOSTIC_SUBROUTINE
                && node.type != NetworkComponentType.NETWORK_REGISTRY)
        {
            pendingNukePos = pos;
            return true;
        } else {
            return false;
        }
    }

public void breakShield(LivingEntity entity, boolean expired) {
		// Temp shields should break first before permanent ones. Reset time each time a temp shield is busted.
		if (this.temporaryShields > 0) {
			this.temporaryShields--;
			this.resetTimer();
		} else if (this.permanentShields > 0) {
			this.permanentShields--;
		}

		if (entity instanceof ServerPlayer player && !expired) {
			player.awardStat(TFStats.TF_SHIELDS_BROKEN.get());
		}
		entity.level().playSound(null, entity.blockPosition(), expired ? TFSounds.SHIELD_EXPIRE.get() : TFSounds.SHIELD_BREAK.get(), SoundSource.PLAYERS, 1.0F, (entity.getRandom().nextFloat() - entity.getRandom().nextFloat()) * 0.3F + 1.0F);
		entity.setData(TFDataAttachments.FORTIFICATION_SHIELDS, this);
	}

protected void calculateCollision(Level world) {

        Vec3 start = this.position();
        Vec3 end = start.add(this.getDeltaMovement());
        BlockHitResult blockResult = this.getBlockHitResult(world, start, end);
        boolean blockCollision = false;
        if (blockResult.getType() != HitResult.Type.MISS) {
            end = blockResult.getLocation();
            blockCollision = true;
        }
        this.hitEntities(this.level, start, end);

        if (blockCollision && !EventHooks.onProjectileImpact(this, blockResult)) {
            this.onHitBlock(blockResult);
        }
    }

@Override
    public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
        if (!attacker.level().isClientSide) {
            int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
            double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
            int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
            int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
            boolean overextend = overextendLevel > 0 && !attacker.getFoodData().needsFood();
            ServerPlayer serverPlayer = (ServerPlayer) attacker;

            int cooldown = getCooldown(item, itemStack);
            double damageMultiplier = EffectHelper.getEffectLevel(itemStack, ItemEffect.reap) / 100d;
            double range = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.reap);

            if (overchargeBonus > 0) {
                damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
                range += overchargeBonus * 0.5;
            }

            int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
            int comboPoints = ComboPoints.get(attacker);
            if (comboLevel > 0) {
                damageMultiplier += comboLevel * comboPoints / 100d;
            }

            AtomicInteger kills = new AtomicInteger();
            AtomicInteger revengeKills = new AtomicInteger();
            AtomicInteger hits = new AtomicInteger();
            Vec3 targetVec;
            if (target != null) {
                targetVec = hitVec;
            } else {
                targetVec = Vec3.directionFromRotation(attacker.getXRot(), attacker.getYRot())
                        .normalize()
                        .scale(range)
                        .add(attacker.getEyePosition(0));
            }

            AABB aoe = new AABB(targetVec, targetVec).inflate(range, 1d, range);

            hitEntities(serverPlayer, item, itemStack, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel, momentumEfficiency,
                    kills, revengeKills, hits);

            applyBuff(attacker, kills.get(), hits.get(), hand, item, itemStack, chargedTicks, comboPoints, revengeKills.get());

            attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                    SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

            item.tickProgression(attacker, itemStack, 1 + kills.get());

            attacker.sweepAttack();

            attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);

            double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationEfficiency > 0 && kills.get() > 0) {
                cooldown = (int) (cooldown * (1 - exhilarationEfficiency / 100d));
            }

            attacker.getCooldowns().addCooldown(item, cooldown);

            int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
            if (echoLevel > 0) {
                echoReap(serverPlayer, hand, item, itemStack, chargedTicks, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel,
                        momentumEfficiency, comboPoints);
            }
        }
        attacker.swing(hand, false);

        if (ComboPoints.canSpend(item, itemStack)) {
            ComboPoints.reset(attacker);
        }

        item.applyDamage(2, itemStack, attacker);
    }

public void tick() {
        skipTravel = false;
        Entity entity = this.getOwner();
        var behaviour = getBehaviour();
        var spellEntry = getSpellEntry();
        if (!this.getWorld().isClient) {
            // Server side
            if (spellEntry == null) {
                System.err.println("Spell Projectile safeguard termination, failed to resolve spell: " + spellId());
                this.kill();
                return;
            }
            switch (behaviour) {
                case FLY -> {
                    if (distanceTraveled >= range || age > 1200) { // 1200 ticks = 1 minute
                        this.kill();
                        return;
                    }
                }
                case FALL -> {
                    var fallDistance = range * 0.98F;
                    if (distanceTraveled >= fallDistance) {
                        // Travel advances in whole velocity steps, so this threshold is overshot
                        // by up to a full step (e.g. velocity 1.5 against a 9.8 threshold ends
                        // 0.7 too low — below the aimed surface). Snap back along the travel
                        // direction so the impact and its area FX land where the threshold was
                        // actually crossed.
                        var overshoot = distanceTraveled - fallDistance;
                        var velocity = this.getVelocity();
                        if (overshoot > 0 && velocity.lengthSquared() > 1e-6) {
                            this.setPosition(this.getPos().subtract(velocity.normalize().multiply(overshoot)));
                        }
                        finishFalling();
                        this.kill();
                        return;
                    }
                    if (age > 1200) { // 1200 ticks = 1 minute
                        this.kill();
                        return;
                    }
                }
            }
            if (distanceTraveled >= range || age > 1200) { // 1200 ticks = 1 minute
                this.kill();
                return;
            }
        }
        this.previousVelocity = new Vec3d(getVelocity().x, getVelocity().y, getVelocity().z);
        if (this.getWorld().isClient || (entity == null || !entity.isRemoved()) && this.getWorld().isChunkLoaded(this.getBlockPos())) {
            super.tick();

            if (!getWorld().isClient) {
                HitResult hitResult = ProjectileUtil.getCollision(this, this::canHit);
                var data = projectileData();
                if (data != null && data.hitbox != null) {
                    if (hitResult.getType() == HitResult.Type.BLOCK) {
                        // Block hit: handle normally (preserves bounce/block-impact)
                        handleHitResult(hitResult, behaviour, spellEntry);
                    } else {
                        // Entity/miss from raycast: discard, use swept OBB detection instead
                        performVolumetricEntityCollision(behaviour, spellEntry, data);
                    }
                } else {
                    // RAYCAST mode (default) — original path with intersects bug fixed
                    handleHitResult(hitResult, behaviour, spellEntry);
                    if (hitResult.getType() == HitResult.Type.MISS && hasCustomDimensions) {
                        var boundingBox = this.getBoundingBox();
                        for (Entity areaTarget : this.getWorld().getOtherEntities(entity, this.getBoundingBox().expand(1), this::canHit)) {
                            if (areaTarget.getBoundingBox().intersects(boundingBox)) {
                                var areaHitResult = new EntityHitResult(areaTarget);
                                handleHitResult(areaHitResult, behaviour, spellEntry);
                            }
                        }
                    }
                }
            }

            this.checkBlockCollision();

            // Travel
            if (!skipTravel) {
                this.followTarget();
                // Flight physics (gravity/drag) run after homing and before the move, so homing
                // aims first and drag then damps the whole velocity (vanilla order). May expire
                // the projectile via `min_speed`.
                applyMotion();
                if (this.isRemoved()) {
                    return;
                }
                Vec3d velocity = this.getVelocity();
                double d = this.getX() + velocity.x;
                double e = this.getY() + velocity.y;
                double f = this.getZ() + velocity.z;
                ProjectileUtil.setRotationFromVelocity(this, 0.2F);

                if (this.isTouchingWater()) {
                    for(int i = 0; i < 4; ++i) {
                        this.getWorld().addParticle(ParticleTypes.BUBBLE, d - velocity.x * 0.25, e - velocity.y * 0.25, f - velocity.z * 0.25, velocity.x, velocity.y, velocity.z);
                    }
                }

                var data = projectileData();
                if (data != null) {
                    if (getWorld().isClient) {
                        for (var travel_particles : data.client_data.travel_particles) {
                            ParticleHelper.play(getWorld(), this, getYaw(), getPitch(), travel_particles);
                        }
                    } else {
                        if (data.travel_sound != null && age % data.travel_sound_interval == 0) {
                            SoundHelper.playSound(getWorld(), this, data.travel_sound);
                        }
                    }
                }

                this.setPosition(d, e, f);
                this.distanceTraveled += velocity.length();
            }
        } else {
            this.discard();
        }
    }

protected void onHitEntity(EntityHitResult p_213868_1_)
	{
		super.onHitEntity(p_213868_1_);
		Entity entity = p_213868_1_.getEntity();
		float f = (float) this.getDeltaMovement().length();
		int i = Mth.ceil(Mth.clamp(this.damage, 0.0D, 2.147483647E9D));
		if (this.getPierceLevel() > 0)
		{
			if (this.piercedEntities == null)
			{
				this.piercedEntities = new IntOpenHashSet(5);
			}

			if (this.hitEntities == null)
			{
				this.hitEntities = Lists.newArrayListWithCapacity(5);
			}

			if (this.piercedEntities.size() >= this.getPierceLevel() + 1)
			{
				this.discard();
				return;
			}

			this.piercedEntities.add(entity.getId());
		}

		if (this.getIsCritical())
		{
			long j = (long) this.random.nextInt(i / 2 + 2);
			i = (int) Math.min(j + (long) i, 2147483647L);
		}

		Entity entity1 = this.getOwner();
		DamageSource damagesource;
		if (entity1 == null)
		{
			damagesource = entity.damageSources().thrown(this,this);
		} else
		{
			damagesource = entity.damageSources().thrown(this, entity1);
			if (entity1 instanceof LivingEntity)
			{
				((LivingEntity) entity1).setLastHurtMob(entity);
			}
		}

		boolean flag = entity.getType() == EntityType.ENDERMAN;
		int k = entity.getRemainingFireTicks();
		if (this.isOnFire() && !flag)
		{
			entity.setSecondsOnFire(5);
		}

		if (entity.hurt(damagesource, (float) i))
		{
			if (flag)
			{
				return;
			}

			if (!entity.isAlive() && entity1 instanceof Player && entity instanceof LivingEntity)
			{
				double willAmount = this.getWillDropForMobHealth(((LivingEntity) entity).getMaxHealth());
				if (willAmount > 0)
					PlayerDemonWillHandler.addDemonWill(willType, (Player) entity1, willAmount);
			}

			if (entity instanceof LivingEntity)
			{
				LivingEntity livingentity = (LivingEntity) entity;
//				if (!this.world.isRemote && this.getPierceLevel() <= 0)
//				{
//					livingentity.setArrowCountInEntity(livingentity.getArrowCountInEntity() + 1);
//				}

				if (this.knockbackStrength > 0)
				{
					Vec3 vector3d = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockbackStrength * 0.6D);
					if (vector3d.lengthSqr() > 0.0D)
					{
						livingentity.push(vector3d.x, 0.1D, vector3d.z);
					}
				}

				if (!this.level().isClientSide && entity1 instanceof LivingEntity)
				{
					EnchantmentHelper.doPostHurtEffects(livingentity, entity1);
					EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity);
				}

				this.daggerHit(livingentity);
				if (entity1 != null && livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer && !this.isSilent())
				{
					((ServerPlayer) entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
				}

				if (!entity.isAlive() && this.hitEntities != null)
				{
					this.hitEntities.add(livingentity);
				}
			}

			this.playSound(this.hitSound, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
			if (this.getPierceLevel() <= 0)
			{
				this.discard();
			}
		} else
		{
			entity.setRemainingFireTicks(k);
			this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
			this.setYRot(this.getYRot() + 180.0F);
			this.yRotO += 180.0F;
			if (!this.level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D)
			{
				if (this.pickupStatus == AbstractArrow.Pickup.ALLOWED)
				{
					this.spawnAtLocation(this.getArrowStack(), 0.1F);
				}

				this.discard();
			}
		}

	}

public void tick() {
        boolean flag = this.checkCage();
        if (this.level == null){
            return;
        }
        if (flag) {
            if (this.cursedCageTile.getSouls() > 0){
                RitualRecipe recipe = this.getCurrentRitualRecipe();
                double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                double d1 = (double)this.worldPosition.getY() + this.level.random.nextDouble();
                double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                if (!this.level.isClientSide) {
                    ServerLevel serverWorld = (ServerLevel) this.level;
                    if (recipe != null) {

                        this.restoreCastingPlayer();

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            for (int p = 0; p < 4; ++p) {
                                serverWorld.sendParticles(ParticleTypes.FLAME, d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                            }
                        }

                        ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);

                        if (this.remainingAdditionalIngredients == null) {
                            this.restoreRemainingAdditionalIngredients();
                            if (this.remainingAdditionalIngredients == null) {
                                Goety.LOGGER
                                        .warn("Could not restore remainingAdditionalIngredients during tick - world seems to be null. Will attempt again next tick.");
                                return;
                            }
                        }

                        if (recipe.getRitual().isPending(this)) {
                            return;
                        }

                        IItemHandler handler = this.itemStackHandler.orElseThrow(RuntimeException::new);
                        if (!recipe.getRitual().isValid(this.level, this.worldPosition, this, this.castingPlayer,
                                handler.getStackInSlot(0), this.remainingAdditionalIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            return;
                        }

                        if (this.level.getGameTime() % 20 == 0) {
                            if (this.cursedCageTile.getSouls() >= recipe.getSoulCost()){
                                this.cursedCageTile.decreaseSouls(recipe.getSoulCost());
                                serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F);
                                serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double)this.worldPosition.getX() + 0.5D, (double)this.worldPosition.getY() + 1.15D, (double)this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                this.currentTime++;
                            } else {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noSouls.fail"), true);
                                this.stopRitual(false);
                                return;
                            }
                        }

                        if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual) {
                            if (this.experienceTaken < enchantItemRitual.getLevelCost(handler.getStackInSlot(0))) {
                                if (this.castingPlayer.experienceLevel > 1) {
                                    if (this.level.getGameTime() % 10 == 0) {
                                        serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 0.5F, 0.5F);
                                        this.castingPlayer.giveExperienceLevels(-1);
                                        this.experienceTaken += 1;
                                    }
                                    this.addXPParticles(serverWorld);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noXP.fail"), true);
                                    this.stopRitual(false);
                                    return;
                                }
                            }
                        }

                        recipe.getRitual().update(this.level, this.worldPosition, this, this.castingPlayer, handler.getStackInSlot(0),
                                this.currentTime, recipe.getDuration());

                        if (!recipe.getRitual()
                                .consumeAdditionalIngredients(this.level, this.worldPosition, this.castingPlayer, this.remainingAdditionalIngredients,
                                        this.currentTime, this.consumedIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (recipe.getDuration() >= 0 && this.currentTime >= recipe.getDuration()) {
                            if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual){
                                if (this.experienceTaken >= enchantItemRitual.getLevelCost(handler.getStackInSlot(0))){
                                    this.stopRitual(true);
                                }
                            } else if (!recipe.isConversion()) {
                                this.stopRitual(true);
                            } else {
                                if (this.getConvertEntity != null){
                                    this.stopRitual(true);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            }
                        }

                        int totalTime = 60;

                        if (!RitualRequirements.getProperStructure(recipe.getCraftType(), this.castingPlayer, this, this.worldPosition, this.level)){
                            ++this.structureTime;
                            if (this.structureTime >= totalTime) {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.structure.fail"), true);
                                this.stopRitual(false);
                            }
                        } else {
                            this.structureTime = 0;
                        }
                        if (recipe.isConversion()){
                            if (RitualRequirements.noConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level)){
                                ++this.convertTime;
                                if (this.getConvertEntity != null){
                                    this.getConvertEntity = null;
                                }
                                if (this.convertTime >= totalTime) {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            } else {
                                this.getConvertEntity = RitualRequirements.getConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level);
                                this.convertTime = 0;
                            }
                        }
                    } else {
                        if (this.level.getGameTime() % 20 == 0) {
                            ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);
                        }
                    }
                }
            } else {
                this.stopRitual(false);
            }
        } else {
            this.stopRitual(false);
        }
        this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(DarkAltarBlock.LIT, flag), 3);
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        var stack = player.getItemInHand(hand);

        if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").canPlayerUse(player))
            return InteractionResultHolder.pass(stack);

        var radius = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatData("distance").getValue();

        var eyePos = player.getEyePosition();
        var lookAngle = player.getLookAngle().normalize();

        var destination = eyePos.add(lookAngle.scale(radius));

        var hit = level.clip(new ClipContext(eyePos, destination, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));

        var impulse = Vec3.ZERO;

        var charge = this.getCharge(player, stack);

        if (charge <= 0)
            return InteractionResultHolder.pass(stack);

        if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("ascent").isEnabled()
                && hit.getType() == HitResult.Type.BLOCK && hit.getLocation().distanceTo(eyePos) <= radius) {
            var current = hit.getBlockPos();

            var maxUp = (int) Math.floor(radius - eyePos.distanceTo(hit.getLocation()));

            BlockPos feetPos = null;

            for (int i = 1; i <= maxUp && current.getY() + i < level.getMaxBuildHeight(); i++) {
                var feet = current.above(i);
                var head = feet.above();

                if (level.isEmptyBlock(feet) && level.isEmptyBlock(head)) {
                    feetPos = feet;

                    break;
                }
            }

            if (feetPos != null)
                destination = feetPos.getBottomCenter();
            else
                destination = hit.getLocation().subtract(lookAngle.scale(0.5));
        } else {
            destination = hit.getLocation();

            if (!level.getBlockState(hit.getBlockPos().below()).blocksMotion())
                destination = destination.add(0, -1, 0);

            var extra = Math.min(player.getKnownMovement().length(), 5);

            impulse = lookAngle.scale(1.25 + extra);
        }

        var random = level.getRandom();

        var shift = player.getBbHeight() / 2F;
        var from = player.position().add(0F, shift, 0F);
        var to = destination.add(0F, shift, 0F);

        level.playSound(player, new BlockPos((int) from.x(), (int) from.y(), (int) from.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);
        level.playSound(player, new BlockPos((int) to.x(), (int) to.y(), (int) to.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);

        if (!level.isClientSide) {
            ServerScheduler.schedule(1, () -> {
                var direction = to.subtract(from);
                var dist = Math.max(0.001, direction.length());

                var forward = direction.scale(1.0 / dist);
                var up = Math.abs(forward.y) < 0.99 ? new Vec3(0, 1, 0) : new Vec3(1, 0, 0);
                var right = forward.cross(up).normalize();
                var binormal = forward.cross(right).normalize();

                var pointCount = (int) Math.round(dist);
                var points = new Vec3[pointCount];

                for (int i = 0; i < pointCount; i++) {
                    var t = i / (float) (pointCount - 1);

                    var base = new Vec3(Mth.lerp(t, from.x, to.x), Mth.lerp(t, from.y, to.y), Mth.lerp(t, from.z, to.z));
                    var wobble = 1F + 0.5F * (float) Math.sin(t * Math.PI);

                    var ox = (random.nextFloat() - 0.5F) * wobble;
                    var oy = (random.nextFloat() - 0.5F) * wobble;

                    points[i] = base.add(right.scale(ox)).add(binormal.scale(oy));
                }

                var segments = 12;

                for (int i = 0; i < pointCount - 1; i++) {
                    var p0 = points[i];
                    var p1 = points[i + 1];

                    for (int s = 0; s <= segments; s++) {
                        var t = s / (float) segments;

                        var px = Mth.lerp(t, p0.x, p1.x);
                        var py = Mth.lerp(t, p0.y, p1.y);
                        var pz = Mth.lerp(t, p0.z, p1.z);

                        if (level instanceof ServerLevel serverLevel)
                            serverLevel.sendParticles(ParticleUtils.constructSimpleSpark(FlawlessUtils.getColor(player, stack, new Color(155 + random.nextInt(100), 80, 255)), 1F, 3, 0.5F), px, py, pz, 1, 0, 0, 0, 0);
                    }
                }
            });

            if (player instanceof ServerPlayer serverPlayer) {
                serverPlayer.teleportTo((ServerLevel) level, destination.x, destination.y, destination.z, player.getYRot(), player.getXRot());

                serverPlayer.fallDistance = 0;

                NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), impulse.toVector3f()), serverPlayer);

                var finalImpulse = impulse;

                ServerScheduler.schedule(1, () -> NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), finalImpulse.toVector3f()), serverPlayer));

                this.addCharge(player, stack, -1);

                this.getRelicData(player, stack).getLevelingData().addExperience("blink", "blink", 1);

                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("blinks_amount").addValue(1);
                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("distance_traveled").addValue(from.distanceTo(to));

                if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("safe_fall").isEnabled())
                    this.setSafeFall(stack, true);

                if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("flicker").isEnabled()) {
                    for (var mob : level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(32))) {
                        if (mob.getTarget() == player) {
                            mob.setTarget(null);

                            this.getRelicData(player, stack).getLevelingData().addExperience("blink", "flicker", 1);

                            this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("targets").addValue(1);
                        }
                    }
                }
            }
        } else {
            if (impulse == Vec3.ZERO)
                ShakeManager.add(level, Shake.builder(player)
                        .radius(Integer.MAX_VALUE)
                        .amplitude(0.2F)
                        .duration(5)
                        .build());
            else
                ShakeManager.add(level, Shake.builder(player)
                        .radius(Integer.MAX_VALUE)
                        .amplitude(0)
                        .fovAmplitude(0.35F)
                        .duration(10)
                        .speed(2)
                        .build());

            ChromaticAberrationManager.add(level, ChromaticAberration.builder(player)
                    .radius(Integer.MAX_VALUE)
                    .strength(0.075F)
                    .duration(10)
                    .build());
        }
        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }

private static void onInteract(LivingEntity entity) {
            if (entity.getCommandSenderWorld().isClientSide())
                return;

            for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.MIDNIGHT_MANTLE.get())) {
                var relic = (MidnightMantleItem) stack.getItem();

                if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").canPlayerUse(entity))
                    continue;

                ServerScheduler.schedule(1, () -> relic.setInvisibilityCooldown(stack, (int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("invisibility").getStatData("cooldown").getValue() * 20)));
            }
        }

public static void jankItemsDelayed(ServerLevel level, BlockPos target, int effectLevel, float efficiency, Entity entity) {
        ServerScheduler.schedule(0, () -> jankItems(level, target, effectLevel, efficiency, entity));
    }

protected IState tryAttack()
    {
        if (!checkForTarget() || !canAttack())
        {
            return CombatAIStates.NO_TARGET;
        }

        if (nextAttackTime >= user.level.getGameTime() || !isInDistanceForAttack(target))
        {
            return null;
        }

        if (user.getSensing().hasLineOfSight(target))
        {
            pathAttempts = 0;
            user.getLookControl().setLookAt(target);
            doAttack(target);
            nextAttackTime = user.level.getGameTime() + getAttackDelay();
        }

        return null;
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceToSqr(target) < RANGED_FLEE_SQDIST)
        {
            if (user.getRandom().nextInt(FLEE_CHANCE) == 0 &&
                  !((AbstractBuildingGuards) user.getCitizenData().getWorkBuilding()).getTask().equals(GuardTaskSetting.GUARD))
            {
                EntityNavigationUtils.walkAwayFrom(user, target.blockPosition(), (int) (getAttackDistance() / 2.0), getCombatMovementSpeed());
            }
        }
        else
        {
            user.getNavigation().stop();
        }

        user.swing(InteractionHand.MAIN_HAND);

        final int level = user.getCitizenData().getCitizenSkillHandler().getLevel(ModGuardTypes.druid.get().getSecondarySkill());
        final int time = user.getCitizenData().getCitizenSkillHandler().getLevel(ModGuardTypes.druid.get().getPrimarySkill()) * 20;

        final float inaccuracy = 99f / level;
        final MobEffect effect;
        final ItemStack stack = new ItemStack(Items.SPLASH_POTION);
        boolean gotMaterial = false;
        BiPredicate<LivingEntity, MobEffect> predicate;
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DRUID_USE_POTIONS) > 0
              && InventoryUtils.hasItemInItemHandler(user.getInventoryCitizen(), item -> item.getItem() == ModItems.magicpotion))
        {
            gotMaterial = true;
        }
        if (AbstractEntityAIGuard.isAttackableTarget(user, target))
        {
            effect = ADVERSE_EFFECTS.get(user.getRandom().nextInt(gotMaterial ? 2 : 1));
            predicate = (entity, eff) -> AbstractEntityAIGuard.isAttackableTarget(user, entity);
        }
        else
        {
            effect = SUPPORT_EFFECTS.get(user.getRandom().nextInt(gotMaterial ? 4 : 1));
            predicate = (entity, eff) -> !AbstractEntityAIGuard.isAttackableTarget(user, entity);
        }

        PotionUtils.setCustomEffects(stack, Collections.singleton(new MobEffectInstance(effect, time, gotMaterial ? 2 : 0)));
        DruidPotionEntity.throwPotionAt(stack, target, user, user.getCommandSenderWorld(), POTION_VELOCITY, inaccuracy, predicate);

        if (gotMaterial)
        {
            InventoryUtils.removeStackFromItemHandler(user.getCitizenData().getInventory(), new ItemStack(ModItems.magicpotion, 1), 1);
        }

        this.instantEffect = effect.isInstantenous();

        user.setItemInHand(InteractionHand.MAIN_HAND, stack);

        user.getThreatTable().removeCurrentTarget();

        user.getCitizenExperienceHandler().addExperience(PER_POTION_XP);
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceToSqr(target) < RANGED_FLEE_SQDIST)
        {
            if (user.getRandom().nextInt(FLEE_CHANCE) == 0 &&
                  !((AbstractBuildingGuards) user.getCitizenData().getWorkBuilding()).getTask().equals(GuardTaskSetting.GUARD))
            {
                EntityNavigationUtils.walkAwayFrom(user, target.blockPosition(), (int) (getAttackDistance() / 2.0), getCombatMovementSpeed());
            }
        }
        else
        {
            user.getNavigation().stop();
        }

        user.getCitizenData().setVisibleStatus(ARCHER_COMBAT);
        user.swing(InteractionHand.MAIN_HAND);
        user.stopUsingItem();

        int amountOfArrows = 1;
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DOUBLE_ARROWS) > 0)
        {
            if (user.getRandom().nextDouble() < user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(DOUBLE_ARROWS))
            {
                amountOfArrows++;
            }
        }

        for (int i = 0; i < amountOfArrows; i++)
        {
            final AbstractArrow arrow = CombatUtils.createArrowForShooter(user);

            if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(ARROW_PIERCE) > 0)
            {
                arrow.setPierceLevel((byte) 2);
            }

            // Add bow enchant effects: Knocback and fire
            final ItemStack bow = user.getItemInHand(InteractionHand.MAIN_HAND);

            if (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FLAMING_ARROWS, bow) > 0)
            {
                arrow.setSecondsOnFire(5);
            }
            final int k = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.PUNCH_ARROWS, bow);
            if (k > 0)
            {
                arrow.setKnockback(k);
            }

            double damage = calculateDamage(arrow);
            if (isMarksman())
            {
                arrow.setShotFromCrossbow(true);
            }
            arrow.setBaseDamage(damage);

            final float chance = HIT_CHANCE_DIVIDER / (user.getCitizenData().getCitizenSkillHandler().getLevel(Skill.Adaptability) + 1);
            CombatUtils.shootArrow(arrow, target, chance);
            user.playSound(SoundEvents.SKELETON_SHOOT, (float) BASIC_VOLUME, (float) SoundUtils.getRandomPitch(user.getRandom()));
        }

        target.setLastHurtByMob(user);
        CitizenItemUtils.damageItemInHand(user, InteractionHand.MAIN_HAND, 1);
        user.stopUsingItem();
    }

@Override
    protected void doAttack(final LivingEntity target)
    {
        if (user.distanceTo(target) > 1)
        {
            moveInAttackPosition(target);
        }

        user.swing(InteractionHand.MAIN_HAND);
        user.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, (float) BASIC_VOLUME, (float) SoundUtils.getRandomPitch(user.getRandom()));

        final double damageToBeDealt = getAttackDamage();
        DamageSource source = target.level.damageSources().source(DamageSourceKeys.GUARD, user);
        if (MineColonies.getConfig().getServer().pvp_mode.get() && target instanceof Player)
        {
            source = target.level.damageSources().source(DamageSourceKeys.GUARD_PVP, user);
        }

        final int fireLevel = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.FIRE_ASPECT, user.getItemInHand(InteractionHand.MAIN_HAND));
        if (fireLevel > 0)
        {
            target.setSecondsOnFire(fireLevel * 4);
        }

        if (user.level.getGameTime() - lastAoeUseTime > KNOCKBACK_COOLDOWN)
        {
            doAoeAttack(source, damageToBeDealt);
        }

        if (isHuscarl())
        {
            double share = (50 + user.getCitizenData().getCitizenSkillHandler().getLevel(Skill.Adaptability) / 2.0) / 100.0;
            target.hurt(target.level.damageSources().source(DamageSourceKeys.PIERCE, user), (float) damageToBeDealt * (float) share);
            target.hurt(source, (float) damageToBeDealt * (float) (1.0 - share));
        }
        else
        {
            target.hurt(source, (float) damageToBeDealt);
        }

        target.setLastHurtByMob(user);

        if (target instanceof Mob && user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(KNIGHT_TAUNT) > 0)
        {
            ((Mob) target).setTarget(user);
            if (target instanceof IThreatTableEntity)
            {
                ((IThreatTableEntity) target).getThreatTable().addThreat(user, 5);
            }
        }

        user.stopUsingItem();
        user.getCitizenData().setVisibleStatus(getCombatStatus());
        CitizenItemUtils.damageItemInHand(user, InteractionHand.MAIN_HAND, 1);
    }

private void doAoeAttack(final DamageSource source, final double damageToBeDealt)
    {
        if (user.getCitizenColonyHandler().getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(KNIGHT_WHIRLWIND) > 0
              && user.getRandom().nextInt(KNOCKBACK_CHANCE) == 0)
        {
            List<LivingEntity> entities = user.level.getEntitiesOfClass(LivingEntity.class, user.getBoundingBox().inflate(2.0D, 0.5D, 2.0D));
            for (LivingEntity livingentity : entities)
            {
                if (livingentity != user && isEntityValidTarget(livingentity) && (!(livingentity instanceof ArmorStand)))
                {
                    livingentity.knockback(
                      2F,
                      Mth.sin(livingentity.getYRot() * ((float) Math.PI)),
                      (-Mth.cos(livingentity.getYRot() * ((float) Math.PI))));
                    livingentity.hurt(source, (float) (damageToBeDealt / entities.size()));
                }
            }

            user.level.playSound(null,
              user.getX(),
              user.getY(),
              user.getZ(),
              SoundEvents.PLAYER_ATTACK_SWEEP,
              user.getSoundSource(),
              1.0F,
              1.0F);

            double d0 = (double) (-Mth.sin(user.getYRot() * ((float) Math.PI / 180)));
            double d1 = (double) Mth.cos(user.getYRot() * ((float) Math.PI / 180));
            if (user.level instanceof ServerLevel)
            {
                ((ServerLevel) user.level).sendParticles(ParticleTypes.SWEEP_ATTACK,
                  user.getX() + d0,
                  user.getY(0.5D),
                  user.getZ() + d1,
                  2,
                  d0,
                  0.0D,
                  d1,
                  0.0D);
            }

            lastAoeUseTime = user.level.getGameTime();
        }
    }

private boolean handleDamagePerformed(@NotNull final DamageSource damageSource, final float damage, final Entity sourceEntity)
    {
        float damageInc = Math.min(damage, (getMaxHealth() * 0.2f));

        //If we are in simulation, don't cap damage
        if (citizenJobHandler.getColonyJob() instanceof JobNetherWorker && citizenData != null && damageSource.typeHolder().is(DamageSourceKeys.NETHER))
        {
            damageInc = damage;
        }

        // For cavalry, allocate some of the damage to the horse.
        if (citizenJobHandler.getColonyJob() instanceof JobCavalry cav && citizenData != null)
        {
            final Entity mount = this.getVehicle();
            if (mount instanceof ICitizenJobMount)
            {
                float horseSplit = cav.getMountDamageSplit() * damageInc;
                damageInc = damageInc - horseSplit;

                mount.hurt(damageSource, horseSplit);
            }
        }

        if (!level.isClientSide && !this.isInvisible() && !damageSource.typeHolder().is(DamageTypes.FALL))
        {
            performMoveAway(sourceEntity);
        }
        setLastHurtMob(damageSource.getEntity());

        if (!level.isClientSide)
        {
            if (citizenJobHandler.getColonyJob() instanceof AbstractJobGuard && citizenData != null)
            {
                if (citizenJobHandler.getColonyJob() instanceof JobKnight)
                {
                    if (citizenColonyHandler.getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(BLOCK_ATTACKS) > 0)
                    {
                        if (getRandom().nextDouble() < citizenColonyHandler.getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(BLOCK_ATTACKS))
                        {
                            return false;
                        }
                    }
                }

                if (citizenData.getWorkBuilding() instanceof AbstractBuildingGuards && ((AbstractBuildingGuards) citizenData.getWorkBuilding()).shallRetrieveOnLowHealth()
                      && getHealth() < ((int) getMaxHealth() * 0.2D))
                {
                    damageInc *= 1 - citizenColonyHandler.getColonyOrRegister().getResearchManager().getResearchEffects().getEffectStrength(FLEEING_DAMAGE);
                }
            }
        }

        if (!super.hurt(damageSource, damageInc))
        {
            return false;
        }

        if (damageSource.getEntity() instanceof LivingEntity)
        {
            threatTable.addThreat((LivingEntity) damageSource.getEntity(), (int) damageInc);
        }

        if (damageSource.is(DamageTypeTags.IS_FIRE) || damageSource.is(DamageTypeTags.IS_LIGHTNING))
        {
            return true;
        }

        if (!level.isClientSide)
        {
            CitizenItemUtils.updateArmorDamage(this, damageInc);
            if (citizenData != null)
            {
                getCitizenData().getCitizenHappinessHandler().addModifier(new ExpirationBasedHappinessModifier(DAMAGE, 2.0, new StaticHappinessSupplier(0.0), 1));
            }
        }

        return true;
    }

@Override
    public boolean tryAttack(Entity target) {
        if (this.isKicking()) {
            ((LivingEntity) target).takeKnockback(1.0F, MathHelper.sin(this.getYaw() * ((float) Math.PI / 180F)), (-MathHelper.cos(this.getYaw() * ((float) Math.PI / 180F))));
            this.kickTicks = 10;
            getWorld().sendEntityStatus(this, (byte) 4);
            this.lookAtEntity(target, 90.0F, 90.0F);
        }
        ItemStack hand = this.getMainHandStack();
        hand.damage(1, this, (entity) -> entity.sendEquipmentBreakStatus(EquipmentSlot.MAINHAND));
        return super.tryAttack(target);
    }

@Override
    public void attack(LivingEntity target, float pullProgress) {
        this.shieldCoolDown = 8;
        if (this.getMainHandStack().getItem() instanceof CrossbowItem)
            this.shoot(this, 6.0F);
        if (this.getMainHandStack().getItem() instanceof BowItem) {
            ItemStack itemStack = this.getProjectileType(this.getStackInHand(ProjectileUtil.getHandPossiblyHolding(this, Items.BOW)));
            ItemStack hand = this.getActiveItem();
            PersistentProjectileEntity persistentProjectileEntity = ProjectileUtil.createArrowProjectile(this, itemStack, pullProgress);
            int powerLevel = EnchantmentHelper.getLevel(Enchantments.POWER, itemStack);
            if (powerLevel > 0) {
                persistentProjectileEntity.setDamage(persistentProjectileEntity.getDamage() + (double) powerLevel * 0.5D + 0.5D);
            }
            int punchLevel = EnchantmentHelper.getLevel(Enchantments.PUNCH, itemStack);
            if (punchLevel > 0) {
                persistentProjectileEntity.setPunch(punchLevel);
            }
            if (EnchantmentHelper.getLevel(Enchantments.FLAME, itemStack) > 0)
                persistentProjectileEntity.setFireTicks(100);
            double d = target.getX() - this.getX();
            double e = target.getBodyY(0.3333333333333333D) - persistentProjectileEntity.getY();
            double f = target.getZ() - this.getZ();
            double g = Math.sqrt(d * d + f * f);
            persistentProjectileEntity.setVelocity(d, e + g * 0.20000000298023224D, f, 1.6F, (float) (14 - this.getWorld().getDifficulty().getId() * 4));
            this.playSound(SoundEvents.ENTITY_SKELETON_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
            this.getWorld().spawnEntity(persistentProjectileEntity);
            hand.damage(1, this, (entity) -> entity.sendEquipmentBreakStatus(EquipmentSlot.MAINHAND));
        }
    }

@Override
    public void tick() {
        LivingEntity livingentity = this.mob.getTarget();
        if (livingentity != null) {
            boolean canSee = this.mob.getVisibilityCache().canSee(livingentity);
            boolean hasSeenEntityRecently = this.seeTime > 0;
            if (canSee != hasSeenEntityRecently) {
                this.seeTime = 0;
            }
            if (canSee) {
                ++this.seeTime;
            } else {
                --this.seeTime;
            }
            double d0 = this.mob.squaredDistanceTo(livingentity);
            double d1 = livingentity.distanceTo(this.mob);
            if (d1 <= 4.0D) {
                this.mob.getMoveControl().strafeTo(this.mob.isUsingItem() ? -0.5F : -3.0F, 0.0F);
                this.mob.lookAtEntity(livingentity, 30.0F, 30.0F);
            }
            if (this.mob.getRandom().nextInt(50) == 0) {
                if (this.mob.isInPose(EntityPose.STANDING))
                    this.mob.setPose(EntityPose.CROUCHING);
                else
                    this.mob.setPose(EntityPose.STANDING);
            }
            boolean canSee2 = (d0 > (double) this.attackRadiusSqr || this.seeTime < 5) && this.attackDelay == 0;
            if (canSee2) {
                --this.updatePathDelay;
                if (this.updatePathDelay <= 0) {
                    this.mob.getNavigation().startMovingTo(livingentity, this.canRun() ? this.speedModifier : this.speedModifier * 0.5D);
                    this.updatePathDelay = PATHFINDING_DELAY_RANGE.get(this.mob.getRandom());
                }
            } else {
                this.updatePathDelay = 0;
                this.mob.getNavigation().stop();
            }
            this.mob.lookAtEntity(livingentity, 30.0F, 30.0F);
            this.mob.getLookControl().lookAt(livingentity, 30.0F, 30.0F);
            if (this.friendlyInLineOfSight() && GuardVillagersConfig.friendlyFire)
                this.crossbowState = CrossbowState.FIND_NEW_POSITION;
            if (this.crossbowState == CrossbowState.FIND_NEW_POSITION && GuardVillagersConfig.friendlyFire) {
                this.mob.stopUsingItem();
                this.mob.setCharging(false);
                if (this.findPosition())
                    this.mob.getNavigation().startMovingTo(this.wantedX, this.wantedY, this.wantedZ, this.mob.isSneaking() ? 0.5F : 1.2D);
                this.crossbowState = CrossbowState.UNCHARGED;
            } else if (this.crossbowState == CrossbowState.UNCHARGED) {
                if (hasSeenEntityRecently) {
                    this.mob.setCurrentHand(GuardVillagers.getHandWith(this.mob, item -> item instanceof CrossbowItem));
                    this.crossbowState = CrossbowState.CHARGING;
                    this.mob.setCharging(true);
                }
            } else if (this.crossbowState == CrossbowState.CHARGING) {
                if (!this.mob.isUsingItem()) {
                    this.crossbowState = CrossbowState.UNCHARGED;
                }
                int i = this.mob.getItemUseTime();
                ItemStack itemstack = this.mob.getActiveItem();
                if (i >= CrossbowItem.getPullTime(itemstack) || CrossbowItem.isCharged(itemstack)) {
                    this.mob.stopUsingItem();
                    this.crossbowState = CrossbowState.CHARGED;
                    this.attackDelay = 10 + this.mob.getRandom().nextInt(5);
                    this.mob.setCharging(false);
                }
            } else if (this.crossbowState == CrossbowState.CHARGED) {
                --this.attackDelay;
                if (this.attackDelay == 0) {
                    this.crossbowState = CrossbowState.READY_TO_ATTACK;
                }
            } else if (this.crossbowState == CrossbowState.READY_TO_ATTACK && canSee) {
                this.mob.attack(livingentity, 1.0F);
                ItemStack itemstack1 = this.mob.getStackInHand(GuardVillagers.getHandWith(this.mob, item -> item instanceof CrossbowItem));
                CrossbowItem.setCharged(itemstack1, false);
                this.crossbowState = CrossbowState.UNCHARGED;
            }
        }

    }

@SubscribeEvent
    public void onLivingHurt(LivingHurtEvent event) {
        if(event.getEntity().getCommandSenderWorld().isClientSide()) return;

        if (Main.isMusketModLoaded) {
            Entity sourceEntity = event.getSource().getEntity();
            if (sourceEntity instanceof AbstractRecruitEntity owner && IWeapon.isMusketModWeapon(owner.getMainHandItem())) {
                Entity target = event.getEntity();
                if (target instanceof LivingEntity impactEntity) {

                    if (!canAttack(owner, impactEntity)) {
                        event.setCanceled(true);
                    } else {
                        owner.addXp(2);
                        owner.checkLevel();
                    }
                }
            }
        }

        Entity target = event.getEntity();
        Entity source = event.getSource().getEntity();
        if (source instanceof LivingEntity sourceEntity) {
            alertTeam(target, sourceEntity);
        }
    }

public boolean doHurtTarget(@NotNull Entity entity) {
        float f = (float)this.getAttributeValue(Attributes.ATTACK_DAMAGE);
        if (entity instanceof LivingEntity) {
            f += EnchantmentHelper.getDamageBonus(this.getMainHandItem(), ((LivingEntity)entity).getMobType());
        }

        int i = EnchantmentHelper.getFireAspect(this);
        if (i > 0) {
            entity.setSecondsOnFire(i * 4);
        }

        boolean flag = entity.hurt(this.damageSources().mobAttack(this), f);
        if (flag) {

            this.doEnchantDamageEffects(this, entity);
            this.setLastHurtMob(entity);
        }
        this.addXp(1);
        if(this.getHunger() > 0) this.setHunger(this.getHunger() - 0.1F);
        this.checkLevel();
        if(this.getMorale() < 100) this.setMoral(this.getMorale() + 0.25F);
        this.damageMainHandItem();
        return true;
    }

public void tick() {
        if(target != null && target.isAlive()) {
            double distance = target.distanceToSqr(this.crossBowman);
            boolean isClose = distance <= 150;
            boolean isFar = distance >= 3500;
            boolean isTooFar = distance >= 4500;
            boolean inRange =  !isFar;
            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);

            if (canSee) {
                ++this.seeTime;
            } else {
                this.seeTime = 0;
            }

            if(isTooFar){
                this.crossBowman.setTarget(null);
                this.stop();
                return;
            }

            // movement
            if (crossBowman.getShouldFollow() && crossBowman.getOwner() != null) {
                handleFollow(this.crossBowman.getOwner(), inRange, isFar);
            }
            else if(crossBowman.getShouldHoldPos() && crossBowman.getHoldPos() != null){
                handleHoldPos(crossBowman.getHoldPos(), inRange);
            }
            else {
                handleWander(inRange, isFar, isClose);
            }
        }

        //WEAPON HANDLING
        if(isWeaponInMainHand()) {
            if(crossBowman.getShouldStrategicFire() && target == null) {
                BlockPos pos = crossBowman.getStrategicFirePos();
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (pos != null) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }

                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (pos != null) {
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(pos.getX(), pos.getY(), pos.getZ());

                            if (++this.seeTime > weapon.getWeaponLoadTime()) {
                                this.state = State.SHOOT;
                                this.seeTime = 0;
                            }
                        }
                    }

                    case SHOOT -> {
                        if (pos != null) {
                            this.weapon.performRangedAttackIWeapon(this.crossBowman, pos.getX(), pos.getY(), pos.getZ(), weapon.getProjectileSpeed());
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE; //RESUPPLY
                    }
                }
            }
            else {
                switch (state) {
                    case IDLE -> {
                        if (weapon.isLoaded(crossBowman.getMainHandItem())) {
                            if (target != null && target.isAlive()) {
                                this.state = State.AIMING;
                            }
                        } else if(hasArrows()) this.state = State.RELOAD;
                    }
                    case RELOAD -> {
                        this.crossBowman.startUsingItem(InteractionHand.MAIN_HAND);

                        int i = this.crossBowman.getTicksUsingItem();
                        if (i >= weapon.getWeaponLoadTime()) {
                            this.crossBowman.releaseUsingItem();
                            this.crossBowman.playSound(this.weapon.getLoadSound(), 1.0F, 1.0F / (crossBowman.getRandom().nextFloat() * 0.4F + 0.8F));
                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), true);

                            this.state = State.AIMING;
                        }
                    }

                    case AIMING -> {
                        if (target != null && target.isAlive()) {
                            boolean canSee = this.crossBowman.getSensing().hasLineOfSight(target);
                            this.crossBowman.setAggressive(true);
                            this.crossBowman.getLookControl().setLookAt(target);

                            if (canSee) {
                                if (++this.seeTime >= weapon.getWeaponLoadTime()) {
                                    this.state = State.SHOOT;
                                    this.seeTime = 0;
                                }
                            } else if (crossBowman.getShouldHoldPos()) {
                                this.crossBowman.setTarget(null);
                            }
                        } else {
                            this.crossBowman.setAggressive(false);
                            seeTime = 0;
                        }
                    }

                    case SHOOT -> {
                        LivingEntity savedTarget = null;
                        if (target != null && target.isAlive() && this.crossBowman.canAttack(target) && this.crossBowman.getState() != 3) {
                            this.crossBowman.getLookControl().setLookAt(target);

                            if(AttackUtil.canPerformHorseAttack(this.crossBowman, target)){
                                if(target.getVehicle() instanceof LivingEntity) {
                                    savedTarget = target;
                                    target = (LivingEntity) target.getVehicle();
                                }
                            }

                            this.weapon.performRangedAttackIWeapon(this.crossBowman, target.getX(), target.getY() + target.getEyeHeight(), target.getZ(), weapon.getProjectileSpeed());

                            if(savedTarget != null){
                                target = savedTarget;
                            }

                            CrossbowItem.setCharged(this.crossBowman.getMainHandItem(), false);
                        }
                        this.state = State.IDLE;
                    }
                }
            }
        }
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        this.lastHitTime = MathHelper.secondsToTicks(15);

        if (pAmount >= 15){
            this.overwhelmed = MathHelper.secondsToTicks(15);
        }

        if (this.getHealth() <= 10.0F){
            if (pSource.is(DamageTypeTags.IS_EXPLOSION)){
                return false;
            }
        }

        if (!pSource.is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !pSource.is(DamageTypes.THORNS) && pSource.getEntity() instanceof LivingEntity livingentity && livingentity != this) {
            float thorn = 2.0F;
            if (this.level.getDifficulty() == Difficulty.HARD){
                thorn *= 2.0F;
            }
            livingentity.hurt(this.damageSources().thorns(this), thorn);
        }

        return super.hurt(pSource, pAmount);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        if (!this.level().isClientSide && !this.isRemoved()) {
            if (pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                this.kill();
                return false;
            }
            else if (!this.isInvulnerableTo(pSource) && !this.isLocked()) {
                if (pSource.is(DamageTypeTags.IS_EXPLOSION)) {
                    this.broken(pSource);
                    this.kill();
                    return false;
                }
                else {
                    boolean flag = pSource.getDirectEntity() instanceof AbstractArrow;
                    boolean flag1 = flag && ((AbstractArrow)pSource.getDirectEntity()).getPierceLevel() > 0;
                    boolean flag2 = "player".equals(pSource.getMsgId());
                    if (!flag2 && !flag) {
                        return false;
                    }
                    else {
                        Entity entity = pSource.getEntity();
                        if (entity instanceof Player) {
                            Player player = (Player)entity;
                            if (!player.getAbilities().mayBuild) {
                                return false;
                            }
                        }

                        if (pSource.isCreativePlayer()) {
                            this.playBrokenSound();
                            this.showBreakingParticles();
                            this.kill();
                            return flag1;
                        }
                        else {
                            long i = this.level().getGameTime();
                            if (i - this.lastHit > 5L && !flag) {
                                this.level().broadcastEntityEvent(this, (byte)32);
                                this.gameEvent(GameEvent.ENTITY_DAMAGE, pSource.getEntity());
                                this.lastHit = i;
                            }
                            else {
                                this.broken(pSource);
                                this.showBreakingParticles();
                                this.kill();
                            }
                            return true;
                        }
                    }
                }
            }
            else {
                return false;
            }
        }
        else {
            return false;
        }
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        if (!this.level().isClientSide && !this.isRemoved()) {
            if (pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                this.discard();
                return false;
            } else if (!this.isInvulnerableTo(pSource) && !this.invisible) {
                if (pSource.is(DamageTypeTags.IS_EXPLOSION)) {
                    this.discard();
                    return false;

                    //todo change to custom tag
                } else if (pSource.is(DamageTypeTags.IGNITES_ARMOR_STANDS)) {
