public void directFromPlayer(float rotationYaw, float rotationPitch, boolean loadChunk, Entity over) {
        final Entity owner = this.getOwner();
        if (owner != null && this.distanceTo(owner) > 150) {
            returnControlTime = 100;
        }
        if (Math.abs(xo - this.getX()) > 0.1F || Math.abs(yo - this.getY()) > 0.1F || Math.abs(zo - this.getZ()) > 0.1F) {
            stillTicksCounter = 0;
        } else {
            stillTicksCounter++;
        }
        int stillTPthreshold = AMConfig.falconryTeleportsBack ? 200 : 6000;
        this.setOrderedToSit(false);
        this.setLaunched(true);
        if (owner != null && (returnControlTime > 0 && AMConfig.falconryTeleportsBack || stillTicksCounter > stillTPthreshold && this.distanceTo(owner) > 30)) {
            this.copyPosition(owner);
            returnControlTime = 0;
            stillTicksCounter = 0;
            launchTime = Math.max(launchTime, 12000);
        }
        if (!this.level().isClientSide) {
            if (returnControlTime > 0 && owner != null) {
                this.getLookControl().setLookAt(owner, 30, 30);
            } else {
                this.yBodyRot = rotationYaw;
                this.setYRot(rotationYaw);
                this.yHeadRot = rotationYaw;
                this.setXRot(rotationPitch);
            }
            if (rotationPitch < 10 && this.onGround()) {
                this.setFlying(true);
            }
            final float yawOffset = rotationYaw + 90;
            final float rad = 3F;
            final float speed = 1.2F;
            if (returnControlTime > 0) {
                this.getMoveControl().setWantedPosition(owner.getX(), owner.getY() + 10, owner.getZ(), speed);
            } else {
                this.getMoveControl().setWantedPosition(this.getX() + rad * 1.5F * Math.cos(yawOffset * Mth.DEG_TO_RAD), this.getY() - rad * Math.sin(rotationPitch * Mth.DEG_TO_RAD), this.getZ() + rad * Math.sin(yawOffset * Mth.DEG_TO_RAD), speed);
            }
            if (loadChunk) {
                loadChunkOnServer(this.blockPosition());
            }
            this.setLastHurtByMob(null);
            this.setTarget(null);
            if (over == null) {
                final List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(3.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR);
                Entity closest = null;
                for (final Entity e : list) {
                    if (closest == null || this.distanceTo(e) < this.distanceTo(closest)) {
                        closest = e;
                    }
                }
                over = closest;
            }
        }
        if (over != null && over != owner && !this.isAlliedTo(over) && canFalconryAttack(over)) {
            if (tackleCapCooldown == 0 && this.distanceTo(over) <= over.getBbWidth() + 4D) {
                this.setTackling(true);
                if (this.distanceTo(over) <= over.getBbWidth() + 2D) {
                    final float speedDamage = (float) Math.ceil(Mth.clamp(this.getDeltaMovement().length() + 0.2, 0, 1.2D) * 3.333);
                    over.hurt(this.damageSources().mobAttack(this), 5 + speedDamage + random.nextInt(2));
                    tackleCapCooldown = 22;
                }
            }
        }
        this.lastPlayerControlTime = 10;
        this.controlledFlag = true;
    }

@Override
	public void aiStep() {
		super.aiStep();
		this.eatTicks++;

		if (this.dropEatingLootCooldown > 0) this.dropEatingLootCooldown--;

		if (!this.isInWater() && this.onGround() && this.verticalCollision) {
			this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.05F, 0.4F, (this.random.nextFloat() * 2.0F - 1.0F) * 0.05F));
			this.setOnGround(false);
			this.hasImpulse = true;
			this.playSound(this.getFlopSound(), this.getSoundVolume(), this.getVoicePitch());
		}

		if (this.level().getGameTime() % 20 == 0) {
			LivingEntity caughtEntity = this.getCaughtEntity();
			if (caughtEntity != null && (!this.isPickerelweedNearby() || this.isHidingInPickerelweed())) {
				this.level().playSound(null, this.blockPosition(), UASoundEvents.PIKE_BITE.get(), SoundSource.HOSTILE, 0.8F, 0.90F);
				if (this.level().isClientSide && caughtEntity.getHealth() <= 1 && this.getVariant().is(UAPikeVariants.SPECTRAL)) {
					for (int i = 0; i < 3; ++i) {
						this.level().addParticle(UAParticleTypes.SPECTRAL_CONSUME.get(), caughtEntity.getX() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), caughtEntity.getY() + caughtEntity.getRandom().nextDouble() * (double) caughtEntity.getBbHeight() - 0.25D, caughtEntity.getZ() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), (this.getCaughtEntity().getRandom().nextDouble() - 0.5D) * 2.0D, -caughtEntity.getRandom().nextDouble(), (caughtEntity.getRandom().nextDouble() - 0.5D) * 2.0D);
					}
				}
				caughtEntity.hurt(this.damageSources().mobAttack(this), 1.0F);
			}
		}

		if (this.getAttackCooldown() > 0) {
			this.setAttackCooldown(this.getAttackCooldown() - 1);
		}

		ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
		if (!this.level().isClientSide && this.isAlive() && this.isEffectiveAi() && !itemstack.isEmpty() && this.canEatItem(itemstack) && this.isInWater()) {
			if (this.eatTicks > 600) {
				ItemStack itemstackFood = itemstack.finishUsingItem(this.level(), this);
				if (!itemstack.isEmpty()) {
					this.setItemSlot(EquipmentSlot.MAINHAND, itemstackFood);
				}

				if (this.dropEatingLootCooldown <= 0) {
					if (this.random.nextFloat() < 0.2F) {
						for (ItemStack stacks : this.generateFishingLoot()) {
							if (stacks.getCount() > 0) {
								stacks.shrink(stacks.getCount() - 1);
							}
							this.spitOutItem(stacks);
						}
					} else {
						this.spitOutItem(new ItemStack(Items.BONE_MEAL));
					}
					this.dropEatingLootCooldown = 3600 + this.getRandom().nextInt(400);
				}

				this.heal(6);
				this.eatTicks = 0;
			} else if (this.eatTicks > 560 && this.random.nextFloat() < 0.1F) {
				this.playSound(this.getEatingSound(itemstack), 1.0F, 1.0F);
				this.level().broadcastEntityEvent(this, (byte) 45);
			}
		}

		if (this.isMoving() && this.isInWater() && this.getVariant().is(UAPikeVariants.SUPERCHARGED)) {
			Vec3 vec3d1 = this.getViewVector(0.0F);

			for (int i = 0; i < 2; ++i) {
				this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.x * 1.5D, this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - vec3d1.y * 1.5D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.z * 1.5D, 0.0D, 0.0D, 0.0D);
			}
		}

		if (this.getVariant().is(UAPikeVariants.OBSIDIAN) && this.isLit()) {
			if (this.level().isClientSide) {
				for (int i = 0; i < 2; i++) {
					this.level().addParticle(ParticleTypes.PORTAL, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - 0.25D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
				}
			}
		}
	}

