                        }
                    }
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        this.prevSitProgress = this.sitProgress;
        if (this.isSitting()) {
            if (sitProgress < 10F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
            this.setOrderedToSit(false);
            sittingTime = 0;
            maxSitTime = 75 + random.nextInt(50);
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isSitting() && this.getCommand() != 1 && random.nextInt(1500) == 0) {
            maxSitTime = 300 + random.nextInt(250);
            this.setOrderedToSit(true);
        }
        this.setMaxUpStep(2);
        if (!forcedSit && this.isSitting() && (this.getDartTarget() != null || this.getCommand() == 1)) {
            this.setOrderedToSit(false);
        }

        if (!this.level().isClientSide) {
            if (this.getTarget() != null && this.getAnimation() == ANIMATION_SCRATCH && this.getAnimationTick() == 10) {
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.3F, 0.0D, Mth.cos(f1) * 0.3F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                this.setAttackDecision(this.getTarget());
            }
            if (this.getDartTarget() != null && this.getDartTarget().isAlive() && this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() == 5) {
                final Vec3 vector3d = this.getDartTarget().getDeltaMovement();
                final double d0 = this.getDartTarget().getX() + vector3d.x - this.getX();
                final double d1 = this.getDartTarget().getEyeY() - (double) 1.1F - this.getY();
                final double d2 = this.getDartTarget().getZ() + vector3d.z - this.getZ();
                final float f = Mth.sqrt((float)(d0 * d0 + d2 * d2));
                EntityTossedItem tossedItem = new EntityTossedItem(this.level(), this);
                tossedItem.setDart(this.hasDart());
                tossedItem.setXRot(tossedItem.getXRot() - 20F);
                tossedItem.shoot(d0, d1 + (double) (f * 0.2F), d2, hasDart() ? 1.15F : 0.75F, 8.0F);
                if (!this.isSilent()) {
                    this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_THROW, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    this.gameEvent(GameEvent.PROJECTILE_SHOOT);
                }
                this.level().addFreshEntity(tossedItem);
                this.setAttackDecision(this.getDartTarget());
            }
        }
        if (rideCooldown > 0) {
            rideCooldown--;
        }
        if (!this.level().isClientSide && getAnimation() == NO_ANIMATION && this.getRandom().nextInt(300) == 0) {
            setAnimation(ANIMATION_HEADTILT);
        }
        if (!this.level().isClientSide && this.isSitting()) {
            this.getNavigation().stop();
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
            super.tick();
            LivingEntity target = EntityFarseer.this.getTarget();
            if (laserCooldown > 0) {
                laserCooldown--;
            }
            timeSinceLastSuccessfulAttack++;
            if (timeSinceLastSuccessfulAttack > 100) {
                timeSinceLastSuccessfulAttack = 0;
                attackDecision = !attackDecision;
            }
            if (target != null) {
                double dist = EntityFarseer.this.distanceTo(target);
                boolean canLaserHit = willLaserHit(target);
                if (this.laserCooldown == 0 && attackDecision && canLaserHit && dist > 2F) {
                    EntityFarseer.this.setAngry(true);
                    EntityFarseer.this.entityData.set(LASER_ENTITY_ID, target.getId());
                    if(laserUseTime == 0){
                        EntityFarseer.this.playSound(AMSoundRegistry.FARSEER_BEAM.get(), EntityFarseer.this.getSoundVolume(), EntityFarseer.this.getVoicePitch());
                    }
                    laserUseTime++;
                    if (laserUseTime > LASER_ATTACK_DURATION) {
                        laserUseTime = 0;
                        if (canLaserHit) {
                            float healthTenth = target.getMaxHealth() * 0.1F;
                            if(target.hurt(AMDamageTypes.causeFarseerDamage(EntityFarseer.this), random.nextInt(2) + Math.max(6, healthTenth)) && !target.isAlive()){
                                AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                            }
                            timeSinceLastSuccessfulAttack = 0;
                        }
                        if (lasersShot++ > 5) {
                            lasersShot = 0;
                            laserCooldown = 80 + random.nextInt(40);
                            EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                            attackDecision = EntityFarseer.this.getRandom().nextBoolean();
                        }
                    }
                    EntityFarseer.this.entityData.set(LASER_ATTACK_LVL, laserUseTime);
                    EntityFarseer.this.lookAt(target, 180F, 180F);
                    if (dist < 17F && canLaserHit) {
                        EntityFarseer.this.getNavigation().stop();
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, false);
                } else {
                    if (!canLaserHit && dist > 10) {
                        EntityFarseer.this.setAngry(false);
                    }
                    if (EntityFarseer.this.hasLaser()) {
                        EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, dist < 4F);
                    if (dist < 4F) {
                        timeSinceLastSuccessfulAttack = 0;
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                        EntityFarseer.this.moveControl.setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1F);
                    }
                }
            }
        }

public void tick() {
        super.tick();
        if (jumpCooldown > 0) {
            jumpCooldown--;
            float f2 = (float) -((float) this.getDeltaMovement().y * (double) Mth.RAD_TO_DEG);
            this.setXRot(f2);
        }
        if (this.isNoAi()) {
            this.setAirSupply(this.getMaxAirSupply());
        } else {

            if (this.isInWaterRainOrBubble()) {
                this.setMoistness(2400);
            } else {
                this.setMoistness(this.getMoistness() - 1);
                if (this.getMoistness() <= 0) {
                    this.hurt(damageSources().dryOut(), 1.0F);
                }

                if (this.onGround()) {
                    this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
                    this.setYRot( this.random.nextFloat() * 360.0F);
                    this.setOnGround(false);
                    this.hasImpulse = true;
                }
            }

            if (this.level().isClientSide && this.isInWater() && this.getDeltaMovement().lengthSqr() > 0.03D) {
                Vec3 vector3d = this.getViewVector(0.0F);
                final float yRotRad = this.getYRot() * Mth.DEG_TO_RAD;
                final float f = Mth.cos(yRotRad) * 0.9F;
                final float f1 = Mth.sin(yRotRad) * 0.9F;
                final float f2 = 1.2F - this.random.nextFloat() * 0.7F;

                for (int i = 0; i < 2; ++i) {
                    this.level().addParticle(ParticleTypes.DOLPHIN, this.getX() - vector3d.x * (double) f2 + (double) f, this.getY() - vector3d.y, this.getZ() - vector3d.z * (double) f2 + (double) f1, 0.0D, 0.0D, 0.0D);
                    this.level().addParticle(ParticleTypes.DOLPHIN, this.getX() - vector3d.x * (double) f2 - (double) f, this.getY() - vector3d.y, this.getZ() - vector3d.z * (double) f2 - (double) f1, 0.0D, 0.0D, 0.0D);
                }
            }

        }
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null && distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2) {
            if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 4) {
                float damage =(float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                if(attackTarget instanceof Drowned || attackTarget instanceof Guardian){
                    damage *= 2F;
                }
                boolean flag = attackTarget.hurt(this.damageSources().mobAttack(this), damage);
                if (flag) {
                    this.doEnchantDamageEffects(this, attackTarget);
                    this.playSound(SoundEvents.DOLPHIN_ATTACK, 1.0F, 1.0F);
                }
            }
            if (this.getAnimation() == ANIMATION_TAILSWING && this.getAnimationTick() == 6) {
                float damage =(float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                if(attackTarget instanceof Drowned || attackTarget instanceof Guardian){
                    damage *= 2F;
                }
                boolean flag = attackTarget.hurt(this.damageSources().mobAttack(this), damage);
                if (flag) {
                    this.doEnchantDamageEffects(this, attackTarget);
                    this.playSound(SoundEvents.DOLPHIN_ATTACK, 1.0F, 1.0F);
                }
                final float yRotRad = this.getYRot() * Mth.DEG_TO_RAD;
                attackTarget.knockback(1F, Mth.sin(yRotRad), -Mth.cos(yRotRad));
                float knockbackResist = (float) Mth.clamp((1.0D - this.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)), 0, 1);
                this.getTarget().setDeltaMovement(this.getTarget().getDeltaMovement().add(0, knockbackResist * 0.4F, 0));

            }
        }
        if (attackTarget != null && attackTarget instanceof Player && attackTarget.hasEffect(AMEffectRegistry.ORCAS_MIGHT.get())) {
            attackTarget.removeEffect(AMEffectRegistry.ORCAS_MIGHT.get());
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void aiStep() {
        super.aiStep();
        float dis = this.getBbWidth();

        float f1 = (float) Math.cos(Math.toRadians(this.getYRot() + 90));
        float f2 = (float) Math.sin(Math.toRadians(this.getYRot() + 90));

        if(this.getAttackState() == 1) {
            if (this.attackTicks == 17) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 4.35f,dis * 4.35f,45,1.25F,60);
            }
            if (this.attackTicks == 35) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 3.6f,dis * 3.6f,200,1.25F,0);
            }
        }
        if(this.getAttackState() == 3) {
            if (this.tickCount % 4 == 0) {
                if (!this.level().isClientSide) {
                    for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                        if (!isAlliedTo(entity) && !(entity instanceof Ignited_Berserker_Entity) && entity != this) {
                            boolean flag = entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                            if (flag) {
                                double d0 = entity.getX() - this.getX();
                                double d1 = entity.getZ() - this.getZ();
                                double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                                entity.push(d0 / d2 * 0.5D, 0.1D, d1 / d2 * 0.5D);
                            }
                        }
                    }
                }
            }
        }

        if(this.getAttackState() == 5) {
            if (this.attackTicks == 11 || this.attackTicks == 18 || this.attackTicks == 23 || this.attackTicks == 28  ) {
                this.push(f1 * 0.45, 0, f2 * 0.45);
            }
            if (this.attackTicks == 13) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 4.5f,dis * 4.5f,50,1,0);
            }
            if (this.attackTicks == 20) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 3.5f,dis * 3.5f,60,1,0);
            }
            if (this.attackTicks == 25) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 4.5f,dis * 4.5f,60,1,0);
            }
            if (this.attackTicks == 30) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 3.25f,dis * 3.25f,60,1,0);
            }
        }
        if(this.getAttackState() == 6) {
            if (this.attackTicks == 15 || this.attackTicks == 123 || this.attackTicks == 26 || this.attackTicks == 33) {
                this.push(f1 * 0.45, 0, f2 * 0.45);
            }
            if (this.attackTicks == 17) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 4.5f,dis * 4.5f,40,1,0);
            }
            if (this.attackTicks == 25) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 3.25f,dis * 3.25f,55,1,0);
            }
            if (this.attackTicks == 28) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 5f,dis * 5f,60,1,0);
            }
            if (this.attackTicks == 35) {
                this.playSound(ModSounds.SWING.get(), 1F, 1.2f);
                AreaAttack(dis * 3.5f,dis * 3.5f,40,1,0);
            }
        }

    }

@Override
	public void tick() {
		super.tick();

		Entity riding = getVehicle();
		if(riding != null)
			rideTime++;
		else
			rideTime = 0;

		if(eatCooldown > 0)
			eatCooldown--;

		if(angeryTicks > 0 && isAlive()) {
			angeryTicks--;

			if(onGround()) {
				int dangerRange = 3;
				double x = getX() + getBbWidth() / 2;
				double y = getY();
				double z = getZ() + getBbWidth() / 2;

				if(level() instanceof ServerLevel serverLevel) {
					if(angeryTicks == 3)
						playSound(QuarkSounds.ENTITY_TORETOISE_ANGRY, 1F, 0.2F);
					else if(angeryTicks == 0) {
						serverLevel.sendParticles(ParticleTypes.CLOUD, x, y, z, 200, dangerRange, 0.5, dangerRange, 0);
						gameEvent(GameEvent.ENTITY_ACTION);
					}
				}

				if(angeryTicks == 0) {
					AABB hurtAabb = new AABB(x - dangerRange, y - 1, z - dangerRange, x + dangerRange, y + 1, z + dangerRange);
					List<LivingEntity> hurtMeDaddy = level().getEntitiesOfClass(LivingEntity.class, hurtAabb, e -> !(e instanceof Toretoise));

					LivingEntity aggressor = lastAggressor == null ? this : lastAggressor;
					DamageSource damageSource = damageSources().mobAttack(aggressor);
					for(LivingEntity e : hurtMeDaddy) {
						DamageSource useSource = damageSource;
						if(e == aggressor)
							useSource = damageSources().mobAttack(this);
						if(e instanceof Player player && level().getDifficulty() == Difficulty.PEACEFUL){
							player.push(0, 0.25, 0);
							//give the player slight upwards knocback so there's some sort of feedback without hurting them in peaceful
						}

						e.hurt(useSource, 4 + level().getDifficulty().ordinal());
					}
				}
			}
		}

		if(level() instanceof ServerLevel serverLevel) {
			int ore = getOreType();
			if(ore != 0)
				breakOre: {
					AABB ourBoundingBox = getBoundingBox();
					BlockPos min = BlockPos.containing(Math.round(ourBoundingBox.minX), Math.round(ourBoundingBox.minY), Math.round(ourBoundingBox.minZ));
					BlockPos max = BlockPos.containing(Math.round(ourBoundingBox.maxX), Math.round(ourBoundingBox.maxY), Math.round(ourBoundingBox.maxZ));

					for(int ix = min.getX(); ix <= max.getX(); ix++)
						for(int iy = min.getY(); iy <= max.getY(); iy++)
							for(int iz = min.getZ(); iz <= max.getZ(); iz++) {
								BlockPos test = new BlockPos(ix, iy, iz);
								BlockState state = level().getBlockState(test);
								if(state.getBlock() == Blocks.MOVING_PISTON) {
									BlockEntity tile = level().getBlockEntity(test);
									if(tile instanceof PistonMovingBlockEntity piston && piston.isExtending()) {
										BlockState pistonState = piston.getMovedState();
										if(pistonState.is(BREAKS_TORETOISE_ORE)) {
											if(!pistonState.hasProperty(RodBlock.FACING) || pistonState.getValue(RodBlock.FACING) == piston.getMovementDirection()) {
												dropOre(ore, new LootParams.Builder(serverLevel)
														.withParameter(LootContextParams.TOOL, new ItemStack(Items.IRON_PICKAXE)));
												break breakOre;
											}
										}
									}
								}
							}
				}
		}
	}

public void tick() {
            LivingEntity target = EntityMimicOctopus.this.getTarget();
            if (target != null) {
                if (scareMobTime > 0) {
                    if (fleePosition == null || target.distanceToSqr(fleePosition) < target.getBbWidth() * target.getBbWidth() * 2) {
                        fleePosition = generateFleePosition(target);
                    }
                    if (target instanceof Mob) {
                        if (fleePosition != null) {
                            ((Mob) target).getNavigation().moveTo(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                            ((Mob) target).getMoveControl().setWantedPosition(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                            ((Mob) target).setTarget(null);
                        }
                    }
                    camoCooldown = Math.max(camoCooldown, 20);
                    stopMimicCooldown = Math.max(stopMimicCooldown, 20);
                    scareMobTime--;
                    if (scareMobTime == 0) {
                        stop();
                        return;
                    }
                }
                double dist = EntityMimicOctopus.this.distanceTo(target);
                boolean move = true;
                if (dist < 7F && EntityMimicOctopus.this.hasLineOfSight(target) && EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN && EntityMimicOctopus.this.isUpgraded()) {
                    EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
                    move = false;
                }
                if (dist < 3) {
                    EntityMimicOctopus.this.entityData.set(LAST_SCARED_MOB_ID, target.getId());
                    if (move) {
                        move = EntityMimicOctopus.this.isUpgraded() && dist > 2;
                    }
                    EntityMimicOctopus.this.getNavigation().stop();
                    if (!EntityMimicOctopus.this.isStopChange()) {
                        EntityMimicOctopus.this.setMimickedBlock(null);
                        MimicState prev = EntityMimicOctopus.this.getMimicState();
                        if (EntityMimicOctopus.this.isInWaterOrBubble()) {
                            if (prev != MimicState.GUARDIAN && prev != MimicState.PUFFERFISH) {
                                if (random.nextBoolean()) {
                                    EntityMimicOctopus.this.setMimicState(MimicState.GUARDIAN);
                                } else {
                                    EntityMimicOctopus.this.setMimicState(MimicState.PUFFERFISH);
                                }
                            }
                        } else {
                            EntityMimicOctopus.this.setMimicState(MimicState.CREEPER);
                        }
                    }
                    if (EntityMimicOctopus.this.getMimicState() != MimicState.OVERLAY) {
                        EntityMimicOctopus.this.mimicCooldown = 40;
                        EntityMimicOctopus.this.stopMimicCooldown = Math.max(EntityMimicOctopus.this.stopMimicCooldown, 60);
                    }
                    if (EntityMimicOctopus.this.isUpgraded() && EntityMimicOctopus.this.transProgress >= 5.0F) {
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.PUFFERFISH) {
                            if (EntityMimicOctopus.this.getBoundingBox().expandTowards(2, 1.3, 2).intersects(target.getBoundingBox())) {
                                target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 4);
                                target.addEffect(new MobEffectInstance(MobEffects.POISON, 400, 2));
                            }
                        }
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN) {
                            if (EntityMimicOctopus.this.getBoundingBox().expandTowards(1, 1, 1).intersects(target.getBoundingBox())) {
                                target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 1);
                            }
                            EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
                        }
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.CREEPER) {
                            EntityMimicOctopus.this.creeperExplode();
                            EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 69);
                            executionCooldown = 300;
                        }
                    }
                    if (scareMobTime == 0) {
                        EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 68);
                        scareMobTime = 60 + random.nextInt(60);
                    }
                }
                if (move) {
                    EntityMimicOctopus.this.lookAt(target, 30, 30);
                    EntityMimicOctopus.this.getNavigation().moveTo(target, 1.2F);
                }
            }
        }

public void tick() {
        super.tick();
        this.prevStandProgress = this.standProgress;
        this.prevBegProgress = this.begProgress;
        this.prevWashProgress = this.washProgress;
        this.prevSitProgress = this.sitProgress;

        if (this.isStanding()) {
            if (standProgress < 5F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        if (this.isBegging()) {
            if (begProgress < 5F)
                begProgress++;
        } else {
            if (begProgress > 0F)
                begProgress--;
        }

        if (this.isWashing()) {
            if (washProgress < 5F)
                washProgress++;
        } else {
            if (washProgress > 0F)
                washProgress--;
        }

        if (this.isSitting()) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (!this.level().isClientSide) {
            if (lookForWaterBeforeEatingTimer > 0) {
                lookForWaterBeforeEatingTimer--;
            } else if (!isWashing() && canTargetItem(this.getMainHandItem())) {
                onEatItem();
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.getMainHandItem().shrink(1);
            }
        }
        if (isWashing()) {
            if (getWashPos() != null) {
                BlockPos washingPos = getWashPos();
                if (this.distanceToSqr(washingPos.getX() + 0.5D, washingPos.getY() + 0.5D, washingPos.getZ() + 0.5D) < 3) {
                    for (int j = 0; (float) j < 4; ++j) {
                        double d2 = (this.random.nextDouble());
                        double d3 = (this.random.nextDouble());
                        Vec3 vector3d = this.getDeltaMovement();

                        this.level().addParticle(ParticleTypes.SPLASH, washingPos.getX() + d2, (double) (washingPos.getY() + 0.8F), washingPos.getZ() + d3, vector3d.x, vector3d.y, vector3d.z);
                    }
                } else {
                    setWashing(false);
                }
            }
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && this.distanceTo(this.getTarget()) < 4 && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 5) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add((double) (-Mth.sin(f1) * -0.06F), 0.0D, (double) (Mth.cos(f1) * -0.06F)));
            this.getTarget().knockback(0.35F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (stealCooldown > 0) {
            stealCooldown--;
        }
        if (pickupItemCooldown > 0) {
            pickupItemCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        Entity entity = source.getDirectEntity();
        LivingEntity target = this.getTarget();
        double range = calculateRange(source);

        if (entity != null && !isNoAi() && (blockingProgress == 10 || swordProgress == 10)) {
            if (target != null && target.isAlive()) {
                if (this.getAnimation() == NO_ANIMATION) {
                    if (this.getRandom().nextFloat() * 100.0F < 12f && counter_strike_cooldown <= 0 && range < 225) {
                        counter_strike_cooldown = CONTER_STRIKE_COOLDOWN;
                        Animation counter = this.getIsShieldBreak() ? SHIELD_BREAK_COUNTER : COUNTER;
                        this.setAnimation(counter);
                    }
                }
            }
            if (this.getAnimation() == COUNTER) {
                if (this.getAnimationTick() > 16 && this.getAnimationTick() <= 46) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, STRIKE);
                    this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                    if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                        return false;
                    }
                }
            }
            if (this.getAnimation() == SHIELD_BREAK_COUNTER) {
                if (this.getAnimationTick() > 8 && this.getAnimationTick() <= 38) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SHIELD_BREAK_STRIKE);
                    this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                    if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                        return false;
                    }
                }
            }
        }

        if (source.getDirectEntity() instanceof Ignis_Abyss_Fireball_Entity) {
            if (!(source.getEntity() instanceof Ignis_Entity)) {
                if (source.is(DamageTypeTags.IS_PROJECTILE)) {
                    if (this.getShieldDurability() < 3) {
                        this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0F, 0.8F);
                        if (!level().isClientSide) {
                            this.setShieldDurability(this.getShieldDurability() + 1);
                        }
                    }
                }
            } else {
                return false;
            }
        }


        if ((this.getAnimation() == ULTIMATE_ATTACK || this.getBossPhase() == 1 && this.getHealth() <= this.getMaxHealth() * 1 / 3 || this.getBossPhase() == 0 && this.getHealth() <= this.getMaxHealth() * 2 / 3) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            damage *= 0.5;
        }

        if ((this.getAnimation() == PHASE_3 || this.getAnimation() == PHASE_2 || this.getAnimation() == STRIKE) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }
        if (source.getDirectEntity() instanceof Ignis_Fireball_Entity) {
            return false;
        }
        if (damage > 0.0F && this.canBlockDamageSource(source)) {
            this.hurtCurrentlyUsedShield(damage);
            if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
                if (entity instanceof LivingEntity) {
                    this.blockUsingShield((LivingEntity) entity);
                }
            }
            this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
            return false;
        }

        if (this.destroyBlocksTick <= 0) {
            this.destroyBlocksTick = 20;
        }

        Crackiness irongolem$crackiness = this.getCrackiness();
        boolean attack = super.hurt(source, damage);
        if (attack && this.getCrackiness() != irongolem$crackiness) {
            this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0f, 0.8f);
        }

        return attack;
    }

public void rideTick() {
        Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                attachTime++;
                Entity mount = this.getVehicle();
                if (mount instanceof LivingEntity) {
                    passengerIndex = mount.getPassengers().indexOf(this);
                    this.yBodyRot = ((LivingEntity) mount).yBodyRot;
                    this.setYRot( ((LivingEntity) mount).getYRot());
                    this.yHeadRot = ((LivingEntity) mount).yHeadRot;
                    this.yRotO = ((LivingEntity) mount).yHeadRot;
                    float radius = mount.getBbWidth();
                    float angle = (Maths.STARTING_ANGLE * (((LivingEntity) mount).yBodyRot + passengerIndex * 90F));
                    double extraX = radius * Mth.sin(Mth.PI + angle);
                    double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    this.setPhagePitch(0F);
                    if (!this.level().isClientSide && attachTime > 15) {
                        LivingEntity target = (LivingEntity) mount;
                        float dmg = 1F;
                        if (target.getHealth() > target.getMaxHealth() * 0.2F) {
                            dmg = 6F;
                        }
                        if ((target.getHealth() < 1.5D || mount.hurt(this.damageSources().mobAttack(this), dmg)) && mount instanceof LivingEntity) {
                            dismountCooldown = 100;
                            if (mount instanceof EnderMan) {
                                this.setMissingEye(false);
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.ENDER_EYE_DEATH, this.getSoundVolume(), this.getVoicePitch());
                                this.heal(5);
                                ((EnderMan) mount).addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 400));
                                this.fleeAfterStealTime = 400;
                                this.setFlying(true);
                                this.angryEnderman = (PathfinderMob) mount;
                            } else {
                                if (random.nextInt(3) == 0) {
                                    if (!this.isMissingEye()) {
                                        if (target.getEffect(AMEffectRegistry.ENDER_FLU.get()) == null) {
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), 12000));
                                        } else {
                                            MobEffectInstance inst = target.getEffect(AMEffectRegistry.ENDER_FLU.get());
                                            int duration = 12000;
                                            int level = 0;
                                            if (inst != null) {
                                                duration = inst.getDuration();
                                                level = inst.getAmplifier();
                                            }
                                            target.removeEffect(AMEffectRegistry.ENDER_FLU.get());
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), duration, Math.min(level + 1, 4)));
                                        }
                                        this.heal(5);
                                        this.gameEvent(GameEvent.ENTITY_ROAR);
                                        this.playSound(SoundEvents.ITEM_BREAK, this.getSoundVolume(), this.getVoicePitch());
                                        this.setMissingEye(true);
                                    }
                                    if (!this.level().isClientSide) {
                                        this.setTarget(null);
                                        this.setLastHurtMob(null);
                                        this.setLastHurtByMob(null);
                                        this.goalSelector.getRunningGoals().forEach(Goal::stop);
                                        this.targetSelector.getRunningGoals().forEach(Goal::stop);
                                    }
                                }
                            }
                        }
                        if (((LivingEntity) mount).getHealth() <= 0 || this.fleeAfterStealTime > 0 || this.isMissingEye() && !(mount instanceof EnderMan) || !this.isMissingEye() && mount instanceof EnderMan) {
                            this.removeVehicle();
                            this.setTarget(null);
                            dismountCooldown = 100;
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(true);
                        }
                    }
                }

            }
        }

    }

public void tick() {
        super.tick();
        repelEntities(1.7F, 3.7f, 1.7F, 1.7F);
        LivingEntity target = this.getTarget();
        prevdeactivateProgress = deactivateProgress;
        if (!this.getIsAwaken() && deactivateProgress < 30F) {
            deactivateProgress++;
        }
        if (this.getIsAwaken() && deactivateProgress > 0F) {
            deactivateProgress--;

        }

        if(!this.getIsAwaken()) {
            if (this.tickCount % 20 == 0) {
                this.heal(2.0F);
            }
        }

        if (deactivateProgress == 0 && this.isAlive()) {
            if (target != null && target.isAlive()) {
                if (void_rune_attack_cooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && target.onGround() && (this.random.nextInt(45) == 0 && this.distanceTo(target) < 4 || this.random.nextInt(24) == 0 && this.distanceTo(target) < 10)) {
                    void_rune_attack_cooldown = VOID_RUNE_ATTACK_COOLDOWN;
                    this.setAnimation(VOID_RUNE_ATTACK);

                } else if (this.distanceTo(target) < 4 && !isNoAi() && this.getAnimation() == NO_ANIMATION) {
                    Animation animation = getRandomAttack(random);
                    this.setAnimation(animation);
                }
            }

            if (this.getAnimation() == ANIMATION_EARTHQUAKE) {
                if (this.getAnimationTick() == 19) {
                    EarthQuake(5,6);
                    EarthQuakeParticle();
                    if (!this.level().isClientSide) {
                        if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                            BlockBreaking(4, 4, 4);
                        } else {
                            if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                                BlockBreaking(4, 4, 4);
                            }
                        }
                    }
                }
            }
            if ((this.getAnimation() == ANIMATION_ATTACK1 || this.getAnimation() == ANIMATION_ATTACK2) && this.getAnimationTick() == 13) {
                this.playSound(ModSounds.GOLEMATTACK.get(), 1, 1);
                if (target != null && target.isAlive()) {
                    if (this.distanceTo(target) < 4.75F) {
                        target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) + this.random.nextInt(4));
                        target.knockback(1.25F, this.getX() - target.getX(), this.getZ() - target.getZ());
                    }
                }
            }
            if (this.getAnimation() == VOID_RUNE_ATTACK) {
                if (this.getAnimationTick() == 22) {
                    EarthQuake(4.25f,4);
                    EarthQuakeParticle();
                    if (!this.level().isClientSide) {
                        if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                            BlockBreaking(4, 4, 4);
                        } else {
                            if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                                BlockBreaking(4, 4, 4);
                            }
                        }
                    }
                }
                if (this.getAnimationTick() == 28) {
                    VoidRuneAttack();
                }
            }
        }
        if (void_rune_attack_cooldown > 0) void_rune_attack_cooldown--;
        if (!level().isClientSide) {
            timeWithoutTarget++;
            if (target != null) {
                timeWithoutTarget = 0;
                if(!this.getIsAwaken()) {
                    this.setIsAwaken(true);
                }
            }

            if (timeWithoutTarget > 400 && this.getIsAwaken() && target == null) {
                timeWithoutTarget = 0;
                this.setIsAwaken(false);
            }
        }

    }

public static AttackShieldResult attackShield(World world, ProtectionShield shield, Vec3d centerPos, float shieldRotationYaw, float shieldRotationPitch, float shieldRotationRoll, float shieldExplosion, Object2IntMap<Entity> deflectionDamageCooldowns, DamageSource source, boolean checkOnly) {
		if(source instanceof EntityDamageSource) {
			EntityDamageSource entityDamage = (EntityDamageSource) source;

			Entity sourceEntity = entityDamage.getTrueSource();
			Entity immediateEntity = entityDamage.getImmediateSource();

			Entity attackingEntity = immediateEntity != null ? immediateEntity : sourceEntity;

			int shieldHit = -1;
			boolean isDeflected = false;

			Vec3d ray = null;
			Vec3d pos = null;

			if(attackingEntity == null) {
				isDeflected = true;
			} else {
				if(attackingEntity instanceof EntityLivingBase) {
					ray = attackingEntity.getLookVec();
				} else {
					ray = new Vec3d(attackingEntity.motionX, attackingEntity.motionY, attackingEntity.motionZ).normalize();
				}
				ray = ray.scale(64.0D);

				pos = new Vec3d(attackingEntity.posX, attackingEntity.posY + attackingEntity.getEyeHeight(), attackingEntity.posZ);

				if(shield.hasShield() && (attackingEntity instanceof EntityPlayer == false || !((EntityPlayer)attackingEntity).capabilities.isCreativeMode) || attackingEntity.isSneaking()) {
					shieldHit = rayTraceShield(shield, centerPos, shieldRotationYaw, shieldRotationPitch, shieldRotationRoll, shieldExplosion, pos, ray, false);

					if(shieldHit >= 0) {
						if(!checkOnly) {
							if(!world.isRemote && attackingEntity.isSneaking() && ((EntityPlayer)attackingEntity).capabilities.isCreativeMode) {
								shield.setActive(shieldHit, false);
							}

							if(world.isRemote) {
								shield.setAnimationTicks(shieldHit, 20);
							}
						}

						isDeflected = true;
					}
				}
			}

			if(isDeflected) {
				if(!checkOnly && !world.isRemote) {
					boolean damaged = false;

					if(sourceEntity != null && !deflectionDamageCooldowns.containsKey(sourceEntity)) {
						double dx = sourceEntity.posX - centerPos.x;
						double dy = sourceEntity.posY - centerPos.y;
						double dz = sourceEntity.posZ - centerPos.z;
						double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
						sourceEntity.motionX = dx / len * 0.8F;
						sourceEntity.motionY = dy / len * 0.8F;
						sourceEntity.motionZ = dz / len * 0.8F;
						sourceEntity.velocityChanged = sourceEntity.isAirBorne = true;
						sourceEntity.attackEntityFrom(DamageSource.MAGIC, 2);

						deflectionDamageCooldowns.put(sourceEntity, 10);
						damaged = true;
					}

					if(immediateEntity != null && !deflectionDamageCooldowns.containsKey(immediateEntity)) {
						double dx = immediateEntity.posX - centerPos.x;
						double dy = immediateEntity.posY - centerPos.y;
						double dz = immediateEntity.posZ - centerPos.z;
						double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
						immediateEntity.motionX = dx / len * 0.8F;
						immediateEntity.motionY = dy / len * 0.8F;
						immediateEntity.motionZ = dz / len * 0.8F;
						immediateEntity.velocityChanged = immediateEntity.isAirBorne = true;
						immediateEntity.attackEntityFrom(DamageSource.MAGIC, 2);

						deflectionDamageCooldowns.put(immediateEntity, 10);
						damaged = true;
					}

					if(damaged) {
						world.playSound(null, centerPos.x, centerPos.y, centerPos.z, SoundRegistry.FORTRESS_BOSS_NOPE, SoundCategory.HOSTILE, 1, 1);
					}
				}

				return new AttackShieldResult(true, shieldHit, pos, ray);
			} else {
				return new AttackShieldResult(false, shieldHit, pos, ray);
			}
		}

		return new AttackShieldResult(true, -1, null, null);
	}

public static void finalizeDeliveredCraftResult(ServerLevel level, ItemStack craftedStack, Inventory playerInventory, ItemStack carriedStack) {
		EnderLinkPendingCraftData pendingCraft = craftedStack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null || pendingCraft.claimId() == null) {
			return;
		}
		ItemStack result = hasClaim(pendingCraft.claimId(), carriedStack) ? carriedStack : findTransferredCraftResult(pendingCraft.claimId(), playerInventory);
		if (result.isEmpty()) {
			result = isUnclaimedDeliveredResult(craftedStack, carriedStack) ? carriedStack : findUnclaimedDeliveredResult(craftedStack, playerInventory);
		}
		if (!result.isEmpty()) {
			result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, pendingCraft);
			finalizePendingCraftResult(level, result);
		}
	}

private void calculatePowerInputAndNotifyNeighbors(World world, BlockPos pos) {
  // calculate the power level from neighbours and store in our TileEntity for later use in getWeakPower()
    int powerLevel = getPowerLevelInputFromNeighbours(world, pos);
    TileEntity tileentity = world.getTileEntity(pos);
    if (tileentity instanceof TileEntityRedstoneMeter) { // prevent a crash if not the right type, or is null
      TileEntityRedstoneMeter tileEntityRedstoneMeter = (TileEntityRedstoneMeter) tileentity;

      boolean currentOutputState = tileEntityRedstoneMeter.getOutputState();
      tileEntityRedstoneMeter.setPowerLevelServer(powerLevel);
      // this method will also schedule the next tick using call world.scheduleTick(pos, block, delay);

      if (currentOutputState != tileEntityRedstoneMeter.getOutputState()) {
        world.notifyNeighborsOfStateChange(pos, this);
      }
    }
  }

@Override
	public void slotChanged(AbstractContainerMenu menu, int index, ItemStack stack) {
		if (!stack.isEmpty() && menu.getSlot(index).container == player.getInventory()) {
			int slotNum = menu.getSlot(index).getContainerSlot();
			if (slotNum >= 0 && slotNum < player.getInventory().items.size()) {
				// Only checking for items in the main inventory & hotbar
				// Armor slots can contain items with rapidly changing NBT (especially powered modded armor)
				//  which can trigger a lot of unnecessary inventory scans
				int delay = Mth.clamp(ServerQuestFile.INSTANCE.getDetectionDelay(), 0, 200);
				if (delay == 0) {
					FTBQuestsInventoryListener.detect(player, ItemStack.EMPTY, 0);
				} else {
					DeferredInventoryDetection.scheduleInventoryCheck(player, delay);
				}
			}
		}
	}

@Override
	protected void doAccept() {
		IntSet toCreate = new IntOpenHashSet();
		for (int idx = 0; idx < rewardTablesCopy.size(); idx++) {
			if (rewardTablesCopy.get(idx).id == 0L && !pendingDeleteIndexes.contains(idx)) {
				toCreate.add(idx);
			}
		}
		editedIndexes.removeAll(pendingDeleteIndexes);

		int nAdded = sendToServer(toCreate, tbl -> new CreateObjectMessage(tbl, null), true);
		int nEdited = sendToServer(editedIndexes, EditObjectMessage::new, false);
		int nDeleted = sendToServer(pendingDeleteIndexes, tbl -> new DeleteObjectMessage(tbl.id), false);

		FTBQuests.LOGGER.debug("Sent {} new, {} edited, {} deleted reward tables to server", nAdded, nEdited, nDeleted);

		questScreen.run();
	}

public boolean payout() {
        BlockEntity returning = getReturningTileEntity();
        if (pendingPayments > 0) {
            final int pay0 = Math.min(pendingPayments, 50);
            int paying = getInput().apply(
                    itemStack -> IOHelper.getInventoryForBlock(returning).map(h -> getInput().findSpaceInItemOutput(h, pay0)).orElse(0),
                    fluidStack -> IOHelper.getFluidHandlerForBlock(returning).map(h -> getInput().findSpaceInFluidOutput(h, pay0)).orElse(0)
            );
            if (paying > 0) {
                pendingPayments -= paying;
                getInput().accept(
                        itemStack -> DroneRegistry.getInstance().deliverItemsAmazonStyle(returningPos, AmadronUtil.buildStacks(itemStack, paying)),
                        fluidStack -> DroneRegistry.getInstance().deliverFluidAmazonStyle(returningPos, AmadronUtil.buildFluidStack(fluidStack, paying)));
                return true;
            }
        }
        return false;
    }

public void spawnEmitter(TileParticle father) {
            if (fxLocation == null) {
                return;
            }
            // probability roll stays here: the particle's RandomSource is confined to its update thread
            if (father.getRandomSource().nextFloat() >= emitProbability.get(father.getT(0),
                    () -> father.getMemRandom("sub_emitter_probability")).floatValue()) {
                return;
            }
            // FXHelper.getFX + FXRuntime.emit (particle engine) are not thread-safe: particle updates
            // may run on parallelStream workers, so defer the spawn to the game thread — the owning
            // emitter drains it at the end of the same tick (deferred in serial mode too, so ordering
            // is mode-independent; a dead particle's fields stay valid until next tick's removal).
            if (father.getEmitter() instanceof ParticleEmitter particleEmitter) {
                particleEmitter.scheduleSubEmitterSpawn(() -> doSpawn(father));
            } else {
                doSpawn(father); // non-ParticleEmitter owners never parallel-update TileParticles
            }
        }

public void tick() {
        int currentTemp = logic.getTemperatureAsInt();

        if (shouldSyncNow()) {
            // large temperature delta: sync immediately
            this.syncedTemp = currentTemp;
            syncTimer = -1;
        } else if (currentTemp != syncedTemp) {
            // small temperature delta: schedule a sync to happen in 60 ticks, unless one is already scheduled
            if (syncTimer == -1) syncTimer = SYNC_RATE;
            pendingTemp = currentTemp;
        }

        if (syncTimer >= 0) {
            if (--syncTimer == -1) {
                this.syncedTemp = pendingTemp;
            }
        }
    }

