            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(ResonanceCrystalBlock.POWERED, this.active > 0), 3);
        }
    }

public void tick() {
        if (hackComplete) return;

        isStarted = true;

        if (stopWormTimer > 0) {
            stopWormTimer--;
        }
        if (nukeVirusCooldown > 0) {
            nukeVirusCooldown--;
        }

        allConnections.clear();
        int nonNullNodes = 0;
        int completeNodes = 0;
        for (int i = 0; i < nodes.length; i++) {
            Node node = getNodeAt(i);
            if (node == null) continue;
            nonNullNodes++;

            int f = node.fortification;
            node.tick();
            if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
                controller.onNodeFortified(this, i);
            }

            if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
                // start the trace to all neighbouring nodes
                for (int neighbourPos : getNeighbours(i)) {
                    Node neighbourNode = getNodeAt(neighbourPos);
                    if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                        // found an unhacked neighbour
                        node.startHacking(i, neighbourPos);
                    }
                }
            }

            if (pendingNukePos == i) {
                activateNukeVirus(i);
            }

            // update all in-progress connections
            int finishedConns = 0;
            for (Pair<Integer, Float> conn : node.outGoingHacks) {
                if (conn.getValue() < 1F) {
                    if (stopWormTimer == 0) {
                        Node targetNode = getNodeAt(conn.getKey());
                        if (targetNode != null) {
                            conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                            targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                        }
                    }
                } else {
                    finishedConns++;
                }
                allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
            }
            if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
        }
        if (completeNodes >= nonNullNodes) {
            hackComplete = true;
        }
    }

@Override
    public void tick() {
        super.tick();

        this.setDeltaMovement(0D, 0D, 0D);

        if (this.level().isClientSide()) {
            if (this.getLifetime() - this.tickCount > 1) {
                var random = this.random;
                var radius = this.getRadius();

                var x = this.getX() + MathUtils.randomFloat(random) * radius;
                var z = this.getZ() + MathUtils.randomFloat(random) * radius;

                this.level().addParticle(new GhostlyFogParticle.Options(this.getLifetime() - this.tickCount - 1),
                        x,
                        this.getY() + random.nextDouble() * 2,
                        z,
                        MathUtils.randomFloat(random) * 0.01F,
                        -0.025F,
                        MathUtils.randomFloat(random) * 0.01F);
            }

            return;
        }

        if (this.tickCount > this.getLifetime()) {
            this.discard();

            return;
        }

        var owner = this.getOwner();
        var radius = this.getRadius();
        var gameTime = this.level().getGameTime();

        if (lastExposureCleanupTick != gameTime && gameTime % 200L == 0L) {
            lastExposureCleanupTick = gameTime;

            LAST_EXPOSURE_TICK.values().removeIf(tick -> tick < gameTime - 200L);
        }

        for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius),
                entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, this.getStack(), "fog"))) {
            target.getPersistentData().putFloat(GhostlyMantleItem.FOG_SUFFOCATION_DAMAGE_TAG, this.getSuffocationDamage());
            target.getPersistentData().putLong(GhostlyMantleItem.FOG_SUFFOCATION_UNTIL_TAG, this.level().getGameTime() + 5L);

            if (this.getAirDrain() > 0)
                target.setAirSupply(Math.max(-20, target.getAirSupply() - this.getAirDrain()));

            if (this.getTremorTicks() > 0)
                TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.TREMOR, this.getTremorTicks(), 0, false, false), owner, this.getStack(), "fog");

            if (target.getAirSupply() <= -20 && this.tickCount % 20 == 0)
                target.hurt(this.level().damageSources().inWall(), 1F);

            if (owner == null)
                continue;

            var key = owner.getStringUUID() + ":" + target.getStringUUID();

            if (LAST_EXPOSURE_TICK.getOrDefault(key, Long.MIN_VALUE) == gameTime)
                continue;

            LAST_EXPOSURE_TICK.put(key, gameTime);

            for (var stack : EntityUtils.findEquippedCurios(owner, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("fog");

                if (!ability.canPlayerUse(owner))
                    continue;

                ability.getStatisticData().getMetricData("fog_exposure").addValue(1D / 20D);
                relic.getRelicData(owner, stack).getLevelingData().addExperience("fog", "fog_exposure", 1D / 20D);

                break;
            }
        }
    }

@Override
        public void tick(LivingEntity entity) {
            if(isRush()) {
                int standingOnY = Mth.floor(entity.getY()) - 3;
                double headY = entity.getY() + 2.0D;
                float yawRadians = (float) (Math.toRadians(90 + entity.getYRot()));
                int temp = getTimer();

                    setTimer(temp - 1);
                    //Deal with rocket punch is valid
                    if (temp > 0) {
                        double yaw = Math.toRadians(entity.getYRot() + 90);
                        double xExpand = 3 * Math.cos(yaw);
                        double zExpand = 3 * Math.sin(yaw);
                        AABB attackRange = entity.getBoundingBox().expandTowards(xExpand, 0, zExpand);
                        for (LivingEntity target : entity.level().getEntitiesOfClass(LivingEntity.class, attackRange)) {
                            if (!target.isAlliedTo(entity) && target != entity) {
                                target.hurt(entity.damageSources().mobAttack(entity), getdamage());

                            }
                        }


                        if(temp % 2 ==0){
                            this.spawnFangs(entity.getX(), headY, entity.getZ(), standingOnY, yawRadians, 1, entity.level(), entity);
                            double x = entity.getX();
                            double y = entity.getY() + entity.getBbHeight() / 2;
                            double z = entity.getZ();
                            float yaw2 = (float) Math.toRadians(-entity.getYRot());
                            float yaw3 = (float) Math.toRadians(-entity.getYRot() + 180);
                            entity.level().addParticle(new RingParticleOptions(yaw2, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                            entity.level().addParticle(new RingParticleOptions(yaw3, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                        }
                    }

                    if (temp == 0) {
                        setRush(false);

                }
            }
        }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity target = result.getEntity();
        Entity shooter = this.getOwner();

        float motion = (float) this.getDeltaMovement().length();
        int damage = Mth.ceil(Mth.clamp((double) motion * 0.5F * this.getBaseDamage(), 0.0D, 2.147483647E9D));

        DamageSource damagesource = UPDamageTypes.shuriken(this.level(), this, shooter);

        if (shooter instanceof LivingEntity living) {
            living.setLastHurtMob(target);
        }

        boolean isEnderman = target.getType() == EntityType.ENDERMAN;
        if (this.isOnFire() && !isEnderman) {
            target.setSecondsOnFire(5);
        }

        if (target.hurt(damagesource, (float) damage)) {
            if (isEnderman) return;

            if (target instanceof LivingEntity livingTarget) {

                if (!this.level().isClientSide() && shooter instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingTarget, shooter);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) shooter, livingTarget);
                }

                this.doPostHurtEffects(livingTarget);
                if (livingTarget != shooter && livingTarget instanceof Player && shooter instanceof ServerPlayer && !this.isSilent()) {
                    ((ServerPlayer) shooter).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

            }

            this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.25F / (this.random.nextFloat() * 0.2F + 0.9F));
        }
        else {
            target.setRemainingFireTicks(target.getRemainingFireTicks());
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            this.setYRot(this.getYRot() + 180.0F);
            this.yRotO += 180.0F;
            if (!this.level().isClientSide() && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }
                this.discard();
            }
        }
    }

@Override
    protected void onHitEntity(EntityHitResult pResult) {
        if (!this.level.isClientSide) {
            Entity entity = pResult.getEntity();
            if (this.getSpearLevel() > 0) {
                if (this.piercingIgnoreEntityIds == null) {
                    this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
                }

                if (this.piercedAndKilledEntities == null) {
                    this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
                }

                if (this.piercingIgnoreEntityIds.size() >= this.getSpearLevel() + 1) {
                    this.discard();
                    return;
                }

                this.piercingIgnoreEntityIds.add(entity.getId());
            }
            Entity entity1 = this.getOwner();
            boolean flag;
            float damage = entity1 instanceof Mob mob ? (float) MobUtil.getAttributeValue(mob, Attributes.ATTACK_DAMAGE, 2.0D) : SpellConfig.PoisonDartDamage.get().floatValue();
            damage += this.getExtraDamage();
            if (entity1 instanceof LivingEntity livingentity) {
                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }
                flag = entity.hurt(this.damageSources().arrow(this, entity1), damage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    }
                }
            } else {
                flag = entity.hurt(this.damageSources().arrow(this, this), damage);
            }
            if (flag && entity.getType() != EntityType.ENDERMAN && entity instanceof LivingEntity livingEntity) {
                if (entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingEntity, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingEntity);
                }

                this.doPostHurtEffects(livingEntity);

                MobEffect mobEffect = MobEffects.POISON;
                if ((entity1 instanceof IOwned owned && CuriosFinder.hasWildRobe(owned.getMasterOwner()))
                        || (entity1 instanceof LivingEntity livingEntity1 && CuriosFinder.hasWildRobe(livingEntity1))) {
                    mobEffect = GoetyEffects.ACID_VENOM.get();
                }
                livingEntity.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(2 + this.getDuration())));

                this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (this.getSpearLevel() <= 0) {
                    this.discard();
                }
            }
        }
    }

@Override
	public void onUpdate() {
		this.world.profiler.startSection("entityBaseTick");

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		this.motionX = 0;
		this.motionZ = 0;
		this.lastTickPosX = this.posX;
		this.lastTickPosY = this.posY;
		this.lastTickPosZ = this.posZ;

		if(this.ticksExisted >= this.delay) {
			if(this.world.isRemote && this.ticksExisted == this.delay) {
				this.spawnEmergeParticles();
				this.world.playSound(this.posX, this.posY, this.posZ, SoundRegistry.SPIRIT_TREE_SPIKES, SoundCategory.HOSTILE, 0.7F, 0.9F + this.rand.nextFloat() * 0.2F, false);
			}
			if(this.ticksExisted == this.delay && this.motionY <= 0.0D) {
				this.motionY += 0.25D;
			} else {
				this.motionY -= 0.05D;

				if(!this.world.isRemote && (this.posY <= this.origin.getY() || this.onGround)) {
					this.setDead();
				}
			}
		} else {
			this.motionY = 0.0D;
		}

		if(this.posY < -64.0D) {
			this.setDead();
		}

		if(this.posY + this.motionY <= this.origin.getY()) {
			this.motionY = 0.0D;
			this.setLocationAndAngles(this.posX, this.origin.getY(), this.posZ, 0, 0);
		} else {
			this.move(MoverType.SELF, 0, this.motionY, 0);
		}

		if(this.motionY > 0.1D && !this.world.isRemote) {
			DamageSource damageSource = new EntityDamageSource("bl.spikewave", this);
			for(BlockPos pos : this.positions) {
				AxisAlignedBB aabb = new AxisAlignedBB(pos).offset(this.posX - (this.origin.getX() + 0.5D), this.posY - this.origin.getY(), this.posZ - (this.origin.getZ() + 0.5D)).shrink(0.1D).offset(0, 0.2D, 0);
				List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, aabb);
				for(EntityLivingBase entity : entities) {      
					if (entity instanceof EntityLivingBase) {    
						entity.attackEntityFrom(damageSource, this.attackDamage);
					}
				}
			}
		}

		this.renderingBounds = this.blockEnclosingBounds.offset(this.posX - (this.origin.getX() + 0.5D), this.posY - this.origin.getY(), this.posZ - (this.origin.getZ() + 0.5D));

		this.firstUpdate = false;
		this.world.profiler.endSection();
	}

