public void tick() {
        super.tick();
        prevGroundProgress = groundProgress;
        prevBiteProgress = biteProgress;
        if (this.onGround() && groundProgress < 5.0F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0.0F) {
            groundProgress--;
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (biteProgress < 5F) {
                biteProgress++;
            }
        } else {
            if (biteProgress > 4 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 1.3D) {
                this.getTarget().hurt(damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            }
            if (biteProgress > 0F) {
                biteProgress--;
            }
        }
        if (!level().isClientSide) {
            float delta = (float) this.getDeltaMovement().horizontalDistance();
            if (crawling || !this.isInWaterOrBubble()) {
                timeSwimming = 0;
                if(delta > 0.01F){
                    if(tickCount - lastStepSoundTimestamp > 10){
                        lastStepSoundTimestamp = tickCount;
                        this.playSound(ACSoundRegistry.TRILOCARIS_STEP.get(), 0.2F, 1.0F);
                    }

                }
            } else {
                timeSwimming++;
            }
        }
    }

public void tick(Level level, BlockPos pos, BlockState state) {
        if (!level.isClientSide && activity > 0 && level.getGameTime() % getRate() == 0) {
            int intensity = getIntensity();
            Vec3 origin = Vec3.atCenterOf(pos);

            for (int i = 0; i < intensity; i++) {
                Vec3 target = getTarget(step + i);
                BlockHitResult result = raytrace(level, origin, origin.add(target));

                if (result.getType() != HitResult.Type.MISS) {
                    BlockPos hitPos = result.getBlockPos();
                    BlockState hitState = level.getBlockState(hitPos);

                    breakBlock(level, hitPos, hitState);

                    int minY = level.getMinBuildHeight();
                    BlockPos spawnPos = traceDown(hitPos, minY, level);
                    BlockState spawnState = level.getBlockState(spawnPos);

                    if (canReplace(spawnState)) {
                        if (level.getRandom().nextFloat() < spawnRatio) {
                            if (spawnPos.getY() < minY + spawnYLimit) {
                                spawnOre(spawnPos);
                            }
                        } else {
                            spawnMob(spawnPos);
                        }
                    } else {
                        breakBlock(level, spawnPos, spawnState);
                    }
                }
            }

            ((ServerLevel) level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, FracturedBedrockBlock.instance.defaultBlockState()),
                    worldPosition.getX() + 0.5, worldPosition.getY() + 1.1, worldPosition.getZ() + 0.5,
                    8, 0, level.random.nextGaussian() * 0.1, 0, 0.1);

            step += intensity;
            activity -= intensity;

            if (shouldDeplete()) {
                level.setBlock(getBlockPos(), DepletedBedrockBlock.instance.defaultBlockState(), 2);
            }
        }

        if (!level.isClientSide && activity > 0 && this.level.getGameTime() % 80 == 0) {
            playSound();
        }
    }

@Override
	public void tick() {
		super.tick();

		if (this.isEffectiveAi()) {
			if (this.isPassenger()) {
				this.setYRot(0.0F);
				this.setXRot(0.0F);
				this.setAirSupply(this.getMaxAirSupply());
			} else if (this.isInWater() && this.getNavigation().isDone()) {
				float yaw = this.getYRot();
				float pitch = this.getXRot();
				float pitchFactor = Mth.cos(pitch * ((float) Math.PI / 180F));
				float x = -Mth.sin(yaw * ((float) Math.PI / 180F)) * pitchFactor;
				float y = -Mth.sin(pitch * ((float) Math.PI / 180F));
				float z = Mth.cos(yaw * ((float) Math.PI / 180F)) * pitchFactor;
				Vec3 motion = new Vec3(x, y, z).normalize().scale(0.01666666666F);
				this.push(motion.x, motion.y, motion.z);
			}

			if (!this.level().isClientSide && (Mth.abs(this.xRotO - this.getXRot()) >= 1.0F || Mth.abs(this.yRotO - this.getYRot()) >= 1.0F)) {
				this.hasImpulse = true;
			}
		}

		if (this.hasCooldown()) {
			if (this.isEffectiveAi()) {
				this.setCooldown(this.getCooldown() - 1);
				if (!this.hasCooldown()) {
					this.playSound(UASoundEvents.JELLYFISH_COOLDOWN_END.get(), 1.0F, this.random.nextFloat() * 0.15F + 1.0F);
				}
			}

			if (this.level().isClientSide && this.level().getGameTime() % 4 == 0) {
				for (int i = 0; i < 2; i++) {
					this.level().addParticle(JellyTorchType.getBlobParticleType(this.getJellyTorchType()), this.getRandomX(0.5D), this.getY() + this.getEyeHeight(), this.getRandomZ(0.5D), makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()), -this.random.nextDouble() * 0.05F, makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()));
				}
			}
		}

		if (this.isAlive()) {
			for (LivingEntity entities : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.15D), CAN_STING)) {
				if (entities.isAlive()) {
					this.stingEntity(entities);
				}
			}

			if (this.isInWater() && this.isNoEndimationPlaying()) {
				this.setDeltaMovement(this.getDeltaMovement().subtract(0.0F, 0.005F, 0.0F));
			}
		}
	}

