@Override
    public void tick() {
        super.tick();
        BlockPos target = getMoveToTarget();
        if (target != null) {
            if (isReachedTarget()) {
                if (relicheirus.lockTreePosition(blockPos)) {
                    if (relicheirus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        relicheirus.setPeckY(blockPos.getY());
                        relicheirus.setAnimation(RelicheirusEntity.ANIMATION_PUSH_TREE);
                    } else if (relicheirus.getAnimation() == RelicheirusEntity.ANIMATION_PUSH_TREE) {
                        if (relicheirus.getAnimationTick() >= 35 && !madeTreeEntity) {
                            madeTreeEntity = true;
                            relicheirus.playSound(ACSoundRegistry.RELICHEIRUS_TOPPLE.get());
                            List<BlockPos> gathered = new ArrayList<>();
                            gatherAttachedBlocks(blockPos, blockPos, gathered);
                            if (!gathered.isEmpty()) {
                                List<MovingBlockData> allData = new ArrayList<>();
                                for (BlockPos pos : gathered) {
                                    BlockState moveState = relicheirus.level().getBlockState(pos);
                                    BlockEntity te = relicheirus.level().getBlockEntity(pos);
                                    BlockPos offset = pos.subtract(blockPos);
                                    MovingBlockData data = new MovingBlockData(moveState, moveState.getShape(relicheirus.level(), pos), offset, te == null ? null : te.saveWithoutMetadata());
                                    relicheirus.level().removeBlockEntity(pos);
                                    allData.add(data);
                                }
                                for (BlockPos pos : gathered) {
                                    relicheirus.level().setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
                                }
                                FallingTreeBlockEntity fallingTree = ACEntityRegistry.FALLING_TREE_BLOCK.get().create(relicheirus.level());
                                fallingTree.moveTo(Vec3.atCenterOf(blockPos));
                                fallingTree.setAllBlockData(FallingTreeBlockEntity.createTagFromData(allData));
                                fallingTree.setPlacementCooldown(1);
                                Vec3 vec3 = Vec3.atCenterOf(blockPos).subtract(relicheirus.position());
                                float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
                                fallingTree.setFallDirection(Direction.fromYRot(f));
                                relicheirus.level().addFreshEntity(fallingTree);
                            }
                        }
                    }
                }
            } else {
                if (relicheirus.getNavigation().isDone()) {
                    Vec3 vec31 = Vec3.atCenterOf(target);
                    Vec3 vec32 = vec31.subtract(relicheirus.position());
                    if (vec32.length() > 1) {
                        vec32 = vec32.normalize();
                    }
                    Vec3 delta = new Vec3(vec32.x * 0.1F, 0F, vec32.z * 0.1F);
                    relicheirus.setDeltaMovement(relicheirus.getDeltaMovement().add(delta));
                }
            }
        }
    }

public void tick() {
        if (tossItemCooldown > 0) {
            tossItemCooldown--;
        }
        if (checkReachCooldown > 0) {
            checkReachCooldown--;
        }
        if (checkReachCooldown == 0) {
            checkReachCooldown = 100 + mob.getRandom().nextInt(40);
            if (mob.canTeleport() && !mob.canReach(cruciblePos)) {
                mob.setTeleportingToPos(Vec3.atCenterOf(cruciblePos.relative(Util.getRandom(ACMath.HORIZONTAL_DIRECTIONS, mob.getRandom()))));
                return;
            }
        }
        Vec3 center = Vec3.atCenterOf(cruciblePos);
        double distance = Vec3.atBottomCenterOf(cruciblePos).subtract(mob.position()).horizontalDistance();
        if (distance < 8.0D) {
            mob.getLookControl().setLookAt(center.x, center.y + 1.0F - Math.sin(cookTime * 0.2F) * 0.2F, center.z, 10.0F, (float) this.mob.getMaxHeadXRot());
        }
        if (distance > 2.5D) {
            mob.getNavigation().moveTo(cruciblePos.getX() + 0.5F, cruciblePos.getY(), cruciblePos.getZ() + 0.5F, 1);
        } else {
            if (distance < 1.25D) {
                mob.getMoveControl().strafe(0.1F, 0F);
            } else {
                mob.getMoveControl().strafe(0F, 0F);
            }
            mob.setLastCruciblePos(cruciblePos);
            mob.getNavigation().stop();
            if (mob.level().getBlockEntity(cruciblePos) instanceof ConversionCrucibleBlockEntity crucibleBlock && hasLineOfSightCrucible()) {
                mob.updateHeldItems = false;
                boolean flag = crucibleBlock.isWitchMode();
                crucibleBlock.setWitchModeDuration(10);
                if (!flag && crucibleBlock.isWitchMode()) {
                    crucibleBlock.rerollWantedItem();
                    crucibleBlock.markUpdated();
                }
                if (mob.areArmsVisuallyCrossed(1.0F) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION && !crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F) {
                    mob.setItemInHand(InteractionHand.MAIN_HAND, crucibleBlock.getWantItem().copy());
                }
                if (!crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F && tossItemCooldown == 0) {
                    if (tossedItem != null) {
                        tossedItem.discard();
                    }
                    if (mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        mob.setAnimation(mob.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                    } else if ((mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && mob.getAnimationTick() == 4) {
                        mob.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                        Vec3 from = mob.getSwingArmPosition();
                        ItemStack stack = crucibleBlock.getWantItem().copy();
                        tossedItem = new ItemEntity(mob.level(), from.x, from.y, from.z, stack);
                        Vec3 delta = center.subtract(from).normalize().scale(0.13F).add(0, 0.4F, 0);
                        tossedItem.setNeverPickUp();
                        tossedItem.setDeltaMovement(delta);
                        tossedItem.checkDespawn();
                        mob.level().addFreshEntity(tossedItem);
                        tossItemCooldown = 50;
                    }
                }
                cookTime++;
            }
        }
    }

@Override
    public void tick() {
        if (tickCount % 20 == 0) {
            if (!isDormant || level().isClientSide()
                    || !onGround() || isDeadOrDying()
                    || isPassenger() || !getPassengers().isEmpty()
                    || level().getNearestPlayer(this, 32) != null) {
                tickRate = 1;
            } else {
                tickRate = DORMANT_TICK_RATE;
            }
        }

        if (tickCount % tickRate != 0) {
            return;
        }
        super.tick();

        if (isInWater()) {
            ticksInAir = 0;
        } else if (!onGround()) {
            ticksInAir++;
        } else {
            if (ticksInAir > 0) {
                playSound(getLandingSound(), getSoundVolume(), getVoicePitch());
                ticksInAir = 0;
            }
        }

        if (attackCooldown > 0) {
            attackCooldown--;
        }
    }

public void tick() {
        tickMultipart();
        super.tick();
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        prevLandProgress = landProgress;
        prevFishPitch = fishPitch;
        prevPulseAmount = pulseAmount;
        float targetFishPitch = Mth.clamp((float) this.getDeltaMovement().y * 2F, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI);
        if(!isAlive()){
            targetFishPitch = 0.0F;
        }
        fishPitch = Mth.approachDegrees(fishPitch, targetFishPitch, 2.5F);
        boolean grounded = this.onGround() && !isInWaterOrBubble();
        if (grounded && landProgress < 5F) {
            landProgress++;
        }
        if (!grounded && landProgress > 0F) {
            landProgress--;
        }
        float pulseBy = getInterestLevel() * 0.45F;
        pulseAmount += pulseBy;
        if (!level().isClientSide) {
            double waterHeight = getFluidTypeHeight(ForgeMod.WATER_TYPE.get());
            if (waterHeight > 0 && waterHeight < this.getBbHeight() - 1.0F) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.05, 0));
            }
        }
        if (this.getAnimation() == HullbreakerEntity.ANIMATION_BASH && this.getAnimationTick() > 10 && this.getAnimationTick() <= 20) {
            breakBlock();
        }
        if (blockBreakCooldown > 0) {
            blockBreakCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public boolean doHurtTarget(ServerLevel serverLevel, Entity toAttack) {
		if (toAttack instanceof LivingEntity living && living.isBlocking()) {
			if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.CHARGE) {
				Vec3 motion = this.getDeltaMovement();
				toAttack.push(motion.x() * 1.5D, 0.5D, motion.z() * 1.5D);
				this.push(motion.x() * -1.25D, 0.5D, motion.z() * -1.25D);
				if (toAttack instanceof ServerPlayer player) {
					player.getUseItem().hurtAndBreak(5, player, player.getUsedItemHand());
					PacketDistributor.sendToPlayer(player, new MovePlayerPacket(motion.x() * 3.0D, motion.y() + 0.75D, motion.z() * 3.0D));
				}
				this.hurt(this.damageSources().generic(), 2.0F);
				this.level().playSound(null, toAttack.blockPosition(), SoundEvents.SHIELD_BLOCK.value(), SoundSource.PLAYERS, 1.0F, 0.8F + this.level().getRandom().nextFloat() * 0.4F);
				this.getMovementPattern().doDaze();
				return false;
			} else if (this.getMovementPattern().getState() == NagaMovementPattern.MovementState.STUNLESS_CHARGE) {
				if (toAttack instanceof ServerPlayer player) {
					player.getUseItem().hurtAndBreak(10, player, player.getUsedItemHand());
					player.getCooldowns().addCooldown(player.getUseItem(), 200);
					player.stopUsingItem();
					this.level().broadcastEntityEvent(player, (byte) 30);
				}
				living.hurt(this.damageSources().mobAttack(this), 4.0F);
				this.playSound(SoundEvents.FOX_BITE, 2.0F, 0.5F);
				this.getMovementPattern().doCircle();
				return false;
			}
		}
		if (!this.isDazed()) {
			boolean result = super.doHurtTarget(serverLevel, toAttack);

			if (result) {
				// charging, apply extra pushback
				toAttack.push(-Mth.sin((getYRot() * Mth.PI) / 180.0F) * 2.0F, 0.4F, Mth.cos((getYRot() * Mth.PI) / 180.0F) * 2.0F);
			}

			return result;
		}
		return false;
	}

default boolean isCoolingDown(World world, ItemStack stack) {
