public void itemReceived(DisplayLinkBlockEntity be, int amount) {
		if (be.getBlockState()
			.getOptionalValue(DisplayLinkBlock.POWERED)
			.orElse(true))
			return;

		CompoundTag conf = be.getSourceConfig();
		long gameTime = be.getLevel()
			.getGameTime();

		if (!conf.contains("LastReceived")) {
			conf.putLong("LastReceived", gameTime);
			return;
		}

		long previousTime = conf.getLong("LastReceived");
		ListTag rates = conf.getList("PrevRates", Tag.TAG_FLOAT);

		if (rates.size() != POOL_SIZE) {
			rates = new ListTag();
			for (int i = 0; i < POOL_SIZE; i++)
				rates.add(FloatTag.valueOf(-1));
		}

		int poolIndex = conf.getInt("Index") % POOL_SIZE;
		rates.set(poolIndex, FloatTag.valueOf((float) (amount / (double) (gameTime - previousTime))));

		float rate = 0;
		int validIntervals = 0;
		for (int i = 0; i < POOL_SIZE; i++) {
			float pooledRate = rates.getFloat(i);
			if (pooledRate >= 0) {
				rate += pooledRate;
				validIntervals++;
			}
		}

		conf.remove("Rate");
		if (validIntervals > 0) {
			rate /= validIntervals;
			conf.putFloat("Rate", rate);
		}

		conf.remove("Inactive");
		conf.putInt("LastReceivedAmount", amount);
		conf.putLong("LastReceived", gameTime);
		conf.putInt("Index", poolIndex + 1);
		conf.put("PrevRates", rates);
		be.updateGatheredData();
	}

@Override
  public void onInventoryTick(IToolStackView tool, ModifierEntry modifier, Level world, LivingEntity holder, int itemSlot, boolean isSelected, boolean isCorrectSlot, ItemStack stack) {
    // overslime increases every 2^(4-level) seconds
    // that is 1 per second at 4 levels, 1 per 8 seconds at 1 level
    // we support max level 6, as that leaves us working with integers
    int level = Math.min(modifier.getLevel(), 6);
    int updateInterval = 5 << (6 - level);

    // don't run if drawing back a bow, prevents losing animation
    // does mean you may end up wasting some fuel, could be as much as 19 lost. So, don't hold your bows for 20 updates?
    if (!world.isClientSide && holder.tickCount % updateInterval == 0 && holder.getUseItem() != stack) {
      // must have overslime and space to fill
      if (OverslimeModule.INSTANCE.getAmount(tool) < OverslimeModule.getCapacity(tool)) {
        // find current fuel info
        ResourceLocation key = modifier.getId();
        FuelInfo info = FuelInfo.read(tool, key);

        // if we have no fuel, try and find some
        boolean neededFuel = info == null;
        // since we will write this to NBT, use game time as that is global
        long time = holder.level().getGameTime();
        if (neededFuel || info.expiration < time) {
          info = null;
          FluidStack fluid = ToolTankHelper.TANK_HELPER.getFluid(tool);
          if (!fluid.isEmpty()) {
            MeltingFuel fuel = MeltingFuelLookup.findFuel(fluid.getFluid());
            if (fuel != null) {
              // scale amount consumed by level
              int amount = fuel.getAmount(fluid.getFluid());
              // scale up fuel duration so we always get the same amount of overslime per fuel bucket
              // if we didn't do this, lower levels would consume way more than higher ones
              // this works out to equivalent to the alloyer/melter at level 4
              // note this does mean changing trait levels multiplies fuel efficiency, but the part swap costs more than just adding a slimeball so its fine
              int duration = fuel.getDuration() * updateInterval / 5;
              // if we don't have a full recipe, use what is left but scale down the duration
              if (amount > fluid.getAmount()) {
                ToolTankHelper.TANK_HELPER.setFluid(tool, FluidStack.EMPTY);
                duration = duration * fluid.getAmount() / amount;
              } else {
                // if we have a complete recipe, just decrease fluid in the tank
                fluid.shrink(amount);
                ToolTankHelper.TANK_HELPER.setFluid(tool, fluid);
              }
              info = new FuelInfo(time + duration, fuel.getRate());
            }
          }
          // store current fuel in NBT for next round if it will last
          // no need to store if it will expire before our next update tick though
          if (info != null && info.expiration >= time + updateInterval) {
            info.write(tool, key);
          } else if (!neededFuel) {
            // no need to remove if we had nothing, saves some hash map modifications
            tool.getPersistentData().remove(key);
          }
        }
        // if we have fuel, increase overslime
        if (info != null) {
          // restore 1 per 10 rate. For the remainder, treat it as a chance
          int restore = info.rate / 10;
          int remainder = info.rate % 10;
          if (remainder > 0 && Modifier.RANDOM.nextInt(10) < remainder) {
            restore++;
          }
          OverslimeModule.INSTANCE.addAmount(tool, restore);
        }
      }
    }
  }

@SubscribeEvent
        public static void onLivingHurt3(LivingDamageEvent.Pre event) {
            if (!(event.getSource().getEntity() instanceof LivingEntity attacker))
                return;

            var rings = EntityUtils.findEquippedCurios(attacker, RelicsItems.RING_OF_THE_SEVEN_DEADLY_SINS.get(), stack -> {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                return relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").canPlayerUse(attacker);
            });

            if (rings.isEmpty())
                return;

            var now = attacker.level().getGameTime();
            var baseDamage = event.getNewDamage();
            var totalModifier = 1D;
            var ringModifiers = new ArrayList<Double>(rings.size());

            for (var stack : rings) {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                if (!TargetingUtils.canHarm(attacker, event.getEntity(), stack, "wrath")) {
                    ringModifiers.add(1D);
                    continue;
                }

                var windowTicks = Math.max(1, (int) Math.round(relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("window").getValue() * 20D));
                var state = stack.getOrDefault(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), WrathData.create(now));
                var delta = now - state.lastHitTick();

                double modifier = 1D;

                if (delta < windowTicks) {
                    var mid = windowTicks / 2D;
                    var earlyMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("early_multiplier").getValue();
                    var lateMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("late_multiplier").getValue();

                    if (delta <= mid) {
                        var t = delta / mid;
                        var start = 1D + earlyMultiplier;

                        modifier = start + (1D - start) * t;
                    } else {
                        var t = (delta - mid) / Math.max(1D, windowTicks - mid);
                        var end = 1D - lateMultiplier;

                        modifier = 1D + (end - 1D) * t;
                    }
                }

                ringModifiers.add(modifier);
                totalModifier *= modifier;
            }

            event.setNewDamage((float) (baseDamage * totalModifier));

            for (var i = 0; i < rings.size(); i++) {
                var stack = rings.get(i);
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();
                var modifier = ringModifiers.get(i);
                var extraDamage = baseDamage * (modifier - 1D);

                relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("windows").addValue(1);
                relic.getRelicData(attacker, stack).getLevelingData().addExperience("wrath", "timing", Math.abs(extraDamage));

                if (extraDamage > 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("bonus_damage").addValue(extraDamage);
                else if (extraDamage < 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("reduced_damage").addValue(Math.abs(extraDamage));

                stack.set(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), new WrathData(now));
            }
        }

@Override
    public boolean canContinueToUse() {
        if (ticksRunning >= 20 * 15) {
            starbuncle.addGoalDebug(this, new DebugEvent("BedTimeout", "Took too long to find bed"));
            starbuncle.goalState = Starbuncle.StarbuncleGoalState.NONE;
            return false;
        }

        if (bedPos == null || starbuncle.data.bedPos == null)
            return false;

        boolean bedValid = true;
        boolean isOnBed = false;
        // Time defer these checks otherwise we will destroy TPS with blockstate lookups.
        if (starbuncle.level.getGameTime() % 10 == 0) {
            bedValid = isBedValid();
            isOnBed = isOnBed();
        }

        return !unreachable && bedValid && !isOnBed;
    }

public boolean searchMovedStructure(Level world, BlockPos pos, @Nullable Direction forcedDirection)
		throws AssemblyException {
		initialPassengers.clear();
		Queue<BlockPos> frontier = new UniqueLinkedList<>();
		Set<BlockPos> visited = new HashSet<>();
		anchor = pos;

		if (bounds == null)
			bounds = new AABB(BlockPos.ZERO);

		if (!BlockMovementChecks.isBrittle(world.getBlockState(pos)))
			frontier.add(pos);
		if (!addToInitialFrontier(world, pos, forcedDirection, frontier))
			return false;
		for (int limit = 100000; limit > 0; limit--) {
			if (frontier.isEmpty())
				return true;
			if (!moveBlock(world, forcedDirection, frontier, visited))
				return false;
		}
		throw AssemblyException.structureTooLarge();
	}

@Override
	public NBTTagCompound writeToNBT(NBTTagCompound compound) {

		compound.setBoolean("activated", this.activated);
		compound.setBoolean("conquered", this.conquered);
		compound.setLong("regenerationTime", this.regenerationTime);
		compound.setLong("lastRegenerationTime", this.lastRegenerationTime);
		if (shrineElement != null) compound.setInteger("shrineElement", this.shrineElement.ordinal());
		if (linkedContainer != null)
			NBTExtras.storeTagSafely(compound, "linkedContainerPos", NBTUtil.createPosTag(linkedContainer.getPos()));

		NBTTagList wizardTagList = new NBTTagList();
		for (UUID uuid : linkedWizards) {
			if (uuid != null) wizardTagList.appendTag(NBTUtil.createUUIDTag(uuid));
		}
		NBTExtras.storeTagSafely(compound, "wizards", wizardTagList);

		NBTTagList playerTagList = new NBTTagList();
		for (UUID uuid : lootedPlayers) {
			playerTagList.appendTag(NBTUtil.createUUIDTag(uuid));
		}
		NBTExtras.storeTagSafely(compound, "lootedPlayers", playerTagList);

		return super.writeToNBT(compound);
	}

private void regenerate() {

		if (world.isRemote) return;

		// Remove containment effects from nearby targets when shrine regenerates
		removeContainmentFromNearbyTargets();

		// Reset shrine state
		this.conquered = false;
		this.regenerationTime = 0;
		this.activated = false;
		Arrays.fill(this.linkedWizards, null);
		// Keep lootedPlayers list - it's permanent for this shrine instance

		// Force a short delay before allowing reactivation to prevent immediate re-activation
		this.lastRegenerationTime = world.getTotalWorldTime();

		// Forcibly replace whatever block is above the altar with a fresh chest
		BlockPos chestPos = this.pos.up();

		// Always replace the block above with a fresh chest during regeneration
		world.setBlockState(chestPos, Blocks.CHEST.getDefaultState());

		// Set up the loot table for the shrine chest
		TileEntity chestTileEntity = world.getTileEntity(chestPos);
		if (chestTileEntity instanceof TileEntityChest) {
			TileEntityChest chest = (TileEntityChest) chestTileEntity;
			chest.setLootTable(new ResourceLocation(Wizardry.MODID, "chests/shrine"), world.rand.nextLong());
		}

		// Link and apply arcane lock to the container
		if (chestTileEntity != null) {
			this.linkContainer(chestTileEntity);
			chestTileEntity.getTileData().setUniqueId(ArcaneLock.NBT_KEY, new UUID(0, 0)); // Nil UUID for shrine lock
			chestTileEntity.markDirty(); // Mark tile entity as dirty for client sync

			// Trigger visual update for arcane lock effect
			IBlockState blockState = world.getBlockState(chestPos);
			world.markAndNotifyBlock(chestPos, null, blockState, blockState, 3);
			world.notifyBlockUpdate(chestPos, blockState, blockState, 3); // Additional client sync
		}

		// Visual and audio effects for regeneration
		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		//	WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
		}

		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

		this.markDirty();
	}

@Override
	public void update() {

		if (this.linkedContainer == null && this.linkedContainerPos != null) {
			this.linkContainer(world.getTileEntity(this.linkedContainerPos));
		}

		// Handle shrine regeneration
		if (conquered && Wizardry.settings.shrineRegenerationEnabled && regenerationTime > 0) {
			if (world.getTotalWorldTime() >= regenerationTime) {
				regenerate();
				return; // Don't process other logic during regeneration
			}
		}

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!activated && !conquered && world.getClosestPlayer(x, y, z, ACTIVATION_RADIUS, false) != null && (lastRegenerationTime == 0 || world.getTotalWorldTime() - lastRegenerationTime > 100)) { // 5 second delay after regeneration

			this.activated = true;

			if (world.isRemote) {
				ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
			}

			world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

			if (!world.isRemote) {

				EntityEvilWizard[] wizards = new EntityEvilWizard[linkedWizards.length];

				for (int i = 0; i < linkedWizards.length; i++) {

					EntityEvilWizard wizard = new EntityEvilWizard(world);

					float angle = world.rand.nextFloat() * 2 * (float) Math.PI;
					double x1 = this.pos.getX() + 0.5 + 5 * MathHelper.sin(angle);
					double z1 = this.pos.getZ() + 0.5 + 5 * MathHelper.cos(angle);
					Integer y1 = BlockUtils.getNearestFloor(world, new BlockPos(x1, this.pos.getY(), z1), 8);
					if (y1 == null) {
						// Fallback to the position of the shrine core if it failed to find a position (unlikely)
						x1 = this.pos.getX() + 1; // Offset it so the wizard isn't inside the block
						y1 = this.pos.getY();
						z1 = this.pos.getZ();
					}

					wizard.setLocationAndAngles(x1, y1 + 0.5, z1, 0, 0);
					wizard.setElement(world.getBlockState(pos).getValue(BlockPedestal.ELEMENT));
					wizard.onInitialSpawn(world.getDifficultyForLocation(pos), null);
					wizard.hasStructure = true;

					world.spawnEntity(wizard);
					wizards[i] = wizard;
					linkedWizards[i] = wizard.getUniqueID();
				}

				for (EntityEvilWizard wizard : wizards) wizard.groupUUIDs.addAll(Arrays.asList(linkedWizards));
			}

			containNearbyTargets();
		}

		if (!areWizardsDead() && activated && world.getTotalWorldTime() % 20L == 0) containNearbyTargets();

		if (activated && areWizardsDead() && !world.isRemote) {
			conquer();
		}
	}

