public VoidVaultState update(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
        return switch (this) {
            case INACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.activationRange());
            case ACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
            case UNLOCKING -> {
                serverData.setStateUpdatingResumeTime(world.getGameTime() + 20L);
                yield EJECTING;
            }
            case EJECTING -> {
                if (serverData.getItemsToEject().isEmpty()) {
                    serverData.finishEjecting();
                    yield updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
                } else {
                    float f = serverData.getEjectSoundPitchModifier();
                    this.ejectItem(world, pos, serverData.getItemToEject(), f);
                    sharedData.setDisplayItem(serverData.getItemToDisplay());
                    boolean bl = serverData.getItemsToEject().isEmpty();
                    int i = bl ? 20 : 20;
                    serverData.setStateUpdatingResumeTime(world.getGameTime() + i);
                    yield EJECTING;
                }
            }
        };
    }

@Override
    public InteractionResult useOn(UseOnContext context) {
        Player player = context.getPlayer();
        InteractionHand hand = context.getHand();
        BlockPos blockpos = context.getClickedPos();
        Direction side = context.getClickedFace();
        if (player != null) {
            ItemStack held = player.getItemInHand(hand);
            if (!held.isEmpty() && held.getItem() instanceof WaystoneItem) {
                player.swing(hand);
                CompoundTag nbt = held.getOrCreateTag();
                nbt.putUUID(TAG_OWNER, player.getUUID());
                nbt.putString(TAG_OWNER_NAME, player.getDisplayName().getString());
                addBlockTags(player.level.dimension(), blockpos, nbt);
                nbt.putInt(TAG_DIRECTION, side.ordinal());
                nbt.putInt(TAG_FACING, player.getDirection().ordinal());
                player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                player.level.playLocalSound(blockpos.getX(), blockpos.getY(), blockpos.getZ(), SoundEvents.ARROW_HIT_PLAYER, SoundSource.PLAYERS, 1.0F, 0.45F, false);
                held.setTag(nbt);
                return InteractionResult.sidedSuccess(player.level.isClientSide);
            }
        }
        return InteractionResult.PASS;
    }

private void tickOrbiting() {
        // But we might want it to follow the owner if not fired yet.
        if (this.dracula == null && this.draculaUUID != null && this.level() instanceof ServerLevel serverLevel) {
            Entity entity = serverLevel.getEntity(this.draculaUUID);
            if (entity instanceof Dracula d) {
                this.dracula = d;
            }
        }

        // orbit Dracula
        if (this.dracula != null && this.dracula.isAlive()) {
            double angle = (this.level().getGameTime() * 0.1) + (this.indexOffset * (Math.PI * 2 / this.maxCount));
            double x = this.dracula.getX() + Math.cos(angle) * 1.5;
            double z = this.dracula.getZ() + Math.sin(angle) * 1.5;
            double y = this.dracula.getY() + 1.5 + Math.sin(this.level().getGameTime() * 0.05 + this.indexOffset) * 0.5;

            this.setPos(x, y, z);
            this.setYRot((float) (angle * (180 / Math.PI)));
            this.yRotO = this.getYRot();
            this.xRotO = this.getXRot();
        } else if (!this.level().isClientSide()) {
            this.discard();
        }
    }

@Override
    public void tick() {
        super.tick();
        if (level instanceof ServerLevel && level.getGameTime() % 20 == 0 && this.canAcceptSource()) {
            BlockPos potionPos = findNearbyPotion(level, worldPosition);
            if (potionPos != null && level.getBlockEntity(potionPos) instanceof PotionJarTile tile) {
                int source = 75;
                Set<MobEffect> effectTypes = new HashSet<>();
                for (MobEffectInstance e : tile.getData().getAllEffects()) {
                    source += (e.getDuration() / 50);
                    source += e.getAmplifier() * 250;
                    source += 150;
                    effectTypes.add(e.getEffect().value());
                }
                if (effectTypes.size() > 1) {
                    source *= Math.pow(2.1, effectTypes.size());
                }
                if (source > 0 && canAcceptSource(source) || this.getSource() <= 0) {
                    addSource(source);
                    tile.remove(100);
                }
            }
        }
    }

