private static void freezeNearbyWater(LivingEntity entity, Level level, BlockPos pos, int amplifier) {
    if (!entity.onGround()) { return; }
    BlockState frostedIce = Blocks.FROSTED_ICE.defaultBlockState();
    float radius = Math.min(16, 2 + amplifier);
    BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();
    for (BlockPos blockPos : BlockPos.betweenClosed(
        pos.offset(-(int) radius, -1, -(int) radius),
        pos.offset((int) radius, -1, (int) radius)
    )) {
      if (blockPos.closerToCenterThan(entity.position(), radius)) {
        mutablePos.set(blockPos.getX(), blockPos.getY() + 1, blockPos.getZ());
        BlockState above = level.getBlockState(mutablePos);
        if (above.isAir()) {
          BlockState below = level.getBlockState(blockPos);
          boolean isWater = below.is(Blocks.WATER) && below.getValue(LiquidBlock.LEVEL) == 0;
          if (isWater && frostedIce.canSurvive(level, blockPos)
              && level.isUnobstructed(frostedIce, blockPos, CollisionContext.empty())
              && level.mayInteract(entity instanceof Player p ? p : null, blockPos)) {
            level.setBlockAndUpdate(blockPos, frostedIce);
            level.scheduleTick(blockPos, Blocks.FROSTED_ICE, Mth.nextInt(entity.getRandom(), 60, 120));
          }
        }
      }
    }
  }

public static void serverTick(Level level, BlockPos pos, BlockState state, SunscreenBeaconBlockEntity blockEntity) {
        if (level.getGameTime() % 80L == 0L) {
            //Position check is probably not necessary, but not sure
            if (blockEntity.oldPos == null || blockEntity.selector == null || !blockEntity.oldPos.equals(pos)) {
                blockEntity.oldPos = pos;
                final BlockPos center = new BlockPos(pos.getX(), 0, pos.getZ());
                final int distSq = ModConfig.server().sunscreenBeaconRadius.get() * ModConfig.server().sunscreenBeaconRadius.get();
                blockEntity.selector = input -> {
                    if (input == null) return false;
                    BlockPos player = new BlockPos((int) input.getX(), 0, (int) input.getZ());
                    return player.distSqr(center) < distSq;
                };
            }

            List<? extends Player> list = level.players();

            for (Player player : list) {
                if (player.isAlive() && blockEntity.selector.test(player)) {
                    if (VampirePlayer.get(player).getLevel() > 0) {
                        player.addEffect(new MobEffectInstance(ModEffects.SUNSCREEN, 160, 5, true, false));
                    }
                }
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        int defenderChance = nonNullLevel().getDifficulty() == Difficulty.EASY ? 40 : 20;
        if (mode == Mode.RUNNING && getPressure() <= getMinWorkingPressure()) {
            addAir(PneumaticValues.USAGE_SPAWNER_EXTRACTOR);
            if (progress >= 1f) {
                extractSpawnerCore();
            } else if (currentSpeed > 0.1f && nonNullLevel().random.nextInt(defenderChance) == 0) {
                // spawn defending entities; each entity nearby will slow down the extraction process
                nonNullLevel().getBlockEntity(worldPosition.below(), BlockEntityType.MOB_SPAWNER).ifPresent(te -> {
                    if (!trySpawnDefender(te)) {
                        spawnFailures++;
                    }
                });
