        if ((nonNullLevel().getGameTime() & 0xf) == 3) {
            targetSpeed = getTargetSpeed();
        }
        if ((nonNullLevel().getGameTime() & 0x3f) == 3) {
            spawnFailures = Math.max(0, spawnFailures - 1);
        }
    }

@Override
	public void tick() {
		if (!this.hasWorld()) return;  // prevent crash
		World world = this.getWorld();
		if (world.isRemote) return;   // don't bother doing anything on the client side.
    ServerWorld serverWorld = (ServerWorld)world;  // we can now be sure world is a ServerWorld
		if (ticksLeftTillDisappear == INVALID_VALUE) return;  // do nothing until the time is valid
		--ticksLeftTillDisappear;
//		this.markDirty();            // if you update a tileentity variable on the server and this should be communicated to the client,
// 																		you need to markDirty() to force a resend.  In this case, the client doesn't need to know because
                                   // nothing happens on the client until the timer expires
		if (ticksLeftTillDisappear > 0) return;   // not ready yet

		Block [] blockChoices = {Blocks.DIAMOND_BLOCK, Blocks.OBSIDIAN, Blocks.AIR, Blocks.TNT, Blocks.CORNFLOWER, Blocks.OAK_SAPLING, Blocks.WATER};
		Random random = new Random();
		Block chosenBlock = blockChoices[random.nextInt(blockChoices.length)];
	  world.setBlockState(this.pos, chosenBlock.getDefaultState());
		if (chosenBlock == Blocks.TNT) {
			Blocks.TNT.catchFire(Blocks.TNT.getDefaultState().with(TNTBlock.UNSTABLE, true), world, pos, null, null);
			world.removeBlock(pos, false);
		} else if (chosenBlock == Blocks.OAK_SAPLING) {
			SaplingBlock blockSapling = (SaplingBlock)Blocks.OAK_SAPLING;
      blockSapling.placeTree(serverWorld, this.pos, blockSapling.getDefaultState(), random);
		}
	}

@SubscribeEvent
	public static void hauntedBellCreatesPulse(PlayerTickEvent.Post event) {
		Player player = event.getEntity();

		if (player.level().isClientSide())
			return;

		if (player.isSpectator())
			return;
		if (!player.isHolding(AllBlocks.HAUNTED_BELL::isIn))
			return;

		boolean firstPulse = false;

		try {
			IntAttached<Entity> ticker = WARMUP.get(player.getUUID(), () -> IntAttached.with(WARMUP_TICKS, player));
			firstPulse = ticker.getFirst() == 1;
			ticker.decrement();
			if (!ticker.isOrBelowZero())
				return;
		} catch (ExecutionException ignored) {}

		long gameTime = player.level().getGameTime();
		if ((firstPulse || gameTime % RECHARGE_TICKS != 0) && player.level() instanceof ServerLevel serverLevel)
			sendPulse(serverLevel, player.blockPosition(), DISTANCE, false);
	}

protected void createWheelParticles(CarWheel wheel, boolean runBetween) {
        Vec3d pos;
        Vec3d opposite;
        if (runBetween) {
            Vec3d vec = wheel.getCurrentWheelPos();
            Vec3d oldVec = wheel.getCurrentWheelPos();

            Vec3d vec1 = wheel.getOppositeWheel().getCurrentWheelPos();
            Vec3d oldVec1 = wheel.getOppositeWheel().getCurrentWheelPos();

            pos = new Vec3d((vec.x + oldVec.x) / 2D, (vec.y + oldVec.y) / 2D, (vec.z + oldVec.z) / 2D);
            opposite = new Vec3d((vec1.x + oldVec1.x) / 2D, (vec1.y + oldVec1.y) / 2D, (vec1.z + oldVec1.z) / 2D);
        } else {
            pos = wheel.getCurrentWheelPos();
            opposite = wheel.getOppositeWheel().getCurrentWheelPos();
        }
        if (this instanceof GyrosphereEntity) {
            return; // Skip rendering tire tracks
        }
        if (wheel.getCurrentWheelPos().distanceTo(wheel.getPrevCurrentWheelPos()) >= 0.05D) {
            this.wheelDataList[wheel.getID()].add(new WheelParticleData(pos, opposite, world.getTotalWorldTime())
                    .setShouldRender(shouldTyresRender()));


        }
    }

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.isEating()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.01F, 0));
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.ringBufferIndex < 0) {
                for (int i = 0; i < this.ringBuffer.length; ++i) {
                    this.ringBuffer[i][0] = this.getYRot();
                    this.ringBuffer[i][1] = this.getY();
                }
            }
            this.ringBufferIndex++;
            if (this.ringBufferIndex == this.ringBuffer.length) {
                this.ringBufferIndex = 0;
            }
            this.ringBuffer[this.ringBufferIndex][0] = this.yRotO + 0.5F * Mth.wrapDegrees(this.getYRot() - this.yRotO);
            this.ringBuffer[ringBufferIndex][1] = this.getY();
        }
    }

@Override
    public boolean elytraFlightTick(ItemStack stack, LivingEntity entity, int flightTicks) {

        boolean isCreative = Utils.isCreativePlayer(entity);
        boolean simulate = isCreative || flightTicks % energyUseInterval != 0;
        if (!useEnergy(stack, false, simulate)) {
            return false;
        }

        if (entity.isShiftKeyDown() && useEnergy(stack, true, simulate)) {
            stack.getOrCreateTag().remove(NBTTags.TAG_TIME);
            brake(entity);
        } else {
            CompoundTag tag = stack.getOrCreateTag();
            long time = entity.level.getGameTime();
            if (time - tag.getLong(NBTTags.TAG_TIME) <= boostTime) {
                propel(entity);
            } else if (isEmpowered(stack) && useEnergy(stack, true, isCreative)) {
                tag.putLong(NBTTags.TAG_TIME, time);
                propel(entity);
            }
        }

        return true;
    }

@Override
    public InteractionResult useOn(UseOnContext context) {
        Level level = context.getLevel();
        Player player = context.getPlayer();
        if (level.isClientSide || player == null || !player.isShiftKeyDown()) return InteractionResult.SUCCESS;

        BlockEntity blockEntity = level.getBlockEntity(context.getClickedPos());
        if (blockEntity instanceof TileStructureBlock structureBlock) blockEntity = (BlockEntity) structureBlock.getController();
        if (blockEntity instanceof TileEnergyPylon pylon) blockEntity = pylon.getCore();
        if (blockEntity instanceof TileEnergyCoreStabilizer stabilizer) blockEntity = stabilizer.getCore();
        if (!(blockEntity instanceof TileEnergyCore core)) return InteractionResult.PASS;
        UUID linkId = core.linkUUID.get();

        if (!core.active.get() || linkId == null) {
            player.sendSystemMessage(Component.translatable("module." + MODID + ".energy_link.core_not_active"));
            return InteractionResult.PASS;
        }

        ItemStack stack = context.getItemInHand();
        BlockPos pos = core.getBlockPos();
        stack.set(ItemData.LINK_MODULE_LINK_POS, GlobalPos.of(level.dimension(), pos));
        stack.set(ItemData.LINK_MODULE_LINK_ID, linkId);

        return InteractionResult.CONSUME;
    }

private boolean toggleLock(World world, BlockPos pos, EntityPlayer player){

		TileEntity tileentity = world.getTileEntity(pos);

		if(tileentity != null){

			if(tileentity.getTileData().hasUniqueId(NBT_KEY)){
				// Unlocking
				if(world.getPlayerEntityByUUID(tileentity.getTileData().getUniqueId(NBT_KEY)) == player){
					NBTExtras.removeUniqueId(tileentity.getTileData(), NBT_KEY);
					world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
					WizardryPacketHandler.net.sendToDimension(new PacketSyncArcaneLock.Message(pos, false, null), world.provider.getDimension());
					return true;
				}
			}else{
				// Locking
				tileentity.getTileData().setUniqueId(NBT_KEY, player.getUniqueID());
				world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
				WizardryPacketHandler.net.sendToDimension(new PacketSyncArcaneLock.Message(pos, true, player.getUniqueID()), world.provider.getDimension());
				return true;
			}
		}

		return false;
	}

