protected void doTick(ServerLevel level, E entity) {
        Brain<?> brain = entity.getBrain();

        var walkTarget = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_TREE_WALK_TARGET.get());
        if (walkTarget == null) {
            this.resetState(brain);
        } else {
            Long unpathableTime = BrainUtil.getMemory(brain, MemoryModuleType.CANT_REACH_WALK_TARGET_SINCE);
            if (unpathableTime == null) {
                this.resetState(brain);
            } else {
                if (this.lastUnpathableTime == 0L) {
                    this.lastUnpathableTime = unpathableTime;
                } else if (this.lastUnpathableTime == unpathableTime) {
                    BrainUtil.clearMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get());
                } else if (this.lastUnpathableTime < unpathableTime) {
                    this.lastUnpathableTime = unpathableTime;
                    BrainUtil.setMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get(), walkTarget.getTarget().currentBlockPosition().getY() > entity.getEyeY());
                    BrainUtil.clearMemory(brain, OccultismMemoryTypes.LAST_TREE_WALK_TARGET.get());
                    if (Occultism.DEBUG.debugAI) {
                        Networking.sendToTracking(entity, new MessageSelectBlock(walkTarget.getTarget().currentBlockPosition(), 50000, Color.RED));
                    }
                }

            }
        }
    }

public AbilityUseResult directSlam(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
        int stunDuration = 0;
        double damageMultiplier = item.getEffectLevel(itemStack, ItemEffect.slam) * 1.5 / 100;
        float knockbackBase = (float) item.getEffectEfficiency(itemStack, ItemEffect.slam);
        float knockbackMultiplier = 1f;

        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

        if (isDefensive) {
            damageMultiplier -= 0.3;
            stunDuration = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive);
        }

        if (overchargeBonus > 0) {
            double bonus = overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
            damageMultiplier += bonus;
            knockbackMultiplier += bonus;
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0) {
            stunDuration = momentumLevel;
        }

        double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
        if (momentumEfficiency > 0) {
            knockbackMultiplier = 0.4f;
        }

        double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
        if (overextendLevel > 0 && !attacker.getFoodData().needsFood()) {
            damageMultiplier += overextendLevel / 100d;
        }

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockbackMultiplier * knockbackBase, knockbackMultiplier / 2);

        if (result != AbilityUseResult.fail) {
            if (stunDuration > 0) {
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false));
            }

            if (momentumEfficiency > 0) {
                double velocity = momentumEfficiency;
                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                target.push(0, velocity, 0);
            }

            if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
            }

            double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationEfficiency > 0) {
                knockbackExhilaration(attacker, attacker.position(), target, target.level().getGameTime() + 200, exhilarationEfficiency);
            }

            RandomSource rand = target.getRandom();
            CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                    world.sendParticles(ParticleTypes.CRIT,
                            hitVec.x, hitVec.y, hitVec.z, 10,
                            rand.nextGaussian() * 0.3, rand.nextGaussian() * target.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f));

            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.7f);
        } else {
            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.7f);
        }

        return result;
    }

@Override
	public void playerTouch(Player player) {
		if (!this.level().isClientSide) {
			if (this.pickupDelay > 0)
				return;

			ItemStack itemstack = this.getItem();
			Item item = itemstack.getItem();
			int i = itemstack.getCount();

			ItemStack copy = itemstack.copy();
			boolean isPlayerOwner = player.getUUID().equals(this.getOwnerId());
			boolean allowPickUp = false;

			if (item instanceof StorageCrystal && (isPlayerOwner || !EnigmaticItems.ENIGMATIC_AMULET.isVesselOwnerOnly())) {
				allowPickUp = true;
			} else if (item instanceof SoulCrystal && isPlayerOwner) {
				allowPickUp = true;
			}

			if (allowPickUp) {
				if (item instanceof StorageCrystal) {
					CompoundTag crystalNBT = ItemNBTHelper.getNBT(itemstack);
					ItemStack embeddedSoul = crystalNBT.contains("embeddedSoul") ? ItemStack.of(crystalNBT.getCompound("embeddedSoul")) : null;

					if (!isPlayerOwner && embeddedSoul != null)
						return;

					EnigmaticItems.STORAGE_CRYSTAL.retrieveDropsFromCrystal(itemstack, player, embeddedSoul);
					SoulArchive.getInstance().removeItem(this);

					/*
					if (!isPlayerOwner && embeddedSoul != null) {
						PermanentItemEntity droppedSoulCrystal = new PermanentItemEntity(this.world, this.getPosX(), this.getPosY(), this.getPosZ(), embeddedSoul);
						droppedSoulCrystal.setOwnerId(this.getOwnerId());
						this.world.addEntity(droppedSoulCrystal);
					}
					 */

				} else if (item instanceof SoulCrystal) {
					if (!EnigmaticItems.SOUL_CRYSTAL.retrieveSoulFromCrystal(player, itemstack))
						return;
					else {
						SoulArchive.getInstance().removeItem(this);
					}
				}

				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), 64, player.level().dimension())), new PacketRecallParticles(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), 48, false));

				player.take(this, i);
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketHandleItemPickup(player.getId(), this.getId()));

				EnigmaticLegacy.LOGGER.info("Player " + player.getGameProfile().getName() + " picking up: " + this);
				this.discard();
				itemstack.setCount(0);
			} else if (this.pickupDelay == 0 && (this.owner == null || this.owner.equals(player.getUUID())) && (i <= 0 || player.getInventory().add(itemstack))) {
				copy.setCount(copy.getCount() - this.getItem().getCount());
				if (itemstack.isEmpty()) {
					player.take(this, i);

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketHandleItemPickup(player.getId(), this.getId()));

					EnigmaticLegacy.LOGGER.info("Player " + player.getGameProfile().getName() + " picking up: " + this);
					this.discard();
					itemstack.setCount(i);
				}

				player.awardStat(Stats.ITEM_PICKED_UP.get(item), i);
			}

		}
	}

public void dealDamageTo(LivingEntity target) {
        LivingEntity owner = this.getOwner();
        float damage = 4.0F;
        if (this.tickCount >= 14){
            damage = 2.0F;
        }
        if (target.isAlive() && !target.isInvulnerable() && target != owner) {
            if (target.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES)){
                return;
            }
            if (owner == null) {
                boolean flag = target.getType().is(EntityTypeTags.FREEZE_HURTS_EXTRA_TYPES);
                if (flag){
                    damage *= 2.0F;
                }
                if (target.hurt(this.damageSources().freeze(), damage)){
                    target.invulnerableTime = 16;
                }
            } else {
                if (owner instanceof Mob mobOwner) {
                    if (mobOwner instanceof Enemy && target instanceof Enemy) {
                        if (mobOwner.getTarget() != target) {
                            return;
                        }
                    }
                    if (mobOwner instanceof IOwned owned){
                        if (owned.getTrueOwner() != null){
                            if (MobUtil.areAllies(owned.getTrueOwner(), target)){
                                return;
                            }
                        }
                    }
                }
                if (MobUtil.areAllies(owner, target)){
                    return;
                }
                if (owner instanceof Mob) {
                    if (owner.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                        damage = (float) owner.getAttributeValue(Attributes.ATTACK_DAMAGE);
                        if (damage < 1){
                            damage = 1.0F;
                        }
                        if (this.tickCount >= 14){
                            damage /= 2.0F;
                        }
                    }
                } else {
                    damage += this.getExtraDamage();
                }
                DamageSource damageSource = ModDamageSource.iceBouquet(this, owner);
                if (this.isTrap()) {
                    damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.ICE_BOUQUET);
                }
                if (target.hurt(damageSource, damage)){
                    target.invulnerableTime = 16;
                    if (owner instanceof Player player) {
                        if (target.isAlive() && this.isSoulEating() && SEHelper.getSoulGiven(target) > 0) {
                            SEHelper.increaseSouls(player, 1);
                        }
                        if (this.isTrap()) {
                            target.lastHurtByPlayer = player;
                            target.lastHurtByPlayerTime = 100;
                        }
                    }
                    if (this.isTrap()) {
                        target.lastHurtByMob = owner;
                        target.lastHurtByMobTimestamp = 100;
                    }
                }
            }
        }
    }

@Override
	public void update() {
		super.update();

		if (suckingCooldown > 0) {
			suckingCooldown--;
			//markDirty();
		}

		if (!((BlockCraftingPlate) getBlockType()).testStructure(getWorld(), getPos()).isEmpty()) return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (!ManaManager.isManaFull(getWizardryCap())) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canGiveToOutside() || !((TileOrbHolder) tile).canSuckFromOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanGiveToOutside(false);
						((TileOrbHolder) tile).setCanSuckFromOutside(true);
						tile.markDirty();
					}
				}
			}
		}

		if (!world.isRemote) {
			for (EntityItem entityItem : world.getEntitiesWithinAABB(EntityItem.class, new AxisAlignedBB(pos))) {
				if (entityItem.getItem().isEmpty()) continue;
				if (hasInput()) break;

				if (!isInventoryEmpty() && CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem())) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);
					entityItem.getItem().shrink(1);

					input.getHandler().insertItem(0, stack, false);

					PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

				} else if (!(CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem()))) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);

					ItemStack left = ItemHandlerHelper.insertItem(realInventory.getHandler(), stack, false);
					if (left.isEmpty()) {
						entityItem.getItem().shrink(1);
						PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
					}
				}
			}
		}

		boolean done = CraftingPlateRecipeManager.tick(world, pos, getInput(), realInventory.getHandler(), this::suckMana);
		if (done) {
			ItemStack inputStack = input.getHandler().extractItem(0, 1, false);
			if (!inputStack.isEmpty()) {
				output.getHandler().insertItem(0, inputStack, false);
				for (int i = 0; i < realInventory.getHandler().getSlots(); i++)
					realInventory.getHandler().setStackInSlot(i, ItemStack.EMPTY);
				PacketHandler.NETWORK.sendToAllAround(new PacketClearCraftingPlate(pos), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 128));
			}
			markDirty();
		}
	}

