public BlockPos groundBlock(boolean ignoreAir) {
        Block block = this.blockState.getBlock();
        BlockPos blockpos = this.blockPosition();
        BlockState blockstate = this.level.getBlockState(blockpos);
        boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
        boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
        this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
        if (blockstate.is(Blocks.MOVING_PISTON))
            return null;
        if (this.cancelDrop) {
            this.discard();
            this.callOnBrokenAfterFall(block, blockpos);
            return null;
        }
        boolean canBeReplaced = blockstate.canBeReplaced(new DirectionalPlaceContext(this.level, blockpos, Direction.DOWN, ItemStack.EMPTY, Direction.UP));
        boolean isFreeBelow = FallingBlock.isFree(this.level.getBlockState(blockpos.below())) && (!isConcrete || !isConcreteInWater);
        boolean canSurvive = this.blockState.canSurvive(this.level, blockpos) && (!isFreeBelow || ignoreAir);
        if (canBeReplaced && canSurvive) {
            if (this.blockState.hasProperty(BlockStateProperties.WATERLOGGED) && this.level.getFluidState(blockpos).getType() == Fluids.WATER) {
                this.blockState = this.blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.TRUE);
            }

            if (this.level.setBlock(blockpos, this.blockState, 3)) {
                ((ServerLevel) this.level).getChunkSource().chunkMap.broadcast(this, new ClientboundBlockUpdatePacket(blockpos, this.level.getBlockState(blockpos)));
                this.discard();
                if (block instanceof Fallable fallable) {
                    fallable.onLand(this.level, blockpos, this.blockState, blockstate, new FallingBlockEntity(level, this.getX(), this.getY(), this.getZ(), this.blockState));
                } else if (context != null && resolver != null) {
                    RewindAttachment.get(context).addRewindEvent(level.getGameTime(), new EntityToBlockRewind(this, blockpos, this.blockState));
                    ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(
                            new Vec3(blockpos.getX(), blockpos.getY(), blockpos.getZ()), Direction.DOWN, blockpos, false
                    ), level, getOwner(), context, resolver);
                }

                if (this.blockData != null && this.blockState.hasBlockEntity()) {
                    BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                    if (blockentity != null) {

                        try {
                            blockentity.loadWithComponents(this.blockData, level.registryAccess());
                            if (blockentity instanceof SkullBlockEntity sk && this.blockData != null && this.blockData.contains("SkullOwner")) {
                                sk.setOwner(ANCodecs.decode(level.registryAccess(), ResolvableProfile.CODEC, this.blockData.getCompound("SkullOwner")));
                            }
                        } catch (Exception exception) {
                            exception.printStackTrace();
                        }

                        blockentity.setChanged();
                    }
                }
                if (this.level.getBlockEntity(blockpos) instanceof MageBlockTile mbt) {
                    if (context != null) {
                        mbt.color = context.getSpell().particleTimeline().get(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor();
                    }
                    mbt.setChanged();
                }

                return blockpos;
            } else if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.discard();
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));
                }
                this.spawnAtLocation(itemstack);
                return null;
            }
        } else {
            this.discard();
            if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));

                }
                this.spawnAtLocation(itemstack);
            }
        }
        return null;
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide && !initMusic) {
            initMusic = true;
            ((Runnable) () -> ChimeraMusic.play(WildenChimera.this)).run();
        }

        // written like this allows for hotswap
        // this.goalSelector.getAvailableGoals().stream().filter(WrappedGoal::isRunning).map(WrappedGoal::getGoal).forEach(System.out::println);


        if (!level.isClientSide && isDefensive()) {
            this.getNavigation().stop();
        }
        if (level.isClientSide && isFlying() && random.nextInt(18) == 0) {

            this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.BAT_LOOP, this.getSoundSource(),
                    0.95F + this.random.nextFloat() * 0.05F,
                    0.3f + this.random.nextFloat() * 0.05F,
                    false);

        }

        if (!level.isClientSide && this.isInLava() && this.level.getGameTime() % 10 == 0) {
            this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 20, 4));
            this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 3));
            this.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 20));
            this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20, 3));

        }

        if (this.isFlying()) {
            this.navigation.stop();
            flyingNavigator.tick();
        }

        if (!level.isClientSide) {
            // Reduce skill cooldown
            if (diveCooldown > 0) {
                diveCooldown--;
                if (this.isInLava() || this.isInWater())
                    diveCooldown -= 2;
            }
            if (summonCooldown > 0) summonCooldown--;
            if (spikeCooldown > 0) spikeCooldown--;
            if (ramCooldown > 0) ramCooldown--;

            if (getTarget() != null && this.invulnerableTime == 0 && !this.isDefensive() && !this.isFlying() && (this.onGround() || isInWater())) {
                var path = getNavigation().createPath(getTarget(), 1);
                if (path == null || !path.canReach() || getTarget().getY() - (this.getY() + 2) >= 3) {
                    rageTimer--;
                }
            }

        }

        if (!level.isClientSide && getPhaseSwapping() && !this.dead) {
            if (swapTicks < 60) {
                swapTicks++;
                this.navigation.stop();
            } else {
                this.removeAllEffects();
                this.setPhaseSwapping(false);
                for (LivingEntity e : level.getEntitiesOfClass(Player.class, new AABB(this.blockPosition()).inflate(5))) {
                    EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, new Spell().add(MethodTouch.INSTANCE)
                            .add(EffectLaunch.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            .add(EffectDelay.INSTANCE)
                            .add(EffectKnockback.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            , this, new LivingCaster(this)));
                    resolver.onCastOnEntity(ItemStack.EMPTY, e, InteractionHand.MAIN_HAND);
                }
                getRandomUpgrade();
                ParticleUtil.spawnPoof((ServerLevel) level, blockPosition().above());
                if (getPhase() == 1)
                    rageTimer = 200;
                swapTicks = 0;
            }
        }

        if (getPhaseSwapping() && level.isClientSide) {
            spawnPhaseParticles(blockPosition(), level, getPhase());
        }
    }

public void tick() {
        if (this.level.hasNeighborSignal(this.getBlockPos())) {
            this.miningTime = 0;
            return;
        }
        if (!this.level.isClientSide()) {
            ItemStack input = this.inputHandler.getStackInSlot(0);

            if (!this.cachedEnchantment) {
                this.setCachedEnchantment();
                this.cachedEnchantment = true;
            }

            // handle unusing enchantment from evilcraft, see
            // https://github.com/klikli-dev/occultism/issues/909
            if (input.isEnchanted() && input.getMaxDamage() - input.getDamageValue() < 6 &&
                    this.UNUSING != null && input.getEnchantmentLevel(this.UNUSING) > 0) {
                this.miningTime = 0;
                return;
            }

            if (this.miningTime > 0) {

                int efficiency = this.bonusEfficiency && input.isEnchanted() ? input.getEnchantmentLevel(this.EFFICIENCY) : 0;
                if (efficiency > 0) {
                    int extra1 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    int extra2 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    efficiency = Math.min(extra1, extra2);
                }

                this.miningTime -= 1 + efficiency;

                if (this.miningTime <= 0 && !this.level.isClientSide()) {
                    this.mine();
                }

                if (input.getItem() != this.currentInputType) {
                    this.miningTime = 0;
                    this.possibleResults = null;
                }

                // handled by delta check
            } else if (!input.isEmpty()) {

                this.currentInputType = input.getItem();

                forceInitStackNBT(input, (ServerLevel) this.level);
                this.maxMiningTime = getMaxMiningTime(input);
                this.rollsPerOperation = getRollsPerOperation(input);
                this.outputMultiplier = getOutputMultiplier(input);
                this.miningTime = this.maxMiningTime;
            }

            // Sync Logic
            boolean needsSync = this.maxMiningTime != this.lastSyncedMaxMiningTime;

            // Sync if max mining time changed (e.g. new item with different stats)

            // Sync if mining active state changes (0 <-> >0)
            boolean wasActive = this.lastSyncedMiningTime > 0;
            boolean isActive = this.miningTime > 0;
            if (wasActive != isActive) {
                needsSync = true;
            }

            // Syncs if progress drifts by 10
            if (Math.abs(this.miningTime - this.lastSyncedMiningTime) >= 10) {
                needsSync = true;
            }
            // Also sync if we just finished (already covered by 0 check above? sorta).

            if (needsSync) {
                this.markNetworkDirty();
            }

            if (this.outputDirty) {
                this.setChanged();
                this.outputDirty = false;
            }
        } else {
            if (this.miningTime > 0 && this.level.getGameTime() % 10 == 0) {
                this.level.addParticle(ParticleTypes.PORTAL, this.worldPosition.getX() + 0.5f,
                        this.worldPosition.getY() + 0.5, this.worldPosition.getZ() + 0.5f, 0.0D, 0.0D, 0.0D);
            }
        }
    }

@Override
    public void tick() {
        if (level == null) return;
        if (level.isClientSide) {

            int baseAge = draining ? 20 : 40;
            int randBound = draining ? 3 : 6;
            int numParticles = draining ? 2 : 1;
            float scaleAge = draining ? (float) ParticleUtil.inRange(0.1, 0.2) : (float) ParticleUtil.inRange(0.05, 0.15);
            if (level.random.nextInt(randBound) == 0 && !Minecraft.getInstance().isPaused()) {
                for (int i = 0; i < numParticles; i++) {
                    Vec3 particlePos = new Vec3(getX(), getY(), getZ()).add(0.5, 0.5, 0.5);
                    particlePos = particlePos.add(ParticleUtil.pointInSphere());
                    level.addParticle(ParticleLineData.createData(new ParticleColor(255, 25, 180), scaleAge, baseAge + level.random.nextInt(20)),
                            particlePos.x(), particlePos.y(), particlePos.z(),
                            getX() + 0.5, getY() + 0.5, getZ() + 0.5);
                }
            }
            if (!stack.isEmpty() && recipe == null) {
                var holder = getRecipeNow();
                this.recipe = holder != null ? holder.value() : null;
            }
            return;
        }
        this.hasRecipe = recipe != null;
        if (backoff > 0) {
            backoff--;
            return;
        }
        if (stack.isEmpty()) {
            return;
        }
        if (craftTicks > 0)
            craftTicks--;

        // Restore the recipe on world restart
        if (recipe == null) {
            var foundRecipe = getRecipeNow();
            if (foundRecipe != null) {
                this.recipe = foundRecipe.value();
                this.craftTicks = 100;
            }
        }

        if (recipe == null || !recipe.matches(this, level)) {
            backoff = 20;
            recipe = null;
            if (this.draining) {
                this.draining = false;
                updateBlock();
            }
            return;
        }

        int transferRate = 200;

        int cost = recipe.getSourceCost(this);

        if (level instanceof ServerLevel serverLevel && this.level.getGameTime() % 20 == 0 && this.getSource() < cost) {
            if (!canAcceptSource(Math.min(200, cost)))
                return;

            List<ISpecialSourceProvider> takePos = SourceUtil.takeSourceMultiple(worldPosition, level, 2, Math.min(200, cost));
            if (takePos != null) {
                this.addSource(transferRate);
                for (ISpecialSourceProvider provider : takePos) {
                    EntityFlyingItem.spawn(worldPosition, serverLevel, provider.getCurrentPos().above(), worldPosition)
                            .withNoTouch().setDistanceAdjust(2f);
                }

                if (!draining) {
                    draining = true;
                    updateBlock();
                }
            } else {
                this.addSource(10);
                if (draining) {
                    draining = false;
                    updateBlock();
                }
            }

        }

        if (this.getSource() >= cost && craftTicks <= 0) {
            this.setItem(0, recipe.assemble(this, this.level.registryAccess()).copy());
            this.addSource(-cost);
            ParticleUtil.spawnTouchPacket(level, worldPosition, ParticleColor.defaultParticleColor());
            updateBlock();
        }
    }

private void onImpactEntity(EntityHitResult entityRayTrace) {
    Entity entityHit = entityRayTrace.getEntity();
    if (entityHit == null || !entityHit.isAlive()) {
      return;
    }
    Entity owner = getOwner();
    if (owner == entityHit) {
      //player catch it on return 
      dropAsItem();
      return;
    }
    switch (this.boomerangType) {
      case CARRY:
        if (!entityHit.level().isClientSide) {
          entityHit.startRiding(this);
        }
      break;
      case DAMAGE:
        if (entityHit instanceof LivingEntity) {
          LivingEntity live = (LivingEntity) entityHit;
          float damage = Mth.nextFloat(level().random, ConfigRegistry.BOOMERANG_DAMAGE_MIN.get().floatValue(), ConfigRegistry.BOOMERANG_DAMAGE_MAX.get().floatValue());
          boolean attackSucc = live.hurt(level().damageSources().thrown(this, owner), damage);
          if (attackSucc && live.isAlive() == false) {
            //           ("killed one");
          }
        }
      break;
      case STUN:
        //!entityHit.getUniqueID().equals(owner.getUniqueID()) 
        if (entityHit != owner && entityHit instanceof LivingEntity
            && !(entityHit instanceof Player)) {
          LivingEntity live = (LivingEntity) entityHit;
          if (!live.hasEffect(PotionEffectRegistry.STUN)) {
            live.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, ConfigRegistry.BOOMERANG_STUN_SECONDS.get() * Const.TICKS_PER_SEC, 1, false, true, true));
            SoundUtil.playSound(live, SoundEvents.IRON_GOLEM_ATTACK);
          }
        }
      break;
      default:
      break;
    }
  }

