private void setPhase(byte phase) {
        byte previous = getDataTracker().get(PHASE);
        if (previous != phase && phase == PHASE_DESPAWNING && behaviour != null) {
            playConfiguredSound(behaviour.sounds.despawn);
            emitDespawnFx();
        }
        getDataTracker().set(PHASE, phase);
        int endAge = switch (phase) {
            case PHASE_SPAWNING   -> spawnEndAge;
            case PHASE_ACTIVE     -> despawnStartAge;
            case PHASE_DESPAWNING -> timeToLive;
            default               -> 0;
        };
        getDataTracker().set(END_OF_PHASE_AGE, endAge);
    }

public static void attemptRepair(ItemStack stack, LivingEntity entity) {
        if (entity.level.getGameTime() % 200 != 0 || stack.getDamageValue() <= 0) {
            return;
        }

        double repairLevel = PerkUtil.countForPerk(RepairingPerk.INSTANCE, entity);
        int damage = stack.getDamageValue();
        int repairAmount = Math.min(damage, (int) repairLevel + Config.BASE_ARMOR_REPAIR_RATE.get());
        if (repairAmount <= 0) {
            return;
        }

        var cap = CapabilityRegistry.getMana(entity);
        if (cap != null && cap.getCurrentMana() >= 20) {
            cap.removeMana(20);
            stack.setDamageValue(damage - repairAmount);
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Vec3d position = spell.getTarget(world);
		BlockPos pos = spell.getTargetPos();

		if (position == null || pos == null) return true;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		double area = spellRing.getAttributeValue(world, AttributeRegistry.AREA, spell);

		if (world.getTotalWorldTime() % 2 == 0)
			world.playSound(null, pos, ModSounds.FIZZING_LOOP, CommonProxy.SoundCategory_WizardryGeneral, RandUtil.nextFloat(0.6f, 1f), RandUtil.nextFloat(0.1f, 4f));
		for (Entity entity : world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(new BlockPos(position)).grow(area, area, area))) {
			if (entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				if (potency >= 3) {
					living.addPotionEffect(new PotionEffect(MobEffects.NAUSEA, 100));
				}
				living.addPotionEffect(new PotionEffect(MobEffects.POISON, 60, (int) (potency / 3)));
			}
		}

		return true;
	}

private static boolean applyCharm(DeferredItem<Item> charm, Inventory keptInventory, Player player, int fromSlot, int toSlot) {
		Inventory inventory = player.getInventory();
		List<ItemStack> mergedCheck = new ArrayList<>(inventory.getNonEquipmentItems().subList(fromSlot, toSlot));

		// Armor and offhand are always kept by a Charm of Keeping
		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			mergedCheck.add(inventory.getItem(slot));
		}

		// Filter out the charm so it does not count towards keeping items if it is the only thing being held
		if (mergedCheck.stream().filter(stack -> !stack.is(charm)).allMatch(ItemStack::isEmpty)) {
			return false;
		}

		// Stop operation if there is no charm present
		if (!TFItemStackUtils.consumeInventoryItem(player, charm, getPlayerData(player), true) && !hasCharmCurio(charm.value(), player, true)) {
			return false;
		}

		boolean skipCasketCheck = charm == TFItems.CHARM_OF_KEEPING_3;
		boolean keptCasket = false;

		for (int slot = fromSlot; slot < toSlot; slot++) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		return true;
	}

@SubscribeEvent
    public static void levelTick(ServerTickEvent.Post event) {
        var server = event.getServer();
        int tick = server.getTickCount();
        if (!INSTANCE.summonExpirations.isEmpty() && tick % 20 == 0) {
            var nextDespawn = INSTANCE.summonExpirations.peek();
            while (nextDespawn.expirationServerTick < tick) {
                INSTANCE.summonExpirations.remove();

                var uuid = nextDespawn.uuid;
                Entity toRemove = Streams.of(server.getAllLevels())
                        .map(level -> level.getEntity(uuid))
                        .filter(Objects::nonNull)
                        .findFirst()
                        .orElse(null);
                if (toRemove instanceof IMagicSummon summon) {
                    summon.onUnSummon();
                } else if (toRemove != null) {
                    toRemove.discard();
                }

                if (INSTANCE.summonExpirations.isEmpty()) {
                    break;
                } else {
                    nextDespawn = INSTANCE.summonExpirations.peek();
                }
            }
        }
        if (Log.SUMMON_MANAGER && tick % 100 == 0) {
            IronsSpellbooks.LOGGER.debug("SummonManagerDump -------------");
            IronsSpellbooks.LOGGER.debug("SummonManagerDump ownerToSummons: {}", INSTANCE.ownerToSummons.toString());
            IronsSpellbooks.LOGGER.debug("SummonManagerDump summonToOwner: {}", INSTANCE.summonToOwner.toString());
            IronsSpellbooks.LOGGER.debug("SummonManagerDump summonExpirations: {}", INSTANCE.summonExpirations.toString());
        }
    }

public void onUpdate(){

		super.onUpdate();

		// System.out.println("Client side: " + this.world.isRemote + ", Caster: " + this.caster);

		// Particle effect. Finishes 40 ticks before the end so the particles disappear at the same time.
		if(this.ticksExisted + 40 < this.lifetime){
			for(int i = 0; i < 5; i++){
				// this.world.spawnParticle(EnumParticleTypes.PORTAL, this.posX + (this.rand.nextDouble() - 0.5D) *
				// (double)this.width, this.posY + this.rand.nextDouble() * (double)this.height - 0.75D, this.posZ +
				// (this.rand.nextDouble() - 0.5D) * (double)this.width, (this.rand.nextDouble() - 0.5D) * 2.0D,
				// -this.rand.nextDouble(), (this.rand.nextDouble() - 0.5D) * 2.0D);
				this.world.spawnParticle(EnumParticleTypes.PORTAL, this.posX, this.posY, this.posZ,
						(this.rand.nextDouble() - 0.5D) * 4.0D, (this.rand.nextDouble() - 0.5D) * 4.0D - 1,
						(this.rand.nextDouble() - 0.5D) * 4.0D);
			}
		}

		if(this.lifetime - this.ticksExisted == 75){
			this.playSound(WizardrySounds.ENTITY_BLACK_HOLE_VANISH, 1.5f, 1.0f);
		}else if(this.ticksExisted % 80 == 1 && this.ticksExisted + 80 < this.lifetime){
			this.playSound(WizardrySounds.ENTITY_BLACK_HOLE_AMBIENT, 1.5f, 1.0f);
		}

		if(!this.world.isRemote){

			double radius = 2 * height * sizeMultiplier;

			boolean suckInBlocks = getCaster() instanceof EntityPlayer && EntityUtils.canDamageBlocks(getCaster(), world)
					&& ItemArtefact.isArtefactActive((EntityPlayer)getCaster(), WizardryItems.charm_black_hole);

			if(suckInBlocks){

				List<BlockPos> sphere = BlockUtils.getBlockSphere(new BlockPos(this), radius);

				int blocksUnhooked = 0;

				for(BlockPos pos : sphere){

					if(rand.nextInt(Math.max(1, (int)this.getDistanceSq(pos) * 3)) == 0){

						if(!BlockUtils.isBlockUnbreakable(world, pos) && !world.isAirBlock(pos)
								&& world.isBlockNormalCube(pos, false) && BlockUtils.canBreakBlock(getCaster(), world, pos)){
							// Checks that the block above is not solid, since this causes the falling block to vanish.
//							&& !world.isBlockNormalCube(pos.up(), false)){

							EntityFallingBlock fallingBlock = new EntityLevitatingBlock(world, pos.getX() + 0.5,
									pos.getY() + 0.5, pos.getZ() + 0.5, world.getBlockState(pos));
//							fallingBlock.noClip = true;
							fallingBlock.fallTime = 1; // Prevent it from trying to delete the block itself
							world.spawnEntity(fallingBlock);
							world.setBlockToAir(pos);

							if(++blocksUnhooked >= BLOCK_UNHOOK_LIMIT) break; // Lag prevention
						}
					}
				}

			}

			List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius, this.posX, this.posY,
					this.posZ, this.world, Entity.class);

			targets.removeIf(t -> !(t instanceof EntityLivingBase || (suckInBlocks && t instanceof EntityFallingBlock)));

			for(Entity target : targets){

				if(this.isValidTarget(target)){

					// If the target can't be moved, it isn't sucked in but is still damaged if it gets too close
					if(!(target instanceof EntityPlayer && ((getCaster() instanceof EntityPlayer && !Wizardry.settings.playersMoveEachOther)
							|| ItemArtefact.isArtefactActive((EntityPlayer)target, WizardryItems.amulet_anchoring)))){

						EntityUtils.undoGravity(target);
						if(target instanceof EntityLevitatingBlock) ((EntityLevitatingBlock)target).suspend();

						// Sucks the target in
						if(this.posX > target.posX && target.motionX < 1){
							target.motionX += SUCTION_STRENGTH;
						}else if(this.posX < target.posX && target.motionX > -1){
							target.motionX -= SUCTION_STRENGTH;
						}

						if(this.posY > target.posY && target.motionY < 1){
							target.motionY += SUCTION_STRENGTH;
						}else if(this.posY < target.posY && target.motionY > -1){
							target.motionY -= SUCTION_STRENGTH;
						}

						if(this.posZ > target.posZ && target.motionZ < 1){
							target.motionZ += SUCTION_STRENGTH;
						}else if(this.posZ < target.posZ && target.motionZ > -1){
							target.motionZ -= SUCTION_STRENGTH;
						}

						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}
					}

					if(this.getDistance(target) <= 2){
						// Damages the target if it is close enough, or destroys it if it's a block
						if(target instanceof EntityFallingBlock){
							target.playSound(WizardrySounds.ENTITY_BLACK_HOLE_BREAK_BLOCK, 0.5f,
									(rand.nextFloat() - rand.nextFloat()) * 0.2f + 1);
							IBlockState state = ((EntityFallingBlock)target).getBlock();
							if(state != null) world.playEvent(2001, new BlockPos(target), Block.getStateId(state));
							target.setDead();

						}else{
							if(this.getCaster() != null){
								target.attackEntityFrom(
										MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.MAGIC),
										2 * damageMultiplier);
							}else{
								target.attackEntityFrom(DamageSource.MAGIC, 2 * damageMultiplier);
							}
						}
					}
				}
			}
		}
	}

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
			this.setDead();
			return;
		}

		this.setTriangleSize(this.getTriangleSize());

		this.motionX = 0;
		this.motionY = 0;
		this.motionZ = 0;

		super.onUpdate();

		if(!this.world.isRemote) {
			this.despawnTicks++;
			if(this.despawnTicks >= this.getMaxDespawnTicks()) {
				this.setDead();
			}

			this.rotation += 1.0F;
			this.getDataManager().set(ROTATION, this.rotation);

			List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(this.getTriangleSize()*2, 0, this.getTriangleSize()*2));
			for(EntityLivingBase target : targets) {
				if(target != this.getOwner()) {
					Vec3d[] vertices = this.getTriangleVertices(1);

					if(EntityFortressBoss.rayTraceTriangle(new Vec3d(target.posX - this.posX, 1, target.posZ - this.posZ), new Vec3d(0, -2, 0), vertices[0], vertices[1], vertices[2])) {

						if(this.isPlayerControlled()) {
							IPuppetCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);

							Entity owner = this.getOwner();

							if(cap != null && cap.getPuppeteer() == owner && owner instanceof EntityPlayer) {
								EntityPlayer player = (EntityPlayer) owner;

								IPuppeteerCapability playerCap = player.getCapability(CapabilityRegistry.CAPABILITY_PUPPETEER, null);
								if(playerCap != null) {
									ProtectionShield shield = playerCap.getShield();

									if(shield != null) {
										float healthPercent = 0.3f;

										if(target.getHealth() * (1 - healthPercent) > 5.0f) {
											float healthCost = target.getHealth() * healthPercent;
											float prevHealth = target.getHealth();

											if(target.attackEntityFrom(DamageSource.MAGIC, healthCost) && (prevHealth - target.getHealth()) >= healthCost * 0.5f) {
												List<Integer> indices = new ArrayList<>();
												for(int i = 0; i < 20; i++) {
													indices.add(i);
												}
												Collections.shuffle(indices, this.rand);

												for(int index : indices) {
													if(!shield.isActive(index)) {
														shield.setActive(index, true);
														break;
													}
												}

												this.maxDespawnTicks = this.despawnTicks + 8;
											}
										}
									}
								}
							}
						} else if(target instanceof EntityPlayer)  {
							float damage = (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue();
							if(target.attackEntityFrom(DamageSource.MAGIC, damage) && this.getOwner() != null && this.getOwner() instanceof EntityLivingBase) {
								EntityLivingBase owner = (EntityLivingBase) this.getOwner();
								if(owner.getHealth() < owner.getMaxHealth() - damage) {
									owner.heal(damage * 3.0F);
								}
							}
						}

					}
				}
			}
		} else {
			this.prevRotation = this.rotation;
			this.rotation = this.getDataManager().get(ROTATION);

			for(int c = 0; c < 4; c++) {
				float r1 = this.world.rand.nextFloat();
				float r2 = this.world.rand.nextFloat();
				this.rotation += 15;
				Vec3d[] vertices = this.getTriangleVertices(1);
				this.rotation -= 15;
				double xc = 0, zc = 0;
				for(int i = 0; i < 3; i++) {
					Vec3d vertex = vertices[i];
					switch(i) {
					default:
					case 0:
						xc += vertex.x * (1 - Math.sqrt(r1));
						zc += vertex.z * (1 - Math.sqrt(r1));
						break;
					case 1:
						xc += (Math.sqrt(r1) * (1 - r2)) * vertex.x;
						zc += (Math.sqrt(r1) * (1 - r2)) * vertex.z;
						break;
					case 2:
						xc += (Math.sqrt(r1) * r2) * vertex.x;
						zc += (Math.sqrt(r1) * r2) * vertex.z;
						break;
					}
				}
				Vec3d rp = new Vec3d(xc, vertices[0].y, zc);

				double sx = this.posX + rp.x;
				double sy = this.posY + rp.y + 4;
				double sz = this.posZ + rp.z;
				double ex = this.posX + rp.x;
				double ey = this.posY + rp.y;
				double ez = this.posZ + rp.z;

				if(this.getOwner() != null) {
					sx = this.getOwner().posX;
					sy = this.getOwner().getEntityBoundingBox().minY + (this.getOwner().getEntityBoundingBox().maxY - this.getOwner().getEntityBoundingBox().minY) / 2.0D;
					sz = this.getOwner().posZ;
				}

				if(!this.isPlayerControlled()) {
					this.world.spawnParticle(EnumParticleTypes.PORTAL, sx, sy, sz, ex - sx, ey - sy, ez - sz);
				}
			}
		}
	}

public void tick() {
        super.tick();
        if (!this.isActivated()){
            int count = SpellConfig.RuptureDuration.get() / 3;
            if (this.tickCount % count == 0) {
                if (this.level.isClientSide) {
                    if (this.getAnimation() < 2) {
                        this.setAnimation(this.getAnimation() + 1);
                    }
                }
                this.playSound(ModSounds.RUMBLE.get(), 2.0F, this.random.nextFloat() + 0.75F);
            }
        } else {
            if (this.level.isClientSide) {
                if (this.tickCount % 20 == 0) {
                    if (this.isClosing) {
                        if (this.getAnimation() > 0) {
                            this.setAnimation(this.getAnimation() - 1);
                        }
                    } else {
                        if (this.getAnimation() < 7) {
                            this.setAnimation(this.getAnimation() + 1);
                        } else {
                            this.setAnimation(3);
                        }
                    }
                }
            }
        }
        if (!this.level.isClientSide) {
            if (this.warmUp <= 0) {
                if (!this.isActivated()) {
                    this.setActivated(true);
                    this.level.broadcastEntityEvent(this, (byte) 100);
                }
                if (!this.playEvent) {
                    this.playSound(ModSounds.VOID_RIFT_OPEN.get(), 5.0F, 1.0F);
                    ModNetwork.sendToALL(new SPlayLoopSoundPacket(this, ModSounds.VOID_RIFT.get(), 5.0F, 1.0F));
                    this.playEvent = true;
                }
                if (this.tickCount % 200 == 0){
                    this.playSound(SoundEvents.PORTAL_AMBIENT, 5.0F, 0.75F);
                }
                List<Entity> targets = new ArrayList<>();
                float range = 16.0F * (this.getSize() + 1.0F);
                /*if (!this.isClosing) {
                    int rangeInt = Mth.floor(range);
                    this.suckBlocks(rangeInt, rangeInt, rangeInt);
                }*/
                if (this.level instanceof ServerLevel serverWorld) {
                    ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, (int)range);
                }
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(range))) {
                    if (!(entity instanceof Endermite)) {
                        if (entity instanceof ModFallingBlock modFallingBlock && modFallingBlock.getMode() == ModFallingBlock.FallingBlockMode.DEBRIS){
                            targets.add(entity);
                            if (entity.distanceTo(this) <= 1.0F){
                                entity.discard();
                            }
                        }
                        if (this.getOwner() != null) {
                            if (!MobUtil.areAllies(this.getOwner(), entity) && MobUtil.getOwner(entity) != this.getOwner()) {
                                targets.add(entity);
                            }
                        } else {
                            targets.add(entity);
                        }
                    }
                }
                if (!targets.isEmpty()) {
                    for (Entity entity : targets) {
                        double distance = 1.0D - (entity.distanceTo(this) / range);
                        double scale = distance * 0.25D;
                        Vec3 vec3 = entity.position().subtract(this.position());
                        vec3 = vec3.normalize().scale(scale);
                        MobUtil.pull(entity, vec3.x, vec3.y, vec3.z, 0.5D);
                        if (entity.distanceTo(this) <= this.getBoundingBox().getSize()){
                            if (entity instanceof LivingEntity livingEntity) {
                                float damage = SpellConfig.RuptureDamage.get().floatValue() * WandUtil.damageMultiply();
                                if (this.getOwner() != null) {
                                    if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                                        damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F;
                                    }
                                }
                                damage += this.getExtraDamage();
                                livingEntity.hurt(this.damageSources().indirectMagic(this, this.getOwner()), damage);
                            }
                        }
                    }
                }
            } else {
                if (this.level instanceof ServerLevel serverWorld) {
                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    double d2 = this.getY() + 0.5F;
                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    serverWorld.sendParticles(ParticleTypes.PORTAL, d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                }
                if (this.getOwner() != null && this.getOwner().isDeadOrDying()) {
                    this.discard();
                }
                --this.warmUp;
            }
            if (this.tickCount >= this.getDuration()) {
                if (!this.isClosing){
                    this.isClosing = true;
                    this.level.broadcastEntityEvent(this, (byte) 101);
                }
                if (this.tickCount >= this.getDuration() + 20) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        ColorUtil colorUtil = new ColorUtil(0x7317d2);
                        float range = 8.0F * (this.getSize() + 1.0F);
                        serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, range, 0, true), this.getX(), this.getY() + 0.5D, this.getZ(), 0, 0, 0, 0, 0);
                        ServerParticleUtil.createParticleBall(ParticleTypes.DRAGON_BREATH, this.getX(), this.getY() + 0.5D, this.getZ(), serverLevel,  8 + (int) this.getSize());
                        this.playSound(SoundEvents.RESPAWN_ANCHOR_DEPLETE.get(), 5.0F, 0.5F);
                        this.playSound(SoundEvents.GENERIC_EXPLODE, 5.0F, 0.5F);
                        new SpellExplosion(this.level, this.getOwner() != null ? this.getOwner() : this, this.damageSources().indirectMagic(this, this.getOwner()), this.blockPosition(), range / 4, 0.0F) {
                            @Override
                            public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                                super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                                if (VoidRift.this.isStaff()) {
                                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
                                        if (target instanceof LivingEntity livingEntity) {
                                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5), 2, false, true));
                                        }
                                    }
                                }
                            }
                        };
                    }
                    this.discard();
                }
            }
        }
    }

@Override
	public void onUpdate(){

		super.onUpdate();

		if(ticksExisted == 1 && world.isRemote){
			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_FORCEFIELD_AMBIENT, WizardrySounds.SPELLS, 0.5f, 1, true);
		}

		// New forcefield repulsion system:
		// Searches for all entities near the forcefield and determines where they will be next tick.
		// If they will be inside the forcefield next tick, sets their position and velocity such that they appear to
		// bounce off the forcefield and creates impact particle effects and sounds where they hit it

		List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius + SEARCH_BORDER_SIZE, posX, posY, posZ, world, Entity.class);

		targets.remove(this);
		targets.removeIf(t -> t instanceof EntityXPOrb); // Gets annoying since they're attracted to the player

		// Ring of the defender allows players to shoot through their own forcefields
		if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
				WizardryItems.ring_defender)){
			targets.removeIf(t -> t instanceof EntityMagicArrow && !this.isValidTarget(((EntityMagicArrow)t).getCaster())
								|| t instanceof EntityThrowable && !this.isValidTarget(((EntityThrowable)t).getThrower())
								|| t instanceof EntityArrow && !this.isValidTarget(((EntityArrow)t).shootingEntity));
		}

		for(Entity target : targets){

			if(this.isValidTarget(target)){

				Vec3d currentPos = Arrays.stream(GeometryUtils.getVertices(target.getEntityBoundingBox()))
						.min(Comparator.comparingDouble(v -> v.distanceTo(this.getPositionVector())))
						.orElse(target.getPositionVector()); // This will never happen, it's just here to make the compiler happy

				double currentDistance = target.getDistance(this);

				// Estimate the target's position next tick
				// We have to assume the same vertex is closest or the velocity will be wrong
				Vec3d nextTickPos = currentPos.add(target.motionX, target.motionY, target.motionZ);
				double nextTickDistance = nextTickPos.distanceTo(this.getPositionVector());

				boolean flag;

				if(EntityUtils.isLiving(target)){
					// Non-allied living entities shouldn't be inside at all
					flag = nextTickDistance <= radius;
				}else{
					// Non-living entities will bounce off if they hit the forcefield within the next tick...
					flag = (currentDistance > radius && nextTickDistance <= radius) // ...from the outside...
							|| (currentDistance < radius && nextTickDistance >= radius); // ...or from the inside
				}

				if(flag){

					// Ring of interdiction
					if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
							WizardryItems.ring_interdiction) && EntityUtils.isLiving(target)){
						target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
								MagicDamage.DamageType.MAGIC), 1);
					}

					Vec3d targetRelativePos = currentPos.subtract(this.getPositionVector());

					double nudgeVelocity = this.contains(target) ? -0.1 : 0.1;
					if(EntityUtils.isLiving(target)) nudgeVelocity = 0.25;
					Vec3d extraVelocity = targetRelativePos.normalize().scale(nudgeVelocity);

					//Moved up the check by "19" so that way allied players aren't being moved out of the forcefield because
					//allied players aren't synced to client like minions. Minions are only synced because it's saved to their
					//entity data which is synced in their serialize/deserialize methods
					if(!world.isRemote){
						// ...make it bounce off!

						target.motionX = target.motionX * -BOUNCINESS + extraVelocity.x;
						target.motionY = target.motionY * -BOUNCINESS + extraVelocity.y;
						target.motionZ = target.motionZ * -BOUNCINESS + extraVelocity.z;

						// Prevents the forcefield bouncing things into the floor
						if(target.onGround && target.motionY < 0) target.motionY = 0.1;

						// How far the target needs to move towards the centre (negative means away from the centre)
						double distanceTowardsCentre = -(targetRelativePos.length() - radius) - (radius - nextTickDistance);
						Vec3d targetNewPos = target.getPositionVector().add(targetRelativePos.normalize().scale(distanceTowardsCentre));
						target.setPosition(targetNewPos.x, targetNewPos.y, targetNewPos.z);

						world.playSound(target.posX, target.posY, target.posZ, WizardrySounds.ENTITY_FORCEFIELD_DEFLECT,
								WizardrySounds.SPELLS, 0.3f, 1.3f, false);


						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}

						if (this.ticksExisted % 5 == 0) {
							this.lifetime = (int) (lifetime * 0.99);
						}

					}else{

						//This is a super lazy way to make sure the visual isn't playing for players and probably won't display the visual
						//for players if their velocity towards the forcefield is high. But it prevents the visual being spammed when ally player
						//is in forcefield so it's fine #19
						if(target instanceof EntityPlayer && target.getPositionVector().distanceTo(this.getPositionVector()) < this.getRadius()) return;

						Vec3d relativeImpactPos = targetRelativePos.normalize().scale(radius);

						float yaw = (float)Math.atan2(relativeImpactPos.x, -relativeImpactPos.z);
						float pitch = (float)Math.asin(relativeImpactPos.y/ radius);

						ParticleBuilder.create(Type.FLASH).pos(this.getPositionVector().add(relativeImpactPos))
						.time(6).face((float)(yaw * 180/Math.PI), (float)(pitch * 180/Math.PI))
						.clr(0.9f, 0.95f, 1).spawn(world);

						for(int i = 0; i < 12; i++){

							float yaw1 = yaw + 0.3f * (rand.nextFloat() - 0.5f) - (float)Math.PI/2;
							float pitch1 = pitch + 0.3f * (rand.nextFloat() - 0.5f);

							float brightness = rand.nextFloat();

							double r = radius + 0.05;
							double x = this.posX + r * MathHelper.cos(yaw1) * MathHelper.cos(pitch1);
							double y = this.posY + r * MathHelper.sin(pitch1);
							double z = this.posZ + r * MathHelper.sin(yaw1) * MathHelper.cos(pitch1);

							ParticleBuilder.create(Type.DUST).pos(x, y, z).time(6 + rand.nextInt(6))
							.face((float)(yaw1 * 180/Math.PI) + 90, (float)(pitch1 * 180/Math.PI)).scale(1.5f)
							.clr(0.7f + 0.3f * brightness, 0.85f + 0.15f * brightness, 1).spawn(world);
						}
					}
				}
			}
		}
	}

