@Override
	public void tick() {
		super.tick();
		if (searchForEntity) {
			searchForEntity = false;
			List<Entity> search = level.getEntities((Entity) null, new AABB(getBlockPos()),
				e -> entityUUID.equals(e.getUUID()));
			if (search.isEmpty())
				clear();
			else
				processingEntity = search.get(0);
		}

		if (!isOccupied())
			return;
		if (crushingspeed == 0)
			return;

		if (level.isClientSide)
			CatnipServices.PLATFORM.executeOnClientOnly(() -> () -> this.tickAudio());

		float speed = crushingspeed * 4;

		Vec3 centerPos = VecHelper.getCenterOf(worldPosition);
		Direction facing = getBlockState().getValue(CrushingWheelControllerBlock.FACING);
		int offset = facing.getAxisDirection()
			.getStep();
		Vec3 outSpeed = new Vec3((facing.getAxis() == Axis.X ? 0.25D : 0.0D) * offset,
			offset == 1 ? (facing.getAxis() == Axis.Y ? 0.5D : 0.0D) : 0.0D // Increased upwards speed so upwards
			// crushing wheels shoot out the item
			// properly.
			, (facing.getAxis() == Axis.Z ? 0.25D : 0.0D) * offset); // No downwards speed, so downwards crushing wheels
		// drop the items as before.
		Vec3 outPos = centerPos.add((facing.getAxis() == Axis.X ? .55f * offset : 0f),
			(facing.getAxis() == Axis.Y ? .55f * offset : 0f), (facing.getAxis() == Axis.Z ? .55f * offset : 0f));

		if (!hasEntity()) {

			float processingSpeed =
				Mth.clamp((speed) / (!inventory.appliedRecipe ? (float) Math.log(inventory.getStackInSlot(0)
					.getCount()) / (float) Math.log(2) : 1), .25f, 20);
			inventory.remainingTime -= processingSpeed;
			spawnParticles(inventory.getStackInSlot(0));

			if (level.isClientSide)
				return;

			if (inventory.remainingTime < 20 && !inventory.appliedRecipe) {
				applyRecipe();
				inventory.appliedRecipe = true;
				level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 2 | 16);
				return;
			}

			if (inventory.remainingTime > 0) {
				return;
			}
			inventory.remainingTime = 0;

			// Output Items
			if (facing != Direction.UP) {
				BlockPos nextPos = worldPosition.below()
					.relative(facing, facing.getAxis() == Axis.Y ? 0 : 1);

				DirectBeltInputBehaviour behaviour =
					BlockEntityBehaviour.get(level, nextPos, DirectBeltInputBehaviour.TYPE);
				if (behaviour != null) {
					boolean changed = false;
					if (!behaviour.canInsertFromSide(facing))
						return;
					for (int slot = 0; slot < inventory.getSlots(); slot++) {
						ItemStack stack = inventory.getStackInSlot(slot);
						if (stack.isEmpty())
							continue;
						ItemStack remainder = behaviour.handleInsertion(stack, facing, false);
						if (ItemStack.matches(remainder, stack))
							continue;
						inventory.setStackInSlot(slot, remainder);
						changed = true;
					}
					if (changed) {
						setChanged();
						sendData();
					}
					return;
				}
			}

			// Eject Items
			for (int slot = 0; slot < inventory.getSlots(); slot++) {
				ItemStack stack = inventory.getStackInSlot(slot);
				if (stack.isEmpty())
					continue;
				ItemEntity entityIn = new ItemEntity(level, outPos.x, outPos.y, outPos.z, stack);
				entityIn.setDeltaMovement(outSpeed);
				entityIn.getPersistentData()
					.put("BypassCrushingWheel", NbtUtils.writeBlockPos(worldPosition));
				level.addFreshEntity(entityIn);
			}
			inventory.clear();
			level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 2 | 16);

			return;
		}

		if (!processingEntity.isAlive() || !processingEntity.getBoundingBox()
			.intersects(new AABB(worldPosition).inflate(.5f))) {
			clear();
			return;
		}

		double xMotion = ((worldPosition.getX() + .5f) - processingEntity.getX()) / 2f;
		double zMotion = ((worldPosition.getZ() + .5f) - processingEntity.getZ()) / 2f;
		if (processingEntity.isShiftKeyDown())
			xMotion = zMotion = 0;
		double movement = Math.max(-speed / 4f, -.5f) * -offset;
		processingEntity.setDeltaMovement(
			new Vec3(facing.getAxis() == Axis.X ? movement : xMotion, facing.getAxis() == Axis.Y ? movement : 0f // Do
				// not
				// move
				// entities
				// upwards
				// or
				// downwards
				// for
				// horizontal
				// crushers,
				, facing.getAxis() == Axis.Z ? movement : zMotion)); // Or they'll only get their feet crushed.

		if (level.isClientSide)
			return;

		if (!(processingEntity instanceof ItemEntity itemEntity)) {
			Vec3 entityOutPos = outPos.add(facing.getAxis() == Axis.X ? .5f * offset : 0f,
				facing.getAxis() == Axis.Y ? .5f * offset : 0f, facing.getAxis() == Axis.Z ? .5f * offset : 0f);
			int crusherDamage = AllConfigs.server().kinetics.crushingDamage.get();

			if (processingEntity instanceof LivingEntity livingEntity) {
				if (livingEntity.getHealth() - crusherDamage <= 0 // Takes LivingEntity instances
					// as exception, so it can
					// move them before it would
					// kill them.
					&& livingEntity.hurtTime <= 0) { // This way it can actually output the items
					// to the right spot.
					processingEntity.setPos(entityOutPos.x, entityOutPos.y, entityOutPos.z);
				}
			}
			processingEntity.hurt(CreateDamageSources.crush(level), crusherDamage);
			if (!processingEntity.isAlive()) {
				processingEntity.setPos(entityOutPos.x, entityOutPos.y, entityOutPos.z);
			}
			return;
		}

		itemEntity.setPickUpDelay(20);
		if (facing.getAxis() == Axis.Y) {
			if (processingEntity.getY() * -offset < (centerPos.y - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		} else if (facing.getAxis() == Axis.Z) {
			if (processingEntity.getZ() * -offset < (centerPos.z - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		} else {
			if (processingEntity.getX() * -offset < (centerPos.x - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		}
	}

@Override
    public void tick() {
        super.tick();
        prevCollidePosX = collidePosX;
        prevCollidePosY = collidePosY;
        prevCollidePosZ = collidePosZ;
        prevYaw = renderYaw;
        prevPitch = renderPitch;
        xo = getX();
        yo = getY();
        zo = getZ();
        if (tickCount == 1 && level().isClientSide) {
            caster = (LivingEntity) level().getEntity(getCasterID());
        }

        if (!level().isClientSide) {
            if (getHasPlayer()) {
                this.updateWithPlayer();
            }
            else if (caster instanceof EntityUmvuthi) {
                this.updateWithUmvuthi();
            }
        }
        if (caster != null) {
            renderYaw = (float) ((caster.yHeadRot + 90.0d) * Math.PI / 180.0d);
            renderPitch = (float) (-caster.getXRot() * Math.PI / 180.0d);
        }

        if (!on && appear.getTimer() == 0) {
            this.discard() ;
        }
        if (on && tickCount > 20) {
            appear.increaseTimer();
        } else {
            appear.decreaseTimer();
        }

        if (caster != null && !caster.isAlive()) discard() ;

        if (level().isClientSide && tickCount <= 10 && caster != null) {
            int particleCount = 8;
            while (--particleCount != 0) {
                double radius = 2f * caster.getBbWidth();
                double yaw = random.nextFloat() * 2 * Math.PI;
                double pitch = random.nextFloat() * 2 * Math.PI;
                double ox = radius * Math.sin(yaw) * Math.sin(pitch);
                double oy = radius * Math.cos(pitch);
                double oz = radius * Math.cos(yaw) * Math.sin(pitch);
                double rootX = caster.getX();
                double rootY = caster.getY() + caster.getBbHeight() / 2f + 0.3f;
                double rootZ = caster.getZ();
                if (getHasPlayer()) {
                    if (caster instanceof Player && !(caster == MMCommon.PROXY.getLocalPlayer() && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON)) {
                        GeckoPlayer geckoPlayer = GeckoPlayer.getGeckoPlayer((Player) caster, GeckoPlayer.Perspective.THIRD_PERSON);
                        if (geckoPlayer != null) {
                            GeckoRenderPlayer renderPlayer = (GeckoRenderPlayer) geckoPlayer.getPlayerRenderer();
                            if (renderPlayer.betweenHandsPos != null) {
                                rootX += renderPlayer.betweenHandsPos.x();
                                rootY += renderPlayer.betweenHandsPos.y();
                                rootZ += renderPlayer.betweenHandsPos.z();
                            }
                        }
                    }
                    attractorPos[0] = new Vec3(rootX, rootY, rootZ);
                }
                else if (caster instanceof EntityUmvuthi) {
                    EntityUmvuthi umvuthi = (EntityUmvuthi)caster;
                    if (umvuthi.headPos != null && umvuthi.headPos[0] != null) {
                        attractorPos[0] = ((EntityUmvuthi) caster).headPos[0];
                        rootX = attractorPos[0].x();
                        rootY = attractorPos[0].y();
                        rootZ = attractorPos[0].z();
                    }
                }
                else {
                    attractorPos[0] = new Vec3(rootX, rootY, rootZ);
                }
                AdvancedParticleBase.spawnParticle(level(), ParticleHandler.ORB2, rootX + ox, rootY + oy, rootZ + oz, 0, 0, 0, true, 0, 0, 0, 0, 5F, 1, 1, 1, 1, 1, 7, true, false, new ParticleComponent[]{
                        new ParticleComponent.Attractor(attractorPos, 1.7f, 0.0f, ParticleComponent.Attractor.EnumAttractorBehavior.EXPONENTIAL),
                        new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.ALPHA, new ParticleComponent.KeyTrack(
                                new float[]{0f, 0.8f},
                                new float[]{0f, 1f}
                        ), false),
                        new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.SCALE, new ParticleComponent.KeyTrack(
                                new float[]{3f, 6f},
                                new float[]{0f, 1f}
                        ), false)
                });
            }
        }
        if (tickCount > 20) {
            this.calculateEndPos();
            List<Entity> hit = raytraceEntities(level(), new Vec3(getX(), getY(), getZ()), new Vec3(endPosX, endPosY, endPosZ), false, true, true).entities;
            if (blockSide != null) {
                spawnExplosionParticles(2);
            }
            if (!level().isClientSide) {
                for (Entity target : hit) {
                    if (target instanceof ItemEntity) continue;
                    if (caster instanceof EntityUmvuthi && target instanceof LeaderSunstrikeImmune) {
                        continue;
                    }
                    float damageFire = 1f;
                    float damageMob = 1.5f;
                    if (caster instanceof EntityUmvuthi) {
                        damageFire *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                        damageMob *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                    }
                    if (caster instanceof Player) {
                        damageFire *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.75;
                        damageMob *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.75;
                    }
                    if (target instanceof LivingEntity) {
                        DamageUtil.dealMixedDamage((LivingEntity) target, damageSources().mobProjectile(this, caster), damageMob, damageSources().onFire(), damageFire);
                    }
                    else {
                        target.hurt(damageSources().mobProjectile(this, caster), damageMob);
                    }
                }
            } else {
                if (tickCount - 15 < getDuration()) {
                    int particleCount = 4;
                    while (particleCount --> 0) {
                        double radius = 1f;
                        double yaw = (float) (random.nextFloat() * 2 * Math.PI);
                        double pitch = (float) (random.nextFloat() * 2 * Math.PI);
                        double ox = (float) (radius * Math.sin(yaw) * Math.sin(pitch));
                        double oy = (float) (radius * Math.cos(pitch));
                        double oz = (float) (radius * Math.cos(yaw) * Math.sin(pitch));
                        double o2x = (float) (-1 * Math.cos(getYaw()) * Math.cos(getPitch()));
                        double o2y = (float) (-1 * Math.sin(getPitch()));
                        double o2z = (float) (-1 * Math.sin(getYaw()) * Math.cos(getPitch()));
                        level().addParticle(ParticleOrb.Data.create((float) (collidePosX + o2x + ox), (float) (collidePosY + o2y + oy), (float) (collidePosZ + o2z + oz), 15), getX() + o2x + ox, getY() + o2y + oy, getZ() + o2z + oz, 0, 0, 0);
                    }
                    particleCount = 4;
                    while (particleCount --> 0) {
                        double radius = 2f;
                        double yaw = random.nextFloat() * 2 * Math.PI;
                        double pitch = random.nextFloat() * 2 * Math.PI;
                        double ox = radius * Math.sin(yaw) * Math.sin(pitch);
                        double oy = radius * Math.cos(pitch);
                        double oz = radius * Math.cos(yaw) * Math.sin(pitch);
                        double o2x = -1 * Math.cos(getYaw()) * Math.cos(getPitch());
                        double o2y = -1 * Math.sin(getPitch());
                        double o2z = -1 * Math.sin(getYaw()) * Math.cos(getPitch());
                        level().addParticle(ParticleOrb.Data.create((float) (collidePosX + o2x + ox), (float) (collidePosY + o2y + oy), (float) (collidePosZ + o2z + oz), 20), collidePosX + o2x, collidePosY + o2y, collidePosZ + o2z, 0, 0, 0);
                    }
                }
            }
        }
        if (tickCount - 20 > getDuration()) {
            on = false;
        }
    }

public void tick() {
        super.tick();
        prevScreenShakeAmount = screenShakeAmount;
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (screenShakeAmount > 0) {
            screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
        }
        if (this.onGround() && !this.isInFluidType() && this.walkAnimation.speed() > 0.1F && !this.isBaby()) {
            float f = (float) Math.cos(this.walkAnimation.position() * 0.8F - 1.5F);
            if (Math.abs(f) < 0.2) {
                if (screenShakeAmount <= 0.3) {
                    this.playSound(ACSoundRegistry.TREMORSAURUS_STOMP.get(), 2, 1.0F);
                    this.shakeWater();
                }
                screenShakeAmount = 1F;
            }
        }
        if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
        }
        if(this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5){
            this.playRoarSound();
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 40 && !this.isBaby()) {
            screenShakeAmount = 1F;
            roarScatterTime = 30;
            if (this.getAnimationTick() % 5 == 0 && level().isClientSide) {
                this.shakeWater();
            }
        }
        if (roarScatterTime > 0) {
            roarScatterTime--;
            scareMobs();
        }
        if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 5) {
            actuallyPlayAmbientSound();
        }
        if (!level().isClientSide) {
            if (this.getDeltaMovement().horizontalDistance() < 0.05 && this.getAnimation() == NO_ANIMATION && !this.isDancing() && !this.isInSittingPose()) {
                if (random.nextInt(180) == 0) {
                    this.setAnimation(ANIMATION_SNIFF);
                }
                if (random.nextInt(600) == 0 && !this.isVehicle()) {
                    this.tryRoar();
                }
            }
            boolean held = false;
            if (riderHitEntity != null && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() > 10 && this.getAnimationTick() <= 12) {
                if (this.hasLineOfSight(riderHitEntity) && this.distanceTo(riderHitEntity) < this.getBbWidth() + riderHitEntity.getBbWidth() + 2.0D) {
                    riderHitEntity.hurt(riderHitEntity.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                    if (riderHitEntity instanceof LivingEntity living) {
                        living.knockback(0.5D, this.getX() - riderHitEntity.getX(), this.getZ() - riderHitEntity.getZ());
                    }
                    riderHitEntity = null;
                }
            }
            LivingEntity target = riderHitEntity instanceof LivingEntity ? (LivingEntity) riderHitEntity : this.getTarget();
            if (target != null && target.isAlive() && target.distanceTo(this) < (isVehicle() ? 10.0F : 5.5F)) {
                if (this.getAnimation() == ANIMATION_SHAKE_PREY && this.getAnimationTick() <= 35) {
                    held = true;
                    this.setHeldMobId(target.getId());
                }
            }
            if (!held && getHeldMobId() != -1) {
                this.setHeldMobId(-1);
                this.playSound(ACSoundRegistry.TREMORSAURUS_THROW.get());
                riderHitEntity = null;
            }
        } else {
            Player player = AlexsCaves.PROXY.getClientSidePlayer();
            if (player != null && player.isPassengerOfSameVehicle(this)) {
                if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
                }
                if (AlexsCaves.PROXY.isKeyDown(3) && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 3));
                }
            }
        }
        if (this.isVehicle()) {
            if (this.getMeterAmount() < 1.0F) {
                this.setMeterAmount(Math.min(this.getMeterAmount() + 0.0035F, 1.0F));
            }
        } else {
            this.setMeterAmount(0.0F);
        }
        if(this.getAnimation() == ANIMATION_SHAKE_PREY && getHeldMobId() != -1){
            Entity entity = level().getEntity(getHeldMobId());
            if(entity != null){
                if (this.getAnimationTick() <= 35) {
                    Vec3 shakePreyPos = getShakePreyPos();
                    Vec3 minus = new Vec3(shakePreyPos.x - entity.getX(), shakePreyPos.y - entity.getY(), shakePreyPos.z - entity.getZ());
                    entity.setDeltaMovement(minus);
                    if (this.getAnimationTick() % 10 == 0) {
                        entity.hurt(damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                    }
                }else{
                    entity.setDeltaMovement(entity.getDeltaMovement().scale(0.6F));
                }
            }
        }
        if (roarCooldown > 0) {
            roarCooldown--;
        }
        lastStompX = this.getX();
        lastStompZ = this.getZ();
    }

@Override
    public void aiStep() {
        super.aiStep();
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null && this.hasLineOfSight(attackTarget)) {
            int index = random.nextInt(getHeadCount());
            if (!isBreathing[index] && !isStriking[index]) {
                if (this.distanceTo(attackTarget) < 6) {
                    if (strikeCooldown == 0 && strikingProgress[index] == 0) {
                        isBreathing[index] = false;
                        isStriking[index] = true;
                        this.level.broadcastEntityEvent(this, (byte) (40 + index));
                        strikeCooldown = 3;
                    }
                } else if (random.nextBoolean() && breathCooldown == 0) {
                    isBreathing[index] = true;
                    isStriking[index] = false;
                    this.level.broadcastEntityEvent(this, (byte) (50 + index));
                    breathCooldown = 15;
                }

            }

        }
        for (int i = 0; i < HEADS; i++) {
            boolean striking = isStriking[i];
            boolean breathing = isBreathing[i];
            prevStrikeProgress[i] = strikingProgress[i];
            if (striking && strikingProgress[i] > 9) {
                isStriking[i] = false;
                if (attackTarget != null && this.distanceTo(attackTarget) < 6) {
                    attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                    attackTarget.addEffect(new MobEffectInstance(MobEffects.POISON, 100, 3, false, false));
                    attackTarget.knockback(0.25F, this.getX() - attackTarget.getX(), this.getZ() - attackTarget.getZ());
                }
            }
            if (breathing) {
                if (tickCount % 7 == 0 && attackTarget != null && i < this.getHeadCount()) {
                    Vec3 Vector3d = this.getViewVector(1.0F);
                    if (random.nextFloat() < 0.2F) {
                        this.playSound(IafSoundRegistry.HYDRA_SPIT, this.getSoundVolume(), this.getVoicePitch());
                    }
                    double headPosX = this.headBoxes[i].getX() + Vector3d.x;
                    double headPosY = this.headBoxes[i].getY() + 1.3F;
                    double headPosZ = this.headBoxes[i].getZ() + Vector3d.z;
                    double d2 = attackTarget.getX() - headPosX + this.random.nextGaussian() * 0.4D;
                    double d3 = attackTarget.getY() + attackTarget.getEyeHeight() - headPosY + this.random.nextGaussian() * 0.4D;
                    double d4 = attackTarget.getZ() - headPosZ + this.random.nextGaussian() * 0.4D;
                    EntityHydraBreath entitylargefireball = new EntityHydraBreath(IafEntityRegistry.HYDRA_BREATH.get(),
                        level, this, d2, d3, d4);
                    entitylargefireball.setPos(headPosX, headPosY, headPosZ);
                    if (!level.isClientSide) {
                        level.addFreshEntity(entitylargefireball);
                    }
                }
                if (isBreathing[i] && (attackTarget == null || !attackTarget.isAlive() || breathTicks[i] > 60) && !level.isClientSide) {
                    isBreathing[i] = false;
                    breathTicks[i] = 0;
                    breathCooldown = 15;
                    this.level.broadcastEntityEvent(this, (byte) (60 + i));
                }
                breathTicks[i]++;
            } else {
                breathTicks[i] = 0;
            }
            if (striking && strikingProgress[i] < 10.0F) {
                strikingProgress[i] += 2.5F;
            } else if (!striking && strikingProgress[i] > 0.0F) {
                strikingProgress[i] -= 2.5F;
            }
            prevSpeakingProgress[i] = speakingProgress[i];
            if (speakingProgress[i] > 0.0F) {
                speakingProgress[i] -= 0.1F;
            }
            prevBreathProgress[i] = breathProgress[i];
            if (breathing && breathProgress[i] < 10.0F) {
                breathProgress[i] += 1.0F;
            } else if (!breathing && breathProgress[i] > 0.0F) {
                breathProgress[i] -= 1.0F;
            }

        }
        if (strikeCooldown > 0) {
            strikeCooldown--;
        }
        if (breathCooldown > 0) {
            breathCooldown--;
        }
        if (this.getHeadCount() == 1 && this.getSeveredHead() != -1) {
            this.setSeveredHead(-1);
        }
        if (this.getHeadCount() == 1 && !this.isOnFire()) {
            this.setHeadCount(2);
            this.setSeveredHead(1);
            onlyRegrowOneHeadNotTwo = true;
        }

        if (this.getSeveredHead() != -1 && this.getSeveredHead() < this.getHeadCount()) {
            this.setSeveredHead(Mth.clamp(this.getSeveredHead(), 0, this.getHeadCount() - 1));
            regrowHeadCooldown++;
            if (regrowHeadCooldown >= 100) {
                headDamageTracker[this.getSeveredHead()] = 0;
                this.setSeveredHead(-1);
                if (this.isOnFire()) {
                    this.setHeadCount(this.getHeadCount() - 1);
                } else {
                    this.playSound(IafSoundRegistry.HYDRA_REGEN_HEAD, this.getSoundVolume(), this.getVoicePitch());
                    if (!onlyRegrowOneHeadNotTwo) {
                        this.setHeadCount(this.getHeadCount() + 1);
                    }
                }
                onlyRegrowOneHeadNotTwo = false;
                regrowHeadCooldown = 0;
            }
        } else {
            regrowHeadCooldown = 0;
        }
    }

public void tick() {
        super.tick();
        prevOpenProgress = openProgress;
        prevClutchProgress = clutchProgress;
        prevBiteProgress = biteProgress;
        prevCosmawPitch = this.getCosmawPitch();
        if (!this.level().isClientSide) {
            final float f2 = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
            this.setCosmawPitch(this.getCosmawPitch() + 0.6F * (this.getCosmawPitch() + f2) - this.getCosmawPitch());
        }

        if (isMouthOpen()) {
            if (openProgress < 5F)
                openProgress++;
        } else {
            if (openProgress > 0F)
                openProgress--;
        }

        if (isVehicle()) {
            if (clutchProgress < 5F)
                clutchProgress++;
        } else {
            if (clutchProgress > 0F)
                clutchProgress--;
        }

        if (this.entityData.get(ATTACK_TICK) > 0) {
            if (biteProgress < 5F) {
                biteProgress = Math.min(5F, biteProgress + 2F);
            } else {
                if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 3.3D) {
                    if (this.getTarget() instanceof EntityCosmicCod && !this.isTame()) {
                        EntityCosmicCod fish = (EntityCosmicCod) this.getTarget();
                        CompoundTag fishNbt = new CompoundTag();
                        fish.addAdditionalSaveData(fishNbt);
                        fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                        fish.readAdditionalSaveData(fishNbt);
                    }
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                }
                this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            }
        } else {
            if (biteProgress > 0F) {
                biteProgress -= 1F;
            }
        }
        if (!this.getMainHandItem().isEmpty()) {
            heldItemTime++;
            if (heldItemTime > 30 && canTargetItem(this.getMainHandItem())) {
                heldItemTime = 0;
                this.heal(4);
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
                if (this.getMainHandItem().is(AMTagRegistry.COSMAW_TAMEABLES) && fishThrowerID != null && !this.isTame()) {
                    if (getRandom().nextFloat() < 0.3F) {
                        this.setTame(true);
                        this.setCommand(1);
                        this.setOwnerUUID(this.fishThrowerID);
                        Player player = level().getPlayerByUUID(fishThrowerID);
                        if (player instanceof ServerPlayer) {
                            CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer) player, this);
                        }
                        this.level().broadcastEntityEvent(this, (byte) 7);
                    } else {
                        this.level().broadcastEntityEvent(this, (byte) 6);
                    }
                }
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.getMainHandItem().shrink(1);
            }
        } else {
            heldItemTime = 0;
        }
        if (!this.level().isClientSide) {
            if (tickCount % 100 == 0 || lastSafeTpPosition == null) {
                BlockPos pos = getCosmawGround(this.blockPosition());
                if (pos.getY() > 1) {
                    lastSafeTpPosition = pos;
                }
            }

            if (this.isVehicle()) {
                if (lastSafeTpPosition != null) {
                    final double dist = this.distanceToSqr(Vec3.atCenterOf(lastSafeTpPosition));
                    float speed = 0.8F;
                    if(this.getY() < -40){
                        speed = 3F;
                    }
                    if (verticalCollision && dist > 14) {
                        this.setYRot(this.stuckRot);
                        if (random.nextInt(50) == 0) {
                            this.stuckRot = Mth.wrapDegrees(this.stuckRot + 90);

                        }
                        final float angle = (Maths.STARTING_ANGLE * stuckRot);
                        final double extraX = -2 * Mth.sin(Mth.PI + angle);
                        final double extraZ = -2 * Mth.cos(angle);
                        this.getMoveControl().setWantedPosition(this.getX() + extraX, this.getY() + 2, this.getZ() + extraZ, speed);
                    } else if (lastSafeTpPosition.getY() > this.getY() + 2.3F) {
                        this.getMoveControl().setWantedPosition(this.getX(), this.getY() + 2, this.getZ(), speed);
                    } else {
                        this.getMoveControl().setWantedPosition(lastSafeTpPosition.getX(), lastSafeTpPosition.getY() + 2, lastSafeTpPosition.getZ(), speed);
                    }
                    if (dist < 7 && getCosmawGround(this.blockPosition()).getY() > 1) {
                        this.ejectPassengers();
                    }
                } else {
                    if (this.getY() < 0F) {
                        this.getDeltaMovement().add(0, 0.75F, 0);
                    } else if (this.getY() < 80F) {
                        this.getDeltaMovement().add(0, 0.1F, 0);
                    }
                }

            }
        }

    }

public void tick() {
        super.tick();
        prevSitProgress = sitProgress;
        prevSleepProgress = sleepProgress;
        prevHoldProgress = holdProgress;
        prevStealthProgress = stealthProgress;

        final boolean sitting = isSitting();
        final boolean sleeping = isSleeping();
        final boolean holding = isHolding();
        final boolean stealth = isStealth();

        if (sitting) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (sleeping) {
            if (sleepProgress < 5F)
                sleepProgress++;
        } else {
            if (sleepProgress > 0F)
                sleepProgress--;
        }

        if (holding) {
            if (holdProgress < 5F)
                holdProgress++;
        } else {
            if (holdProgress > 0F)
                holdProgress--;
        }

        if (stealth) {
            if (stealthProgress < 10F)
                stealthProgress += 0.25F;
        } else {
            if (stealthProgress > 0F)
                stealthProgress--;
        }

        if (!this.level().isClientSide) {
            if (isRunning() && !hasSpedUp) {
                hasSpedUp = true;
                this.setMaxUpStep(1F);
                this.setSprinting(true);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.4F);
            }
            if (!isRunning() && hasSpedUp) {
                hasSpedUp = false;
                this.setMaxUpStep(0.6F);
                this.setSprinting(false);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
            if ((isSitting() || isSleeping()) && (++sittingTime > maxSitTime || this.getTarget() != null || this.isInLove() || dontSitFlag || this.isInWaterOrBubble())) {
                this.setSitting(false);
                this.setSleeping(false);
                sittingTime = 0;
                maxSitTime = 100 + random.nextInt(50);
            }
            if (this.getTarget() == null && !dontSitFlag && this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSleeping() && !this.isSitting() && !this.isInWaterOrBubble() && random.nextInt(100) == 0) {
                sittingTime = 0;
                if (this.getRandom().nextBoolean()) {
                    maxSitTime = 100 + random.nextInt(550);
                    this.setSitting(true);
                    this.setSleeping(false);
                } else {
                    maxSitTime = 200 + random.nextInt(550);
                    this.setSitting(false);
                    this.setSleeping(true);
                }
            }
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSleeping() && !this.isSitting() && random.nextInt(100) == 0) {
                this.setAnimation(ANIMATION_TAIL_FLICK);
            }
        }
        if (this.isHolding()) {
            this.setSprinting(false);
            this.setRunning(false);
            Entity target = this.getTarget();
            if (!this.level().isClientSide && target != null && target.isAlive()) {
                this.setXRot(0);
                final float radius = 1.0F + target.getBbWidth() * 0.5F;
                final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                final double extraX = radius * Mth.sin(Mth.PI + angle);
                final double extraZ = radius * Mth.cos(angle);
                final double extraY = -0.5F;
                Vec3 minus = new Vec3(this.getX() + extraX - target.getX(), this.getY() + extraY - target.getY(), this.getZ() + extraZ - target.getZ());
                target.setDeltaMovement(minus);
                target.hasImpulse = true;
                if (holdTime % 20 == 0) {
                    target.hurt(this.damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                }
                if(target.distanceTo(this) > 8.0F){
                    this.setHolding(false);
                    holdTime = 150;
                }
            }
            holdTime++;
            if (holdTime > 100) {
                holdTime = 0;
                this.setHolding(false);
            }
        } else {
            holdTime = 0;
        }
        if (prevScaredMobId != this.entityData.get(LAST_SCARED_MOB_ID) && this.level().isClientSide) {
            Entity e = level().getEntity(this.entityData.get(LAST_SCARED_MOB_ID));
            if (e != null) {
                final double d2 = this.random.nextGaussian() * 0.1D;
                final double d0 = this.random.nextGaussian() * 0.1D;
                final double d1 = this.random.nextGaussian() * 0.1D;
                this.level().addParticle(AMParticleRegistry.SHOCKED.get(), e.getX(), e.getEyeY() + e.getBbHeight() * 0.15F + (double) (this.random.nextFloat() * e.getBbHeight() * 0.15F), e.getZ(), d0, d1, d2);
            }
        }
        if(this.getTarget() != null && this.getTarget().hasEffect(AMEffectRegistry.TIGERS_BLESSING.get())){
            this.setTarget(null);
            this.setLastHurtByMob(null);
        }
        prevScaredMobId = this.entityData.get(LAST_SCARED_MOB_ID);
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public void tick() {
		super.tick();
		prevRightPunchProgress = rightPunchProgress;
		prevLeftPunchProgress = leftPunchProgress;
		prevLaserX = this.getLaserX();
		prevLaserY = this.getLaserY();
		prevLaserZ = this.getLaserZ();
		prevLaserProgress = laserProgress;
		if (laserProgress < 1.0F && this.isUsingBeamAttack() && !this.isUsingRegularAttack()) {
			laserProgress += 0.1F;
		}
		if (laserProgress > 0.0F && (!this.isUsingBeamAttack() || this.isUsingRegularAttack())) {
			laserProgress -= 0.1F;
		}
		if (getTarget() != null) {
			targetDistance = distanceTo(getTarget()) - getTarget().getBbWidth() / 2f;
			targetAngle = (float) getAngleBetweenEntities(this, getTarget());
		}
		if (getTarget() != null && (!getTarget().isAlive() || getTarget().getHealth() <= 0))
			setTarget(null);
		if (!level().isClientSide()) {
			if (!isNoAi()) {
				if (isActive()) {
					if (getTarget() == null) {
						setActive(false);
					}
				} else if (getTarget() != null && targetDistance <= 30 || getTarget() != null && targetDistance <= 30) {
					setActive(true);
				}
				if(this.getHealthRatio() < 0.5F && shieldCooldown == 0 && !this.hasHealingShield()){
					shieldCooldown = 300 + random.nextInt(300);
					this.setHealingShield(3);
				}
			}
		}
		if (!isActive()) {
			setDeltaMovement(0, getDeltaMovement().y, 0);
			yRot = yRotO;
			if (this.getHealth() < this.getMaxHealth()) {
				this.setHealingShield(1);
			}
			if (this.getHealth() == this.getMaxHealth()) {
				this.setHealingShield(0);
			}
		}
		yBodyRot = yHeadRot;
		if (!level().isClientSide() && hasHealingShield()){
			if(this.getTarget() == null){
				this.heal(0.3F);
			}else{
				double dist = this.distanceTo(this.getTarget());
				if(dist > 16.0F){
					this.heal(3F);
				}else{
					this.heal((float)Mth.clamp(dist * 0.085F, 0.2F, 3F));
				}
			}
		}
		if (this.entityData.get(MELEE_TICK) > 0 && isUsingRegularAttack()) {
			if (Math.max(rightPunchProgress, leftPunchProgress) == 5 && this.getTarget() != null && this.distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 2.0F) {
				this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
				if (this.getTarget().isBlocking()) {
					((Player)this.getTarget()).getCooldowns().addCooldown(Items.SHIELD, 100);
					((Player)this.getTarget()).stopUsingItem();
					this.level().broadcastEntityEvent(((Player)this.getTarget()), (byte)30);
				}
			}
			this.entityData.set(MELEE_TICK, this.entityData.get(MELEE_TICK) - 1);
			if (this.entityData.get(MELEE_TICK) == 0) {
				usingLeftHand = !usingLeftHand;
			}
			if (!usingLeftHand && rightPunchProgress < 5F) {
				rightPunchProgress += 2.5F;
			}
			if (usingLeftHand && leftPunchProgress < 5F) {
				leftPunchProgress += 2.5F;
			}
		} else {
			if (leftPunchProgress > 0F) {
				leftPunchProgress -= Math.min(0.5F, leftPunchProgress);
			}
			if (rightPunchProgress > 0F) {
				rightPunchProgress -= Math.min(0.5F, rightPunchProgress);
			}
		}
		if (usingLeftHand) {
			if (rightPunchProgress > 0F) {
				rightPunchProgress--;
			}
		} else {
			if (leftPunchProgress > 0F) {
				leftPunchProgress--;
			}
		}
		if (this.isUsingBeamAttack()) {
			double d0 = this.getLaserX() - this.getX();
			double d1 = this.getLaserY() - this.getY(1);
			double d2 = this.getLaserZ() - this.getZ();
			double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
			d0 = d0 / d3;
			d1 = d1 / d3;
			d2 = d2 / d3;
			double d4 = this.random.nextDouble();
			while (d4 < d3) {
				d4 += 3.0D - this.random.nextDouble() * 2.5D;
				this.level().addParticle(PFParticles.BOSS_LASER.get(), this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, (random.nextFloat() - 0.5F) * 0.1F, random.nextFloat() * 0.2F, (random.nextFloat() - 0.5F) * 0.1F);
			}
		}
		if(this.hasHealingShield() && level().isClientSide()){
			for(int i = 0; i < 2 + random.nextInt(2); i++){
				this.level().addParticle(PFParticles.BOSS_HEAL.get(), this.getRandomX(2.0D), this.getY(), this.getRandomZ(2.0D), this.getX(), this.getY(0.75F), this.getZ());
			}
		}
		if (this.getLaserTick() < 0) {
			this.setLaserTick(this.getLaserTick() + 1);
		}
		if(shieldCooldown > 0 && !this.hasHealingShield()){
			shieldCooldown--;
		}
	}

public void tick() {
        super.tick();

        this.prevSwimProgress = swimProgress;

        final boolean ground = !this.isInWaterOrBubble();

        if (!ground && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (ground && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (ground && swimProgress > 0) {
            swimProgress--;
        }
        if (!ground && swimProgress < 5F) {
            swimProgress++;
        }
        if (!this.level().isClientSide) {
            if (isInWater()) {
                swimTimer++;
            } else {
                swimTimer--;
            }
        }

        prevHeadHeight = this.getHeadHeight();
        float neckBase = 5.5F;
        if (!this.isNoAi() && !this.isBaby()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            float yaw = this.getYRot() * ((float) Math.PI / 180F);
            float neckContraction = 0.3F * Math.abs(getHeadHeight() / 3) + 0.5F * Math.abs(getHeadYaw(0) / 50F);

            for (int l = 0; l < this.theEntireNeck.length; ++l) {
                float f = l / ((float) this.theEntireNeck.length);
                float f1 = -(2.2F + l - f * neckContraction);
                float f2 = Mth.sin(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                float f3 = Mth.cos(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                this.setPartPosition(this.theEntireNeck[l], f2 * f1, neckBase + Math.sin(f * Math.PI * 0.5F) * (getHeadHeight() * -11.1F), -f3 * f1);
            }

            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
        }
        if (entityToLaunchId != -1 && this.isAlive()) {
            Entity launch = this.level().getEntity(entityToLaunchId);
            this.ejectPassengers();
            entityToLaunchId = -1;
            if (launch != null && !launch.isPassenger()) {
                if (launch instanceof LivingEntity) {
                    this.playSound(UPSounds.BRACHI_TOSS.get(), 0.5F, 0.5F);
                    launch.setPos(this.getEyePosition().add(0, 1, 0));
                    float rot = 180F + this.getYRot();
                    float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                    float x = Mth.sin(rot * ((float) Math.PI / 180F));
                    float z = -Mth.cos(rot * ((float) Math.PI / 180F));
                    if (!(strength <= 0.0D)) {
                        launch.hasImpulse = true;
                        Vec3 vec3 = this.getDeltaMovement();
                        Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                        launch.setDeltaMovement(vec31.x, strength, vec31.z);
                    }
                }
            }
        }
        if (this.isLaunching()) {
            Entity passenger = this.getControllingPassenger();
            if (passenger instanceof LivingEntity) {
                entityToLaunchId = passenger.getId();
                this.setLaunching(false);
                for (Entity rider : this.getPassengers()) {
                    if (rider instanceof Player player) {
                        player.addEffect(new MobEffectInstance(UPEffects.BRACHI_PROTECTION.get(), 200));
                    }
                }
            }
        }
        if (!level().isClientSide) {
            if (this.isVehicle()) {
                ridingTime++;
                if (ridingTime >= this.getMaxRidingTime()) {
                    this.setLaunching(true);
                    this.isLaunching();
                }
            } else {
                ridingTime = 0;
                this.setLaunching(false);
            }
            if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D && this.isLaunching()) {
                for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                    if (!(entity instanceof BrachiosaurusEntity) && !entity.isPassengerOfSameVehicle(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                        if (entity.onGround()) {
                            double d0 = entity.getX() - this.getX();
                            double d1 = entity.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            float f = 0.5F;
                            entity.push(d0 / d2 * f, f, d1 / d2 * f);
                        }
                    }
                }
            }
        }
        if ( headPeakCooldown == 0) {
            float low = getLowHeadHeight();
            this.setHeadHeight(this.getHeadHeight() + (0.5F + ((getLowHeadHeight() + getHighHeadHeight(low)) / 2F) - this.getHeadHeight()) * 0.2F);
        } else {
            if (getMaxFluidHeight() <= this.getBbHeight() * 0.5F && getMaxFluidHeight() >= this.getBbHeight() * 0.25F) {
                float mot = (float) this.getDeltaMovement().lengthSqr();
                this.setHeadHeight(Mth.clamp(this.getHeadHeight() + 0.1F - 0.2F * mot, 0, 2));
                headPeakCooldown = 5;
            }
        }

        this.TailKinematics.calculateTailAngles(this);
    }

public void tick() {
        prevFlyAngle = this.getFlyAngle();
        super.tick();
        prevAttackProgress = attackProgress;
        prevFlyProgress = flyProgress;
        prevSitProgress = sitProgress;
        prevDragProgress = dragProgress;
        prevDigProgress = digProgress;

        final boolean flying = this.isFlying();
        final boolean sitting = this.isSitting();
        final boolean dragging = this.isDragging();
        final boolean digging = this.isDigging();

        if (flying) {
            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (flyProgress > 0F)
                flyProgress--;
        }

        if (sitting) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (dragging) {
            if (dragProgress < 5F)
                dragProgress++;
        } else {
            if (dragProgress > 0F)
                dragProgress--;
        }

        if (digging) {
            if (digProgress < 5F)
                digProgress++;
        } else {
            if (digProgress > 0F)
                digProgress--;
        }

        if (flightSize && !flying) {
            this.refreshDimensions();
            flightSize = false;
        }
        if (!flightSize && isFlying()) {
            this.refreshDimensions();
            flightSize = true;
        }
        float threshold = 0.015F;
        if (isFlying() && this.yRotO - this.getYRot() > threshold) {
            this.setFlyAngle(this.getFlyAngle() + 5);
        } else if (isFlying() && this.yRotO - this.getYRot() < -threshold) {
            this.setFlyAngle(this.getFlyAngle() - 5);
        } else if (this.getFlyAngle() > 0) {
            this.setFlyAngle(Math.max(this.getFlyAngle() - 4, 0));
        } else if (this.getFlyAngle() < 0) {
            this.setFlyAngle(Math.min(this.getFlyAngle() + 4, 0));
        }
        this.setFlyAngle(Mth.clamp(this.getFlyAngle(), -30, 30));
        if (!this.level().isClientSide) {
            if (isFlying() && this.isLandNavigator) {
                switchNavigator(false);
            }
            if (!isFlying() && !this.isLandNavigator) {
                switchNavigator(true);
            }
            if (isFlying()) {
                if(timeFlying % 25 == 0){
                    this.playSound(AMSoundRegistry.TARANTULA_HAWK_WING.get(), this.getSoundVolume(), this.getVoicePitch());
                }
                timeFlying++;
                this.setNoGravity(true);
                if (this.isSitting() || this.isPassenger() || this.isInLove()) {
                    this.setFlying(false);
                }
            } else {
                timeFlying = 0;
                this.setNoGravity(false);
            }
            if (this.getTarget() != null && this.getTarget() instanceof Player && !this.isTame()) {
                this.entityData.set(ANGRY, true);
            } else {
                this.entityData.set(ANGRY, false);
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if (isDigging() && level().getBlockState(this.getBlockPosBelowThatAffectsMyMovement()).canOcclude()) {
            BlockPos posit = this.getBlockPosBelowThatAffectsMyMovement();
            BlockState understate = level().getBlockState(posit);
            for (int i = 0; i < 4 + random.nextInt(2); i++) {
                final double particleX = posit.getX() + random.nextFloat();
                final double particleY = posit.getY() + 1F;
                final double particleZ = posit.getZ() + random.nextFloat();
                final double motX = this.random.nextGaussian() * 0.02D;
                final double motY = 0.1F + random.nextFloat() * 0.2F;
                final double motZ = this.random.nextGaussian() * 0.02D;
                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, understate), particleX, particleY, particleZ, motX, motY, motZ);
            }
        }
        if(this.tickCount > 0 && tickCount % 300 == 0 && this.getHealth() < this.getMaxHealth()){
            this.heal(1);
        }
        if(!this.level().isClientSide && this.isDragging() && this.getPassengers().isEmpty() && !this.isDigging()){
            dragTime++;
            if(dragTime > 5000){
                dragTime = 0;
                for(Entity e : this.getPassengers()){
                    e.hurt(this.damageSources().mobAttack(this), 10);
                }
                this.ejectPassengers();
                this.setDragging(false);
            }
        }
    }

public void tick() {
        super.tick();
        if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(true);
            this.setOrderedToSit(true);
            this.setStanding(false);
        }
        if (isEating() && !this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(false);
            eatingTime = 0;
            if (!forcedSit) {
                this.setOrderedToSit(true);
            }
        }
        if (isEating()) {
            eatingTime++;
            if (!this.getMainHandItem().is(ItemTags.LEAVES)) {
                for (int i = 0; i < 3; i++) {
                    double d2 = this.random.nextGaussian() * 0.02D;
                    double d0 = this.random.nextGaussian() * 0.02D;
                    double d1 = this.random.nextGaussian() * 0.02D;
                    this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
                }
            }
            if (eatingTime % 5 == 0) {
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.PANDA_EAT, this.getSoundVolume(), this.getVoicePitch());
            }
            if (eatingTime > 100) {
                ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
                if (!stack.isEmpty()) {
                    this.heal(4);
                    if (isTameableFood(stack) && bananaThrowerID != null) {
                        if (getRandom().nextFloat() < 0.3F) {
                            this.setTame(true);
                            this.setOwnerUUID(this.bananaThrowerID);
                            Player player = level().getPlayerByUUID(bananaThrowerID);
                            if (player instanceof ServerPlayer) {
                                CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer)player, this);
                            }
                            this.level().broadcastEntityEvent(this, (byte) 7);
                        } else {
                            this.level().broadcastEntityEvent(this, (byte) 6);
                        }
                    }
                    if (stack.hasCraftingRemainingItem()) {
                        this.spawnAtLocation(stack.getCraftingRemainingItem());
                    }
                    stack.shrink(1);
                }
                eatingTime = 0;
            }
        }
        prevSitProgress = sitProgress;
        prevStandProgress = standProgress;

        if (this.isSitting()) {
            if (sitProgress < 10F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (this.isStanding()) {
            if (standProgress < 10F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        if (this.isPassenger() && this.getVehicle() instanceof EntityGorilla) {
            if(!this.isBaby()){
                this.removeVehicle();
            }else{
                EntityGorilla mount = (EntityGorilla) this.getVehicle();
                this.setYRot( mount.yBodyRot);
                this.yHeadRot = mount.yBodyRot;
                this.yBodyRot = mount.yBodyRot;
            }
        }
        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
            this.setOrderedToSit(false);
            sittingTime = 0;
            maxSitTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && this.isSitting() && (this.getTarget() != null || this.isStanding()) && !this.isEating()) {
            this.setOrderedToSit(false);
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
            maxSitTime = 300 + random.nextInt(250);
            this.setOrderedToSit(true);
        }
        if (this.forcedSit && !this.isVehicle() && this.isTame()) {
            this.setOrderedToSit(true);
        }
        if (sitProgress == 0 && poundChestCooldown <= 0 && this.isSilverback() && random.nextInt(800) == 0 && this.getAnimation() == NO_ANIMATION && !this.isSitting() && !this.isNoAi() && this.getMainHandItem().isEmpty()) {
            this.setAnimation(ANIMATION_POUNDCHEST);
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 10) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
            getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (!hasSilverbackAttributes && isSilverback() && !isBaby()) {
            hasSilverbackAttributes = true;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(50F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10F);
            this.heal(50F);
        }
        if (hasSilverbackAttributes && !isSilverback() && !isBaby()) {
            hasSilverbackAttributes = false;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(8F);
            this.heal(30F);
        }
        if(poundChestCooldown > 0){
            poundChestCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@SubscribeEvent
    public static void serverTick(LevelTickEvent.Post event) {
        if (INSTANCE.dirtyProjectiles.isEmpty()) {
            return;
        }
        if (event.getLevel() instanceof ServerLevel serverLevel) {
            HashMap<Entity, List<Projectile>> toSync = new HashMap<Entity, List<Projectile>>();
            var dirtyProjectiles = INSTANCE.dirtyProjectiles.getOrDefault(serverLevel.dimension(), List.of());
            for (int i = dirtyProjectiles.size() - 1; i >= 0; i--) {
                var projectile = dirtyProjectiles.get(i);
                if (projectile.isRemoved()) {
                    dirtyProjectiles.remove(i);
                    continue;
                }
                if (projectile.isAddedToLevel()) {
                    Vec3 start = projectile.position();
                    int searchRange = 48;
                    Vec3 end = Utils.raycastForBlock(serverLevel, start, projectile.getDeltaMovement().normalize().scale(searchRange).add(start), ClipContext.Fluid.NONE).getLocation();
                    for (Map.Entry<UUID, HashSet<Projectile>> entityToTrackedProjectiles : GuidingBoltManager.INSTANCE.trackedEntities.entrySet()) {
                        var entity = serverLevel.getEntity(entityToTrackedProjectiles.getKey());
                        if (entity != null) {
                            if (Math.abs(entity.getX() - projectile.getX()) > searchRange || Math.abs(entity.getY() - projectile.getY()) > searchRange || Math.abs(entity.getZ() - projectile.getZ()) > searchRange) {
                                continue;
                            }
                            float homeRadius = 3.5f + Math.min(entity.getBbWidth() * .5f, 2);
                            if (!entity.equals(projectile.getOwner()) && (entity.getBoundingBox().inflate(homeRadius).contains(start) || Utils.checkEntityIntersecting(entity, start, end, homeRadius).getType() == HitResult.Type.ENTITY)) {
                                updateTrackedProjectiles(entityToTrackedProjectiles.getValue(), projectile);
                                toSync.computeIfAbsent(entity, (key) -> new ArrayList<>()).add(projectile);
                                break;
                            }
                        }
                    }
                    dirtyProjectiles.remove(i);
                }
            }
            for (Map.Entry<Entity, List<Projectile>> entry : toSync.entrySet()) {
                var entity = entry.getKey();
                PacketDistributor.sendToPlayersTrackingEntity(entity, new GuidingBoltManagerStartTrackingPacket(entity, entry.getValue()));
            }
        }
    }

private void hitEntities(ServerPlayer player, ItemModularHandheld item, ItemStack itemStack, AABB aoe,
            double damageMultiplier, int revengeLevel, boolean overextend, int overextendLevel, double momentumEfficiency,
            AtomicInteger kills, AtomicInteger revengeKills, AtomicInteger hits) {
        Collection<LivingEntity> momentumTargets = new LinkedList<>();
        player.level().getEntitiesOfClass(LivingEntity.class, aoe).stream()
                .filter(entity -> entity != player)
                .filter(entity -> !player.isAlliedTo(entity))
                .forEach(entity -> {
                    double individualDamageMultiplier = damageMultiplier;

                    boolean canRevenge = revengeLevel > 0 && RevengeTracker.canRevenge(player, entity);
                    if (canRevenge) {
                        individualDamageMultiplier += revengeLevel / 100d;
                    }

                    if (overextend && entity.getHealth() / entity.getMaxHealth() >= overextendLevel / 100f) {
                        individualDamageMultiplier *= 2;
                    }

                    AbilityUseResult result = item.hitEntity(itemStack, player, entity, individualDamageMultiplier, 0.5f, 0.2f);
                    if (result != AbilityUseResult.fail) {
                        if (!entity.isAlive()) {
                            kills.incrementAndGet();

                            if (canRevenge) {
                                revengeKills.incrementAndGet();
                                RevengeTracker.removeEnemySynced(player, entity);
                            }
                        } else if (momentumEfficiency > 0) {
                            momentumTargets.add(entity);
                        }

                        hits.incrementAndGet();
                    }

                    if (result == AbilityUseResult.crit) {
                        player.getCommandSenderWorld().playSound(player, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 1.3f);
                    }
                });

        if (momentumEfficiency > 0 && kills.get() > 0) {
            int stunDuration = (int) (momentumEfficiency * kills.get() * 20);
            momentumTargets.forEach(entity -> entity.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false)));
        }
    }

@Override
	public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
		if (SuperpositionHandler.hasSpellstoneCooldown(player))
			return;

		CachedTeleportationLocation location = null;

		if (this.locationCache.containsKey(player)) {
			try {
				var future = this.locationCache.get(player);

				if (future.isDone()) {
					location = this.locationCache.get(player).get();
				} else {
					future.cancel(true);
				}

				this.locationCache.remove(player);
			} catch (Exception ex) {
				ex.printStackTrace();
			}
		}

		if (location == null) {
			EnigmaticLegacy.LOGGER.getInternal().info("No cached location found for {}, generating new one synchronously.", player.getGameProfile().getName());
			location = this.findRandomLocation(player);
		}

		ResourceKey<Level> key = location.dimension();

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
		player.teleportTo(location.x(), location.y(), location.z());

		if (player.level().dimension() != key) {
			SuperpositionHandler.sendToDimension(player, key);
			player.teleportTo(location.x(), location.y(), location.z());
		}

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));

		SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));

		EnigmaticLegacy.LOGGER.getInternal().info("Player {} triggered active ability of Non-Euclidean Cube. Teleported to D: {}, X: {}, Y: {}, Z: {}.",
				player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
	}

@SubscribeEvent
	public static void breatheUnderwater(LivingBreatheEvent event) {
		LivingEntity entity = event.getEntity();
		Level level = entity.level();

		if (level.isClientSide)
			entity.getPersistentData().remove("VisualBacktankAir");

		ItemStack helmet = getWornItem(entity);
		if (helmet.isEmpty())
			return;

		boolean lavaDiving = entity.isInLava();
		if (!helmet.has(DataComponents.FIRE_RESISTANT) && lavaDiving)
			return;

		if (event.canBreathe() && !lavaDiving)
			return;

		List<ItemStack> backtanks = BacktankUtil.getAllWithAir(entity);
		if (backtanks.isEmpty())
			return;

		if (lavaDiving) {
			if (entity instanceof ServerPlayer sp)
				AllAdvancements.DIVING_SUIT_LAVA.awardTo(sp);
			if (backtanks.stream()
				.noneMatch(backtank -> backtank.has(DataComponents.FIRE_RESISTANT)))
				return;
		}

		float visualBacktankAir = 0f;
		for (ItemStack stack : backtanks)
			visualBacktankAir += BacktankUtil.getAir(stack);

		if (level.isClientSide)
			entity.getPersistentData()
				.putInt("VisualBacktankAir", Math.round(visualBacktankAir));

		if (level.getGameTime() % 20 == 0)
			BacktankUtil.consumeAir(entity, backtanks.get(0), 1);

		if (lavaDiving)
			return;

		if (entity instanceof ServerPlayer sp)
			AllAdvancements.DIVING_SUIT.awardTo(sp);

		event.setCanBreathe(true);
		event.setRefillAirAmount(entity.getMaxAirSupply());
	}

public boolean tick() {
			// If empty, this swapper is done.
			if (candidateQueue.isEmpty()) {
				return false;
			}

			int remainingSwaps = BLOCK_SWAP_RATE;
			while (remainingSwaps > 0 && !candidateQueue.isEmpty()) {
				SwapCandidate cand = candidateQueue.poll();

				// If we've already completed this location, move along, as this
				// is just a suboptimal one.
				if (completedCoords.contains(cand.coordinates)) {
					continue;
				}

				// If this candidate is out of range, discard it.
				if (cand.range <= 0) {
					continue;
				}

				// Otherwise, perform the break and then look at the adjacent tiles.
				ToolCommons.removeBlockWithDrops(player, truncator, world,
						cand.coordinates,
						state -> state.is(BlockTags.MINEABLE_WITH_AXE) || state.is(BlockTags.LEAVES));

				remainingSwaps--;

				completedCoords.add(cand.coordinates);

				// Then, go through all of the adjacent blocks and look if
				// any of them are any good.
				for (BlockPos adj : adjacent(cand.coordinates)) {
					var state = world.getBlockState(adj);

					boolean isWood = state.is(BlockTags.LOGS);
					boolean isLeaf = state.is(BlockTags.LEAVES);
					// TODO: Make "blocks the axe will propagate through" a tag
					boolean shouldPropagateThrough = isWood || isLeaf
							|| state.is(Blocks.MANGROVE_ROOTS);

					if (!shouldPropagateThrough) {
						continue;
					}

					// If this is a leaf, it gets
					// the minimum of the leaf range and the current range - 1.
					// Otherwise, it gets the standard range - 1.
					int newRange = isLeaf ? Math.min(LEAF_BLOCK_RANGE, cand.range - 1) : cand.range - 1;

					candidateQueue.offer(new SwapCandidate(adj, newRange));
				}
			}

			// If we did any iteration, then hang around until next tick.
			return true;
		}

@SubscribeEvent
        public static void onLivingDamageModifiers(LivingDamageEvent.Pre event) {
            var target = event.getEntity();
            var source = event.getSource().getEntity();

            if (!target.level().isClientSide() && target.getPersistentData().getLong(FOG_SUFFOCATION_UNTIL_TAG) >= target.level().getGameTime()
                    && event.getSource().is(DamageTypes.IN_WALL)) {
                var modifier = target.getPersistentData().getFloat(FOG_SUFFOCATION_DAMAGE_TAG);

                event.setNewDamage((float) (event.getNewDamage() * (1D + modifier)));
            }

            if (!target.level().isClientSide()) {
                var targetId = target.getStringUUID();

                for (var player : target.level().players()) {
                    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                        var relic = (GhostlyMantleItem) stack.getItem();
                        var marks = relic.getReprisalMarks(stack);
                        var modifier = marks.remove(targetId);

                        if (modifier == null)
                            continue;

                        var original = event.getNewDamage();
                        var modified = original * (1D + modifier);
                        var extra = modified - original;

                        event.setNewDamage((float) modified);
                        relic.setReprisalMarks(stack, marks);

                        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

                        ability.getStatisticData().getMetricData("reprisal_damage").addValue(extra);

                        if (extra > 0D) {
                            var experience = player.getRandom().nextInt((int) (extra + 1D));

                            if (experience > 0)
                                relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "reprisal_damage", experience);
                        }

                        return;
                    }
                }
            }

            if (!(target instanceof Player player) || !(source instanceof LivingEntity attacker) || source == target)
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

                if (!ability.canPlayerUse(player))
                    continue;

                var data = relic.getGazeCharges(stack).get(attacker.getStringUUID());

                if (data == null || data.charges() <= 0)
                    continue;

                var original = event.getNewDamage();
                var reduction = data.charges() * ability.getStatData("weakness").getValue();

                event.setNewDamage((float) Math.max(0D, original * (1D - reduction)));
                ability.getStatisticData().getMetricData("damage_reduced").addValue(original - event.getNewDamage());

                return;
            }
        }

