    	super.onUpdate();
    	renderYawOffset = rotationYaw;
		double a = Math.toRadians(rotationYaw);
		double offSetX = -Math.sin(a) * 1.5D;
		double offSetZ = Math.cos(a) * 1.5D;
		tailPart[0].setLocationAndAngles(posX - offSetX, posY, posZ - offSetZ, 0.0F, 0.0F);

		if (getEntityWorld().getTotalWorldTime()%5 == 0)
			if (getEntityWorld().isRemote)
				flameParticles(getEntityWorld(), tailPart[0].posX, tailPart[0].posY + 0.25, tailPart[0].posZ, rand);

		checkCollision();

		if (getEntityWorld().isRemote) {
			if (getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks <= 1F)
					animationTicks += 0.1F;

			}
			if (!getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks >= 0.1F)
					animationTicks -= 0.1F;

				if (animationTicks < 0F)
					animationTicks = 0F;
			}
		}
		if (!getEntityWorld().isRemote && recentlyHit > 40)
			if(getIsCastingSpell())
				setIsCastingSpell(false);

		if (getEntityWorld().isRemote) {
			if(rand.nextInt(4) == 0) {
				ParticleArgs<?> args = ParticleArgs.get().withDataBuilder().setData(2, this).buildData();
					args.withColor(1F, 1F, 1F, 1F);
					args.withScale(0.75F + rand.nextFloat() * 0.75F);
				BLParticles.EMBER_SWIRL.spawn(getEntityWorld(), posX, posY, posZ, args);
			}
		}
    }

public static void tick(Level level, BlockPos pos, BlockState state, CarminiteBuilderBlockEntity te) {
		if (!level.isClientSide() && te.makingBlocks) {
			// if we are not tracking the nearest player, start tracking them
			if (te.trackedPlayer == null) {
				te.trackedPlayer = te.findClosestValidPlayer();
			}

			// find player facing
			Direction nextFacing = te.findNextFacing();

			++te.ticksRunning;

			// if we are at the half second marker, make a block and advance the block cursor
			if (te.ticksRunning % 10 == 0 && te.lastBlockCoords != null && nextFacing != null) {
				BlockPos nextPos = te.lastBlockCoords.relative(nextFacing);

				// make a block
				if (te.blocksMade <= RANGE && level.isEmptyBlock(nextPos)) {
					level.setBlock(nextPos, te.blockBuiltState, Block.UPDATE_ALL);

					level.playSound(null, pos, TFSounds.BUILDER_CREATE.get(), SoundSource.BLOCKS, 0.75F, 1.2F);

					te.lastBlockCoords = nextPos;

					te.blockedCounter = 0;
					te.blocksMade++;
				} else {
					te.blockedCounter++;
				}
			}

			// if we're blocked for more than a second, shut down block making
			if (te.blockedCounter > 0) {
				te.makingBlocks = false;
				te.trackedPlayer = null;
				te.ticksStopped = 0;
			}
		} else if (!level.isClientSide() && !te.makingBlocks) {
			te.trackedPlayer = null;
			if (++te.ticksStopped == 60) {
				// force the builder back into an inactive state
				level.setBlockAndUpdate(pos, state.setValue(BuilderBlock.STATE, TowerDeviceVariant.BUILDER_TIMEOUT));
				level.scheduleTick(pos, state.getBlock(), 4);
			}
		}
	}

@Override
    public void tick() {
        if (level.isClientSide || disabled) {
            return;
        }
        if (level.getGameTime() % 20 != 0)
            return;

        if (fromPos != null && level.isLoaded(fromPos)) {
            // Block has been removed
            if (!(level.getBlockEntity(fromPos) instanceof AbstractSourceMachine) && level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, fromPos, null) == null) {
                fromPos = null;
                updateBlock();
                return;
            } else if (level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, fromPos, null) instanceof ISourceCap sourceHandler) {
                // Transfer mana fromPos to this
                if (transferSource(sourceHandler, getSourceStorage()) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, fromPos, worldPosition, this.getColor());
                }
            } else if (level.getBlockEntity(fromPos) instanceof AbstractSourceMachine fromTile) {
                // Transfer mana fromPos to this
                if (transferSource(fromTile, this) > 0) {
                    updateBlock();
                    ParticleUtil.spawnFollowProjectile(level, fromPos, worldPosition, this.getColor());
                }
            }
        }

        if (toPos != null && level.isLoaded(toPos)) {
            if (!(level.getBlockEntity(toPos) instanceof AbstractSourceMachine) && level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, toPos, null) == null) {
                toPos = null;
                updateBlock();
                return;
            }
            if (level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, toPos, null) instanceof ISourceCap sourceHandler) {
                // Transfer mana from this to toPos
                if (transferSource(this.getSourceStorage(), sourceHandler) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, worldPosition, toPos, this.getColor());
                }
            } else if (level.getBlockEntity(toPos) instanceof AbstractSourceMachine toTile) {
                // Transfer mana from this to toPos
                if (transferSource(this, toTile) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, worldPosition, toPos, this.getColor());
                }
            }
        }
    }

@SubscribeEvent(priority = EventPriority.HIGHEST)
	public void playerTick(TickEvent.PlayerTickEvent event) {
		//Leaving the underowrld
		if (event.player.getEntityWorld().provider.getDimension() == Wizardry.underWorld.getId()) {
			if (event.player.posY < 0) {
				//Gets the players spwanpoint and sets the location to teleport to around that
				event.player.isDead = false;
				BlockPos spawn = event.player.isSpawnForced(0) ? event.player.getBedLocation(0) : event.player.world.getSpawnPoint().add(event.player.world.rand.nextGaussian() * 16, 0, event.player.world.rand.nextGaussian() * 16);
				BlockPos teleportTo = spawn.add(0, 300 - spawn.getY(), 0);
				//stops fall damage
				fallResetter.add(event.player.getUniqueID());
				TeleportUtil.teleportToDimension(event.player, 0, teleportTo.getX(), teleportTo.getY(), teleportTo.getZ());
			}
		}
		//adds pass to check if player on bedrock after reached velocity
		if (event.player.getEntityWorld().provider.getDimension() == 0 && ConfigValues.underworldFallSpeed <= 0) {
			if (event.player.motionY < ConfigValues.underworldFallSpeed || passmap.get(event.player.getEntityId()) != null) {
				passmap.put(event.player.getEntityId(), true);
				BlockPos location = event.player.getPosition();
				BlockPos bedrock = PosUtils.checkNeighborBlocksThoroughly(event.player.getEntityWorld(), location, Blocks.BEDROCK);
				if (bedrock != null) {
					event.player.isDead = false;
					fallResetter.add(event.player.getUniqueID());
					TeleportUtil.teleportToDimension(event.player, Wizardry.underWorld.getId(), 0, 300, 0);
					passmap.remove(event.player.getEntityId());
				} else if (event.player.motionY > ConfigValues.underworldFallSpeed) {//resets pass if stopped falling or slowed down alot
					passmap.remove(event.player.getEntityId());
				}
			}
		}

		if (!event.player.world.isRemote) {
			for (ItemStack stack : event.player.inventory.mainInventory) {
				if (stack.getItem() == ModItems.LEVITATION_ORB) {

					if (stack.getItemDamage() + 1 > stack.getMaxDamage()) {
						stack.shrink(1);
						continue;
					}

					if (event.player.world.getTotalWorldTime() % 10 == 0)
						stack.setItemDamage(stack.getItemDamage() + 1);

					if (!event.player.isPotionActive(ModPotions.LOW_GRAVITY)) {
						event.player.addPotionEffect(new PotionEffect(ModPotions.LOW_GRAVITY, 3, 3, false, false));
					}
					break;
				}
			}
		}
	}

public void use(int hammerLevel, float hammerEfficiency, float angle) {
        ServerLevel serverLevel = (ServerLevel) getLevel();
        int count = 4 + (int) hammerEfficiency / 4;
        double cone = (20 + hammerLevel * 6) * Math.PI / 180;
        int ox = SectionPos.blockToSectionCoord(getBlockPos().getX());
        int oz = SectionPos.blockToSectionCoord(getBlockPos().getZ());

        int preResultSize = scanResults.size();
        AtomicInteger stagger = new AtomicInteger();

        ChunkPos.rangeClosed(new ChunkPos(-32, -32), new ChunkPos(32, 32))
                .filter(pos -> Math.abs(Mth.atan2(pos.x, pos.z) - angle) < cone)
                .sorted(Comparator.comparingInt(pos -> pos.x * pos.x + pos.z * pos.z))
                .map(pos -> new ChunkPos(pos.x + ox, pos.z + oz))
                .filter(pos -> Math.abs(pos.x - ox) + Math.abs(pos.z - oz) < 20)
                .filter(pos -> scanResults.stream().noneMatch(result -> result.chunkX == pos.x && result.chunkZ == pos.z))
                .limit(count)
                .forEach(pos -> {
//                    boolean wasLoaded = serverLevel.hasChunk(pos.x, pos.z);
//                    System.out.println("has chunk [" + pos.x + ", " + pos.z + "]: " + wasLoaded);
//                    serverLevel.getChunkSource().getGenerator().findNearestMapStructure()
                    long timestamp = this.getTimestamp(serverLevel.getGameTime(), pos.x - ox, pos.z - oz) + stagger.getAndIncrement() * 3L;
                    int height = serverLevel.getChunk(pos.x, pos.z, ChunkStatus.SURFACE).getHeight(Heightmap.Types.WORLD_SURFACE_WG, pos.x, pos.z);

                    BlockPos centerPos = pos.getMiddleBlockPosition(height);
                    float temperature = level.getBiome(centerPos).value().getTemperature(centerPos);
                    List<String> structures =
                            Arrays.stream(getScannableStructures())
                                    .filter(id -> ScanHelper.hasStructure(id, serverLevel, pos)).toList();
                    scanResults.add(new ScanResult(pos.x, pos.z, height, temperature, structures, timestamp));


//                    if (!wasLoaded) {
//                        System.out.println("[post]  Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z));
//                        ServerScheduler.schedule(100, () -> System.out.println("[delayed] Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z)));
//                    }


                    ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime())), () ->
                            serverLevel.playSound(null, getBlockPos(), TetraSounds.scanMiss, SoundSource.PLAYERS, 0.01f, 1.0f + (float) Math.random() * 0f));
                    if (!structures.isEmpty()) {
                        ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime()) + 20), () ->
                                serverLevel.playSound(null, getBlockPos(), TetraSounds.scanHit, SoundSource.PLAYERS, 0.1f, 1.0f));
                    }

                });

        if (preResultSize != scanResults.size()) {
            setChanged();
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
		if (!(entityLiving instanceof Player))
			return stack;

		Player player = (Player) entityLiving;

		if (player instanceof ServerPlayer) {
			CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) player, stack);
		}

		Player receiver = this.getBoundPlayer(worldIn, stack);

		if (!worldIn.isClientSide && receiver != null) {

			Vec3 vec = receiver.position();

			while (vec.distanceTo(receiver.position()) < 1.0D) {
				vec = receiver.position().add((random.nextDouble() - 0.5D) * 4D, 0, (random.nextDouble() - 0.5D) * 4D);
			}

			worldIn.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 100, 1.25F, false));

			player.teleportTo(vec.x, vec.y + 0.25, vec.z);
			worldIn.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
		}

		if (!player.getAbilities().instabuild) {

			stack.shrink(1);

			if (stack.isEmpty())
				return new ItemStack(Items.GLASS_BOTTLE);

			player.getInventory().add(new ItemStack(Items.GLASS_BOTTLE));

		}

		return stack;
	}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
        float potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            if (this.rightStaff(staff)) {
                damage *= 2.0F;
                if (SpellConfig.DragonFrostGriefing.get()) {
                    float flameRange = range * ((float) Math.PI / 180.0F);
                    for (int i = 0; i < 3; i++) {
                        Vec3 cast = caster.getLookAngle().normalize().xRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange).yRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange);
                        HitResult hitResult = worldIn.clip(new ClipContext(caster.getEyePosition(), caster.getEyePosition().add(cast.scale(10)), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, caster));
                        if (hitResult.getType() == HitResult.Type.BLOCK) {
                            Vec3 pos = hitResult.getLocation().subtract(cast.scale(0.5D));
                            BlockPos blockPos = BlockPos.containing(pos.x, pos.y, pos.z);
                            if ((worldIn.getBlockState(blockPos).isAir() ||
                                    (BlockFinder.canBeReplaced(worldIn, blockPos)
                                            && worldIn.getFluidState(blockPos).isEmpty()))
                                    && worldIn.getBlockState(blockPos.below()).isSolidRender(worldIn, blockPos.below())) {
                                worldIn.setBlockAndUpdate(blockPos, Blocks.SNOW.defaultBlockState());
                            }
                            BlockState blockstate = Blocks.FROSTED_ICE.defaultBlockState();
                            if (worldIn.getBlockState(blockPos) == FrostedIceBlock.meltsInto() && blockstate.canSurvive(worldIn, blockPos) && worldIn.isUnobstructed(blockstate, blockPos, CollisionContext.empty()) && !net.minecraftforge.event.ForgeEventFactory.onBlockPlace(caster, net.minecraftforge.common.util.BlockSnapshot.create(worldIn.dimension(), worldIn, blockPos), net.minecraft.core.Direction.UP)) {
                                worldIn.setBlockAndUpdate(blockPos, blockstate);
                                worldIn.scheduleTick(blockPos, Blocks.FROSTED_ICE, Mth.nextInt(caster.getRandom(), 60, 120));
                            }
                        }
                    }
                }
            }
            for (Entity target : getBreathTarget(caster, range)) {
                LivingEntity livingEntity = MobUtil.getLivingTarget(target);
                if (livingEntity != null) {
                    if (livingEntity.hurt(ModDamageSource.frostBreath(caster, caster), damage)) {
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(1) * duration));
                    }
                }
            }
        }
        worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.FROST_BREATH.get(), this.getSoundSource(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

@Override
    public @NonNull InteractionResult use(Level level, Player player, @NonNull InteractionHand hand) {
        final ItemStack stack = player.getItemInHand(hand);

        if (!level.isClientSide() && player instanceof ServerPlayer serverPlayer) {
            if (player.isShiftKeyDown()) {
                //here we use main hand item as selected slot
                int selectedSlot = hand == InteractionHand.MAIN_HAND ? player.getInventory().getSelectedSlot() : -1;

                serverPlayer.openMenu(
                        new SimpleMenuProvider((id, playerInventory, unused) -> {
                            return new TeleportTabletContainer(id, playerInventory,
                                    this.getInventory(serverPlayer, stack), selectedSlot);
                        }, stack.getDisplayName()), buffer -> {
                            buffer.writeVarInt(selectedSlot);
                        });
            } else { //Teleport logic
                if (stack.has(DataComponents.CONTAINER)) {
                    ItemContainerContents contents = stack.getOrDefault(DataComponents.CONTAINER, ItemContainerContents.EMPTY);
                    if (contents  == ItemContainerContents.EMPTY)
                        return InteractionResult.FAIL;

                    ItemStack compass = contents.getStackInSlot(0);
                    TeleportTransition transition = this.getDestination((ServerLevel) level, player, compass);
                    if (transition == null)
                        return InteractionResult.FAIL;

                    if (compass.getOrDefault(DataComponents.CUSTOM_NAME, "") != "BACK") {
                        boolean checking = true;
                        NonNullList<ItemStack> items = NonNullList.create();
                        for (int i = 0 ; i < contents.getSlots() ; i++) {
                            ItemStack back = contents.getStackInSlot(i);
                            if (checking && back.getOrDefault(DataComponents.CUSTOM_NAME, Component.empty()).getString().equals("BACK")) {
                                LodestoneTracker target = new LodestoneTracker(Optional.of(GlobalPos.of(level.dimension(), player.blockPosition())), true);
                                back.set(DataComponents.LODESTONE_TRACKER, target);
                                checking = false;
                            }
                            items.add(back);
                        }
                        if (!checking)
                            Networking.sendToServer(new MessageSetContents(ItemContainerContents.fromItems(items), hand));
                    }

                    player.teleport(transition);
                    player.getCooldowns().addCooldown(stack, 20 * Occultism.SERVER_CONFIG.itemSettings.wormholeTabletCooldown.getAsInt());
                    level.broadcastEntityEvent(player, (byte) 46);
                    return InteractionResult.SUCCESS;
                }
            }
        }

        return InteractionResult.SUCCESS;
    }

@Override
    public @NotNull InteractionResultHolder<ItemStack> use(@NotNull Level world, Player player, @NotNull InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        WarpScrollData data = stack.get(DataComponentRegistry.WARP_SCROLL);
        if (hand == InteractionHand.OFF_HAND)
            return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);

        if (!(world instanceof ServerLevel serverLevel))
            return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);

        if (data.isValid()) {
            if (!data.canTeleportWithDim(player.getCommandSenderWorld().dimension().location().toString())) {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.wrong_dim"));
                return InteractionResultHolder.fail(stack);
            }
            BlockPos pos = data.pos().get();
            Vec2 rotation = data.rotation();
            Vec3 vec3 = player.position;
            Networking.sendToNearbyClient(world, player, new PacketWarpPosition(player.getId(), pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, rotation.x, rotation.y));
            player.teleportTo(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5);
            player.level().gameEvent(GameEvent.TELEPORT, vec3, GameEvent.Context.of(player));
            player.setXRot(rotation.x);
            player.setYRot(rotation.y);

            serverLevel.sendParticles(ParticleTypes.PORTAL, pos.getX(), pos.getY() + 1.0, pos.getZ(),
                    10, (world.random.nextDouble() - 0.5D) * 2.0D, -world.random.nextDouble(), (world.random.nextDouble() - 0.5D) * 2.0D, 0.1f);
            world.playSound(null, pos, SoundEvents.ILLUSIONER_CAST_SPELL, SoundSource.NEUTRAL, 1.0f, 1.0f);
            if (!player.hasInfiniteMaterials()) {
                stack.shrink(1);
            }
            return InteractionResultHolder.pass(stack);
        }
        if (player.isShiftKeyDown()) {
            ItemStack newWarpStack = new ItemStack(ItemsRegistry.WARP_SCROLL.get());
            newWarpStack.set(DataComponentRegistry.WARP_SCROLL, new WarpScrollData(Optional.of(player.blockPosition()), player.getCommandSenderWorld().dimension().location().toString(), player.getRotationVector(), false));
            boolean didAdd;
            if (stack.getCount() == 1) {
                stack = newWarpStack;
                didAdd = true;
            } else {
                didAdd = player.addItem(newWarpStack);
                if (didAdd && !player.hasInfiniteMaterials()) {
                    stack.shrink(1);
                }
            }
            if (!didAdd) {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.inv_full"));
                return InteractionResultHolder.fail(stack);
            } else {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.recorded"));
            }
        }
        return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
    }

@Override
    protected void tick() {
        Level world = getWorld();
        int radius = 3;
        if (world.isClientSide) {
            BlockPos pos = getPos();
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), radius);
        }
        if (!getWorld().isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            Level level = getWorld();
            BlockPos pos = getPos();
            //Get nearby source jars
            for (BlockPos blockPos : BlockPos.betweenClosed(pos.offset(-radius, -radius, -radius), pos.offset(radius, radius, radius))) {
                if (level.getBlockState(blockPos).getBlock() instanceof MobJar) {
                    MobJarTile tile = (MobJarTile) level.getBlockEntity(blockPos);
                    if (tile == null || tile.getEntity() != null) {
                        continue;
                    }
                    for (Entity e : level.getEntities((Entity) null, new AABB(tile.getBlockPos()).inflate(5), this::canJar)) {
                        for (var passenger : e.getPassengers()) {
                            passenger.stopRiding();
                        }
                        if (e instanceof Mob mob && ((Mob) e).isLeashed() && e.shouldBeSaved()) {
                            if (mob.isLeashed()) {
                                mob.dropLeash(true, true);
                            }
                        }
                        if (e instanceof Raider raider && raider.hasActiveRaid()) {
                            raider.getCurrentRaid().removeFromRaid(raider, false);
                        }
                        if (e instanceof Villager villager) {
                            villager.releasePoi(MemoryModuleType.HOME);
                            villager.releasePoi(MemoryModuleType.JOB_SITE);
                            villager.releasePoi(MemoryModuleType.POTENTIAL_JOB_SITE);
                            villager.releasePoi(MemoryModuleType.MEETING_POINT);
                        }
                        if (tile.setEntityData(e)) {
                            e.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);
                            EntityFlyingItem followProjectile = new EntityFlyingItem(level, e.position, Vec3.atCenterOf(tile.getBlockPos()), 100, 50, 100);
                            level.addFreshEntity(followProjectile);
                            ParticleUtil.spawnPoof((ServerLevel) level, e.getOnPos().above());
                            didWorkOnce = true;
                            if (e instanceof Starbuncle starbuncle) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.SHRUNK_STARBY.get(), (ServerLevel) level, starbuncle.blockPosition(), 10);
                            }
                            if (e instanceof LightningBolt bolt) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.CAUGHT_LIGHTNING.get(), (ServerLevel) level, bolt.blockPosition(), 10);
                            }
                            if (e instanceof ItemEntity item && item.getItem().getItem() == Items.CLOCK) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.TIME_IN_BOTTLE.get(), (ServerLevel) level, item.blockPosition(), 10);
                            }
                            break;
                        }
                    }
                }
            }
            if (didWorkOnce) {
                this.setNeedsSource(true);
            }
        }
    }

@Override
	public void tickServer()
	{
		if(level.getGameTime()%8!=0||!isActive())
			return;
		IItemHandler outputHandler = output.getCapability();
		if(outputHandler!=null)
		{
			boolean matched = true;
			if(this.batchMode==BatchMode.ALL)
			{
				for(int slot = 0; slot < NUM_SLOTS; slot++)
					if(!this.filters.get(slot).isEmpty())
						matched &= isFilterMatched(slot);
			}
			if(matched)
			{
				boolean anySent = false;
				for(int slot = 0; slot < NUM_SLOTS; slot++)
				{
					ItemStack filterStack = this.filters.get(slot);
					if(filterStack.isEmpty())
						continue;
					if(this.batchMode==BatchMode.ALL||isFilterMatched(slot))
					{
						ItemStack outStack = buffers.get(slot);
						int outSize = filterStack.getCount();
						ItemStack stack = outStack.copyWithCount(outSize);
						stack = ItemHandlerHelper.insertItem(outputHandler, stack, false);
						if(!stack.isEmpty())
							outSize -= stack.getCount();
						outStack.shrink(outSize);
						if(outStack.getCount() <= 0)
							this.buffers.set(slot, ItemStack.EMPTY);
						anySent = true;
					}
				}
				if(anySent)
					redstoneCap.markDirty();
			}
		}
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		State state = context.getState();
		IMultiblockLevel level = context.getLevel();
		final Level rawLevel = context.getLevel().getRawLevel();
		if(rawLevel instanceof ServerLevel serverLevel)
		{
			BlockPos broadcastPos = level.toAbsolute(BROADCAST_POS);
			// update the maximum range if it's undefined or every ~ 7 minutes
			if(state.rangeInChunks < 0||serverLevel.getGameTime()%8192==((broadcastPos.getX()^broadcastPos.getZ())&8191))
			{
				int maxRange = calculateMaxRange(serverLevel, broadcastPos, 4);
				state.rangeInChunks = maxRange;
			}

			// fetch the wireless handler for this world
			WirelessRedstoneHandler handler = WirelessRedstoneHandler.getHandler(serverLevel);

			// consume energy and set active state
			int consumed = IEServerConfig.MACHINES.radio_tower_consumption.get();
			int extracted = state.energy.extractEnergy(consumed, false);
			final boolean prevActive = state.active;
			state.active = extracted >= consumed;
			// if active state changed, notify the network
			if(state.active!=prevActive)
				state.markSendAndReceiveDirty();

			// register with handler if not yet done
			if(!handler.isRegistered(broadcastPos, context.getState()))
				handler.register(broadcastPos, context.getState());

			// if the sending signal has changed, notify other components
			if(state.sendingDirty)
			{
				handler.notifyComponents(broadcastPos, state);
				state.sendingDirty = false;
			}
			// if the network has changed, fetch new signal
			if(state.receivingDirty)
			{
				state.receivedSignals = state.isActive()?handler.fetchSignals(broadcastPos, state): new byte[16];
				state.bundleConnection.markDirty();
				state.receivingDirty = false;
			}
		}
	}

