@Override
    public void tick() {
        if (te.isRemoved() || !hacker.isAlive()) {
            // TODO maybe find a way to catch up with hackers who disconnect just to avoid getting zapped?
            return;
        }

        boolean wasDone = isSimulationDone();

        if (!(hacker.containerMenu instanceof SecurityStationHackingMenu) && !playerSimulation.isHackComplete()) {
            // hacker closed their window before hack complete: AI wins
            for (int slot = 0; slot < HackSimulation.GRID_SIZE; slot++) {
                HackSimulation.Node node = aiSimulation.getNodeAt(slot);
                if (node != null && node.getType() == NetworkComponentType.NETWORK_IO_PORT) {
                    node.setHackProgress(slot, 1F, true);
                    break;
                }
            }
        } else if (!wasDone) {
            playerSimulation.tick();
            aiSimulation.tick();
        }

        boolean syncToClient = (te.nonNullLevel().getGameTime() & 0x7) == 0;
        if (!wasDone && aiSimulation.isHackComplete()) {
            // security station wins
            syncToClient = true;
            if (aiSimulation.isAwake()) {
                // if hack window is closed before AI detects intrustion, hacker gets away with it
                if (te.nonNullLevel().isClientSide) {
                    hacker.playSound(SoundEvents.ENDERMAN_DEATH, 1f, 1f);
                } else {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.1").withStyle(ChatFormatting.RED), false);
                    if (!justTesting) {
                        hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.2").withStyle(ChatFormatting.RED), false);
                        te.retaliate(hacker);
                    }
                }
            }
        } else if (!wasDone && playerSimulation.isHackComplete()) {
            // hacker wins
            syncToClient = true;
            if (te.nonNullLevel().isClientSide) {
                hacker.playSound(SoundEvents.PLAYER_LEVELUP, 1f, 1f);
            } else {
                hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.1").withStyle(ChatFormatting.GREEN), false);
                if (!justTesting) {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.2").withStyle(ChatFormatting.GREEN), false);
                    te.addHacker(hacker.getGameProfile());
                }
            }
        }
        if (!te.nonNullLevel().isClientSide() && syncToClient) {
            NetworkHandler.sendToPlayer(PacketSyncHackSimulationUpdate.forSecurityStation(te), (ServerPlayer) hacker);
        }
    }

public boolean addProcessToQueue(
			MultiblockProcess<R, CTX> process, Level level, boolean simulate, boolean addToPrevious
	)
	{
		if(addToPrevious&&process instanceof MultiblockProcessInWorld)
		{
			// Pattern variables look fine in IntelliJ, but cause the "real" compiler to complain. Probably related to
			// the CTX type parameter
			@SuppressWarnings("PatternVariableCanBeUsed") final MultiblockProcessInWorld<R> newProcess = (MultiblockProcessInWorld<R>)process;
			for(MultiblockProcess<R, CTX> curr : processQueue)
				if(curr instanceof MultiblockProcessInWorld&&process.getRecipeId().equals(curr.getRecipeId()))
				{
					boolean canStack = true;
					final MultiblockProcessInWorld<R> existingProcess = (MultiblockProcessInWorld<R>)curr;
					for(ItemStack old : existingProcess.inputItems)
					{
						for(ItemStack in : newProcess.inputItems)
							if(ItemStack.isSameItemSameComponents(old, in))
								if(old.getCount()+in.getCount() > old.getMaxStackSize())
								{
									canStack = false;
									break;
								}
						if(!canStack)
							break;
					}
					if(canStack)
					{
						if(!simulate)
							for(ItemStack old : existingProcess.inputItems)
							{
								for(ItemStack in : newProcess.inputItems)
									if(ItemStack.isSameItemSameComponents(old, in))
									{
										old.grow(in.getCount());
										break;
									}
							}
						return true;
					}
				}
		}
		if(maxQueueLength < 0||processQueue.size() < maxQueueLength)
		{
			if(!processQueue.isEmpty())
			{
				MultiblockProcess<R, CTX> previousProcess = processQueue.get(processQueue.size()-1);
				final int maxTime = previousProcess.getMaxTicks(level);
				float dist = previousProcess.processTick/(float)maxTime;
				if(dist < minDelayAfter.applyAsDouble(maxTime))
					return false;
			}

			if(!simulate)
				processQueue.add(process);
			markDirty.run();
			onQueueChange.run();
			return true;
		}
		return false;
	}

public PriorityQueue<LogisticsTask> getTasks(Object holdingStack, boolean droneAccess) {
        this.droneAccess = droneAccess;

        ItemStack item = holdingStack instanceof ItemStack is ? is : ItemStack.EMPTY;
        FluidStack fluid = holdingStack instanceof FluidStack fs ? fs : FluidStack.EMPTY;

        PriorityQueue<LogisticsTask> tasks = new PriorityQueue<>();
        for (int priority = logistics.size() - 1; priority >= 0; priority--) {
            for (int requesterId = 0; requesterId < logistics.get(priority).size(); requesterId++) {
                AbstractLogisticsFrameEntity requester = logistics.get(priority).get(requesterId);
                if (droneAccess && requester.isObstructed(PathComputationType.AIR)) {
                    continue;
                }
                for (int i = 0; i < priority; i++) {
                    for (int providerId = 0; providerId < logistics.get(i).size(); providerId++) {
                        AbstractLogisticsFrameEntity provider = logistics.get(i).get(providerId);
                        if (droneAccess && provider.isObstructed(PathComputationType.AIR)) {
                            continue;
                        }
                        if (provider.shouldProvideTo(priority)) {
                            if (!item.isEmpty()) {
                                int requestedAmount = getRequestedAmount(requester, item, false);
                                if (requestedAmount > 0) {
                                    tasks.add(new LogisticsTask(provider, requester, item.copyWithCount(requestedAmount)));
                                    return tasks;
                                }
                            } else if (!fluid.isEmpty()) {
                                int requestedAmount = getRequestedAmount(requester, fluid, false);
                                if (requestedAmount > 0) {
                                    tasks.add(new LogisticsTask(provider, requester, fluid.copyWithAmount(requestedAmount)));
                                    return tasks;
                                }
                            }
                            // it could be that the drone is carrying some item or fluid it can't drop off right now
                            // however it might still be able to transfer the other resource type (i.e. transfer items if
                            // it's holding a fluid, and vice versa)
                            if (provider.getCachedTileEntity() != null) {
                                if (item.isEmpty()) {
                                    tryProvideItems(provider, requester, tasks);
                                }
                                if (fluid.isEmpty()) {
                                    tryProvideFluids(provider, requester, tasks);
                                }
                            }

                            // if we provided something to the requester, move the requester and provider to last in their
                            // lists so another frame gets selected first, effectively round-robin.
                            if (!tasks.isEmpty()) {
                                if (logistics.get(priority).size() > 1)
                                    logistics.get(priority).add(logistics.get(priority).remove(requesterId));
                                if (logistics.get(i).size() > 1)
                                    logistics.get(i).add(logistics.get(i).remove(providerId));
                                return tasks;
                            }
                        }
                    }
                }
            }
        }

        return tasks;
    }

@Override
	public void update() {
		super.update();

		if (getBlockType() == ModBlocks.MANA_BATTERY && !((BlockManaBattery) getBlockType()).testStructure(getWorld(), getPos()).isEmpty())
			return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (getBlockType() != ModBlocks.CREATIVE_MANA_BATTERY) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canSuckFromOutside() || !((TileOrbHolder) tile).canGiveToOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanSuckFromOutside(false);
						((TileOrbHolder) tile).setCanGiveToOutside(true);
						tile.markDirty();
					}
				}
			}


			if (world.getTotalWorldTime() % 20 == 0 && !ManaManager.forObject(getWizardryCap()).isManaFull()) {
				ManaManager.forObject(getWizardryCap())
						.addMana(5)
						.removeBurnout(5)
						.close();

				if (world.isRemote)
					ClientRunnable.run(new ClientRunnable() {
						@Override
						@SideOnly(Side.CLIENT)
						public void runIfClient() {
							Vec3d from = new Vec3d(getPos()).add(0.5, 1, 0.5);
							Vec3d to = from.add(RandUtil.nextDouble(-1, 1), -3, RandUtil.nextDouble(-1, 1));

							ParticleBuilder helix = new ParticleBuilder(200);
							helix.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
							helix.setAlphaFunction(new InterpFloatInOut(0.1f, 0.1f));
							ParticleSpawner.spawn(helix, world, new StaticInterp<>(to), 5, 0, (someFloat, particleBuilder) -> {
								particleBuilder.setColor(ColorUtils.changeColorAlpha(new Color(0x0097FF), RandUtil.nextInt(50, 200)));
								particleBuilder.setScale(RandUtil.nextFloat(0.3f, 0.8f));
								particleBuilder.setPositionFunction(new InterpBezier3D(Vec3d.ZERO,
										from.subtract(to),
										new Vec3d(0, 5, 0), new Vec3d(0, 1, 0)));
								particleBuilder.setLifetime(RandUtil.nextInt(50, 60));
							});
						}
					});
			}

		} else {
			ManaManager.forObject(getWizardryCap())
					.setMana(ManaManager.getMaxMana(getWizardryCap()))
					.setBurnout(0)
					.close();
		}
	}

public void tick() {
        if (this.level != null) {
            boolean flag = this.level.getBiome(this.getBlockPos()).is(Biomes.DEEP_DARK);
            if (flag) {
                this.findCandlesticks();
                if (!this.level.isClientSide) {
                    if (this.level.random.nextFloat() < 0.3F) {
                        if (this.level.random.nextFloat() < 0.17F) {
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FURNACE_FIRE_CRACKLE, 0.5F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                        }
                    }
                }
                if (!this.candlestickBlockEntityList.isEmpty()){
                    BrazierRecipe recipe = this.getRecipe();
                    double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                    double d1 = (double)this.worldPosition.getY() + 0.5D + this.level.random.nextDouble();
                    double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                    if (!this.level.isClientSide) {
                        ServerLevel serverWorld = (ServerLevel) this.level;
                        this.makeParticles();
                        if (this.activate(this.level)) {
                            if (recipe != null) {
                                for (int p = 0; p < 2; ++p) {
                                    serverWorld.sendParticles(ModParticleTypes.SMALL_NECRO_FIRE.get(), d0, this.worldPosition.getY() + 0.5F, d2, 1, 0, 0, 0, 0);
                                    serverWorld.sendParticles(ParticleTypes.SMOKE, d0, d1, d2, 0, 0.0D, 5.0E-4D, 0.0D, 0.5F);
                                    serverWorld.sendParticles(ModParticleTypes.NECRO_EFFECT.get(), d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                                }
                                for (BlockEntity blockEntity : this.candlestickBlockEntityList){
                                    if (blockEntity instanceof ISoulCandle soulCandle) {
                                        if (soulCandle.getSouls() > 0) {
                                            soulCandle.drainSouls(this.getBlockPos());
                                            this.currentTime += soulCandle.soulDrainAmount();
                                        }
                                    }
                                }
                                if (!this.playSound) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.BLAZE_AMBIENT, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    this.playSound = true;
                                }
                                if (this.level.getGameTime() % 20 == 0) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FIRE_AMBIENT, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double) this.worldPosition.getX() + 0.5D, (double) this.worldPosition.getY() + 1.15D, (double) this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                }

                                if (this.currentTime >= recipe.getSoulCost()) {
                                    this.stopBrazier(true);
                                } else {
                                    this.updateRecipe(this.level);
                                }
                            }
                        }
                    }
                } else {
                    if (!this.level.isClientSide) {
                        this.stopBrazier(false);
                    }
                }
            } else {
                if (!this.level.isClientSide) {
                    this.stopBrazier(false);
                }
            }
            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(NecroBrazierBlock.LIT, flag), 3);
        }
    }

@Override
    public void tickCommonPre() {
        oldExtension = extension;

        super.tickCommonPre();

        if (!nonNullLevel().isClientSide) {
            runScheduledStructureRefresh();
        }

        if (!isCoreElevator()) {
            extension = 0f;
            return;
        }

        if (!nonNullLevel().isClientSide) {
            if (isControlledByRedstone()) {
                handleRedstoneControl();
            }
            syncedSpeedMult = getSpeedMultiplierFromUpgrades();
            chargingUpgrades = getUpgrades(ModUpgrades.CHARGING.get());  // sync'd to client to adjust elevator speed as appropriate
            MiscEventHandler.needsTPSSync(getLevel());
        } else {
            if (prevCamoState != camoState) {
                fakeFloorTextureUV = ClientUtils.getTextureUV(camoState, Direction.UP);
                fakeFloorTextureTint = camoState != null && camoState.getBlock() instanceof ColorHandlers.ITintableBlock t ?
                        0xFF000000 | t.getTintColor(camoState, level, getBlockPos(), 0) :
                        0xFFFFFFFF;
                prevCamoState = camoState;
            }
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                // kludge to prevent elevator TER rendering unlit sometimes
                lightAbove = ClientUtils.getLightAt(worldPosition.above());
            }
        }

        double speedMultiplier = getEffectiveSpeedMultiplier();
        if (extension < targetExtension && !nonNullLevel().isClientSide && getPressure() < PneumaticValues.MIN_PRESSURE_ELEVATOR) {
            setTargetExtensionForConnectedElevators(extension);
            queueStateSyncForConnectedElevators();
        }

        double elevatorDelta = calculateElevatorDelta(extension, targetExtension, speedMultiplier);
        if (elevatorDelta != 0) {
            extension += elevatorDelta;

            if (elevatorDelta > 0) {
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            } else if (!nonNullLevel().isClientSide && chargingUpgrades > 0 && getPressure() < airHandler.getDangerPressure() - 0.1f) {
                float mul = 0.15f * Math.min(4, chargingUpgrades);
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * mul * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            }
        }

        moveEntitiesOnPlatform(extension - oldExtension);

        if (PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && !isStopped) {
            // just arrived
            isStopped = true;
            ticksRunning = 0;
            playStopStartSound();
            if (!nonNullLevel().isClientSide) updateFloors(false);
        } else if (!PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && isStopped) {
            // just departed
            isStopped = false;
            playStopStartSound();
        }
        if (!isStopped) ticksRunning++;
    }

public void conquer() {

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!world.isRemote) {

			WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

			// Remove containment effects from nearby targets when shrine is conquered
			removeContainmentFromNearbyTargets();

			// If regeneration is enabled, schedule regeneration instead of removing the tile entity
			if (Wizardry.settings.shrineRegenerationEnabled) {
				this.conquered = true;
				this.regenerationTime = world.getTotalWorldTime() + (Wizardry.settings.shrineRegenerationTime * 1200L); // Convert minutes to ticks (20 ticks per second * 60 seconds)
				this.activated = false;
				Arrays.fill(this.linkedWizards, null); // Clear wizard references
				// Keep lootedPlayers list - it's permanent tracking for this shrine instance

				// Handle chest breaking and loot dropping
				handleChestLootDrop();

				// Mark the tile entity for update
				this.markDirty();

				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					// Keep the block state the same, just mark as conquered
					this.shrineElement = world.getBlockState(pos).getValue(BlockPedestal.ELEMENT);
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
			} else {
				// Original behavior: remove the tile entity
				BlockPos chestPos = this.pos.up();
				TileEntity chestTileEntity = world.getTileEntity(chestPos);
				if (chestTileEntity instanceof TileEntityChest) {
					TileEntityChest chest = (TileEntityChest) chestTileEntity;
					NBTExtras.removeUniqueId(chest.getTileData(), ArcaneLock.NBT_KEY);
					chest.markDirty();
					world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
				}
				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					world.setBlockState(pos, WizardryBlocks.runestone_pedestal.getDefaultState().withProperty(BlockPedestal.ELEMENT, world.getBlockState(pos).getValue(BlockPedestal.ELEMENT)));
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
				world.markTileEntityForRemoval(this);
			}
		}

		if (linkedContainer == null) {
			linkedContainer = world.getTileEntity(pos.up());
		}

		if (linkedContainer != null) {
			NBTExtras.removeUniqueId(linkedContainer.getTileData(), ArcaneLock.NBT_KEY);
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerMost");
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerLeast");
		}
		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_CONQUER, SoundCategory.BLOCKS, 1, 1, false);

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).scale(5).pos(x, y + 1, z).clr(0xf06495).time(12).spawn(world);
			for (int i = 0; i < 5; i++) {
				float brightness = 0.8f + world.rand.nextFloat() * 0.2f;
				ParticleBuilder.create(Type.SPARKLE, world.rand, x, y + 1, z, 1, true).clr(1, brightness, brightness).spawn(world);
			}
		}
	}

