@Override
        public void tick() {
            this.charger.getLookControl().setLookAt(this.chargePos.x(), this.chargePos.y() - 1, this.chargePos.z(), 10.0F, this.charger.getMaxHeadXRot());

            --this.windup;
            if (this.windup == 0){
                PathNavigation pathnavigation = this.charger.getNavigation();
                Path path = pathnavigation.createPath(BlockPos.containing(this.chargePos), 0);
                if (path != null && path.canReach()){
                    pathnavigation.moveTo(path, this.speed);
                } else {
                    pathnavigation.moveTo(this.chargePos.x(), this.chargePos.y(), this.chargePos.z(), this.speed);
                }
            }
            if (this.windup <= 0) {
                List<LivingEntity> list = this.charger.level.getNearbyEntities(LivingEntity.class, RAM_TARGET_CONDITIONS, this.charger, this.charger.getBoundingBox());
                list.removeIf(livingEntity -> MobUtil.areAllies(this.charger, livingEntity));
                if (!list.isEmpty()) {
                    LivingEntity livingentity = list.get(0);
                    DamageSource damageSource = this.charger instanceof IOwned owned && owned.getTrueOwner() != null ? ModDamageSource.summonAttack(this.charger, owned.getTrueOwner()) : this.charger.damageSources().mobAttack(this.charger);
                    livingentity.hurt(damageSource, (float)this.charger.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    int i = this.charger.hasEffect(MobEffects.MOVEMENT_SPEED) ? this.charger.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier() + 1 : 0;
                    int j = this.charger.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) ? this.charger.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier() + 1 : 0;
                    float f = 0.25F * (float)(i - j);
                    float f1 = Mth.clamp(this.charger.getSpeed() * 1.65F, 0.2F, 3.0F) + f;
                    float f2 = livingentity.isDamageSourceBlocked(damageSource) ? 0.5F : 1.0F;
                    if (this.ramDirection != null) {
                        livingentity.knockback((double) (f2 * f1) * this.getKnockbackForce.applyAsDouble(this.charger), this.ramDirection.x(), this.ramDirection.z());
                    }
                    this.stop();
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                } else if (this.hasRammedHornBreakingBlock()) {
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    boolean flag = this.charger instanceof TwilightGoat goat && goat.dropHorn();
                    if (flag) {
                        this.charger.level.playSound((Player)null, this.charger, this.getHornBreakSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    }

                    this.stop();
                } else {
                    boolean flag1 = this.chargePos == null || this.chargePos.closerThan(this.charger.position(), 0.25D);
                    if (flag1) {
                        this.stop();
                    }
                }
            } else {
                if (this.charger instanceof ICharger chargeMob) {
                    chargeMob.setCharging(true);
                }
            }
        }

@Override
    public void tick() {
        super.tick();
        LivingEntity target = this.getTarget();
        if(this.isAlive()) {
            if (this.getAnimation() == DEEPLING_BRUTE_TRIDENT_THROW) {
                if (target != null) {
                    if (this.getAnimationTick() == 11) {
                        if(this.isInWaterOrRain() && !this.isPassenger()) {
                            double f1 = target.getX() - this.getX();
                            double f2 = target.getY() - this.getY();
                            double f3 = target.getZ() - this.getZ();
                            double f4 = Mth.sqrt((float) (f1 * f1 + f2 * f2 + f3 * f3));
                            float f5 = 2.0F;
                            f1 *= f5 / f4;
                            f2 *= f5 / f4;
                            f3 *= f5 / f4;
                            this.push((double)f1, (double)f2, (double)f3);
                            this.startAutoSpinAttack(20);
                            if (this.onGround()) {
                                this.move(MoverType.SELF, new Vec3(0.0D, (double)1.1999999F, 0.0D));
                            }
                            this.playSound( SoundEvents.TRIDENT_RIPTIDE_3,1.0F, 1.0F);
                        }else{
                            ThrownCoral_Bardiche_Entity throwntrident = new ThrownCoral_Bardiche_Entity(this.level(), this, new ItemStack(ModItems.CORAL_BARDICHE.get()));
                            double p0 = target.getX() - this.getX();
                            double p1 = target.getY(0.3333333333333333D) - throwntrident.getY();
                            double p2 = target.getZ() - this.getZ();
                            double p3 = Math.sqrt(p0 * p0 + p2 * p2);
                            throwntrident.shoot(p0, p1 + p3 * (double) 0.2F, p2, 1.6F, (float) (14 - this.level().getDifficulty().getId() * 4));
                            this.playSound(SoundEvents.DROWNED_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                            this.level().addFreshEntity(throwntrident);
                        }
                    }
                }
            }
            if (this.getAnimation() == DEEPLING_BRUTE_MELEE) {
                if (this.getAnimationTick() == 5) {
                    this.playSound(ModSounds.DEEPLING_SWING.get(), 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                    if (target != null) {
                        if (this.distanceTo(target) < 3.0F) {
                            float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            target.hurt(damageSources().mobAttack(this), damage);
                        }
                    }
                }
            }
        }
        AABB aabb = this.getBoundingBox();
        if (this.SpinAttackTicks > 0) {
            --this.SpinAttackTicks;
            this.checkAutoSpinAttack(aabb, this.getBoundingBox());
        }

    }

@Override
	public void onUpdate() {
		if (!world.isRemote) {
			if (fleeingTick == 0 && getAttackTarget() != null && getDistance(getAttackTarget()) < 2) {
				onCollideWithEntity(getAttackTarget());
			}
			if (getRidingEntity() != null) {
				setRotation(getRidingEntity().rotationYaw, getRidingEntity().rotationPitch);
				if (getRidingEntity().isBurning() && getRidingEntity() instanceof EntityLivingBase) {
					PotionEffect stomachContents = new PotionEffect(MobEffects.POISON, 120 + getBloodConsumed() * 200 / MAX_BLOOD_LEVEL, 0);
					((EntityLivingBase) getRidingEntity()).addPotionEffect(stomachContents);
					setBloodConsumed(0);
					Entity mount = this.getRidingEntity();
					dismountEntity(mount);
					flee();
					dismountRidingEntity();
					this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
				}
			}
			if (getBloodConsumed() == MAX_BLOOD_LEVEL && getRidingEntity() != null) {
				Entity mount = this.getRidingEntity();
				dismountEntity(getRidingEntity());
				dismountRidingEntity();
				this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
			}
			if (fleeingTick > 0) {
				fleeingTick--;
				if (fleeingTick == 0) {
					stopFleeing();
				}
			}
		}

		if (!firstTickCheck) {
			dismountRidingEntity();
			firstTickCheck = true;
		}
		if (--hungerCoolDown == 0) {
			if (getBloodConsumed() > 0) {
				setBloodConsumed(getBloodConsumed() - 1);
			}
		}
		if (getRidingEntity() != null) {
			moveProgress = 1 + mathSucking.swing(1, 0.15F, false);
			if (rand.nextInt(10) == 0) {
				for (int i = 0; i < 8; i++) {
					world.spawnParticle(EnumParticleTypes.REDSTONE, posX + (rand.nextFloat() - rand.nextFloat()), posY + rand.nextFloat(), posZ + (rand.nextFloat() - rand.nextFloat()), 0, 0, 0);
				}
			}
		} else if (!world.isRemote) {
			moveProgress = 0F + mathSucking.swing(1, 0.15F, false);
		}

		if (getRidingEntity() != null && getRidingEntity() instanceof EntityLivingBase && getBloodConsumed() < MAX_BLOOD_LEVEL) {
			drainage++;
			if (drainage >= attackCountDown && this.deathTime == 0) {
				getRidingEntity().attackEntityFrom(DamageSource.causeMobDamage(this), (int)getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
				drainage = 0;
				setBloodConsumed(getBloodConsumed() + 1);
			}
		}
		super.onUpdate();
	}

