public static Pair<Boolean, Boolean> dealMixedDamage(LivingEntity target, DamageSource source1, float amount1, DamageSource source2, float amount2) {
        if (target.level().isClientSide()) return Pair.of(false, false);
        boolean flag1 = source1.getEntity() != null && target.isAlliedTo(source1.getEntity());
        boolean flag2 = source2.getEntity() != null && target.isAlliedTo(source2.getEntity());
        if(flag1 || flag2) return Pair.of(false, false);
        LivingData data = DataHandler.getData(target, DataHandler.LIVING_DATA);
        data.setLastDamage(-1);
        float damageSoFar = 0;
        float origLastDamage = target.lastHurt;
        boolean hit1 = target.hurt(source1, amount1);
        boolean hit1Registered = hit1;
        if (data.getLastDamage() != -1) {
            hit1Registered = true;
        }
        if (data.getLastDamage() != 0) {
            damageSoFar += amount1;
        }
        target.lastHurt = Math.max(target.lastHurt - amount1, 0);
        data.setLastDamage(-1);
        boolean hit2 = target.hurt(source2, amount2);
        if (data.getLastDamage() != 0) {
            damageSoFar += amount2;
        }
        target.lastHurt = origLastDamage;
        if (damageSoFar > target.lastHurt) target.lastHurt = damageSoFar;

        if (hit2 && hit1Registered) {
            onHit2(target, source2);
            if (target instanceof Player) {
                SoundEvent sound = SoundEvents.PLAYER_HURT;
                if (source2.is(DamageTypeTags.IS_FIRE)) sound = SoundEvents.PLAYER_HURT_ON_FIRE;
                else if (source2.is(DamageTypeTags.IS_DROWNING)) sound = SoundEvents.PLAYER_HURT_DROWN;
                target.playSound(sound, 1F, getSoundPitch(target));
            }
        }
        return Pair.of(hit1, hit2);
    }

public void tick() {
        super.tick();
        prevRunProgress = runProgress;
        prevShadeProgress = shadeProgress;
        Entity possessedEntity = getPossessedEntity();
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if (isShadeMode() && shadeProgress < 5F) {
            shadeProgress++;
        }
        if (!isShadeMode() && shadeProgress > 0F) {
            shadeProgress--;
        }
        if (isShadeMode()) {
            this.fallDistance = 0;
            if (this.isLandNavigator) {
                switchNavigator(false);
            }
        } else {
            if (!this.isLandNavigator) {
                switchNavigator(true);
            }
        }
        if (possessedEntity instanceof Player) {
            this.yHeadRot = Mth.approachDegrees(this.yHeadRotO, yHeadRot, 3);
        }
        if (!level().isClientSide) {
            if (possessedEntity != null && possessedEntity.isAlive()) {
                double dist = possessedEntity.distanceTo(this);
                if (this.entityData.get(POSSESSED_ENTITY_ID) != possessedEntity.getId()) {
                    this.entityData.set(POSSESSED_ENTITY_ID, possessedEntity.getId());
                    this.setPossessionStrength(1.0F);
                }
                lastPossessionTimestamp = this.tickCount;
                if (possessedTimeout++ > 140) {
                    this.setPossessionStrength(Math.max(0, this.getPossessionStrength(1.0F) + 0.1F));
                }
                if (dist < 1 || stopPossession(possessedEntity) || !this.isAlive()) {
                    if(possessedEntity instanceof WatcherPossessionAccessor possessionAccessor){
                        possessionAccessor.setPossessedByWatcher(false);
                    }
                    if(possessedEntity instanceof Player player){
                        setLastPossessedTimeFor(player);
                    }
                    this.level().broadcastEntityEvent(this, (byte) 78);
                    this.setPossessedEntityUUID(null);
                    this.entityData.set(POSSESSED_ENTITY_ID, -1);
                } else {
                    this.level().broadcastEntityEvent(this, (byte) 77);
                    if (possessedEntity instanceof LivingEntity living) {
                        living.zza = 0;
                        living.yya = 0;
                        living.xxa = 0;
                    }
                }
            } else {
                if(possessedEntity != null || this.entityData.get(POSSESSED_ENTITY_ID) != -1){
                    this.level().broadcastEntityEvent(this, (byte) 78);
                }
                possessedTimeout = 0;
                this.entityData.set(POSSESSED_ENTITY_ID, -1);
            }
        } else if (possessedEntity instanceof LivingEntity living) {
            living.zza = 0;
            living.yya = 0;
            living.xxa = 0;
            if (this.getPossessionStrength(1.0F) == 0) {
                isPossessionBreakable = true;
            }
            if (living instanceof Player player && isPossessionBreakable) {
                player.jumping = false;
                Player clientSidePlayer = AlexsCaves.PROXY.getClientSidePlayer();
                if (AlexsCaves.PROXY.isKeyDown(-1) && player == clientSidePlayer) {
                    AlexsCaves.sendMSGToServer(new PossessionKeyMessage(this.getId(), player.getId(), 0));
                }
            }
            if (prevPossessedEntity != living) {
                isPossessionBreakable = false;
            }
            prevPossessedEntity = living;
        } else {
            prevPossessedEntity = null;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        prevExplodeProgress = explodeProgress;
        prevScanProgress = scanProgress;
        if (this.isScanning() && scanProgress < 5F) {
            scanProgress++;
        }
        if (!this.isScanning() && scanProgress > 0F) {
            scanProgress--;
        }
        if (this.isExploding() && explodeProgress < 10F) {
            explodeProgress += 0.5F;
        }
        if (!this.isExploding() && explodeProgress > 0F) {
            explodeProgress -= 0.5F;
        }
        if (this.isExploding()) {
            if (explodeProgress >= 10.0F) {
                this.remove(RemovalReason.KILLED);
                Explosion.BlockInteraction blockinteraction = net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(level(), this) ? level().getGameRules().getBoolean(GameRules.RULE_MOB_EXPLOSION_DROP_DECAY) ? Explosion.BlockInteraction.DESTROY_WITH_DECAY : Explosion.BlockInteraction.DESTROY : Explosion.BlockInteraction.KEEP;
                MineExplosion explosion = new MineExplosion(level(), this, this.getX(), this.getY(0.5), this.getZ(), 5.0F, this.isInWaterOrBubble(), blockinteraction);
                explosion.explode();
                explosion.finalizeExplosion(true);
            }
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.3F, 1, 0.3F));
        }
        if (!level().isClientSide) {
            Entity entity = getAnchor();
            if (entity == null) {
                this.setMaxChainLength(7 + this.getRandom().nextInt(6));
                MineGuardianAnchorEntity created = new MineGuardianAnchorEntity(this);
                level().addFreshEntity(created);
                this.setAnchorUUID(created.getUUID());
                this.entityData.set(ANCHOR_ID, created.getId());
            } else {
                if (entity instanceof MineGuardianAnchorEntity anchorEntity) {
                    anchorEntity.linkWithGuardian(this);
                }
            }
            if (this.isInWaterOrBubble()) {
                this.setAirSupply(300);
            } else if (this.onGround()) {
                this.setDeltaMovement(this.getDeltaMovement().add((double) ((this.random.nextFloat() * 2.0F - 1.0F) * 0.6F), 0.6F, (double) ((this.random.nextFloat() * 2.0F - 1.0F) * 0.6F)));
                this.setYRot(this.random.nextFloat() * 360.0F);
                this.setOnGround(false);
                this.playSound(ACSoundRegistry.MINE_GUARDIAN_FLOP.get());
                this.hasImpulse = true;
            }
            Entity target = this.getTarget();
            if (target == null || !target.isAlive()) {
                timeSinceHadTarget++;
            } else {
                timeSinceHadTarget = 0;
            }
            if (this.isScanning()) {
                this.setEyeClosed(false);
                if (scanTime < maxScanTime) {
                    if(scanTime % 20 == 0){
                        this.playSound(ACSoundRegistry.MINE_GUARDIAN_SCAN.get());
                    }
                    if (scanTime % 5 == 0 && scanProgress >= 5.0F) {
                        Entity found = null;
                        HitResult hitresult = level().clip(new ClipContext(this.getEyePosition(), this.getEyePosition().add(this.getLookAngle().scale(8)), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
                        if (hitresult instanceof EntityHitResult entityHitResult && isValidTarget(entityHitResult.getEntity())) {
                            Entity inSight = entityHitResult.getEntity();
                            if (!inSight.equals(this) && !inSight.isAlliedTo(this) && !this.isAlliedTo(inSight) && this.hasLineOfSight(inSight)) {
                                found = inSight;
                            }
                        } else {
                            AABB around = new AABB(hitresult.getLocation().add(-0.5F, -0.5F, -0.5F), hitresult.getLocation().add(0.5F, 0.5F, 0.5F)).inflate(3);
                            for (Entity inSight : level().getEntitiesOfClass(LivingEntity.class, around)) {
                                if (!inSight.equals(this) && !inSight.isAlliedTo(this) && !this.isAlliedTo(inSight) && this.hasLineOfSight(inSight)) {
                                    if (found == null && isValidTarget(inSight) || found != null && isValidTarget(inSight) && inSight.distanceTo(this) < found.distanceTo(this)) {
                                        found = inSight;
                                    }
                                }
                            }
                        }
                        if (found instanceof LivingEntity living) {
                            this.setTarget(living);
                            this.setScanning(false);
                        }
                    }
                    scanTime++;
                } else {
                    scanTime = 0;
                    lastScanTime = tickCount;
                    this.setScanning(false);
                }
            } else if (this.isEyeClosed()) {
                int j = this.tickCount - lastScanTime;
                if (timeSinceHadTarget == 0 || !this.isInWaterOrBubble()) {
                    this.setEyeClosed(false);
                } else if (this.isInWaterOrBubble() && (timeSinceHadTarget > maxSleepTime && j > 200 || this.hurtTime > 0)) {
                    maxSleepTime = 200 + random.nextInt(100);
                    this.setScanning(true);
                    scanTime = 0;
                    maxScanTime = 100 + random.nextInt(100);
                }
            } else {
                if (this.isInWaterOrBubble() && timeSinceHadTarget > 100) {
                    this.setEyeClosed(true);
                }
            }
        } else {
            Vec3 vec3 = this.getDeltaMovement();
            if (vec3.y > 0.0D && this.clientSideTouchedGround && !this.isSilent()) {
                this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), this.getFlopSound(), this.getSoundSource(), 1.0F, 1.0F, false);
            }

            this.clientSideTouchedGround = vec3.y < 0.0D && this.level().loadedAndEntityCanStandOn(this.blockPosition().below(), this);

        }
    }

public void tick(){
        super.tick();
        prevCurlProgress = curlProgress;

        if (this.isCurled()) {
            if (curlProgress < 5F)
                curlProgress += 0.5F;
        } else {
            if (curlProgress > 0F)
                curlProgress--;
        }

        if (randomToungeTick == 0 && random.nextInt(15) == 0) {
            randomToungeTick = 10 + random.nextInt(20);
        }
        if (randomToungeTick > 0) {
            randomToungeTick--;
        }
        if (isCurled() && !isRattling() && ++curlTime > maxCurlTime) {
            this.setCurled(false);
            curlTime = 0;
            maxCurlTime = 75 + random.nextInt(50);
        }

        LivingEntity target = this.getTarget();
        if (!this.level().isClientSide) {
            if (this.isCurled() && (target != null && target.isAlive())) {
                this.setCurled(false);
            }
            if (this.isRattling() && target == null) {
                this.setCurled(true);

            }
            if (!this.isCurled() && this.getTarget() == null && random.nextInt(500) == 0) {
                maxCurlTime = 300 + random.nextInt(250);
                this.setCurled(true);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE) {
            if (this.getAnimationTick() == 4) {
                this.playSound(AMSoundRegistry.RATTLESNAKE_ATTACK.get(), getSoundVolume(), getVoicePitch());
            }
            if (this.getAnimationTick() == 8 && target != null && this.distanceTo(target) < 2D) {
                final boolean meepMeep = target instanceof EntityRoadrunner;
                final int f = isBaby() ? 2 : 1;
                target.hurt(this.damageSources().mobAttack(this), meepMeep ? 1.0F : f * (float) getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                if (!meepMeep) {
                    target.addEffect(new MobEffectInstance(MobEffects.POISON, 300, f * 2));
                }
            }
        }
        if(isRattling()){
            if(loopSoundTick == 0){
                this.gameEvent(GameEvent.ENTITY_ROAR);
                this.playSound(AMSoundRegistry.RATTLESNAKE_LOOP.get(), this.getSoundVolume() * 0.5F, this.getVoicePitch());
            }
            loopSoundTick++;
            if(loopSoundTick > 50){
                loopSoundTick = 0;
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void aiStep() {
        super.aiStep();
        if (this.isBaby() && this.getEyeHeight() > this.getBbHeight()) {
            this.refreshDimensions();
        }
        prevLeftPitch = this.getEyePitch(true);
        prevRightPitch = this.getEyePitch(false);
        prevLeftYaw = this.getEyeYaw(true);
        prevRightYaw = this.getEyeYaw(false);
        prevInWaterProgress = this.inWaterProgress;
        prevPunchProgress = this.punchProgress;
        updateEyes();
        if (this.isSitting() && this.getNavigation().isDone()) {
            this.getNavigation().stop();
        }

        if (this.isInWater()) {
            if (inWaterProgress < 5F)
                inWaterProgress++;

            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (inWaterProgress > 0F)
                inWaterProgress--;

            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        if (this.entityData.get(PUNCH_TICK) > 0) {
            if (this.entityData.get(PUNCH_TICK) == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 2.8D) {
                if (this.getTarget() instanceof AbstractFish && !this.isTame()) {
                    AbstractFish fish = (AbstractFish) this.getTarget();
                    CompoundTag fishNbt = new CompoundTag();
                    fish.addAdditionalSaveData(fishNbt);
                    fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                    fish.readAdditionalSaveData(fishNbt);
                }
                this.getTarget().knockback(1.7F, this.getX() - this.getTarget().getX(), this.getZ() - this.getTarget().getZ());
                float knockbackResist = (float) Mth.clamp((1.0D - this.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)), 0, 1);
                this.getTarget().setDeltaMovement(this.getTarget().getDeltaMovement().add(0, knockbackResist * 0.8F, 0));
                if (!this.getTarget().isInWater()) {
                    this.getTarget().setSecondsOnFire(2);
                }
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            }
            if(punchProgress == 1){
                this.playSound(AMSoundRegistry.MANTIS_SHRIMP_SNAP.get(), this.getVoicePitch(), this.getSoundVolume());
            }
            if (punchProgress == 2 && this.level().isClientSide && this.isInWater()) {
                for (int i = 0; i < 10 + random.nextInt(8); i++) {
                    double d2 = this.random.nextGaussian() * 0.6D;
                    double d0 = this.random.nextGaussian() * 0.2D;
                    double d1 = this.random.nextGaussian() * 0.6D;
                    float radius = this.getBbWidth() * 0.85F;
                    float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                    double extraX = radius * Mth.sin(Mth.PI + angle) + random.nextFloat() * 0.5F - 0.25F;
                    double extraZ = radius * Mth.cos(angle) + random.nextFloat() * 0.5F - 0.25F;
                    ParticleOptions data = ParticleTypes.BUBBLE;
                    this.level().addParticle(data, this.getX() + extraX, this.getY() + this.getBbHeight() * 0.3F + random.nextFloat() * 0.15F, this.getZ() + extraZ, d0, d1, d2);
                }
            }
            if (punchProgress < 2F) {
                punchProgress++;
            }
            this.entityData.set(PUNCH_TICK, this.entityData.get(PUNCH_TICK) - 1);
        } else {
            if (punchProgress > 0F) {
                punchProgress -= 0.25F;
            }
        }
    }

public void tick(){
        super.tick();
        this.prevBaskProgress = this.baskProgress;
        this.prevSitProgress = this.sitProgress;

        if (this.isSitting()) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (this.isBasking()) {
            if (baskProgress < 5F)
                baskProgress++;
        } else {
            if (baskProgress > 0F)
                baskProgress--;
        }

        if (!this.level().isClientSide) {
            if (this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 5 && this.hasLineOfSight(this.getTarget())) {
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
            if ((isSitting() || isBasking()) && ++sittingTime > maxSitTime) {
                this.setSitting(false);
                this.setBasking(false);
                sittingTime = 0;
                maxSitTime = 75 + random.nextInt(50);
            }
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isBasking() && !this.isSitting() && random.nextInt(100) == 0) {
                sittingTime = 0;
                maxSitTime = 100 + random.nextInt(550);
                if (this.getRandom().nextBoolean()) {
                    this.setSitting(true);
                    this.setBasking(false);
                } else {
                    this.setSitting(false);
                    this.setBasking(true);
                }
            }
        }
        if(this.getAnimation() == ANIMATION_HOWL && this.getAnimationTick() == 1){
            this.gameEvent(GameEvent.ENTITY_ROAR);
            this.playSound(AMSoundRegistry.TASMANIAN_DEVIL_ROAR.get(), this.getSoundVolume() * 2F, this.getVoicePitch());
        }
        if(this.getAnimation() == ANIMATION_HOWL && this.getAnimationTick() > 3){
            scareMobsTime = 40;
        }
        if(scareMobsTime > 0) {
            List<Monster> list = this.level().getEntitiesOfClass(Monster.class, this.getBoundingBox().inflate(16, 8, 16));
            for (Monster e : list) {
                e.setTarget(null);
                e.setLastHurtByMob(null);
                if(scareMobsTime % 5 == 0){
                    Vec3 vec = LandRandomPos.getPosAway(e, 20, 7, this.position());
                    if(vec != null){
                        e.getNavigation().moveTo(vec.x, vec.y, vec.z, 1.5D);
                    }
                }

            }
            scareMobsTime--;
        }
        if(this.getTarget() != null && this.getTarget().isAlive() && (this.getLastHurtByMob() == null || !this.getLastHurtByMob().isAlive()) ){
            this.setLastHurtByMob(this.getTarget());
        }
        if((this.isSitting() || this.isBasking()) && (this.getTarget() != null || this.isInLove())) {
            this.setSitting(false);
            this.setBasking(false);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        prevFlyRightProgress = flyRightProgress;
        prevLeftFlyProgress = flyLeftProgress;
        final boolean dashRight = isDashRight();
        final boolean flying = isFlying();
        if (flying && dashRight && flyRightProgress < 5F) {
            flyRightProgress++;
        }
        if ((!flying || !dashRight) && flyRightProgress > 0F) {
            flyRightProgress--;
        }
        if (flying && !dashRight && flyLeftProgress < 5F) {
            flyLeftProgress++;
        }
        if ((!flying || dashRight) && flyLeftProgress > 0F) {
            flyLeftProgress--;
        }
        if (!this.level().isClientSide) {
            if (flying) {
                if (this.isLandNavigator)
                    switchNavigator(false);
            } else {
                if (!this.isLandNavigator)
                    switchNavigator(true);
            }
        }
        if (flying) {
            if (loopSoundTick == 0) {
                this.playSound(AMSoundRegistry.MOSQUITO_LOOP.get(), this.getSoundVolume(), this.getVoicePitch() * 0.3F);
            }
            loopSoundTick++;
            if (loopSoundTick > 100) {
                loopSoundTick = 0;
            }
            timeFlying++;
            this.setNoGravity(true);
            if (this.isPassenger() || this.isVehicle()) {
                this.setFlying(false);
            }
        } else {
            timeFlying = 0;
            this.setNoGravity(false);
        }
        if (this.horizontalCollision && net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
            boolean flag = false;
            AABB axisalignedbb = this.getBoundingBox().inflate(0.2D);
            for (BlockPos blockpos : BlockPos.betweenClosed(Mth.floor(axisalignedbb.minX), Mth.floor(axisalignedbb.minY), Mth.floor(axisalignedbb.minZ), Mth.floor(axisalignedbb.maxX), Mth.floor(axisalignedbb.maxY), Mth.floor(axisalignedbb.maxZ))) {
                BlockState blockstate = this.level().getBlockState(blockpos);
                if (blockstate.is(AMTagRegistry.WARPED_MOSCO_BREAKABLES)) {
                    flag = this.level().destroyBlock(blockpos, true, this) || flag;
                }
            }
            if (!flag && this.onGround()) {
                this.jumpFromGround();
            }
        }

        LivingEntity target = this.getTarget();
        if (target != null && this.isAlive()) {
            if (this.getAnimation() == ANIMATION_SUCK && this.getAnimationTick() == 3 && this.distanceTo(target) < 4.7F) {
                target.startRiding(this, true);
            }
            if (this.getAnimation() == ANIMATION_SLAM) {
                if (this.getAnimationTick() == 19) {
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(5.0D))) {
                        if (!isAlliedTo(entity) && !(entity instanceof EntityWarpedMosco) && entity != this) {
                            entity.hurt(this.damageSources().mobAttack(this), 10.0F + random.nextFloat() * 8.0F);
                            launch(entity, true);
                        }
                    }

                }
            }
            if ((this.getAnimation() == ANIMATION_PUNCH_R || this.getAnimation() == ANIMATION_PUNCH_L) && this.getAnimationTick() == 13) {
                if (this.distanceTo(target) < 4.7F) {
                    target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackRidiculous(target, 0.9F);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_SLAM && this.getAnimationTick() == 19) {
            spawnGroundEffects();
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        if(isInNether()) {
            conversionTime++;
            if (conversionTime > 300 && !this.level().isClientSide) {
                Hoglin hoglin = this.convertTo(EntityType.HOGLIN, false);
                if(hoglin != null){
                    hoglin.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 200, 0));
                    this.dropEquipment();
                    level().addFreshEntity(hoglin);
                    this.remove(RemovalReason.DISCARDED);
                }
            }
        }
        if (entityToLaunchId != -1 && this.isAlive()) {
            Entity launch = this.level().getEntity(entityToLaunchId);
            this.ejectPassengers();
            entityToLaunchId = -1;
            if (launch != null && !launch.isPassenger()) {
                if (launch instanceof LivingEntity) {
                    launch.setPos(this.getEyePosition().add(0, 1, 0));
                    float rot = 180F + this.getYRot();
                    float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                    float x = Mth.sin(rot * Mth.DEG_TO_RAD);
                    float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
                    if (!(strength <= 0.0D)) {
                        launch.hasImpulse = true;
                        Vec3 vec3 = this.getDeltaMovement();
                        Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                        launch.setDeltaMovement(vec31.x, strength, vec31.z);
                    }
                }
            }
        }
        if (this.getAnimation() == ANIMATION_BUCK && this.getAnimationTick() >= 5) {
            Entity passenger = this.getControllingPassenger();
            if (passenger instanceof LivingEntity) {
                entityToLaunchId = passenger.getId();
            }
        }
        if (!this.level().isClientSide) {
            if (this.isVehicle()) {
                ridingTime++;
                if (ridingTime >= this.getMaxRidingTime() && this.getAnimation() != ANIMATION_BUCK) {
                    this.setAnimation(ANIMATION_BUCK);
                }
            } else {
                ridingTime = 0;
            }
            if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D) {
                for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                    if (!(entity instanceof EntityTusklin) && !entity.isPassengerOfSameVehicle(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                        if (entity.onGround()) {
                            double d0 = entity.getX() - this.getX();
                            double d1 = entity.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            float f = 0.5F;
                            entity.push(d0 / d2 * f, f, d1 / d2 * f);
                        }
                    }
                }
                this.setMaxUpStep(2F);
            }else{
                this.setMaxUpStep(1.1F);
            }
            if (this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 1.8F) {
                if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.9F, 0F);
                }
                if ((this.getAnimation() == ANIMATION_GORE_L) && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.5F, -90F);
                }
                if ((this.getAnimation() == ANIMATION_GORE_R) && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.5F, 90F);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_RUT && this.getAnimationTick() == 23) {
            if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
                if (this.isBaby()) {
                    if (level().getBlockState(this.blockPosition()).canBeReplaced() && random.nextInt(3) == 0) {
                        level().setBlockAndUpdate(this.blockPosition(), Blocks.BROWN_MUSHROOM.defaultBlockState());
                        this.gameEvent(GameEvent.BLOCK_DESTROY);
                        this.playSound(SoundEvents.CROP_PLANTED, this.getSoundVolume(), this.getVoicePitch());
                    }
                }
                this.level().levelEvent(2001, blockPosition().below(), Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
                this.level().setBlock(blockPosition().below(), Blocks.DIRT.defaultBlockState(), 2);
                this.heal(5);
            }
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && getRandom().nextInt(isBaby() ? 140 : 70) == 0 && (this.getLastHurtByMob() == null || this.distanceTo(this.getLastHurtByMob()) > 30)) {
            if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
                this.setAnimation(ANIMATION_RUT);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        LivingEntity target = entity.getTarget();
        if (target != null && target.isAlive()) {
            double distance = entity.distanceTo(target);
            double attackDistance = entity.getBbWidth() + target.getBbWidth();
            boolean inPursuit = !this.isMovementFrozen();
            if (attemptSonicDamageIn > 0) {
                attemptSonicDamageIn--;
                if (attemptSonicDamageIn == 0 && this.entity.hasLineOfSight(target)) {
                    target.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), entity.getSonicDamageAgainst(target));
                    knockBackAngle(target, 1.0F, 0F);
                }
            }
            if (sonicEnqueued && this.entity.hasLineOfSight(target) && distance < 200F) {
                this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                entity.setSonarId(target.getId());
                this.entity.getNavigation().stop();
                if(distance > 10 || entity.getRandom().nextFloat() < 0.4){
                    tryAnimation(ForsakenEntity.ANIMATION_SONIC_ATTACK);
                    this.entity.playSound(ACSoundRegistry.FORSAKEN_SCREECH.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
                }else{
                    tryAnimation(ForsakenEntity.ANIMATION_SONIC_BLAST);
                    this.entity.playSound(ACSoundRegistry.FORSAKEN_AOE.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
                }
                if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_ATTACK) {
                    inPursuit = false;
                    if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30 && attemptSonicDamageIn <= 0) {
                        attemptSonicDamageIn = (int) Math.ceil(distance * 0.2F);
                    }
                    if (this.entity.getAnimationTick() > 30) {
                        sonicEnqueued = false;
                    }
                }
                if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_BLAST) {
                    inPursuit = false;
                    if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30) {
                        if (this.entity.getAnimationTick() % 5 == 0) {
                            List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, this.entity.getBoundingBox().inflate(16, 8, 16));
                            for (LivingEntity living : list) {
                                if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceTo(entity) <= 14F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                                    living.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), (float) Math.ceil(entity.getSonicDamageAgainst(target) * 0.65F));
                                }
                            }
                        }
                    }
                    if (this.entity.getAnimationTick() > 40) {
                        sonicEnqueued = false;
                    }
                }
            } else if (jumpEnqueued) {
                if (jumpTarget == null) {
                    jumpTarget = findJumpTarget(target, distance > 20.0F);
                } else {
                    inPursuit = false;
                    if (entity.isLeaping()) {
                        Vec3 vec3 = this.entity.getDeltaMovement();
                        Vec3 vec31 = new Vec3(this.jumpTarget.getX() + 0.5F - this.entity.getX(), 0.0D, this.jumpTarget.getZ() + 0.5F - this.entity.getZ());
                        if (vec31.lengthSqr() > 1.0E-7D) {
                            vec31 = vec31.scale(0.155F).add(vec3.scale(0.2D));
                        }
                        this.entity.setDeltaMovement(vec31.x, 0.2F + (double) vec31.length() * 0.3F, vec31.z);
                        jumpEnqueued = false;
                        jumpTarget = null;
                    } else if (entity.onGround()) {
                        entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(jumpTarget));
                        tryAnimation(ForsakenEntity.ANIMATION_PREPARE_JUMP);
                    }
                }
            }
            if (inPursuit) {
                this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                this.entity.getNavigation().moveTo(target, 1.0D);
                if (distance < attackDistance + 1.0F && this.entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    float attackType = entity.getRandom().nextFloat();
                    if (attackType < 0.25F && target.getBbWidth() < 2.0F) {
                        tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_PICKUP : ForsakenEntity.ANIMATION_RIGHT_PICKUP);
                    } else if (attackType < 0.5F) {
                        tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_SLASH : ForsakenEntity.ANIMATION_RIGHT_SLASH);
                    } else if (attackType < 0.75F) {
                        tryAnimation(ForsakenEntity.ANIMATION_GROUND_SMASH);
                    } else {
                        tryAnimation(ForsakenEntity.ANIMATION_BITE);
                        this.entity.playSound(ACSoundRegistry.FORSAKEN_BITE.get());
                    }
                }
            } else {
                entity.getNavigation().stop();
            }
            if ((distance > 20.0F && this.entity.getRandom().nextFloat() < 0.01 || entity.hasSonicCharge()) && !this.sonicEnqueued) {
                this.sonicEnqueued = true;
                this.entity.setSonicCharge(false);
            }
            if (distance > 30.0F && this.entity.getRandom().nextFloat() < 0.05 && !this.jumpEnqueued) {
                this.startCleanJump();
            }
            if (distance < 64.0F && distance > attackDistance && inPursuit) {
                this.entity.setRunning(true);
            } else {
                this.entity.setRunning(false);
            }
            if ((entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_PICKUP || entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_PICKUP) && entity.getHeldMobId() == target.getId() && entity.getAnimationTick() >= 30) {
                checkAndDealDamage(target, 1.2F, 5);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
                float knockbackStrength = 0.5F;
                if (checkAndDealDamage(target, 0.8F, 2)) {
                    knockbackStrength = 3F;
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
                knockBackAngle(target, knockbackStrength, -90F);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
                float knockbackStrength = 0.5F;
                if (checkAndDealDamage(target, 0.8F, 2)) {
                    knockbackStrength = 3F;
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
                knockBackAngle(target, knockbackStrength, 90F);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_GROUND_SMASH && entity.getAnimationTick() >= 10 && entity.getAnimationTick() <= 15) {
                Vec3 smashPos = entity.position().add(new Vec3(0, 0, 3.5F).yRot((float) -Math.toRadians(entity.yBodyRot)));
                List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, new AABB(smashPos.x - 4, smashPos.y - 2, smashPos.z - 4, smashPos.x + 4, smashPos.y + 3, smashPos.z + 4));
                boolean flag = false;
                for (LivingEntity living : list) {
                    if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceToSqr(smashPos) <= 16F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                        if (checkAndDealDamage(living, 0.8F, 3) && living.onGround()) {
                            living.setDeltaMovement(living.getDeltaMovement().add(0, 0.5, 0));
                            flag = true;
                        }
                    }
                }
                if(flag){
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_BITE && entity.getAnimationTick() >= 5 && entity.getAnimationTick() <= 8) {
                float knockbackStrength = 0.0F;
                if (checkAndDealDamage(target, 1F, 1)) {
                    knockbackStrength = 0.5F;
                }
                knockBackAngle(target, knockbackStrength, 0F);
            }
            if (navigationCheckCooldown-- < 0 && this.entity.onGround()) {
                navigationCheckCooldown = 20 + entity.getRandom().nextInt(40);
                if (!canReach(target)) {
                    this.startCleanJump();
                }
            }
        }
    }

public void tick() {
        super.tick();
        this.prevLatchProgress = latchProgress;
        if (this.isLatched() && latchProgress < 5F) {
            latchProgress++;
        }
        if (!this.isLatched() && latchProgress > 0F) {
            latchProgress--;
        }
        if (noLatchCooldown > 0) {
            noLatchCooldown--;
        }
        double d1 = (this.getX() - xo);
        double d2 = (this.getZ() - zo);
        double d3 = Math.sqrt(d1 * d1 + d2 * d2);
        if (isLatched() && verticalCollision && d3 > 0.1F) {
            if (tickCount - lastStepTimestamp > 6) {
                lastStepTimestamp = tickCount;
                BlockState state = level().getBlockState(BlockPos.containing(this.getX(), this.getBoundingBox().maxY + 0.5, this.getZ()));
                this.playSound(state.getSoundType().getStepSound(), 1F, 0.5F);
            }
        }
        if (!level().isClientSide) {
            if (this.isLatched() && !this.isUpsideDownNavigator) {
                switchNavigator(true);
            }
            if (!this.isLatched() && this.isUpsideDownNavigator) {
                switchNavigator(false);
            }
        }
        Entity head = getHead();
        if (head instanceof BoundroidEntity boundroid) {
            if (!level().isClientSide) {
                this.entityData.set(HEAD_ID, head.getId());
                double distance = this.distanceTo(boundroid);
                double distanceGoal = isLatched() ? 1.25F + Math.sin(tickCount * 0.1F) * 0.25F : 3.5F;
                boolean headNoClip = false;
                float pullSpeed = boundroid.getTarget() != null ? 0.3F : 0.1F;
                if (!boundroid.hasLineOfSight(this) && !boundroid.stopPullingUp() && distance > 7) {
                    headNoClip = true;
                }
                if (distance > distanceGoal && !boundroid.stopPullingUp()) {
                    double disRem = Math.min(distance - distanceGoal, 1F);
                    Vec3 moveTo = getChainFrom(1.0F).subtract(boundroid.position());
                    if (moveTo.length() > 1.0D) {
                        moveTo = moveTo.normalize();
                    }
                    boundroid.draggedClimable = true;
                    boundroid.setDeltaMovement(boundroid.getDeltaMovement().multiply(0.95F, 0.7F, 0.95F).add(moveTo.scale(disRem * pullSpeed)));
                } else {
                    boundroid.draggedClimable = false;
                }
                distanceToCeiling = calculateDistanceToCeiling();
                if (this.isLatched()) {
                    this.setNoGravity(true);
                    if (distanceToCeiling > MAX_DIST_TO_CEILING || !isAlive() || noLatchCooldown > 0) {
                        changeLatchStateTime++;
                    } else {
                        changeLatchStateTime = 0;
                    }
                    if (changeLatchStateTime > 5) {
                        this.setLatched(false);
                        if(noLatchCooldown > 0){
                            this.playSound(ACSoundRegistry.BOUNDROID_DAZED.get(), 2.0F, 1.0F);
                        }
                        changeLatchStateTime = 0;
                    }
                    this.setDeltaMovement(this.getDeltaMovement().add(0, 0.14, 0).scale(0.85F));
                    goingUp = false;
                    boundroid.stopGravity = true;
                } else {
                    this.setNoGravity(false);
                    boundroid.stopGravity = false;
                    if ((distanceToCeiling < MAX_DIST_TO_CEILING || verticalCollision && !verticalCollisionBelow) && noLatchCooldown <= 0) {
                        changeLatchStateTime++;
                    } else {
                        changeLatchStateTime = 0;
                    }
                    if (changeLatchStateTime > 5) {
                        this.setLatched(true);
                        changeLatchStateTime = 0;
                    }
                    if(goingUp && !hasBlockAbove()){
                        goingUp = false;
                    }
                    if (goingUp) {
                        this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, 1.5F, this.getDeltaMovement().z));
                    } else if (this.onGround() && noLatchCooldown == 0 && this.isAlive() && random.nextInt(30) == 0 && distanceToCeiling > MAX_DIST_TO_CEILING && hasBlockAbove()) {
                        goingUp = true;
                    }
                }
                boundroid.noPhysics = headNoClip;
            }
            if (boundroid.hurtTime > 0 || boundroid.deathTime > 0) {
                this.hurtTime = boundroid.hurtTime;
                this.deathTime = boundroid.deathTime;
            }
        } else if (!level().isClientSide) {
            this.remove(RemovalReason.KILLED);
        }
    }

public void tick() {
        super.tick();
        prevFaceCameraProgress = faceCameraProgress;
        prevLaserLvl = this.getLaserAttackLvl();
        if (this.getAnimation() == ANIMATION_EMERGE) {
            this.setHasEmerged(true);
            faceCameraProgress = 1F;
        } else if (faceCameraProgress > 0.0F) {
            faceCameraProgress = Math.max(0, faceCameraProgress - 0.2F);
        }
        prevAngryProgress = angryProgress;
        for (int i = 0; i < HANDS; i++) {
            prevClaspProgress[i] = claspProgress[i];
            prevStrikeProgress[i] = strikeProgress[i];
        }
        if (this.posPointer < 0) {
            for (int i = 0; i < this.positions.length; ++i) {
                this.positions[i][0] = this.getX();
                this.positions[i][1] = this.getY();
                this.positions[i][2] = this.getZ();
                this.positions[i][3] = this.yBodyRot;
            }
        }
        if (++this.posPointer == this.positions.length) {
            this.posPointer = 0;
        }
        this.positions[this.posPointer][0] = this.getX();
        this.positions[this.posPointer][1] = this.getY();
        this.positions[this.posPointer][2] = this.getZ();
        this.positions[this.posPointer][3] = this.yBodyRot;
        if (this.isAngry() && angryProgress < 5F) {
            angryProgress++;
        }
        if (!this.isAngry() && angryProgress > 0F) {
            angryProgress--;
        }
        if (this.isAlive()) {
            if (random.nextInt(isAngry() ? 12 : 40) == 0 && claspingHand == -1) {
                int i = Mth.clamp(random.nextInt(HANDS), 0, 3);
                if (claspProgress[i] == 0) {
                    claspingHand = i;
                }
            }
            if (claspingHand >= 0) {
                if (claspProgress[claspingHand] < 5F) {
                    claspProgress[claspingHand]++;
                } else {
                    claspingHand = -1;
                }
            } else {
                for (int i = 0; i < HANDS; i++) {
                    if (claspProgress[i] > 0) {
                        claspProgress[i]--;
                    }
                }
            }
            if (!this.hasEmerged()) {
                this.setInvisible(true);
                if(this.level().hasNearbyAlivePlayer(this.getX(), this.getY(), this.getZ(), 9)){
                    this.setAnimation(ANIMATION_EMERGE);
                }
            }else{
                this.setInvisible(this.hasEffect(MobEffects.INVISIBILITY));
            }
            if (this.getAnimation() == ANIMATION_EMERGE) {
                if(this.level().isClientSide){
                    this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getRandomX(0.75F), this.getRandomY(), this.getRandomZ(0.75F), (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
                }
                if(this.getAnimationTick() == 1){
                    this.playSound(AMSoundRegistry.FARSEER_EMERGE.get(), this.getSoundVolume(), this.getVoicePitch());
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null) {
                if (this.entityData.get(MELEEING)) {
                    if (meleeCooldown == 0) {
                        meleeCooldown = 5;
                        int i = random.nextInt(HANDS);
                        this.isStriking[i] = true;
                        this.level().broadcastEntityEvent(this, (byte) (40 + i));
                    }
                }
            }
            if (meleeCooldown > 0) {
                meleeCooldown--;
            }
            for (int i = 0; i < HANDS; i++) {
                if (!this.isStriking[i] || !this.entityData.get(MELEEING)) {
                    if (strikeProgress[i] > 0F) {
                        strikeProgress[i]--;
                    }
                } else if (this.isStriking[i]) {
                    if (strikeProgress[i] < 5F) {
                        strikeProgress[i]++;
                    }
                    if (strikeProgress[i] == 5F) {
                        isStriking[i] = false;
                        this.level().broadcastEntityEvent(this, (byte) (44 + i));
                        if (target != null && distanceTo(target) <= 4F) {
                            target.hurt(this.damageSources().mobAttack(this), 5 + random.nextInt(5));
                        }
                    }
                }
            }

            if (this.hasLaser()) {
                LivingEntity livingentity = this.getLaserTarget();
                if (livingentity != null) {
                    Vec3 hit = this.calculateLaserHit(livingentity.getEyePosition());
                    this.entityData.set(LASER_DISTANCE, (float) hit.distanceTo(this.getEyePosition()));
                    this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
                    this.getLookControl().tick();
                    double d0 = hit.x - this.getX();
                    double d1 = hit.y - this.getEyeY();
                    double d2 = hit.z - this.getZ();
                    double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                    d0 = d0 / d3;
                    d1 = d1 / d3;
                    d2 = d2 / d3;
                    float progress = this.getLaserAttackLvl() / (float) LASER_ATTACK_DURATION;
                    double d4 = this.random.nextDouble();
                    while (d4 < d3 * progress) {
                        d4 += 0.5F + 2F * this.random.nextDouble();
                        double width = d4 / (d3 * progress);
                        double d5 = (random.nextDouble() - 0.5F) * width;
                        double d6 = (random.nextDouble() - 0.5F) * width;
                        this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getX() + d0 * d4 + d5, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4 + d6, (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
                    }
                }
            }
        }
        if (this.isAngry()) {
            angryShakeVec = new Vec3(random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F);
        } else {
            angryShakeVec = Vec3.ZERO;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public static void tremor(LivingEntity livingEntity, int distance, double topY, float side, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double minY = livingEntity.getY() - 2.0D;
        double maxY = livingEntity.getY() + topY;
        float angle = (float) ((Math.PI / 180.0F) * livingEntity.yHeadRot);
        float f = Mth.cos(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        float f1 = Mth.sin(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        double extraX = distance * Mth.sin((float) (Math.PI + angle));
        double extraZ = distance * Mth.cos(angle);
        double px = livingEntity.getX() + extraX + f * side;
        double pz = livingEntity.getZ() + extraZ + f1 * side;
        int hitX = Mth.floor(px);
        int hitZ = Mth.floor(pz);
        BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);
        BlockPos abovePos = new BlockPos(blockPos).above();
        BlockState blockState = livingEntity.level.getBlockState(blockPos);
        BlockState blockAbove = livingEntity.level.getBlockState(abovePos);

        if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
            ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
            livingEntity.level.addFreshEntity(fallingBlock);
        }
        AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
        List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
        for (LivingEntity target : entities) {
            if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                if (flag) {
                    MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                }
            }
        }
        if (distance % 4 == 0) {
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
        }
    }

public static void surroundTremor(LivingEntity livingEntity, int distance, double topY, float side, boolean grab, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double spread = Math.PI * (double)2.0F;
        int arcLen = Mth.ceil((double)distance * spread);
        double minY = livingEntity.getY() - 1.0D;
        double maxY = livingEntity.getY() + topY;

        for(int i = 0; i < arcLen; ++i) {
            double theta = ((double)i / ((double)arcLen - 1.0D) - 0.5D) * spread;
            double vx = Math.cos(theta);
            double vz = Math.sin(theta);
            double px = livingEntity.getX() + vx * (double)distance + (double)side * Math.cos((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            double pz = livingEntity.getZ() + vz * (double)distance + (double)side * Math.sin((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            float factor = 1.0F - (float)distance / 12.0F;
            int hitX = Mth.floor(px);
            int hitZ = Mth.floor(pz);
            BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);

            BlockState blockState;
            for(blockState = livingEntity.level.getBlockState(blockPos); blockState.getRenderShape() != RenderShape.MODEL; blockState = livingEntity.level.getBlockState(blockPos)) {
                blockPos = blockPos.below();
            }
            BlockState blockAbove = livingEntity.level.getBlockState(blockPos.above());

            if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
                ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
                livingEntity.level.addFreshEntity(fallingBlock);
            }

            if (distance % 4 == 0) {
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            }

            AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
            List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
            for (LivingEntity target : entities) {
                if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                    boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                    if (flag) {
                        if (grab) {
                            if (target.isDamageSourceBlocked(livingEntity.damageSources().mobAttack(livingEntity))) {
                                MobUtil.disableShield(target);
                            }
                        } else {
                            MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                        }
                    }
                }
            }
        }

    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            for (Entity target : getBreathTarget(caster, range)) {
                if (target != null) {
                    if (target.hurt(ModDamageSource.swarm(caster, caster), damage)){
                        if (rightStaff(staff)) {
                            if (target instanceof LivingEntity livingTarget) {
                                MobEffect mobEffect = MobEffects.POISON;
                                if (CuriosFinder.hasWildRobe(caster)) {
                                    mobEffect = GoetyEffects.ACID_VENOM.get();
                                }
                                livingTarget.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5) * duration));
                            }
                        }
                        if (!target.isAlive()){
                            InsectSwarm insectSwarm = new InsectSwarm(worldIn, caster, target.position());
                            insectSwarm.setLimitedLife(200 * duration);
                            if (potency > 0){
                                insectSwarm.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), potency - 1, false, false));
                            }
                            worldIn.addFreshEntity(insectSwarm);
                        }
                    }
                }
            }
        }
        this.playSound(worldIn, caster, ModSounds.INSECT_SWARM.get(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

public static void chainLightning(LivingEntity pTarget, @Nullable LivingEntity pAttacker, ColorUtil colorUtil, double range, float damage, boolean small) {
        Level level = pTarget.level;

        List<Entity> harmed = new ArrayList<>();
        Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && !harmed.contains(livingEntity);
        if (pAttacker != null){
            selector = selector.and(entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && MobUtil.canAttack(pAttacker, livingEntity));
        }
        Entity prevTarget = pTarget;

        int hops = level.isThundering() ? 8 : 4;

        for (int i = 0; i < hops; i++) {
            AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
            Entity finalPrevTarget = prevTarget;
            List<Entity> entities = level.getEntities(prevTarget, aabb, selector.and(entity -> MobUtil.hasLineOfSight(finalPrevTarget, entity)));
            if (!entities.isEmpty()) {
                Entity target = entities.get(level.getRandom().nextInt(entities.size()));
                DamageSource damageSource = ModDamageSource.getDamageSource(pTarget.level, ModDamageSource.SHOCK);
                if (pAttacker != null){
                    damageSource = ModDamageSource.directShock(pAttacker);
                }
                if (target.hurt(damageSource, damage)) {
                    if (prevTarget != target) {
                        Vec3 vec3 = prevTarget.getEyePosition();
                        Vec3 vec31 = target.getEyePosition();
                        if (small){
                            ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 5));
                        } else {
                            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 8));
                        }
                    }
                }

                harmed.add(target);
                prevTarget = target;
                damage--;
            }
        }
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
        float potency = spellStat.getPotency();
        int range = spellStat.getRange();
        int burning = spellStat.getBurning();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            range += WandUtil.getRangeLevel(caster);
            burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        }
        float damage = SpellConfig.WaterJetDamage.get().floatValue() * WandUtil.damageMultiply();
        damage += potency;
        HitResult result = this.rayTrace(worldIn, caster, range, 3.0F);
        if (result.getType() != HitResult.Type.MISS) {
            double particleOffset = 0;
            if (result instanceof EntityHitResult entityHitResult) {
                Entity target = entityHitResult.getEntity();
                if (!MobUtil.areAllies(caster, target)) {
                    MiscCapHelper.setClientTarget(caster, target);
                    if (target.hurt(ModDamageSource.directDrench(caster), damage)) {
                        if (this.rightStaff(staff) && target instanceof LivingEntity livingEntity) {
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), MathHelper.secondsToTicks(5)));
                        }
                    }
                }
                if (burning <= 0) {
                    target.clearFire();
                } else if (!MobUtil.areAllies(caster, target)) {
                    target.setSecondsOnFire(5 * burning);
                }
                particleOffset = target.getBbHeight() / 2;
            } else if (result instanceof BlockHitResult blockHitResult) {
                BlockPos blockPos = blockHitResult.getBlockPos();
                this.dowseFire(caster, worldIn, blockPos);
            }
            Vec3 vec3 = result.getLocation();
            worldIn.sendParticles(ModParticleTypes.WATER_TRAIL.get(), vec3.x, vec3.y + particleOffset, vec3.z, 1, 0, 0, 0, 0.15);
        }
        if (result.getType() == HitResult.Type.MISS || !(result instanceof EntityHitResult)) {
            MiscCapHelper.setClientTarget(caster, null);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float area = this.getAreaOfEffect() / 2;
            float f = 1.5F + area;
            float f5 = (float) Math.PI * f * f;
            for (int k1 = 0; (float) k1 < f5; ++k1) {
                float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                float f8 = Mth.cos(f6) * f7;
                float f9 = Mth.sin(f6) * f7;
                serverLevel.sendParticles(ModParticleTypes.BURNING.get(), this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 1, 0, 0, 0, 0);
            }
            ColorUtil color = ColorUtil.GOLD;
            ServerParticleUtil.windParticle(serverLevel, color, (f - 1.0F) + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());
            ServerParticleUtil.windParticle(serverLevel, color, f + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());

            if (this.tickCount == 20 || this.getImmediate()){
                for (int j1 = 0; j1 < 16; ++j1) {
                    for (int k1 = 0; (float) k1 < f5; ++k1) {
                        float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                        float f8 = Mth.cos(f6) * f7;
                        float f9 = Mth.sin(f6) * f7;
                        serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                    }
                }
                List<Entity> targets = new ArrayList<>();
                float area0 = 1.0F + area;
                AABB aabb = this.getBoundingBox();
                AABB aabb1 = new AABB(aabb.minX - area0, aabb.minY - 1.0F, aabb.minZ - area0, aabb.maxX + area0, aabb.maxY + 1.0F, aabb.maxZ + area0);
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb1)){
                    if (this.owner != null) {
                        if (entity != this.owner && !MobUtil.areAllies(entity, this.owner)) {
                            if (this.owner instanceof Mob mob && this.owner instanceof Enemy && entity instanceof Enemy) {
                                if (mob.getTarget() == entity) {
                                    targets.add(entity);
                                }
                            } else {
                                targets.add(entity);
                            }
                        }
                    } else {
                        targets.add(entity);
                    }
                }
                if (!targets.isEmpty()){
                    for (Entity entity : targets) {
                        if ((this.owner != null && CuriosFinder.hasUnholySet(this.owner))) {
                            if (entity instanceof LivingEntity livingEntity) {
                                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.BURN_HEX.get(), 1200));
                            }
                            entity.hurt(ModDamageSource.hellfire(this, this.owner), AttributesConfig.ApostleMagicDamage.get().floatValue() + this.getExtraDamage());
                        } else {
                            float damage = 5.0F;
                            if (this.owner != null){
                                if (this.owner instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                                    damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                                }
                                entity.hurt(ModDamageSource.magicFireBreath(this, this.owner), damage + this.getExtraDamage());
                            } else {
                                entity.hurt(damageSources().magic(), damage + this.getExtraDamage());
                            }
                        }
                        if (entity instanceof LivingEntity livingEntity) {
                            MobUtil.push(livingEntity, 0.0D, 1.0D, 0.0D, 0.5D);
                            if (this.burning > 0){
                                livingEntity.setSecondsOnFire(this.burning * 4);
                            }
                        }
                    }
                }
            }
        }
        if (this.tickCount > 20 || (this.getImmediate() && this.tickCount > 5)){
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.25D, 0.0D));
            this.move(MoverType.SELF, this.getDeltaMovement());
        }
        if (this.tickCount == 20 || (this.getImmediate() && this.tickCount == 5)){
            this.playSound(SoundEvents.GENERIC_EXPLODE, 1.0F, 0.5F);
        }
        if (this.owner != null){
            if (this.owner.isDeadOrDying() || this.owner.isRemoved()){
                this.discard();
            }
        }
        if (this.tickCount % 30 == 0){
            this.discard();
        }
    }

@Override
    public void tick() {
        float progress = this.getProgress();
        this.prevProgress = progress;
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if(tickCount == 1){
            if(!this.level().isClientSide){
                this.playSound(ModSounds.TIDAL_TENTACLE.get(),1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        if(!this.isRetracting() && progress < MAX_EXTEND_TIME){
            this.setProgress(progress + 1);
        }
        if(this.isRetracting() && progress > 0F){
            this.setProgress(progress - 1);
        }
        if(this.isRetracting() && progress == 0F){
            Entity from = this.getFromEntity();
            if(from instanceof Tidal_Tentacle_Entity){
                Tidal_Tentacle_Entity tendonSegment = (Tidal_Tentacle_Entity) from;
                tendonSegment.setRetracting(true);
                updateLastTendon(tendonSegment);
            }else{
                updateLastTendon(null);
            }

            kill();
        }
        if (creator instanceof LivingEntity) {
            if (current != null) {
                Vec3 target = new Vec3(current.getX(), current.getY(0.4F), current.getZ());
                Vec3 lerp = target.subtract(this.position());
                this.setDeltaMovement(lerp.scale(0.5F));
                if(!this.level().isClientSide){
                    if(progress >= MAX_EXTEND_TIME){
                        if (this.tickCount % 2 == 0) {
                            Entity entity = getCreatorEntity();
                            if(entity instanceof LivingEntity) {
                                if (current != creator && current.hurt(damageSources().mobProjectile(this, (LivingEntity) entity), this.getBaseDamage())) {
                                    MobEffectInstance effectinstance1 = ((LivingEntity)current).getEffect(ModEffect.EFFECTABYSSAL_CURSE.get());
                                    int i = 1;
                                    if (effectinstance1 != null) {
                                        i += effectinstance1.getAmplifier();
                                        ((LivingEntity)current).removeEffectNoUpdate(ModEffect.EFFECTABYSSAL_CURSE.get());
                                    } else {
                                        --i;
                                    }

                                    i = Mth.clamp(i, 0, 4);
                                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTABYSSAL_CURSE.get(), 60, i, false, true, true);
                                    ((LivingEntity)current).addEffect(effectinstance);

                                    // this.doEnchantDamageEffects((LivingEntity) creator, current);
                                }
                            }
                        }
                    }
                }
            }
        }
        Vec3 vector3d = this.getDeltaMovement();
        if(!this.level().isClientSide){
            if(!hasChained){
                if(this.getTargetsHit() > 5){
                    this.setRetracting(true);
                }else if(creator instanceof LivingEntity && this.getProgress() >= MAX_EXTEND_TIME) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(12.0D))) {
                        if (!entity.equals(creator) && !previouslyTouched.contains(entity) && isValidTarget((LivingEntity) creator, entity) && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createChain(closestValid);
                        hasChained = true;
                    }else{
                        this.setRetracting(true);
                    }
                }
            }
        }

        double d0 = this.getX() + vector3d.x;
        double d1 = this.getY() + vector3d.y;
        double d2 = this.getZ() + vector3d.z;
        this.setDeltaMovement(vector3d.scale(0.99F));
        this.setPos(d0, d1, d2);
    }

public void tick() {
        super.tick();
        if(!madeOpenNoise){
            this.gameEvent(GameEvent.ENTITY_PLACE);
            this.playSound(ModSounds.BLACK_HOLE_OPENING.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
            madeOpenNoise = true;
        }


        for (Entity entity : this.level().getEntities(this, this.getBoundingBox().inflate(30))) {
            if (entity != owner) {
                if (entity instanceof Player && ((Player) entity).getAbilities().invulnerable) continue;
                if (isAlliedTo(entity)) continue;
                if (entity instanceof The_Leviathan_Entity) continue;
                if (entity instanceof The_Leviathan_Tongue_Entity) continue;
                Vec3 diff = entity.position().subtract(this.position().add(0, 0, 0));
                if (entity instanceof LivingEntity) {
                    diff = diff.normalize().scale( getStage() * 0.015);
                    entity.setDeltaMovement(entity.getDeltaMovement().subtract(diff));
                } else if(!entity.getType().is(ModTag.DIMENSIONAL_LIFT_IMMUNE)) {
                    diff = diff.normalize().scale(getStage() * 0.045);
                    entity.setDeltaMovement(entity.getDeltaMovement().subtract(diff));
                }
            }
        }
            berserkBlockBreaking(15, 15, 15);

            for (LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.2D, 0.0D, 0.2D))) {
                this.damage(livingentity);
            }

            for (Entity entity : this.level().getEntities(this, this.getBoundingBox().inflate(0.5))) {
                if (entity instanceof Cm_Falling_Block_Entity) {
                    entity.remove(RemovalReason.DISCARDED);
                }
            }


            if (this.random.nextInt(3000) < this.ambientSoundTime++) {
                this.resetAmbientSoundTime();
                this.playSound(ModSounds.BLACK_HOLE_LOOP.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
            }



        this.setLifespan(this.getLifespan() - 1);
        if(this.getLifespan() <= 100){
            if(!madeCloseNoise){
                this.gameEvent(GameEvent.ENTITY_PLACE);
                this.playSound(ModSounds.BLACK_HOLE_CLOSING.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
                madeCloseNoise = true;
            }
            if(this.tickCount % 40 == 0){
                this.setStage(this.getStage() - 1);
            }

            if (this.getStage() <= 0) {
                if(!madeParticle){
                    if (this.level().isClientSide) {
                        this.level().addParticle(ModParticle.SHOCK_WAVE.get(), this.getX(), this.getY(), this.getZ(), 0, 0, 0);
                    }else{
                        this.level().explode(this.owner, this.getX(), this.getY(), this.getZ(), 4.0F, false, Level.ExplosionInteraction.NONE);
                    }
                    madeParticle = true;
                }else{
                    this.discard();
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        prevCollidePosX = collidePosX;
        prevCollidePosY = collidePosY;
        prevCollidePosZ = collidePosZ;
        prevYaw = renderYaw;
        prevPitch = renderPitch;
        renderYaw = getYaw();
        renderPitch = getPitch();
        xo = getX();
        yo = getY();
        zo = getZ();
        if (tickCount == 1 && level().isClientSide) {
            caster = (LivingEntity) level().getEntity(getCasterID());
        }

        if (!on && appear.getTimer() == 0) {
            this.discard();
        }
        if (on && tickCount > 20) {
            appear.increaseTimer();
        } else {
            appear.decreaseTimer();
        }

        if(tickCount ==20){
            this.level().playSound((Player) null, this, ModSounds.PORTAL_ABYSS_BLAST.get(), SoundSource.HOSTILE, 0.5f, 1.0f);
        }

        if (caster != null && !caster.isAlive()) discard();

        if (tickCount > 20) {
            this.calculateEndPos();
            List<LivingEntity> hit = raytraceEntities(level(), new Vec3(getX(), getY(), getZ()), new Vec3(endPosX, endPosY, endPosZ)).entities;
            if (blockSide != null) {
                spawnExplosionParticles(3);
                if (!this.level().isClientSide) {
                    for (BlockPos pos : BlockPos.betweenClosed(Mth.floor(collidePosX - 0.5F), Mth.floor(collidePosY - 0.5F), Mth.floor(collidePosZ - 0.5F), Mth.floor(collidePosX + 0.5F), Mth.floor(collidePosY + 0.5F), Mth.floor(collidePosZ + 0.5F))) {
                        BlockState block = level().getBlockState(pos);
                        if (!block.isAir() && !block.is(ModTag.LEVIATHAN_IMMUNE) && net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                            level().destroyBlock(pos, false);
                        }
                    }
                }
            }
            if (!level().isClientSide) {
                for (LivingEntity target : hit) {
                    if (caster != null) {
                        if (!this.caster.isAlliedTo(target) && target != caster) {
                            boolean flag = target.hurt(CMDamageTypes.causeDeathLaserDamage(this, caster), (float) (this.getDamage() + Math.min(this.getDamage(), target.getMaxHealth() * this.getHpDamage() * 0.01)));
                            if (flag) {
                                MobEffectInstance effectinstance1 = target.getEffect(ModEffect.EFFECTABYSSAL_BURN.get());
                                int i = 1;
                                if (effectinstance1 != null) {
                                    i += effectinstance1.getAmplifier();
                                    target.removeEffectNoUpdate(ModEffect.EFFECTABYSSAL_BURN.get());
                                } else {
                                    --i;
                                }

                                i = Mth.clamp(i, 0, 3);
                                MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTABYSSAL_BURN.get(), 160, i, false, true, true);
                                target.addEffect(effectinstance);
                            }
                        }
                    }

                }
            }
        }
        if (tickCount - 20 > getDuration()) {
            on = false;
        }
    }

private void EarthQuake(UseOnContext context, Player player) {
        Level world = context.getLevel();

        boolean berserk = player.getHealth() <= player.getMaxHealth() * 0.5F;
        double radius = 4.0D;

        world.playSound(player, player.blockPosition(), ModSounds.EXPLOSION.get(), SoundSource.PLAYERS, 1.5F, 1.0F / (world.getRandom().nextFloat() * 0.4F + 0.8F));

        if (world.isClientSide) {
            BlockState block = world.getBlockState(context.getClickedPos());
            int numParticles = 80;
            for (int i = 0; i < numParticles; i++) {

                double angle = (double) i / numParticles * (Math.PI * 2.0D);
                double d0 = player.getX() + radius * Math.sin(angle);
                double d1 = player.getY() + 0.15D;
                double d2 = player.getZ() + radius * Math.cos(angle);

                double d3 = world.getRandom().nextGaussian() * 0.1D;
                double d4 = world.getRandom().nextGaussian() * 0.1D;
                double d5 = world.getRandom().nextGaussian() * 0.1D;

                world.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, block), d0, d1, d2, d3, d4, d5);
                if (berserk) {
                    world.addParticle(ParticleTypes.FLAME, d0, d1, d2, d3, d4, d5);
                }
            }
        } else if (world instanceof ServerLevel serverLevel) {
            ScreenShake_Entity.ScreenShake(serverLevel, player.position(), 30, 0.1f, 0, 30);

            DamageSource shredderDamage = serverLevel.damageSources().playerAttack(player);
            float basedmg = AttributeUtils.OriginDamage(player, context.getItemInHand());

            List<Entity> list = serverLevel.getEntities(player, player.getBoundingBox().inflate(radius));
            for (Entity entity : list) {
                if (entity instanceof LivingEntity living) {
                    float bonusDamage = EnchantmentHelper.getDamageBonus(context.getItemInHand(), living.getMobType());
                    float enchanteddmg = basedmg + bonusDamage;

                    if (living.hurt(shredderDamage, enchanteddmg)) {
                        living.setDeltaMovement(living.getDeltaMovement().multiply(0.5D, 1.0D, 0.5D).add(0.0D, 0.6D, 0.0D));
                        if (berserk) {
                            living.setSecondsOnFire(5);
                        }
                    }

                }
            }
        }
    }

@Override
    public void tick() {
        if (!level.isClientSide) {
            if (tickCount % delay == 0) {
                //do volley
                int arrows = arrowsPerRow;
                float speed = .85f;
                Vec3 motion = Vec3.directionFromRotation(getXRot() - tickCount / 5f * 7, this.getYRot()).normalize().scale(speed);
                Vec3 orth = new Vec3(-Mth.cos(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI), 0, Mth.sin(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI));
                for (int i = 0; i < arrows; i++) {
                    float distance = (i - arrows * .5f) * .7f;
                    SmallMagicArrow arrow = new SmallMagicArrow(this.level, this.getOwner());
                    arrow.setDamage(this.getDamage());
                    var spawn = this.position().add(orth.scale(distance));
                    arrow.setPos(spawn);
                    arrow.shoot(motion.add(Utils.getRandomVec3(.04f)));
                    arrow.setOwner(this.getOwner());
                    level.addFreshEntity(arrow);
                    MagicManager.spawnParticles(level, ParticleTypes.FIREWORK, spawn.x, spawn.y, spawn.z, 2, .1, .1, .1, .05, false);
                }
                level.playSound(null, position().x, position().y, position().z, SoundEvents.FIREWORK_ROCKET_LAUNCH, SoundSource.NEUTRAL, 3.0f, 1.1f + Utils.random.nextFloat() * .3f);
                level.playSound(null, position().x, position().y, position().z, SoundRegistry.BOW_SHOOT.get(), SoundSource.NEUTRAL, 2, Utils.random.nextIntBetweenInclusive(16, 20) * .1f);
            } else if (tickCount > rows * delay) {
                discard();
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        // swirling line towards destination during delay
        if (startPos != null && !level.isClientSide && tickCount < getDelay()) {
            float f = tickCount / (float) getDelay();
            Vec3 forward = position().subtract(startPos).multiply(1, 0, 1).normalize();
            Vec3 right = new Vec3(-forward.z, 0, forward.x);
            Vec3 spawn = startPos.lerp(position(), f);
            float phase = tickCount * 0.5f;
            float threshold = 3;
            float distance = (float) position().subtract(spawn).horizontalDistance();
            float strength = distance > threshold ? 1 : distance / threshold;
            Vec3 oscillation = right.scale(Mth.sin(phase) * 2 * strength);
            spawn = Utils.moveToRelativeGroundLevel(level, spawn.add(oscillation), 6);
            float yrot = Utils.getAngle(startPos.x, startPos.z, getX(), getZ());
            if (!level.getBlockState(BlockPos.containing(spawn).below()).isAir()) {
                ExtendedEvokerFang fang = new ExtendedEvokerFang(level, spawn.x, spawn.y, spawn.z, yrot, 0, this.getOwner() instanceof LivingEntity e ? e : null, this.getDamage());
                level.addFreshEntity(fang);
            }
        }
    }

@Override
    public void tick() {
        if (!isSpawnDagger() && age++ < delay) {
            var owner = getOwner();
            float strength = .5f;
            if (owner != null && isTrackingOwner()) {
                //use client delta motion instead of jittery server information
                Vec3 ownerMotion = owner.position().subtract(owner.xOld, owner.yOld, owner.zOld);
                setPos(this.position().add(ownerMotion));
            }
            var target = getTargetEntity();
            if (target != null) {
                var targetPos = target.getBoundingBox().getCenter();
                Vec3 targetMotion = targetPos.subtract(this.position()).normalize().scale(this.getSpeed());
                Vec3 currentMotion = getDeltaMovement();
                deltaMovementOld = currentMotion;
                this.setDeltaMovement(currentMotion.add(targetMotion.subtract(currentMotion).scale(strength)));
                // prevent first-tick flicker due to deltaMoveOld being "uninitialized" on our first tick
                if (tickCount == 1) {
                    deltaMovementOld = getDeltaMovement();
                }
            }
            if (age == delay) {
                if (isGrounded) {
                    if (Utils.random.nextFloat() < 0.25f) {
                        playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 0.75f, Utils.random.nextIntBetweenInclusive(90, 110) * .01f);
                    }
                } else {
                    playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 2f, Utils.random.nextIntBetweenInclusive(90, 110) * .01f);
                }
                // do an initial near-collision check since we cannot organically hit things if we originate inside their hitbox (such as if they are standing on a dagger)
                var hits = level.getEntities(this, this.getBoundingBox().inflate(0.4f), this::canHitEntity);
                EntityHitResult hitResult = hits.isEmpty() ? null : new EntityHitResult(hits.getFirst());
                if (hitResult != null) {
                    onHit(hitResult);
                }
            }
            if (level.isClientSide) {
                level.addParticle(ParticleHelper.EMBERS, getX(), getY() + getBbHeight() * .5f, getZ(), 0, 0, 0);
            }
        } else {
            super.tick();
        }
    }

