public static void tickOnceForge(Player player) {
    if (!WAS_ACTIVE.containsKey(player)) return;

    if (player.isFallFlying() || player.isSleeping() || player.isAutoSpinAttack()) {
        if (wasActive(player)) {
            Services.PLATFORM.setForcedPlayerPose(player, null);
            setWasActive(player, false);
        }
        return;
    }

    if (!wasActive(player) && Services.PLATFORM.canSetPose(player) && Services.POWER.hasPower(player, ApugliPowers.CRAWLING.get()) && (player.hasPose(Pose.STANDING) || player.hasPose(Pose.CROUCHING))) {
        Services.PLATFORM.setForcedPlayerPose(player, Pose.SWIMMING);
        setWasActive(player, true);
    } else if (wasActive(player) && !Services.POWER.hasPower(player, ApugliPowers.CRAWLING.get())) {
        Services.PLATFORM.setForcedPlayerPose(player, null);
        setWasActive(player, false);
    }
}

@Override
public void onRemoved() {
    if (this.entity instanceof Player player && Services.POWER.getPowers(player, ApugliPowers.CRAWLING.get()).size() - 1 <= 0) {
        boolean wasActive = WAS_ACTIVE.remove(player);
        if (wasActive) {
            Services.PLATFORM.setForcedPlayerPose(player, null);
        }
    }
}

private static void setWasActive(Player player, boolean value) {
    WAS_ACTIVE.put(player, value);
}

public static boolean wasActive(Player player) {
    return WAS_ACTIVE.get(player);
}

@SubscribeEvent
public static void onLivingTick(LivingEvent.LivingTickEvent event) {
    event.getEntity().getCapability(KeyPressCapability.INSTANCE).ifPresent(KeyPressCapability::tick);

    if (event.getEntity().isDeadOrDying()) return;

    if (event.getEntity() instanceof Player player) {
        CrawlingPower.tickOnceForge(player);
    }

    IndividualisedEmptyStackUtil.addEntityToStack(event.getEntity());
    if (ModList.get().isLoaded("pehkui") && !Services.POWER.getPowers(event.getEntity(), ApugliPowers.MODIFY_SCALE.get(), true).isEmpty())
        PehkuiUtil.tickScalePowers(event.getEntity());

    if (Services.POWER.hasPower(event.getEntity(), ApugliPowers.HOVER.get())) {
        event.getEntity().setDeltaMovement(event.getEntity().getDeltaMovement().multiply(1.0, 0.0, 1.0));
        event.getEntity().fallDistance = 0.0F;
    }

    if (event.getEntity().level().isClientSide)
        Services.POWER.getPowers(event.getEntity(), ApugliPowers.CLIENT_ACTION_OVER_TIME.get()).forEach(ClientActionOverTime::clientTick);

    if (!event.getEntity().level().isClientSide) {
        event.getEntity().getCapability(HitsOnTargetCapability.INSTANCE).ifPresent(HitsOnTargetCapability::serverTick);
        ApugliPowers.BUNNY_HOP.get().onTravel(event.getEntity(), new Vec3(event.getEntity().xxa, event.getEntity().yya, event.getEntity().zza));
    }
}

