@Override
	protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
		if (!attacker.level().isClientSide) {
			for (LivingEntity entity : target.level().getEntitiesOfClass(LivingEntity.class, new AABB(target.getX() - 1.5, target.getBoundingBox().minY, target.getZ() - 1.5, target.getX() + 1.5, target.getBoundingBox().minY + 1, target.getZ() + 1.5), EntityUtil::isHostileMob)) {
				entity.igniteForSeconds((int)(5 * attackCooldown));
			}

			AoAResource.Instance spirit = target instanceof ServerPlayer ? PlayerUtil.getResource((ServerPlayer)target, AoAResources.SPIRIT.get()) : null;
			float consumeAmount = (spirit != null ? Math.min(50, spirit.getCurrentValue()) : 50) * attackCooldown;

			if (consumeAmount > 0) {
				if (spirit != null && !spirit.consume(consumeAmount, true))
					return;

				if (attacker instanceof ServerPlayer)
					PlayerUtil.addResourceToPlayer((ServerPlayer)attacker, AoAResources.SPIRIT.get(), consumeAmount);
			}
		}
	}

@Override
	protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
		if (attackCooldown > 0.75) {
			Collection<MobEffectInstance> effects = attacker.getActiveEffects();

			if (!effects.isEmpty()) {
				ArrayList<MobEffectInstance> removableEffects = new ArrayList<MobEffectInstance>(effects.size());

				for (MobEffectInstance effect : effects) {
					if (!effect.getEffect().value().isBeneficial())
						removableEffects.add(effect);
				}

				for (MobEffectInstance effect : removableEffects) {
					target.addEffect(effect);
					attacker.removeEffect(effect.getEffect());
				}
			}
		}
	}

@Override
	protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
		if (!attacker.level().isClientSide && !EntityUtil.isImmuneToSpecialAttacks(target) && RandomUtil.percentChance(0.1f * attackCooldown)) {
			List<LivingEntity> nearbyMobs = EntityRetrievalUtil.getEntities(target, 5, LivingEntity.class, nearby -> EntityUtil.areProbablyEnemies(nearby, attacker));

			if (nearbyMobs.size() > 1) {
				EffectBuilder builder = new EffectBuilder(MobEffects.BLINDNESS, 60);
				LivingEntity newTarget = null;

				for (LivingEntity nearbyMob : nearbyMobs) {
					if ((newTarget = nearbyMob) != target)
						break;
				}

				if (newTarget == null)
					return;

				target.setLastHurtByMob(newTarget);
				BrainUtils.setTargetOfEntity(target, newTarget);

				EntityUtil.applyPotions(target, attacker, builder);
			}
		}
	}

@Override
	protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
		if (!attacker.level().isClientSide && attackCooldown > 0.75) {
			ItemStack offhandStack = attacker.getOffhandItem();

			if (offhandStack.is(AoATags.Items.ADVENT_RUNE) && offhandStack.getCount() >= 5) {
				Item rune = offhandStack.getItem();

				if (rune == AoAItems.POISON_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.POISON, 72).level(2));
				}
				else if (rune == AoAItems.WITHER_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.WITHER, 40).level(3));
				}
				else if (rune == AoAItems.WIND_RUNE.get()) {
					DamageUtil.doScaledKnockback(target, attacker, 0.5f, 1, 1, 1);
				}
				else if (rune == AoAItems.WATER_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, 60));
				}
				else if (rune == AoAItems.CHARGED_RUNE.get()) {
					((ServerLevel)target.level()).sendParticles(ParticleTypes.ANGRY_VILLAGER, target.getX() + (RandomUtil.valueUpTo(1) * target.getBbWidth() * 2f) - target.getBbWidth(), target.getY() + 1 + (RandomUtil.valueUpTo(1) * target.getBbHeight()), target.getZ() + (RandomUtil.valueUpTo(1) * target.getBbWidth() * 2f) - target.getBbWidth(), 3, 0, 0, 0, (double)0);
				}
				else if (rune != AoAItems.FIRE_RUNE.get()) {
					return;
				}

				if (attacker instanceof Player pl && !pl.getAbilities().instabuild) {
					offhandStack.shrink(5);
					ItemUtil.damageItemForUser(pl, stack, EquipmentSlot.MAINHAND);
				}
			}
		}
	}

