		if(this.world.isRemote && this.ticksExisted % 3 == 0){
			ParticleBuilder.create(Type.SPARK)
					.pos(this.posX - 0.5d + rand.nextDouble(), this.posY + 2 * rand.nextDouble(), this.posZ - 0.5d + rand.nextDouble())
					.spawn(world);
		}

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		++this.fallTime;
		this.motionY -= 0.03999999910593033D;
		this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		this.motionX *= 0.9800000190734863D;
		this.motionY *= 0.9800000190734863D;
		this.motionZ *= 0.9800000190734863D;

		if(this.onGround){

			this.motionX *= 0.699999988079071D;
			this.motionZ *= 0.699999988079071D;
			this.motionY *= -0.5D;

			this.rotationPitch = 0;
			this.spin = false;

			double seekerRange = Spells.lightning_hammer.getProperty(Spell.EFFECT_RADIUS).doubleValue();

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX,
					this.posY + 1, this.posZ, world);

			int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue();
			while(targets.size() > maxTargets) targets.remove(targets.size() - 1);

			for(EntityLivingBase target : targets){

				if(EntityUtils.isLiving(target) && this.isValidTarget(target)
						&& target.ticksExisted % Spells.lightning_hammer.getProperty(LightningHammer.ATTACK_INTERVAL).floatValue() == 0){

					if(world.isRemote){

						ParticleBuilder.create(Type.LIGHTNING).pos(posX, posY + height - 0.1, posZ) .target(target).spawn(world);

						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height, target.posZ);
					}

					target.playSound(WizardrySounds.ENTITY_HAMMER_ATTACK, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					float damage = Spells.lightning_hammer.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier;

					if(this.getCaster() != null){
						EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(
								this, getCaster(), DamageType.SHOCK), damage);
						EntityUtils.applyStandardKnockback(this, target);
					}else{
						target.attackEntityFrom(DamageSource.MAGIC, damage);
					}
				}
			}

		}else{

			if(spin) this.setRotation(this.rotationYaw, this.rotationPitch + 15);

			List<Entity> collided = world.getEntitiesInAABBexcluding(this, this.getCollisionBoundingBox(), e -> e instanceof EntityLivingBase);

			float damage = Spells.lightning_hammer.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

			for(Entity entity : collided){
				entity.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.SHOCK), damage);
				//if(entity instanceof EntityLivingBase) ((EntityLivingBase)entity).knockBack(this, 2, -this.motionX, -this.motionZ);
			}
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		BlockPos pos = this.getPosition().down(1);
		IBlockState blockState = this.world.getBlockState(pos);

		if(!this.world.isRemote) {
			if(blockState.getBlock() == Blocks.AIR || (this.hasPlayerOwner() && !blockState.isSideSolid(this.world, pos, EnumFacing.UP))) {
				this.setDead();
			}

			Entity owner = this.getPlayerOwner();

			if(this.hasPlayerOwner() && (owner == null || owner.getDistance(this) > 32.0D)) {
				this.setHealth(0);
			} else if(owner instanceof EntityPlayer) {
				EntityPlayer player = (EntityPlayer) owner;
				if(!ItemRingOfSummoning.isRingActive(player)) {
					this.setHealth(0);
				}
			}

			if(this.despawnTicks >= 150) {
				this.setHealth(0);
			} else {
				if(this.spawnTicks >= 40) {
					this.despawnTicks++;
				}
			}
		}

		if(this.deathTicks > 0) {
			this.yOffset = -this.deathTicks / 40.0F;
		} else if(this.spawnTicks >= 40) {
			this.yOffset = 0.0F;
		}

		if(this.isEntityAlive()) {
			if(this.spawnTicks >= 4) {
				List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox());
				for(EntityLivingBase target : targets) {

					boolean isValidTarget;
					if(this.hasPlayerOwner()) {
						isValidTarget = target != this && target != this.getPlayerOwner() && (target instanceof EntityMob || target instanceof IMob);
					} else {
						isValidTarget = target instanceof EntityPlayer;
					}
					if(isValidTarget) {
						target.setInWeb();

						if(target.hurtResistantTime < 10) {
							DamageSource damageSource;
							Entity owner = this.getPlayerOwner();
							if(owner != null) {
								damageSource = new EntityDamageSourceIndirect("mob", this, owner);
							} else {
								damageSource = DamageSource.causeMobDamage(this);
							}

							target.attackEntityFrom(damageSource, (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());

							if(this.attackSwing <= 0) {
								this.attackSwing = 20;
							}
						}
					}
				}
			}

			if(this.spawnTicks < 40) {
				this.spawnTicks++;
				this.yOffset = -1 + this.spawnTicks / 40.0F;
			} else {
				this.yOffset = 0.0F;
			}

			if(this.attackSwing > 0) {
				this.attackSwing--;
			}
		}

		if(this.world.isRemote && this.rand.nextInt(this.yOffset < 0.0F ? 2 : 8) == 0) {
			if(blockState.getBlock() != Blocks.AIR) {
				double px = this.posX;
				double py = this.posY;
				double pz = this.posZ;
				for (int i = 0, amount = 2 + this.rand.nextInt(this.yOffset < 0.0F ? 8 : 3); i < amount; i++) {
					double ox = this.rand.nextDouble() * 0.1F - 0.05F;
					double oz = this.rand.nextDouble() * 0.1F - 0.05F;
					double motionX = this.rand.nextDouble() * 0.2 - 0.1;
					double motionY = this.rand.nextDouble() * 0.1 + 0.1;
					double motionZ = this.rand.nextDouble() * 0.2 - 0.1;
					this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, px + ox, py, pz + oz, motionX, motionY, motionZ, Block.getStateId(blockState));
				}
			}
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if(!this.world.isRemote) {
			if(this.source == null) {
				this.setDead();
			} else {
				Entity shootingEntity;
				DamageSource damageSource;

				if(this.source instanceof EntityBLArrow) {
					shootingEntity = ((EntityBLArrow) this.source).getThrower();

					if(shootingEntity != null) {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, shootingEntity);
					} else {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, (EntityBLArrow) this.source);
					}
				} else if(this.source instanceof EntityLivingBase) {
					shootingEntity = null;
					damageSource = DamageSource.causeMobDamage((EntityLivingBase) this.source);
				} else {
					shootingEntity = null;
					damageSource = DamageSource.GENERIC;
				}

				List<Pair<Entity, Entity>> chain = new ArrayList<>();

				if(this.jumps < this.maxJumps) {
					if(this.ticksExisted != 0 && this.ticksExisted % 3 == 0) {
						Set<EntityLivingBase> newTargets = new HashSet<>();

						entityLoop: for(Entity entity : this.targets) {
							boolean isWet = entity.isWet() || entity.isInWater() || this.world.isRainingAt(entity.getPosition().up());

							List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, entity.getEntityBoundingBox().grow(isWet ? 6 : 4), e -> {
								Entity riding = e.getLowestRidingEntity();

								//Passengers are handled further down
								if(riding != e && riding instanceof EntityLivingBase) {
									return false;
								}

								return true;	
							});

							if(entities.size() > 1) {
								Collections.sort(entities, (e1, e2) -> Double.compare(e1.getDistanceSq(entity), e2.getDistanceSq(entity)));

								for(int j = 1; j < entities.size(); j++) {
									EntityLivingBase newTarget = entities.get(j);

									if(!this.targets.contains(newTarget) && !newTargets.contains(newTarget)) {
										newTargets.add(newTarget);

										chain.add(Pair.of(entity, newTarget));

										float f = MathHelper.sqrt(this.source.motionX * this.source.motionX + this.source.motionY * this.source.motionY + this.source.motionZ * this.source.motionZ);

										float damage = this.damage;
										if(this.source instanceof EntityBLArrow) {
											damage = MathHelper.ceil((double)f * ((EntityBLArrow) this.source).getDamage());

											if (((EntityBLArrow) this.source).getIsCritical()) {
												damage += this.rand.nextInt((int)damage / 2 + 2);
											}
										}

										boolean blocked = false;

										for(ItemStack stack : newTarget.getEquipmentAndArmor()) {
											if(!stack.isEmpty() && stack.getItem() instanceof ItemRubberBoots) {
												stack.damageItem(2, newTarget);
												blocked = true;
											}
										}

										boolean wasShocked = false;

										if(!blocked) {
											wasShocked = newTarget.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);

											//Also zap all passengers >:)
											for(Entity passenger : newTarget.getRecursivePassengers()) {
												if(passenger instanceof EntityLivingBase && !this.targets.contains(passenger) && !newTargets.contains(passenger)) {
													passenger.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);
													newTargets.add((EntityLivingBase) passenger);
												}
											}
										}

										if(!wasShocked) {
											newTarget.addPotionEffect(ElixirEffectRegistry.EFFECT_SHOCKED.createEffect(newTarget instanceof EntityPlayer ? 30 : 80, 0, true, true));
										}

										continue entityLoop;
									}
								}
							}
						}

						this.targets.addAll(newTargets);

						TheBetweenlands.networkWrapper.sendToAllTracking(new MessageShockArrowHit(chain), this);

						this.jumps++;
					}
				} else {
					this.setDead();
				}
			}
		}
	}

@Override
    public boolean hurt(@NotNull DamageSource source, float damage) {
        Entity parent = getParent();
        if (level.isClientSide && source.getEntity() instanceof Player && parent != null) {
            IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageMultipartInteract(parent.getId(), damage * damageMultiplier));
        }
        return parent != null && parent.hurt(source, damage * this.damageMultiplier);
    }

public boolean attackEntityFrom(DamageSource source, float damage){
		if(source != null && source.getImmediateSource() instanceof IProjectile){
			world.playSound(null, source.getImmediateSource().posX, source.getImmediateSource().posY,
					source.getImmediateSource().posZ, WizardrySounds.ENTITY_SHIELD_DEFLECT, WizardrySounds.SPELLS, 0.3f, 1.3f);
		}
		super.attackEntityFrom(source, damage);
		return false;
	}

@Override
    protected void onHitBlock(BlockHitResult traceResult) {
        byte basePenetration = entityData.get(PENETRATION);
        int remainingPenetration = basePenetration - blockPenetration;
        if (piercingIgnoreEntityIds != null) {
            remainingPenetration -= piercingIgnoreEntityIds.size();
        }
        double canPenetrate = remainingPenetration * 0.25;
        byte techLevel = entityData.get(TECH_LEVEL);
        if (canPenetrate > 0 && basePenetration >= techLevel * 1.5) {
            blockPenetration += remainingPenetration;
            BlockPos pos = traceResult.getBlockPos();
            BlockState blockstate = level().getBlockState(pos);
            if (!blockstate.isAir()) {
                VoxelShape voxelshape = blockstate.getCollisionShape(level(), pos);
                if (!voxelshape.isEmpty()) {
                    boolean canPass = true;
                    Vec3 vector3d1 = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(canPenetrate, canPenetrate, canPenetrate));

                    for (AABB axisalignedbb : voxelshape.toAabbs()) {
                        if (axisalignedbb.move(pos).contains(vector3d1)) {
                            canPass = false;
                            break;
                        }
                    }
                    if (canPass) {
                        this.playSound(SoundEvents.ANCIENT_DEBRIS_BREAK, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                        for (int i = 0; i < 25; i++) {
                            Vec3 critPos = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(2, 2, 2).add((-0.5 + random.nextGaussian()) * 0.2, (-0.5 + random.nextGaussian()) * 0.2, (-0.5 + random.nextGaussian()) * 0.2));
                            Vec3 critVel = getDeltaMovement().normalize().multiply(5, 5, 5);
                            level().addParticle(ParticleTypes.CRIT, critPos.x, critPos.y, critPos.z, critVel.x, critVel.y, critVel.z);
                        }

                        //Fire Shrapnel
                        Vec3 shrapnelTravelEnd = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(remainingPenetration, remainingPenetration, remainingPenetration));
                        EntityHitResult result = findHitEntity(traceResult.getLocation(), shrapnelTravelEnd);
                        if (result != null) {
                            Entity entity = result.getEntity();
                            DamageSource damagesource = getDamageSource(entity);
                            float velocity = (float) this.getDeltaMovement().length();
                            int damage = Mth.ceil(Mth.clamp((double) velocity * this.getBaseDamage(), 0.0D, 2.147483647E9D));
                            entity.hurt(damagesource, (float) damage * 0.75F);
                        }
                    }
                }
            }
        }

        this.lastState = level().getBlockState(traceResult.getBlockPos());
        BlockState blockstate = level().getBlockState(traceResult.getBlockPos());
        blockstate.onProjectileHit(level(), blockstate, traceResult, this);
        Vec3 vector3d = traceResult.getLocation().subtract(this.getX(), this.getY(), this.getZ());
        this.setDeltaMovement(vector3d);
        Vec3 vector3d1 = vector3d.normalize().scale((double) 0.05F);
        this.setPosRaw(this.getX() - vector3d1.x, this.getY() - vector3d1.y, this.getZ() - vector3d1.z);
        this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
        this.inGround = true;
        this.shakeTime = 7;
        this.setCritArrow(false);
        this.setPierceLevel((byte) 0);
        this.setSoundEvent(SoundEvents.ARROW_HIT);
        this.resetPiercedEntities();
    }

@Override
    public Set<ScheduledTask> tasks(final PluginContainer plugin) {
        final String testOwnerId = Objects.requireNonNull(plugin, "plugin").metadata().id();

        final Set<ScheduledTask> allTasks = this.tasks();
        final Iterator<ScheduledTask> it = allTasks.iterator();

        while (it.hasNext()) {
            final String taskOwnerId = it.next().task().plugin().metadata().id();
            if (!testOwnerId.equals(taskOwnerId)) {
                it.remove();
            }
        }

        return allTasks;
    }

void popFrameMutator(final PhaseContext<?> context) {
        final @Nullable PhaseContext<?> peek = this.phaseContextProviders.peek();
        if (peek == null) {
            return;
        }
        if (peek != context) {
            // there's an exception to be thrown or printed out at least, basically a copy of popFrame.
            System.err.println("oops. corrupted phase context providers!");
        }
        this.phaseContextProviders.pop();
        if (this.phaseContextProviders.isEmpty()) {
            // if we're empty, we don't need to bother with the context providers
            // because there's nothing to push.
            this.pendingProviders.compareAndSet(true, false);
        }

    }

@Redirect(method = "execute",
            at = @At(
                    value = "INVOKE",
                    target = "Ljava/lang/Runnable;run()V",
                    remap = false))
    private void tracker$callOnMainThreadWithPhaseState(final Runnable runnable) {
        // The server thread has been killed, we are unable to process requests any further.
        if (this.tracker$isServerAndIsServerStopped()) {
            this.dropAllTasks();
            return;
        }

        try (final BasicPluginContext context = PluginPhase.State.SCHEDULED_TASK.createPhaseContext(PhaseTracker.getInstance())
                .source(runnable)) {
            context.buildAndSwitch();
            runnable.run();
        }
    }

private void sendRegistries(Acknowledge msg, CustomPayloadEvent.Context ctx) {
        if (msg.token() != expectedToken) {
            LOGGER.error(MARKER, "Received unknown acknowledgement received {} exptected {}", msg.token(), expectedToken);
            ctx.getConnection().disconnect(Component.literal("Illegal Acknowledge packet received, unknown token: " + msg.token()));
            return;
        }

        // We've got no more to send, so finish this task!
        if (this.snapshot == null || this.snapshot.isEmpty()) {
            taskCtx.finish(type());
            return;
        }

        // Send the next registry!
        var name = this.snapshot.keySet().iterator().next();
        var data = this.snapshot.remove(name);
        expectedToken = this.handler.expectAck(this::sendRegistries);
        NetworkInitialization.CONFIG.reply(new RegistryData(expectedToken, name, data), ctx);
    }

public void runTasks() {
        if (tasks.isEmpty()) return;
        LOGGER.debug(LOADING, "Dispatching synchronous work for work queue {}: {} jobs", modLoadingStage, tasks.size());
        RuntimeException aggregate = new RuntimeException();
        Stopwatch timer = Stopwatch.createStarted();
        for (TaskInfo t : tasks) {
            makeRunnable(t, Runnable::run, aggregate);
        }
        timer.stop();
        if (aggregate.getSuppressed().length > 0) {
            LOGGER.fatal(
                    LOADING,
                    "Synchronous work queue completed exceptionally in {}, see suppressed exceptions for details:",
                    timer,
                    aggregate
            );
            throw aggregate;
        } else {
            LOGGER.debug(LOADING, "Synchronous work queue completed in {}", timer);
        }
    }

@SuppressWarnings("rawtypes")
    private void checkProviders() {
        // Seriously, ok so, uh...
        if (!this.pendingProviders.compareAndSet(true, false)) {
            return; // we've done our work already
        }
        // Then, we want to inversely iterate the stack (from bottom to top)
        // to properly mimic as though the frames were created at the time of the
        // phase switches. It does not help the debugging of cause frames
        // except for this method call-point.
        for (final Iterator<PhaseContext<@NonNull ?>> iterator = this.phaseContextProviders.descendingIterator(); iterator.hasNext(); ) {
            final PhaseContext<@NonNull ?> context = iterator.next();
            final StackFrame frame = this.pushCauseFrame(); // these should auto close
            context.getFrameModifier().accept(frame); // The frame will be auto closed by the phase context
        }
        // Clear the list since everything is now loaded.
        // PhaseStates will handle automatically closing their frames
        // and then any new phase states that get entered can still be lazily loaded afterwards, while
        // we take advantage of the already made modifications are being tracked by the stack manager
        this.phaseContextProviders.clear();
    }

