@Override
    public void tick() {
        super.tick();
        double dist = bear.distanceTo(target);
        bear.getLookControl().setLookAt(this.target.getX(), this.target.getEyeY(), this.target.getZ());
        if(dist <= 6 && bear.hasLineOfSight(target)){
            bear.getNavigation().stop();
            if(bear.getAprilFoolsFlag() == 5){
                leapTimer++;
                if(leapTimer == 7){
                    AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                }
                if(leapTimer >= 10){
                    bear.setAprilFoolsFlag(0);
                    if(bear.level().getLevelData().isHardcore()){
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() - 1);
                        target.setHealth(1);
                    }else{
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() + 1000F);
                    }
                    stop();
                    return;
                }
            }else if(bear.getAprilFoolsFlag() < 4) {
                if(powerOutTimer == 0){
                    target.addEffect(new MobEffectInstance(AMEffectRegistry.POWER_DOWN.get(), 2 * (maxMusicBoxTime + 100), 0, false, false, true));
                }
                powerOutTimer++;
                if (powerOutTimer >= 60) {
                    bear.setAprilFoolsFlag(4);
                    powerOutTimer = 0;
                }else{
                    bear.setAprilFoolsFlag(3);
                }
            }else{
                if(musicBoxTimer == 0){
                    bear.level().broadcastEntityEvent(bear, (byte) 67);
                }
                musicBoxTimer++;
                if (musicBoxTimer >= maxMusicBoxTime) {
                    if(bear.getAprilFoolsFlag() != 5){
                        bear.level().broadcastEntityEvent(bear, (byte) 68);
                        bear.setAprilFoolsFlag(5);
                        bear.gameEvent(GameEvent.ENTITY_ROAR);
                        bear.playSound(AMSoundRegistry.APRIL_FOOLS_SCREAM.get(), 3, 1);
                        musicBoxTimer = 0;
                    }
                }
            }
            if(bear.getAprilFoolsFlag() < 2){
                bear.setAprilFoolsFlag(2);
            }
        }else{
            bear.getNavigation().moveTo(target, 1.2F);
            if(bear.getAprilFoolsFlag() < 1){
                bear.setAprilFoolsFlag(1);
            }
        }
    }

public void rideTick() {
        final Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                final Entity mount = this.getVehicle();
                if (mount instanceof final LivingEntity livingEntity) {
                    this.yBodyRot = livingEntity.yBodyRot;
                    this.setYRot(livingEntity.getYRot());
                    this.yHeadRot = livingEntity.yHeadRot;
                    this.yRotO = livingEntity.yHeadRot;
                    final float radius = 1F;
                    final float angle = (Maths.STARTING_ANGLE * livingEntity.yBodyRot);
                    final double extraX = radius * Mth.sin(Mth.PI + angle);
                    final double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    if (!this.level().isClientSide) {
                        if (drinkTime % 20 == 0 && this.isAlive()) {
                            final boolean mungus = AMConfig.warpedMoscoTransformation && mount instanceof EntityMungus && ((EntityMungus) mount).isWarpedMoscoReady();
                            if (mount.hurt(this.damageSources().mobAttack(this), mungus ? 7F : 2.0F)) {
                                if (mungus) {
                                    ((EntityMungus) mount).disableExplosion();
                                }
                                final boolean sick = this.isNonMungusWarpedTrigger(mount);
                                if (sick || mungus) {
                                    if (!this.isSick()) {
                                        for (ServerPlayer serverplayerentity : this.level().getEntitiesOfClass(ServerPlayer.class, this.getBoundingBox().inflate(40.0D, 25.0D, 40.0D))) {
                                            AMAdvancementTriggerRegistry.MOSQUITO_SICK.trigger(serverplayerentity);
                                        }
                                    }
                                    this.setSick(true);
                                    this.setFlying(false);
                                    flightTicks = -150 - random.nextInt(200);
                                }
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.HONEY_DRINK, this.getSoundVolume(), this.getVoicePitch());
                                this.setBloodLevel(this.getBloodLevel() + 1);
                                if (this.getBloodLevel() > 3) {
                                    this.removeVehicle();
                                    AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                                    this.setFlying(false);
                                    this.flightTicks = -15;
                                }
                            }
                        }

                        if (drinkTime > 81) {
                            drinkTime = -20 - random.nextInt(20);
                            this.removeVehicle();
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(false);
                            this.flightTicks = -15;
                        }
                    }
                }

            }
        }

    }

private void doTick(Level level, BlockPos pos, BlockState blockState) {
		if (!(blockState.getBlock() instanceof HenostoneFireSpitterBlock fireSpitter)) return;

		Direction dir = fireSpitter.getDirection(blockState);

		rangeLen = raycastRange(level, pos, dir, 8.0);

		AABB detectionAABB = buildAABB(pos, dir, rangeLen);

		switch (state) {

		case IDLE -> {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			if (!entities.isEmpty()) {
				boolean hasValidTarget = entities.stream().anyMatch(e ->
				!(e instanceof Player player && player.isCreative()));
				if (hasValidTarget) {
					transitionTo(FireState.WARNING_1, level, pos);
				}
			}
			setPowered(level, pos, blockState, false);
		}

		case WARNING_1 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_2, level, pos);
			}
		}

		case WARNING_2 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_3, level, pos);
			}
		}

		case WARNING_3 -> {
			timer++;
			if (timer == WARNING_3A_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3B_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3C_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer >= FIRE_START_TICKS - WARNING_3A_TICKS) {
				transitionTo(FireState.FIRING, level, pos);
			}
		}

		case FIRING -> {
			timer++;
			setPowered(level, pos, blockState, true);

			List<LivingEntity> targets = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			double ox = pos.getX() + 0.5;
			double oy = pos.getY() + 0.5;
			double oz = pos.getZ() + 0.5;
			level.addParticle(ParticleTypes.FLAME, ox, oy, oz, dir.getStepX() * 0.5, 0, dir.getStepZ() * 0.5);
			for (LivingEntity entity : targets) {
				if (!entity.fireImmune()) {
					entity.setSecondsOnFire(8);
					entity.hurt(level.damageSources().inFire(), 1);
				}
			}

			if (timer >= FIRE_END_TICKS - FIRE_START_TICKS) {
				transitionTo(FireState.COOLDOWN, level, pos);
			}
		}

		case COOLDOWN -> {
			timer++;
			setPowered(level, pos, blockState, false);
			if (timer >= COOLDOWN_TICKS) {
				transitionTo(FireState.IDLE, level, pos);
			}
		}
		}
	}

@Override
