            }
            if (this.attackTicks == 23) {
                StompDamage(0.25f, 5, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                StompDamage(0.25f, 6, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                Stompsound(5.5F,-0.2F);

            }
            if (this.attackTicks == 25) {
                StompDamage(0.25f, 7, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                StompDamage(0.25f, 8, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                Stompsound(7.5F,-0.2F);

            }
            if (this.attackTicks == 27) {
                StompDamage(0.25f, 9, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                StompDamage(0.25f, 10, 5,1.05F, 2.0f, -0.2f, 0, 1.0f);
                Stompsound(9.5F,-0.2F);

            }
        }

        if(this.getAttackState() == 4) {
            if (this.attackTicks == 18) {
                AreaAttack(9.0f,6.0F,270,1,0);
                this.playSound(ModSounds.STRONGSWING.get(), 1F, 1.0f);
                ScreenShake_Entity.ScreenShake(level(), this.position(), 15, 0.05f, 0, 10);
            }
            if (this.attackTicks == 36) {
                AreaAttack(9.0f,6.0F,270,1,0);
                this.playSound(ModSounds.STRONGSWING.get(), 1F, 1.0f);
                ScreenShake_Entity.ScreenShake(level(), this.position(), 15, 0.05f, 0, 10);
            }
            if (this.attackTicks == 65) {
                AreaAttack(10.0f,6.0F,45,1.25F,120);
                this.playSound(ModSounds.REMNANT_STOMP.get(), 1F, 1.0f);
                ScreenShake_Entity.ScreenShake(level(), this.position(), 15, 0.1f, 0, 20);
                Makeparticle(0.5f, 9.0f, 1.8f);
            }
        }
        if(this.getAttackState() == 6) {
            if (!this.level().isClientSide) {
                if (CMCommonConfig.Kobolediator.ignoreMobGriefing) {
                    ChargeBlockBreaking();
                } else {
                    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                        ChargeBlockBreaking();
                    }
                }

                if (this.tickCount % 4 == 0) {
                    DamageSource damagesource = this.damageSources().mobAttack(this);
                    for (LivingEntity Lentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.5D))) {
                        if (!isAlliedTo(Lentity) && !(Lentity instanceof Kobolediator_Entity) && Lentity != this) {
                            boolean flag = Lentity.hurt(damagesource, (float) ((float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.4F));
                            if (flag) {
                                if (Lentity.onGround()) {
                                    double d0 = Lentity.getX() - this.getX();
                                    double d1 = Lentity.getZ() - this.getZ();
                                    double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                                    float f = 1.5F;
                                    Lentity.push(d0 / d2 * f, 0.5F, d1 / d2 * f);
                                }
                            }
                        }
                    }
                }
            }
        }
        if(this.getAttackState() == 7) {
            if (this.attackTicks == 5) {
                AreaAttack(9.0f,6.0F,200,1.25F,120);
                this.playSound(ModSounds.STRONGSWING.get(), 1F, 1.0f);
                ScreenShake_Entity.ScreenShake(level(), this.position(), 15, 0.05f, 0, 10);
            }
        }

    }

@SuppressWarnings("removal")
  @SubscribeEvent
  static void onExperienceDrop(LivingExperienceDropEvent event) {
    // boost entity experience if they are under the effects of experienced
    LivingEntity entity = event.getEntity();
    MobEffectInstance instance = entity.getEffect(TinkerEffects.experienced.get());
    double multiplier = 1 + (instance != null ? instance.getAmplifier() : 0);

    // always add armor boost, unfortunately no good way to stop shield stuff here
    Player player = event.getAttackingPlayer();
    if (player != null) {
      multiplier += player.getAttributeValue(TinkerAttributes.EXPERIENCE_MULTIPLIER.get()) + ArmorStatModule.getStat(player, TinkerDataKeys.EXPERIENCE);
    }
    // if the target was killed by an experienced arrow, use that level
    TinkerDataCapability.Holder data = TinkerDataCapability.getData(entity);
    Float projectileBoost = data != null ? data.get(PROJECTILE_EXPERIENCE) : null;
    if (projectileBoost != null) {
      multiplier += projectileBoost;
    // being -1 means no projectile was involved, so boost by held tool
    } else if (player != null) {
      ToolStack tool = Modifier.getHeldTool(player, ModifierLootingHandler.getLootingSlot(player));
      if (tool != null) {
        multiplier += tool.getVolatileData().getFloat(EXPERIENCE);
      }
    }
    event.setDroppedExperience((int) (event.getDroppedExperience() * multiplier));
  }

