public void tick() {
        super.tick();
        if (localMimic != this.getPrevMimickedBlock()) {
            localMimic = this.getPrevMimickedBlock();
            colorShiftProgress = 0.0F;
        }
        if (localMimicState != this.getPrevMimicState()) {
            localMimicState = this.getPrevMimicState();
            transProgress = 0.0F;
        }

        if (this.isInWater()) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        BlockPos pos = AMBlockPos.fromCoords(this.getX(), this.getEyeY() - 1F, this.getZ());
        boolean ground = level().getBlockState(pos).isFaceSturdy(level(), pos, Direction.UP) && this.getMimicState() != MimicState.GUARDIAN || !this.isInWaterOrBubble() || this.isSitting();
        this.prevTransProgress = transProgress;
        this.prevColorShiftProgress = colorShiftProgress;
        this.prevGroundProgress = groundProgress;
        this.prevSitProgress = sitProgress;
        if (this.getPrevMimicState() != this.getMimicState() && transProgress < 5.0F) {
            transProgress += 0.25F;
        }
        if (this.getPrevMimicState() == this.getMimicState() && transProgress > 0F) {
            transProgress -= 0.25F;
        }
        if (getPrevMimickedBlock() != this.getMimickedBlock() && colorShiftProgress < 5.0F) {
            colorShiftProgress += 0.25F;
        }
        if (getPrevMimickedBlock() == this.getMimickedBlock() && colorShiftProgress > 0F) {
            colorShiftProgress -= 0.25F;
        }
        if (ground && groundProgress < 5F) {
            groundProgress += 0.5F;
        }
        if (!ground && groundProgress > 0F) {
            groundProgress -= 0.5F;
        }
        if (isSitting() && sitProgress < 5F) {
            sitProgress += 0.5F;
        }
        if (!isSitting() && sitProgress > 0F) {
            sitProgress -= 0.5F;
        }
        if (this.isInWaterOrBubble()) {
            float f2 = (float) -((float) this.getDeltaMovement().y * 3 * (double) Mth.RAD_TO_DEG);
            this.setXRot(f2);
        }
        if (camoCooldown > 0) {
            camoCooldown--;
        }
        if (mimicCooldown > 0) {
            mimicCooldown--;
        }
        if (stopMimicCooldown > 0) {
            stopMimicCooldown--;
        }
        if (this.isNoAi()) {
            this.setAirSupply(this.getMaxAirSupply());
        } else {
            if (this.isInWaterRainOrBubble() || this.getMainHandItem().getItem() == Items.WATER_BUCKET) {
                this.setMoistness(60000);
            } else {
                this.setMoistness(this.getMoistness() - 1);
                if (this.getMoistness() <= 0 && moistureAttackTime-- <= 0) {
                    this.setOrderedToSit(false);
                    this.hurt(damageSources().dryOut(), random.nextInt(2) == 0 ? 1.0F : 0F);
                    moistureAttackTime = 20;
                }
            }
        }
        if (camoCooldown <= 0 && random.nextInt(300) == 0) {
            mimicEnvironment();
            camoCooldown = this.getRandom().nextInt(2200) + 200;
        }
        if ((this.getMimicState() != MimicState.OVERLAY || this.getMimickedBlock() != null) && stopMimicCooldown == 0 && !this.isStopChange()) {
            this.setMimicState(MimicState.OVERLAY);
            this.setMimickedBlock(null);
            stopMimicCooldown = -1;
        }
        if (this.level().isClientSide && exclaimTime > 0) {
            exclaimTime--;
            if (exclaimTime == 0) {
                Entity e = level().getEntity(this.entityData.get(LAST_SCARED_MOB_ID));
                if (e != null && transProgress >= 5.0F) {
                    double d2 = this.random.nextGaussian() * 0.1D;
                    double d0 = this.random.nextGaussian() * 0.1D;
                    double d1 = this.random.nextGaussian() * 0.1D;
                    this.level().addParticle(AMParticleRegistry.SHOCKED.get(), e.getX(), e.getEyeY() + e.getBbHeight() * 0.15F + (double) (this.random.nextFloat() * e.getBbHeight() * 0.15F), e.getZ(), d0, d1, d2);
                }
            }
        }

        if (this.hasGuardianLaser()) {
            if (this.guardianLaserTime < 30) {
                ++this.guardianLaserTime;
            }
            LivingEntity livingentity = this.getGuardianLaser();
            if (livingentity != null && this.isInWaterOrBubble()) {
                this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
                this.getLookControl().tick();
                double d5 = this.getLaserAttackAnimationScale(0.0F);
                double d0 = livingentity.getX() - this.getX();
                double d1 = livingentity.getY(0.5D) - this.getEyeY();
                double d2 = livingentity.getZ() - this.getZ();
                double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                d0 = d0 / d3;
                d1 = d1 / d3;
                d2 = d2 / d3;
                double d4 = this.random.nextDouble();
                while (d4 < d3) {
                    d4 += 1.8D - d5 + this.random.nextDouble() * (1.7D - d5);
                    this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, 0.0D, 0.0D, 0.0D);
                }
                if (guardianLaserTime == 30) {
                    livingentity.hurt(this.damageSources().mobAttack(this), 5);
                    guardianLaserTime = 0;
                    this.entityData.set(UPGRADED_LASER_ENTITY_ID, -1);
                }
            }
        }
        if (!this.level().isClientSide && tickCount % 40 == 0) {
            this.heal(2);
        }
    /*if(!world.isRemote){
            if(ticksExisted % 80 == 0){
                mimicEnvironment();
            }else if(ticksExisted % 40 == 0){
                this.setMimicState(MimicState.OVERLAY);
                this.setMimickedBlock(null);
            }
        }*/
    }

@Override
    public void onEntityUpdate() {

        if (!world.isRemote) {
            if (this.getHealth() < 0 && !this.isDead) {
                this.setDead();
                if (this.world.getGameRules().getBoolean("doEntityDrops")) {
                    this.dropItems();
                    ItemStack recordItem = this.dataManager.get(RECORD_ITEM);
                    if (!recordItem.isEmpty()) {
                        this.entityDropItem(recordItem, 0);
                    }
                }
            }

        }

        for (int i = 0; i < this.seats.length; i++) {
            Entity e = this.getEntityInSeat(i);
            if(e != null && e instanceof EntityPlayerMP) {
                resetFlyTicks((EntityPlayerMP) e);
            }
        }

        if (this.getSpeed() == Speed.FAST) {
            this.allWheels.forEach(wheel -> this.createWheelParticles(wheel, true));
        }
        this.allWheels.forEach(this::createWheelParticles);

        if (shouldStopUpdates()) {
            super.onEntityUpdate();
            return;
        }
        if (!world.isRemote) {
            if (prevWorldTime != -1) {
                world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(0.1f),
                        this::canRunoverEntity).forEach(this::runOverEntity);
            }
        }
        if (this.isInWater()) {
            for (int i = 0; i < this.seats.length; i++) {
                Entity e = this.getEntityInSeat(i);
                if (e != null) {
                    e.attackEntityFrom(DamageSource.DROWN, 0.5f);
                }
            }
            this.setHealth(this.getHealth() - 0.25F);
        }
        if (previousPosition == null) {
            previousPosition = this.getPositionVector();
        }
        estimatedSpeed = this.getPositionVector().distanceTo(previousPosition)
                / (world.getTotalWorldTime() - prevWorldTime);
        previousPosition = this.getPositionVector();
        prevWorldTime = world.getTotalWorldTime();

        for (int i = 0; i < 4; i++) {
            List<WheelParticleData> markedRemoved = Lists.newArrayList();
            wheelDataList[i].forEach(wheel -> wheel.onUpdate(markedRemoved));
            markedRemoved.forEach(wheelDataList[i]::remove);
        }

        super.onEntityUpdate();

        this.allWheels.forEach(this::processWheel);

        Vector4d vec = wheeldata.carVector;
        this.backValue.setTarget(this.calculateWheelHeight(vec.y, false));
        this.frontValue.setTarget(this.calculateWheelHeight(vec.w, false));
        this.leftValue.setTarget(this.calculateWheelHeight(vec.z, true));
        this.rightValue.setTarget(this.calculateWheelHeight(vec.x, true));

        if (!this.world.isRemote) {
            this.updateHeal();
        }

        this.tickInterp();
        this.updateMotion();
        if (this.getPassengers().isEmpty() || !(this.getPassengers().get(0) instanceof EntityPlayer)) {
            this.setControlState((byte) 0);
        }
        if (this.world.isRemote) {
            this.handleControl();
        }
        this.applyMovement();
        this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
    }

@Override
    public void aiStep() {
        super.aiStep();
        prevJumpProgress = jumpProgress;
        if (this.getWormJumping() > 0 && jumpProgress < 5F) {
            jumpProgress++;
        }
        if (this.getWormJumping() == 0 && jumpProgress > 0F) {
            jumpProgress--;
        }
        if (this.isInSand() && this.horizontalCollision) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.05, 0));
        }
        if (this.getWormJumping() > 0) {
            float f2 = (float) -((float) this.getDeltaMovement().y * (double) (180F / (float) Math.PI));
            this.setXRot(f2);
            if (this.isInSand() || this.isOnGround()) {
                this.setWormJumping(this.getWormJumping() - 1);
            }
        }
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
        if (this.getTarget() != null && (!this.getTarget().isAlive() || !DragonUtils.isAlive(this.getTarget()))) {
            this.setTarget(null);
        }
        if (this.willExplode) {
            if (this.ticksTillExplosion == 0) {
                boolean b = !MinecraftForge.EVENT_BUS.post(new GenericGriefEvent(this, this.getX(), this.getY(), this.getZ()));
                if (b) {
                    level.explode(this.thrower, this.getX(), this.getY(), this.getZ(), 2.5F * this.getScale(), false, Explosion.BlockInteraction.DESTROY);
                }
                this.thrower = null;
            } else {
                this.ticksTillExplosion--;
            }
        }
        if (this.tickCount == 1) {
            initSegments(this.getScale());
        }
        if (isInSandStrict()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.08D, 0));
        }
        if (growthCounter > 1000 && this.getWormAge() < 5) {
            growthCounter = 0;
            this.setWormAge(Math.min(5, this.getWormAge() + 1));
            this.clearSegments();
            this.heal(15);
            this.setDeathWormScale(this.getDeathwormScale());
            if (level.isClientSide) {
                for (int i = 0; i < 10 * this.getScale(); i++) {
                    this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getSurface((int) Math.floor(this.getX()), (int) Math.floor(this.getY()), (int) Math.floor(this.getZ())) + 0.5F, this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                    /*
                    for (int j = 0; j < segments.length; j++) {
                        this.world.addParticle(ParticleTypes.HAPPY_VILLAGER, segments[j].getPosX() + (double) (this.rand.nextFloat() * segments[j].getWidth() * 2.0F) - (double) segments[j].getWidth(), this.getSurface((int) Math.floor(segments[j].getPosX()), (int) Math.floor(segments[j].getPosY()), (int) Math.floor(segments[j].getPosZ())) + 0.5F, segments[j].getPosZ() + (double) (this.rand.nextFloat() * segments[j].getWidth() * 2.0F) - (double) segments[j].getWidth(), this.rand.nextGaussian() * 0.02D, this.rand.nextGaussian() * 0.02D, this.rand.nextGaussian() * 0.02D);
                    }
                     */
                }
            }
        }
        if (this.getWormAge() < 5) {
            growthCounter++;
        }
        if (this.getControllingPassenger() != null && this.getTarget() != null) {
            this.getNavigation().stop();
            this.setTarget(null);
        }
        //this.faceEntity(this.getAttackTarget(), 10.0F, 10.0F);
           /* if (dist >= 4.0D * getRenderScale() && dist <= 16.0D * getRenderScale() && (this.isInSand() || this.onGround)) {
                this.setWormJumping(true);
                double d0 = this.getAttackTarget().getPosX() - this.getPosX();
                double d1 = this.getAttackTarget().getPosZ() - this.getPosZ();
                float leap = MathHelper.sqrt(d0 * d0 + d1 * d1);
                if ((double) leap >= 1.0E-4D) {
                    this.setMotion(this.getMotion().add(d0 / (double) leap * 0.5D, 0.15F, d1 / (double) leap * 0.5D));
                }
                this.setAnimation(ANIMATION_BITE);
            }*/
        if (this.getTarget() != null && this.distanceTo(this.getTarget()) < Math.min(4, 4D * getScale()) && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5) {
            float f = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue();
            this.getTarget().hurt(DamageSource.mobAttack(this), f);
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.4F, 0));
        }

    }

@Override
    public void aiStep() {
        super.aiStep();
        yBodyRot = getYRot();

        LivingEntity attackTarget = this.getTarget();
        if (singCooldown > 0) {
            singCooldown--;
            this.setSinging(false);
        }
        if (!level.isClientSide && attackTarget == null && !this.isAgressive()) {
            this.setSinging(true);
        }
        if (this.getAnimation() == ANIMATION_BITE && attackTarget != null && this.distanceToSqr(attackTarget) < 7D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        }
        if (this.getAnimation() == ANIMATION_PULL && attackTarget != null && this.distanceToSqr(attackTarget) < 16D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            double attackmotionX = (Math.signum(this.getX() - attackTarget.getX()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;
            double attackmotionY = (Math.signum(this.getY() - attackTarget.getY() + 1) * 0.5D - attackTarget.getDeltaMovement().y) * 0.100000000372529 * 5;
            double attackmotionZ = (Math.signum(this.getZ() - attackTarget.getZ()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;

            attackTarget.setDeltaMovement(attackTarget.getDeltaMovement().add(attackmotionX, attackmotionY, attackmotionZ));
            // float angle = (float) (Math.atan2(attackTarget.getDeltaMovement().z, attackTarget.getDeltaMovement().x) * 180.0D / Math.PI) - 90.0F;
            // entity.moveForward = 0.5F;
            double d0 = this.getX() - attackTarget.getX();
            double d2 = this.getZ() - attackTarget.getZ();
            double d1 = this.getY() - 1 - attackTarget.getY();
            double d3 = Math.sqrt((float) (d0 * d0 + d2 * d2));
            float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
            float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
            attackTarget.setXRot(updateRotation(attackTarget.getXRot(), f1, 30F));
            attackTarget.setYRot(updateRotation(attackTarget.getYRot(), f, 30F));
        }
        if (level.isClientSide) {
            tail_buffer.calculateChainSwingBuffer(40, 10, 2.5F, this);
        }
        if (this.isAgressive()) {
            ticksAgressive++;
        } else {
            ticksAgressive = 0;
        }
        if (ticksAgressive > 300 && this.isAgressive() && attackTarget == null && !level.isClientSide) {
            this.setAggressive(false);
            this.ticksAgressive = 0;
            this.setSinging(false);
        }

        if (this.isInWater() && !this.isSwimming()) {
            this.setSwimming(true);
        }
        if (!this.isInWater() && this.isSwimming()) {
            this.setSwimming(false);
        }
        LivingEntity target = getTarget();
        boolean pathOnHighGround = this.isPathOnHighGround() || !level.isClientSide && target != null && !target.isInWater();
        if (target == null || !target.isInWater() && !target.isInWater()) {
            if (pathOnHighGround && this.isInWater()) {
                jumpFromGround();
                doWaterSplashEffect();
            }
        }
        if ((this.isInWater() && !pathOnHighGround) && this.isLandNavigator) {
            switchNavigator(false);
        }
        if ((!this.isInWater() || pathOnHighGround) && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (target instanceof Player && ((Player) target).isCreative()) {
            this.setTarget(null);
            this.setAggressive(false);
        }
        if (target != null && !this.isAgressive()) {
            this.setAggressive(true);
        }
        boolean singing = isActuallySinging() && !this.isAgressive() && !this.isInWater() && onGround;
        if (singing && singProgress < 20.0F) {
            singProgress += 1F;
        } else if (!singing && singProgress > 0.0F) {
            singProgress -= 1F;
        }
        boolean swimming = isSwimming();
        if (swimming && swimProgress < 20.0F) {
            swimProgress += 1F;
        } else if (!swimming && swimProgress > 0.0F) {
            swimProgress -= 0.5F;
        }
        if (!level.isClientSide && !EntityGorgon.isStoneMob(this) && this.isActuallySinging()) {
            updateLure();
            checkForPrey();

        }
        if (!level.isClientSide && EntityGorgon.isStoneMob(this) && this.isSinging()) {
            this.setSinging(false);
        }
        if (isActuallySinging() && !this.isInWater()) {
            if (this.getRandom().nextInt(3) == 0) {
                yBodyRot = getYRot();
                if (this.level.isClientSide) {
                    float radius = -0.9F;
                    float angle = (0.01745329251F * this.yBodyRot) - 3F;
                    double extraX = radius * Mth.sin((float) (Math.PI + angle));
                    double extraY = 1.2F;
                    double extraZ = radius * Mth.cos(angle);
                    IceAndFire.PROXY.spawnParticle(EnumParticles.Siren_Music, this.getX() + extraX + this.random.nextFloat() - 0.5, this.getY() + extraY + this.random.nextFloat() - 0.5, this.getZ() + extraZ + this.random.nextFloat() - 0.5, 0, 0, 0);
                }
            }
        }
        if (this.isActuallySinging() && !this.isInWater() && this.tickCount % 200 == 0) {
            this.playSound(IafSoundRegistry.SIREN_SONG, 2, 1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
  public InteractionResult afterBlockUse(IToolStackView tool, ModifierEntry modifier, UseOnContext context, InteractionSource source) {
    if (!tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
      FluidStack fluid = TANK_HELPER.getFluid(tool);
      if (!fluid.isEmpty()) {
        FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
        if (recipe.hasBlockEffects()) {
          Player player = context.getPlayer();
          Level world = context.getLevel();

          // cooldown based on draw speed, works similarly enough to attack speed
          // applied before we do the effect to block recursive calls, notably ender might cause that
          if (player != null) {
            player.getCooldowns().addCooldown(tool.getItem(), (int)(20 / ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.DRAW_SPEED)));
          }

          if (!world.isClientSide) {
            float level = strength.compute(modifier);
            int numTargets = 0;
            BlockHitResult hit = context.getHitResult();
            BlockState state = world.getBlockState(hit.getBlockPos());
            int consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(hit), FluidAction.EXECUTE);
            if (consumed > 0) {
              numTargets++;
              spawnParticles(world, hit, fluid);
              fluid.shrink(consumed);
            }

            // AOE selection logic, get boosted from expanded
            if (!fluid.isEmpty()) {
              for (BlockPos offset : tool.getHook(ToolHooks.AOE_ITERATOR).getBlocks(tool, context, state, AOEMatchType.TRANSFORM)) {
                BlockHitResult offsetHit = Util.offset(hit, offset);
                consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(offsetHit), FluidAction.EXECUTE);
                if (consumed > 0) {
                  numTargets++;
                  spawnParticles(world, offsetHit, fluid);
                  fluid.shrink(consumed);
                  // stop if we run out of fluid
                  if (fluid.isEmpty()) {
                    break;
                  }
                }
              }
            }

            // update fluid in tool and damage tool
            if (ModifierUtil.consumesResources(player)) {
              if (numTargets > 0) {
                TANK_HELPER.setFluid(tool, fluid);
              }

              // damage the tool, we charge for the multiplier and for the number of targets hit
              ItemStack stack = context.getItemInHand();
              if (ToolDamageUtil.damage(tool, Mth.ceil(numTargets * level), player, stack, modifier.getId()) && player != null) {
                player.broadcastBreakEvent(source.getSlot(context.getHand()));
              }
            }
          }
          return InteractionResult.SUCCESS;
        }
      }
    }
    return InteractionResult.PASS;
  }

@Override
    public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
        if (!(livingEntity instanceof Player player))
            return;

        if (player.isPassenger())
            player.stopRiding();

        if (level.isClientSide())
            return;

        var path = new ArrayList<>(stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()));

        if (path.size() < 2) {
            stack.set(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        var lastIndex = path.size() - 1;
        var cursor = (double) stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

        if (cursor < 0D || cursor > lastIndex)
            cursor = lastIndex;

        var speed = 1.05D + Math.min(3D, Math.max(0, player.getTicksUsingItem() - 1) * 0.01D);

        cursor = Math.max(0D, cursor - speed);

        var segment = Mth.floor(cursor);

        var t = (float) (cursor - segment);

        var p1 = path.get(segment);
        var p2 = path.get(Math.min(lastIndex, segment + 1));

        if (player instanceof ServerPlayer serverPlayer) {
            var p0 = path.get(Math.max(0, segment - 1));
            var p3 = path.get(Math.min(lastIndex, segment + 2));
            var currentDimension = serverPlayer.level().dimension().location().toString();
            var p1Dimension = p1.dimension().isBlank() ? currentDimension : p1.dimension();
            var p2Dimension = p2.dimension().isBlank() ? currentDimension : p2.dimension();

            if (!p1Dimension.equals(currentDimension)) {
                var dimensionId = ResourceLocation.tryParse(p1Dimension);

                if (dimensionId != null) {
                    var key = ResourceKey.create(Registries.DIMENSION, dimensionId);
                    var targetLevel = serverPlayer.server.getLevel(key);

                    if (targetLevel != null) {
                        serverPlayer.teleportTo(targetLevel, p1.x(), p1.y(), p1.z(), p1.yRot(), p1.xRot());
                        serverPlayer.setPortalCooldown();
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                        serverPlayer.fallDistance = 0F;

                        setRewindCursor(stack, -1D);
                        setPath(stack, path);

                        player.stopUsingItem();

                        return;
                    }
                }
            }

            double targetX;
            double targetY;
            double targetZ;

            float targetYRot;
            float targetXRot;

            if (!p1Dimension.equals(p2Dimension)) {
                var point = p1Dimension.equals(currentDimension) ? p1 : p2;

                targetX = point.x();
                targetY = point.y();
                targetZ = point.z();

                targetYRot = point.yRot();
                targetXRot = point.xRot();
            } else {
                targetX = Mth.catmullrom(t, (float) p0.x(), (float) p1.x(), (float) p2.x(), (float) p3.x());
                targetY = Mth.catmullrom(t, (float) p0.y(), (float) p1.y(), (float) p2.y(), (float) p3.y());
                targetZ = Mth.catmullrom(t, (float) p0.z(), (float) p1.z(), (float) p2.z(), (float) p3.z());

                var targetRotation = this.interpolateLookRotationCatmullrom(t, p0, p1, p2, p3);

                targetYRot = targetRotation.yRot();
                targetXRot = targetRotation.xRot();
            }

            var clampedXRot = Mth.clamp(targetXRot, -90F, 90F);

            if (serverPlayer.distanceToSqr(targetX, targetY, targetZ) > 16D * 16D)
                serverPlayer.teleportTo((ServerLevel) serverPlayer.level(), targetX, targetY, targetZ, targetYRot, clampedXRot);
            else
                serverPlayer.moveTo(targetX, targetY, targetZ, targetYRot, clampedXRot);

            serverPlayer.setYHeadRot(targetYRot);
            serverPlayer.yHeadRotO = targetYRot;
            serverPlayer.yBodyRot = targetYRot;
            serverPlayer.yBodyRotO = targetYRot;
            serverPlayer.setDeltaMovement(Vec3.ZERO);
            serverPlayer.fallDistance = 0F;
        }

        if (level instanceof ServerLevel) {
            var random = level.random;
            var previousCenter = new Vec3(player.xOld, player.yOld + player.getBbHeight() * 0.55D, player.zOld);
            var currentCenter = new Vec3(player.getX(), player.getY() + player.getBbHeight() * 0.55D, player.getZ());
            var movement = currentCenter.subtract(previousCenter);
            var distance = movement.length();
            var spawnCount = Mth.clamp((int) Math.ceil(distance / 0.125D), 2, 5);
            var phase = player.tickCount * 0.45D;

            for (int step = 0; step <= spawnCount; step++) {
                var progress = spawnCount == 0 ? 0D : (double) step / spawnCount;
                var center = previousCenter.add(movement.scale(progress));
                var subPhase = phase + progress * 0.35D;

                for (int i = 0; i < 6; i++) {
                    var angle = subPhase + i * (Math.PI * 2D / 6D);
                    var radius = 0.45D + 0.12D * Math.sin(subPhase * 1.6D + i);

                    var px = center.x + Math.cos(angle) * radius;
                    var pz = center.z + Math.sin(angle) * radius;
                    var py = center.y + Math.sin(angle * 1.7D) * 0.2D;

                    var hue = (float) ((0.58D + subPhase * 0.025D + i * 0.06D) % 1D);
                    var color = Color.getHSBColor(hue, 0.6F + random.nextFloat() * 0.25F, 1F);

                    var inward = new Vec3(center.x - px, center.y - py, center.z - pz).scale(0.1D);
                    var swirl = new Vec3(-Math.sin(angle), 0D, Math.cos(angle)).scale(0.03D);

                    var velocity = inward.add(swirl).add(0D, 0.01D + random.nextDouble() * 0.01D, 0D);

                    NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat() * 0.15F, 20 + random.nextInt(10), 0.975F), new Vector3f((float) px, (float) py, (float) pz),
                            new Vector3f((float) velocity.x, (float) velocity.y, (float) velocity.z)), player);
                }
            }
        }

        var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

        if (ability.canPlayerUse(player)) {
            this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "rewind", 1D / 20D);

            ability.getStatisticData().getMetricData("rewind_duration").addValue(1D / 20D);
        }

        if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
            var rewindHealth = Mth.lerp(t, p1.health(), p2.health());
            var currentHealth = player.getHealth();
            var targetHealth = Math.min(player.getMaxHealth(), Math.max(currentHealth, rewindHealth));

            if (targetHealth > currentHealth) {
                player.setHealth(targetHealth);

                if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
                    this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "health_rewind", targetHealth - currentHealth);
                    ability.getStatisticData().getMetricData("health_restored").addValue(targetHealth - currentHealth);
                }
            }
        }

        while (path.size() > 2 && cursor <= path.size() - 2)
            path.removeLast();

        if (cursor <= 0D) {
            setRewindCursor(stack, -1D);
            setPath(stack, path);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        setRewindCursor(stack, cursor);
        setPath(stack, path);
    }

@Override
    public void tick() {
        super.tick();
        this.prevRaiseArmsAmount = raiseArmsAmount;
        this.prevLeftArmAmount = raiseLeftArmAmount;
        this.prevShootTongueAmount = shootTongueAmount;
        this.prevLastTongueDistance = lastTongueDistance;
        if (this.getAnimation() == ANIMATION_SMASH && raiseArmsAmount < 5F) {
            raiseArmsAmount++;
        }
        if (this.getAnimation() != ANIMATION_SMASH && raiseArmsAmount > 0F) {
            raiseArmsAmount--;
        }
        if (this.raisingLeftArm() && raiseLeftArmAmount < 5F) {
            raiseLeftArmAmount++;
        }
        if (!this.raisingLeftArm() && raiseLeftArmAmount > 0F) {
            raiseLeftArmAmount--;
        }
        if (this.getLickTicks() > 0 && shootTongueAmount < 10F) {
            shootTongueAmount++;
        }
        if (this.getLickTicks() <= 0 && shootTongueAmount > 0F) {
            shootTongueAmount--;
        }
        if (!level().isClientSide && this.hasBarrel()) {
            if (this.getAnimation() == ANIMATION_DRINK_BARREL && this.getAnimationTick() >= 60) {
                this.setHasBarrel(false);
                this.heal(10);
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 400, 4));
            }
            if (this.getAnimation() == ANIMATION_THROW_BARREL && this.getAnimationTick() >= 15) {
                LivingEntity attackTarget = this.getTarget();
                if (attackTarget != null && attackTarget.isAlive()) {
                    this.setHasBarrel(false);
                    Vec3 hand = new Vec3(0.65F, -0.3F, 0.9F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYHeadRot() * ((float) Math.PI / 180F));
                    Vec3 handOnBody = this.getEyePosition().add(hand);
                    ThrownWasteDrumEntity wasteDrumEntity = ACEntityRegistry.THROWN_WASTE_DRUM.get().create(level());
                    wasteDrumEntity.setPos(handOnBody);
                    Vec3 toss = attackTarget.getEyePosition().subtract(handOnBody).multiply(0.35F, 0, 0.35F).add(0, 0.4, 0);
                    wasteDrumEntity.setYRot(-((float) Mth.atan2(toss.x, toss.z)) * 180.0F / (float) Math.PI);
                    level().addFreshEntity(wasteDrumEntity);
                    wasteDrumEntity.setDeltaMovement(toss.normalize().scale(attackTarget.distanceTo(this) * 0.2F));
                }
            }
        }
        Entity tongueTarget = this.getTongueTarget();
        if (level().isClientSide) {
            if (tongueTarget != null && tongueTarget.isAlive()) {
                lastTongueDistance = this.distanceTo(tongueTarget) - 0.5F;
            }
        } else {
            LivingEntity attackTarget = this.getTarget();
            if (this.getLickTicks() > 0) {
                this.setLickTicks(this.getLickTicks() - 1);
                if (attackTarget != null && attackTarget.isAlive() && this.hasLineOfSight(attackTarget) && attackTarget.distanceTo(this) < 20) {
                    this.setTongueTargetId(attackTarget.getId());
                    this.lookAt(EntityAnchorArgument.Anchor.EYES, attackTarget.getEyePosition());
                } else {
                    this.setTongueTargetId(-1);
                }
            } else {
                this.setTongueTargetId(-1);
            }
        }
        if (tongueTarget instanceof LivingEntity living) {
            if (this.shootTongueAmount >= 5F) {
                postAttackEffect(living);
                tongueTarget.hurt(damageSources().mobAttack(this), 4);
                living.knockback(0.3D, living.getX() - this.getX(), tongueTarget.getZ() - this.getZ());
                this.setLickTicks(0);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void curioTick(SlotContext slotContext, ItemStack stack) {
        super.curioTick(slotContext, stack);

        if (!(slotContext.entity() instanceof LivingEntity entity))
            return;

        var level = entity.level();
        var belowState = level.getBlockState(entity.getBlockPosBelowThatAffectsMyMovement());

        var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");
        var forcedFall = this.isForcedFall(stack);
        var onGround = entity.onGround();
        var glitchEnabled = this.isGlitchEnabled(entity, stack);

        if (!glitchEnabled) {
            this.setStandTicks(stack, 0);
            this.setForcedFall(stack, false);
            this.setPhaseTicks(stack, 0);
        } else {
            var stable = onGround && belowState.isAir() && !isMovingHorizontally(entity) && !entity.isShiftKeyDown();

            if (!forcedFall) {
                if (stable) {
                    this.addStandTicks(stack, 1);

                    if (this.getStandTicks(stack) >= (int) Math.max(1D, ability.getStatData("stability_time").getValue() * 20D)) {
                        this.setForcedFall(stack, true);
                        this.setForcedFallStartY(stack, entity.getY());
                        this.setStandTicks(stack, 0);

                        if (!level.isClientSide())
                            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch").getStatisticData().getMetricData("forced_falls").addValue(1);
                    }
                } else {
                    this.setStandTicks(stack, 0);
                }
            }

            if (this.isForcedFall(stack) && onGround && !belowState.isAir() && entity.fallDistance <= 0F)
                this.setForcedFall(stack, false);
        }

        if (level.isClientSide())
            return;

        var gameTime = level.getGameTime();

        if (glitchEnabled && belowState.isAir() && this.canCollideWithAirLike(entity, stack) && this.getLastAirTick(stack) != gameTime) {
            this.setLastAirTick(stack, gameTime);

            ability.getStatisticData().getMetricData("solid_air_duration").addValue(1D / 20D);

            if (isMovingHorizontally(entity))
                this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "air_walking", 1D / 20D);
        }

        var illusion = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("illusion");

        if (illusion.canPlayerUse(entity) && illusion.getMode().equals("enabled")) {
            if (this.getIllusionCooldown(stack) > 0) {
                this.addIllusionCooldown(stack, -1);
            } else {
                var look = entity.getLookAngle().multiply(1D, 0D, 1D);
                var backward = look.lengthSqr() > 1.0E-6D ? look.normalize().scale(-0.95D) : Vec3.ZERO;
                var spawnPos = entity.position().add(backward);
                var copy = new GlitchyIllusionEntity(RelicsEntities.GLITCHY_ILLUSION.get(), level);

                copy.setOwner(entity);
                copy.setLifetime((int) Math.max(1D, illusion.getStatData("duration").getValue() * 20D));
                copy.setStunDuration((int) Math.max(1D, illusion.getStatData("stun").getValue() * 20D));
                copy.setStunRadius((float) Math.max(0D, illusion.getStatData("stun_radius").getValue()));
                copy.setFlawless(this.getRelicData(entity, stack).isVisuallyFlawless());
                copy.setStack(stack);
                copy.setPos(spawnPos.x(), spawnPos.y(), spawnPos.z());
                copy.setYRot(entity.getYRot());
                copy.setXRot(entity.getXRot());
                copy.setYHeadRot(entity.getYHeadRot());
                copy.setSnapshotXRot(entity.getXRot());
                copy.setPose(entity.getPose());

                if (level.getEntitiesOfClass(GlitchyIllusionEntity.class, copy.getBoundingBox().inflate(0.05D)).isEmpty()) {
                    level.addFreshEntity(copy);

                    this.setIllusionCooldown(stack, (int) Math.max(1D, illusion.getStatData("interval").getValue() * 20D));
                    illusion.getStatisticData().getMetricData("illusions").addValue(1);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("illusion", "creation", 1);
                }
            }
        } else {
            this.setIllusionCooldown(stack, 0);
        }

        if (glitchEnabled && ability.getRankModifierData("phase").isEnabled()) {
            var eyesInsideBlock = areEyesInsideCollidingBlock(entity);

            if (!eyesInsideBlock) {
                this.setLastSafePosition(stack, entity.position());
                this.setPhaseTicks(stack, 0);
            } else {
                if (this.getLastPhaseTick(stack) != gameTime) {
                    this.setLastPhaseTick(stack, gameTime);

                    ability.getStatisticData().getMetricData("phase_duration").addValue(1D / 20D);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "phasing", 1D / 20D);
                }

                if (!level.isClientSide())
                    entity.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 5, 0, false, false));

                this.addPhaseTicks(stack, 1);

                var limit = Math.max(1, (int) Math.round(ability.getStatData("phase_time").getValue() * 20D));

                if (this.getPhaseTicks(stack) > limit) {
                    var pos = this.getLastSafePosition(stack);

                    if (entity instanceof ServerPlayer serverPlayer) {
                        serverPlayer.teleportTo(serverPlayer.serverLevel(), pos.x(), pos.y(), pos.z(), entity.getYRot(), entity.getXRot());
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                    } else {
                        entity.teleportTo(pos.x(), pos.y(), pos.z());
                        entity.setDeltaMovement(Vec3.ZERO);
                    }

                    level.playSound(null, BlockPos.containing(pos), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1F, 1F);

                    this.setPhaseTicks(stack, 0);
                    ability.getStatisticData().getMetricData("phase_rollbacks").addValue(1);
                }
            }
        }
    }

@Override
    protected void tick() {
        if (getWorld().isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 5);
        } else {
            if (getWorld().getGameTime() % 100 == 0) {
                List<LivingEntity> entities = getWorld().getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5));
                Optional<LivingEntity> player = entities.stream().filter(e -> e instanceof Player).findFirst();

                boolean didWorkOnce = false;
                for (LivingEntity a : entities) {
                    if (a instanceof ZombieVillager zv) {
                        zv.startConverting(player.map(Entity::getUUID).orElse(null), 0);
                        didWorkOnce = true;
                        continue;
                    }

                    if (a.getHealth() < a.getMaxHealth() || a.isInvertedHealAndHarm()) {
                        if (a.isInvertedHealAndHarm()) {
                            FakePlayer player1 = ANFakePlayer.getPlayer((ServerLevel) getWorld());
                            a.hurt(getWorld().damageSources().playerAttack(player1), 10.0f);
                        } else {
                            a.heal(10.0f);
                        }
                        didWorkOnce = true;
                    }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            }
        }
    }

@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		/* Default Ritual Stuff */
		Level world = masterRitualStone.getWorldObj();
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();
		BlockPos pos = masterRitualStone.getMasterBlockPos();

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		int maxEffects = currentEssence / getRefreshCost();
		int totalEffects = 0;

		/* Default will augment stuff */
		List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();
		DemonWillHolder holder = WorldDemonWillHandler.getWillHolder(world, pos);

		double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
		double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);
		double destructiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DESTRUCTIVE, willConfig);
		double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
		double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);

		double rawDrained = 0;
		double corrosiveDrained = 0;
		double destructiveDrained = 0;
		double steadfastDrained = 0;
		double vengefulDrained = 0;

		/* Actual ritual stuff begins here */
		AreaDescriptor groundingRange = masterRitualStone.getBlockRange(GROUNDING_RANGE);
		List<LivingEntity> entities = world.getEntitiesOfClass(LivingEntity.class, groundingRange.getAABB(pos));
		for (LivingEntity entity : entities)
		{
			if (totalEffects >= maxEffects)
			{
				break;
			}

			if (entity instanceof Player && ((Player) entity).isCreative())
				continue;

			totalEffects++;

			if (entity instanceof Player)
			{
				/* Raw will effect: Affects players */
				if (world.getGameTime() % 10 == 0)
				{
					if (rawWill >= willDrain)
					{

						rawDrained += willDrain;

						double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

						corrosiveDrained += drainagePlayer[0];
						destructiveDrained += drainagePlayer[1];
						vengefulDrained += drainagePlayer[2];
					}
				}
			} else if (entity.canChangeDimensions())
			{
				if (world.getGameTime() % 10 == 0)
				{
					double[] drainageEntity = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainageEntity[0];
					destructiveDrained += drainageEntity[1];
					vengefulDrained += drainageEntity[2];
				}
			} else if (!entity.canChangeDimensions())
			{
				/*
				 * Steadfast will effect: Affects bosses (some bosses, like the wither, have a
				 * restriction to motion modification, others, like the Ender Dragon, don't do
				 * potions)
				 */
				if (steadfastWill >= willDrain)
				{
					if (entity instanceof WitherBoss || entity instanceof EnderDragon)
						entity.move(MoverType.SELF, new Vec3(0, -0.05, 0)); // to work on Wither and EnderDragon
																				// without
					// interfering with other mod author's decisions
					// (looking at you, Vazkii)

					steadfastDrained += willDrain / 10f;

					double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainagePlayer[0];
					destructiveDrained += drainagePlayer[1];
					vengefulDrained += drainagePlayer[2];
				}
			}
		}

		if (rawDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawDrained, true);
		if (corrosiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.CORROSIVE, corrosiveDrained, true);
		if (destructiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DESTRUCTIVE, destructiveDrained, true);
		if (steadfastDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, steadfastDrained, true);
		if (vengefulDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.VENGEFUL, vengefulDrained, true);

		masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost() * totalEffects));
	}

@Override
    public void tickServer() {
        super.tickServer();

        if (getMinigun().getAttackTarget() == null && rsController.shouldRun()) {
            getMinigun().setSweeping(true);
            if ((nonNullLevel().getGameTime() & 0xF) == 0) {
                List<LivingEntity> entities = nonNullLevel().getEntitiesOfClass(LivingEntity.class, getTargetingBoundingBox(), entitySelector);
                if (!entities.isEmpty()) {
                    entities.sort(new EntityDistanceComparator(getBlockPos()));
                    getMinigun().setAttackTarget(entities.getFirst());
                    targetEntityId = getMinigun().getAttackTarget().getId();
                } else if (targetEntityId > 0) {
                    getMinigun().setReturning(true);
                    targetEntityId = -1;
                }
            }
        } else {
            getMinigun().setSweeping(false);
        }
        LivingEntity target = getMinigun().getAttackTarget();
        if (target != null) {
            if (rsController.shouldRun() && entitySelector.test(target)) {
                if ((nonNullLevel().getGameTime() & 0x7) == 0) {
                    // Make sure any knockback has the right direction.
                    getFakePlayer().setPos(getBlockPos().getX() + 0.5, getBlockPos().getY() + 0.5, getBlockPos().getZ() + 0.5);
                    if (getMinigun().tryFireMinigun(target).ammoUsedUp()) {
                        clearEmptyAmmo();
                    }
                }
            } else {
                getMinigun().setAttackTarget(null);
                getMinigun().minigunYaw = idleYaw;
                targetEntityId = -1;
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (!this.isInWaterOrBubble() && !this.hasEffect(ACEffectRegistry.BUBBLED.get())) {
            this.addEffect(new MobEffectInstance(ACEffectRegistry.BUBBLED.get(), 200));
        }
        if (this.isInWaterOrBubble() && this.hasEffect(ACEffectRegistry.BUBBLED.get())) {
            this.removeEffect(ACEffectRegistry.BUBBLED.get());
        }
        isMageInWater = this.isInWaterOrBubble();
        if (this.getAnimation() == ANIMATION_SPIN) {
            this.setDeltaMovement(this.getDeltaMovement().scale(0.6F));
            LivingEntity target = this.getTarget();
            if (target != null) {
                Vec3 vec = target.position().subtract(this.position()).normalize();
                this.setDeltaMovement(this.getDeltaMovement().add(vec.scale(0.1)));
            }
            if (this.getAnimationTick() % 6 == 0) {
                AABB bashBox = this.getBoundingBox().inflate(2.0D, 0, 2.0D);
                for (LivingEntity entity : DeepOneMageEntity.this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                    if (!isAlliedTo(entity) && !(entity instanceof DeepOneBaseEntity)) {
                        checkAndDealMeleeDamage(entity, 0.4F, 1.0F);
                    }
                }

            }
        }
        if (this.getAnimation() == ANIMATION_ATTACK) {
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                if (this.getAnimationTick() == 16) {
                    useMagicAttack(target);
                } else if (this.getAnimationTick() < 16) {
                    this.level().broadcastEntityEvent(this, (byte) 68);
                }
                this.getLookControl().setLookAt(target.getX(), target.getEyeY(), target.getZ(), 180.0F, 10.0F);
            }
        }
        if (spinCooldown > 0) {
            spinCooldown--;
        }
        if (rangedCooldown > 0) {
            rangedCooldown--;
        }
    }

@Override
    public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (!this.level().isClientSide) {
            if (this.getAnimation() == NO_ANIMATION && (this.getTarget() == null || !this.getTarget().isAlive())) {
                if (this.getDeltaMovement().lengthSqr() < 0.03D && (getRandom().nextInt(500) == 0 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK))) {
                    this.setAnimation(ANIMATION_EAT_GRASS);
                } else if (getRandom().nextInt(200) == 0) {
                    this.setAnimation(ANIMATION_FLICK_EARS);
                }
            }
            if (this.getAnimation() == ANIMATION_EAT_GRASS && this.getAnimationTick() == 30 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)) {
                BlockPos down = this.blockPosition().below();
                this.level().levelEvent(2001, down, Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
                this.level().setBlock(down, Blocks.DIRT.defaultBlockState(), 2);
                this.heal(10);
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                this.setAngry(this.distanceTo(target) < 20);
                double dist = this.distanceTo(target);
                if (hasLineOfSight(target)) {
                    this.lookAt(target, 30, 30);
                    this.yBodyRot = this.getYRot();
                }
                if (dist < this.getBbWidth() + 3.0F) {
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(random.nextBoolean() ? ANIMATION_SLASH : ANIMATION_FLING);
                    }
                    if(dist < this.getBbWidth() + 1.5F && this.hasLineOfSight(target)){
                        if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 8) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, 0, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, 0, 0.5F);
                                }
                            }
                        }
                        if (this.getAnimation() == ANIMATION_SLASH && (this.getAnimationTick() >= 9 && this.getAnimationTick() <= 11 || this.getAnimationTick() >= 19 && this.getAnimationTick() <= 21)) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, this.getAnimationTick() <= 15 ? -90 : 90, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, this.getAnimationTick() <= 15 ? -90 : 90, 0.5F);
                                }
                            }
                        }
                    }
                }
            }else{
                this.setAngry(false);
            }
        }
    }

public void tick() {
        super.tick();
        prevRunProgress = runProgress;
        prevLeapProgress = leapProgress;
        prevRelaxedProgress = relaxedProgress;
        prevHideProgress = hideProgress;
        prevTailYaw = tailYaw;
        float headPuzzleRot = getPuzzledHeadRot();
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if (isLeaping() && leapProgress < 5F) {
            leapProgress++;
        }
        if (!isLeaping() && leapProgress > 0F) {
            leapProgress--;
        }
        if (getRelaxedFor() > 0 && relaxedProgress < 20F) {
            relaxedProgress++;
        }
        if (getRelaxedFor() <= 0 && relaxedProgress > 0F) {
            relaxedProgress--;
        }
        if (getHideFor() > 0 && hideProgress < 20F) {
            hideProgress++;
        }
        if (getHideFor() <= 0 && hideProgress > 0F) {
            hideProgress--;
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
        }
        if (isElder() && !hasElderAttributes) {
            hasElderAttributes = true;
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(32.0D);
            this.getAttribute(Attributes.ARMOR).setBaseValue(5.0D);
            this.heal(36.0F);
        }
        if (!isElder() && hasElderAttributes) {
            hasElderAttributes = false;
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(24.0D);
            this.getAttribute(Attributes.ARMOR).setBaseValue(0.0D);
            this.heal(28.0F);
        }
        if (this.tickCount % (this.getHideFor() > 0 ? 15 : 100) == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (!level().isClientSide) {
            puzzledTick(headPuzzleRot);
            if (isStillEnough() && random.nextInt(100) == 0 && this.getAnimation() == NO_ANIMATION && this.getRelaxedFor() <= 0 && !this.isDancing()) {
                Animation idle;
                float rand = random.nextFloat();
                if (rand < 0.45F) {
                    idle = ANIMATION_SCRATCH_1;
                } else if (rand < 0.9F) {
                    idle = ANIMATION_SCRATCH_2;
                } else {
                    idle = ANIMATION_SHAKE;
                }
                this.setAnimation(idle);
            }
            if (fleeTicks > 0) {
                fleeTicks--;
            }
            if (this.isLeaping()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(1.1F, 1, 1.1F));
            }
        }
        if (this.getAnimation() == ANIMATION_CALL_1 && this.getAnimationTick() == 5 || this.getAnimation() == ANIMATION_CALL_2 && this.getAnimationTick() == 4) {
            actuallyPlayAmbientSound();
        }
        if (!level().isClientSide) {
            if (eatHeldItemIn > 0) {
                eatHeldItemIn--;
            } else if (canTargetItem(this.getMainHandItem())) {
                ItemStack stack = this.getMainHandItem();
                this.level().broadcastEntityEvent(this, (byte) 45);
                this.heal(5);
                if (stack.is(ACItemRegistry.DINOSAUR_NUGGET.get()) && justLootedChest) {
                    this.setRelaxedForTime(200 + random.nextInt(200));
                }
                if (!this.level().isClientSide) {
                    stack.shrink(1);
                }
                justLootedChest = false;
            }
            if (getRelaxedFor() > 0) {
                this.setRelaxedForTime(this.getRelaxedFor() - 1);
            }
            if (getHideFor() > 0) {
                this.setHideFor(this.getHideFor() - 1);
            }
        }
        LivingEntity target = this.getTarget();
        if (target != null && target.isAlive() && !(target instanceof Player player && player.isCreative())) {
            if (this.isElder()) {
                PackAnimal leader = this;
                while (leader.getAfterPackMember() != null) {
                    leader = leader.getAfterPackMember();
                    if(!((VallumraptorEntity) leader).isAlliedTo(target)){
                        ((VallumraptorEntity) leader).setTarget(target);
                    }
                }
            }
            if (this.getHealth() < this.getMaxHealth() * 0.45F && this.isTame() && this.getHideFor() <= 0) {
                int i = 80 + random.nextInt(40);
                this.setHideFor(i);
                this.fleeFromPosition = target.position();
                this.fleeTicks = i;
                if (target instanceof Mob mob) {
                    mob.setTarget(null);
                    mob.setLastHurtByMob(null);
                    mob.setLastHurtMob(null);
                }
            }
            if (target instanceof GrottoceratopsEntity && (tickCount + this.getId()) % 20 == 0 && getPackSize() < 4 && !this.isTame()) {
                this.fleeFromPosition = target.position();
                this.fleeTicks = 100 + random.nextInt(100);
                this.setTarget(null);
                this.setLastHurtByMob(null);
            }
        }
        tailYaw = Mth.approachDegrees(this.tailYaw, yBodyRot, 8);
        prevPuzzleHeadRot = headPuzzleRot;
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        prevFishPitch = fishPitch;
        prevSummonedProgress = summonedProgress;
        boolean water = this.isInWaterOrBubble();
        if (water && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!water && !this.isLandNavigator) {
            switchNavigator(true);
        }
        float pitchTarget;
        if (isDeepOneSwimming()) {
            pitchTarget = (float) this.getDeltaMovement().y * getPitchScale();
            if (!level().isClientSide && this.getNavigation().isDone() && this.onGround()) {
                this.setDeepOneSwimming(false);
            }
        } else {
            pitchTarget = 0;
        }
        if (isSummoned()) {
            if (this.getSummonTime() > 0) {
                if (summonedProgress < 20.0F) {
                    if (summonedProgress == 0) {
                        if (!level().isClientSide) {
                            this.level().broadcastEntityEvent(this, (byte) 61);
                        }
                        this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                    }
                    summonedProgress++;
                }
            } else {
                if (summonedProgress > 0.0F) {
                    summonedProgress--;
                }
            }
            if (getSummonTime() > 0) {
                if (!level().isClientSide) {
                    setSummonTime(getSummonTime() - 1);
                }
                if (getSummonTime() == 0) {
                    if (!level().isClientSide) {
                        this.level().broadcastEntityEvent(this, (byte) 61);
                    }
                    this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                }
            } else {
                if (!level().isClientSide && this.summonedProgress <= 0) {
                    this.remove(RemovalReason.DISCARDED);
                }
            }
        }
        if (!isSummoned() && summonedProgress > 0.0F) {
            summonedProgress--;
        }
        if (hasSwimmingBoundingBox()) {
            if (!hasSwimmingSize) {
                hasSwimmingSize = true;
                refreshDimensions();
            }
        } else {
            if (hasSwimmingSize) {
                hasSwimmingSize = false;
                refreshDimensions();
            }
        }
        if (tradingLockedTime > 0) {
            tradingLockedTime--;
        }
        if (!level().isClientSide && this.getAnimation() == getTradingAnimation() && this.getMainHandItem().is(ACTagRegistry.DEEP_ONE_BARTERS)) {
            BlockPos altarPos = getLastAltarPos();
            if (altarPos != null) {
                Vec3 center = Vec3.atCenterOf(altarPos);
                if (this.getAnimationTick() > getTradingAnimation().getDuration() - 10) {
                    if (level().getBlockEntity(altarPos) instanceof AbyssalAltarBlockEntity altar && !spawnedLootItem) {
                        List<ItemStack> possibles = generateBarterLoot();
                        ItemStack stack = possibles.isEmpty() ? ItemStack.EMPTY : possibles.get(0);
                        if (altar.getItem(0).isEmpty()) {
                            altar.setItem(0, stack);
                            this.level().broadcastEntityEvent(this, (byte) 68);
                            altar.onEntityInteract(this, false);
                        } else {
                            Vec3 vec3 = center.add(0, 0.5F, 0);
                            ItemEntity itemEntity = new ItemEntity(level(), vec3.x, vec3.y, vec3.z, stack);
                            level().addFreshEntity(itemEntity);
                        }
                        double advancementRange = 20.0D;
                        for (Player player : level().getNearbyPlayers(TargetingConditions.forNonCombat().range(advancementRange), this, this.getBoundingBox().inflate(advancementRange))) {
                            if (player.distanceTo(this) < advancementRange) {
                                ACAdvancementTriggerRegistry.DEEP_ONE_TRADE.triggerForEntity(player);
                            }
                        }
                        spawnedLootItem = true;
                    }
                    restoreSwappedItem();
                }
                this.lookAt(EntityAnchorArgument.Anchor.EYES, center);
            }
        }
        if (spawnedLootItem && this.getAnimation() != getTradingAnimation()) {
            spawnedLootItem = false;
        }
        fishPitch = Mth.approachDegrees(fishPitch, Mth.clamp((float) pitchTarget, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI), 5);
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        this.prevBipedProgress = bipedProgress;
        this.prevTackleProgress = tackleProgress;
        this.prevSpikeShakeProgress = spikeShakeProgress;
        this.prevTurnAngle = getTurnAngle();

        if (this.isBipedal()) {
            if (bipedProgress < 5.0F)
                bipedProgress++;
        } else {
            if (bipedProgress > 0F)
                bipedProgress--;
        }

        if (this.isTackling()) {
            if (tackleProgress < 5.0F)
                tackleProgress++;
        } else {
            if (tackleProgress > 0F)
                tackleProgress--;
        }

        if (this.isSpikeShaking()) {
            if (spikeShakeProgress < 5.0F)
                spikeShakeProgress++;

            if (currentSpeedMode != 2) {
                currentSpeedMode = 2;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.1F);
            }
        } else {
            if (spikeShakeProgress > 0F)
                spikeShakeProgress--;

            if (isBipedal()) {
                if (currentSpeedMode != 0) {
                    currentSpeedMode = 0;
                    this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
                }
            } else {
                if (currentSpeedMode != 1) {
                    currentSpeedMode = 1;
                    this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
                }
            }
        }

        if (this.hasSpikes()) {
            if (!hasSpikedArmor) {
                hasSpikedArmor = true;
                this.getAttribute(Attributes.ARMOR).setBaseValue(12F);
            }
        } else {
            if (hasSpikedArmor) {
                hasSpikedArmor = false;
                this.getAttribute(Attributes.ARMOR).setBaseValue(0F);
            }
        }

        if (!this.level().isClientSide) {
            if (this.tickCount % 200 == 0) {
                if (isInWaterRainOrBubble() && !this.hasSpikes()) {
                    this.setSpiked(true);
                }
                if (this.isHotBiome() && !isInWaterRainOrBubble()) {
                    this.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 400));
                    if (random.nextInt(2) == 0 && !this.isInWaterRainOrBubble()) {
                        this.setSpiked(false);
                    }
                }
            }
            float threshold = 1F;
            boolean flag = false;
            if (isBipedal() && this.yRotO - this.getYRot() > threshold) {
                this.setTurnAngle(this.getTurnAngle() + 5);
                flag = true;
            }
            if (isBipedal() && this.yRotO - this.getYRot() < -threshold) {
                this.setTurnAngle(this.getTurnAngle() - 5);
                flag = true;
            }
            if (!flag) {
                if (this.getTurnAngle() > 0) {
                    this.setTurnAngle(Math.max(this.getTurnAngle() - 10, 0));
                }
                if (this.getTurnAngle() < 0) {
                    this.setTurnAngle(Math.min(this.getTurnAngle() + 10, 0));
                }
            }
            this.setTurnAngle(Mth.clamp(this.getTurnAngle(), -60, 60));
            if (standingTime > 0) {
                standingTime--;
            }
            if (standingTime < 0) {
                standingTime++;
            }

            if (standingTime <= 0 && this.isBipedal()) {
                standingTime = -200 - random.nextInt(400);
                this.setBipedal(false);
            }
            if (standingTime == 0 && !this.isBipedal() && this.getDeltaMovement().lengthSqr() >= 0.03D) {
                standingTime = 200 + random.nextInt(600);
                this.setBipedal(true);
            }
            if (shakeTime > 0) {
                if (this.shakeTime % 5 == 0) {
                    int spikeCount = 2 + random.nextInt(4);
                    for (int i = 0; i < spikeCount; i++) {
                        float f = ((i + 1) / (float) spikeCount) * 360F;
                        EntityIceShard shard = new EntityIceShard(level(), this);
                        shard.shootFromRotation(this, this.getXRot() - random.nextInt(40), f, 0.0F, 0.15F + random.nextFloat() * 0.2F, 1.0F);
                        level().addFreshEntity(shard);
                    }
                }
                shakeTime--;
            }
            if (shakeTime == 0 && this.isSpikeShaking()) {
                this.setSpikeShaking(false);
                if (random.nextInt(2) == 0) {
                    this.setSpiked(false);
                }
            }
            if (this.getTarget() != null && isValidLeader(this.getTarget())) {
                this.setTarget(null);
            }
            //Makes entire pack attack target
            if (this.getTarget() != null && !isValidLeader(this.getTarget()) && this.getTarget().isAlive() && (this.getLastHurtByMob() == null || !this.getLastHurtByMob().isAlive())) {
                this.setLastHurtByMob(this.getTarget());
            }
            LivingEntity playerTarget = null;
            if (leader instanceof Player) {
                playerTarget = leader.getLastHurtMob();
                if (playerTarget == null || !playerTarget.isAlive() || playerTarget instanceof EntityFroststalker) {
                    playerTarget = leader.getLastHurtByMob();
                }
            }
            if (playerTarget != null && playerTarget.isAlive() && !(playerTarget instanceof EntityFroststalker)) {
                this.setTarget(playerTarget);
            }
            boolean attackAnim = this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5 ||
                    this.getAnimation() == ANIMATION_SHOVE && this.getAnimationTick() == 8 ||
                    this.getAnimation() == ANIMATION_SLASH_L && this.getAnimationTick() == 7 ||
                    this.getAnimation() == ANIMATION_SLASH_R && this.getAnimationTick() == 7;
            if (this.getTarget() != null && attackAnim) {
                getTarget().knockback(0.2F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            }
        }
        if (fleeFireFlag > 0) {
            fleeFireFlag--;
        }
        if(!this.level().isClientSide){
            if(resetLeaderCooldown > 0){
                resetLeaderCooldown--;
            }else{
                resetLeaderCooldown = 200 + this.getRandom().nextInt(200);
                this.lookForPlayerLeader();
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void aiStep() {
        super.aiStep();
        if (!level.isClientSide) {
            if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
                this.setTarget(null);
            }
        }
        boolean breathing = isBreathing() && this.getAnimation() != ANIMATION_BITE && this.getAnimation() != ANIMATION_ROAR;
        boolean jumping = !this.isInWater() && !this.isOnGround() && this.getDeltaMovement().y >= 0;
        boolean wantJumping = false; //(ticksSinceJump > TIME_BETWEEN_JUMPS) && this.isInWater();
        boolean ground = !isInWater() && this.onGround;
        boolean prevJumping = this.isJumpingOutOfWater();
        this.ticksSinceRoar++;
        this.jumpCooldown++;
        this.prevJumpRot = jumpRot;
        if (this.ticksSinceRoar > TIME_BETWEEN_ROARS && isAtSurface() && this.getAnimation() != ANIMATION_BITE && jumpProgress == 0 && !isJumpingOutOfWater()) {
            this.setAnimation(ANIMATION_ROAR);
            this.ticksSinceRoar = 0;
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 1) {
            this.playSound(IafSoundRegistry.SEA_SERPENT_ROAR, this.getSoundVolume() + 1, 1);
        }
        if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 5) {
            this.playSound(IafSoundRegistry.SEA_SERPENT_BITE, this.getSoundVolume(), 1);
        }
        if (isJumpingOutOfWater() && isWaterBlock(level, this.blockPosition().above(2))) {
            setJumpingOutOfWater(false);
        }
        if (this.swimCycle < 38) {
            this.swimCycle += 2;
        } else {
            this.swimCycle = 0;
        }
        if (breathing && breathProgress < 20.0F) {
            breathProgress += 0.5F;
        } else if (!breathing && breathProgress > 0.0F) {
            breathProgress -= 0.5F;
        }
        if (jumping && jumpProgress < 10.0F) {
            jumpProgress += 0.5F;
        } else if (!jumping && jumpProgress > 0.0F) {
            jumpProgress -= 0.5F;
        }
        if (wantJumping && wantJumpProgress < 10.0F) {
            wantJumpProgress += 2F;
        } else if (!wantJumping && wantJumpProgress > 0.0F) {
            wantJumpProgress -= 2F;
        }
        if (this.isJumpingOutOfWater() && jumpRot < 1.0F) {
            jumpRot += 0.1F;
        } else if (!this.isJumpingOutOfWater() && jumpRot > 0.0F) {
            jumpRot -= 0.1F;
        }
        if (prevJumping && !this.isJumpingOutOfWater()) {
            this.playSound(IafSoundRegistry.SEA_SERPENT_SPLASH, 5F, 0.75F);
            spawnSlamParticles(ParticleTypes.BUBBLE);
            this.doSplashDamage();
        }
        if (!ground && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (ground && !this.isLandNavigator) {
            switchNavigator(true);
        }
        setXRot(Mth.clamp((float) this.getDeltaMovement().y * 20F, -90, 90));
        if (changedSwimBehavior) {
            changedSwimBehavior = false;
        }
        if (!level.isClientSide) {
            if (attackDecision) {
                this.setBreathing(false);
            }
            if (this.getTarget() != null && this.getAnimation() != ANIMATION_ROAR) {
                if (!attackDecision) {
                    if (!this.getTarget().isInWater() || !this.hasLineOfSight(this.getTarget()) || this.distanceTo(this.getTarget()) < 30 * this.getSeaSerpentScale()) {
                        attackDecision = true;
                    }
                    if (!attackDecision) {
                        shoot(this.getTarget());
                    }
                } else {
                    if (this.distanceToSqr(this.getTarget()) > 200 * this.getSeaSerpentScale()) {
                        attackDecision = false;
                    }
                }
            } else {
                this.setBreathing(false);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE && this.getTarget() != null && (this.isTouchingMob(this.getTarget()) || this.distanceToSqr(this.getTarget()) < 50)) {
            this.hurtMob(this.getTarget());
        }
        breakBlock();
        if (!level.isClientSide && this.isPassenger() && this.getRootVehicle() instanceof Boat) {
            Boat boat = (Boat) this.getRootVehicle();
            boat.remove(RemovalReason.KILLED);
            this.stopRiding();
        }
    }

public void tick() {
        super.tick();
        this.prevRunProgress = runProgress;
        this.prevLeapProgress = leapProgress;
        this.prevRaiseLeftArmProgress = raiseLeftArmProgress;
        this.prevRaiseRightArmProgress = raiseRightArmProgress;
        this.prevDarknessProgress = darknessProgress;
        this.prevLeapPitch = leapPitch;
        this.prevScreenShakeAmount = screenShakeAmount;
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        if (this.isRunning() && runProgress < 5.0F) {
            runProgress++;
        }
        if (!this.isRunning() && runProgress > 0.0F) {
            runProgress--;
        }
        if (isLeaping() && leapProgress < 5F) {
            leapProgress++;
        }
        if (!isLeaping() && leapProgress > 0F) {
            leapProgress--;
        }
        if (getDarknessTime() > 0 && darknessProgress < 5F) {
            darknessProgress++;
        }
        if (getDarknessTime() <= 0 && darknessProgress > 0F) {
            darknessProgress--;
        }
        if (this.isLeaping()) {
            if (this.onGround() && leapProgress >= 5.0F) {
                this.setLeaping(false);
            }
            timeLeaping++;
            Vec3 vec3 = this.getDeltaMovement();
            float f2 = (float) (-(Mth.atan2(vec3.y, vec3.horizontalDistance()) * (double) (180F / (float) Math.PI)));
            this.leapPitch = Mth.approachDegrees(leapPitch, f2, 5);
        } else {
            timeLeaping = 0;
            this.leapPitch = Mth.approachDegrees(leapPitch, 0, 5);
            if (this.getAnimation() == ANIMATION_PREPARE_JUMP && this.onGround() && !level().isClientSide && this.getAnimationTick() >= 8 && this.getAnimationTick() <= 10) {
                this.setLeaping(true);
                this.playSound(ACSoundRegistry.FORSAKEN_LEAP.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.45D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25D);
        }
        boolean raisingLeftArm = this.isRaisingArm(true);
        boolean raisingRightArm = this.isRaisingArm(false);
        if (raisingLeftArm && raiseLeftArmProgress < 10.0F) {
            raiseLeftArmProgress++;
        }
        if (!raisingLeftArm && raiseLeftArmProgress > 0.0F) {
            raiseLeftArmProgress--;
        }
        if (raisingRightArm && raiseRightArmProgress < 10.0F) {
            raiseRightArmProgress++;
        }
        if (!raisingRightArm && raiseRightArmProgress > 0.0F) {
            raiseRightArmProgress--;
        }
        if (screenShakeAmount > 0) {
            screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
        }
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        if (level().isClientSide) {
            if (random.nextInt(6) == 0) {
                level().addParticle(ACParticleRegistry.FORSAKEN_SPIT.get(), this.getX(), this.getY() + 0.5F, this.getZ(), this.getId(), 0, 0);
            }
            if (darknessProgress > 0) {
                for (int i = 0; i < 1; i++) {
                    if (random.nextBoolean()) {
                        level().addParticle(ACParticleRegistry.UNDERZEALOT_MAGIC.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), this.getX(), this.getEyeY(), this.getZ());
                    } else {
                        level().addParticle(ParticleTypes.SMOKE, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, 0, 0);
                    }
                }
            }
            if (this.getAnimation() == ANIMATION_SONIC_ATTACK) {
                if (this.getAnimationTick() > 10 && this.getAnimationTick() < 30) {
                    if (this.getAnimationTick() % 4 == 0) {
                        level().addAlwaysVisibleParticle(ACParticleRegistry.FORSAKEN_SONAR.get(), true, this.getX(), this.getY() + 0.5F, this.getZ(), this.getId(), this.getXRot(), this.getYHeadRot());
                    }
                    this.screenShakeAmount = 1F;
                }
            }
            if (this.getAnimation() == ANIMATION_SONIC_BLAST) {
                if (this.getAnimationTick() > 10 && this.getAnimationTick() < 30) {
                    if (this.getAnimationTick() % 4 == 0) {
                        level().addAlwaysVisibleParticle(ACParticleRegistry.FORSAKEN_SONAR_LARGE.get(), true, this.getX(), this.getY() + 0.5F, this.getZ(), this.getId(), 90, 0);
                    }
                    this.screenShakeAmount = 1F;
                }
            }
            if (this.getAnimation() == ANIMATION_GROUND_SMASH) {
                if (this.getAnimationTick() >= 10 && this.getAnimationTick() <= 15) {
                    this.screenShakeAmount = 1F;
                }
                if (this.getAnimationTick() == 12) {
                    Vec3 smashPos = this.position().add(new Vec3(0, 0, 3.5F).yRot((float) -Math.toRadians(this.yBodyRot)));
                    float radius = 1.4F;
                    float particleCount = 20 + random.nextInt(12);
                    for (int i1 = 0; i1 < particleCount; i1++) {
                        double motionX = (getRandom().nextFloat() - 0.5F) * 0.7D;
                        double motionY = getRandom().nextFloat() * 0.7D + 1.8F;
                        double motionZ = (getRandom().nextFloat() - 0.5F) * 0.7D;
                        float angle = (0.01745329251F * (this.yBodyRot + (i1 / particleCount) * 360F));
                        double extraX = radius * Mth.sin((float) (Math.PI + angle));
                        double extraY = 1.2F;
                        double extraZ = radius * Mth.cos(angle);
                        BlockPos ground = BlockPos.containing(ACMath.getGroundBelowPosition(level(), new Vec3(Mth.floor(smashPos.x + extraX), Mth.floor(smashPos.y + extraY) + 2, Mth.floor(smashPos.z + extraZ))));
                        BlockState groundState = this.level().getBlockState(ground);
                        if (groundState.isSolid()) {
                            if (level().isClientSide) {
                                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, groundState), true, smashPos.x + extraX, ground.getY() + extraY, smashPos.z + extraZ, motionX, motionY, motionZ);
                            }
                        }
                    }
                }
            }
        } else {
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive() && target.distanceTo(this) < 10 && this.hasLineOfSight(target) && (this.getAnimation() == ANIMATION_RIGHT_PICKUP || this.getAnimation() == ANIMATION_LEFT_PICKUP)) {
                if(getHeldMobId() == -1){
                    this.playSound(ACSoundRegistry.FORSAKEN_GRAB.get(), this.getSoundVolume(), this.getVoicePitch());
                }
                this.setHeldMobId(target.getId());
            } else if (getHeldMobId() != -1) {
                this.setHeldMobId(-1);
            }
            if (this.getHealth() < this.getMaxHealth() * 0.5F && !level().isClientSide) {
                int lightLevel = getLightLevel();
                if (lightLevel <= LIGHT_THRESHOLD) {
                    this.setDarknessTime(30);
                } else if (getDarknessTime() > 0) {
                    this.setDarknessTime(this.getDarknessTime() - 1);
                }
                if (getDarknessTime() > 0 && this.tickCount % 30 == 0) {
                    this.heal(1);
                }
            } else {
                this.setDarknessTime(0);
            }
        }
        Entity grabbedEntity = this.getHeldMob();
        if (grabbedEntity != null && grabbedEntity.isAlive() && grabbedEntity.distanceTo(this) < 10) {
            grabbedEntity.fallDistance = 0;
            if ((this.getAnimation() == ANIMATION_RIGHT_PICKUP || this.getAnimation() == ANIMATION_LEFT_PICKUP) && this.getAnimationTick() >= 10 && this.getAnimationTick() <= 38) {
                Vec3 grabPos = getPickupPos();
                Vec3 minus = new Vec3(grabPos.x - grabbedEntity.getX(), grabPos.y - grabbedEntity.getY(), grabPos.z - grabbedEntity.getZ()).scale(0.33F);
                grabbedEntity.setDeltaMovement(minus);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        this.prevDanceProgress = danceProgress;
        this.prevSitProgress = sitProgress;
        this.prevCarryItemProgress = carryItemProgress;
        if (this.jukeboxPosition == null || !this.jukeboxPosition.closerToCenterThan(this.position(), 15) || !this.level().getBlockState(this.jukeboxPosition).is(Blocks.JUKEBOX)) {
            this.setDancing(false);
            this.jukeboxPosition = null;
        }
        if (isDancing() && danceProgress < 5F) {
            danceProgress++;
        }
        if (!isDancing() && danceProgress > 0F) {
            danceProgress--;
        }
        if (isSitting() && sitProgress < 10F) {
            sitProgress++;
        }
        if (!isSitting() && sitProgress > 0F) {
            sitProgress--;
        }
        if (isCarryingItem() && carryItemProgress < 10F) {
            carryItemProgress++;
        }
        if (!isCarryingItem() && carryItemProgress > 0F) {
            carryItemProgress--;
        }
        if (!level().isClientSide) {
            if (isStillEnough() && !isCarryingItem() && random.nextInt(150) == 0 && this.getAnimation() == NO_ANIMATION && !this.isDancing()) {
                if (random.nextInt(3) == 0 && sitFor == 0) {
                    sitFor = 100 + random.nextInt(80);
                } else {
                    Animation idle;
                    float rand = random.nextFloat();
                    if (!this.isSitting()) {
                        if (rand < 0.25F) {
                            idle = ANIMATION_IDLE_JUMP;
                        } else if (rand < 0.5F) {
                            idle = ANIMATION_IDLE_FALL_OVER;
                        } else {
                            idle = rand < 0.75F ? ANIMATION_IDLE_WAVE_LEFT : ANIMATION_IDLE_WAVE_RIGHT;
                        }
                    } else {
                        idle = rand < 0.5F ? ANIMATION_IDLE_WAVE_LEFT : ANIMATION_IDLE_WAVE_RIGHT;
                    }
                    this.setAnimation(idle);
                }
            }
            if(this.isCarryingItem() && this.getItemInHand(InteractionHand.OFF_HAND).isEmpty()){
                this.setCarryingItem(false);
            }
        }else{
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
        }
        if (this.getAnimation() == ANIMATION_IDLE_JUMP && this.onGround() && this.getAnimationTick() == 5) {
            this.jumpFromGround();
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (sitFor > 0) {
            this.setSitting(true);
            sitFor--;
        } else {
            this.setSitting(false);
            if (sitFor < 0) {
                sitFor++;
            }
        }
        if(fleeFor > 0){
            fleeFor--;
            if(fleeFor == 0){
                this.setFleeingFromUUID(null);
            }
        }
        if(this.isOvenSpawned()){
            if(despawnFromOvenCooldown-- < 0){
                this.kill();
                this.spawnAtLocation(this.getItemInHand(InteractionHand.MAIN_HAND));
                this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                this.spawnAtLocation(this.getItemInHand(InteractionHand.OFF_HAND));
                this.setItemInHand(InteractionHand.OFF_HAND, ItemStack.EMPTY);
            }
        }
        lastStepX = this.xo;
        lastStepZ = this.zo;
    }
